     !> DBDSDC: computes the singular value decomposition (SVD) of a real
     !> N-by-N (upper or lower) bidiagonal matrix B:  B = U * S * VT,
     !> using a divide and conquer method, where S is a diagonal matrix
     !> with non-negative diagonal elements (the singular values of B), and
     !> U and VT are orthogonal matrices of left and right singular vectors,
     !> respectively. DBDSDC can be used to compute all singular values,
     !> and optionally, singular vectors or singular vectors in compact form.
     !> This code makes very mild assumptions about floating point
     !> arithmetic. It will work on machines with a guard digit in
     !> add/subtract, or on those binary machines without guard digits
     !> which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or Cray-2.
     !> It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.  See DLASD3 for details.
     !> The code currently calls DLASDQ if singular values only are desired.
     !> However, it can be slightly modified to compute singular values
     !> using the divide and conquer method.

     pure subroutine la_qbdsdc(uplo,compq,n,d,e,u,ldu,vt,ldvt,q,iq,work,iwork, &
               info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: compq,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldu,ldvt,n
           ! Array Arguments
           integer(ilp),intent(out) :: iq(*),iwork(*)
           real(qp),intent(inout) :: d(*),e(*)
           real(qp),intent(out) :: q(*),u(ldu,*),vt(ldvt,*),work(*)
        ! =====================================================================
        ! changed dimension statement in comment describing e from (n) to
        ! (n-1).  sven, 17 feb 05.
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: difl,difr,givcol,givnum,givptr,i,ic,icompq,ierr,ii,is,iu, &
           iuplo,ivt,j,k,kk,mlvl,nm1,nsize,perm,poles,qstart,smlsiz,smlszp,sqre, &
                     start,wstart,z
           real(qp) :: cs,eps,orgnrm,p,r,sn
           ! Intrinsic Functions
           intrinsic :: abs,real,int,log,sign
           ! Executable Statements
           ! test the input parameters.
           info = 0
           iuplo = 0
           if (la_lsame(uplo,'U')) iuplo = 1
           if (la_lsame(uplo,'L')) iuplo = 2
           if (la_lsame(compq,'N')) then
              icompq = 0
           else if (la_lsame(compq,'P')) then
              icompq = 1
           else if (la_lsame(compq,'I')) then
              icompq = 2
           else
              icompq = -1
           end if
           if (iuplo == 0) then
              info = -1
           else if (icompq < 0) then
              info = -2
           else if (n < 0) then
              info = -3
           else if ((ldu < 1) .or. ((icompq == 2) .and. (ldu < n))) then
              info = -7
           else if ((ldvt < 1) .or. ((icompq == 2) .and. (ldvt < n))) then
              info = -9
           end if
           if (info /= 0) then
              call la_xerbla('DBDSDC',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           smlsiz = la_ilaenv(9,'DBDSDC',' ',0,0,0,0)
           if (n == 1) then
              if (icompq == 1) then
                 q(1) = sign(one,d(1))
                 q(1 + smlsiz*n) = one
              else if (icompq == 2) then
                 u(1,1) = sign(one,d(1))
                 vt(1,1) = one
              end if
              d(1) = abs(d(1))
              return
           end if
           nm1 = n - 1
           ! if matrix lower bidiagonal, rotate to be upper bidiagonal
           ! by applying givens rotations on the left
           wstart = 1
           qstart = 3
           if (icompq == 1) then
              call la_qcopy(n,d,1,q(1),1)
              call la_qcopy(n - 1,e,1,q(n + 1),1)
           end if
           if (iuplo == 2) then
              qstart = 5
              if (icompq == 2) wstart = 2*n - 1
              do i = 1,n - 1
                 call la_qlartg(d(i),e(i),cs,sn,r)
                 d(i) = r
                 e(i) = sn*d(i + 1)
                 d(i + 1) = cs*d(i + 1)
                 if (icompq == 1) then
                    q(i + 2*n) = cs
                    q(i + 3*n) = sn
                 else if (icompq == 2) then
                    work(i) = cs
                    work(nm1 + i) = -sn
                 end if
              end do
           end if
           ! if icompq = 0, use la_qlasdq to compute the singular values.
           if (icompq == 0) then
              ! ignore wstart, instead using work( 1 ), since the two vectors
              ! for cs and -sn above are added only if icompq == 2,
              ! and adding them exceeds documented work size of 4*n.
              call la_qlasdq('U',0,n,0,0,0,d,e,vt,ldvt,u,ldu,u,ldu,work(1), &
                        info)
              go to 40
           end if
           ! if n is smaller than the minimum divide size smlsiz, then solve
           ! the problem with another solver.
           if (n <= smlsiz) then
              if (icompq == 2) then
                 call la_qlaset('A',n,n,zero,one,u,ldu)
                 call la_qlaset('A',n,n,zero,one,vt,ldvt)
                 call la_qlasdq('U',0,n,n,n,0,d,e,vt,ldvt,u,ldu,u,ldu,work( &
                           wstart),info)
              else if (icompq == 1) then
                 iu = 1
                 ivt = iu + n
                 call la_qlaset('A',n,n,zero,one,q(iu + (qstart - 1)*n),n)
                 call la_qlaset('A',n,n,zero,one,q(ivt + (qstart - 1)*n),n)
                 call la_qlasdq('U',0,n,n,n,0,d,e,q(ivt + (qstart - 1)*n),n,q(iu + ( &
                           qstart - 1)*n),n,q(iu + (qstart - 1)*n),n,work(wstart),info)
              end if
              go to 40
           end if
           if (icompq == 2) then
              call la_qlaset('A',n,n,zero,one,u,ldu)
              call la_qlaset('A',n,n,zero,one,vt,ldvt)
           end if
           ! scale.
           orgnrm = la_qlanst('M',n,d,e)
           if (orgnrm == zero) return
           call la_qlascl('G',0,0,orgnrm,one,n,1,d,n,ierr)
           call la_qlascl('G',0,0,orgnrm,one,nm1,1,e,nm1,ierr)
           eps = (0.9e+0_qp)*la_qlamch('EPSILON')
           mlvl = int(log(real(n,KIND=qp)/real(smlsiz + 1,KIND=qp))/log(two),KIND=ilp) + &
                     1
           smlszp = smlsiz + 1
           if (icompq == 1) then
              iu = 1
              ivt = 1 + smlsiz
              difl = ivt + smlszp
              difr = difl + mlvl
              z = difr + mlvl*2
              ic = z + mlvl
              is = ic + 1
              poles = is + 1
              givnum = poles + 2*mlvl
              k = 1
              givptr = 2
              perm = 3
              givcol = perm + mlvl
           end if
           do i = 1,n
              if (abs(d(i)) < eps) then
                 d(i) = sign(eps,d(i))
              end if
           end do
           start = 1
           sqre = 0
           loop_30: do i = 1,nm1
              if ((abs(e(i)) < eps) .or. (i == nm1)) then
                 ! subproblem found. first determine its size and then
                 ! apply divide and conquer on it.
                 if (i < nm1) then
                    ! a subproblem with e(i) small for i < nm1.
                    nsize = i - start + 1
                 else if (abs(e(i)) >= eps) then
                    ! a subproblem with e(nm1) not too small but i = nm1.
                    nsize = n - start + 1
                 else
                    ! a subproblem with e(nm1) small. this implies an
                    ! 1-by-1 subproblem at d(n). solve this 1-by-1 problem
                    ! first.
                    nsize = i - start + 1
                    if (icompq == 2) then
                       u(n,n) = sign(one,d(n))
                       vt(n,n) = one
                    else if (icompq == 1) then
                       q(n + (qstart - 1)*n) = sign(one,d(n))
                       q(n + (smlsiz + qstart - 1)*n) = one
                    end if
                    d(n) = abs(d(n))
                 end if
                 if (icompq == 2) then
                    call la_qlasd0(nsize,sqre,d(start),e(start),u(start,start), &
                              ldu,vt(start,start),ldvt,smlsiz,iwork,work(wstart),info)
                 else
                    call la_qlasda(icompq,smlsiz,nsize,sqre,d(start),e(start),q( &
                    start + (iu + qstart - 2)*n),n,q(start + (ivt + qstart - 2)*n),iq(start + k*n),q( &
                     start + (difl + qstart - 2)*n),q(start + (difr + qstart - 2)*n),q(start + (z + &
                     qstart - 2)*n),q(start + (poles + qstart - 2)*n),iq(start + givptr*n),iq( &
                     start + givcol*n),n,iq(start + perm*n),q(start + (givnum + qstart - 2)*n),q( &
                     start + (ic + qstart - 2)*n),q(start + (is + qstart - 2)*n),work(wstart),iwork, &
                                info)
                 end if
                 if (info /= 0) then
                    return
                 end if
                 start = i + 1
              end if
           end do loop_30
           ! unscale
           call la_qlascl('G',0,0,one,orgnrm,n,1,d,n,ierr)
           40 continue
           ! use selection sort to minimize swaps of singular vectors
           do ii = 2,n
              i = ii - 1
              kk = i
              p = d(i)
              do j = ii,n
                 if (d(j) > p) then
                    kk = j
                    p = d(j)
                 end if
              end do
              if (kk /= i) then
                 d(kk) = d(i)
                 d(i) = p
                 if (icompq == 1) then
                    iq(i) = kk
                 else if (icompq == 2) then
                    call la_qswap(n,u(1,i),1,u(1,kk),1)
                    call la_qswap(n,vt(i,1),ldvt,vt(kk,1),ldvt)
                 end if
              else if (icompq == 1) then
                 iq(i) = i
              end if
           end do
           ! if icompq = 1, use iq(n,1) as the indicator for uplo
           if (icompq == 1) then
              if (iuplo == 1) then
                 iq(n) = 1
              else
                 iq(n) = 0
              end if
           end if
           ! if b is lower bidiagonal, update u by those givens rotations
           ! which rotated b to be upper bidiagonal
           if ((iuplo == 2) .and. (icompq == 2)) call la_qlasr('L','V','B',n,n,work(1) &
                     ,work(n),u,ldu)
           return
     end subroutine la_qbdsdc

     !> DDISNA: computes the reciprocal condition numbers for the eigenvectors
     !> of a real symmetric or complex Hermitian matrix or for the left or
     !> right singular vectors of a general m-by-n matrix. The reciprocal
     !> condition number is the 'gap' between the corresponding eigenvalue or
     !> singular value and the nearest other one.
     !> The bound on the error, measured by angle in radians, in the I-th
     !> computed vector is given by
     !> DLAMCH( 'E' ) * ( ANORM / SEP( I ) )
     !> where ANORM = 2-norm(A) = max( abs( D(j) ) ).  SEP(I) is not allowed
     !> to be smaller than DLAMCH( 'E' )*ANORM in order to limit the size of
     !> the error bound.
     !> DDISNA may also be used to compute error bounds for eigenvectors of
     !> the generalized symmetric definite eigenproblem.

     pure subroutine la_qdisna(job,m,n,d,sep,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: job
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: m,n
           ! Array Arguments
           real(qp),intent(in) :: d(*)
           real(qp),intent(out) :: sep(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: decr,eigen,incr,left,right,sing
           integer(ilp) :: i,k
           real(qp) :: anorm,eps,newgap,oldgap,safmin,thresh
           ! Intrinsic Functions
           intrinsic :: abs,max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           eigen = la_lsame(job,'E')
           left = la_lsame(job,'L')
           right = la_lsame(job,'R')
           sing = left .or. right
           if (eigen) then
              k = m
           else if (sing) then
              k = min(m,n)
           end if
           if (.not. eigen .and. .not. sing) then
              info = -1
           else if (m < 0) then
              info = -2
           else if (k < 0) then
              info = -3
           else
              incr = .true.
              decr = .true.
              do i = 1,k - 1
                 if (incr) incr = incr .and. d(i) <= d(i + 1)
                 if (decr) decr = decr .and. d(i) >= d(i + 1)
              end do
              if (sing .and. k > 0) then
                 if (incr) incr = incr .and. zero <= d(1)
                 if (decr) decr = decr .and. d(k) >= zero
              end if
              if (.not. (incr .or. decr)) info = -4
           end if
           if (info /= 0) then
              call la_xerbla('DDISNA',-info)
              return
           end if
           ! quick return if possible
           if (k == 0) return
           ! compute reciprocal condition numbers
           if (k == 1) then
              sep(1) = la_qlamch('O')
           else
              oldgap = abs(d(2) - d(1))
              sep(1) = oldgap
              do i = 2,k - 1
                 newgap = abs(d(i + 1) - d(i))
                 sep(i) = min(oldgap,newgap)
                 oldgap = newgap
              end do
              sep(k) = oldgap
           end if
           if (sing) then
              if ((left .and. m > n) .or. (right .and. m < n)) then
                 if (incr) sep(1) = min(sep(1),d(1))
                 if (decr) sep(k) = min(sep(k),d(k))
              end if
           end if
           ! ensure that reciprocal condition numbers are not less than
           ! threshold, in order to limit the size of the error bound
           eps = la_qlamch('E')
           safmin = la_qlamch('S')
           anorm = max(abs(d(1)),abs(d(k)))
           if (anorm == zero) then
              thresh = eps
           else
              thresh = max(eps*anorm,safmin)
           end if
           do i = 1,k
              sep(i) = max(sep(i),thresh)
           end do
           return
     end subroutine la_qdisna

     !> DGBBRD: reduces a real general m-by-n band matrix A to upper
     !> bidiagonal form B by an orthogonal transformation: Q**T * A * P = B.
     !> The routine computes B, and optionally forms Q or P**T, or computes
     !> Q**T*C for a given matrix C.

     pure subroutine la_qgbbrd(vect,m,n,ncc,kl,ku,ab,ldab,d,e,q,ldq,pt,ldpt,c, &
               ldc,work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: vect
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kl,ku,ldab,ldc,ldpt,ldq,m,n,ncc
           ! Array Arguments
           real(qp),intent(inout) :: ab(ldab,*),c(ldc,*)
           real(qp),intent(out) :: d(*),e(*),pt(ldpt,*),q(ldq,*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: wantb,wantc,wantpt,wantq
           integer(ilp) :: i,inca,j,j1,j2,kb,kb1,kk,klm,klu1,kun,l,minmn,ml,ml0,mn, &
                      mu,mu0,nr,nrt
           real(qp) :: ra,rb,rc,rs
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters
           wantb = la_lsame(vect,'B')
           wantq = la_lsame(vect,'Q') .or. wantb
           wantpt = la_lsame(vect,'P') .or. wantb
           wantc = ncc > 0
           klu1 = kl + ku + 1
           info = 0
           if (.not. wantq .and. .not. wantpt .and. .not. la_lsame(vect,'N')) then
              info = -1
           else if (m < 0) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ncc < 0) then
              info = -4
           else if (kl < 0) then
              info = -5
           else if (ku < 0) then
              info = -6
           else if (ldab < klu1) then
              info = -8
           else if (ldq < 1 .or. wantq .and. ldq < max(1,m)) then
              info = -12
           else if (ldpt < 1 .or. wantpt .and. ldpt < max(1,n)) then
              info = -14
           else if (ldc < 1 .or. wantc .and. ldc < max(1,m)) then
              info = -16
           end if
           if (info /= 0) then
              call la_xerbla('DGBBRD',-info)
              return
           end if
           ! initialize q and p**t to the unit matrix, if needed
           if (wantq) call la_qlaset('FULL',m,m,zero,one,q,ldq)
           if (wantpt) call la_qlaset('FULL',n,n,zero,one,pt,ldpt)
           ! quick return if possible.
           if (m == 0 .or. n == 0) return
           minmn = min(m,n)
           if (kl + ku > 1) then
              ! reduce to upper bidiagonal form if ku > 0; if ku = 0, reduce
              ! first to lower bidiagonal form and then transform to upper
              ! bidiagonal
              if (ku > 0) then
                 ml0 = 1
                 mu0 = 2
              else
                 ml0 = 2
                 mu0 = 1
              end if
              ! wherever possible, plane rotations are generated and applied in
              ! vector operations of length nr over the index set j1:j2:klu1.
              ! the sines of the plane rotations are stored in work(1:max(m,n))
              ! and the cosines in work(max(m,n)+1:2*max(m,n)).
              mn = max(m,n)
              klm = min(m - 1,kl)
              kun = min(n - 1,ku)
              kb = klm + kun
              kb1 = kb + 1
              inca = kb1*ldab
              nr = 0
              j1 = klm + 2
              j2 = 1 - kun
              loop_90: do i = 1,minmn
                 ! reduce i-th column and i-th row of matrix to bidiagonal form
                 ml = klm + 1
                 mu = kun + 1
                 loop_80: do kk = 1,kb
                    j1 = j1 + kb
                    j2 = j2 + kb
                    ! generate plane rotations to annihilate nonzero elements
                    ! which have been created below the band
                    if (nr > 0) call la_qlargv(nr,ab(klu1,j1 - klm - 1),inca,work(j1),kb1, &
                              work(mn + j1),kb1)
                    ! apply plane rotations from the left
                    do l = 1,kb
                       if (j2 - klm + l - 1 > n) then
                          nrt = nr - 1
                       else
                          nrt = nr
                       end if
                       if (nrt > 0) call la_qlartv(nrt,ab(klu1 - l,j1 - klm + l - 1),inca,ab( &
                                 klu1 - l + 1,j1 - klm + l - 1),inca,work(mn + j1),work(j1),kb1)
                    end do
                    if (ml > ml0) then
                       if (ml <= m - i + 1) then
                          ! generate plane rotation to annihilate a(i+ml-1,i)
                          ! within the band, and apply rotation from the left
                          call la_qlartg(ab(ku + ml - 1,i),ab(ku + ml,i),work(mn + i + ml - 1), &
                                    work(i + ml - 1),ra)
                          ab(ku + ml - 1,i) = ra
                          if (i < n) call la_qrot(min(ku + ml - 2,n - i),ab(ku + ml - 2,i + 1),ldab - &
                                    1,ab(ku + ml - 1,i + 1),ldab - 1,work(mn + i + ml - 1),work(i + ml - 1))
                       end if
                       nr = nr + 1
                       j1 = j1 - kb1
                    end if
                    if (wantq) then
                       ! accumulate product of plane rotations in q
                       do j = j1,j2,kb1
                          call la_qrot(m,q(1,j - 1),1,q(1,j),1,work(mn + j),work(j &
                                    ))
                       end do
                    end if
                    if (wantc) then
                       ! apply plane rotations to c
                       do j = j1,j2,kb1
                          call la_qrot(ncc,c(j - 1,1),ldc,c(j,1),ldc,work(mn + j), &
                                    work(j))
                       end do
                    end if
                    if (j2 + kun > n) then
                       ! adjust j2 to keep within the bounds of the matrix
                       nr = nr - 1
                       j2 = j2 - kb1
                    end if
                    do j = j1,j2,kb1
                       ! create nonzero element a(j-1,j+ku) above the band
                       ! and store it in work(n+1:2*n)
                       work(j + kun) = work(j)*ab(1,j + kun)
                       ab(1,j + kun) = work(mn + j)*ab(1,j + kun)
                    end do
                    ! generate plane rotations to annihilate nonzero elements
                    ! which have been generated above the band
                    if (nr > 0) call la_qlargv(nr,ab(1,j1 + kun - 1),inca,work(j1 + kun),kb1, &
                               work(mn + j1 + kun),kb1)
                    ! apply plane rotations from the right
                    do l = 1,kb
                       if (j2 + l - 1 > m) then
                          nrt = nr - 1
                       else
                          nrt = nr
                       end if
                       if (nrt > 0) call la_qlartv(nrt,ab(l + 1,j1 + kun - 1),inca,ab(l,j1 + &
                                 kun),inca,work(mn + j1 + kun),work(j1 + kun),kb1)
                    end do
                    if (ml == ml0 .and. mu > mu0) then
                       if (mu <= n - i + 1) then
                          ! generate plane rotation to annihilate a(i,i+mu-1)
                          ! within the band, and apply rotation from the right
                          call la_qlartg(ab(ku - mu + 3,i + mu - 2),ab(ku - mu + 2,i + mu - 1),work( &
                                    mn + i + mu - 1),work(i + mu - 1),ra)
                          ab(ku - mu + 3,i + mu - 2) = ra
                          call la_qrot(min(kl + mu - 2,m - i),ab(ku - mu + 4,i + mu - 2),1,ab(ku - &
                                    mu + 3,i + mu - 1),1,work(mn + i + mu - 1),work(i + mu - 1))
                       end if
                       nr = nr + 1
                       j1 = j1 - kb1
                    end if
                    if (wantpt) then
                       ! accumulate product of plane rotations in p**t
                       do j = j1,j2,kb1
                          call la_qrot(n,pt(j + kun - 1,1),ldpt,pt(j + kun,1),ldpt,work( &
                                    mn + j + kun),work(j + kun))
                       end do
                    end if
                    if (j2 + kb > m) then
                       ! adjust j2 to keep within the bounds of the matrix
                       nr = nr - 1
                       j2 = j2 - kb1
                    end if
                    do j = j1,j2,kb1
                       ! create nonzero element a(j+kl+ku,j+ku-1) below the
                       ! band and store it in work(1:n)
                       work(j + kb) = work(j + kun)*ab(klu1,j + kun)
                       ab(klu1,j + kun) = work(mn + j + kun)*ab(klu1,j + kun)
                    end do
                    if (ml > ml0) then
                       ml = ml - 1
                    else
                       mu = mu - 1
                    end if
                 end do loop_80
              end do loop_90
           end if
           if (ku == 0 .and. kl > 0) then
              ! a has been reduced to lower bidiagonal form
              ! transform lower bidiagonal form to upper bidiagonal by applying
              ! plane rotations from the left, storing diagonal elements in d
              ! and off-diagonal elements in e
              do i = 1,min(m - 1,n)
                 call la_qlartg(ab(1,i),ab(2,i),rc,rs,ra)
                 d(i) = ra
                 if (i < n) then
                    e(i) = rs*ab(1,i + 1)
                    ab(1,i + 1) = rc*ab(1,i + 1)
                 end if
                 if (wantq) call la_qrot(m,q(1,i),1,q(1,i + 1),1,rc,rs)
                 if (wantc) call la_qrot(ncc,c(i,1),ldc,c(i + 1,1),ldc,rc,rs)

              end do
              if (m <= n) d(m) = ab(1,m)
           else if (ku > 0) then
              ! a has been reduced to upper bidiagonal form
              if (m < n) then
                 ! annihilate a(m,m+1) by applying plane rotations from the
                 ! right, storing diagonal elements in d and off-diagonal
                 ! elements in e
                 rb = ab(ku,m + 1)
                 do i = m,1,-1
                    call la_qlartg(ab(ku + 1,i),rb,rc,rs,ra)
                    d(i) = ra
                    if (i > 1) then
                       rb = -rs*ab(ku,i)
                       e(i - 1) = rc*ab(ku,i)
                    end if
                    if (wantpt) call la_qrot(n,pt(i,1),ldpt,pt(m + 1,1),ldpt,rc,rs)

                 end do
              else
                 ! copy off-diagonal elements to e and diagonal elements to d
                 do i = 1,minmn - 1
                    e(i) = ab(ku,i + 1)
                 end do
                 do i = 1,minmn
                    d(i) = ab(ku + 1,i)
                 end do
              end if
           else
              ! a is diagonal. set elements of e to zero and copy diagonal
              ! elements to d.
              do i = 1,minmn - 1
                 e(i) = zero
              end do
              do i = 1,minmn
                 d(i) = ab(1,i)
              end do
           end if
           return
     end subroutine la_qgbbrd

     !> DGEBD2: reduces a real general m by n matrix A to upper or lower
     !> bidiagonal form B by an orthogonal transformation: Q**T * A * P = B.
     !> If m >= n, B is upper bidiagonal; if m < n, B is lower bidiagonal.

     pure subroutine la_qgebd2(m,n,a,lda,d,e,tauq,taup,work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,m,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: d(*),e(*),taup(*),tauq(*),work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters
           info = 0
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           end if
           if (info < 0) then
              call la_xerbla('DGEBD2',-info)
              return
           end if
           if (m >= n) then
              ! reduce to upper bidiagonal form
              do i = 1,n
                 ! generate elementary reflector h(i) to annihilate a(i+1:m,i)
                 call la_qlarfg(m - i + 1,a(i,i),a(min(i + 1,m),i),1,tauq(i))

                 d(i) = a(i,i)
                 a(i,i) = one
                 ! apply h(i) to a(i:m,i+1:n) from the left
                 if (i < n) call la_qlarf('LEFT',m - i + 1,n - i,a(i,i),1,tauq(i),a(i,i + &
                           1),lda,work)
                 a(i,i) = d(i)
                 if (i < n) then
                    ! generate elementary reflector g(i) to annihilate
                    ! a(i,i+2:n)
                    call la_qlarfg(n - i,a(i,i + 1),a(i,min(i + 2,n)),lda,taup(i))

                    e(i) = a(i,i + 1)
                    a(i,i + 1) = one
                    ! apply g(i) to a(i+1:m,i+1:n) from the right
                    call la_qlarf('RIGHT',m - i,n - i,a(i,i + 1),lda,taup(i),a(i + 1,i + 1 &
                              ),lda,work)
                    a(i,i + 1) = e(i)
                 else
                    taup(i) = zero
                 end if
              end do
           else
              ! reduce to lower bidiagonal form
              do i = 1,m
                 ! generate elementary reflector g(i) to annihilate a(i,i+1:n)
                 call la_qlarfg(n - i + 1,a(i,i),a(i,min(i + 1,n)),lda,taup(i))

                 d(i) = a(i,i)
                 a(i,i) = one
                 ! apply g(i) to a(i+1:m,i:n) from the right
                 if (i < m) call la_qlarf('RIGHT',m - i,n - i + 1,a(i,i),lda,taup(i),a(i + &
                           1,i),lda,work)
                 a(i,i) = d(i)
                 if (i < m) then
                    ! generate elementary reflector h(i) to annihilate
                    ! a(i+2:m,i)
                    call la_qlarfg(m - i,a(i + 1,i),a(min(i + 2,m),i),1,tauq(i))

                    e(i) = a(i + 1,i)
                    a(i + 1,i) = one
                    ! apply h(i) to a(i+1:m,i+1:n) from the left
                    call la_qlarf('LEFT',m - i,n - i,a(i + 1,i),1,tauq(i),a(i + 1,i + 1), &
                              lda,work)
                    a(i + 1,i) = e(i)
                 else
                    tauq(i) = zero
                 end if
              end do
           end if
           return
     end subroutine la_qgebd2

     !> DGEBRD: reduces a general real M-by-N matrix A to upper or lower
     !> bidiagonal form B by an orthogonal transformation: Q**T * A * P = B.
     !> If m >= n, B is upper bidiagonal; if m < n, B is lower bidiagonal.

     pure subroutine la_qgebrd(m,n,a,lda,d,e,tauq,taup,work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,lwork,m,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: d(*),e(*),taup(*),tauq(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: i,iinfo,j,ldwrkx,ldwrky,lwkopt,minmn,nb,nbmin,nx,ws
           ! Intrinsic Functions
           intrinsic :: real,max,min
           ! Executable Statements
           ! test the input parameters
           info = 0
           nb = max(1,la_ilaenv(1,'DGEBRD',' ',m,n,-1,-1))
           lwkopt = (m + n)*nb
           work(1) = real(lwkopt,KIND=qp)
           lquery = (lwork == -1)
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,m)) then
              info = -4
           else if (lwork < max(1,m,n) .and. .not. lquery) then
              info = -10
           end if
           if (info < 0) then
              call la_xerbla('DGEBRD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           minmn = min(m,n)
           if (minmn == 0) then
              work(1) = 1
              return
           end if
           ws = max(m,n)
           ldwrkx = m
           ldwrky = n
           if (nb > 1 .and. nb < minmn) then
              ! set the crossover point nx.
              nx = max(nb,la_ilaenv(3,'DGEBRD',' ',m,n,-1,-1))
              ! determine when to switch from blocked to unblocked code.
              if (nx < minmn) then
                 ws = (m + n)*nb
                 if (lwork < ws) then
                    ! not enough work space for the optimal nb, consider using
                    ! a smaller block size.
                    nbmin = la_ilaenv(2,'DGEBRD',' ',m,n,-1,-1)
                    if (lwork >= (m + n)*nbmin) then
                       nb = lwork/(m + n)
                    else
                       nb = 1
                       nx = minmn
                    end if
                 end if
              end if
           else
              nx = minmn
           end if
           do i = 1,minmn - nx,nb
              ! reduce rows and columns i:i+nb-1 to bidiagonal form and return
              ! the matrices x and y which are needed to update the unreduced
              ! part of the matrix
              call la_qlabrd(m - i + 1,n - i + 1,nb,a(i,i),lda,d(i),e(i),tauq(i), &
                        taup(i),work,ldwrkx,work(ldwrkx*nb + 1),ldwrky)
              ! update the trailing submatrix a(i+nb:m,i+nb:n), using an update
              ! of the form  a := a - v*y**t - x*u**t
              call la_qgemm('NO TRANSPOSE','TRANSPOSE',m - i - nb + 1,n - i - nb + 1,nb,-one,a(i + &
                        nb,i),lda,work(ldwrkx*nb + nb + 1),ldwrky,one,a(i + nb,i + nb),lda)
              call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',m - i - nb + 1,n - i - nb + 1,nb,-one, &
                        work(nb + 1),ldwrkx,a(i,i + nb),lda,one,a(i + nb,i + nb),lda)
              ! copy diagonal and off-diagonal elements of b back into a
              if (m >= n) then
                 do j = i,i + nb - 1
                    a(j,j) = d(j)
                    a(j,j + 1) = e(j)
                 end do
              else
                 do j = i,i + nb - 1
                    a(j,j) = d(j)
                    a(j + 1,j) = e(j)
                 end do
              end if
           end do
           ! use unblocked code to reduce the remainder of the matrix
           call la_qgebd2(m - i + 1,n - i + 1,a(i,i),lda,d(i),e(i),tauq(i),taup(i), &
                     work,iinfo)
           work(1) = ws
           return
     end subroutine la_qgebrd

     !> DGEES: computes for an N-by-N real nonsymmetric matrix A, the
     !> eigenvalues, the real Schur form T, and, optionally, the matrix of
     !> Schur vectors Z.  This gives the Schur factorization A = Z*T*(Z**T).
     !> Optionally, it also orders the eigenvalues on the diagonal of the
     !> real Schur form so that selected eigenvalues are at the top left.
     !> The leading columns of Z then form an orthonormal basis for the
     !> invariant subspace corresponding to the selected eigenvalues.
     !> A matrix is in real Schur form if it is upper quasi-triangular with
     !> 1-by-1 and 2-by-2 blocks. 2-by-2 blocks will be standardized in the
     !> form
     !> [  a  b  ]
     !> [  c  a  ]
     !> where b*c < 0. The eigenvalues of such a block are a +- sqrt(bc).

     subroutine la_qgees(jobvs,sort,select,n,a,lda,sdim,wr,wi,vs,ldvs,work,lwork, &
               bwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobvs,sort
           integer(ilp),intent(out) :: info,sdim
           integer(ilp),intent(in) :: lda,ldvs,lwork,n
           ! Array Arguments
           logical(lk),intent(out) :: bwork(*)
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: vs(ldvs,*),wi(*),work(*),wr(*)
           ! Function Arguments
           procedure(la_select_q) :: select
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: cursl,lastsl,lquery,lst2sl,scalea,wantst,wantvs
           integer(ilp) :: hswork,i,i1,i2,ibal,icond,ierr,ieval,ihi,ilo,inxt,ip,itau, &
                     iwrk,maxwrk,minwrk
           real(qp) :: anrm,bignum,cscale,eps,s,sep,smlnum
           ! Local Arrays
           integer(ilp) :: idum(1)
           real(qp) :: dum(1)
           ! Intrinsic Functions
           intrinsic :: max,sqrt
           ! Executable Statements
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           wantvs = la_lsame(jobvs,'V')
           wantst = la_lsame(sort,'S')
           if ((.not. wantvs) .and. (.not. la_lsame(jobvs,'N'))) then
              info = -1
           else if ((.not. wantst) .and. (.not. la_lsame(sort,'N'))) then
              info = -2
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else if (ldvs < 1 .or. (wantvs .and. ldvs < n)) then
              info = -11
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv.
             ! hswork refers to the workspace preferred by la_qhseqr, as
             ! calculated below. hswork is computed assuming ilo=1 and ihi=n,
             ! the worst case.)
           if (info == 0) then
              if (n == 0) then
                 minwrk = 1
                 maxwrk = 1
              else
                 maxwrk = 2*n + n*la_ilaenv(1,'DGEHRD',' ',n,1,n,0)
                 minwrk = 3*n
                 call la_qhseqr('S',jobvs,n,1,n,a,lda,wr,wi,vs,ldvs,work,-1, &
                           ieval)
                 hswork = work(1)
                 if (.not. wantvs) then
                    maxwrk = max(maxwrk,n + hswork)
                 else
                    maxwrk = max(maxwrk,2*n + (n - 1)*la_ilaenv(1,'DORGHR',' ',n,1,n, &
                               -1))
                    maxwrk = max(maxwrk,n + hswork)
                 end if
              end if
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) then
                 info = -13
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DGEES ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) then
              sdim = 0
              return
           end if
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           smlnum = sqrt(smlnum)/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',n,n,a,lda,dum)
           scalea = .false.
           if (anrm > zero .and. anrm < smlnum) then
              scalea = .true.
              cscale = smlnum
           else if (anrm > bignum) then
              scalea = .true.
              cscale = bignum
           end if
           if (scalea) call la_qlascl('G',0,0,anrm,cscale,n,n,a,lda,ierr)
           ! permute the matrix to make it more nearly triangular
           ! (workspace: need n)
           ibal = 1
           call la_qgebal('P',n,a,lda,ilo,ihi,work(ibal),ierr)
           ! reduce to upper hessenberg form
           ! (workspace: need 3*n, prefer 2*n+n*nb)
           itau = n + ibal
           iwrk = n + itau
           call la_qgehrd(n,ilo,ihi,a,lda,work(itau),work(iwrk),lwork - iwrk + 1,ierr &
                     )
           if (wantvs) then
              ! copy householder vectors to vs
              call la_qlacpy('L',n,n,a,lda,vs,ldvs)
              ! generate orthogonal matrix in vs
              ! (workspace: need 3*n-1, prefer 2*n+(n-1)*nb)
              call la_qorghr(n,ilo,ihi,vs,ldvs,work(itau),work(iwrk),lwork - iwrk + 1, &
                        ierr)
           end if
           sdim = 0
           ! perform qr iteration, accumulating schur vectors in vs if desired
           ! (workspace: need n+1, prefer n+hswork (see comments) )
           iwrk = itau
           call la_qhseqr('S',jobvs,n,ilo,ihi,a,lda,wr,wi,vs,ldvs,work(iwrk), &
                     lwork - iwrk + 1,ieval)
           if (ieval > 0) info = ieval
           ! sort eigenvalues if desired
           if (wantst .and. info == 0) then
              if (scalea) then
                 call la_qlascl('G',0,0,cscale,anrm,n,1,wr,n,ierr)
                 call la_qlascl('G',0,0,cscale,anrm,n,1,wi,n,ierr)
              end if
              do i = 1,n
                 bwork(i) = select(wr(i),wi(i))
              end do
              ! reorder eigenvalues and transform schur vectors
              ! (workspace: none needed)
              call la_qtrsen('N',jobvs,bwork,n,a,lda,vs,ldvs,wr,wi,sdim,s,sep, &
                        work(iwrk),lwork - iwrk + 1,idum,1,icond)
              if (icond > 0) info = n + icond
           end if
           if (wantvs) then
              ! undo balancing
              ! (workspace: need n)
              call la_qgebak('P','R',n,ilo,ihi,work(ibal),n,vs,ldvs,ierr)
           end if
           if (scalea) then
              ! undo scaling for the schur form of a
              call la_qlascl('H',0,0,cscale,anrm,n,n,a,lda,ierr)
              call la_qcopy(n,a,lda + 1,wr,1)
              if (cscale == smlnum) then
                 ! if scaling back towards underflow, adjust wi if an
                 ! offdiagonal element of a 2-by-2 block in the schur form
                 ! underflows.
                 if (ieval > 0) then
                    i1 = ieval + 1
                    i2 = ihi - 1
                    call la_qlascl('G',0,0,cscale,anrm,ilo - 1,1,wi,max(ilo - 1,1), &
                              ierr)
                 else if (wantst) then
                    i1 = 1
                    i2 = n - 1
                 else
                    i1 = ilo
                    i2 = ihi - 1
                 end if
                 inxt = i1 - 1
                 loop_20: do i = i1,i2
                    if (i < inxt) cycle loop_20
                    if (wi(i) == zero) then
                       inxt = i + 1
                    else
                       if (a(i + 1,i) == zero) then
                          wi(i) = zero
                          wi(i + 1) = zero
                       else if (a(i + 1,i) /= zero .and. a(i,i + 1) == zero) then
                          wi(i) = zero
                          wi(i + 1) = zero
                          if (i > 1) call la_qswap(i - 1,a(1,i),1,a(1,i + 1),1)
                          if (n > i + 1) call la_qswap(n - i - 1,a(i,i + 2),lda,a(i + 1,i + 2), &
                                    lda)
                          if (wantvs) then
                             call la_qswap(n,vs(1,i),1,vs(1,i + 1),1)
                          end if
                          a(i,i + 1) = a(i + 1,i)
                          a(i + 1,i) = zero
                       end if
                       inxt = i + 2
                    end if
                 end do loop_20
              end if
              ! undo scaling for the imaginary part of the eigenvalues
              call la_qlascl('G',0,0,cscale,anrm,n - ieval,1,wi(ieval + 1),max(n - ieval, &
                         1),ierr)
           end if
           if (wantst .and. info == 0) then
              ! check if reordering successful
              lastsl = .true.
              lst2sl = .true.
              sdim = 0
              ip = 0
              do i = 1,n
                 cursl = select(wr(i),wi(i))
                 if (wi(i) == zero) then
                    if (cursl) sdim = sdim + 1
                    ip = 0
                    if (cursl .and. .not. lastsl) info = n + 2
                 else
                    if (ip == 1) then
                       ! last eigenvalue of conjugate pair
                       cursl = cursl .or. lastsl
                       lastsl = cursl
                       if (cursl) sdim = sdim + 2
                       ip = -1
                       if (cursl .and. .not. lst2sl) info = n + 2
                    else
                       ! first eigenvalue of conjugate pair
                       ip = 1
                    end if
                 end if
                 lst2sl = lastsl
                 lastsl = cursl
              end do
           end if
           work(1) = maxwrk
           return
     end subroutine la_qgees

     !> DGEESX: computes for an N-by-N real nonsymmetric matrix A, the
     !> eigenvalues, the real Schur form T, and, optionally, the matrix of
     !> Schur vectors Z.  This gives the Schur factorization A = Z*T*(Z**T).
     !> Optionally, it also orders the eigenvalues on the diagonal of the
     !> real Schur form so that selected eigenvalues are at the top left;
     !> computes a reciprocal condition number for the average of the
     !> selected eigenvalues (RCONDE); and computes a reciprocal condition
     !> number for the right invariant subspace corresponding to the
     !> selected eigenvalues (RCONDV).  The leading columns of Z form an
     !> orthonormal basis for this invariant subspace.
     !> For further explanation of the reciprocal condition numbers RCONDE
     !> and RCONDV, see Section 4.10_qp of the LAPACK Users' Guide (where
     !> these quantities are called s and sep respectively).
     !> A real matrix is in real Schur form if it is upper quasi-triangular
     !> with 1-by-1 and 2-by-2 blocks. 2-by-2 blocks will be standardized in
     !> the form
     !> [  a  b  ]
     !> [  c  a  ]
     !> where b*c < 0. The eigenvalues of such a block are a +- sqrt(bc).

     subroutine la_qgeesx(jobvs,sort,select,sense,n,a,lda,sdim,wr,wi,vs,ldvs, &
               rconde,rcondv,work,lwork,iwork,liwork,bwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobvs,sense,sort
           integer(ilp),intent(out) :: info,sdim
           integer(ilp),intent(in) :: lda,ldvs,liwork,lwork,n
           real(qp),intent(out) :: rconde,rcondv
           ! Array Arguments
           logical(lk),intent(out) :: bwork(*)
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: vs(ldvs,*),wi(*),work(*),wr(*)
           ! Function Arguments
           procedure(la_select_q) :: select
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: cursl,lastsl,lquery,lst2sl,scalea,wantsb,wantse,wantsn,wantst, &
                     wantsv,wantvs
           integer(ilp) :: hswork,i,i1,i2,ibal,icond,ierr,ieval,ihi,ilo,inxt,ip,itau, &
                     iwrk,liwrk,lwrk,maxwrk,minwrk
           real(qp) :: anrm,bignum,cscale,eps,smlnum
           ! Local Arrays
           real(qp) :: dum(1)
           ! Intrinsic Functions
           intrinsic :: max,sqrt
           ! Executable Statements
           ! test the input arguments
           info = 0
           wantvs = la_lsame(jobvs,'V')
           wantst = la_lsame(sort,'S')
           wantsn = la_lsame(sense,'N')
           wantse = la_lsame(sense,'E')
           wantsv = la_lsame(sense,'V')
           wantsb = la_lsame(sense,'B')
           lquery = (lwork == -1 .or. liwork == -1)
           if ((.not. wantvs) .and. (.not. la_lsame(jobvs,'N'))) then
              info = -1
           else if ((.not. wantst) .and. (.not. la_lsame(sort,'N'))) then
              info = -2
           else if (.not. (wantsn .or. wantse .or. wantsv .or. wantsb) .or. (.not. wantst .and. &
                     .not. wantsn)) then
              info = -4
           else if (n < 0) then
              info = -5
           else if (lda < max(1,n)) then
              info = -7
           else if (ldvs < 1 .or. (wantvs .and. ldvs < n)) then
              info = -12
           end if
           ! compute workspace
            ! (note: comments in the code beginning "rworkspace:" describe the
             ! minimal amount of real workspace needed at that point in the
             ! code, as well as the preferred amount for good performance.
             ! iworkspace refers to integer workspace.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv.
             ! hswork refers to the workspace preferred by la_qhseqr, as
             ! calculated below. hswork is computed assuming ilo=1 and ihi=n,
             ! the worst case.
             ! if sense = 'e', 'v' or 'b', then the amount of workspace needed
             ! depends on sdim, which is computed by the routine la_qtrsen later
             ! in the code.)
           if (info == 0) then
              liwrk = 1
              if (n == 0) then
                 minwrk = 1
                 lwrk = 1
              else
                 maxwrk = 2*n + n*la_ilaenv(1,'DGEHRD',' ',n,1,n,0)
                 minwrk = 3*n
                 call la_qhseqr('S',jobvs,n,1,n,a,lda,wr,wi,vs,ldvs,work,-1, &
                           ieval)
                 hswork = work(1)
                 if (.not. wantvs) then
                    maxwrk = max(maxwrk,n + hswork)
                 else
                    maxwrk = max(maxwrk,2*n + (n - 1)*la_ilaenv(1,'DORGHR',' ',n,1,n, &
                               -1))
                    maxwrk = max(maxwrk,n + hswork)
                 end if
                 lwrk = maxwrk
                 if (.not. wantsn) lwrk = max(lwrk,n + (n*n)/2)
                 if (wantsv .or. wantsb) liwrk = (n*n)/4
              end if
              iwork(1) = liwrk
              work(1) = lwrk
              if (lwork < minwrk .and. .not. lquery) then
                 info = -16
              else if (liwork < 1 .and. .not. lquery) then
                 info = -18
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DGEESX',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) then
              sdim = 0
              return
           end if
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           smlnum = sqrt(smlnum)/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',n,n,a,lda,dum)
           scalea = .false.
           if (anrm > zero .and. anrm < smlnum) then
              scalea = .true.
              cscale = smlnum
           else if (anrm > bignum) then
              scalea = .true.
              cscale = bignum
           end if
           if (scalea) call la_qlascl('G',0,0,anrm,cscale,n,n,a,lda,ierr)
           ! permute the matrix to make it more nearly triangular
           ! (rworkspace: need n)
           ibal = 1
           call la_qgebal('P',n,a,lda,ilo,ihi,work(ibal),ierr)
           ! reduce to upper hessenberg form
           ! (rworkspace: need 3*n, prefer 2*n+n*nb)
           itau = n + ibal
           iwrk = n + itau
           call la_qgehrd(n,ilo,ihi,a,lda,work(itau),work(iwrk),lwork - iwrk + 1,ierr &
                     )
           if (wantvs) then
              ! copy householder vectors to vs
              call la_qlacpy('L',n,n,a,lda,vs,ldvs)
              ! generate orthogonal matrix in vs
              ! (rworkspace: need 3*n-1, prefer 2*n+(n-1)*nb)
              call la_qorghr(n,ilo,ihi,vs,ldvs,work(itau),work(iwrk),lwork - iwrk + 1, &
                        ierr)
           end if
           sdim = 0
           ! perform qr iteration, accumulating schur vectors in vs if desired
           ! (rworkspace: need n+1, prefer n+hswork (see comments) )
           iwrk = itau
           call la_qhseqr('S',jobvs,n,ilo,ihi,a,lda,wr,wi,vs,ldvs,work(iwrk), &
                     lwork - iwrk + 1,ieval)
           if (ieval > 0) info = ieval
           ! sort eigenvalues if desired
           if (wantst .and. info == 0) then
              if (scalea) then
                 call la_qlascl('G',0,0,cscale,anrm,n,1,wr,n,ierr)
                 call la_qlascl('G',0,0,cscale,anrm,n,1,wi,n,ierr)
              end if
              do i = 1,n
                 bwork(i) = select(wr(i),wi(i))
              end do
              ! reorder eigenvalues, transform schur vectors, and compute
              ! reciprocal condition numbers
              ! (rworkspace: if sense is not 'n', need n+2*sdim*(n-sdim)
                           ! otherwise, need n )
              ! (iworkspace: if sense is 'v' or 'b', need sdim*(n-sdim)
                           ! otherwise, need 0 )
              call la_qtrsen(sense,jobvs,bwork,n,a,lda,vs,ldvs,wr,wi,sdim,rconde, &
                        rcondv,work(iwrk),lwork - iwrk + 1,iwork,liwork,icond)
              if (.not. wantsn) maxwrk = max(maxwrk,n + 2*sdim*(n - sdim))
              if (icond == -15) then
                 ! not enough real workspace
                 info = -16
              else if (icond == -17) then
                 ! not enough integer workspace
                 info = -18
              else if (icond > 0) then
                 ! la_qtrsen failed to reorder or to restore standard schur form
                 info = icond + n
              end if
           end if
           if (wantvs) then
              ! undo balancing
              ! (rworkspace: need n)
              call la_qgebak('P','R',n,ilo,ihi,work(ibal),n,vs,ldvs,ierr)
           end if
           if (scalea) then
              ! undo scaling for the schur form of a
              call la_qlascl('H',0,0,cscale,anrm,n,n,a,lda,ierr)
              call la_qcopy(n,a,lda + 1,wr,1)
              if ((wantsv .or. wantsb) .and. info == 0) then
                 dum(1) = rcondv
                 call la_qlascl('G',0,0,cscale,anrm,1,1,dum,1,ierr)
                 rcondv = dum(1)
              end if
              if (cscale == smlnum) then
                 ! if scaling back towards underflow, adjust wi if an
                 ! offdiagonal element of a 2-by-2 block in the schur form
                 ! underflows.
                 if (ieval > 0) then
                    i1 = ieval + 1
                    i2 = ihi - 1
                    call la_qlascl('G',0,0,cscale,anrm,ilo - 1,1,wi,n,ierr)
                 else if (wantst) then
                    i1 = 1
                    i2 = n - 1
                 else
                    i1 = ilo
                    i2 = ihi - 1
                 end if
                 inxt = i1 - 1
                 loop_20: do i = i1,i2
                    if (i < inxt) cycle loop_20
                    if (wi(i) == zero) then
                       inxt = i + 1
                    else
                       if (a(i + 1,i) == zero) then
                          wi(i) = zero
                          wi(i + 1) = zero
                       else if (a(i + 1,i) /= zero .and. a(i,i + 1) == zero) then
                          wi(i) = zero
                          wi(i + 1) = zero
                          if (i > 1) call la_qswap(i - 1,a(1,i),1,a(1,i + 1),1)
                          if (n > i + 1) call la_qswap(n - i - 1,a(i,i + 2),lda,a(i + 1,i + 2), &
                                    lda)
                          if (wantvs) then
                            call la_qswap(n,vs(1,i),1,vs(1,i + 1),1)
                          end if
                          a(i,i + 1) = a(i + 1,i)
                          a(i + 1,i) = zero
                       end if
                       inxt = i + 2
                    end if
                 end do loop_20
              end if
              call la_qlascl('G',0,0,cscale,anrm,n - ieval,1,wi(ieval + 1),max(n - ieval, &
                         1),ierr)
           end if
           if (wantst .and. info == 0) then
              ! check if reordering successful
              lastsl = .true.
              lst2sl = .true.
              sdim = 0
              ip = 0
              do i = 1,n
                 cursl = select(wr(i),wi(i))
                 if (wi(i) == zero) then
                    if (cursl) sdim = sdim + 1
                    ip = 0
                    if (cursl .and. .not. lastsl) info = n + 2
                 else
                    if (ip == 1) then
                       ! last eigenvalue of conjugate pair
                       cursl = cursl .or. lastsl
                       lastsl = cursl
                       if (cursl) sdim = sdim + 2
                       ip = -1
                       if (cursl .and. .not. lst2sl) info = n + 2
                    else
                       ! first eigenvalue of conjugate pair
                       ip = 1
                    end if
                 end if
                 lst2sl = lastsl
                 lastsl = cursl
              end do
           end if
           work(1) = maxwrk
           if (wantsv .or. wantsb) then
              iwork(1) = max(1,sdim*(n - sdim))
           else
              iwork(1) = 1
           end if
           return
     end subroutine la_qgeesx

     !> DGEEV: computes for an N-by-N real nonsymmetric matrix A, the
     !> eigenvalues and, optionally, the left and/or right eigenvectors.
     !> The right eigenvector v(j) of A satisfies
     !> A * v(j) = lambda(j) * v(j)
     !> where lambda(j) is its eigenvalue.
     !> The left eigenvector u(j) of A satisfies
     !> u(j)**H * A = lambda(j) * u(j)**H
     !> where u(j)**H denotes the conjugate-transpose of u(j).
     !> The computed eigenvectors are normalized to have Euclidean norm
     !> equal to 1 and largest component real.

     subroutine la_qgeev(jobvl,jobvr,n,a,lda,wr,wi,vl,ldvl,vr,ldvr,work,lwork, &
               info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobvl,jobvr
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldvl,ldvr,lwork,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: vl(ldvl,*),vr(ldvr,*),wi(*),work(*),wr(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,scalea,wantvl,wantvr
           character :: side
           integer(ilp) :: hswork,i,ibal,ierr,ihi,ilo,itau,iwrk,k,lwork_trevc,maxwrk, &
                     minwrk,nout
           real(qp) :: anrm,bignum,cs,cscale,eps,r,scl,smlnum,sn
           ! Local Arrays
           logical(lk) :: select(1)
           real(qp) :: dum(1)
           ! Intrinsic Functions
           intrinsic :: max,sqrt
           ! Executable Statements
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           wantvl = la_lsame(jobvl,'V')
           wantvr = la_lsame(jobvr,'V')
           if ((.not. wantvl) .and. (.not. la_lsame(jobvl,'N'))) then
              info = -1
           else if ((.not. wantvr) .and. (.not. la_lsame(jobvr,'N'))) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldvl < 1 .or. (wantvl .and. ldvl < n)) then
              info = -9
           else if (ldvr < 1 .or. (wantvr .and. ldvr < n)) then
              info = -11
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv.
             ! hswork refers to the workspace preferred by la_qhseqr, as
             ! calculated below. hswork is computed assuming ilo=1 and ihi=n,
             ! the worst case.)
           if (info == 0) then
              if (n == 0) then
                 minwrk = 1
                 maxwrk = 1
              else
                 maxwrk = 2*n + n*la_ilaenv(1,'DGEHRD',' ',n,1,n,0)
                 if (wantvl) then
                    minwrk = 4*n
                    maxwrk = max(maxwrk,2*n + (n - 1)*la_ilaenv(1,'DORGHR',' ',n,1,n, &
                               -1))
                    call la_qhseqr('S','V',n,1,n,a,lda,wr,wi,vl,ldvl,work,-1, &
                              info)
                    hswork = int(work(1),KIND=ilp)
                    maxwrk = max(maxwrk,n + 1,n + hswork)
                    call la_qtrevc3('L','B',select,n,a,lda,vl,ldvl,vr,ldvr,n,nout, &
                              work,-1,ierr)
                    lwork_trevc = int(work(1),KIND=ilp)
                    maxwrk = max(maxwrk,n + lwork_trevc)
                    maxwrk = max(maxwrk,4*n)
                 else if (wantvr) then
                    minwrk = 4*n
                    maxwrk = max(maxwrk,2*n + (n - 1)*la_ilaenv(1,'DORGHR',' ',n,1,n, &
                               -1))
                    call la_qhseqr('S','V',n,1,n,a,lda,wr,wi,vr,ldvr,work,-1, &
                              info)
                    hswork = int(work(1),KIND=ilp)
                    maxwrk = max(maxwrk,n + 1,n + hswork)
                    call la_qtrevc3('R','B',select,n,a,lda,vl,ldvl,vr,ldvr,n,nout, &
                              work,-1,ierr)
                    lwork_trevc = int(work(1),KIND=ilp)
                    maxwrk = max(maxwrk,n + lwork_trevc)
                    maxwrk = max(maxwrk,4*n)
                 else
                    minwrk = 3*n
                    call la_qhseqr('E','N',n,1,n,a,lda,wr,wi,vr,ldvr,work,-1, &
                              info)
                    hswork = int(work(1),KIND=ilp)
                    maxwrk = max(maxwrk,n + 1,n + hswork)
                 end if
                 maxwrk = max(maxwrk,minwrk)
              end if
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) then
                 info = -13
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DGEEV ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           smlnum = sqrt(smlnum)/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',n,n,a,lda,dum)
           scalea = .false.
           if (anrm > zero .and. anrm < smlnum) then
              scalea = .true.
              cscale = smlnum
           else if (anrm > bignum) then
              scalea = .true.
              cscale = bignum
           end if
           if (scalea) call la_qlascl('G',0,0,anrm,cscale,n,n,a,lda,ierr)
           ! balance the matrix
           ! (workspace: need n)
           ibal = 1
           call la_qgebal('B',n,a,lda,ilo,ihi,work(ibal),ierr)
           ! reduce to upper hessenberg form
           ! (workspace: need 3*n, prefer 2*n+n*nb)
           itau = ibal + n
           iwrk = itau + n
           call la_qgehrd(n,ilo,ihi,a,lda,work(itau),work(iwrk),lwork - iwrk + 1,ierr &
                     )
           if (wantvl) then
              ! want left eigenvectors
              ! copy householder vectors to vl
              side = 'L'
              call la_qlacpy('L',n,n,a,lda,vl,ldvl)
              ! generate orthogonal matrix in vl
              ! (workspace: need 3*n-1, prefer 2*n+(n-1)*nb)
              call la_qorghr(n,ilo,ihi,vl,ldvl,work(itau),work(iwrk),lwork - iwrk + 1, &
                        ierr)
              ! perform qr iteration, accumulating schur vectors in vl
              ! (workspace: need n+1, prefer n+hswork (see comments) )
              iwrk = itau
              call la_qhseqr('S','V',n,ilo,ihi,a,lda,wr,wi,vl,ldvl,work(iwrk), &
                        lwork - iwrk + 1,info)
              if (wantvr) then
                 ! want left and right eigenvectors
                 ! copy schur vectors to vr
                 side = 'B'
                 call la_qlacpy('F',n,n,vl,ldvl,vr,ldvr)
              end if
           else if (wantvr) then
              ! want right eigenvectors
              ! copy householder vectors to vr
              side = 'R'
              call la_qlacpy('L',n,n,a,lda,vr,ldvr)
              ! generate orthogonal matrix in vr
              ! (workspace: need 3*n-1, prefer 2*n+(n-1)*nb)
              call la_qorghr(n,ilo,ihi,vr,ldvr,work(itau),work(iwrk),lwork - iwrk + 1, &
                        ierr)
              ! perform qr iteration, accumulating schur vectors in vr
              ! (workspace: need n+1, prefer n+hswork (see comments) )
              iwrk = itau
              call la_qhseqr('S','V',n,ilo,ihi,a,lda,wr,wi,vr,ldvr,work(iwrk), &
                        lwork - iwrk + 1,info)
           else
              ! compute eigenvalues only
              ! (workspace: need n+1, prefer n+hswork (see comments) )
              iwrk = itau
              call la_qhseqr('E','N',n,ilo,ihi,a,lda,wr,wi,vr,ldvr,work(iwrk), &
                        lwork - iwrk + 1,info)
           end if
           ! if info /= 0 from la_qhseqr, then quit
           if (info /= 0) go to 50
           if (wantvl .or. wantvr) then
              ! compute left and/or right eigenvectors
              ! (workspace: need 4*n, prefer n + n + 2*n*nb)
              call la_qtrevc3(side,'B',select,n,a,lda,vl,ldvl,vr,ldvr,n,nout,work( &
                         iwrk),lwork - iwrk + 1,ierr)
           end if
           if (wantvl) then
              ! undo balancing of left eigenvectors
              ! (workspace: need n)
              call la_qgebak('B','L',n,ilo,ihi,work(ibal),n,vl,ldvl,ierr)
              ! normalize left eigenvectors and make largest component real
              do i = 1,n
                 if (wi(i) == zero) then
                    scl = one/la_qnrm2(n,vl(1,i),1)
                    call la_qscal(n,scl,vl(1,i),1)
                 else if (wi(i) > zero) then
                    scl = one/la_qlapy2(la_qnrm2(n,vl(1,i),1),la_qnrm2(n, &
                              vl(1,i + 1),1))
                    call la_qscal(n,scl,vl(1,i),1)
                    call la_qscal(n,scl,vl(1,i + 1),1)
                    do k = 1,n
                       work(iwrk + k - 1) = vl(k,i)**2 + vl(k,i + 1)**2
                    end do
                    k = la_iqamax(n,work(iwrk),1)
                    call la_qlartg(vl(k,i),vl(k,i + 1),cs,sn,r)
                    call la_qrot(n,vl(1,i),1,vl(1,i + 1),1,cs,sn)
                    vl(k,i + 1) = zero
                 end if
              end do
           end if
           if (wantvr) then
              ! undo balancing of right eigenvectors
              ! (workspace: need n)
              call la_qgebak('B','R',n,ilo,ihi,work(ibal),n,vr,ldvr,ierr)
              ! normalize right eigenvectors and make largest component real
              do i = 1,n
                 if (wi(i) == zero) then
                    scl = one/la_qnrm2(n,vr(1,i),1)
                    call la_qscal(n,scl,vr(1,i),1)
                 else if (wi(i) > zero) then
                    scl = one/la_qlapy2(la_qnrm2(n,vr(1,i),1),la_qnrm2(n, &
                              vr(1,i + 1),1))
                    call la_qscal(n,scl,vr(1,i),1)
                    call la_qscal(n,scl,vr(1,i + 1),1)
                    do k = 1,n
                       work(iwrk + k - 1) = vr(k,i)**2 + vr(k,i + 1)**2
                    end do
                    k = la_iqamax(n,work(iwrk),1)
                    call la_qlartg(vr(k,i),vr(k,i + 1),cs,sn,r)
                    call la_qrot(n,vr(1,i),1,vr(1,i + 1),1,cs,sn)
                    vr(k,i + 1) = zero
                 end if
              end do
           end if
           ! undo scaling if necessary
           50 continue
           if (scalea) then
              call la_qlascl('G',0,0,cscale,anrm,n - info,1,wr(info + 1),max(n - info,1 &
                        ),ierr)
              call la_qlascl('G',0,0,cscale,anrm,n - info,1,wi(info + 1),max(n - info,1 &
                        ),ierr)
              if (info > 0) then
                 call la_qlascl('G',0,0,cscale,anrm,ilo - 1,1,wr,n,ierr)
                 call la_qlascl('G',0,0,cscale,anrm,ilo - 1,1,wi,n,ierr)
              end if
           end if
           work(1) = maxwrk
           return
     end subroutine la_qgeev

     !> DGEEVX: computes for an N-by-N real nonsymmetric matrix A, the
     !> eigenvalues and, optionally, the left and/or right eigenvectors.
     !> Optionally also, it computes a balancing transformation to improve
     !> the conditioning of the eigenvalues and eigenvectors (ILO, IHI,
     !> SCALE, and ABNRM), reciprocal condition numbers for the eigenvalues
     !> (RCONDE), and reciprocal condition numbers for the right
     !> eigenvectors (RCONDV).
     !> The right eigenvector v(j) of A satisfies
     !> A * v(j) = lambda(j) * v(j)
     !> where lambda(j) is its eigenvalue.
     !> The left eigenvector u(j) of A satisfies
     !> u(j)**H * A = lambda(j) * u(j)**H
     !> where u(j)**H denotes the conjugate-transpose of u(j).
     !> The computed eigenvectors are normalized to have Euclidean norm
     !> equal to 1 and largest component real.
     !> Balancing a matrix means permuting the rows and columns to make it
     !> more nearly upper triangular, and applying a diagonal similarity
     !> transformation D * A * D**(-1), where D is a diagonal matrix, to
     !> make its rows and columns closer in norm and the condition numbers
     !> of its eigenvalues and eigenvectors smaller.  The computed
     !> reciprocal condition numbers correspond to the balanced matrix.
     !> Permuting rows and columns will not change the condition numbers
     !> (in exact arithmetic) but diagonal scaling will.  For further
     !> explanation of balancing, see section 4.10.2_qp of the LAPACK
     !> Users' Guide.

     subroutine la_qgeevx(balanc,jobvl,jobvr,sense,n,a,lda,wr,wi,vl,ldvl,vr,ldvr, &
               ilo,ihi,scale,abnrm,rconde,rcondv,work,lwork,iwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: balanc,jobvl,jobvr,sense
           integer(ilp),intent(out) :: ihi,ilo,info
           integer(ilp),intent(in) :: lda,ldvl,ldvr,lwork,n
           real(qp),intent(out) :: abnrm
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: rconde(*),rcondv(*),scale(*),vl(ldvl,*),vr(ldvr,*),wi(*), &
                      work(*),wr(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,scalea,wantvl,wantvr,wntsnb,wntsne,wntsnn,wntsnv
           character :: job,side
           integer(ilp) :: hswork,i,icond,ierr,itau,iwrk,k,lwork_trevc,maxwrk,minwrk, &
                     nout
           real(qp) :: anrm,bignum,cs,cscale,eps,r,scl,smlnum,sn
           ! Local Arrays
           logical(lk) :: select(1)
           real(qp) :: dum(1)
           ! Intrinsic Functions
           intrinsic :: max,sqrt
           ! Executable Statements
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           wantvl = la_lsame(jobvl,'V')
           wantvr = la_lsame(jobvr,'V')
           wntsnn = la_lsame(sense,'N')
           wntsne = la_lsame(sense,'E')
           wntsnv = la_lsame(sense,'V')
           wntsnb = la_lsame(sense,'B')
           if (.not. (la_lsame(balanc,'N') .or. la_lsame(balanc,'S') .or. &
                     la_lsame(balanc,'P') .or. la_lsame(balanc,'B'))) then
              info = -1
           else if ((.not. wantvl) .and. (.not. la_lsame(jobvl,'N'))) then
              info = -2
           else if ((.not. wantvr) .and. (.not. la_lsame(jobvr,'N'))) then
              info = -3
           else if (.not. (wntsnn .or. wntsne .or. wntsnb .or. wntsnv) .or. ((wntsne .or. &
                     wntsnb) .and. .not. (wantvl .and. wantvr))) then
              info = -4
           else if (n < 0) then
              info = -5
           else if (lda < max(1,n)) then
              info = -7
           else if (ldvl < 1 .or. (wantvl .and. ldvl < n)) then
              info = -11
           else if (ldvr < 1 .or. (wantvr .and. ldvr < n)) then
              info = -13
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv.
             ! hswork refers to the workspace preferred by la_qhseqr, as
             ! calculated below. hswork is computed assuming ilo=1 and ihi=n,
             ! the worst case.)
           if (info == 0) then
              if (n == 0) then
                 minwrk = 1
                 maxwrk = 1
              else
                 maxwrk = n + n*la_ilaenv(1,'DGEHRD',' ',n,1,n,0)
                 if (wantvl) then
                    call la_qtrevc3('L','B',select,n,a,lda,vl,ldvl,vr,ldvr,n,nout, &
                              work,-1,ierr)
                    lwork_trevc = int(work(1),KIND=ilp)
                    maxwrk = max(maxwrk,n + lwork_trevc)
                    call la_qhseqr('S','V',n,1,n,a,lda,wr,wi,vl,ldvl,work,-1, &
                              info)
                 else if (wantvr) then
                    call la_qtrevc3('R','B',select,n,a,lda,vl,ldvl,vr,ldvr,n,nout, &
                              work,-1,ierr)
                    lwork_trevc = int(work(1),KIND=ilp)
                    maxwrk = max(maxwrk,n + lwork_trevc)
                    call la_qhseqr('S','V',n,1,n,a,lda,wr,wi,vr,ldvr,work,-1, &
                              info)
                 else
                    if (wntsnn) then
                       call la_qhseqr('E','N',n,1,n,a,lda,wr,wi,vr,ldvr,work,-1, &
                                 info)
                    else
                       call la_qhseqr('S','N',n,1,n,a,lda,wr,wi,vr,ldvr,work,-1, &
                                 info)
                    end if
                 end if
                 hswork = int(work(1),KIND=ilp)
                 if ((.not. wantvl) .and. (.not. wantvr)) then
                    minwrk = 2*n
                    if (.not. wntsnn) minwrk = max(minwrk,n*n + 6*n)
                    maxwrk = max(maxwrk,hswork)
                    if (.not. wntsnn) maxwrk = max(maxwrk,n*n + 6*n)
                 else
                    minwrk = 3*n
                    if ((.not. wntsnn) .and. (.not. wntsne)) minwrk = max(minwrk,n*n + 6*n)

                    maxwrk = max(maxwrk,hswork)
                    maxwrk = max(maxwrk,n + (n - 1)*la_ilaenv(1,'DORGHR',' ',n,1,n,- &
                              1))
                    if ((.not. wntsnn) .and. (.not. wntsne)) maxwrk = max(maxwrk,n*n + 6*n)

                    maxwrk = max(maxwrk,3*n)
                 end if
                 maxwrk = max(maxwrk,minwrk)
              end if
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) then
                 info = -21
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DGEEVX',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           smlnum = sqrt(smlnum)/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           icond = 0
           anrm = la_qlange('M',n,n,a,lda,dum)
           scalea = .false.
           if (anrm > zero .and. anrm < smlnum) then
              scalea = .true.
              cscale = smlnum
           else if (anrm > bignum) then
              scalea = .true.
              cscale = bignum
           end if
           if (scalea) call la_qlascl('G',0,0,anrm,cscale,n,n,a,lda,ierr)
           ! balance the matrix and compute abnrm
           call la_qgebal(balanc,n,a,lda,ilo,ihi,scale,ierr)
           abnrm = la_qlange('1',n,n,a,lda,dum)
           if (scalea) then
              dum(1) = abnrm
              call la_qlascl('G',0,0,cscale,anrm,1,1,dum,1,ierr)
              abnrm = dum(1)
           end if
           ! reduce to upper hessenberg form
           ! (workspace: need 2*n, prefer n+n*nb)
           itau = 1
           iwrk = itau + n
           call la_qgehrd(n,ilo,ihi,a,lda,work(itau),work(iwrk),lwork - iwrk + 1,ierr &
                     )
           if (wantvl) then
              ! want left eigenvectors
              ! copy householder vectors to vl
              side = 'L'
              call la_qlacpy('L',n,n,a,lda,vl,ldvl)
              ! generate orthogonal matrix in vl
              ! (workspace: need 2*n-1, prefer n+(n-1)*nb)
              call la_qorghr(n,ilo,ihi,vl,ldvl,work(itau),work(iwrk),lwork - iwrk + 1, &
                        ierr)
              ! perform qr iteration, accumulating schur vectors in vl
              ! (workspace: need 1, prefer hswork (see comments) )
              iwrk = itau
              call la_qhseqr('S','V',n,ilo,ihi,a,lda,wr,wi,vl,ldvl,work(iwrk), &
                        lwork - iwrk + 1,info)
              if (wantvr) then
                 ! want left and right eigenvectors
                 ! copy schur vectors to vr
                 side = 'B'
                 call la_qlacpy('F',n,n,vl,ldvl,vr,ldvr)
              end if
           else if (wantvr) then
              ! want right eigenvectors
              ! copy householder vectors to vr
              side = 'R'
              call la_qlacpy('L',n,n,a,lda,vr,ldvr)
              ! generate orthogonal matrix in vr
              ! (workspace: need 2*n-1, prefer n+(n-1)*nb)
              call la_qorghr(n,ilo,ihi,vr,ldvr,work(itau),work(iwrk),lwork - iwrk + 1, &
                        ierr)
              ! perform qr iteration, accumulating schur vectors in vr
              ! (workspace: need 1, prefer hswork (see comments) )
              iwrk = itau
              call la_qhseqr('S','V',n,ilo,ihi,a,lda,wr,wi,vr,ldvr,work(iwrk), &
                        lwork - iwrk + 1,info)
           else
              ! compute eigenvalues only
              ! if condition numbers desired, compute schur form
              if (wntsnn) then
                 job = 'E'
              else
                 job = 'S'
              end if
              ! (workspace: need 1, prefer hswork (see comments) )
              iwrk = itau
              call la_qhseqr(job,'N',n,ilo,ihi,a,lda,wr,wi,vr,ldvr,work(iwrk), &
                        lwork - iwrk + 1,info)
           end if
           ! if info /= 0 from la_qhseqr, then quit
           if (info /= 0) go to 50
           if (wantvl .or. wantvr) then
              ! compute left and/or right eigenvectors
              ! (workspace: need 3*n, prefer n + 2*n*nb)
              call la_qtrevc3(side,'B',select,n,a,lda,vl,ldvl,vr,ldvr,n,nout,work( &
                         iwrk),lwork - iwrk + 1,ierr)
           end if
           ! compute condition numbers if desired
           ! (workspace: need n*n+6*n unless sense = 'e')
           if (.not. wntsnn) then
              call la_qtrsna(sense,'A',select,n,a,lda,vl,ldvl,vr,ldvr,rconde, &
                        rcondv,n,nout,work(iwrk),n,iwork,icond)
           end if
           if (wantvl) then
              ! undo balancing of left eigenvectors
              call la_qgebak(balanc,'L',n,ilo,ihi,scale,n,vl,ldvl,ierr)
              ! normalize left eigenvectors and make largest component real
              do i = 1,n
                 if (wi(i) == zero) then
                    scl = one/la_qnrm2(n,vl(1,i),1)
                    call la_qscal(n,scl,vl(1,i),1)
                 else if (wi(i) > zero) then
                    scl = one/la_qlapy2(la_qnrm2(n,vl(1,i),1),la_qnrm2(n, &
                              vl(1,i + 1),1))
                    call la_qscal(n,scl,vl(1,i),1)
                    call la_qscal(n,scl,vl(1,i + 1),1)
                    do k = 1,n
                       work(k) = vl(k,i)**2 + vl(k,i + 1)**2
                    end do
                    k = la_iqamax(n,work,1)
                    call la_qlartg(vl(k,i),vl(k,i + 1),cs,sn,r)
                    call la_qrot(n,vl(1,i),1,vl(1,i + 1),1,cs,sn)
                    vl(k,i + 1) = zero
                 end if
              end do
           end if
           if (wantvr) then
              ! undo balancing of right eigenvectors
              call la_qgebak(balanc,'R',n,ilo,ihi,scale,n,vr,ldvr,ierr)
              ! normalize right eigenvectors and make largest component real
              do i = 1,n
                 if (wi(i) == zero) then
                    scl = one/la_qnrm2(n,vr(1,i),1)
                    call la_qscal(n,scl,vr(1,i),1)
                 else if (wi(i) > zero) then
                    scl = one/la_qlapy2(la_qnrm2(n,vr(1,i),1),la_qnrm2(n, &
                              vr(1,i + 1),1))
                    call la_qscal(n,scl,vr(1,i),1)
                    call la_qscal(n,scl,vr(1,i + 1),1)
                    do k = 1,n
                       work(k) = vr(k,i)**2 + vr(k,i + 1)**2
                    end do
                    k = la_iqamax(n,work,1)
                    call la_qlartg(vr(k,i),vr(k,i + 1),cs,sn,r)
                    call la_qrot(n,vr(1,i),1,vr(1,i + 1),1,cs,sn)
                    vr(k,i + 1) = zero
                 end if
              end do
           end if
           ! undo scaling if necessary
           50 continue
           if (scalea) then
              call la_qlascl('G',0,0,cscale,anrm,n - info,1,wr(info + 1),max(n - info,1 &
                        ),ierr)
              call la_qlascl('G',0,0,cscale,anrm,n - info,1,wi(info + 1),max(n - info,1 &
                        ),ierr)
              if (info == 0) then
                 if ((wntsnv .or. wntsnb) .and. icond == 0) call la_qlascl('G',0,0,cscale, &
                            anrm,n,1,rcondv,n,ierr)
              else
                 call la_qlascl('G',0,0,cscale,anrm,ilo - 1,1,wr,n,ierr)
                 call la_qlascl('G',0,0,cscale,anrm,ilo - 1,1,wi,n,ierr)
              end if
           end if
           work(1) = maxwrk
           return
     end subroutine la_qgeevx

     !> DGEJSV: computes the singular value decomposition (SVD) of a real M-by-N
     !> matrix [A], where M >= N. The SVD of [A] is written as
     !> [A] = [U] * [SIGMA] * [V]^t,
     !> where [SIGMA] is an N-by-N (M-by-N) matrix which is zero except for its N
     !> diagonal elements, [U] is an M-by-N (or M-by-M) orthonormal matrix, and
     !> [V] is an N-by-N orthogonal matrix. The diagonal elements of [SIGMA] are
     !> the singular values of [A]. The columns of [U] and [V] are the left and
     !> the right singular vectors of [A], respectively. The matrices [U] and [V]
     !> are computed and stored in the arrays U and V, respectively. The diagonal
     !> of [SIGMA] is computed and stored in the array SVA.
     !> DGEJSV can sometimes compute tiny singular values and their singular vectors much
     !> more accurately than other SVD routines, see below under Further Details.

     pure subroutine la_qgejsv(joba,jobu,jobv,jobr,jobt,jobp,m,n,a,lda,sva,u,ldu, &
               v,ldv,work,lwork,iwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldu,ldv,lwork,m,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: sva(n),u(ldu,*),v(ldv,*),work(lwork)
           integer(ilp),intent(out) :: iwork(*)
           character,intent(in) :: joba,jobp,jobr,jobt,jobu,jobv
        ! ===========================================================================

           ! Local Scalars
           real(qp) :: aapp,aaqq,aatmax,aatmin,big,big1,cond_ok,condr1,condr2,entra, &
                     entrat,epsln,maxprj,scalem,sconda,sfmin,small,temp1,uscal1,uscal2,xsc
           integer(ilp) :: ierr,n1,nr,numrank,p,q,warning
           logical(lk) :: almort,defr,errest,goscal,jracc,kill,lsvec,l2aber,l2kill, &
                     l2pert,l2rank,l2tran,noscal,rowpiv,rsvec,transp
           ! Intrinsic Functions
           intrinsic :: abs,log,max,min,real,idnint,sign,sqrt
           ! test the input arguments
           lsvec = la_lsame(jobu,'U') .or. la_lsame(jobu,'F')
           jracc = la_lsame(jobv,'J')
           rsvec = la_lsame(jobv,'V') .or. jracc
           rowpiv = la_lsame(joba,'F') .or. la_lsame(joba,'G')
           l2rank = la_lsame(joba,'R')
           l2aber = la_lsame(joba,'A')
           errest = la_lsame(joba,'E') .or. la_lsame(joba,'G')
           l2tran = la_lsame(jobt,'T')
           l2kill = la_lsame(jobr,'R')
           defr = la_lsame(jobr,'N')
           l2pert = la_lsame(jobp,'P')
           if (.not. (rowpiv .or. l2rank .or. l2aber .or. errest .or. la_lsame(joba,'C'))) &
                     then
              info = -1
           else if (.not. (lsvec .or. la_lsame(jobu,'N') .or. la_lsame(jobu,'W'))) &
                      then
              info = -2
           else if (.not. (rsvec .or. la_lsame(jobv,'N') .or. la_lsame(jobv,'W')) &
                     .or. (jracc .and. (.not. lsvec))) then
              info = -3
           else if (.not. (l2kill .or. defr)) then
              info = -4
           else if (.not. (l2tran .or. la_lsame(jobt,'N'))) then
              info = -5
           else if (.not. (l2pert .or. la_lsame(jobp,'N'))) then
              info = -6
           else if (m < 0) then
              info = -7
           else if ((n < 0) .or. (n > m)) then
              info = -8
           else if (lda < m) then
              info = -10
           else if (lsvec .and. (ldu < m)) then
              info = -13
           else if (rsvec .and. (ldv < n)) then
              info = -15
           else if ((.not. (lsvec .or. rsvec .or. errest) .and. (lwork < max(7,4*n + 1,2*m + n))) .or. ( &
           .not. (lsvec .or. rsvec) .and. errest .and. (lwork < max(7,4*n + n*n,2*m + n))) .or. (lsvec &
           .and. (.not. rsvec) .and. (lwork < max(7,2*m + n,4*n + 1))) .or. (rsvec .and. (.not. lsvec) &
           .and. (lwork < max(7,2*m + n,4*n + 1))) .or. (lsvec .and. rsvec .and. (.not. jracc) .and. ( &
           lwork < max(2*m + n,6*n + 2*n*n))) .or. (lsvec .and. rsvec .and. jracc .and. lwork < max(2*m + n, &
                     4*n + n*n,2*n + n*n + 6))) then
              info = -17
           else
              ! #:)
              info = 0
           end if
           if (info /= 0) then
             ! #:(
              call la_xerbla('DGEJSV',-info)
              return
           end if
           ! quick return for void matrix (y3k safe)
       ! #:)
           if ((m == 0) .or. (n == 0)) then
              iwork(1:3) = 0
              work(1:7) = 0
              return
           end if
           ! determine whether the matrix u should be m x n or m x m
           if (lsvec) then
              n1 = n
              if (la_lsame(jobu,'F')) n1 = m
           end if
           ! set numerical parameters
      ! !    note: make sure la_qlamch() does not fail on the target architecture.
           epsln = la_qlamch('EPSILON')
           sfmin = la_qlamch('SAFEMINIMUM')
           small = sfmin/epsln
           big = la_qlamch('O')
           ! big   = one / sfmin
           ! initialize sva(1:n) = diag( ||a e_i||_2 )_1^n
      ! (!)  if necessary, scale sva() to protect the largest norm from
           ! overflow. it is possible that this scaling pushes the smallest
           ! column norm left from the underflow threshold (extreme case).
           scalem = one/sqrt(real(m,KIND=qp)*real(n,KIND=qp))
           noscal = .true.
           goscal = .true.
           do p = 1,n
              aapp = zero
              aaqq = one
              call la_qlassq(m,a(1,p),1,aapp,aaqq)
              if (aapp > big) then
                 info = -9
                 call la_xerbla('DGEJSV',-info)
                 return
              end if
              aaqq = sqrt(aaqq)
              if ((aapp < (big/aaqq)) .and. noscal) then
                 sva(p) = aapp*aaqq
              else
                 noscal = .false.
                 sva(p) = aapp*(aaqq*scalem)
                 if (goscal) then
                    goscal = .false.
                    call la_qscal(p - 1,scalem,sva,1)
                 end if
              end if
           end do
           if (noscal) scalem = one
           aapp = zero
           aaqq = big
           do p = 1,n
              aapp = max(aapp,sva(p))
              if (sva(p) /= zero) aaqq = min(aaqq,sva(p))
           end do
           ! quick return for zero m x n matrix
       ! #:)
           if (aapp == zero) then
              if (lsvec) call la_qlaset('G',m,n1,zero,one,u,ldu)
              if (rsvec) call la_qlaset('G',n,n,zero,one,v,ldv)
              work(1) = one
              work(2) = one
              if (errest) work(3) = one
              if (lsvec .and. rsvec) then
                 work(4) = one
                 work(5) = one
              end if
              if (l2tran) then
                 work(6) = zero
                 work(7) = zero
              end if
              iwork(1) = 0
              iwork(2) = 0
              iwork(3) = 0
              return
           end if
           ! issue warning if denormalized column norms detected. override the
           ! high relative accuracy request. issue licence to kill columns
           ! (set them to zero) whose norm is less than sigma_max / big (roughly).
       ! #:(
           warning = 0
           if (aaqq <= sfmin) then
              l2rank = .true.
              l2kill = .true.
              warning = 1
           end if
           ! quick return for one-column matrix
       ! #:)
           if (n == 1) then
              if (lsvec) then
                 call la_qlascl('G',0,0,sva(1),scalem,m,1,a(1,1),lda,ierr)
                 call la_qlacpy('A',m,1,a,lda,u,ldu)
                 ! computing all m left singular vectors of the m x 1 matrix
                 if (n1 /= n) then
                    call la_qgeqrf(m,n,u,ldu,work,work(n + 1),lwork - n,ierr)
                    call la_qorgqr(m,n1,1,u,ldu,work,work(n + 1),lwork - n,ierr)
                    call la_qcopy(m,a(1,1),1,u(1,1),1)
                 end if
              end if
              if (rsvec) then
                  v(1,1) = one
              end if
              if (sva(1) < (big*scalem)) then
                 sva(1) = sva(1)/scalem
                 scalem = one
              end if
              work(1) = one/scalem
              work(2) = one
              if (sva(1) /= zero) then
                 iwork(1) = 1
                 if ((sva(1)/scalem) >= sfmin) then
                    iwork(2) = 1
                 else
                    iwork(2) = 0
                 end if
              else
                 iwork(1) = 0
                 iwork(2) = 0
              end if
              iwork(3) = 0
              if (errest) work(3) = one
              if (lsvec .and. rsvec) then
                 work(4) = one
                 work(5) = one
              end if
              if (l2tran) then
                 work(6) = zero
                 work(7) = zero
              end if
              return
           end if
           transp = .false.
           l2tran = l2tran .and. (m == n)
           aatmax = -one
           aatmin = big
           if (rowpiv .or. l2tran) then
           ! compute the row norms, needed to determine row pivoting sequence
           ! (in the case of heavily row weighted a, row pivoting is strongly
           ! advised) and to collect information needed to compare the
           ! structures of a * a^t and a^t * a (in the case l2tran==.true.).
              if (l2tran) then
                 do p = 1,m
                    xsc = zero
                    temp1 = one
                    call la_qlassq(n,a(p,1),lda,xsc,temp1)
                    ! la_qlassq gets both the ell_2 and the ell_infinity norm
                    ! in one pass through the vector
                    work(m + n + p) = xsc*scalem
                    work(n + p) = xsc*(scalem*sqrt(temp1))
                    aatmax = max(aatmax,work(n + p))
                    if (work(n + p) /= zero) aatmin = min(aatmin,work(n + p))
                 end do
              else
                 do p = 1,m
                    work(m + n + p) = scalem*abs(a(p,la_iqamax(n,a(p,1),lda)))
                    aatmax = max(aatmax,work(m + n + p))
                    aatmin = min(aatmin,work(m + n + p))
                 end do
              end if
           end if
           ! for square matrix a try to determine whether a^t  would be  better
           ! input for the preconditioned jacobi svd, with faster convergence.
           ! the decision is based on an o(n) function of the vector of column
           ! and row norms of a, based on the shannon entropy. this should give
           ! the right choice in most cases when the difference actually matters.
           ! it may fail and pick the slower converging side.
           entra = zero
           entrat = zero
           if (l2tran) then
              xsc = zero
              temp1 = one
              call la_qlassq(n,sva,1,xsc,temp1)
              temp1 = one/temp1
              entra = zero
              do p = 1,n
                 big1 = ((sva(p)/xsc)**2)*temp1
                 if (big1 /= zero) entra = entra + big1*log(big1)
              end do
              entra = -entra/log(real(n,KIND=qp))
              ! now, sva().^2/trace(a^t * a) is a point in the probability simplex.
              ! it is derived from the diagonal of  a^t * a.  do the same with the
              ! diagonal of a * a^t, compute the entropy of the corresponding
              ! probability distribution. note that a * a^t and a^t * a have the
              ! same trace.
              entrat = zero
              do p = n + 1,n + m
                 big1 = ((work(p)/xsc)**2)*temp1
                 if (big1 /= zero) entrat = entrat + big1*log(big1)
              end do
              entrat = -entrat/log(real(m,KIND=qp))
              ! analyze the entropies and decide a or a^t. smaller entropy
              ! usually means better input for the algorithm.
              transp = (entrat < entra)
              ! if a^t is better than a, transpose a.
              if (transp) then
                 ! in an optimal implementation, this trivial transpose
                 ! should be replaced with faster transpose.
                 do p = 1,n - 1
                    do q = p + 1,n
                        temp1 = a(q,p)
                       a(q,p) = a(p,q)
                       a(p,q) = temp1
                    end do
                 end do
                 do p = 1,n
                    work(m + n + p) = sva(p)
                    sva(p) = work(n + p)
                 end do
                 temp1 = aapp
                 aapp = aatmax
                 aatmax = temp1
                 temp1 = aaqq
                 aaqq = aatmin
                 aatmin = temp1
                 kill = lsvec
                 lsvec = rsvec
                 rsvec = kill
                 if (lsvec) n1 = n
                 rowpiv = .true.
              end if
           end if
           ! end if l2tran
           ! scale the matrix so that its maximal singular value remains less
           ! than sqrt(big) -- the matrix is scaled so that its maximal column
           ! has euclidean norm equal to sqrt(big/n). the only reason to keep
           ! sqrt(big) instead of big is the fact that la_qgejsv uses lapack and
           ! blas routines that, in some implementations, are not capable of
           ! working in the full interval [sfmin,big] and that they may provoke
           ! overflows in the intermediate results. if the singular values spread
           ! from sfmin to big, then la_qgesvj will compute them. so, in that case,
           ! one should use la_qgesvj instead of la_qgejsv.
           big1 = sqrt(big)
           temp1 = sqrt(big/real(n,KIND=qp))
           call la_qlascl('G',0,0,aapp,temp1,n,1,sva,n,ierr)
           if (aaqq > (aapp*sfmin)) then
               aaqq = (aaqq/aapp)*temp1
           else
               aaqq = (aaqq*temp1)/aapp
           end if
           temp1 = temp1*scalem
           call la_qlascl('G',0,0,aapp,temp1,m,n,a,lda,ierr)
           ! to undo scaling at the end of this procedure, multiply the
           ! computed singular values with uscal2 / uscal1.
           uscal1 = temp1
           uscal2 = aapp
           if (l2kill) then
              ! l2kill enforces computation of nonzero singular values in
              ! the restricted range of condition number of the initial a,
              ! sigma_max(a) / sigma_min(a) approx. sqrt(big)/sqrt(sfmin).
              xsc = sqrt(sfmin)
           else
              xsc = small
              ! now, if the condition number of a is too big,
              ! sigma_max(a) / sigma_min(a) > sqrt(big/n) * epsln / sfmin,
              ! as a precaution measure, the full svd is computed using la_qgesvj
              ! with accumulated jacobi rotations. this provides numerically
              ! more robust computation, at the cost of slightly increased run
              ! time. depending on the concrete implementation of blas and lapack
              ! (i.e. how they behave in presence of extreme ill-conditioning) the
              ! implementor may decide to remove this switch.
              if ((aaqq < sqrt(sfmin)) .and. lsvec .and. rsvec) then
                 jracc = .true.
              end if
           end if
           if (aaqq < xsc) then
              do p = 1,n
                 if (sva(p) < xsc) then
                    call la_qlaset('A',m,1,zero,zero,a(1,p),lda)
                    sva(p) = zero
                 end if
              end do
           end if
           ! preconditioning using qr factorization with pivoting
           if (rowpiv) then
              ! optional row permutation (bjoerck row pivoting):
              ! a result by cox and higham shows that the bjoerck's
              ! row pivoting combined with standard column pivoting
              ! has similar effect as powell-reid complete pivoting.
              ! the ell-infinity norms of a are made nonincreasing.
              do p = 1,m - 1
                 q = la_iqamax(m - p + 1,work(m + n + p),1) + p - 1
                 iwork(2*n + p) = q
                 if (p /= q) then
                    temp1 = work(m + n + p)
                    work(m + n + p) = work(m + n + q)
                    work(m + n + q) = temp1
                 end if
              end do
              call la_qlaswp(n,a,lda,1,m - 1,iwork(2*n + 1),1)
           end if
           ! end of the preparation phase (scaling, optional sorting and
           ! transposing, optional flushing of small columns).
           ! preconditioning
           ! if the full svd is needed, the right singular vectors are computed
           ! from a matrix equation, and for that we need theoretical analysis
           ! of the businger-golub pivoting. so we use la_qgeqp3 as the first rr qrf.
           ! in all other cases the first rr qrf can be chosen by other criteria
           ! (eg speed by replacing global with restricted window pivoting, such
           ! as in sgeqpx from toms # 782). good results will be obtained using
           ! sgeqpx with properly (!) chosen numerical parameters.
           ! any improvement of la_qgeqp3 improves overall performance of la_qgejsv.
           ! a * p1 = q1 * [ r1^t 0]^t:
           do p = 1,n
              ! All Columns Are Free Columns
              iwork(p) = 0
           end do
           call la_qgeqp3(m,n,a,lda,iwork,work,work(n + 1),lwork - n,ierr)
           ! the upper triangular matrix r1 from the first qrf is inspected for
           ! rank deficiency and possibilities for deflation, or possible
           ! ill-conditioning. depending on the user specified flag l2rank,
           ! the procedure explores possibilities to reduce the numerical
           ! rank by inspecting the computed upper triangular factor. if
           ! l2rank or l2aber are up, then la_qgejsv will compute the svd of
           ! a + da, where ||da|| <= f(m,n)*epsln.
           nr = 1
           if (l2aber) then
              ! standard absolute error bound suffices. all sigma_i with
              ! sigma_i < n*epsln*||a|| are flushed to zero. this is an
              ! aggressive enforcement of lower numerical rank by introducing a
              ! backward error of the order of n*epsln*||a||.
              temp1 = sqrt(real(n,KIND=qp))*epsln
              do p = 2,n
                 if (abs(a(p,p)) >= (temp1*abs(a(1,1)))) then
                    nr = nr + 1
                 else
                    go to 3002
                 end if
              end do
              3002 continue
           else if (l2rank) then
              ! .. similarly as above, only slightly more gentle (less aggressive).
              ! sudden drop on the diagonal of r1 is used as the criterion for
              ! close-to-rank-deficient.
              temp1 = sqrt(sfmin)
              do p = 2,n
                 if ((abs(a(p,p)) < (epsln*abs(a(p - 1,p - 1)))) .or. (abs(a(p,p)) < small) .or. ( &
                           l2kill .and. (abs(a(p,p)) < temp1))) go to 3402
                 nr = nr + 1
              end do
              3402 continue
           else
              ! the goal is high relative accuracy. however, if the matrix
              ! has high scaled condition number the relative accuracy is in
              ! general not feasible. later on, a condition number estimator
              ! will be deployed to estimate the scaled condition number.
              ! here we just remove the underflowed part of the triangular
              ! factor. this prevents the situation in which the code is
              ! working hard to get the accuracy not warranted by the data.
              temp1 = sqrt(sfmin)
              do p = 2,n
                 if ((abs(a(p,p)) < small) .or. (l2kill .and. (abs(a(p,p)) < temp1))) go to &
                           3302
                 nr = nr + 1
              end do
              3302 continue
           end if
           almort = .false.
           if (nr == n) then
              maxprj = one
              do p = 2,n
                 temp1 = abs(a(p,p))/sva(iwork(p))
                 maxprj = min(maxprj,temp1)
              end do
              if (maxprj**2 >= one - real(n,KIND=qp)*epsln) almort = .true.
           end if
           sconda = -one
           condr1 = -one
           condr2 = -one
           if (errest) then
              if (n == nr) then
                 if (rsvec) then
                    ! V Is Available As Workspace
                    call la_qlacpy('U',n,n,a,lda,v,ldv)
                    do p = 1,n
                       temp1 = sva(iwork(p))
                       call la_qscal(p,one/temp1,v(1,p),1)
                    end do
                    call la_qpocon('U',n,v,ldv,one,temp1,work(n + 1),iwork(2*n + m + 1), &
                              ierr)
                 else if (lsvec) then
                    ! U Is Available As Workspace
                    call la_qlacpy('U',n,n,a,lda,u,ldu)
                    do p = 1,n
                       temp1 = sva(iwork(p))
                       call la_qscal(p,one/temp1,u(1,p),1)
                    end do
                    call la_qpocon('U',n,u,ldu,one,temp1,work(n + 1),iwork(2*n + m + 1), &
                              ierr)
                 else
                    call la_qlacpy('U',n,n,a,lda,work(n + 1),n)
                    do p = 1,n
                       temp1 = sva(iwork(p))
                       call la_qscal(p,one/temp1,work(n + (p - 1)*n + 1),1)
                    end do
                 ! The Columns Of R Are Scaled To Have Unit Euclidean Lengths
                    call la_qpocon('U',n,work(n + 1),n,one,temp1,work(n + n*n + 1),iwork(2*n + &
                              m + 1),ierr)
                 end if
                 sconda = one/sqrt(temp1)
                 ! sconda is an estimate of sqrt(||(r^t * r)^(-1)||_1).
                 ! n^(-1/4) * sconda <= ||r^(-1)||_2 <= n^(1/4) * sconda
              else
                 sconda = -one
              end if
           end if
           l2pert = l2pert .and. (abs(a(1,1)/a(nr,nr)) > sqrt(big1))
           ! if there is no violent scaling, artificial perturbation is not needed.
           ! phase 3:
           if (.not. (rsvec .or. lsvec)) then
               ! singular values only
               ! .. transpose a(1:nr,1:n)
              do p = 1,min(n - 1,nr)
                 call la_qcopy(n - p,a(p,p + 1),lda,a(p + 1,p),1)
              end do
              ! the following two do-loops introduce small relative perturbation
              ! into the strict upper triangle of the lower triangular matrix.
              ! small entries below the main diagonal are also changed.
              ! this modification is useful if the computing environment does not
              ! provide/allow flush to zero underflow, for it prevents many
              ! annoying denormalized numbers in case of strongly scaled matrices.
              ! the perturbation is structured so that it does not introduce any
              ! new perturbation of the singular values, and it does not destroy
              ! the job done by the preconditioner.
              ! the licence for this perturbation is in the variable l2pert, which
              ! should be .false. if flush to zero underflow is active.
              if (.not. almort) then
                 if (l2pert) then
                    ! xsc = sqrt(small)
                    xsc = epsln/real(n,KIND=qp)
                    do q = 1,nr
                       temp1 = xsc*abs(a(q,q))
                       do p = 1,n
                          if (((p > q) .and. (abs(a(p,q)) <= temp1)) .or. (p < q)) a(p,q) = sign( &
                                    temp1,a(p,q))
                       end do
                    end do
                 else
                    call la_qlaset('U',nr - 1,nr - 1,zero,zero,a(1,2),lda)
                 end if
                  ! Second Preconditioning Using The Qr Factorization
                 call la_qgeqrf(n,nr,a,lda,work,work(n + 1),lwork - n,ierr)
                 ! And Transpose Upper To Lower Triangular
                 do p = 1,nr - 1
                    call la_qcopy(nr - p,a(p,p + 1),lda,a(p + 1,p),1)
                 end do
              end if
                 ! row-cyclic jacobi svd algorithm with column pivoting
                 ! .. again some perturbation (a "background noise") is added
                 ! to drown denormals
                 if (l2pert) then
                    ! xsc = sqrt(small)
                    xsc = epsln/real(n,KIND=qp)
                    do q = 1,nr
                       temp1 = xsc*abs(a(q,q))
                       do p = 1,nr
                          if (((p > q) .and. (abs(a(p,q)) <= temp1)) .or. (p < q)) a(p,q) = sign( &
                                    temp1,a(p,q))
                       end do
                    end do
                 else
                    call la_qlaset('U',nr - 1,nr - 1,zero,zero,a(1,2),lda)
                 end if
                 ! .. and one-sided jacobi rotations are started on a lower
                 ! triangular matrix (plus perturbation which is ignored in
                 ! the part which destroys triangular form (confusing?!))
                 call la_qgesvj('L','NOU','NOV',nr,nr,a,lda,sva,n,v,ldv,work, &
                           lwork,info)
                 scalem = work(1)
                 numrank = nint(work(2),KIND=ilp)
           else if (rsvec .and. (.not. lsvec)) then
              ! -> singular values and right singular vectors <-
              if (almort) then
                 ! In This Case Nr Equals N
                 do p = 1,nr
                    call la_qcopy(n - p + 1,a(p,p),lda,v(p,p),1)
                 end do
                 call la_qlaset('UPPER',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 call la_qgesvj('L','U','N',n,nr,v,ldv,sva,nr,a,lda,work,lwork,info)

                 scalem = work(1)
                 numrank = nint(work(2),KIND=ilp)
              else
              ! .. two more qr factorizations ( one qrf is not enough, two require
              ! accumulated product of jacobi rotations, three are perfect )
                 call la_qlaset('LOWER',nr - 1,nr - 1,zero,zero,a(2,1),lda)
                 call la_qgelqf(nr,n,a,lda,work,work(n + 1),lwork - n,ierr)
                 call la_qlacpy('LOWER',nr,nr,a,lda,v,ldv)
                 call la_qlaset('UPPER',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 call la_qgeqrf(nr,nr,v,ldv,work(n + 1),work(2*n + 1),lwork - 2*n,ierr)

                 do p = 1,nr
                    call la_qcopy(nr - p + 1,v(p,p),ldv,v(p,p),1)
                 end do
                 call la_qlaset('UPPER',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 call la_qgesvj('LOWER','U','N',nr,nr,v,ldv,sva,nr,u,ldu,work(n + 1), &
                           lwork,info)
                 scalem = work(n + 1)
                 numrank = nint(work(n + 2),KIND=ilp)
                 if (nr < n) then
                    call la_qlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                    call la_qlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                    call la_qlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                 end if
              call la_qormlq('LEFT','TRANSPOSE',n,n,nr,a,lda,work,v,ldv,work(n + 1), &
                        lwork - n,ierr)
              end if
              do p = 1,n
                 call la_qcopy(n,v(p,1),ldv,a(iwork(p),1),lda)
              end do
              call la_qlacpy('ALL',n,n,a,lda,v,ldv)
              if (transp) then
                 call la_qlacpy('ALL',n,n,v,ldv,u,ldu)
              end if
           else if (lsvec .and. (.not. rsvec)) then
              ! Singular Values And Left Singular Vectors
              ! Second Preconditioning Step To Avoid Need To Accumulate
              ! jacobi rotations in the jacobi iterations.
              do p = 1,nr
                 call la_qcopy(n - p + 1,a(p,p),lda,u(p,p),1)
              end do
              call la_qlaset('UPPER',nr - 1,nr - 1,zero,zero,u(1,2),ldu)
              call la_qgeqrf(n,nr,u,ldu,work(n + 1),work(2*n + 1),lwork - 2*n,ierr)
              do p = 1,nr - 1
                 call la_qcopy(nr - p,u(p,p + 1),ldu,u(p + 1,p),1)
              end do
              call la_qlaset('UPPER',nr - 1,nr - 1,zero,zero,u(1,2),ldu)
              call la_qgesvj('LOWER','U','N',nr,nr,u,ldu,sva,nr,a,lda,work(n + 1), &
                        lwork - n,info)
              scalem = work(n + 1)
              numrank = nint(work(n + 2),KIND=ilp)
              if (nr < m) then
                 call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                 if (nr < n1) then
                    call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                    call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                 end if
              end if
              call la_qormqr('LEFT','NO TR',m,n1,n,a,lda,work,u,ldu,work(n + 1), &
                        lwork - n,ierr)
              if (rowpiv) call la_qlaswp(n1,u,ldu,1,m - 1,iwork(2*n + 1),-1)
              do p = 1,n1
                 xsc = one/la_qnrm2(m,u(1,p),1)
                 call la_qscal(m,xsc,u(1,p),1)
              end do
              if (transp) then
                 call la_qlacpy('ALL',n,n,u,ldu,v,ldv)
              end if
           else
              ! Full Svd
              if (.not. jracc) then
              if (.not. almort) then
                 ! second preconditioning step (qrf [with pivoting])
                 ! note that the composition of transpose, qrf and transpose is
                 ! equivalent to an lqf call. since in many libraries the qrf
                 ! seems to be better optimized than the lqf, we do explicit
                 ! transpose and use the qrf. this is subject to changes in an
                 ! optimized implementation of la_qgejsv.
                 do p = 1,nr
                    call la_qcopy(n - p + 1,a(p,p),lda,v(p,p),1)
                 end do
                 ! The Following Two Loops Perturb Small Entries To Avoid
                 ! denormals in the second qr factorization, where they are
                 ! as good as zeros. this is done to avoid painfully slow
                 ! computation with denormals. the relative size of the perturbation
                 ! is a parameter that can be changed by the implementer.
                 ! this perturbation device will be obsolete on machines with
                 ! properly implemented arithmetic.
                 ! to switch it off, set l2pert=.false. to remove it from  the
                 ! code, remove the action under l2pert=.true., leave the else part.
                 ! the following two loops should be blocked and fused with the
                 ! transposed copy above.
                 if (l2pert) then
                    xsc = sqrt(small)
                    do q = 1,nr
                       temp1 = xsc*abs(v(q,q))
                       do p = 1,n
                          if ((p > q) .and. (abs(v(p,q)) <= temp1) .or. (p < q)) v(p,q) = &
                                    sign(temp1,v(p,q))
                          if (p < q) v(p,q) = -v(p,q)
                       end do
                    end do
                 else
                    call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 end if
                 ! estimate the row scaled condition number of r1
                 ! (if r1 is rectangular, n > nr, then the condition number
                 ! of the leading nr x nr submatrix is estimated.)
                 call la_qlacpy('L',nr,nr,v,ldv,work(2*n + 1),nr)
                 do p = 1,nr
                    temp1 = la_qnrm2(nr - p + 1,work(2*n + (p - 1)*nr + p),1)
                    call la_qscal(nr - p + 1,one/temp1,work(2*n + (p - 1)*nr + p),1)
                 end do
                 call la_qpocon('LOWER',nr,work(2*n + 1),nr,one,temp1,work(2*n + nr*nr + 1),iwork(m + &
                           2*n + 1),ierr)
                 condr1 = one/sqrt(temp1)
                 ! Here Need A Second Opinion On The Condition Number
                 ! Then Assume Worst Case Scenario
                 ! r1 is ok for inverse <=> condr1 < real(n,KIND=qp)
                 ! more conservative    <=> condr1 < sqrt(real(n,KIND=qp))
                 cond_ok = sqrt(real(nr,KIND=qp))
      ! [tp]       cond_ok is a tuning parameter.
                 if (condr1 < cond_ok) then
                    ! .. the second qrf without pivoting. note: in an optimized
                    ! implementation, this qrf should be implemented as the qrf
                    ! of a lower triangular matrix.
                    ! r1^t = q2 * r2
                    call la_qgeqrf(n,nr,v,ldv,work(n + 1),work(2*n + 1),lwork - 2*n,ierr)

                    if (l2pert) then
                       xsc = sqrt(small)/epsln
                       do p = 2,nr
                          do q = 1,p - 1
                             temp1 = xsc*min(abs(v(p,p)),abs(v(q,q)))
                             if (abs(v(q,p)) <= temp1) v(q,p) = sign(temp1,v(q,p))
                          end do
                       end do
                    end if
                    if (nr /= n) call la_qlacpy('A',n,nr,v,ldv,work(2*n + 1),n)
                    ! .. save ...
                 ! This Transposed Copy Should Be Better Than Naive
                    do p = 1,nr - 1
                       call la_qcopy(nr - p,v(p,p + 1),ldv,v(p + 1,p),1)
                    end do
                    condr2 = condr1
                 else
                    ! .. ill-conditioned case: second qrf with pivoting
                    ! note that windowed pivoting would be equally good
                    ! numerically, and more run-time efficient. so, in
                    ! an optimal implementation, the next call to la_qgeqp3
                    ! should be replaced with eg. call sgeqpx (acm toms #782)
                    ! with properly (carefully) chosen parameters.
                    ! r1^t * p2 = q2 * r2
                    do p = 1,nr
                       iwork(n + p) = 0
                    end do
                    call la_qgeqp3(n,nr,v,ldv,iwork(n + 1),work(n + 1),work(2*n + 1),lwork - &
                              2*n,ierr)
      ! *               call la_qgeqrf( n, nr, v, ldv, work(n+1), work(2*n+1),
      ! *     $              lwork-2*n, ierr )
                    if (l2pert) then
                       xsc = sqrt(small)
                       do p = 2,nr
                          do q = 1,p - 1
                             temp1 = xsc*min(abs(v(p,p)),abs(v(q,q)))
                             if (abs(v(q,p)) <= temp1) v(q,p) = sign(temp1,v(q,p))
                          end do
                       end do
                    end if
                    call la_qlacpy('A',n,nr,v,ldv,work(2*n + 1),n)
                    if (l2pert) then
                       xsc = sqrt(small)
                       do p = 2,nr
                          do q = 1,p - 1
                             temp1 = xsc*min(abs(v(p,p)),abs(v(q,q)))
                             v(p,q) = -sign(temp1,v(q,p))
                          end do
                       end do
                    else
                       call la_qlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)
                    end if
                    ! now, compute r2 = l3 * q3, the lq factorization.
                    call la_qgelqf(nr,nr,v,ldv,work(2*n + n*nr + 1),work(2*n + n*nr + nr + 1), &
                              lwork - 2*n - n*nr - nr,ierr)
                    ! And Estimate The Condition Number
                    call la_qlacpy('L',nr,nr,v,ldv,work(2*n + n*nr + nr + 1),nr)
                    do p = 1,nr
                       temp1 = la_qnrm2(p,work(2*n + n*nr + nr + p),nr)
                       call la_qscal(p,one/temp1,work(2*n + n*nr + nr + p),nr)
                    end do
                    call la_qpocon('L',nr,work(2*n + n*nr + nr + 1),nr,one,temp1,work(2*n + n*nr + nr + &
                              nr*nr + 1),iwork(m + 2*n + 1),ierr)
                    condr2 = one/sqrt(temp1)
                    if (condr2 >= cond_ok) then
                       ! Save The Householder Vectors Used For Q3
                       ! (this overwrites the copy of r2, as it will not be
                       ! needed in this branch, but it does not overwritte the
                       ! huseholder vectors of q2.).
                       call la_qlacpy('U',nr,nr,v,ldv,work(2*n + 1),n)
                       ! And The Rest Of The Information On Q3 Is In
                       ! work(2*n+n*nr+1:2*n+n*nr+n)
                    end if
                 end if
                 if (l2pert) then
                    xsc = sqrt(small)
                    do q = 2,nr
                       temp1 = xsc*v(q,q)
                       do p = 1,q - 1
                          ! v(p,q) = - sign( temp1, v(q,p) )
                          v(p,q) = -sign(temp1,v(p,q))
                       end do
                    end do
                 else
                    call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 end if
              ! second preconditioning finished; continue with jacobi svd
              ! the input matrix is lower trinagular.
              ! recover the right singular vectors as solution of a well
              ! conditioned triangular matrix equation.
                 if (condr1 < cond_ok) then
                    call la_qgesvj('L','U','N',nr,nr,v,ldv,sva,nr,u,ldu,work(2*n + n*nr + nr + 1), &
                              lwork - 2*n - n*nr - nr,info)
                    scalem = work(2*n + n*nr + nr + 1)
                    numrank = nint(work(2*n + n*nr + nr + 2),KIND=ilp)
                    do p = 1,nr
                       call la_qcopy(nr,v(1,p),1,u(1,p),1)
                       call la_qscal(nr,sva(p),v(1,p),1)
                    end do
              ! Pick The Right Matrix Equation And Solve It
                    if (nr == n) then
       ! :))             .. best case, r1 is inverted. the solution of this matrix
                       ! equation is q2*v2 = the product of the jacobi rotations
                       ! used in la_qgesvj, premultiplied with the orthogonal matrix
                       ! from the second qr factorization.
                       call la_qtrsm('L','U','N','N',nr,nr,one,a,lda,v,ldv)
                    else
                       ! .. r1 is well conditioned, but non-square. transpose(r2)
                       ! is inverted to get the product of the jacobi rotations
                       ! used in la_qgesvj. the q-factor from the second qr
                       ! factorization is then built in explicitly.
                       call la_qtrsm('L','U','T','N',nr,nr,one,work(2*n + 1),n,v,ldv)
                       if (nr < n) then
                         call la_qlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                         call la_qlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                         call la_qlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       end if
                       call la_qormqr('L','N',n,n,nr,work(2*n + 1),n,work(n + 1),v,ldv,work(2*n + &
                                 n*nr + nr + 1),lwork - 2*n - n*nr - nr,ierr)
                    end if
                 else if (condr2 < cond_ok) then
       ! :)           .. the input matrix a is very likely a relative of
                    ! the kahan matrix :)
                    ! the matrix r2 is inverted. the solution of the matrix equation
                    ! is q3^t*v3 = the product of the jacobi rotations (appplied to
                    ! the lower triangular l3 from the lq factorization of
                    ! r2=l3*q3), pre-multiplied with the transposed q3.
                    call la_qgesvj('L','U','N',nr,nr,v,ldv,sva,nr,u,ldu,work(2*n + &
                              n*nr + nr + 1),lwork - 2*n - n*nr - nr,info)
                    scalem = work(2*n + n*nr + nr + 1)
                    numrank = nint(work(2*n + n*nr + nr + 2),KIND=ilp)
                    do p = 1,nr
                       call la_qcopy(nr,v(1,p),1,u(1,p),1)
                       call la_qscal(nr,sva(p),u(1,p),1)
                    end do
                    call la_qtrsm('L','U','N','N',nr,nr,one,work(2*n + 1),n,u,ldu)
                    ! Apply The Permutation From The Second Qr Factorization
                    do q = 1,nr
                       do p = 1,nr
                          work(2*n + n*nr + nr + iwork(n + p)) = u(p,q)
                       end do
                       do p = 1,nr
                          u(p,q) = work(2*n + n*nr + nr + p)
                       end do
                    end do
                    if (nr < n) then
                       call la_qlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_qlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_qlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                    end if
                    call la_qormqr('L','N',n,n,nr,work(2*n + 1),n,work(n + 1),v,ldv,work(2*n + &
                              n*nr + nr + 1),lwork - 2*n - n*nr - nr,ierr)
                 else
                    ! last line of defense.
       ! #:(          this is a rather pathological case: no scaled condition
                    ! improvement after two pivoted qr factorizations. other
                    ! possibility is that the rank revealing qr factorization
                    ! or the condition estimator has failed, or the cond_ok
                    ! is set very close to one (which is unnecessary). normally,
                    ! this branch should never be executed, but in rare cases of
                    ! failure of the rrqr or condition estimator, the last line of
                    ! defense ensures that la_qgejsv completes the task.
                    ! compute the full svd of l3 using la_qgesvj with explicit
                    ! accumulation of jacobi rotations.
                    call la_qgesvj('L','U','V',nr,nr,v,ldv,sva,nr,u,ldu,work(2*n + &
                              n*nr + nr + 1),lwork - 2*n - n*nr - nr,info)
                    scalem = work(2*n + n*nr + nr + 1)
                    numrank = nint(work(2*n + n*nr + nr + 2),KIND=ilp)
                    if (nr < n) then
                       call la_qlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_qlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_qlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                    end if
                    call la_qormqr('L','N',n,n,nr,work(2*n + 1),n,work(n + 1),v,ldv,work(2*n + &
                              n*nr + nr + 1),lwork - 2*n - n*nr - nr,ierr)
                    call la_qormlq('L','T',nr,nr,nr,work(2*n + 1),n,work(2*n + n*nr + 1),u, &
                              ldu,work(2*n + n*nr + nr + 1),lwork - 2*n - n*nr - nr,ierr)
                    do q = 1,nr
                       do p = 1,nr
                          work(2*n + n*nr + nr + iwork(n + p)) = u(p,q)
                       end do
                       do p = 1,nr
                          u(p,q) = work(2*n + n*nr + nr + p)
                       end do
                    end do
                 end if
                 ! permute the rows of v using the (column) permutation from the
                 ! first qrf. also, scale the columns to make them unit in
                 ! euclidean norm. this applies to all cases.
                 temp1 = sqrt(real(n,KIND=qp))*epsln
                 do q = 1,n
                    do p = 1,n
                       work(2*n + n*nr + nr + iwork(p)) = v(p,q)
                    end do
                    do p = 1,n
                       v(p,q) = work(2*n + n*nr + nr + p)
                    end do
                    xsc = one/la_qnrm2(n,v(1,q),1)
                    if ((xsc < (one - temp1)) .or. (xsc > (one + temp1))) call la_qscal(n,xsc, &
                              v(1,q),1)
                 end do
                 ! at this moment, v contains the right singular vectors of a.
                 ! next, assemble the left singular vector matrix u (m x n).
                 if (nr < m) then
                    call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                    if (nr < n1) then
                       call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                       call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                    end if
                 end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! matrix u. this applies to all cases.
                 call la_qormqr('LEFT','NO_TR',m,n1,n,a,lda,work,u,ldu,work(n + 1), &
                           lwork - n,ierr)
                 ! the columns of u are normalized. the cost is o(m*n) flops.
                 temp1 = sqrt(real(m,KIND=qp))*epsln
                 do p = 1,nr
                    xsc = one/la_qnrm2(m,u(1,p),1)
                    if ((xsc < (one - temp1)) .or. (xsc > (one + temp1))) call la_qscal(m,xsc, &
                              u(1,p),1)
                 end do
                 ! if the initial qrf is computed with row pivoting, the left
                 ! singular vectors must be adjusted.
                 if (rowpiv) call la_qlaswp(n1,u,ldu,1,m - 1,iwork(2*n + 1),-1)
              else
              ! The Initial Matrix A Has Almost Orthogonal Columns And
              ! the second qrf is not needed
                 call la_qlacpy('UPPER',n,n,a,lda,work(n + 1),n)
                 if (l2pert) then
                    xsc = sqrt(small)
                    do p = 2,n
                       temp1 = xsc*work(n + (p - 1)*n + p)
                       do q = 1,p - 1
                          work(n + (q - 1)*n + p) = -sign(temp1,work(n + (p - 1)*n + q))
                       end do
                    end do
                 else
                    call la_qlaset('LOWER',n - 1,n - 1,zero,zero,work(n + 2),n)
                 end if
                 call la_qgesvj('UPPER','U','N',n,n,work(n + 1),n,sva,n,u,ldu,work(n + &
                           n*n + 1),lwork - n - n*n,info)
                 scalem = work(n + n*n + 1)
                 numrank = nint(work(n + n*n + 2),KIND=ilp)
                 do p = 1,n
                    call la_qcopy(n,work(n + (p - 1)*n + 1),1,u(1,p),1)
                    call la_qscal(n,sva(p),work(n + (p - 1)*n + 1),1)
                 end do
                 call la_qtrsm('LEFT','UPPER','NOTRANS','NO UD',n,n,one,a,lda,work(n + &
                           1),n)
                 do p = 1,n
                    call la_qcopy(n,work(n + p),n,v(iwork(p),1),ldv)
                 end do
                 temp1 = sqrt(real(n,KIND=qp))*epsln
                 do p = 1,n
                    xsc = one/la_qnrm2(n,v(1,p),1)
                    if ((xsc < (one - temp1)) .or. (xsc > (one + temp1))) call la_qscal(n,xsc, &
                              v(1,p),1)
                 end do
                 ! assemble the left singular vector matrix u (m x n).
                 if (n < m) then
                    call la_qlaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                    if (n < n1) then
                       call la_qlaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                       call la_qlaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                    end if
                 end if
                 call la_qormqr('LEFT','NO TR',m,n1,n,a,lda,work,u,ldu,work(n + 1), &
                           lwork - n,ierr)
                 temp1 = sqrt(real(m,KIND=qp))*epsln
                 do p = 1,n1
                    xsc = one/la_qnrm2(m,u(1,p),1)
                    if ((xsc < (one - temp1)) .or. (xsc > (one + temp1))) call la_qscal(m,xsc, &
                              u(1,p),1)
                 end do
                 if (rowpiv) call la_qlaswp(n1,u,ldu,1,m - 1,iwork(2*n + 1),-1)
              end if
              ! end of the  >> almost orthogonal case <<  in the full svd
              else
              ! this branch deploys a preconditioned jacobi svd with explicitly
              ! accumulated rotations. it is included as optional, mainly for
              ! experimental purposes. it does perform well, and can also be used.
              ! in this implementation, this branch will be automatically activated
              ! if the  condition number sigma_max(a) / sigma_min(a) is predicted
              ! to be greater than the overflow threshold. this is because the
              ! a posteriori computation of the singular vectors assumes robust
              ! implementation of blas and some lapack procedures, capable of working
              ! in presence of extreme values. since that is not always the case, ...
              do p = 1,nr
                 call la_qcopy(n - p + 1,a(p,p),lda,v(p,p),1)
              end do
              if (l2pert) then
                 xsc = sqrt(small/epsln)
                 do q = 1,nr
                    temp1 = xsc*abs(v(q,q))
                    do p = 1,n
                       if ((p > q) .and. (abs(v(p,q)) <= temp1) .or. (p < q)) v(p,q) = sign( &
                                  temp1,v(p,q))
                       if (p < q) v(p,q) = -v(p,q)
                    end do
                 end do
              else
                 call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
              end if
              call la_qgeqrf(n,nr,v,ldv,work(n + 1),work(2*n + 1),lwork - 2*n,ierr)
              call la_qlacpy('L',n,nr,v,ldv,work(2*n + 1),n)
              do p = 1,nr
                 call la_qcopy(nr - p + 1,v(p,p),ldv,u(p,p),1)
              end do
              if (l2pert) then
                 xsc = sqrt(small/epsln)
                 do q = 2,nr
                    do p = 1,q - 1
                       temp1 = xsc*min(abs(u(p,p)),abs(u(q,q)))
                       u(p,q) = -sign(temp1,u(q,p))
                    end do
                 end do
              else
                 call la_qlaset('U',nr - 1,nr - 1,zero,zero,u(1,2),ldu)
              end if
              call la_qgesvj('G','U','V',nr,nr,u,ldu,sva,n,v,ldv,work(2*n + n*nr + 1), &
                        lwork - 2*n - n*nr,info)
              scalem = work(2*n + n*nr + 1)
              numrank = nint(work(2*n + n*nr + 2),KIND=ilp)
              if (nr < n) then
                 call la_qlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                 call la_qlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                 call la_qlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
              end if
              call la_qormqr('L','N',n,n,nr,work(2*n + 1),n,work(n + 1),v,ldv,work(2*n + n*nr + nr + 1) &
                        ,lwork - 2*n - n*nr - nr,ierr)
                 ! permute the rows of v using the (column) permutation from the
                 ! first qrf. also, scale the columns to make them unit in
                 ! euclidean norm. this applies to all cases.
                 temp1 = sqrt(real(n,KIND=qp))*epsln
                 do q = 1,n
                    do p = 1,n
                       work(2*n + n*nr + nr + iwork(p)) = v(p,q)
                    end do
                    do p = 1,n
                       v(p,q) = work(2*n + n*nr + nr + p)
                    end do
                    xsc = one/la_qnrm2(n,v(1,q),1)
                    if ((xsc < (one - temp1)) .or. (xsc > (one + temp1))) call la_qscal(n,xsc, &
                              v(1,q),1)
                 end do
                 ! at this moment, v contains the right singular vectors of a.
                 ! next, assemble the left singular vector matrix u (m x n).
              if (nr < m) then
                 call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                 if (nr < n1) then
                    call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                    call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                 end if
              end if
              call la_qormqr('LEFT','NO TR',m,n1,n,a,lda,work,u,ldu,work(n + 1), &
                        lwork - n,ierr)
                 if (rowpiv) call la_qlaswp(n1,u,ldu,1,m - 1,iwork(2*n + 1),-1)
              end if
              if (transp) then
                 ! .. swap u and v because the procedure worked on a^t
                 do p = 1,n
                    call la_qswap(n,u(1,p),1,v(1,p),1)
                 end do
              end if
           end if
           ! end of the full svd
           ! undo scaling, if necessary (and possible)
           if (uscal2 <= (big/sva(1))*uscal1) then
              call la_qlascl('G',0,0,uscal1,uscal2,nr,1,sva,n,ierr)
              uscal1 = one
              uscal2 = one
           end if
           if (nr < n) then
              do p = nr + 1,n
                 sva(p) = zero
              end do
           end if
           work(1) = uscal2*scalem
           work(2) = uscal1
           if (errest) work(3) = sconda
           if (lsvec .and. rsvec) then
              work(4) = condr1
              work(5) = condr2
           end if
           if (l2tran) then
              work(6) = entra
              work(7) = entrat
           end if
           iwork(1) = nr
           iwork(2) = numrank
           iwork(3) = warning
           return
     end subroutine la_qgejsv

     !> DGELS: solves overdetermined or underdetermined real linear systems
     !> involving an M-by-N matrix A, or its transpose, using a QR or LQ
     !> factorization of A.  It is assumed that A has full rank.
     !> The following options are provided:
     !> 1. If TRANS = 'N' and m >= n:  find the least squares solution of
     !> an overdetermined system, i.e., solve the least squares problem
     !> minimize || B - A*X ||.
     !> 2. If TRANS = 'N' and m < n:  find the minimum norm solution of
     !> an underdetermined system A * X = B.
     !> 3. If TRANS = 'T' and m >= n:  find the minimum norm solution of
     !> an underdetermined system A**T * X = B.
     !> 4. If TRANS = 'T' and m < n:  find the least squares solution of
     !> an overdetermined system, i.e., solve the least squares problem
     !> minimize || B - A**T * X ||.
     !> Several right hand side vectors b and solution vectors x can be
     !> handled in a single call; they are stored as the columns of the
     !> M-by-NRHS right hand side matrix B and the N-by-NRHS solution
     !> matrix X.

     subroutine la_qgels(trans,m,n,nrhs,a,lda,b,ldb,work,lwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,lwork,m,n,nrhs
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,tpsd
           integer(ilp) :: brow,i,iascl,ibscl,j,mn,nb,scllen,wsize
           real(qp) :: anrm,bignum,bnrm,smlnum
           ! Local Arrays
           real(qp) :: rwork(1)
           ! Intrinsic Functions
           intrinsic :: real,max,min
           ! Executable Statements
           ! test the input arguments.
           info = 0
           mn = min(m,n)
           lquery = (lwork == -1)
           if (.not. (la_lsame(trans,'N') .or. la_lsame(trans,'T'))) then
              info = -1
           else if (m < 0) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (nrhs < 0) then
              info = -4
           else if (lda < max(1,m)) then
              info = -6
           else if (ldb < max(1,m,n)) then
              info = -8
           else if (lwork < max(1,mn + max(mn,nrhs)) .and. .not. lquery) then
              info = -10
           end if
           ! figure out optimal block size
           if (info == 0 .or. info == -10) then
              tpsd = .true.
              if (la_lsame(trans,'N')) tpsd = .false.
              if (m >= n) then
                 nb = la_ilaenv(1,'DGEQRF',' ',m,n,-1,-1)
                 if (tpsd) then
                    nb = max(nb,la_ilaenv(1,'DORMQR','LN',m,nrhs,n,-1))
                 else
                    nb = max(nb,la_ilaenv(1,'DORMQR','LT',m,nrhs,n,-1))
                 end if
              else
                 nb = la_ilaenv(1,'DGELQF',' ',m,n,-1,-1)
                 if (tpsd) then
                    nb = max(nb,la_ilaenv(1,'DORMLQ','LT',n,nrhs,m,-1))
                 else
                    nb = max(nb,la_ilaenv(1,'DORMLQ','LN',n,nrhs,m,-1))
                 end if
              end if
              wsize = max(1,mn + max(mn,nrhs)*nb)
              work(1) = real(wsize,KIND=qp)
           end if
           if (info /= 0) then
              call la_xerbla('DGELS ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (min(m,n,nrhs) == 0) then
              call la_qlaset('FULL',max(m,n),nrhs,zero,zero,b,ldb)
              return
           end if
           ! get machine parameters
           smlnum = la_qlamch('S')/la_qlamch('P')
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           ! scale a, b if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',m,n,a,lda,rwork)
           iascl = 0
           if (anrm > zero .and. anrm < smlnum) then
              ! scale matrix norm up to smlnum
              call la_qlascl('G',0,0,anrm,smlnum,m,n,a,lda,info)
              iascl = 1
           else if (anrm > bignum) then
              ! scale matrix norm down to bignum
              call la_qlascl('G',0,0,anrm,bignum,m,n,a,lda,info)
              iascl = 2
           else if (anrm == zero) then
              ! matrix all zero. return zero solution.
              call la_qlaset('F',max(m,n),nrhs,zero,zero,b,ldb)
              go to 50
           end if
           brow = m
           if (tpsd) brow = n
           bnrm = la_qlange('M',brow,nrhs,b,ldb,rwork)
           ibscl = 0
           if (bnrm > zero .and. bnrm < smlnum) then
              ! scale matrix norm up to smlnum
              call la_qlascl('G',0,0,bnrm,smlnum,brow,nrhs,b,ldb,info)
              ibscl = 1
           else if (bnrm > bignum) then
              ! scale matrix norm down to bignum
              call la_qlascl('G',0,0,bnrm,bignum,brow,nrhs,b,ldb,info)
              ibscl = 2
           end if
           if (m >= n) then
              ! compute qr factorization of a
              call la_qgeqrf(m,n,a,lda,work(1),work(mn + 1),lwork - mn,info)
              ! workspace at least n, optimally n*nb
              if (.not. tpsd) then
                 ! least-squares problem min || a * x - b ||
                 ! b(1:m,1:nrhs) := q**t * b(1:m,1:nrhs)
                 call la_qormqr('LEFT','TRANSPOSE',m,nrhs,n,a,lda,work(1),b,ldb, &
                           work(mn + 1),lwork - mn,info)
                 ! workspace at least nrhs, optimally nrhs*nb
                 ! b(1:n,1:nrhs) := inv(r) * b(1:n,1:nrhs)
                 call la_qtrtrs('UPPER','NO TRANSPOSE','NON-UNIT',n,nrhs,a,lda,b,ldb, &
                           info)
                 if (info > 0) then
                    return
                 end if
                 scllen = n
              else
                 ! underdetermined system of equations a**t * x = b
                 ! b(1:n,1:nrhs) := inv(r**t) * b(1:n,1:nrhs)
                 call la_qtrtrs('UPPER','TRANSPOSE','NON-UNIT',n,nrhs,a,lda,b,ldb, &
                           info)
                 if (info > 0) then
                    return
                 end if
                 ! b(n+1:m,1:nrhs) = zero
                 do j = 1,nrhs
                    do i = n + 1,m
                       b(i,j) = zero
                    end do
                 end do
                 ! b(1:m,1:nrhs) := q(1:n,:) * b(1:n,1:nrhs)
                 call la_qormqr('LEFT','NO TRANSPOSE',m,nrhs,n,a,lda,work(1),b,ldb, &
                            work(mn + 1),lwork - mn,info)
                 ! workspace at least nrhs, optimally nrhs*nb
                 scllen = m
              end if
           else
              ! compute lq factorization of a
              call la_qgelqf(m,n,a,lda,work(1),work(mn + 1),lwork - mn,info)
              ! workspace at least m, optimally m*nb.
              if (.not. tpsd) then
                 ! underdetermined system of equations a * x = b
                 ! b(1:m,1:nrhs) := inv(l) * b(1:m,1:nrhs)
                 call la_qtrtrs('LOWER','NO TRANSPOSE','NON-UNIT',m,nrhs,a,lda,b,ldb, &
                           info)
                 if (info > 0) then
                    return
                 end if
                 ! b(m+1:n,1:nrhs) = 0
                 do j = 1,nrhs
                    do i = m + 1,n
                       b(i,j) = zero
                    end do
                 end do
                 ! b(1:n,1:nrhs) := q(1:n,:)**t * b(1:m,1:nrhs)
                 call la_qormlq('LEFT','TRANSPOSE',n,nrhs,m,a,lda,work(1),b,ldb, &
                           work(mn + 1),lwork - mn,info)
                 ! workspace at least nrhs, optimally nrhs*nb
                 scllen = n
              else
                 ! overdetermined system min || a**t * x - b ||
                 ! b(1:n,1:nrhs) := q * b(1:n,1:nrhs)
                 call la_qormlq('LEFT','NO TRANSPOSE',n,nrhs,m,a,lda,work(1),b,ldb, &
                            work(mn + 1),lwork - mn,info)
                 ! workspace at least nrhs, optimally nrhs*nb
                 ! b(1:m,1:nrhs) := inv(l**t) * b(1:m,1:nrhs)
                 call la_qtrtrs('LOWER','TRANSPOSE','NON-UNIT',m,nrhs,a,lda,b,ldb, &
                           info)
                 if (info > 0) then
                    return
                 end if
                 scllen = m
              end if
           end if
           ! undo scaling
           if (iascl == 1) then
              call la_qlascl('G',0,0,anrm,smlnum,scllen,nrhs,b,ldb,info)
           else if (iascl == 2) then
              call la_qlascl('G',0,0,anrm,bignum,scllen,nrhs,b,ldb,info)
           end if
           if (ibscl == 1) then
              call la_qlascl('G',0,0,smlnum,bnrm,scllen,nrhs,b,ldb,info)
           else if (ibscl == 2) then
              call la_qlascl('G',0,0,bignum,bnrm,scllen,nrhs,b,ldb,info)
           end if
           50 continue
           work(1) = real(wsize,KIND=qp)
           return
     end subroutine la_qgels

     !> DGELSD: computes the minimum-norm solution to a real linear least
     !> squares problem:
     !> minimize 2-norm(| b - A*x |)
     !> using the singular value decomposition (SVD) of A. A is an M-by-N
     !> matrix which may be rank-deficient.
     !> Several right hand side vectors b and solution vectors x can be
     !> handled in a single call; they are stored as the columns of the
     !> M-by-NRHS right hand side matrix B and the N-by-NRHS solution
     !> matrix X.
     !> The problem is solved in three steps:
     !> (1) Reduce the coefficient matrix A to bidiagonal form with
     !> Householder transformations, reducing the original problem
     !> into a "bidiagonal least squares problem" (BLS)
     !> (2) Solve the BLS using a divide and conquer approach.
     !> (3) Apply back all the Householder transformations to solve
     !> the original least squares problem.
     !> The effective rank of A is determined by treating as zero those
     !> singular values which are less than RCOND times the largest singular
     !> value.
     !> The divide and conquer algorithm makes very mild assumptions about
     !> floating point arithmetic. It will work on machines with a guard
     !> digit in add/subtract, or on those binary machines without guard
     !> digits which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or
     !> Cray-2. It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.

     subroutine la_qgelsd(m,n,nrhs,a,lda,b,ldb,s,rcond,rank,work,lwork,iwork, &
               info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info,rank
           integer(ilp),intent(in) :: lda,ldb,lwork,m,n,nrhs
           real(qp),intent(in) :: rcond
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: s(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: iascl,ibscl,ie,il,itau,itaup,itauq,ldwork,liwork,maxmn, &
                     maxwrk,minmn,minwrk,mm,mnthr,nlvl,nwork,smlsiz,wlalsd
           real(qp) :: anrm,bignum,bnrm,eps,sfmin,smlnum
           ! Intrinsic Functions
           intrinsic :: real,int,log,max,min
           ! Executable Statements
           ! test the input arguments.
           info = 0
           minmn = min(m,n)
           maxmn = max(m,n)
           mnthr = la_ilaenv(6,'DGELSD',' ',m,n,nrhs,-1)
           lquery = (lwork == -1)
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           else if (ldb < max(1,maxmn)) then
              info = -7
           end if
           smlsiz = la_ilaenv(9,'DGELSD',' ',0,0,0,0)
           ! compute workspace.
           ! (note: comments in the code beginning "workspace:" describe the
           ! minimal amount of workspace needed at that point in the code,
           ! as well as the preferred amount for good performance.
           ! nb refers to the optimal block size for the immediately
           ! following subroutine, as returned by la_ilaenv.)
           minwrk = 1
           liwork = 1
           minmn = max(1,minmn)
           nlvl = max(int(log(real(minmn,KIND=qp)/real(smlsiz + 1,KIND=qp))/log(two), &
                     KIND=ilp) + 1,0)
           if (info == 0) then
              maxwrk = 0
              liwork = 3*minmn*nlvl + 11*minmn
              mm = m
              if (m >= n .and. m >= mnthr) then
                 ! path 1a - overdetermined, with many more rows than columns.
                 mm = n
                 maxwrk = max(maxwrk,n + n*la_ilaenv(1,'DGEQRF',' ',m,n,-1,-1))

                 maxwrk = max(maxwrk,n + nrhs*la_ilaenv(1,'DORMQR','LT',m,nrhs,n,-1))

              end if
              if (m >= n) then
                 ! path 1 - overdetermined or exactly determined.
                 maxwrk = max(maxwrk,3*n + (mm + n)*la_ilaenv(1,'DGEBRD',' ',mm,n,-1,- &
                           1))
                 maxwrk = max(maxwrk,3*n + nrhs*la_ilaenv(1,'DORMBR','QLT',mm,nrhs,n,- &
                           1))
                 maxwrk = max(maxwrk,3*n + (n - 1)*la_ilaenv(1,'DORMBR','PLN',n,nrhs,n, &
                           -1))
                 wlalsd = 9*n + 2*n*smlsiz + 8*n*nlvl + n*nrhs + (smlsiz + 1)**2
                 maxwrk = max(maxwrk,3*n + wlalsd)
                 minwrk = max(3*n + mm,3*n + nrhs,3*n + wlalsd)
              end if
              if (n > m) then
                 wlalsd = 9*m + 2*m*smlsiz + 8*m*nlvl + m*nrhs + (smlsiz + 1)**2
                 if (n >= mnthr) then
                    ! path 2a - underdetermined, with many more columns
                    ! than rows.
                    maxwrk = m + m*la_ilaenv(1,'DGELQF',' ',m,n,-1,-1)
                    maxwrk = max(maxwrk,m*m + 4*m + 2*m*la_ilaenv(1,'DGEBRD',' ',m,m,-1,- &
                              1))
                    maxwrk = max(maxwrk,m*m + 4*m + nrhs*la_ilaenv(1,'DORMBR','QLT',m,nrhs, &
                               m,-1))
                    maxwrk = max(maxwrk,m*m + 4*m + (m - 1)*la_ilaenv(1,'DORMBR','PLN',m, &
                              nrhs,m,-1))
                    if (nrhs > 1) then
                       maxwrk = max(maxwrk,m*m + m + m*nrhs)
                    else
                       maxwrk = max(maxwrk,m*m + 2*m)
                    end if
                    maxwrk = max(maxwrk,m + nrhs*la_ilaenv(1,'DORMLQ','LT',n,nrhs,m,-1 &
                              ))
                    maxwrk = max(maxwrk,m*m + 4*m + wlalsd)
           ! xxx: ensure the path 2a case below is triggered.  the workspace
           ! calculation should use queries for all routines eventually.
                    maxwrk = max(maxwrk,4*m + m*m + max(m,2*m - 4,nrhs,n - 3*m))
                 else
                    ! path 2 - remaining underdetermined cases.
                    maxwrk = 3*m + (n + m)*la_ilaenv(1,'DGEBRD',' ',m,n,-1,-1)
                    maxwrk = max(maxwrk,3*m + nrhs*la_ilaenv(1,'DORMBR','QLT',m,nrhs,n, &
                              -1))
                    maxwrk = max(maxwrk,3*m + m*la_ilaenv(1,'DORMBR','PLN',n,nrhs,m,-1 &
                              ))
                    maxwrk = max(maxwrk,3*m + wlalsd)
                 end if
                 minwrk = max(3*m + nrhs,3*m + m,3*m + wlalsd)
              end if
              minwrk = min(minwrk,maxwrk)
              work(1) = maxwrk
              iwork(1) = liwork
              if (lwork < minwrk .and. .not. lquery) then
                 info = -12
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DGELSD',-info)
              return
           else if (lquery) then
              go to 10
           end if
           ! quick return if possible.
           if (m == 0 .or. n == 0) then
              rank = 0
              return
           end if
           ! get machine parameters.
           eps = la_qlamch('P')
           sfmin = la_qlamch('S')
           smlnum = sfmin/eps
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           ! scale a if max entry outside range [smlnum,bignum].
           anrm = la_qlange('M',m,n,a,lda,work)
           iascl = 0
           if (anrm > zero .and. anrm < smlnum) then
              ! scale matrix norm up to smlnum.
              call la_qlascl('G',0,0,anrm,smlnum,m,n,a,lda,info)
              iascl = 1
           else if (anrm > bignum) then
              ! scale matrix norm down to bignum.
              call la_qlascl('G',0,0,anrm,bignum,m,n,a,lda,info)
              iascl = 2
           else if (anrm == zero) then
              ! matrix all zero. return zero solution.
              call la_qlaset('F',max(m,n),nrhs,zero,zero,b,ldb)
              call la_qlaset('F',minmn,1,zero,zero,s,1)
              rank = 0
              go to 10
           end if
           ! scale b if max entry outside range [smlnum,bignum].
           bnrm = la_qlange('M',m,nrhs,b,ldb,work)
           ibscl = 0
           if (bnrm > zero .and. bnrm < smlnum) then
              ! scale matrix norm up to smlnum.
              call la_qlascl('G',0,0,bnrm,smlnum,m,nrhs,b,ldb,info)
              ibscl = 1
           else if (bnrm > bignum) then
              ! scale matrix norm down to bignum.
              call la_qlascl('G',0,0,bnrm,bignum,m,nrhs,b,ldb,info)
              ibscl = 2
           end if
           ! if m < n make sure certain entries of b are zero.
           if (m < n) call la_qlaset('F',n - m,nrhs,zero,zero,b(m + 1,1),ldb)
           ! overdetermined case.
           if (m >= n) then
              ! path 1 - overdetermined or exactly determined.
              mm = m
              if (m >= mnthr) then
                 ! path 1a - overdetermined, with many more rows than columns.
                 mm = n
                 itau = 1
                 nwork = itau + n
                 ! compute a=q*r.
                 ! (workspace: need 2*n, prefer n+n*nb)
                 call la_qgeqrf(m,n,a,lda,work(itau),work(nwork),lwork - nwork + 1, &
                           info)
                 ! multiply b by transpose(q).
                 ! (workspace: need n+nrhs, prefer n+nrhs*nb)
                 call la_qormqr('L','T',m,nrhs,n,a,lda,work(itau),b,ldb,work( &
                           nwork),lwork - nwork + 1,info)
                 ! zero out below r.
                 if (n > 1) then
                    call la_qlaset('L',n - 1,n - 1,zero,zero,a(2,1),lda)
                 end if
              end if
              ie = 1
              itauq = ie + n
              itaup = itauq + n
              nwork = itaup + n
              ! bidiagonalize r in a.
              ! (workspace: need 3*n+mm, prefer 3*n+(mm+n)*nb)
              call la_qgebrd(mm,n,a,lda,s,work(ie),work(itauq),work(itaup),work( &
                         nwork),lwork - nwork + 1,info)
              ! multiply b by transpose of left bidiagonalizing vectors of r.
              ! (workspace: need 3*n+nrhs, prefer 3*n+nrhs*nb)
              call la_qormbr('Q','L','T',mm,nrhs,n,a,lda,work(itauq),b,ldb,work( &
                        nwork),lwork - nwork + 1,info)
              ! solve the bidiagonal least squares problem.
              call la_qlalsd('U',smlsiz,n,nrhs,s,work(ie),b,ldb,rcond,rank,work( &
                        nwork),iwork,info)
              if (info /= 0) then
                 go to 10
              end if
              ! multiply b by right bidiagonalizing vectors of r.
              call la_qormbr('P','L','N',n,nrhs,n,a,lda,work(itaup),b,ldb,work( &
                        nwork),lwork - nwork + 1,info)
           else if (n >= mnthr .and. lwork >= 4*m + m*m + max(m,2*m - 4,nrhs,n - 3*m,wlalsd)) &
                     then
              ! path 2a - underdetermined, with many more columns than rows
              ! and sufficient workspace for an efficient algorithm.
              ldwork = m
              if (lwork >= max(4*m + m*lda + max(m,2*m - 4,nrhs,n - 3*m),m*lda + m + m*nrhs,4*m + m*lda + &
                        wlalsd)) ldwork = lda
              itau = 1
              nwork = m + 1
              ! compute a=l*q.
              ! (workspace: need 2*m, prefer m+m*nb)
              call la_qgelqf(m,n,a,lda,work(itau),work(nwork),lwork - nwork + 1,info)

              il = nwork
              ! copy l to work(il), zeroing out above its diagonal.
              call la_qlacpy('L',m,m,a,lda,work(il),ldwork)
              call la_qlaset('U',m - 1,m - 1,zero,zero,work(il + ldwork),ldwork)
              ie = il + ldwork*m
              itauq = ie + m
              itaup = itauq + m
              nwork = itaup + m
              ! bidiagonalize l in work(il).
              ! (workspace: need m*m+5*m, prefer m*m+4*m+2*m*nb)
              call la_qgebrd(m,m,work(il),ldwork,s,work(ie),work(itauq),work( &
                        itaup),work(nwork),lwork - nwork + 1,info)
              ! multiply b by transpose of left bidiagonalizing vectors of l.
              ! (workspace: need m*m+4*m+nrhs, prefer m*m+4*m+nrhs*nb)
              call la_qormbr('Q','L','T',m,nrhs,m,work(il),ldwork,work(itauq),b, &
                        ldb,work(nwork),lwork - nwork + 1,info)
              ! solve the bidiagonal least squares problem.
              call la_qlalsd('U',smlsiz,m,nrhs,s,work(ie),b,ldb,rcond,rank,work( &
                        nwork),iwork,info)
              if (info /= 0) then
                 go to 10
              end if
              ! multiply b by right bidiagonalizing vectors of l.
              call la_qormbr('P','L','N',m,nrhs,m,work(il),ldwork,work(itaup),b, &
                        ldb,work(nwork),lwork - nwork + 1,info)
              ! zero out below first m rows of b.
              call la_qlaset('F',n - m,nrhs,zero,zero,b(m + 1,1),ldb)
              nwork = itau + m
              ! multiply transpose(q) by b.
              ! (workspace: need m+nrhs, prefer m+nrhs*nb)
              call la_qormlq('L','T',n,nrhs,m,a,lda,work(itau),b,ldb,work(nwork) &
                        ,lwork - nwork + 1,info)
           else
              ! path 2 - remaining underdetermined cases.
              ie = 1
              itauq = ie + m
              itaup = itauq + m
              nwork = itaup + m
              ! bidiagonalize a.
              ! (workspace: need 3*m+n, prefer 3*m+(m+n)*nb)
              call la_qgebrd(m,n,a,lda,s,work(ie),work(itauq),work(itaup),work( &
                        nwork),lwork - nwork + 1,info)
              ! multiply b by transpose of left bidiagonalizing vectors.
              ! (workspace: need 3*m+nrhs, prefer 3*m+nrhs*nb)
              call la_qormbr('Q','L','T',m,nrhs,n,a,lda,work(itauq),b,ldb,work( &
                        nwork),lwork - nwork + 1,info)
              ! solve the bidiagonal least squares problem.
              call la_qlalsd('L',smlsiz,m,nrhs,s,work(ie),b,ldb,rcond,rank,work( &
                        nwork),iwork,info)
              if (info /= 0) then
                 go to 10
              end if
              ! multiply b by right bidiagonalizing vectors of a.
              call la_qormbr('P','L','N',n,nrhs,m,a,lda,work(itaup),b,ldb,work( &
                        nwork),lwork - nwork + 1,info)
           end if
           ! undo scaling.
           if (iascl == 1) then
              call la_qlascl('G',0,0,anrm,smlnum,n,nrhs,b,ldb,info)
              call la_qlascl('G',0,0,smlnum,anrm,minmn,1,s,minmn,info)
           else if (iascl == 2) then
              call la_qlascl('G',0,0,anrm,bignum,n,nrhs,b,ldb,info)
              call la_qlascl('G',0,0,bignum,anrm,minmn,1,s,minmn,info)
           end if
           if (ibscl == 1) then
              call la_qlascl('G',0,0,smlnum,bnrm,n,nrhs,b,ldb,info)
           else if (ibscl == 2) then
              call la_qlascl('G',0,0,bignum,bnrm,n,nrhs,b,ldb,info)
           end if
           10 continue
           work(1) = maxwrk
           iwork(1) = liwork
           return
     end subroutine la_qgelsd

     !> DGELSS: computes the minimum norm solution to a real linear least
     !> squares problem:
     !> Minimize 2-norm(| b - A*x |).
     !> using the singular value decomposition (SVD) of A. A is an M-by-N
     !> matrix which may be rank-deficient.
     !> Several right hand side vectors b and solution vectors x can be
     !> handled in a single call; they are stored as the columns of the
     !> M-by-NRHS right hand side matrix B and the N-by-NRHS solution matrix
     !> X.
     !> The effective rank of A is determined by treating as zero those
     !> singular values which are less than RCOND times the largest singular
     !> value.

     subroutine la_qgelss(m,n,nrhs,a,lda,b,ldb,s,rcond,rank,work,lwork,info)

        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info,rank
           integer(ilp),intent(in) :: lda,ldb,lwork,m,n,nrhs
           real(qp),intent(in) :: rcond
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: s(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: bdspac,bl,chunk,i,iascl,ibscl,ie,il,itau,itaup,itauq,iwork, &
                     ldwork,maxmn,maxwrk,minmn,minwrk,mm,mnthr
           integer(ilp) :: lwork_qgeqrf,lwork_qormqr,lwork_qgebrd,lwork_qormbr,lwork_qorgbr, &
                     lwork_qormlq,lwork_qgelqf
           real(qp) :: anrm,bignum,bnrm,eps,sfmin,smlnum,thr
           ! Local Arrays
           real(qp) :: dum(1)
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           minmn = min(m,n)
           maxmn = max(m,n)
           lquery = (lwork == -1)
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           else if (ldb < max(1,maxmn)) then
              info = -7
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv.)
           if (info == 0) then
              minwrk = 1
              maxwrk = 1
              if (minmn > 0) then
                 mm = m
                 mnthr = la_ilaenv(6,'DGELSS',' ',m,n,nrhs,-1)
                 if (m >= n .and. m >= mnthr) then
                    ! path 1a - overdetermined, with many more rows than
                              ! columns
                    ! compute space needed for la_qgeqrf
                    call la_qgeqrf(m,n,a,lda,dum(1),dum(1),-1,info)
                    lwork_qgeqrf = dum(1)
                    ! compute space needed for la_qormqr
                    call la_qormqr('L','T',m,nrhs,n,a,lda,dum(1),b,ldb,dum(1),-1, &
                              info)
                    lwork_qormqr = dum(1)
                    mm = n
                    maxwrk = max(maxwrk,n + lwork_qgeqrf)
                    maxwrk = max(maxwrk,n + lwork_qormqr)
                 end if
                 if (m >= n) then
                    ! path 1 - overdetermined or exactly determined
                    ! compute workspace needed for la_qbdsqr
                    bdspac = max(1,5*n)
                    ! compute space needed for la_qgebrd
                    call la_qgebrd(mm,n,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1,info &
                              )
                    lwork_qgebrd = dum(1)
                    ! compute space needed for la_qormbr
                    call la_qormbr('Q','L','T',mm,nrhs,n,a,lda,dum(1),b,ldb,dum(1), &
                               -1,info)
                    lwork_qormbr = dum(1)
                    ! compute space needed for la_qorgbr
                    call la_qorgbr('P',n,n,n,a,lda,dum(1),dum(1),-1,info)
                    lwork_qorgbr = dum(1)
                    ! compute total workspace needed
                    maxwrk = max(maxwrk,3*n + lwork_qgebrd)
                    maxwrk = max(maxwrk,3*n + lwork_qormbr)
                    maxwrk = max(maxwrk,3*n + lwork_qorgbr)
                    maxwrk = max(maxwrk,bdspac)
                    maxwrk = max(maxwrk,n*nrhs)
                    minwrk = max(3*n + mm,3*n + nrhs,bdspac)
                    maxwrk = max(minwrk,maxwrk)
                 end if
                 if (n > m) then
                    ! compute workspace needed for la_qbdsqr
                    bdspac = max(1,5*m)
                    minwrk = max(3*m + nrhs,3*m + n,bdspac)
                    if (n >= mnthr) then
                       ! path 2a - underdetermined, with many more columns
                       ! than rows
                       ! compute space needed for la_qgelqf
                       call la_qgelqf(m,n,a,lda,dum(1),dum(1),-1,info)
                       lwork_qgelqf = dum(1)
                       ! compute space needed for la_qgebrd
                       call la_qgebrd(m,m,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1, &
                                 info)
                       lwork_qgebrd = dum(1)
                       ! compute space needed for la_qormbr
                       call la_qormbr('Q','L','T',m,nrhs,n,a,lda,dum(1),b,ldb,dum( &
                                 1),-1,info)
                       lwork_qormbr = dum(1)
                       ! compute space needed for la_qorgbr
                       call la_qorgbr('P',m,m,m,a,lda,dum(1),dum(1),-1,info)
                       lwork_qorgbr = dum(1)
                       ! compute space needed for la_qormlq
                       call la_qormlq('L','T',n,nrhs,m,a,lda,dum(1),b,ldb,dum(1),- &
                                 1,info)
                       lwork_qormlq = dum(1)
                       ! compute total workspace needed
                       maxwrk = m + lwork_qgelqf
                       maxwrk = max(maxwrk,m*m + 4*m + lwork_qgebrd)
                       maxwrk = max(maxwrk,m*m + 4*m + lwork_qormbr)
                       maxwrk = max(maxwrk,m*m + 4*m + lwork_qorgbr)
                       maxwrk = max(maxwrk,m*m + m + bdspac)
                       if (nrhs > 1) then
                          maxwrk = max(maxwrk,m*m + m + m*nrhs)
                       else
                          maxwrk = max(maxwrk,m*m + 2*m)
                       end if
                       maxwrk = max(maxwrk,m + lwork_qormlq)
                    else
                       ! path 2 - underdetermined
                       ! compute space needed for la_qgebrd
                       call la_qgebrd(m,n,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1, &
                                 info)
                       lwork_qgebrd = dum(1)
                       ! compute space needed for la_qormbr
                       call la_qormbr('Q','L','T',m,nrhs,m,a,lda,dum(1),b,ldb,dum( &
                                 1),-1,info)
                       lwork_qormbr = dum(1)
                       ! compute space needed for la_qorgbr
                       call la_qorgbr('P',m,n,m,a,lda,dum(1),dum(1),-1,info)
                       lwork_qorgbr = dum(1)
                       maxwrk = 3*m + lwork_qgebrd
                       maxwrk = max(maxwrk,3*m + lwork_qormbr)
                       maxwrk = max(maxwrk,3*m + lwork_qorgbr)
                       maxwrk = max(maxwrk,bdspac)
                       maxwrk = max(maxwrk,n*nrhs)
                    end if
                 end if
                 maxwrk = max(minwrk,maxwrk)
              end if
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) info = -12
           end if
           if (info /= 0) then
              call la_xerbla('DGELSS',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) then
              rank = 0
              return
           end if
           ! get machine parameters
           eps = la_qlamch('P')
           sfmin = la_qlamch('S')
           smlnum = sfmin/eps
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',m,n,a,lda,work)
           iascl = 0
           if (anrm > zero .and. anrm < smlnum) then
              ! scale matrix norm up to smlnum
              call la_qlascl('G',0,0,anrm,smlnum,m,n,a,lda,info)
              iascl = 1
           else if (anrm > bignum) then
              ! scale matrix norm down to bignum
              call la_qlascl('G',0,0,anrm,bignum,m,n,a,lda,info)
              iascl = 2
           else if (anrm == zero) then
              ! matrix all zero. return zero solution.
              call la_qlaset('F',max(m,n),nrhs,zero,zero,b,ldb)
              call la_qlaset('F',minmn,1,zero,zero,s,minmn)
              rank = 0
              go to 70
           end if
           ! scale b if max element outside range [smlnum,bignum]
           bnrm = la_qlange('M',m,nrhs,b,ldb,work)
           ibscl = 0
           if (bnrm > zero .and. bnrm < smlnum) then
              ! scale matrix norm up to smlnum
              call la_qlascl('G',0,0,bnrm,smlnum,m,nrhs,b,ldb,info)
              ibscl = 1
           else if (bnrm > bignum) then
              ! scale matrix norm down to bignum
              call la_qlascl('G',0,0,bnrm,bignum,m,nrhs,b,ldb,info)
              ibscl = 2
           end if
           ! overdetermined case
           if (m >= n) then
              ! path 1 - overdetermined or exactly determined
              mm = m
              if (m >= mnthr) then
                 ! path 1a - overdetermined, with many more rows than columns
                 mm = n
                 itau = 1
                 iwork = itau + n
                 ! compute a=q*r
                 ! (workspace: need 2*n, prefer n+n*nb)
                 call la_qgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + 1, &
                           info)
                 ! multiply b by transpose(q)
                 ! (workspace: need n+nrhs, prefer n+nrhs*nb)
                 call la_qormqr('L','T',m,nrhs,n,a,lda,work(itau),b,ldb,work( &
                           iwork),lwork - iwork + 1,info)
                 ! zero out below r
                 if (n > 1) call la_qlaset('L',n - 1,n - 1,zero,zero,a(2,1),lda)
              end if
              ie = 1
              itauq = ie + n
              itaup = itauq + n
              iwork = itaup + n
              ! bidiagonalize r in a
              ! (workspace: need 3*n+mm, prefer 3*n+(mm+n)*nb)
              call la_qgebrd(mm,n,a,lda,s,work(ie),work(itauq),work(itaup),work( &
                         iwork),lwork - iwork + 1,info)
              ! multiply b by transpose of left bidiagonalizing vectors of r
              ! (workspace: need 3*n+nrhs, prefer 3*n+nrhs*nb)
              call la_qormbr('Q','L','T',mm,nrhs,n,a,lda,work(itauq),b,ldb,work( &
                        iwork),lwork - iwork + 1,info)
              ! generate right bidiagonalizing vectors of r in a
              ! (workspace: need 4*n-1, prefer 3*n+(n-1)*nb)
              call la_qorgbr('P',n,n,n,a,lda,work(itaup),work(iwork),lwork - iwork + &
                        1,info)
              iwork = ie + n
              ! perform bidiagonal qr iteration
                ! multiply b by transpose of left singular vectors
                ! compute right singular vectors in a
              ! (workspace: need bdspac)
              call la_qbdsqr('U',n,n,0,nrhs,s,work(ie),a,lda,dum,1,b,ldb,work( &
                        iwork),info)
              if (info /= 0) go to 70
              ! multiply b by reciprocals of singular values
              thr = max(rcond*s(1),sfmin)
              if (rcond < zero) thr = max(eps*s(1),sfmin)
              rank = 0
              do i = 1,n
                 if (s(i) > thr) then
                    call la_qrscl(nrhs,s(i),b(i,1),ldb)
                    rank = rank + 1
                 else
                    call la_qlaset('F',1,nrhs,zero,zero,b(i,1),ldb)
                 end if
              end do
              ! multiply b by right singular vectors
              ! (workspace: need n, prefer n*nrhs)
              if (lwork >= ldb*nrhs .and. nrhs > 1) then
                 call la_qgemm('T','N',n,nrhs,n,one,a,lda,b,ldb,zero,work,ldb)

                 call la_qlacpy('G',n,nrhs,work,ldb,b,ldb)
              else if (nrhs > 1) then
                 chunk = lwork/n
                 do i = 1,nrhs,chunk
                    bl = min(nrhs - i + 1,chunk)
                    call la_qgemm('T','N',n,bl,n,one,a,lda,b(1,i),ldb,zero,work, &
                               n)
                    call la_qlacpy('G',n,bl,work,n,b(1,i),ldb)
                 end do
              else
                 call la_qgemv('T',n,n,one,a,lda,b,1,zero,work,1)
                 call la_qcopy(n,work,1,b,1)
              end if
           else if (n >= mnthr .and. lwork >= 4*m + m*m + max(m,2*m - 4,nrhs,n - 3*m)) then
              ! path 2a - underdetermined, with many more columns than rows
              ! and sufficient workspace for an efficient algorithm
              ldwork = m
              if (lwork >= max(4*m + m*lda + max(m,2*m - 4,nrhs,n - 3*m),m*lda + m + m*nrhs)) ldwork = &
                        lda
              itau = 1
              iwork = m + 1
              ! compute a=l*q
              ! (workspace: need 2*m, prefer m+m*nb)
              call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + 1,info)

              il = iwork
              ! copy l to work(il), zeroing out above it
              call la_qlacpy('L',m,m,a,lda,work(il),ldwork)
              call la_qlaset('U',m - 1,m - 1,zero,zero,work(il + ldwork),ldwork)
              ie = il + ldwork*m
              itauq = ie + m
              itaup = itauq + m
              iwork = itaup + m
              ! bidiagonalize l in work(il)
              ! (workspace: need m*m+5*m, prefer m*m+4*m+2*m*nb)
              call la_qgebrd(m,m,work(il),ldwork,s,work(ie),work(itauq),work( &
                        itaup),work(iwork),lwork - iwork + 1,info)
              ! multiply b by transpose of left bidiagonalizing vectors of l
              ! (workspace: need m*m+4*m+nrhs, prefer m*m+4*m+nrhs*nb)
              call la_qormbr('Q','L','T',m,nrhs,m,work(il),ldwork,work(itauq),b, &
                        ldb,work(iwork),lwork - iwork + 1,info)
              ! generate right bidiagonalizing vectors of r in work(il)
              ! (workspace: need m*m+5*m-1, prefer m*m+4*m+(m-1)*nb)
              call la_qorgbr('P',m,m,m,work(il),ldwork,work(itaup),work(iwork), &
                        lwork - iwork + 1,info)
              iwork = ie + m
              ! perform bidiagonal qr iteration,
                 ! computing right singular vectors of l in work(il) and
                 ! multiplying b by transpose of left singular vectors
              ! (workspace: need m*m+m+bdspac)
              call la_qbdsqr('U',m,m,0,nrhs,s,work(ie),work(il),ldwork,a,lda,b, &
                         ldb,work(iwork),info)
              if (info /= 0) go to 70
              ! multiply b by reciprocals of singular values
              thr = max(rcond*s(1),sfmin)
              if (rcond < zero) thr = max(eps*s(1),sfmin)
              rank = 0
              do i = 1,m
                 if (s(i) > thr) then
                    call la_qrscl(nrhs,s(i),b(i,1),ldb)
                    rank = rank + 1
                 else
                    call la_qlaset('F',1,nrhs,zero,zero,b(i,1),ldb)
                 end if
              end do
              iwork = ie
              ! multiply b by right singular vectors of l in work(il)
              ! (workspace: need m*m+2*m, prefer m*m+m+m*nrhs)
              if (lwork >= ldb*nrhs + iwork - 1 .and. nrhs > 1) then
                 call la_qgemm('T','N',m,nrhs,m,one,work(il),ldwork,b,ldb,zero, &
                           work(iwork),ldb)
                 call la_qlacpy('G',m,nrhs,work(iwork),ldb,b,ldb)
              else if (nrhs > 1) then
                 chunk = (lwork - iwork + 1)/m
                 do i = 1,nrhs,chunk
                    bl = min(nrhs - i + 1,chunk)
                    call la_qgemm('T','N',m,bl,m,one,work(il),ldwork,b(1,i),ldb, &
                               zero,work(iwork),m)
                    call la_qlacpy('G',m,bl,work(iwork),m,b(1,i),ldb)
                 end do
              else
                 call la_qgemv('T',m,m,one,work(il),ldwork,b(1,1),1,zero,work( &
                           iwork),1)
                 call la_qcopy(m,work(iwork),1,b(1,1),1)
              end if
              ! zero out below first m rows of b
              call la_qlaset('F',n - m,nrhs,zero,zero,b(m + 1,1),ldb)
              iwork = itau + m
              ! multiply transpose(q) by b
              ! (workspace: need m+nrhs, prefer m+nrhs*nb)
              call la_qormlq('L','T',n,nrhs,m,a,lda,work(itau),b,ldb,work(iwork) &
                        ,lwork - iwork + 1,info)
           else
              ! path 2 - remaining underdetermined cases
              ie = 1
              itauq = ie + m
              itaup = itauq + m
              iwork = itaup + m
              ! bidiagonalize a
              ! (workspace: need 3*m+n, prefer 3*m+(m+n)*nb)
              call la_qgebrd(m,n,a,lda,s,work(ie),work(itauq),work(itaup),work( &
                        iwork),lwork - iwork + 1,info)
              ! multiply b by transpose of left bidiagonalizing vectors
              ! (workspace: need 3*m+nrhs, prefer 3*m+nrhs*nb)
              call la_qormbr('Q','L','T',m,nrhs,n,a,lda,work(itauq),b,ldb,work( &
                        iwork),lwork - iwork + 1,info)
              ! generate right bidiagonalizing vectors in a
              ! (workspace: need 4*m, prefer 3*m+m*nb)
              call la_qorgbr('P',m,n,m,a,lda,work(itaup),work(iwork),lwork - iwork + &
                        1,info)
              iwork = ie + m
              ! perform bidiagonal qr iteration,
                 ! computing right singular vectors of a in a and
                 ! multiplying b by transpose of left singular vectors
              ! (workspace: need bdspac)
              call la_qbdsqr('L',m,n,0,nrhs,s,work(ie),a,lda,dum,1,b,ldb,work( &
                        iwork),info)
              if (info /= 0) go to 70
              ! multiply b by reciprocals of singular values
              thr = max(rcond*s(1),sfmin)
              if (rcond < zero) thr = max(eps*s(1),sfmin)
              rank = 0
              do i = 1,m
                 if (s(i) > thr) then
                    call la_qrscl(nrhs,s(i),b(i,1),ldb)
                    rank = rank + 1
                 else
                    call la_qlaset('F',1,nrhs,zero,zero,b(i,1),ldb)
                 end if
              end do
              ! multiply b by right singular vectors of a
              ! (workspace: need n, prefer n*nrhs)
              if (lwork >= ldb*nrhs .and. nrhs > 1) then
                 call la_qgemm('T','N',n,nrhs,m,one,a,lda,b,ldb,zero,work,ldb)

                 call la_qlacpy('F',n,nrhs,work,ldb,b,ldb)
              else if (nrhs > 1) then
                 chunk = lwork/n
                 do i = 1,nrhs,chunk
                    bl = min(nrhs - i + 1,chunk)
                    call la_qgemm('T','N',n,bl,m,one,a,lda,b(1,i),ldb,zero,work, &
                               n)
                    call la_qlacpy('F',n,bl,work,n,b(1,i),ldb)
                 end do
              else
                 call la_qgemv('T',m,n,one,a,lda,b,1,zero,work,1)
                 call la_qcopy(n,work,1,b,1)
              end if
           end if
           ! undo scaling
           if (iascl == 1) then
              call la_qlascl('G',0,0,anrm,smlnum,n,nrhs,b,ldb,info)
              call la_qlascl('G',0,0,smlnum,anrm,minmn,1,s,minmn,info)
           else if (iascl == 2) then
              call la_qlascl('G',0,0,anrm,bignum,n,nrhs,b,ldb,info)
              call la_qlascl('G',0,0,bignum,anrm,minmn,1,s,minmn,info)
           end if
           if (ibscl == 1) then
              call la_qlascl('G',0,0,smlnum,bnrm,n,nrhs,b,ldb,info)
           else if (ibscl == 2) then
              call la_qlascl('G',0,0,bignum,bnrm,n,nrhs,b,ldb,info)
           end if
           70 continue
           work(1) = maxwrk
           return
     end subroutine la_qgelss

     !> DGELSY: computes the minimum-norm solution to a real linear least
     !> squares problem:
     !> minimize || A * X - B ||
     !> using a complete orthogonal factorization of A.  A is an M-by-N
     !> matrix which may be rank-deficient.
     !> Several right hand side vectors b and solution vectors x can be
     !> handled in a single call; they are stored as the columns of the
     !> M-by-NRHS right hand side matrix B and the N-by-NRHS solution
     !> matrix X.
     !> The routine first computes a QR factorization with column pivoting:
     !> A * P = Q * [ R11 R12 ]
     !> [  0  R22 ]
     !> with R11 defined as the largest leading submatrix whose estimated
     !> condition number is less than 1/RCOND.  The order of R11, RANK,
     !> is the effective rank of A.
     !> Then, R22 is considered to be negligible, and R12 is annihilated
     !> by orthogonal transformations from the right, arriving at the
     !> complete orthogonal factorization:
     !> A * P = Q * [ T11 0 ] * Z
     !> [  0  0 ]
     !> The minimum-norm solution is then
     !> X = P * Z**T [ inv(T11)*Q1**T*B ]
     !> [        0         ]
     !> where Q1 consists of the first RANK columns of Q.
     !> This routine is basically identical to the original xGELSX except
     !> three differences:
     !> o The call to the subroutine xGEQPF has been substituted by the
     !> the call to the subroutine xGEQP3. This subroutine is a Blas-3
     !> version of the QR factorization with column pivoting.
     !> o Matrix B (the right hand side) is updated with Blas-3.
     !> o The permutation of matrix B (the right hand side) is faster and
     !> more simple.

     subroutine la_qgelsy(m,n,nrhs,a,lda,b,ldb,jpvt,rcond,rank,work,lwork,info)

        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info,rank
           integer(ilp),intent(in) :: lda,ldb,lwork,m,n,nrhs
           real(qp),intent(in) :: rcond
           ! Array Arguments
           integer(ilp),intent(inout) :: jpvt(*)
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: imax = 1
           integer(ilp),parameter :: imin = 2

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: i,iascl,ibscl,ismax,ismin,j,lwkmin,lwkopt,mn,nb,nb1,nb2, &
                     nb3,nb4
           real(qp) :: anrm,bignum,bnrm,c1,c2,s1,s2,smax,smaxpr,smin,sminpr,smlnum, &
                     wsize
           ! Intrinsic Functions
           intrinsic :: abs,max,min
           ! Executable Statements
           mn = min(m,n)
           ismin = mn + 1
           ismax = 2*mn + 1
           ! test the input arguments.
           info = 0
           lquery = (lwork == -1)
           if (m < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           else if (ldb < max(1,m,n)) then
              info = -7
           end if
           ! figure out optimal block size
           if (info == 0) then
              if (mn == 0 .or. nrhs == 0) then
                 lwkmin = 1
                 lwkopt = 1
              else
                 nb1 = la_ilaenv(1,'DGEQRF',' ',m,n,-1,-1)
                 nb2 = la_ilaenv(1,'DGERQF',' ',m,n,-1,-1)
                 nb3 = la_ilaenv(1,'DORMQR',' ',m,n,nrhs,-1)
                 nb4 = la_ilaenv(1,'DORMRQ',' ',m,n,nrhs,-1)
                 nb = max(nb1,nb2,nb3,nb4)
                 lwkmin = mn + max(2*mn,n + 1,mn + nrhs)
                 lwkopt = max(lwkmin,mn + 2*n + nb*(n + 1),2*mn + nb*nrhs)
              end if
              work(1) = lwkopt
              if (lwork < lwkmin .and. .not. lquery) then
                 info = -12
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DGELSY',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (mn == 0 .or. nrhs == 0) then
              rank = 0
              return
           end if
           ! get machine parameters
           smlnum = la_qlamch('S')/la_qlamch('P')
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           ! scale a, b if max entries outside range [smlnum,bignum]
           anrm = la_qlange('M',m,n,a,lda,work)
           iascl = 0
           if (anrm > zero .and. anrm < smlnum) then
              ! scale matrix norm up to smlnum
              call la_qlascl('G',0,0,anrm,smlnum,m,n,a,lda,info)
              iascl = 1
           else if (anrm > bignum) then
              ! scale matrix norm down to bignum
              call la_qlascl('G',0,0,anrm,bignum,m,n,a,lda,info)
              iascl = 2
           else if (anrm == zero) then
              ! matrix all zero. return zero solution.
              call la_qlaset('F',max(m,n),nrhs,zero,zero,b,ldb)
              rank = 0
              go to 70
           end if
           bnrm = la_qlange('M',m,nrhs,b,ldb,work)
           ibscl = 0
           if (bnrm > zero .and. bnrm < smlnum) then
              ! scale matrix norm up to smlnum
              call la_qlascl('G',0,0,bnrm,smlnum,m,nrhs,b,ldb,info)
              ibscl = 1
           else if (bnrm > bignum) then
              ! scale matrix norm down to bignum
              call la_qlascl('G',0,0,bnrm,bignum,m,nrhs,b,ldb,info)
              ibscl = 2
           end if
           ! compute qr factorization with column pivoting of a:
              ! a * p = q * r
           call la_qgeqp3(m,n,a,lda,jpvt,work(1),work(mn + 1),lwork - mn,info)

           wsize = mn + work(mn + 1)
           ! workspace: mn+2*n+nb*(n+1).
           ! details of householder rotations stored in work(1:mn).
           ! determine rank using incremental condition estimation
           work(ismin) = one
           work(ismax) = one
           smax = abs(a(1,1))
           smin = smax
           if (abs(a(1,1)) == zero) then
              rank = 0
              call la_qlaset('F',max(m,n),nrhs,zero,zero,b,ldb)
              go to 70
           else
              rank = 1
           end if
           10 continue
           if (rank < mn) then
              i = rank + 1
              call la_qlaic1(imin,rank,work(ismin),smin,a(1,i),a(i,i),sminpr, &
                        s1,c1)
              call la_qlaic1(imax,rank,work(ismax),smax,a(1,i),a(i,i),smaxpr, &
                        s2,c2)
              if (smaxpr*rcond <= sminpr) then
                 do i = 1,rank
                    work(ismin + i - 1) = s1*work(ismin + i - 1)
                    work(ismax + i - 1) = s2*work(ismax + i - 1)
                 end do
                 work(ismin + rank) = c1
                 work(ismax + rank) = c2
                 smin = sminpr
                 smax = smaxpr
                 rank = rank + 1
                 go to 10
              end if
           end if
           ! workspace: 3*mn.
           ! logically partition r = [ r11 r12 ]
                                   ! [  0  r22 ]
           ! where r11 = r(1:rank,1:rank)
           ! [r11,r12] = [ t11, 0 ] * y
           if (rank < n) call la_qtzrzf(rank,n,a,lda,work(mn + 1),work(2*mn + 1),lwork - &
                     2*mn,info)
           ! workspace: 2*mn.
           ! details of householder rotations stored in work(mn+1:2*mn)
           ! b(1:m,1:nrhs) := q**t * b(1:m,1:nrhs)
           call la_qormqr('LEFT','TRANSPOSE',m,nrhs,mn,a,lda,work(1),b,ldb,work( &
                     2*mn + 1),lwork - 2*mn,info)
           wsize = max(wsize,2*mn + work(2*mn + 1))
           ! workspace: 2*mn+nb*nrhs.
           ! b(1:rank,1:nrhs) := inv(t11) * b(1:rank,1:nrhs)
           call la_qtrsm('LEFT','UPPER','NO TRANSPOSE','NON-UNIT',rank,nrhs,one,a,lda, &
                      b,ldb)
           do j = 1,nrhs
              do i = rank + 1,n
                 b(i,j) = zero
              end do
           end do
           ! b(1:n,1:nrhs) := y**t * b(1:n,1:nrhs)
           if (rank < n) then
              call la_qormrz('LEFT','TRANSPOSE',n,nrhs,rank,n - rank,a,lda,work(mn + 1), &
                         b,ldb,work(2*mn + 1),lwork - 2*mn,info)
           end if
           ! workspace: 2*mn+nrhs.
           ! b(1:n,1:nrhs) := p * b(1:n,1:nrhs)
           do j = 1,nrhs
              do i = 1,n
                 work(jpvt(i)) = b(i,j)
              end do
              call la_qcopy(n,work(1),1,b(1,j),1)
           end do
           ! workspace: n.
           ! undo scaling
           if (iascl == 1) then
              call la_qlascl('G',0,0,anrm,smlnum,n,nrhs,b,ldb,info)
              call la_qlascl('U',0,0,smlnum,anrm,rank,rank,a,lda,info)
           else if (iascl == 2) then
              call la_qlascl('G',0,0,anrm,bignum,n,nrhs,b,ldb,info)
              call la_qlascl('U',0,0,bignum,anrm,rank,rank,a,lda,info)
           end if
           if (ibscl == 1) then
              call la_qlascl('G',0,0,smlnum,bnrm,n,nrhs,b,ldb,info)
           else if (ibscl == 2) then
              call la_qlascl('G',0,0,bignum,bnrm,n,nrhs,b,ldb,info)
           end if
           70 continue
           work(1) = lwkopt
           return
     end subroutine la_qgelsy

     !> DGESDD: computes the singular value decomposition (SVD) of a real
     !> M-by-N matrix A, optionally computing the left and right singular
     !> vectors.  If singular vectors are desired, it uses a
     !> divide-and-conquer algorithm.
     !> The SVD is written
     !> A = U * SIGMA * transpose(V)
     !> where SIGMA is an M-by-N matrix which is zero except for its
     !> min(m,n) diagonal elements, U is an M-by-M orthogonal matrix, and
     !> V is an N-by-N orthogonal matrix.  The diagonal elements of SIGMA
     !> are the singular values of A; they are real and non-negative, and
     !> are returned in descending order.  The first min(m,n) columns of
     !> U and V are the left and right singular vectors of A.
     !> Note that the routine returns VT = V**T, not V.
     !> The divide and conquer algorithm makes very mild assumptions about
     !> floating point arithmetic. It will work on machines with a guard
     !> digit in add/subtract, or on those binary machines without guard
     !> digits which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or
     !> Cray-2. It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.

     subroutine la_qgesdd(jobz,m,n,a,lda,s,u,ldu,vt,ldvt,work,lwork,iwork,info)

        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldu,ldvt,lwork,m,n
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: s(*),u(ldu,*),vt(ldvt,*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,wntqa,wntqas,wntqn,wntqo,wntqs
           integer(ilp) :: bdspac,blk,chunk,i,ie,ierr,il,ir,iscl,itau,itaup,itauq,iu, &
                     ivt,ldwkvt,ldwrkl,ldwrkr,ldwrku,maxwrk,minmn,minwrk,mnthr,nwork,wrkbl
           integer(ilp) :: lwork_qgebrd_mn,lwork_qgebrd_mm,lwork_qgebrd_nn,lwork_qgelqf_mn, &
           lwork_qgeqrf_mn,lwork_qorgbr_p_mm,lwork_qorgbr_q_nn,lwork_qorglq_mn, &
           lwork_qorglq_nn,lwork_qorgqr_mm,lwork_qorgqr_mn,lwork_qormbr_prt_mm, &
           lwork_qormbr_qln_mm,lwork_qormbr_prt_mn,lwork_qormbr_qln_mn,lwork_qormbr_prt_nn, &
                     lwork_qormbr_qln_nn
           real(qp) :: anrm,bignum,eps,smlnum
           ! Local Arrays
           integer(ilp) :: idum(1)
           real(qp) :: dum(1)
           ! Intrinsic Functions
           intrinsic :: int,max,min,sqrt
           ! Executable Statements
           ! test the input arguments
           info = 0
           minmn = min(m,n)
           wntqa = la_lsame(jobz,'A')
           wntqs = la_lsame(jobz,'S')
           wntqas = wntqa .or. wntqs
           wntqo = la_lsame(jobz,'O')
           wntqn = la_lsame(jobz,'N')
           lquery = (lwork == -1)
           if (.not. (wntqa .or. wntqs .or. wntqo .or. wntqn)) then
              info = -1
           else if (m < 0) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (lda < max(1,m)) then
              info = -5
           else if (ldu < 1 .or. (wntqas .and. ldu < m) .or. (wntqo .and. m < n .and. ldu < m)) &
                     then
              info = -8
           else if (ldvt < 1 .or. (wntqa .and. ldvt < n) .or. (wntqs .and. ldvt < minmn) .or. (wntqo &
                     .and. m >= n .and. ldvt < n)) then
              info = -10
           end if
           ! compute workspace
             ! note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace allocated at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv.
           if (info == 0) then
              minwrk = 1
              maxwrk = 1
              bdspac = 0
              mnthr = int(minmn*11.0_qp/6.0_qp,KIND=ilp)
              if (m >= n .and. minmn > 0) then
                 ! compute space needed for la_qbdsdc
                 if (wntqn) then
                    ! la_qbdsdc needs only 4*n (or 6*n for uplo=l for lapack <= 3.6_qp)
                    ! keep 7*n for backwards compatibility.
                    bdspac = 7*n
                 else
                    bdspac = 3*n*n + 4*n
                 end if
                 ! compute space preferred for each routine
                 call la_qgebrd(m,n,dum(1),m,dum(1),dum(1),dum(1),dum(1),dum(1),-1, &
                           ierr)
                 lwork_qgebrd_mn = int(dum(1),KIND=ilp)
                 call la_qgebrd(n,n,dum(1),n,dum(1),dum(1),dum(1),dum(1),dum(1),-1, &
                           ierr)
                 lwork_qgebrd_nn = int(dum(1),KIND=ilp)
                 call la_qgeqrf(m,n,dum(1),m,dum(1),dum(1),-1,ierr)
                 lwork_qgeqrf_mn = int(dum(1),KIND=ilp)
                 call la_qorgbr('Q',n,n,n,dum(1),n,dum(1),dum(1),-1,ierr)
                 lwork_qorgbr_q_nn = int(dum(1),KIND=ilp)
                 call la_qorgqr(m,m,n,dum(1),m,dum(1),dum(1),-1,ierr)
                 lwork_qorgqr_mm = int(dum(1),KIND=ilp)
                 call la_qorgqr(m,n,n,dum(1),m,dum(1),dum(1),-1,ierr)
                 lwork_qorgqr_mn = int(dum(1),KIND=ilp)
                 call la_qormbr('P','R','T',n,n,n,dum(1),n,dum(1),dum(1),n,dum(1), &
                           -1,ierr)
                 lwork_qormbr_prt_nn = int(dum(1),KIND=ilp)
                 call la_qormbr('Q','L','N',n,n,n,dum(1),n,dum(1),dum(1),n,dum(1), &
                           -1,ierr)
                 lwork_qormbr_qln_nn = int(dum(1),KIND=ilp)
                 call la_qormbr('Q','L','N',m,n,n,dum(1),m,dum(1),dum(1),m,dum(1), &
                           -1,ierr)
                 lwork_qormbr_qln_mn = int(dum(1),KIND=ilp)
                 call la_qormbr('Q','L','N',m,m,n,dum(1),m,dum(1),dum(1),m,dum(1), &
                           -1,ierr)
                 lwork_qormbr_qln_mm = int(dum(1),KIND=ilp)
                 if (m >= mnthr) then
                    if (wntqn) then
                       ! path 1 (m >> n, jobz='n')
                       wrkbl = n + lwork_qgeqrf_mn
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd_nn)
                       maxwrk = max(wrkbl,bdspac + n)
                       minwrk = bdspac + n
                    else if (wntqo) then
                       ! path 2 (m >> n, jobz='o')
                       wrkbl = n + lwork_qgeqrf_mn
                       wrkbl = max(wrkbl,n + lwork_qorgqr_mn)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd_nn)
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_qln_nn)
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_prt_nn)
                       wrkbl = max(wrkbl,3*n + bdspac)
                       maxwrk = wrkbl + 2*n*n
                       minwrk = bdspac + 2*n*n + 3*n
                    else if (wntqs) then
                       ! path 3 (m >> n, jobz='s')
                       wrkbl = n + lwork_qgeqrf_mn
                       wrkbl = max(wrkbl,n + lwork_qorgqr_mn)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd_nn)
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_qln_nn)
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_prt_nn)
                       wrkbl = max(wrkbl,3*n + bdspac)
                       maxwrk = wrkbl + n*n
                       minwrk = bdspac + n*n + 3*n
                    else if (wntqa) then
                       ! path 4 (m >> n, jobz='a')
                       wrkbl = n + lwork_qgeqrf_mn
                       wrkbl = max(wrkbl,n + lwork_qorgqr_mm)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd_nn)
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_qln_nn)
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_prt_nn)
                       wrkbl = max(wrkbl,3*n + bdspac)
                       maxwrk = wrkbl + n*n
                       minwrk = n*n + max(3*n + bdspac,n + m)
                    end if
                 else
                    ! path 5 (m >= n, but not much larger)
                    wrkbl = 3*n + lwork_qgebrd_mn
                    if (wntqn) then
                       ! path 5n (m >= n, jobz='n')
                       maxwrk = max(wrkbl,3*n + bdspac)
                       minwrk = 3*n + max(m,bdspac)
                    else if (wntqo) then
                       ! path 5o (m >= n, jobz='o')
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_prt_nn)
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_qln_mn)
                       wrkbl = max(wrkbl,3*n + bdspac)
                       maxwrk = wrkbl + m*n
                       minwrk = 3*n + max(m,n*n + bdspac)
                    else if (wntqs) then
                       ! path 5s (m >= n, jobz='s')
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_qln_mn)
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_prt_nn)
                       maxwrk = max(wrkbl,3*n + bdspac)
                       minwrk = 3*n + max(m,bdspac)
                    else if (wntqa) then
                       ! path 5a (m >= n, jobz='a')
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_qln_mm)
                       wrkbl = max(wrkbl,3*n + lwork_qormbr_prt_nn)
                       maxwrk = max(wrkbl,3*n + bdspac)
                       minwrk = 3*n + max(m,bdspac)
                    end if
                 end if
              else if (minmn > 0) then
                 ! compute space needed for la_qbdsdc
                 if (wntqn) then
                    ! la_qbdsdc needs only 4*n (or 6*n for uplo=l for lapack <= 3.6_qp)
                    ! keep 7*n for backwards compatibility.
                    bdspac = 7*m
                 else
                    bdspac = 3*m*m + 4*m
                 end if
                 ! compute space preferred for each routine
                 call la_qgebrd(m,n,dum(1),m,dum(1),dum(1),dum(1),dum(1),dum(1),-1, &
                           ierr)
                 lwork_qgebrd_mn = int(dum(1),KIND=ilp)
                 call la_qgebrd(m,m,a,m,s,dum(1),dum(1),dum(1),dum(1),-1,ierr)

                 lwork_qgebrd_mm = int(dum(1),KIND=ilp)
                 call la_qgelqf(m,n,a,m,dum(1),dum(1),-1,ierr)
                 lwork_qgelqf_mn = int(dum(1),KIND=ilp)
                 call la_qorglq(n,n,m,dum(1),n,dum(1),dum(1),-1,ierr)
                 lwork_qorglq_nn = int(dum(1),KIND=ilp)
                 call la_qorglq(m,n,m,a,m,dum(1),dum(1),-1,ierr)
                 lwork_qorglq_mn = int(dum(1),KIND=ilp)
                 call la_qorgbr('P',m,m,m,a,n,dum(1),dum(1),-1,ierr)
                 lwork_qorgbr_p_mm = int(dum(1),KIND=ilp)
                 call la_qormbr('P','R','T',m,m,m,dum(1),m,dum(1),dum(1),m,dum(1), &
                           -1,ierr)
                 lwork_qormbr_prt_mm = int(dum(1),KIND=ilp)
                 call la_qormbr('P','R','T',m,n,m,dum(1),m,dum(1),dum(1),m,dum(1), &
                           -1,ierr)
                 lwork_qormbr_prt_mn = int(dum(1),KIND=ilp)
                 call la_qormbr('P','R','T',n,n,m,dum(1),n,dum(1),dum(1),n,dum(1), &
                           -1,ierr)
                 lwork_qormbr_prt_nn = int(dum(1),KIND=ilp)
                 call la_qormbr('Q','L','N',m,m,m,dum(1),m,dum(1),dum(1),m,dum(1), &
                           -1,ierr)
                 lwork_qormbr_qln_mm = int(dum(1),KIND=ilp)
                 if (n >= mnthr) then
                    if (wntqn) then
                       ! path 1t (n >> m, jobz='n')
                       wrkbl = m + lwork_qgelqf_mn
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd_mm)
                       maxwrk = max(wrkbl,bdspac + m)
                       minwrk = bdspac + m
                    else if (wntqo) then
                       ! path 2t (n >> m, jobz='o')
                       wrkbl = m + lwork_qgelqf_mn
                       wrkbl = max(wrkbl,m + lwork_qorglq_mn)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd_mm)
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_qln_mm)
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_prt_mm)
                       wrkbl = max(wrkbl,3*m + bdspac)
                       maxwrk = wrkbl + 2*m*m
                       minwrk = bdspac + 2*m*m + 3*m
                    else if (wntqs) then
                       ! path 3t (n >> m, jobz='s')
                       wrkbl = m + lwork_qgelqf_mn
                       wrkbl = max(wrkbl,m + lwork_qorglq_mn)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd_mm)
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_qln_mm)
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_prt_mm)
                       wrkbl = max(wrkbl,3*m + bdspac)
                       maxwrk = wrkbl + m*m
                       minwrk = bdspac + m*m + 3*m
                    else if (wntqa) then
                       ! path 4t (n >> m, jobz='a')
                       wrkbl = m + lwork_qgelqf_mn
                       wrkbl = max(wrkbl,m + lwork_qorglq_nn)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd_mm)
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_qln_mm)
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_prt_mm)
                       wrkbl = max(wrkbl,3*m + bdspac)
                       maxwrk = wrkbl + m*m
                       minwrk = m*m + max(3*m + bdspac,m + n)
                    end if
                 else
                    ! path 5t (n > m, but not much larger)
                    wrkbl = 3*m + lwork_qgebrd_mn
                    if (wntqn) then
                       ! path 5tn (n > m, jobz='n')
                       maxwrk = max(wrkbl,3*m + bdspac)
                       minwrk = 3*m + max(n,bdspac)
                    else if (wntqo) then
                       ! path 5to (n > m, jobz='o')
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_qln_mm)
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_prt_mn)
                       wrkbl = max(wrkbl,3*m + bdspac)
                       maxwrk = wrkbl + m*n
                       minwrk = 3*m + max(n,m*m + bdspac)
                    else if (wntqs) then
                       ! path 5ts (n > m, jobz='s')
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_qln_mm)
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_prt_mn)
                       maxwrk = max(wrkbl,3*m + bdspac)
                       minwrk = 3*m + max(n,bdspac)
                    else if (wntqa) then
                       ! path 5ta (n > m, jobz='a')
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_qln_mm)
                       wrkbl = max(wrkbl,3*m + lwork_qormbr_prt_nn)
                       maxwrk = max(wrkbl,3*m + bdspac)
                       minwrk = 3*m + max(n,bdspac)
                    end if
                 end if
              end if
              maxwrk = max(maxwrk,minwrk)
              work(1) = la_qroundup_lwork(maxwrk)
              if (lwork < minwrk .and. .not. lquery) then
                 info = -12
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DGESDD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) then
              return
           end if
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = sqrt(la_qlamch('S'))/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',m,n,a,lda,dum)
           if (la_qisnan(anrm)) then
               info = -4
               return
           end if
           iscl = 0
           if (anrm > zero .and. anrm < smlnum) then
              iscl = 1
              call la_qlascl('G',0,0,anrm,smlnum,m,n,a,lda,ierr)
           else if (anrm > bignum) then
              iscl = 1
              call la_qlascl('G',0,0,anrm,bignum,m,n,a,lda,ierr)
           end if
           if (m >= n) then
              ! a has at least as many rows as columns. if a has sufficiently
              ! more rows than columns, first reduce using the qr
              ! decomposition (if sufficient workspace available)
              if (m >= mnthr) then
                 if (wntqn) then
                    ! path 1 (m >> n, jobz='n')
                    ! no singular vectors to be computed
                    itau = 1
                    nwork = itau + n
                    ! compute a=q*r
                    ! workspace: need   n [tau] + n    [work]
                    ! workspace: prefer n [tau] + n*nb [work]
                    call la_qgeqrf(m,n,a,lda,work(itau),work(nwork),lwork - nwork + &
                              1,ierr)
                    ! zero out below r
                    call la_qlaset('L',n - 1,n - 1,zero,zero,a(2,1),lda)
                    ie = 1
                    itauq = ie + n
                    itaup = itauq + n
                    nwork = itaup + n
                    ! bidiagonalize r in a
                    ! workspace: need   3*n [e, tauq, taup] + n      [work]
                    ! workspace: prefer 3*n [e, tauq, taup] + 2*n*nb [work]
                    call la_qgebrd(n,n,a,lda,s,work(ie),work(itauq),work(itaup), &
                              work(nwork),lwork - nwork + 1,ierr)
                    nwork = ie + n
                    ! perform bidiagonal svd, computing singular values only
                    ! workspace: need   n [e] + bdspac
                    call la_qbdsdc('U','N',n,s,work(ie),dum,1,dum,1,dum,idum, &
                              work(nwork),iwork,info)
                 else if (wntqo) then
                    ! path 2 (m >> n, jobz = 'o')
                    ! n left singular vectors to be overwritten on a and
                    ! n right singular vectors to be computed in vt
                    ir = 1
                    ! work(ir) is ldwrkr by n
                    if (lwork >= lda*n + n*n + 3*n + bdspac) then
                       ldwrkr = lda
                    else
                       ldwrkr = (lwork - n*n - 3*n - bdspac)/n
                    end if
                    itau = ir + ldwrkr*n
                    nwork = itau + n
                    ! compute a=q*r
                    ! workspace: need   n*n [r] + n [tau] + n    [work]
                    ! workspace: prefer n*n [r] + n [tau] + n*nb [work]
                    call la_qgeqrf(m,n,a,lda,work(itau),work(nwork),lwork - nwork + &
                              1,ierr)
                    ! copy r to work(ir), zeroing out below it
                    call la_qlacpy('U',n,n,a,lda,work(ir),ldwrkr)
                    call la_qlaset('L',n - 1,n - 1,zero,zero,work(ir + 1),ldwrkr)
                    ! generate q in a
                    ! workspace: need   n*n [r] + n [tau] + n    [work]
                    ! workspace: prefer n*n [r] + n [tau] + n*nb [work]
                    call la_qorgqr(m,n,n,a,lda,work(itau),work(nwork),lwork - &
                              nwork + 1,ierr)
                    ie = itau
                    itauq = ie + n
                    itaup = itauq + n
                    nwork = itaup + n
                    ! bidiagonalize r in work(ir)
                    ! workspace: need   n*n [r] + 3*n [e, tauq, taup] + n      [work]
                    ! workspace: prefer n*n [r] + 3*n [e, tauq, taup] + 2*n*nb [work]
                    call la_qgebrd(n,n,work(ir),ldwrkr,s,work(ie),work(itauq), &
                              work(itaup),work(nwork),lwork - nwork + 1,ierr)
                    ! work(iu) is n by n
                    iu = nwork
                    nwork = iu + n*n
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in work(iu) and computing right
                    ! singular vectors of bidiagonal matrix in vt
                    ! workspace: need   n*n [r] + 3*n [e, tauq, taup] + n*n [u] + bdspac
                    call la_qbdsdc('U','I',n,s,work(ie),work(iu),n,vt,ldvt,dum, &
                              idum,work(nwork),iwork,info)
                    ! overwrite work(iu) by left singular vectors of r
                    ! and vt by right singular vectors of r
                    ! workspace: need   n*n [r] + 3*n [e, tauq, taup] + n*n [u] + n    [work]
                    ! workspace: prefer n*n [r] + 3*n [e, tauq, taup] + n*n [u] + n*nb [work]
                    call la_qormbr('Q','L','N',n,n,n,work(ir),ldwrkr,work(itauq), &
                              work(iu),n,work(nwork),lwork - nwork + 1,ierr)
                    call la_qormbr('P','R','T',n,n,n,work(ir),ldwrkr,work(itaup), &
                              vt,ldvt,work(nwork),lwork - nwork + 1,ierr)
                    ! multiply q in a by left singular vectors of r in
                    ! work(iu), storing result in work(ir) and copying to a
                    ! workspace: need   n*n [r] + 3*n [e, tauq, taup] + n*n [u]
                    ! workspace: prefer m*n [r] + 3*n [e, tauq, taup] + n*n [u]
                    do i = 1,m,ldwrkr
                       chunk = min(m - i + 1,ldwrkr)
                       call la_qgemm('N','N',chunk,n,n,one,a(i,1),lda,work(iu), &
                                 n,zero,work(ir),ldwrkr)
                       call la_qlacpy('F',chunk,n,work(ir),ldwrkr,a(i,1),lda)

                    end do
                 else if (wntqs) then
                    ! path 3 (m >> n, jobz='s')
                    ! n left singular vectors to be computed in u and
                    ! n right singular vectors to be computed in vt
                    ir = 1
                    ! work(ir) is n by n
                    ldwrkr = n
                    itau = ir + ldwrkr*n
                    nwork = itau + n
                    ! compute a=q*r
                    ! workspace: need   n*n [r] + n [tau] + n    [work]
                    ! workspace: prefer n*n [r] + n [tau] + n*nb [work]
                    call la_qgeqrf(m,n,a,lda,work(itau),work(nwork),lwork - nwork + &
                              1,ierr)
                    ! copy r to work(ir), zeroing out below it
                    call la_qlacpy('U',n,n,a,lda,work(ir),ldwrkr)
                    call la_qlaset('L',n - 1,n - 1,zero,zero,work(ir + 1),ldwrkr)
                    ! generate q in a
                    ! workspace: need   n*n [r] + n [tau] + n    [work]
                    ! workspace: prefer n*n [r] + n [tau] + n*nb [work]
                    call la_qorgqr(m,n,n,a,lda,work(itau),work(nwork),lwork - &
                              nwork + 1,ierr)
                    ie = itau
                    itauq = ie + n
                    itaup = itauq + n
                    nwork = itaup + n
                    ! bidiagonalize r in work(ir)
                    ! workspace: need   n*n [r] + 3*n [e, tauq, taup] + n      [work]
                    ! workspace: prefer n*n [r] + 3*n [e, tauq, taup] + 2*n*nb [work]
                    call la_qgebrd(n,n,work(ir),ldwrkr,s,work(ie),work(itauq), &
                              work(itaup),work(nwork),lwork - nwork + 1,ierr)
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagoal matrix in u and computing right singular
                    ! vectors of bidiagonal matrix in vt
                    ! workspace: need   n*n [r] + 3*n [e, tauq, taup] + bdspac
                    call la_qbdsdc('U','I',n,s,work(ie),u,ldu,vt,ldvt,dum,idum, &
                              work(nwork),iwork,info)
                    ! overwrite u by left singular vectors of r and vt
                    ! by right singular vectors of r
                    ! workspace: need   n*n [r] + 3*n [e, tauq, taup] + n    [work]
                    ! workspace: prefer n*n [r] + 3*n [e, tauq, taup] + n*nb [work]
                    call la_qormbr('Q','L','N',n,n,n,work(ir),ldwrkr,work(itauq), &
                              u,ldu,work(nwork),lwork - nwork + 1,ierr)
                    call la_qormbr('P','R','T',n,n,n,work(ir),ldwrkr,work(itaup), &
                              vt,ldvt,work(nwork),lwork - nwork + 1,ierr)
                    ! multiply q in a by left singular vectors of r in
                    ! work(ir), storing result in u
                    ! workspace: need   n*n [r]
                    call la_qlacpy('F',n,n,u,ldu,work(ir),ldwrkr)
                    call la_qgemm('N','N',m,n,n,one,a,lda,work(ir),ldwrkr,zero,u, &
                               ldu)
                 else if (wntqa) then
                    ! path 4 (m >> n, jobz='a')
                    ! m left singular vectors to be computed in u and
                    ! n right singular vectors to be computed in vt
                    iu = 1
                    ! work(iu) is n by n
                    ldwrku = n
                    itau = iu + ldwrku*n
                    nwork = itau + n
                    ! compute a=q*r, copying result to u
                    ! workspace: need   n*n [u] + n [tau] + n    [work]
                    ! workspace: prefer n*n [u] + n [tau] + n*nb [work]
                    call la_qgeqrf(m,n,a,lda,work(itau),work(nwork),lwork - nwork + &
                              1,ierr)
                    call la_qlacpy('L',m,n,a,lda,u,ldu)
                    ! generate q in u
                    ! workspace: need   n*n [u] + n [tau] + m    [work]
                    ! workspace: prefer n*n [u] + n [tau] + m*nb [work]
                    call la_qorgqr(m,m,n,u,ldu,work(itau),work(nwork),lwork - &
                              nwork + 1,ierr)
                    ! produce r in a, zeroing out other entries
                    call la_qlaset('L',n - 1,n - 1,zero,zero,a(2,1),lda)
                    ie = itau
                    itauq = ie + n
                    itaup = itauq + n
                    nwork = itaup + n
                    ! bidiagonalize r in a
                    ! workspace: need   n*n [u] + 3*n [e, tauq, taup] + n      [work]
                    ! workspace: prefer n*n [u] + 3*n [e, tauq, taup] + 2*n*nb [work]
                    call la_qgebrd(n,n,a,lda,s,work(ie),work(itauq),work(itaup), &
                              work(nwork),lwork - nwork + 1,ierr)
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in work(iu) and computing right
                    ! singular vectors of bidiagonal matrix in vt
                    ! workspace: need   n*n [u] + 3*n [e, tauq, taup] + bdspac
                    call la_qbdsdc('U','I',n,s,work(ie),work(iu),n,vt,ldvt,dum, &
                              idum,work(nwork),iwork,info)
                    ! overwrite work(iu) by left singular vectors of r and vt
                    ! by right singular vectors of r
                    ! workspace: need   n*n [u] + 3*n [e, tauq, taup] + n    [work]
                    ! workspace: prefer n*n [u] + 3*n [e, tauq, taup] + n*nb [work]
                    call la_qormbr('Q','L','N',n,n,n,a,lda,work(itauq),work(iu), &
                              ldwrku,work(nwork),lwork - nwork + 1,ierr)
                    call la_qormbr('P','R','T',n,n,n,a,lda,work(itaup),vt,ldvt, &
                              work(nwork),lwork - nwork + 1,ierr)
                    ! multiply q in u by left singular vectors of r in
                    ! work(iu), storing result in a
                    ! workspace: need   n*n [u]
                    call la_qgemm('N','N',m,n,n,one,u,ldu,work(iu),ldwrku,zero,a, &
                               lda)
                    ! copy left singular vectors of a from a to u
                    call la_qlacpy('F',m,n,a,lda,u,ldu)
                 end if
              else
                 ! m < mnthr
                 ! path 5 (m >= n, but not much larger)
                 ! reduce to bidiagonal form without qr decomposition
                 ie = 1
                 itauq = ie + n
                 itaup = itauq + n
                 nwork = itaup + n
                 ! bidiagonalize a
                 ! workspace: need   3*n [e, tauq, taup] + m        [work]
                 ! workspace: prefer 3*n [e, tauq, taup] + (m+n)*nb [work]
                 call la_qgebrd(m,n,a,lda,s,work(ie),work(itauq),work(itaup), &
                           work(nwork),lwork - nwork + 1,ierr)
                 if (wntqn) then
                    ! path 5n (m >= n, jobz='n')
                    ! perform bidiagonal svd, only computing singular values
                    ! workspace: need   3*n [e, tauq, taup] + bdspac
                    call la_qbdsdc('U','N',n,s,work(ie),dum,1,dum,1,dum,idum, &
                              work(nwork),iwork,info)
                 else if (wntqo) then
                    ! path 5o (m >= n, jobz='o')
                    iu = nwork
                    if (lwork >= m*n + 3*n + bdspac) then
                       ! work( iu ) is m by n
                       ldwrku = m
                       nwork = iu + ldwrku*n
                       call la_qlaset('F',m,n,zero,zero,work(iu),ldwrku)
                       ! ir is unused; silence compile warnings
                       ir = -1
                    else
                       ! work( iu ) is n by n
                       ldwrku = n
                       nwork = iu + ldwrku*n
                       ! work(ir) is ldwrkr by n
                       ir = nwork
                       ldwrkr = (lwork - n*n - 3*n)/n
                    end if
                    nwork = iu + ldwrku*n
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in work(iu) and computing right
                    ! singular vectors of bidiagonal matrix in vt
                    ! workspace: need   3*n [e, tauq, taup] + n*n [u] + bdspac
                    call la_qbdsdc('U','I',n,s,work(ie),work(iu),ldwrku,vt,ldvt, &
                              dum,idum,work(nwork),iwork,info)
                    ! overwrite vt by right singular vectors of a
                    ! workspace: need   3*n [e, tauq, taup] + n*n [u] + n    [work]
                    ! workspace: prefer 3*n [e, tauq, taup] + n*n [u] + n*nb [work]
                    call la_qormbr('P','R','T',n,n,n,a,lda,work(itaup),vt,ldvt, &
                              work(nwork),lwork - nwork + 1,ierr)
                    if (lwork >= m*n + 3*n + bdspac) then
                       ! path 5o-fast
                       ! overwrite work(iu) by left singular vectors of a
                       ! workspace: need   3*n [e, tauq, taup] + m*n [u] + n    [work]
                       ! workspace: prefer 3*n [e, tauq, taup] + m*n [u] + n*nb [work]
                       call la_qormbr('Q','L','N',m,n,n,a,lda,work(itauq),work(iu &
                                 ),ldwrku,work(nwork),lwork - nwork + 1,ierr)
                       ! copy left singular vectors of a from work(iu) to a
                       call la_qlacpy('F',m,n,work(iu),ldwrku,a,lda)
                    else
                       ! path 5o-slow
                       ! generate q in a
                       ! workspace: need   3*n [e, tauq, taup] + n*n [u] + n    [work]
                       ! workspace: prefer 3*n [e, tauq, taup] + n*n [u] + n*nb [work]
                       call la_qorgbr('Q',m,n,n,a,lda,work(itauq),work(nwork), &
                                 lwork - nwork + 1,ierr)
                       ! multiply q in a by left singular vectors of
                       ! bidiagonal matrix in work(iu), storing result in
                       ! work(ir) and copying to a
                       ! workspace: need   3*n [e, tauq, taup] + n*n [u] + nb*n [r]
                       ! workspace: prefer 3*n [e, tauq, taup] + n*n [u] + m*n  [r]
                       do i = 1,m,ldwrkr
                          chunk = min(m - i + 1,ldwrkr)
                          call la_qgemm('N','N',chunk,n,n,one,a(i,1),lda,work(iu) &
                                    ,ldwrku,zero,work(ir),ldwrkr)
                          call la_qlacpy('F',chunk,n,work(ir),ldwrkr,a(i,1),lda)

                       end do
                    end if
                 else if (wntqs) then
                    ! path 5s (m >= n, jobz='s')
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in u and computing right singular
                    ! vectors of bidiagonal matrix in vt
                    ! workspace: need   3*n [e, tauq, taup] + bdspac
                    call la_qlaset('F',m,n,zero,zero,u,ldu)
                    call la_qbdsdc('U','I',n,s,work(ie),u,ldu,vt,ldvt,dum,idum, &
                              work(nwork),iwork,info)
                    ! overwrite u by left singular vectors of a and vt
                    ! by right singular vectors of a
                    ! workspace: need   3*n [e, tauq, taup] + n    [work]
                    ! workspace: prefer 3*n [e, tauq, taup] + n*nb [work]
                    call la_qormbr('Q','L','N',m,n,n,a,lda,work(itauq),u,ldu, &
                              work(nwork),lwork - nwork + 1,ierr)
                    call la_qormbr('P','R','T',n,n,n,a,lda,work(itaup),vt,ldvt, &
                              work(nwork),lwork - nwork + 1,ierr)
                 else if (wntqa) then
                    ! path 5a (m >= n, jobz='a')
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in u and computing right singular
                    ! vectors of bidiagonal matrix in vt
                    ! workspace: need   3*n [e, tauq, taup] + bdspac
                    call la_qlaset('F',m,m,zero,zero,u,ldu)
                    call la_qbdsdc('U','I',n,s,work(ie),u,ldu,vt,ldvt,dum,idum, &
                              work(nwork),iwork,info)
                    ! set the right corner of u to identity matrix
                    if (m > n) then
                       call la_qlaset('F',m - n,m - n,zero,one,u(n + 1,n + 1),ldu)
                    end if
                    ! overwrite u by left singular vectors of a and vt
                    ! by right singular vectors of a
                    ! workspace: need   3*n [e, tauq, taup] + m    [work]
                    ! workspace: prefer 3*n [e, tauq, taup] + m*nb [work]
                    call la_qormbr('Q','L','N',m,m,n,a,lda,work(itauq),u,ldu, &
                              work(nwork),lwork - nwork + 1,ierr)
                    call la_qormbr('P','R','T',n,n,m,a,lda,work(itaup),vt,ldvt, &
                              work(nwork),lwork - nwork + 1,ierr)
                 end if
              end if
           else
              ! a has more columns than rows. if a has sufficiently more
              ! columns than rows, first reduce using the lq decomposition (if
              ! sufficient workspace available)
              if (n >= mnthr) then
                 if (wntqn) then
                    ! path 1t (n >> m, jobz='n')
                    ! no singular vectors to be computed
                    itau = 1
                    nwork = itau + m
                    ! compute a=l*q
                    ! workspace: need   m [tau] + m [work]
                    ! workspace: prefer m [tau] + m*nb [work]
                    call la_qgelqf(m,n,a,lda,work(itau),work(nwork),lwork - nwork + &
                              1,ierr)
                    ! zero out above l
                    call la_qlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                    ie = 1
                    itauq = ie + m
                    itaup = itauq + m
                    nwork = itaup + m
                    ! bidiagonalize l in a
                    ! workspace: need   3*m [e, tauq, taup] + m      [work]
                    ! workspace: prefer 3*m [e, tauq, taup] + 2*m*nb [work]
                    call la_qgebrd(m,m,a,lda,s,work(ie),work(itauq),work(itaup), &
                              work(nwork),lwork - nwork + 1,ierr)
                    nwork = ie + m
                    ! perform bidiagonal svd, computing singular values only
                    ! workspace: need   m [e] + bdspac
                    call la_qbdsdc('U','N',m,s,work(ie),dum,1,dum,1,dum,idum, &
                              work(nwork),iwork,info)
                 else if (wntqo) then
                    ! path 2t (n >> m, jobz='o')
                    ! m right singular vectors to be overwritten on a and
                    ! m left singular vectors to be computed in u
                    ivt = 1
                    ! work(ivt) is m by m
                    ! work(il)  is m by m; it is later resized to m by chunk for gemm
                    il = ivt + m*m
                    if (lwork >= m*n + m*m + 3*m + bdspac) then
                       ldwrkl = m
                       chunk = n
                    else
                       ldwrkl = m
                       chunk = (lwork - m*m)/m
                    end if
                    itau = il + ldwrkl*m
                    nwork = itau + m
                    ! compute a=l*q
                    ! workspace: need   m*m [vt] + m*m [l] + m [tau] + m    [work]
                    ! workspace: prefer m*m [vt] + m*m [l] + m [tau] + m*nb [work]
                    call la_qgelqf(m,n,a,lda,work(itau),work(nwork),lwork - nwork + &
                              1,ierr)
                    ! copy l to work(il), zeroing about above it
                    call la_qlacpy('L',m,m,a,lda,work(il),ldwrkl)
                    call la_qlaset('U',m - 1,m - 1,zero,zero,work(il + ldwrkl),ldwrkl &
                              )
                    ! generate q in a
                    ! workspace: need   m*m [vt] + m*m [l] + m [tau] + m    [work]
                    ! workspace: prefer m*m [vt] + m*m [l] + m [tau] + m*nb [work]
                    call la_qorglq(m,n,m,a,lda,work(itau),work(nwork),lwork - &
                              nwork + 1,ierr)
                    ie = itau
                    itauq = ie + m
                    itaup = itauq + m
                    nwork = itaup + m
                    ! bidiagonalize l in work(il)
                    ! workspace: need   m*m [vt] + m*m [l] + 3*m [e, tauq, taup] + m      [work]
                    ! workspace: prefer m*m [vt] + m*m [l] + 3*m [e, tauq, taup] + 2*m*nb [work]
                    call la_qgebrd(m,m,work(il),ldwrkl,s,work(ie),work(itauq), &
                              work(itaup),work(nwork),lwork - nwork + 1,ierr)
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in u, and computing right singular
                    ! vectors of bidiagonal matrix in work(ivt)
                    ! workspace: need   m*m [vt] + m*m [l] + 3*m [e, tauq, taup] + bdspac
                    call la_qbdsdc('U','I',m,s,work(ie),u,ldu,work(ivt),m,dum, &
                              idum,work(nwork),iwork,info)
                    ! overwrite u by left singular vectors of l and work(ivt)
                    ! by right singular vectors of l
                    ! workspace: need   m*m [vt] + m*m [l] + 3*m [e, tauq, taup] + m    [work]
                    ! workspace: prefer m*m [vt] + m*m [l] + 3*m [e, tauq, taup] + m*nb [work]
                    call la_qormbr('Q','L','N',m,m,m,work(il),ldwrkl,work(itauq), &
                              u,ldu,work(nwork),lwork - nwork + 1,ierr)
                    call la_qormbr('P','R','T',m,m,m,work(il),ldwrkl,work(itaup), &
                              work(ivt),m,work(nwork),lwork - nwork + 1,ierr)
                    ! multiply right singular vectors of l in work(ivt) by q
                    ! in a, storing result in work(il) and copying to a
                    ! workspace: need   m*m [vt] + m*m [l]
                    ! workspace: prefer m*m [vt] + m*n [l]
                    ! at this point, l is resized as m by chunk.
                    do i = 1,n,chunk
                       blk = min(n - i + 1,chunk)
                       call la_qgemm('N','N',m,blk,m,one,work(ivt),m,a(1,i),lda, &
                                  zero,work(il),ldwrkl)
                       call la_qlacpy('F',m,blk,work(il),ldwrkl,a(1,i),lda)

                    end do
                 else if (wntqs) then
                    ! path 3t (n >> m, jobz='s')
                    ! m right singular vectors to be computed in vt and
                    ! m left singular vectors to be computed in u
                    il = 1
                    ! work(il) is m by m
                    ldwrkl = m
                    itau = il + ldwrkl*m
                    nwork = itau + m
                    ! compute a=l*q
                    ! workspace: need   m*m [l] + m [tau] + m    [work]
                    ! workspace: prefer m*m [l] + m [tau] + m*nb [work]
                    call la_qgelqf(m,n,a,lda,work(itau),work(nwork),lwork - nwork + &
                              1,ierr)
                    ! copy l to work(il), zeroing out above it
                    call la_qlacpy('L',m,m,a,lda,work(il),ldwrkl)
                    call la_qlaset('U',m - 1,m - 1,zero,zero,work(il + ldwrkl),ldwrkl &
                              )
                    ! generate q in a
                    ! workspace: need   m*m [l] + m [tau] + m    [work]
                    ! workspace: prefer m*m [l] + m [tau] + m*nb [work]
                    call la_qorglq(m,n,m,a,lda,work(itau),work(nwork),lwork - &
                              nwork + 1,ierr)
                    ie = itau
                    itauq = ie + m
                    itaup = itauq + m
                    nwork = itaup + m
                    ! bidiagonalize l in work(iu).
                    ! workspace: need   m*m [l] + 3*m [e, tauq, taup] + m      [work]
                    ! workspace: prefer m*m [l] + 3*m [e, tauq, taup] + 2*m*nb [work]
                    call la_qgebrd(m,m,work(il),ldwrkl,s,work(ie),work(itauq), &
                              work(itaup),work(nwork),lwork - nwork + 1,ierr)
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in u and computing right singular
                    ! vectors of bidiagonal matrix in vt
                    ! workspace: need   m*m [l] + 3*m [e, tauq, taup] + bdspac
                    call la_qbdsdc('U','I',m,s,work(ie),u,ldu,vt,ldvt,dum,idum, &
                              work(nwork),iwork,info)
                    ! overwrite u by left singular vectors of l and vt
                    ! by right singular vectors of l
                    ! workspace: need   m*m [l] + 3*m [e, tauq, taup] + m    [work]
                    ! workspace: prefer m*m [l] + 3*m [e, tauq, taup] + m*nb [work]
                    call la_qormbr('Q','L','N',m,m,m,work(il),ldwrkl,work(itauq), &
                              u,ldu,work(nwork),lwork - nwork + 1,ierr)
                    call la_qormbr('P','R','T',m,m,m,work(il),ldwrkl,work(itaup), &
                              vt,ldvt,work(nwork),lwork - nwork + 1,ierr)
                    ! multiply right singular vectors of l in work(il) by
                    ! q in a, storing result in vt
                    ! workspace: need   m*m [l]
                    call la_qlacpy('F',m,m,vt,ldvt,work(il),ldwrkl)
                    call la_qgemm('N','N',m,n,m,one,work(il),ldwrkl,a,lda,zero, &
                              vt,ldvt)
                 else if (wntqa) then
                    ! path 4t (n >> m, jobz='a')
                    ! n right singular vectors to be computed in vt and
                    ! m left singular vectors to be computed in u
                    ivt = 1
                    ! work(ivt) is m by m
                    ldwkvt = m
                    itau = ivt + ldwkvt*m
                    nwork = itau + m
                    ! compute a=l*q, copying result to vt
                    ! workspace: need   m*m [vt] + m [tau] + m    [work]
                    ! workspace: prefer m*m [vt] + m [tau] + m*nb [work]
                    call la_qgelqf(m,n,a,lda,work(itau),work(nwork),lwork - nwork + &
                              1,ierr)
                    call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                    ! generate q in vt
                    ! workspace: need   m*m [vt] + m [tau] + n    [work]
                    ! workspace: prefer m*m [vt] + m [tau] + n*nb [work]
                    call la_qorglq(n,n,m,vt,ldvt,work(itau),work(nwork),lwork - &
                              nwork + 1,ierr)
                    ! produce l in a, zeroing out other entries
                    call la_qlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                    ie = itau
                    itauq = ie + m
                    itaup = itauq + m
                    nwork = itaup + m
                    ! bidiagonalize l in a
                    ! workspace: need   m*m [vt] + 3*m [e, tauq, taup] + m      [work]
                    ! workspace: prefer m*m [vt] + 3*m [e, tauq, taup] + 2*m*nb [work]
                    call la_qgebrd(m,m,a,lda,s,work(ie),work(itauq),work(itaup), &
                              work(nwork),lwork - nwork + 1,ierr)
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in u and computing right singular
                    ! vectors of bidiagonal matrix in work(ivt)
                    ! workspace: need   m*m [vt] + 3*m [e, tauq, taup] + bdspac
                    call la_qbdsdc('U','I',m,s,work(ie),u,ldu,work(ivt),ldwkvt, &
                              dum,idum,work(nwork),iwork,info)
                    ! overwrite u by left singular vectors of l and work(ivt)
                    ! by right singular vectors of l
                    ! workspace: need   m*m [vt] + 3*m [e, tauq, taup]+ m    [work]
                    ! workspace: prefer m*m [vt] + 3*m [e, tauq, taup]+ m*nb [work]
                    call la_qormbr('Q','L','N',m,m,m,a,lda,work(itauq),u,ldu, &
                              work(nwork),lwork - nwork + 1,ierr)
                    call la_qormbr('P','R','T',m,m,m,a,lda,work(itaup),work(ivt), &
                               ldwkvt,work(nwork),lwork - nwork + 1,ierr)
                    ! multiply right singular vectors of l in work(ivt) by
                    ! q in vt, storing result in a
                    ! workspace: need   m*m [vt]
                    call la_qgemm('N','N',m,n,m,one,work(ivt),ldwkvt,vt,ldvt,zero, &
                               a,lda)
                    ! copy right singular vectors of a from a to vt
                    call la_qlacpy('F',m,n,a,lda,vt,ldvt)
                 end if
              else
                 ! n < mnthr
                 ! path 5t (n > m, but not much larger)
                 ! reduce to bidiagonal form without lq decomposition
                 ie = 1
                 itauq = ie + m
                 itaup = itauq + m
                 nwork = itaup + m
                 ! bidiagonalize a
                 ! workspace: need   3*m [e, tauq, taup] + n        [work]
                 ! workspace: prefer 3*m [e, tauq, taup] + (m+n)*nb [work]
                 call la_qgebrd(m,n,a,lda,s,work(ie),work(itauq),work(itaup), &
                           work(nwork),lwork - nwork + 1,ierr)
                 if (wntqn) then
                    ! path 5tn (n > m, jobz='n')
                    ! perform bidiagonal svd, only computing singular values
                    ! workspace: need   3*m [e, tauq, taup] + bdspac
                    call la_qbdsdc('L','N',m,s,work(ie),dum,1,dum,1,dum,idum, &
                              work(nwork),iwork,info)
                 else if (wntqo) then
                    ! path 5to (n > m, jobz='o')
                    ldwkvt = m
                    ivt = nwork
                    if (lwork >= m*n + 3*m + bdspac) then
                       ! work( ivt ) is m by n
                       call la_qlaset('F',m,n,zero,zero,work(ivt),ldwkvt)
                       nwork = ivt + ldwkvt*n
                       ! il is unused; silence compile warnings
                       il = -1
                    else
                       ! work( ivt ) is m by m
                       nwork = ivt + ldwkvt*m
                       il = nwork
                       ! work(il) is m by chunk
                       chunk = (lwork - m*m - 3*m)/m
                    end if
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in u and computing right singular
                    ! vectors of bidiagonal matrix in work(ivt)
                    ! workspace: need   3*m [e, tauq, taup] + m*m [vt] + bdspac
                    call la_qbdsdc('L','I',m,s,work(ie),u,ldu,work(ivt),ldwkvt, &
                              dum,idum,work(nwork),iwork,info)
                    ! overwrite u by left singular vectors of a
                    ! workspace: need   3*m [e, tauq, taup] + m*m [vt] + m    [work]
                    ! workspace: prefer 3*m [e, tauq, taup] + m*m [vt] + m*nb [work]
                    call la_qormbr('Q','L','N',m,m,n,a,lda,work(itauq),u,ldu, &
                              work(nwork),lwork - nwork + 1,ierr)
                    if (lwork >= m*n + 3*m + bdspac) then
                       ! path 5to-fast
                       ! overwrite work(ivt) by left singular vectors of a
                       ! workspace: need   3*m [e, tauq, taup] + m*n [vt] + m    [work]
                       ! workspace: prefer 3*m [e, tauq, taup] + m*n [vt] + m*nb [work]
                       call la_qormbr('P','R','T',m,n,m,a,lda,work(itaup),work( &
                                 ivt),ldwkvt,work(nwork),lwork - nwork + 1,ierr)
                       ! copy right singular vectors of a from work(ivt) to a
                       call la_qlacpy('F',m,n,work(ivt),ldwkvt,a,lda)
                    else
                       ! path 5to-slow
                       ! generate p**t in a
                       ! workspace: need   3*m [e, tauq, taup] + m*m [vt] + m    [work]
                       ! workspace: prefer 3*m [e, tauq, taup] + m*m [vt] + m*nb [work]
                       call la_qorgbr('P',m,n,m,a,lda,work(itaup),work(nwork), &
                                 lwork - nwork + 1,ierr)
                       ! multiply q in a by right singular vectors of
                       ! bidiagonal matrix in work(ivt), storing result in
                       ! work(il) and copying to a
                       ! workspace: need   3*m [e, tauq, taup] + m*m [vt] + m*nb [l]
                       ! workspace: prefer 3*m [e, tauq, taup] + m*m [vt] + m*n  [l]
                       do i = 1,n,chunk
                          blk = min(n - i + 1,chunk)
                          call la_qgemm('N','N',m,blk,m,one,work(ivt),ldwkvt,a(1, &
                                    i),lda,zero,work(il),m)
                          call la_qlacpy('F',m,blk,work(il),m,a(1,i),lda)
                       end do
                    end if
                 else if (wntqs) then
                    ! path 5ts (n > m, jobz='s')
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in u and computing right singular
                    ! vectors of bidiagonal matrix in vt
                    ! workspace: need   3*m [e, tauq, taup] + bdspac
                    call la_qlaset('F',m,n,zero,zero,vt,ldvt)
                    call la_qbdsdc('L','I',m,s,work(ie),u,ldu,vt,ldvt,dum,idum, &
                              work(nwork),iwork,info)
                    ! overwrite u by left singular vectors of a and vt
                    ! by right singular vectors of a
                    ! workspace: need   3*m [e, tauq, taup] + m    [work]
                    ! workspace: prefer 3*m [e, tauq, taup] + m*nb [work]
                    call la_qormbr('Q','L','N',m,m,n,a,lda,work(itauq),u,ldu, &
                              work(nwork),lwork - nwork + 1,ierr)
                    call la_qormbr('P','R','T',m,n,m,a,lda,work(itaup),vt,ldvt, &
                              work(nwork),lwork - nwork + 1,ierr)
                 else if (wntqa) then
                    ! path 5ta (n > m, jobz='a')
                    ! perform bidiagonal svd, computing left singular vectors
                    ! of bidiagonal matrix in u and computing right singular
                    ! vectors of bidiagonal matrix in vt
                    ! workspace: need   3*m [e, tauq, taup] + bdspac
                    call la_qlaset('F',n,n,zero,zero,vt,ldvt)
                    call la_qbdsdc('L','I',m,s,work(ie),u,ldu,vt,ldvt,dum,idum, &
                              work(nwork),iwork,info)
                    ! set the right corner of vt to identity matrix
                    if (n > m) then
                       call la_qlaset('F',n - m,n - m,zero,one,vt(m + 1,m + 1),ldvt)
                    end if
                    ! overwrite u by left singular vectors of a and vt
                    ! by right singular vectors of a
                    ! workspace: need   3*m [e, tauq, taup] + n    [work]
                    ! workspace: prefer 3*m [e, tauq, taup] + n*nb [work]
                    call la_qormbr('Q','L','N',m,m,n,a,lda,work(itauq),u,ldu, &
                              work(nwork),lwork - nwork + 1,ierr)
                    call la_qormbr('P','R','T',n,n,m,a,lda,work(itaup),vt,ldvt, &
                              work(nwork),lwork - nwork + 1,ierr)
                 end if
              end if
           end if
           ! undo scaling if necessary
           if (iscl == 1) then
              if (anrm > bignum) call la_qlascl('G',0,0,bignum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (anrm < smlnum) call la_qlascl('G',0,0,smlnum,anrm,minmn,1,s,minmn, &
                        ierr)
           end if
           ! return optimal workspace in work(1)
           work(1) = la_qroundup_lwork(maxwrk)
           return
     end subroutine la_qgesdd

     !> DGESVD: computes the singular value decomposition (SVD) of a real
     !> M-by-N matrix A, optionally computing the left and/or right singular
     !> vectors. The SVD is written
     !> A = U * SIGMA * transpose(V)
     !> where SIGMA is an M-by-N matrix which is zero except for its
     !> min(m,n) diagonal elements, U is an M-by-M orthogonal matrix, and
     !> V is an N-by-N orthogonal matrix.  The diagonal elements of SIGMA
     !> are the singular values of A; they are real and non-negative, and
     !> are returned in descending order.  The first min(m,n) columns of
     !> U and V are the left and right singular vectors of A.
     !> Note that the routine returns V**T, not V.

     subroutine la_qgesvd(jobu,jobvt,m,n,a,lda,s,u,ldu,vt,ldvt,work,lwork,info)

        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobu,jobvt
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldu,ldvt,lwork,m,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: s(*),u(ldu,*),vt(ldvt,*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,wntua,wntuas,wntun,wntuo,wntus,wntva,wntvas,wntvn,wntvo, &
                      wntvs
           integer(ilp) :: bdspac,blk,chunk,i,ie,ierr,ir,iscl,itau,itaup,itauq,iu, &
           iwork,ldwrkr,ldwrku,maxwrk,minmn,minwrk,mnthr,ncu,ncvt,nru,nrvt, &
                     wrkbl
           integer(ilp) :: lwork_qgeqrf,lwork_qorgqr_n,lwork_qorgqr_m,lwork_qgebrd, &
                     lwork_qorgbr_p,lwork_qorgbr_q,lwork_qgelqf,lwork_qorglq_n,lwork_qorglq_m
           real(qp) :: anrm,bignum,eps,smlnum
           ! Local Arrays
           real(qp) :: dum(1)
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input arguments
           info = 0
           minmn = min(m,n)
           wntua = la_lsame(jobu,'A')
           wntus = la_lsame(jobu,'S')
           wntuas = wntua .or. wntus
           wntuo = la_lsame(jobu,'O')
           wntun = la_lsame(jobu,'N')
           wntva = la_lsame(jobvt,'A')
           wntvs = la_lsame(jobvt,'S')
           wntvas = wntva .or. wntvs
           wntvo = la_lsame(jobvt,'O')
           wntvn = la_lsame(jobvt,'N')
           lquery = (lwork == -1)
           if (.not. (wntua .or. wntus .or. wntuo .or. wntun)) then
              info = -1
           else if (.not. (wntva .or. wntvs .or. wntvo .or. wntvn) .or. (wntvo .and. wntuo)) &
                     then
              info = -2
           else if (m < 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,m)) then
              info = -6
           else if (ldu < 1 .or. (wntuas .and. ldu < m)) then
              info = -9
           else if (ldvt < 1 .or. (wntva .and. ldvt < n) .or. (wntvs .and. ldvt < minmn)) &
                     then
              info = -11
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv.)
           if (info == 0) then
              minwrk = 1
              maxwrk = 1
              if (m >= n .and. minmn > 0) then
                 ! compute space needed for la_qbdsqr
                 mnthr = la_ilaenv(6,'DGESVD',jobu//jobvt,m,n,0,0)
                 bdspac = 5*n
                 ! compute space needed for la_qgeqrf
                 call la_qgeqrf(m,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_qgeqrf = int(dum(1),KIND=ilp)
                 ! compute space needed for la_qorgqr
                 call la_qorgqr(m,n,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_qorgqr_n = int(dum(1),KIND=ilp)
                 call la_qorgqr(m,m,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_qorgqr_m = int(dum(1),KIND=ilp)
                 ! compute space needed for la_qgebrd
                 call la_qgebrd(n,n,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1,ierr)

                 lwork_qgebrd = int(dum(1),KIND=ilp)
                 ! compute space needed for la_qorgbr p
                 call la_qorgbr('P',n,n,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_qorgbr_p = int(dum(1),KIND=ilp)
                 ! compute space needed for la_qorgbr q
                 call la_qorgbr('Q',n,n,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_qorgbr_q = int(dum(1),KIND=ilp)
                 if (m >= mnthr) then
                    if (wntun) then
                       ! path 1 (m much larger than n, jobu='n')
                       maxwrk = n + lwork_qgeqrf
                       maxwrk = max(maxwrk,3*n + lwork_qgebrd)
                       if (wntvo .or. wntvas) maxwrk = max(maxwrk,3*n + lwork_qorgbr_p)
                       maxwrk = max(maxwrk,bdspac)
                       minwrk = max(4*n,bdspac)
                    else if (wntuo .and. wntvn) then
                       ! path 2 (m much larger than n, jobu='o', jobvt='n')
                       wrkbl = n + lwork_qgeqrf
                       wrkbl = max(wrkbl,n + lwork_qorgqr_n)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = max(n*n + wrkbl,n*n + m*n + n)
                       minwrk = max(3*n + m,bdspac)
                    else if (wntuo .and. wntvas) then
                       ! path 3 (m much larger than n, jobu='o', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_qgeqrf
                       wrkbl = max(wrkbl,n + lwork_qorgqr_n)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = max(n*n + wrkbl,n*n + m*n + n)
                       minwrk = max(3*n + m,bdspac)
                    else if (wntus .and. wntvn) then
                       ! path 4 (m much larger than n, jobu='s', jobvt='n')
                       wrkbl = n + lwork_qgeqrf
                       wrkbl = max(wrkbl,n + lwork_qorgqr_n)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    else if (wntus .and. wntvo) then
                       ! path 5 (m much larger than n, jobu='s', jobvt='o')
                       wrkbl = n + lwork_qgeqrf
                       wrkbl = max(wrkbl,n + lwork_qorgqr_n)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = 2*n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    else if (wntus .and. wntvas) then
                       ! path 6 (m much larger than n, jobu='s', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_qgeqrf
                       wrkbl = max(wrkbl,n + lwork_qorgqr_n)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    else if (wntua .and. wntvn) then
                       ! path 7 (m much larger than n, jobu='a', jobvt='n')
                       wrkbl = n + lwork_qgeqrf
                       wrkbl = max(wrkbl,n + lwork_qorgqr_m)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    else if (wntua .and. wntvo) then
                       ! path 8 (m much larger than n, jobu='a', jobvt='o')
                       wrkbl = n + lwork_qgeqrf
                       wrkbl = max(wrkbl,n + lwork_qorgqr_m)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = 2*n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    else if (wntua .and. wntvas) then
                       ! path 9 (m much larger than n, jobu='a', jobvt='s' or
                       ! 'a')
                       wrkbl = n + lwork_qgeqrf
                       wrkbl = max(wrkbl,n + lwork_qorgqr_m)
                       wrkbl = max(wrkbl,3*n + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,3*n + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = n*n + wrkbl
                       minwrk = max(3*n + m,bdspac)
                    end if
                 else
                    ! path 10 (m at least n, but not much larger)
                    call la_qgebrd(m,n,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1,ierr)

                    lwork_qgebrd = int(dum(1),KIND=ilp)
                    maxwrk = 3*n + lwork_qgebrd
                    if (wntus .or. wntuo) then
                       call la_qorgbr('Q',m,n,n,a,lda,dum(1),dum(1),-1,ierr)
                       lwork_qorgbr_q = int(dum(1),KIND=ilp)
                       maxwrk = max(maxwrk,3*n + lwork_qorgbr_q)
                    end if
                    if (wntua) then
                       call la_qorgbr('Q',m,m,n,a,lda,dum(1),dum(1),-1,ierr)
                       lwork_qorgbr_q = int(dum(1),KIND=ilp)
                       maxwrk = max(maxwrk,3*n + lwork_qorgbr_q)
                    end if
                    if (.not. wntvn) then
                      maxwrk = max(maxwrk,3*n + lwork_qorgbr_p)
                    end if
                    maxwrk = max(maxwrk,bdspac)
                    minwrk = max(3*n + m,bdspac)
                 end if
              else if (minmn > 0) then
                 ! compute space needed for la_qbdsqr
                 mnthr = la_ilaenv(6,'DGESVD',jobu//jobvt,m,n,0,0)
                 bdspac = 5*m
                 ! compute space needed for la_qgelqf
                 call la_qgelqf(m,n,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_qgelqf = int(dum(1),KIND=ilp)
                 ! compute space needed for la_qorglq
                 call la_qorglq(n,n,m,dum(1),n,dum(1),dum(1),-1,ierr)
                 lwork_qorglq_n = int(dum(1),KIND=ilp)
                 call la_qorglq(m,n,m,a,lda,dum(1),dum(1),-1,ierr)
                 lwork_qorglq_m = int(dum(1),KIND=ilp)
                 ! compute space needed for la_qgebrd
                 call la_qgebrd(m,m,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1,ierr)

                 lwork_qgebrd = int(dum(1),KIND=ilp)
                  ! compute space needed for la_qorgbr p
                 call la_qorgbr('P',m,m,m,a,n,dum(1),dum(1),-1,ierr)
                 lwork_qorgbr_p = int(dum(1),KIND=ilp)
                 ! compute space needed for la_qorgbr q
                 call la_qorgbr('Q',m,m,m,a,n,dum(1),dum(1),-1,ierr)
                 lwork_qorgbr_q = int(dum(1),KIND=ilp)
                 if (n >= mnthr) then
                    if (wntvn) then
                       ! path 1t(n much larger than m, jobvt='n')
                       maxwrk = m + lwork_qgelqf
                       maxwrk = max(maxwrk,3*m + lwork_qgebrd)
                       if (wntuo .or. wntuas) maxwrk = max(maxwrk,3*m + lwork_qorgbr_q)
                       maxwrk = max(maxwrk,bdspac)
                       minwrk = max(4*m,bdspac)
                    else if (wntvo .and. wntun) then
                       ! path 2t(n much larger than m, jobu='n', jobvt='o')
                       wrkbl = m + lwork_qgelqf
                       wrkbl = max(wrkbl,m + lwork_qorglq_m)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = max(m*m + wrkbl,m*m + m*n + m)
                       minwrk = max(3*m + n,bdspac)
                    else if (wntvo .and. wntuas) then
                       ! path 3t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='o')
                       wrkbl = m + lwork_qgelqf
                       wrkbl = max(wrkbl,m + lwork_qorglq_m)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = max(m*m + wrkbl,m*m + m*n + m)
                       minwrk = max(3*m + n,bdspac)
                    else if (wntvs .and. wntun) then
                       ! path 4t(n much larger than m, jobu='n', jobvt='s')
                       wrkbl = m + lwork_qgelqf
                       wrkbl = max(wrkbl,m + lwork_qorglq_m)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    else if (wntvs .and. wntuo) then
                       ! path 5t(n much larger than m, jobu='o', jobvt='s')
                       wrkbl = m + lwork_qgelqf
                       wrkbl = max(wrkbl,m + lwork_qorglq_m)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = 2*m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    else if (wntvs .and. wntuas) then
                       ! path 6t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='s')
                       wrkbl = m + lwork_qgelqf
                       wrkbl = max(wrkbl,m + lwork_qorglq_m)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    else if (wntva .and. wntun) then
                       ! path 7t(n much larger than m, jobu='n', jobvt='a')
                       wrkbl = m + lwork_qgelqf
                       wrkbl = max(wrkbl,m + lwork_qorglq_n)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    else if (wntva .and. wntuo) then
                       ! path 8t(n much larger than m, jobu='o', jobvt='a')
                       wrkbl = m + lwork_qgelqf
                       wrkbl = max(wrkbl,m + lwork_qorglq_n)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = 2*m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    else if (wntva .and. wntuas) then
                       ! path 9t(n much larger than m, jobu='s' or 'a',
                       ! jobvt='a')
                       wrkbl = m + lwork_qgelqf
                       wrkbl = max(wrkbl,m + lwork_qorglq_n)
                       wrkbl = max(wrkbl,3*m + lwork_qgebrd)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_p)
                       wrkbl = max(wrkbl,3*m + lwork_qorgbr_q)
                       wrkbl = max(wrkbl,bdspac)
                       maxwrk = m*m + wrkbl
                       minwrk = max(3*m + n,bdspac)
                    end if
                 else
                    ! path 10t(n greater than m, but not much larger)
                    call la_qgebrd(m,n,a,lda,s,dum(1),dum(1),dum(1),dum(1),-1,ierr)

                    lwork_qgebrd = int(dum(1),KIND=ilp)
                    maxwrk = 3*m + lwork_qgebrd
                    if (wntvs .or. wntvo) then
                      ! compute space needed for la_qorgbr p
                      call la_qorgbr('P',m,n,m,a,n,dum(1),dum(1),-1,ierr)
                      lwork_qorgbr_p = int(dum(1),KIND=ilp)
                      maxwrk = max(maxwrk,3*m + lwork_qorgbr_p)
                    end if
                    if (wntva) then
                      call la_qorgbr('P',n,n,m,a,n,dum(1),dum(1),-1,ierr)
                      lwork_qorgbr_p = int(dum(1),KIND=ilp)
                      maxwrk = max(maxwrk,3*m + lwork_qorgbr_p)
                    end if
                    if (.not. wntun) then
                       maxwrk = max(maxwrk,3*m + lwork_qorgbr_q)
                    end if
                    maxwrk = max(maxwrk,bdspac)
                    minwrk = max(3*m + n,bdspac)
                 end if
              end if
              maxwrk = max(maxwrk,minwrk)
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) then
                 info = -13
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DGESVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) then
              return
           end if
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = sqrt(la_qlamch('S'))/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',m,n,a,lda,dum)
           iscl = 0
           if (anrm > zero .and. anrm < smlnum) then
              iscl = 1
              call la_qlascl('G',0,0,anrm,smlnum,m,n,a,lda,ierr)
           else if (anrm > bignum) then
              iscl = 1
              call la_qlascl('G',0,0,anrm,bignum,m,n,a,lda,ierr)
           end if
           if (m >= n) then
              ! a has at least as many rows as columns. if a has sufficiently
              ! more rows than columns, first reduce using the qr
              ! decomposition (if sufficient workspace available)
              if (m >= mnthr) then
                 if (wntun) then
                    ! path 1 (m much larger than n, jobu='n')
                    ! no left singular vectors to be computed
                    itau = 1
                    iwork = itau + n
                    ! compute a=q*r
                    ! (workspace: need 2*n, prefer n + n*nb)
                    call la_qgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + 1, &
                              ierr)
                    ! zero out below r
                    if (n > 1) then
                       call la_qlaset('L',n - 1,n - 1,zero,zero,a(2,1),lda)
                    end if
                    ie = 1
                    itauq = ie + n
                    itaup = itauq + n
                    iwork = itaup + n
                    ! bidiagonalize r in a
                    ! (workspace: need 4*n, prefer 3*n + 2*n*nb)
                    call la_qgebrd(n,n,a,lda,s,work(ie),work(itauq),work(itaup), &
                              work(iwork),lwork - iwork + 1,ierr)
                    ncvt = 0
                    if (wntvo .or. wntvas) then
                       ! if right singular vectors desired, generate p'.
                       ! (workspace: need 4*n-1, prefer 3*n + (n-1)*nb)
                       call la_qorgbr('P',n,n,n,a,lda,work(itaup),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       ncvt = n
                    end if
                    iwork = ie + n
                    ! perform bidiagonal qr iteration, computing right
                    ! singular vectors of a in a if desired
                    ! (workspace: need bdspac)
                    call la_qbdsqr('U',n,ncvt,0,0,s,work(ie),a,lda,dum,1,dum,1, &
                              work(iwork),info)
                    ! if right singular vectors desired in vt, copy them there
                    if (wntvas) call la_qlacpy('F',n,n,a,lda,vt,ldvt)
                 else if (wntuo .and. wntvn) then
                    ! path 2 (m much larger than n, jobu='o', jobvt='n')
                    ! n left singular vectors to be overwritten on a and
                    ! no right singular vectors to be computed
                    if (lwork >= n*n + max(4*n,bdspac)) then
                       ! sufficient workspace for a fast algorithm
                       ir = 1
                       if (lwork >= max(wrkbl,lda*n + n) + lda*n) then
                          ! work(iu) is lda by n, work(ir) is lda by n
                          ldwrku = lda
                          ldwrkr = lda
                       else if (lwork >= max(wrkbl,lda*n + n) + n*n) then
                          ! work(iu) is lda by n, work(ir) is n by n
                          ldwrku = lda
                          ldwrkr = n
                       else
                          ! work(iu) is ldwrku by n, work(ir) is n by n
                          ldwrku = (lwork - n*n - n)/n
                          ldwrkr = n
                       end if
                       itau = ir + ldwrkr*n
                       iwork = itau + n
                       ! compute a=q*r
                       ! (workspace: need n*n + 2*n, prefer n*n + n + n*nb)
                       call la_qgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy r to work(ir) and zero out below it
                       call la_qlacpy('U',n,n,a,lda,work(ir),ldwrkr)
                       call la_qlaset('L',n - 1,n - 1,zero,zero,work(ir + 1),ldwrkr)

                       ! generate q in a
                       ! (workspace: need n*n + 2*n, prefer n*n + n + n*nb)
                       call la_qorgqr(m,n,n,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = itau
                       itauq = ie + n
                       itaup = itauq + n
                       iwork = itaup + n
                       ! bidiagonalize r in work(ir)
                       ! (workspace: need n*n + 4*n, prefer n*n + 3*n + 2*n*nb)
                       call la_qgebrd(n,n,work(ir),ldwrkr,s,work(ie),work(itauq), &
                                 work(itaup),work(iwork),lwork - iwork + 1,ierr)
                       ! generate left vectors bidiagonalizing r
                       ! (workspace: need n*n + 4*n, prefer n*n + 3*n + n*nb)
                       call la_qorgbr('Q',n,n,n,work(ir),ldwrkr,work(itauq),work( &
                                 iwork),lwork - iwork + 1,ierr)
                       iwork = ie + n
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of r in work(ir)
                       ! (workspace: need n*n + bdspac)
                       call la_qbdsqr('U',n,0,n,0,s,work(ie),dum,1,work(ir), &
                                 ldwrkr,dum,1,work(iwork),info)
                       iu = ie + n
                       ! multiply q in a by left singular vectors of r in
                       ! work(ir), storing result in work(iu) and copying to a
                       ! (workspace: need n*n + 2*n, prefer n*n + m*n + n)
                       do i = 1,m,ldwrku
                          chunk = min(m - i + 1,ldwrku)
                          call la_qgemm('N','N',chunk,n,n,one,a(i,1),lda,work(ir) &
                                    ,ldwrkr,zero,work(iu),ldwrku)
                          call la_qlacpy('F',chunk,n,work(iu),ldwrku,a(i,1),lda)

                       end do
                    else
                       ! insufficient workspace for a fast algorithm
                       ie = 1
                       itauq = ie + n
                       itaup = itauq + n
                       iwork = itaup + n
                       ! bidiagonalize a
                       ! (workspace: need 3*n + m, prefer 3*n + (m + n)*nb)
                       call la_qgebrd(m,n,a,lda,s,work(ie),work(itauq),work(itaup &
                                 ),work(iwork),lwork - iwork + 1,ierr)
                       ! generate left vectors bidiagonalizing a
                       ! (workspace: need 4*n, prefer 3*n + n*nb)
                       call la_qorgbr('Q',m,n,n,a,lda,work(itauq),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       iwork = ie + n
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of a in a
                       ! (workspace: need bdspac)
                       call la_qbdsqr('U',n,0,m,0,s,work(ie),dum,1,a,lda,dum,1, &
                                 work(iwork),info)
                    end if
                 else if (wntuo .and. wntvas) then
                    ! path 3 (m much larger than n, jobu='o', jobvt='s' or 'a')
                    ! n left singular vectors to be overwritten on a and
                    ! n right singular vectors to be computed in vt
                    if (lwork >= n*n + max(4*n,bdspac)) then
                       ! sufficient workspace for a fast algorithm
                       ir = 1
                       if (lwork >= max(wrkbl,lda*n + n) + lda*n) then
                          ! work(iu) is lda by n and work(ir) is lda by n
                          ldwrku = lda
                          ldwrkr = lda
                       else if (lwork >= max(wrkbl,lda*n + n) + n*n) then
                          ! work(iu) is lda by n and work(ir) is n by n
                          ldwrku = lda
                          ldwrkr = n
                       else
                          ! work(iu) is ldwrku by n and work(ir) is n by n
                          ldwrku = (lwork - n*n - n)/n
                          ldwrkr = n
                       end if
                       itau = ir + ldwrkr*n
                       iwork = itau + n
                       ! compute a=q*r
                       ! (workspace: need n*n + 2*n, prefer n*n + n + n*nb)
                       call la_qgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy r to vt, zeroing out below it
                       call la_qlacpy('U',n,n,a,lda,vt,ldvt)
                       if (n > 1) call la_qlaset('L',n - 1,n - 1,zero,zero,vt(2,1),ldvt)

                       ! generate q in a
                       ! (workspace: need n*n + 2*n, prefer n*n + n + n*nb)
                       call la_qorgqr(m,n,n,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = itau
                       itauq = ie + n
                       itaup = itauq + n
                       iwork = itaup + n
                       ! bidiagonalize r in vt, copying result to work(ir)
                       ! (workspace: need n*n + 4*n, prefer n*n + 3*n + 2*n*nb)
                       call la_qgebrd(n,n,vt,ldvt,s,work(ie),work(itauq),work( &
                                 itaup),work(iwork),lwork - iwork + 1,ierr)
                       call la_qlacpy('L',n,n,vt,ldvt,work(ir),ldwrkr)
                       ! generate left vectors bidiagonalizing r in work(ir)
                       ! (workspace: need n*n + 4*n, prefer n*n + 3*n + n*nb)
                       call la_qorgbr('Q',n,n,n,work(ir),ldwrkr,work(itauq),work( &
                                 iwork),lwork - iwork + 1,ierr)
                       ! generate right vectors bidiagonalizing r in vt
                       ! (workspace: need n*n + 4*n-1, prefer n*n + 3*n + (n-1)*nb)
                       call la_qorgbr('P',n,n,n,vt,ldvt,work(itaup),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       iwork = ie + n
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of r in work(ir) and computing right
                       ! singular vectors of r in vt
                       ! (workspace: need n*n + bdspac)
                       call la_qbdsqr('U',n,n,n,0,s,work(ie),vt,ldvt,work(ir), &
                                 ldwrkr,dum,1,work(iwork),info)
                       iu = ie + n
                       ! multiply q in a by left singular vectors of r in
                       ! work(ir), storing result in work(iu) and copying to a
                       ! (workspace: need n*n + 2*n, prefer n*n + m*n + n)
                       do i = 1,m,ldwrku
                          chunk = min(m - i + 1,ldwrku)
                          call la_qgemm('N','N',chunk,n,n,one,a(i,1),lda,work(ir) &
                                    ,ldwrkr,zero,work(iu),ldwrku)
                          call la_qlacpy('F',chunk,n,work(iu),ldwrku,a(i,1),lda)

                       end do
                    else
                       ! insufficient workspace for a fast algorithm
                       itau = 1
                       iwork = itau + n
                       ! compute a=q*r
                       ! (workspace: need 2*n, prefer n + n*nb)
                       call la_qgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
