                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',n,0,m,0,s,work(ie),dum,1,u,ldu,dum, &
                                    1,work(iwork),info)
                       end if
                    else if (wntvo) then
                       ! path 8 (m much larger than n, jobu='a', jobvt='o')
                       ! m left singular vectors to be computed in u and
                       ! n right singular vectors to be overwritten on a
                       if (lwork >= 2*n*n + max(n + m,4*n,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + 2*lda*n) then
                             ! work(iu) is lda by n and work(ir) is lda by n
                             ldwrku = lda
                             ir = iu + ldwrku*n
                             ldwrkr = lda
                          else if (lwork >= wrkbl + (lda + n)*n) then
                             ! work(iu) is lda by n and work(ir) is n by n
                             ldwrku = lda
                             ir = iu + ldwrku*n
                             ldwrkr = n
                          else
                             ! work(iu) is n by n and work(ir) is n by n
                             ldwrku = n
                             ir = iu + ldwrku*n
                             ldwrkr = n
                          end if
                          itau = ir + ldwrkr*n
                          iwork = itau + n
                          ! compute a=q*r, copying result to u
                          ! (workspace: need 2*n*n + 2*n, prefer 2*n*n + n + n*nb)
                          call la_qgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('L',m,n,a,lda,u,ldu)
                          ! generate q in u
                          ! (workspace: need 2*n*n + n + m, prefer 2*n*n + n + m*nb)
                          call la_qorgqr(m,m,n,u,ldu,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy r to work(iu), zeroing out below it
                          call la_qlacpy('U',n,n,a,lda,work(iu),ldwrku)
                          call la_qlaset('L',n - 1,n - 1,zero,zero,work(iu + 1),ldwrku)

                          ie = itau
                          itauq = ie + n
                          itaup = itauq + n
                          iwork = itaup + n
                          ! bidiagonalize r in work(iu), copying result to
                          ! work(ir)
                          ! (workspace: need 2*n*n + 4*n,
                                      ! prefer 2*n*n+3*n+2*n*nb)
                          call la_qgebrd(n,n,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_qlacpy('U',n,n,work(iu),ldwrku,work(ir),ldwrkr)

                          ! generate left bidiagonalizing vectors in work(iu)
                          ! (workspace: need 2*n*n + 4*n, prefer 2*n*n + 3*n + n*nb)
                          call la_qorgbr('Q',n,n,n,work(iu),ldwrku,work(itauq), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate right bidiagonalizing vectors in work(ir)
                          ! (workspace: need 2*n*n + 4*n-1,
                                      ! prefer 2*n*n+3*n+(n-1)*nb)
                          call la_qorgbr('P',n,n,n,work(ir),ldwrkr,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + n
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of r in work(iu) and computing
                          ! right singular vectors of r in work(ir)
                          ! (workspace: need 2*n*n + bdspac)
                          call la_qbdsqr('U',n,n,n,0,s,work(ie),work(ir),ldwrkr, &
                                    work(iu),ldwrku,dum,1,work(iwork),info)
                          ! multiply q in u by left singular vectors of r in
                          ! work(iu), storing result in a
                          ! (workspace: need n*n)
                          call la_qgemm('N','N',m,n,n,one,u,ldu,work(iu),ldwrku, &
                                    zero,a,lda)
                          ! copy left singular vectors of a from a to u
                          call la_qlacpy('F',m,n,a,lda,u,ldu)
                          ! copy right singular vectors of r from work(ir) to a
                          call la_qlacpy('F',n,n,work(ir),ldwrkr,a,lda)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + n
                          ! compute a=q*r, copying result to u
                          ! (workspace: need 2*n, prefer n + n*nb)
                          call la_qgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('L',m,n,a,lda,u,ldu)
                          ! generate q in u
                          ! (workspace: need n + m, prefer n + m*nb)
                          call la_qorgqr(m,m,n,u,ldu,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ie = itau
                          itauq = ie + n
                          itaup = itauq + n
                          iwork = itaup + n
                          ! zero out below r in a
                          if (n > 1) then
                             call la_qlaset('L',n - 1,n - 1,zero,zero,a(2,1),lda)

                          end if
                          ! bidiagonalize r in a
                          ! (workspace: need 4*n, prefer 3*n + 2*n*nb)
                          call la_qgebrd(n,n,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply q in u by left bidiagonalizing vectors
                          ! in a
                          ! (workspace: need 3*n + m, prefer 3*n + m*nb)
                          call la_qormbr('Q','R','N',m,n,n,a,lda,work(itauq),u, &
                                    ldu,work(iwork),lwork - iwork + 1,ierr)
                          ! generate right bidiagonalizing vectors in a
                          ! (workspace: need 4*n-1, prefer 3*n + (n-1)*nb)
                          call la_qorgbr('P',n,n,n,a,lda,work(itaup),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + n
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in a
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',n,n,m,0,s,work(ie),a,lda,u,ldu,dum, &
                                    1,work(iwork),info)
                       end if
                    else if (wntvas) then
                       ! path 9 (m much larger than n, jobu='a', jobvt='s'
                               ! or 'a')
                       ! m left singular vectors to be computed in u and
                       ! n right singular vectors to be computed in vt
                       if (lwork >= n*n + max(n + m,4*n,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + lda*n) then
                             ! work(iu) is lda by n
                             ldwrku = lda
                          else
                             ! work(iu) is n by n
                             ldwrku = n
                          end if
                          itau = iu + ldwrku*n
                          iwork = itau + n
                          ! compute a=q*r, copying result to u
                          ! (workspace: need n*n + 2*n, prefer n*n + n + n*nb)
                          call la_qgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('L',m,n,a,lda,u,ldu)
                          ! generate q in u
                          ! (workspace: need n*n + n + m, prefer n*n + n + m*nb)
                          call la_qorgqr(m,m,n,u,ldu,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy r to work(iu), zeroing out below it
                          call la_qlacpy('U',n,n,a,lda,work(iu),ldwrku)
                          call la_qlaset('L',n - 1,n - 1,zero,zero,work(iu + 1),ldwrku)

                          ie = itau
                          itauq = ie + n
                          itaup = itauq + n
                          iwork = itaup + n
                          ! bidiagonalize r in work(iu), copying result to vt
                          ! (workspace: need n*n + 4*n, prefer n*n + 3*n + 2*n*nb)
                          call la_qgebrd(n,n,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_qlacpy('U',n,n,work(iu),ldwrku,vt,ldvt)
                          ! generate left bidiagonalizing vectors in work(iu)
                          ! (workspace: need n*n + 4*n, prefer n*n + 3*n + n*nb)
                          call la_qorgbr('Q',n,n,n,work(iu),ldwrku,work(itauq), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate right bidiagonalizing vectors in vt
                          ! (workspace: need n*n + 4*n-1,
                                      ! prefer n*n+3*n+(n-1)*nb)
                          call la_qorgbr('P',n,n,n,vt,ldvt,work(itaup),work(iwork), &
                                     lwork - iwork + 1,ierr)
                          iwork = ie + n
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of r in work(iu) and computing
                          ! right singular vectors of r in vt
                          ! (workspace: need n*n + bdspac)
                          call la_qbdsqr('U',n,n,n,0,s,work(ie),vt,ldvt,work(iu), &
                                     ldwrku,dum,1,work(iwork),info)
                          ! multiply q in u by left singular vectors of r in
                          ! work(iu), storing result in a
                          ! (workspace: need n*n)
                          call la_qgemm('N','N',m,n,n,one,u,ldu,work(iu),ldwrku, &
                                    zero,a,lda)
                          ! copy left singular vectors of a from a to u
                          call la_qlacpy('F',m,n,a,lda,u,ldu)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + n
                          ! compute a=q*r, copying result to u
                          ! (workspace: need 2*n, prefer n + n*nb)
                          call la_qgeqrf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('L',m,n,a,lda,u,ldu)
                          ! generate q in u
                          ! (workspace: need n + m, prefer n + m*nb)
                          call la_qorgqr(m,m,n,u,ldu,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy r from a to vt, zeroing out below it
                          call la_qlacpy('U',n,n,a,lda,vt,ldvt)
                          if (n > 1) call la_qlaset('L',n - 1,n - 1,zero,zero,vt(2,1),ldvt &
                                    )
                          ie = itau
                          itauq = ie + n
                          itaup = itauq + n
                          iwork = itaup + n
                          ! bidiagonalize r in vt
                          ! (workspace: need 4*n, prefer 3*n + 2*n*nb)
                          call la_qgebrd(n,n,vt,ldvt,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply q in u by left bidiagonalizing vectors
                          ! in vt
                          ! (workspace: need 3*n + m, prefer 3*n + m*nb)
                          call la_qormbr('Q','R','N',m,n,n,vt,ldvt,work(itauq),u, &
                                    ldu,work(iwork),lwork - iwork + 1,ierr)
                          ! generate right bidiagonalizing vectors in vt
                          ! (workspace: need 4*n-1, prefer 3*n + (n-1)*nb)
                          call la_qorgbr('P',n,n,n,vt,ldvt,work(itaup),work(iwork), &
                                     lwork - iwork + 1,ierr)
                          iwork = ie + n
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',n,n,m,0,s,work(ie),vt,ldvt,u,ldu, &
                                    dum,1,work(iwork),info)
                       end if
                    end if
                 end if
              else
                 ! m < mnthr
                 ! path 10 (m at least n, but not much larger)
                 ! reduce to bidiagonal form without qr decomposition
                 ie = 1
                 itauq = ie + n
                 itaup = itauq + n
                 iwork = itaup + n
                 ! bidiagonalize a
                 ! (workspace: need 3*n + m, prefer 3*n + (m + n)*nb)
                 call la_qgebrd(m,n,a,lda,s,work(ie),work(itauq),work(itaup), &
                           work(iwork),lwork - iwork + 1,ierr)
                 if (wntuas) then
                    ! if left singular vectors desired in u, copy result to u
                    ! and generate left bidiagonalizing vectors in u
                    ! (workspace: need 3*n + ncu, prefer 3*n + ncu*nb)
                    call la_qlacpy('L',m,n,a,lda,u,ldu)
                    if (wntus) ncu = n
                    if (wntua) ncu = m
                    call la_qorgbr('Q',m,ncu,n,u,ldu,work(itauq),work(iwork), &
                              lwork - iwork + 1,ierr)
                 end if
                 if (wntvas) then
                    ! if right singular vectors desired in vt, copy result to
                    ! vt and generate right bidiagonalizing vectors in vt
                    ! (workspace: need 4*n-1, prefer 3*n + (n-1)*nb)
                    call la_qlacpy('U',n,n,a,lda,vt,ldvt)
                    call la_qorgbr('P',n,n,n,vt,ldvt,work(itaup),work(iwork), &
                              lwork - iwork + 1,ierr)
                 end if
                 if (wntuo) then
                    ! if left singular vectors desired in a, generate left
                    ! bidiagonalizing vectors in a
                    ! (workspace: need 4*n, prefer 3*n + n*nb)
                    call la_qorgbr('Q',m,n,n,a,lda,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvo) then
                    ! if right singular vectors desired in a, generate right
                    ! bidiagonalizing vectors in a
                    ! (workspace: need 4*n-1, prefer 3*n + (n-1)*nb)
                    call la_qorgbr('P',n,n,n,a,lda,work(itaup),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 iwork = ie + n
                 if (wntuas .or. wntuo) nru = m
                 if (wntun) nru = 0
                 if (wntvas .or. wntvo) ncvt = n
                 if (wntvn) ncvt = 0
                 if ((.not. wntuo) .and. (.not. wntvo)) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in vt
                    ! (workspace: need bdspac)
                    call la_qbdsqr('U',n,ncvt,nru,0,s,work(ie),vt,ldvt,u,ldu,dum, &
                               1,work(iwork),info)
                 else if ((.not. wntuo) .and. wntvo) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in a
                    ! (workspace: need bdspac)
                    call la_qbdsqr('U',n,ncvt,nru,0,s,work(ie),a,lda,u,ldu,dum, &
                              1,work(iwork),info)
                 else
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in a and computing right singular
                    ! vectors in vt
                    ! (workspace: need bdspac)
                    call la_qbdsqr('U',n,ncvt,nru,0,s,work(ie),vt,ldvt,a,lda,dum, &
                               1,work(iwork),info)
                 end if
              end if
           else
              ! a has more columns than rows. if a has sufficiently more
              ! columns than rows, first reduce using the lq decomposition (if
              ! sufficient workspace available)
              if (n >= mnthr) then
                 if (wntvn) then
                    ! path 1t(n much larger than m, jobvt='n')
                    ! no right singular vectors to be computed
                    itau = 1
                    iwork = itau + m
                    ! compute a=l*q
                    ! (workspace: need 2*m, prefer m + m*nb)
                    call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + 1, &
                              ierr)
                    ! zero out above l
                    call la_qlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                    ie = 1
                    itauq = ie + m
                    itaup = itauq + m
                    iwork = itaup + m
                    ! bidiagonalize l in a
                    ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                    call la_qgebrd(m,m,a,lda,s,work(ie),work(itauq),work(itaup), &
                              work(iwork),lwork - iwork + 1,ierr)
                    if (wntuo .or. wntuas) then
                       ! if left singular vectors desired, generate q
                       ! (workspace: need 4*m, prefer 3*m + m*nb)
                       call la_qorgbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                 lwork - iwork + 1,ierr)
                    end if
                    iwork = ie + m
                    nru = 0
                    if (wntuo .or. wntuas) nru = m
                    ! perform bidiagonal qr iteration, computing left singular
                    ! vectors of a in a if desired
                    ! (workspace: need bdspac)
                    call la_qbdsqr('U',m,0,nru,0,s,work(ie),dum,1,a,lda,dum,1, &
                              work(iwork),info)
                    ! if left singular vectors desired in u, copy them there
                    if (wntuas) call la_qlacpy('F',m,m,a,lda,u,ldu)
                 else if (wntvo .and. wntun) then
                    ! path 2t(n much larger than m, jobu='n', jobvt='o')
                    ! m right singular vectors to be overwritten on a and
                    ! no left singular vectors to be computed
                    if (lwork >= m*m + max(4*m,bdspac)) then
                       ! sufficient workspace for a fast algorithm
                       ir = 1
                       if (lwork >= max(wrkbl,lda*n + m) + lda*m) then
                          ! work(iu) is lda by n and work(ir) is lda by m
                          ldwrku = lda
                          chunk = n
                          ldwrkr = lda
                       else if (lwork >= max(wrkbl,lda*n + m) + m*m) then
                          ! work(iu) is lda by n and work(ir) is m by m
                          ldwrku = lda
                          chunk = n
                          ldwrkr = m
                       else
                          ! work(iu) is m by chunk and work(ir) is m by m
                          ldwrku = m
                          chunk = (lwork - m*m - m)/m
                          ldwrkr = m
                       end if
                       itau = ir + ldwrkr*m
                       iwork = itau + m
                       ! compute a=l*q
                       ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                       call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy l to work(ir) and zero out above it
                       call la_qlacpy('L',m,m,a,lda,work(ir),ldwrkr)
                       call la_qlaset('U',m - 1,m - 1,zero,zero,work(ir + ldwrkr),ldwrkr)

                       ! generate q in a
                       ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                       call la_qorglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = itau
                       itauq = ie + m
                       itaup = itauq + m
                       iwork = itaup + m
                       ! bidiagonalize l in work(ir)
                       ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                       call la_qgebrd(m,m,work(ir),ldwrkr,s,work(ie),work(itauq), &
                                 work(itaup),work(iwork),lwork - iwork + 1,ierr)
                       ! generate right vectors bidiagonalizing l
                       ! (workspace: need m*m + 4*m-1, prefer m*m + 3*m + (m-1)*nb)
                       call la_qorgbr('P',m,m,m,work(ir),ldwrkr,work(itaup),work( &
                                 iwork),lwork - iwork + 1,ierr)
                       iwork = ie + m
                       ! perform bidiagonal qr iteration, computing right
                       ! singular vectors of l in work(ir)
                       ! (workspace: need m*m + bdspac)
                       call la_qbdsqr('U',m,m,0,0,s,work(ie),work(ir),ldwrkr,dum, &
                                  1,dum,1,work(iwork),info)
                       iu = ie + m
                       ! multiply right singular vectors of l in work(ir) by q
                       ! in a, storing result in work(iu) and copying to a
                       ! (workspace: need m*m + 2*m, prefer m*m + m*n + m)
                       do i = 1,n,chunk
                          blk = min(n - i + 1,chunk)
                          call la_qgemm('N','N',m,blk,m,one,work(ir),ldwrkr,a(1,i &
                                    ),lda,zero,work(iu),ldwrku)
                          call la_qlacpy('F',m,blk,work(iu),ldwrku,a(1,i),lda)

                       end do
                    else
                       ! insufficient workspace for a fast algorithm
                       ie = 1
                       itauq = ie + m
                       itaup = itauq + m
                       iwork = itaup + m
                       ! bidiagonalize a
                       ! (workspace: need 3*m + n, prefer 3*m + (m + n)*nb)
                       call la_qgebrd(m,n,a,lda,s,work(ie),work(itauq),work(itaup &
                                 ),work(iwork),lwork - iwork + 1,ierr)
                       ! generate right vectors bidiagonalizing a
                       ! (workspace: need 4*m, prefer 3*m + m*nb)
                       call la_qorgbr('P',m,n,m,a,lda,work(itaup),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       iwork = ie + m
                       ! perform bidiagonal qr iteration, computing right
                       ! singular vectors of a in a
                       ! (workspace: need bdspac)
                       call la_qbdsqr('L',m,n,0,0,s,work(ie),a,lda,dum,1,dum,1, &
                                 work(iwork),info)
                    end if
                 else if (wntvo .and. wntuas) then
                    ! path 3t(n much larger than m, jobu='s' or 'a', jobvt='o')
                    ! m right singular vectors to be overwritten on a and
                    ! m left singular vectors to be computed in u
                    if (lwork >= m*m + max(4*m,bdspac)) then
                       ! sufficient workspace for a fast algorithm
                       ir = 1
                       if (lwork >= max(wrkbl,lda*n + m) + lda*m) then
                          ! work(iu) is lda by n and work(ir) is lda by m
                          ldwrku = lda
                          chunk = n
                          ldwrkr = lda
                       else if (lwork >= max(wrkbl,lda*n + m) + m*m) then
                          ! work(iu) is lda by n and work(ir) is m by m
                          ldwrku = lda
                          chunk = n
                          ldwrkr = m
                       else
                          ! work(iu) is m by chunk and work(ir) is m by m
                          ldwrku = m
                          chunk = (lwork - m*m - m)/m
                          ldwrkr = m
                       end if
                       itau = ir + ldwrkr*m
                       iwork = itau + m
                       ! compute a=l*q
                       ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                       call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy l to u, zeroing about above it
                       call la_qlacpy('L',m,m,a,lda,u,ldu)
                       call la_qlaset('U',m - 1,m - 1,zero,zero,u(1,2),ldu)
                       ! generate q in a
                       ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                       call la_qorglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = itau
                       itauq = ie + m
                       itaup = itauq + m
                       iwork = itaup + m
                       ! bidiagonalize l in u, copying result to work(ir)
                       ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                       call la_qgebrd(m,m,u,ldu,s,work(ie),work(itauq),work(itaup &
                                 ),work(iwork),lwork - iwork + 1,ierr)
                       call la_qlacpy('U',m,m,u,ldu,work(ir),ldwrkr)
                       ! generate right vectors bidiagonalizing l in work(ir)
                       ! (workspace: need m*m + 4*m-1, prefer m*m + 3*m + (m-1)*nb)
                       call la_qorgbr('P',m,m,m,work(ir),ldwrkr,work(itaup),work( &
                                 iwork),lwork - iwork + 1,ierr)
                       ! generate left vectors bidiagonalizing l in u
                       ! (workspace: need m*m + 4*m, prefer m*m + 3*m + m*nb)
                       call la_qorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       iwork = ie + m
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of l in u, and computing right
                       ! singular vectors of l in work(ir)
                       ! (workspace: need m*m + bdspac)
                       call la_qbdsqr('U',m,m,m,0,s,work(ie),work(ir),ldwrkr,u, &
                                 ldu,dum,1,work(iwork),info)
                       iu = ie + m
                       ! multiply right singular vectors of l in work(ir) by q
                       ! in a, storing result in work(iu) and copying to a
                       ! (workspace: need m*m + 2*m, prefer m*m + m*n + m))
                       do i = 1,n,chunk
                          blk = min(n - i + 1,chunk)
                          call la_qgemm('N','N',m,blk,m,one,work(ir),ldwrkr,a(1,i &
                                    ),lda,zero,work(iu),ldwrku)
                          call la_qlacpy('F',m,blk,work(iu),ldwrku,a(1,i),lda)

                       end do
                    else
                       ! insufficient workspace for a fast algorithm
                       itau = 1
                       iwork = itau + m
                       ! compute a=l*q
                       ! (workspace: need 2*m, prefer m + m*nb)
                       call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - iwork + &
                                 1,ierr)
                       ! copy l to u, zeroing out above it
                       call la_qlacpy('L',m,m,a,lda,u,ldu)
                       call la_qlaset('U',m - 1,m - 1,zero,zero,u(1,2),ldu)
                       ! generate q in a
                       ! (workspace: need 2*m, prefer m + m*nb)
                       call la_qorglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                 iwork + 1,ierr)
                       ie = itau
                       itauq = ie + m
                       itaup = itauq + m
                       iwork = itaup + m
                       ! bidiagonalize l in u
                       ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                       call la_qgebrd(m,m,u,ldu,s,work(ie),work(itauq),work(itaup &
                                 ),work(iwork),lwork - iwork + 1,ierr)
                       ! multiply right vectors bidiagonalizing l by q in a
                       ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                       call la_qormbr('P','L','T',m,n,m,u,ldu,work(itaup),a,lda, &
                                 work(iwork),lwork - iwork + 1,ierr)
                       ! generate left vectors bidiagonalizing l in u
                       ! (workspace: need 4*m, prefer 3*m + m*nb)
                       call la_qorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                 lwork - iwork + 1,ierr)
                       iwork = ie + m
                       ! perform bidiagonal qr iteration, computing left
                       ! singular vectors of a in u and computing right
                       ! singular vectors of a in a
                       ! (workspace: need bdspac)
                       call la_qbdsqr('U',m,n,m,0,s,work(ie),a,lda,u,ldu,dum,1, &
                                 work(iwork),info)
                    end if
                 else if (wntvs) then
                    if (wntun) then
                       ! path 4t(n much larger than m, jobu='n', jobvt='s')
                       ! m right singular vectors to be computed in vt and
                       ! no left singular vectors to be computed
                       if (lwork >= m*m + max(4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          ir = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(ir) is lda by m
                             ldwrkr = lda
                          else
                             ! work(ir) is m by m
                             ldwrkr = m
                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy l to work(ir), zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,work(ir),ldwrkr)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,work(ir + ldwrkr),ldwrkr &
                                    )
                          ! generate q in a
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_qorglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(ir)
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                          call la_qgebrd(m,m,work(ir),ldwrkr,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! generate right vectors bidiagonalizing l in
                          ! work(ir)
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + (m-1)*nb)
                          call la_qorgbr('P',m,m,m,work(ir),ldwrkr,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of l in work(ir)
                          ! (workspace: need m*m + bdspac)
                          call la_qbdsqr('U',m,m,0,0,s,work(ie),work(ir),ldwrkr, &
                                    dum,1,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(ir) by
                          ! q in a, storing result in vt
                          ! (workspace: need m*m)
                          call la_qgemm('N','N',m,n,m,one,work(ir),ldwrkr,a,lda, &
                                    zero,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy result to vt
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qorglq(m,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_qlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_qgebrd(m,m,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right vectors bidiagonalizing l by q in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_qormbr('P','L','T',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',m,n,0,0,s,work(ie),vt,ldvt,dum,1, &
                                    dum,1,work(iwork),info)
                       end if
                    else if (wntuo) then
                       ! path 5t(n much larger than m, jobu='o', jobvt='s')
                       ! m right singular vectors to be computed in vt and
                       ! m left singular vectors to be overwritten on a
                       if (lwork >= 2*m*m + max(4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + 2*lda*m) then
                             ! work(iu) is lda by m and work(ir) is lda by m
                             ldwrku = lda
                             ir = iu + ldwrku*m
                             ldwrkr = lda
                          else if (lwork >= wrkbl + (lda + m)*m) then
                             ! work(iu) is lda by m and work(ir) is m by m
                             ldwrku = lda
                             ir = iu + ldwrku*m
                             ldwrkr = m
                          else
                             ! work(iu) is m by m and work(ir) is m by m
                             ldwrku = m
                             ir = iu + ldwrku*m
                             ldwrkr = m
                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q
                          ! (workspace: need 2*m*m + 2*m, prefer 2*m*m + m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out below it
                          call la_qlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,work(iu + ldwrku),ldwrku &
                                    )
                          ! generate q in a
                          ! (workspace: need 2*m*m + 2*m, prefer 2*m*m + m + m*nb)
                          call la_qorglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to
                          ! work(ir)
                          ! (workspace: need 2*m*m + 4*m,
                                      ! prefer 2*m*m+3*m+2*m*nb)
                          call la_qgebrd(m,m,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_qlacpy('L',m,m,work(iu),ldwrku,work(ir),ldwrkr)

                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (workspace: need 2*m*m + 4*m-1,
                                      ! prefer 2*m*m+3*m+(m-1)*nb)
                          call la_qorgbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in work(ir)
                          ! (workspace: need 2*m*m + 4*m, prefer 2*m*m + 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,work(ir),ldwrkr,work(itauq), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in work(ir) and computing
                          ! right singular vectors of l in work(iu)
                          ! (workspace: need 2*m*m + bdspac)
                          call la_qbdsqr('U',m,m,m,0,s,work(ie),work(iu),ldwrku, &
                                    work(ir),ldwrkr,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in a, storing result in vt
                          ! (workspace: need m*m)
                          call la_qgemm('N','N',m,n,m,one,work(iu),ldwrku,a,lda, &
                                    zero,vt,ldvt)
                          ! copy left singular vectors of l to a
                          ! (workspace: need m*m)
                          call la_qlacpy('F',m,m,work(ir),ldwrkr,a,lda)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qorglq(m,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_qlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_qgebrd(m,m,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right vectors bidiagonalizing l by q in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_qormbr('P','L','T',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors of l in a
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, compute left
                          ! singular vectors of a in a and compute right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,a,lda, &
                                    dum,1,work(iwork),info)
                       end if
                    else if (wntuas) then
                       ! path 6t(n much larger than m, jobu='s' or 'a',
                               ! jobvt='s')
                       ! m right singular vectors to be computed in vt and
                       ! m left singular vectors to be computed in u
                       if (lwork >= m*m + max(4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(iu) is lda by n
                             ldwrku = lda
                          else
                             ! work(iu) is lda by m
                             ldwrku = m
                          end if
                          itau = iu + ldwrku*m
                          iwork = itau + m
                          ! compute a=l*q
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,work(iu + ldwrku),ldwrku &
                                    )
                          ! generate q in a
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_qorglq(m,n,m,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                          call la_qgebrd(m,m,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_qlacpy('L',m,m,work(iu),ldwrku,u,ldu)
                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (workspace: need m*m + 4*m-1,
                                      ! prefer m*m+3*m+(m-1)*nb)
                          call la_qorgbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in u and computing right
                          ! singular vectors of l in work(iu)
                          ! (workspace: need m*m + bdspac)
                          call la_qbdsqr('U',m,m,m,0,s,work(ie),work(iu),ldwrku, &
                                    u,ldu,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in a, storing result in vt
                          ! (workspace: need m*m)
                          call la_qgemm('N','N',m,n,m,one,work(iu),ldwrku,a,lda, &
