                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m + n, prefer m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_qlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_qgebrd(m,m,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in a by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_qormbr('P','L','T',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',m,n,0,0,s,work(ie),vt,ldvt,dum,1, &
                                    dum,1,work(iwork),info)
                       end if
                    else if (wntuo) then
                       ! path 8t(n much larger than m, jobu='o', jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! m left singular vectors to be overwritten on a
                       if (lwork >= 2*m*m + max(n + m,4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + 2*lda*m) then
                             ! work(iu) is lda by m and work(ir) is lda by m
                             ldwrku = lda
                             ir = iu + ldwrku*m
                             ldwrkr = lda
                          else if (lwork >= wrkbl + (lda + m)*m) then
                             ! work(iu) is lda by m and work(ir) is m by m
                             ldwrku = lda
                             ir = iu + ldwrku*m
                             ldwrkr = m
                          else
                             ! work(iu) is m by m and work(ir) is m by m
                             ldwrku = m
                             ir = iu + ldwrku*m
                             ldwrkr = m
                          end if
                          itau = ir + ldwrkr*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m*m + 2*m, prefer 2*m*m + m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need 2*m*m + m + n, prefer 2*m*m + m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,work(iu + ldwrku),ldwrku &
                                    )
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to
                          ! work(ir)
                          ! (workspace: need 2*m*m + 4*m,
                                      ! prefer 2*m*m+3*m+2*m*nb)
                          call la_qgebrd(m,m,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_qlacpy('L',m,m,work(iu),ldwrku,work(ir),ldwrkr)

                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (workspace: need 2*m*m + 4*m-1,
                                      ! prefer 2*m*m+3*m+(m-1)*nb)
                          call la_qorgbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in work(ir)
                          ! (workspace: need 2*m*m + 4*m, prefer 2*m*m + 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,work(ir),ldwrkr,work(itauq), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in work(ir) and computing
                          ! right singular vectors of l in work(iu)
                          ! (workspace: need 2*m*m + bdspac)
                          call la_qbdsqr('U',m,m,m,0,s,work(ie),work(iu),ldwrku, &
                                    work(ir),ldwrkr,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in vt, storing result in a
                          ! (workspace: need m*m)
                          call la_qgemm('N','N',m,n,m,one,work(iu),ldwrku,vt,ldvt, &
                                    zero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_qlacpy('F',m,n,a,lda,vt,ldvt)
                          ! copy left singular vectors of a from work(ir) to a
                          call la_qlacpy('F',m,m,work(ir),ldwrkr,a,lda)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m + n, prefer m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! zero out above l in a
                          call la_qlaset('U',m - 1,m - 1,zero,zero,a(1,2),lda)
                          ! bidiagonalize l in a
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_qgebrd(m,m,a,lda,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in a by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_qormbr('P','L','T',m,n,m,a,lda,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in a
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,a,lda,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in a and computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,a,lda, &
                                    dum,1,work(iwork),info)
                       end if
                    else if (wntuas) then
                       ! path 9t(n much larger than m, jobu='s' or 'a',
                               ! jobvt='a')
                       ! n right singular vectors to be computed in vt and
                       ! m left singular vectors to be computed in u
                       if (lwork >= m*m + max(n + m,4*m,bdspac)) then
                          ! sufficient workspace for a fast algorithm
                          iu = 1
                          if (lwork >= wrkbl + lda*m) then
                             ! work(iu) is lda by m
                             ldwrku = lda
                          else
                             ! work(iu) is m by m
                             ldwrku = m
                          end if
                          itau = iu + ldwrku*m
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need m*m + 2*m, prefer m*m + m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m*m + m + n, prefer m*m + m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to work(iu), zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,work(iu),ldwrku)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,work(iu + ldwrku),ldwrku &
                                    )
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in work(iu), copying result to u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + 2*m*nb)
                          call la_qgebrd(m,m,work(iu),ldwrku,s,work(ie),work(itauq &
                                    ),work(itaup),work(iwork),lwork - iwork + 1,ierr)
                          call la_qlacpy('L',m,m,work(iu),ldwrku,u,ldu)
                          ! generate right bidiagonalizing vectors in work(iu)
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + (m-1)*nb)
                          call la_qorgbr('P',m,m,m,work(iu),ldwrku,work(itaup), &
                                    work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need m*m + 4*m, prefer m*m + 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of l in u and computing right
                          ! singular vectors of l in work(iu)
                          ! (workspace: need m*m + bdspac)
                          call la_qbdsqr('U',m,m,m,0,s,work(ie),work(iu),ldwrku, &
                                    u,ldu,dum,1,work(iwork),info)
                          ! multiply right singular vectors of l in work(iu) by
                          ! q in vt, storing result in a
                          ! (workspace: need m*m)
                          call la_qgemm('N','N',m,n,m,one,work(iu),ldwrku,vt,ldvt, &
                                    zero,a,lda)
                          ! copy right singular vectors of a from a to vt
                          call la_qlacpy('F',m,n,a,lda,vt,ldvt)
                       else
                          ! insufficient workspace for a fast algorithm
                          itau = 1
                          iwork = itau + m
                          ! compute a=l*q, copying result to vt
                          ! (workspace: need 2*m, prefer m + m*nb)
                          call la_qgelqf(m,n,a,lda,work(itau),work(iwork),lwork - &
                                    iwork + 1,ierr)
                          call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                          ! generate q in vt
                          ! (workspace: need m + n, prefer m + n*nb)
                          call la_qorglq(n,n,m,vt,ldvt,work(itau),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          ! copy l to u, zeroing out above it
                          call la_qlacpy('L',m,m,a,lda,u,ldu)
                          call la_qlaset('U',m - 1,m - 1,zero,zero,u(1,2),ldu)
                          ie = itau
                          itauq = ie + m
                          itaup = itauq + m
                          iwork = itaup + m
                          ! bidiagonalize l in u
                          ! (workspace: need 4*m, prefer 3*m + 2*m*nb)
                          call la_qgebrd(m,m,u,ldu,s,work(ie),work(itauq),work( &
                                    itaup),work(iwork),lwork - iwork + 1,ierr)
                          ! multiply right bidiagonalizing vectors in u by q
                          ! in vt
                          ! (workspace: need 3*m + n, prefer 3*m + n*nb)
                          call la_qormbr('P','L','T',m,n,m,u,ldu,work(itaup),vt, &
                                    ldvt,work(iwork),lwork - iwork + 1,ierr)
                          ! generate left bidiagonalizing vectors in u
                          ! (workspace: need 4*m, prefer 3*m + m*nb)
                          call la_qorgbr('Q',m,m,m,u,ldu,work(itauq),work(iwork), &
                                    lwork - iwork + 1,ierr)
                          iwork = ie + m
                          ! perform bidiagonal qr iteration, computing left
                          ! singular vectors of a in u and computing right
                          ! singular vectors of a in vt
                          ! (workspace: need bdspac)
                          call la_qbdsqr('U',m,n,m,0,s,work(ie),vt,ldvt,u,ldu, &
                                    dum,1,work(iwork),info)
                       end if
                    end if
                 end if
              else
                 ! n < mnthr
                 ! path 10t(n greater than m, but not much larger)
                 ! reduce to bidiagonal form without lq decomposition
                 ie = 1
                 itauq = ie + m
                 itaup = itauq + m
                 iwork = itaup + m
                 ! bidiagonalize a
                 ! (workspace: need 3*m + n, prefer 3*m + (m + n)*nb)
                 call la_qgebrd(m,n,a,lda,s,work(ie),work(itauq),work(itaup), &
                           work(iwork),lwork - iwork + 1,ierr)
                 if (wntuas) then
                    ! if left singular vectors desired in u, copy result to u
                    ! and generate left bidiagonalizing vectors in u
                    ! (workspace: need 4*m-1, prefer 3*m + (m-1)*nb)
                    call la_qlacpy('L',m,m,a,lda,u,ldu)
                    call la_qorgbr('Q',m,m,n,u,ldu,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvas) then
                    ! if right singular vectors desired in vt, copy result to
                    ! vt and generate right bidiagonalizing vectors in vt
                    ! (workspace: need 3*m + nrvt, prefer 3*m + nrvt*nb)
                    call la_qlacpy('U',m,n,a,lda,vt,ldvt)
                    if (wntva) nrvt = n
                    if (wntvs) nrvt = m
                    call la_qorgbr('P',nrvt,n,m,vt,ldvt,work(itaup),work(iwork), &
                              lwork - iwork + 1,ierr)
                 end if
                 if (wntuo) then
                    ! if left singular vectors desired in a, generate left
                    ! bidiagonalizing vectors in a
                    ! (workspace: need 4*m-1, prefer 3*m + (m-1)*nb)
                    call la_qorgbr('Q',m,m,n,a,lda,work(itauq),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 if (wntvo) then
                    ! if right singular vectors desired in a, generate right
                    ! bidiagonalizing vectors in a
                    ! (workspace: need 4*m, prefer 3*m + m*nb)
                    call la_qorgbr('P',m,n,m,a,lda,work(itaup),work(iwork),lwork - &
                              iwork + 1,ierr)
                 end if
                 iwork = ie + m
                 if (wntuas .or. wntuo) nru = m
                 if (wntun) nru = 0
                 if (wntvas .or. wntvo) ncvt = n
                 if (wntvn) ncvt = 0
                 if ((.not. wntuo) .and. (.not. wntvo)) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in vt
                    ! (workspace: need bdspac)
                    call la_qbdsqr('L',m,ncvt,nru,0,s,work(ie),vt,ldvt,u,ldu,dum, &
                               1,work(iwork),info)
                 else if ((.not. wntuo) .and. wntvo) then
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in u and computing right singular
                    ! vectors in a
                    ! (workspace: need bdspac)
                    call la_qbdsqr('L',m,ncvt,nru,0,s,work(ie),a,lda,u,ldu,dum, &
                              1,work(iwork),info)
                 else
                    ! perform bidiagonal qr iteration, if desired, computing
                    ! left singular vectors in a and computing right singular
                    ! vectors in vt
                    ! (workspace: need bdspac)
                    call la_qbdsqr('L',m,ncvt,nru,0,s,work(ie),vt,ldvt,a,lda,dum, &
                               1,work(iwork),info)
                 end if
              end if
           end if
           ! if la_qbdsqr failed to converge, copy unconverged superdiagonals
           ! to work( 2:minmn )
           if (info /= 0) then
              if (ie > 2) then
                 do i = 1,minmn - 1
                    work(i + 1) = work(i + ie - 1)
                 end do
              end if
              if (ie < 2) then
                 do i = minmn - 1,1,-1
                    work(i + 1) = work(i + ie - 1)
                 end do
              end if
           end if
           ! undo scaling if necessary
           if (iscl == 1) then
              if (anrm > bignum) call la_qlascl('G',0,0,bignum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (info /= 0 .and. anrm > bignum) call la_qlascl('G',0,0,bignum,anrm,minmn - 1, &
                         1,work(2),minmn,ierr)
              if (anrm < smlnum) call la_qlascl('G',0,0,smlnum,anrm,minmn,1,s,minmn, &
                        ierr)
              if (info /= 0 .and. anrm < smlnum) call la_qlascl('G',0,0,smlnum,anrm,minmn - 1, &
                         1,work(2),minmn,ierr)
           end if
           ! return optimal workspace in work(1)
           work(1) = maxwrk
           return
     end subroutine la_qgesvd

     !> DGESVDQ: computes the singular value decomposition (SVD) of a real
     !> M-by-N matrix A, where M >= N. The SVD of A is written as
     !> [++]   [xx]   [x0]   [xx]
     !> A = U * SIGMA * V^*,  [++] = [xx] * [ox] * [xx]
     !> [++]   [xx]
     !> where SIGMA is an N-by-N diagonal matrix, U is an M-by-N orthonormal
     !> matrix, and V is an N-by-N orthogonal matrix. The diagonal elements
     !> of SIGMA are the singular values of A. The columns of U and V are the
     !> left and the right singular vectors of A, respectively.

     subroutine la_qgesvdq(joba,jobp,jobr,jobu,jobv,m,n,a,lda,s,u,ldu,v,ldv, &
               numrank,iwork,liwork,work,lwork,rwork,lrwork,info)
           ! Scalar Arguments
           character,intent(in) :: joba,jobp,jobr,jobu,jobv
           integer(ilp),intent(in) :: m,n,lda,ldu,ldv,liwork,lrwork
           integer(ilp),intent(out) :: numrank,info
           integer(ilp),intent(inout) :: lwork
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: u(ldu,*),v(ldv,*),work(*)
           real(qp),intent(out) :: s(*),rwork(*)
           integer(ilp),intent(out) :: iwork(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: ierr,iwoff,nr,n1,optratio,p,q
           integer(ilp) :: lwcon,lwqp3,lwrk_qgelqf,lwrk_qgesvd,lwrk_qgesvd2,lwrk_qgeqp3, &
           lwrk_qgeqrf,lwrk_qormlq,lwrk_qormqr,lwrk_qormqr2,lwlqf,lwqrf,lwsvd,lwsvd2, &
                     lworq,lworq2,lworlq,minwrk,minwrk2,optwrk,optwrk2,iminwrk,rminwrk
           logical(lk) :: accla,acclm,acclh,ascaled,conda,dntwu,dntwv,lquery,lsvc0,lsvec, &
                      rowprm,rsvec,rtrans,wntua,wntuf,wntur,wntus,wntva,wntvr
           real(qp) :: big,epsln,rtmp,sconda,sfmin
           ! Local Arrays
           real(qp) :: rdummy(1)
           ! Intrinsic Functions
           intrinsic :: abs,max,min,real,sqrt
           ! test the input arguments
           wntus = la_lsame(jobu,'S') .or. la_lsame(jobu,'U')
           wntur = la_lsame(jobu,'R')
           wntua = la_lsame(jobu,'A')
           wntuf = la_lsame(jobu,'F')
           lsvc0 = wntus .or. wntur .or. wntua
           lsvec = lsvc0 .or. wntuf
           dntwu = la_lsame(jobu,'N')
           wntvr = la_lsame(jobv,'R')
           wntva = la_lsame(jobv,'A') .or. la_lsame(jobv,'V')
           rsvec = wntvr .or. wntva
           dntwv = la_lsame(jobv,'N')
           accla = la_lsame(joba,'A')
           acclm = la_lsame(joba,'M')
           conda = la_lsame(joba,'E')
           acclh = la_lsame(joba,'H') .or. conda
           rowprm = la_lsame(jobp,'P')
           rtrans = la_lsame(jobr,'T')
           if (rowprm) then
              if (conda) then
                 iminwrk = max(1,n + m - 1 + n)
              else
                 iminwrk = max(1,n + m - 1)
              end if
              rminwrk = max(2,m)
           else
              if (conda) then
                 iminwrk = max(1,n + n)
              else
                 iminwrk = max(1,n)
              end if
              rminwrk = 2
           end if
           lquery = (liwork == -1 .or. lwork == -1 .or. lrwork == -1)
           info = 0
           if (.not. (accla .or. acclm .or. acclh)) then
              info = -1
           else if (.not. (rowprm .or. la_lsame(jobp,'N'))) then
               info = -2
           else if (.not. (rtrans .or. la_lsame(jobr,'N'))) then
               info = -3
           else if (.not. (lsvec .or. dntwu)) then
              info = -4
           else if (wntur .and. wntva) then
              info = -5
           else if (.not. (rsvec .or. dntwv)) then
              info = -5
           else if (m < 0) then
              info = -6
           else if ((n < 0) .or. (n > m)) then
              info = -7
           else if (lda < max(1,m)) then
              info = -9
           else if (ldu < 1 .or. (lsvc0 .and. ldu < m) .or. (wntuf .and. ldu < n)) then
              info = -12
           else if (ldv < 1 .or. (rsvec .and. ldv < n) .or. (conda .and. ldv < n)) then
              info = -14
           else if (liwork < iminwrk .and. .not. lquery) then
              info = -17
           end if
           if (info == 0) then
              ! Compute The Minimal And The Optimal Workspace Lengths
              ! [[the expressions for computing the minimal and the optimal
              ! values of lwork are written with a lot of redundancy and
              ! can be simplified. however, this detailed form is easier for
              ! maintenance and modifications of the code.]]
              ! Minimal Workspace Length For la_Dgeqp3 Of An M X N Matrix
              lwqp3 = 3*n + 1
              ! Minimal Workspace Length For la_Dormqr To Build Left Singular Vectors
              if (wntus .or. wntur) then
                  lworq = max(n,1)
              else if (wntua) then
                  lworq = max(m,1)
              end if
              ! Minimal Workspace Length For la_Dpocon Of An N X N Matrix
              lwcon = 3*n
              ! la_Dgesvd Of An N X N Matrix
              lwsvd = max(5*n,1)
              if (lquery) then
                  call la_qgeqp3(m,n,a,lda,iwork,rdummy,rdummy,-1,ierr)
                  lwrk_qgeqp3 = int(rdummy(1),KIND=ilp)
                  if (wntus .or. wntur) then
                      call la_qormqr('L','N',m,n,n,a,lda,rdummy,u,ldu,rdummy,-1, &
                                ierr)
                      lwrk_qormqr = int(rdummy(1),KIND=ilp)
                  else if (wntua) then
                      call la_qormqr('L','N',m,m,n,a,lda,rdummy,u,ldu,rdummy,-1, &
                                ierr)
                      lwrk_qormqr = int(rdummy(1),KIND=ilp)
                  else
                      lwrk_qormqr = 0
                  end if
              end if
              minwrk = 2
              optwrk = 2
              if (.not. (lsvec .or. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If
                  ! only the singular values are requested
                  if (conda) then
                     minwrk = max(n + lwqp3,lwcon,lwsvd)
                  else
                     minwrk = max(n + lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      call la_qgesvd('N','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                ierr)
                      lwrk_qgesvd = int(rdummy(1),KIND=ilp)
                      if (conda) then
                         optwrk = max(n + lwrk_qgeqp3,n + lwcon,lwrk_qgesvd)
                      else
                         optwrk = max(n + lwrk_qgeqp3,lwrk_qgesvd)
                      end if
                  end if
              else if (lsvec .and. (.not. rsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! singular values and the left singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd,lworq)
                  else
                      minwrk = n + max(lwqp3,lwsvd,lworq)
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_qgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                     else
                        call la_qgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                     end if
                     lwrk_qgesvd = int(rdummy(1),KIND=ilp)
                     if (conda) then
                         optwrk = n + max(lwrk_qgeqp3,lwcon,lwrk_qgesvd,lwrk_qormqr)
                     else
                         optwrk = n + max(lwrk_qgeqp3,lwrk_qgesvd,lwrk_qormqr)
                     end if
                  end if
              else if (rsvec .and. (.not. lsvec)) then
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! singular values and the right singular vectors are requested
                  if (conda) then
                      minwrk = n + max(lwqp3,lwcon,lwsvd)
                  else
                      minwrk = n + max(lwqp3,lwsvd)
                  end if
                  if (lquery) then
                      if (rtrans) then
                          call la_qgesvd('O','N',n,n,a,lda,s,u,ldu,v,ldv,rdummy,- &
                                    1,ierr)
                      else
                          call la_qgesvd('N','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,- &
                                    1,ierr)
                      end if
                      lwrk_qgesvd = int(rdummy(1),KIND=ilp)
                      if (conda) then
                          optwrk = n + max(lwrk_qgeqp3,lwcon,lwrk_qgesvd)
                      else
                          optwrk = n + max(lwrk_qgeqp3,lwrk_qgesvd)
                      end if
                  end if
              else
                  ! Minimal And Optimal Sizes Of The Workspace If The
                  ! full svd is requested
                  if (rtrans) then
                      minwrk = max(lwqp3,lwsvd,lworq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n x n/2 la_qgeqrf
                         lwqrf = max(n/2,1)
                         ! .. minimal workspace length for n/2 x n/2 la_qgesvd
                         lwsvd2 = max(5*(n/2),1)
                         lworq2 = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwqrf,n/2 + lwsvd2,n/2 + lworq2,lworq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  else
                      minwrk = max(lwqp3,lwsvd,lworq)
                      if (conda) minwrk = max(minwrk,lwcon)
                      minwrk = minwrk + n
                      if (wntva) then
                         ! .. minimal workspace length for n/2 x n la_qgelqf
                         lwlqf = max(n/2,1)
                         lwsvd2 = max(5*(n/2),1)
                         lworlq = max(n,1)
                         minwrk2 = max(lwqp3,n/2 + lwlqf,n/2 + lwsvd2,n/2 + lworlq,lworq)
                         if (conda) minwrk2 = max(minwrk2,lwcon)
                         minwrk2 = n + minwrk2
                         minwrk = max(minwrk,minwrk2)
                      end if
                  end if
                  if (lquery) then
                     if (rtrans) then
                        call la_qgesvd('O','A',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                        lwrk_qgesvd = int(rdummy(1),KIND=ilp)
                        optwrk = max(lwrk_qgeqp3,lwrk_qgesvd,lwrk_qormqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                            call la_qgeqrf(n,n/2,u,ldu,rdummy,rdummy,-1,ierr)
                            lwrk_qgeqrf = int(rdummy(1),KIND=ilp)
                            call la_qgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,rdummy, &
                                       -1,ierr)
                            lwrk_qgesvd2 = int(rdummy(1),KIND=ilp)
                            call la_qormqr('R','C',n,n,n/2,u,ldu,rdummy,v,ldv, &
                                      rdummy,-1,ierr)
                            lwrk_qormqr2 = int(rdummy(1),KIND=ilp)
                            optwrk2 = max(lwrk_qgeqp3,n/2 + lwrk_qgeqrf,n/2 + lwrk_qgesvd2,n/2 + &
                                      lwrk_qormqr2)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     else
                        call la_qgesvd('S','O',n,n,a,lda,s,u,ldu,v,ldv,rdummy,-1, &
                                  ierr)
                        lwrk_qgesvd = int(rdummy(1),KIND=ilp)
                        optwrk = max(lwrk_qgeqp3,lwrk_qgesvd,lwrk_qormqr)
                        if (conda) optwrk = max(optwrk,lwcon)
                        optwrk = n + optwrk
                        if (wntva) then
                           call la_qgelqf(n/2,n,u,ldu,rdummy,rdummy,-1,ierr)
                           lwrk_qgelqf = int(rdummy(1),KIND=ilp)
                           call la_qgesvd('S','O',n/2,n/2,v,ldv,s,u,ldu,v,ldv,rdummy, &
                                      -1,ierr)
                           lwrk_qgesvd2 = int(rdummy(1),KIND=ilp)
                           call la_qormlq('R','N',n,n,n/2,u,ldu,rdummy,v,ldv,rdummy, &
                                     -1,ierr)
                           lwrk_qormlq = int(rdummy(1),KIND=ilp)
                           optwrk2 = max(lwrk_qgeqp3,n/2 + lwrk_qgelqf,n/2 + lwrk_qgesvd2,n/2 + &
                                     lwrk_qormlq)
                            if (conda) optwrk2 = max(optwrk2,lwcon)
                            optwrk2 = n + optwrk2
                            optwrk = max(optwrk,optwrk2)
                        end if
                     end if
                  end if
              end if
              minwrk = max(2,minwrk)
              optwrk = max(2,optwrk)
              if (lwork < minwrk .and. (.not. lquery)) info = -19
           end if
           if (info == 0 .and. lrwork < rminwrk .and. .not. lquery) then
              info = -21
           end if
           if (info /= 0) then
              call la_xerbla('DGESVDQ',-info)
              return
           else if (lquery) then
           ! return optimal workspace
               iwork(1) = iminwrk
               work(1) = optwrk
               work(2) = minwrk
               rwork(1) = rminwrk
               return
           end if
           ! quick return if the matrix is void.
           if ((m == 0) .or. (n == 0)) then
           ! All Output Is Void
              return
           end if
           big = la_qlamch('O')
           ascaled = .false.
           iwoff = 1
           if (rowprm) then
                 iwoff = m
                 ! Reordering The Rows In Decreasing Sequence In The
                 ! ell-infinity norm - this enhances numerical robustness in
                 ! the case of differently scaled rows.
                 do p = 1,m
                     ! rwork(p) = abs( a(p,la_izamax(n,a(p,1),lda)) )
                     ! [[la_qlange will return nan if an entry of the p-th row is nan]]
                     rwork(p) = la_qlange('M',1,n,a(p,1),lda,rdummy)
                     ! .. check for nan's and inf's
                     if ((rwork(p) /= rwork(p)) .or. ((rwork(p)*zero) /= zero)) then
                         info = -8
                         call la_xerbla('DGESVDQ',-info)
                         return
                     end if
                 end do
                 do p = 1,m - 1
                 q = la_iqamax(m - p + 1,rwork(p),1) + p - 1
                 iwork(n + p) = q
                 if (p /= q) then
                    rtmp = rwork(p)
                    rwork(p) = rwork(q)
                    rwork(q) = rtmp
                 end if
                 end do
                 if (rwork(1) == zero) then
                    ! quick return: a is the m x n zero matrix.
                    numrank = 0
                    call la_qlaset('G',n,1,zero,zero,s,n)
                    if (wntus) call la_qlaset('G',m,n,zero,one,u,ldu)
                    if (wntua) call la_qlaset('G',m,m,zero,one,u,ldu)
                    if (wntva) call la_qlaset('G',n,n,zero,one,v,ldv)
                    if (wntuf) then
                        call la_qlaset('G',n,1,zero,zero,work,n)
                        call la_qlaset('G',m,n,zero,one,u,ldu)
                    end if
                    do p = 1,n
                        iwork(p) = p
                    end do
                    if (rowprm) then
                        do p = n + 1,n + m - 1
                            iwork(p) = p - n
                        end do
                    end if
                    if (conda) rwork(1) = -1
                    rwork(2) = -1
                    return
                 end if
                 if (rwork(1) > big/sqrt(real(m,KIND=qp))) then
                     ! .. to prevent overflow in the qr factorization, scale the
                     ! matrix by 1/sqrt(m) if too large entry detected
                     call la_qlascl('G',0,0,sqrt(real(m,KIND=qp)),one,m,n,a,lda,ierr)

                     ascaled = .true.
                 end if
                 call la_qlaswp(n,a,lda,1,m - 1,iwork(n + 1),1)
           end if
          ! .. at this stage, preemptive scaling is done only to avoid column
          ! norms overflows during the qr factorization. the svd procedure should
          ! have its own scaling to save the singular values from overflows and
          ! underflows. that depends on the svd procedure.
           if (.not. rowprm) then
               rtmp = la_qlange('M',m,n,a,lda,rdummy)
               if ((rtmp /= rtmp) .or. ((rtmp*zero) /= zero)) then
                    info = -8
                    call la_xerbla('DGESVDQ',-info)
                    return
               end if
               if (rtmp > big/sqrt(real(m,KIND=qp))) then
                   ! .. to prevent overflow in the qr factorization, scale the
                   ! matrix by 1/sqrt(m) if too large entry detected
                   call la_qlascl('G',0,0,sqrt(real(m,KIND=qp)),one,m,n,a,lda,ierr)

                   ascaled = .true.
               end if
           end if
           ! Qr Factorization With Column Pivoting
           ! a * p = q * [ r ]
                       ! [ 0 ]
           do p = 1,n
              ! All Columns Are Free Columns
              iwork(p) = 0
           end do
           call la_qgeqp3(m,n,a,lda,iwork,work,work(n + 1),lwork - n,ierr)
          ! if the user requested accuracy level allows truncation in the
          ! computed upper triangular factor, the matrix r is examined and,
          ! if possible, replaced with its leading upper trapezoidal part.
           epsln = la_qlamch('E')
           sfmin = la_qlamch('S')
           ! small = sfmin / epsln
           nr = n
           if (accla) then
              ! standard absolute error bound suffices. all sigma_i with
              ! sigma_i < n*eps*||a||_f are flushed to zero. this is an
              ! aggressive enforcement of lower numerical rank by introducing a
              ! backward error of the order of n*eps*||a||_f.
              nr = 1
              rtmp = sqrt(real(n,KIND=qp))*epsln
              do p = 2,n
                 if (abs(a(p,p)) < (rtmp*abs(a(1,1)))) go to 3002
                    nr = nr + 1
              end do
              3002 continue
           elseif (acclm) then
              ! .. similarly as above, only slightly more gentle (less aggressive).
              ! sudden drop on the diagonal of r is used as the criterion for being
              ! close-to-rank-deficient. the threshold is set to epsln=la_qlamch('e').
              ! [[this can be made more flexible by replacing this hard-coded value
              ! with a user specified threshold.]] also, the values that underflow
              ! will be truncated.
              nr = 1
              do p = 2,n
                 if ((abs(a(p,p)) < (epsln*abs(a(p - 1,p - 1)))) .or. (abs(a(p,p)) < sfmin)) go &
                           to 3402
                 nr = nr + 1
              end do
              3402 continue
           else
              ! Rrqr Not Authorized To Determine Numerical Rank Except In The
              ! obvious case of zero pivots.
              ! .. inspect r for exact zeros on the diagonal;
              ! r(i,i)=0 => r(i:n,i:n)=0.
              nr = 1
              do p = 2,n
                 if (abs(a(p,p)) == zero) go to 3502
                 nr = nr + 1
              end do
              3502 continue
              if (conda) then
                 ! estimate the scaled condition number of a. use the fact that it is
                 ! the same as the scaled condition number of r.
                    ! V Is Used As Workspace
                    call la_qlacpy('U',n,n,a,lda,v,ldv)
                    ! only the leading nr x nr submatrix of the triangular factor
                    ! is considered. only if nr=n will this give a reliable error
                    ! bound. however, even for nr < n, this can be used on an
                    ! expert level and obtain useful information in the sense of
                    ! perturbation theory.
                    do p = 1,nr
                       rtmp = la_qnrm2(p,v(1,p),1)
                       call la_qscal(p,one/rtmp,v(1,p),1)
                    end do
                    if (.not. (lsvec .or. rsvec)) then
                        call la_qpocon('U',nr,v,ldv,one,rtmp,work,iwork(n + iwoff),ierr &
                                  )
                    else
                        call la_qpocon('U',nr,v,ldv,one,rtmp,work(n + 1),iwork(n + iwoff), &
                                  ierr)
                    end if
                    sconda = one/sqrt(rtmp)
                 ! for nr=n, sconda is an estimate of sqrt(||(r^* * r)^(-1)||_1),
                 ! n^(-1/4) * sconda <= ||r^(-1)||_2 <= n^(1/4) * sconda
                 ! see the reference [1] for more details.
              end if
           end if
           if (wntur) then
               n1 = nr
           else if (wntus .or. wntuf) then
               n1 = n
           else if (wntua) then
               n1 = m
           end if
           if (.not. (rsvec .or. lsvec)) then
      ! .......................................................................
              ! Only The Singular Values Are Requested
      ! .......................................................................
              if (rtrans) then
               ! .. compute the singular values of r**t = [a](1:nr,1:n)**t
                 ! .. set the lower triangle of [a] to [a](1:nr,1:n)**t and
                 ! the upper triangle of [a] to zero.
                 do p = 1,min(n,nr)
                    do q = p + 1,n
                       a(q,p) = a(p,q)
                       if (q <= nr) a(p,q) = zero
                    end do
                 end do
                 call la_qgesvd('N','N',n,nr,a,lda,s,u,ldu,v,ldv,work,lwork,info &
                           )
              else
                 ! .. compute the singular values of r = [a](1:nr,1:n)
                 if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,a(2,1),lda)
                 call la_qgesvd('N','N',nr,n,a,lda,s,u,ldu,v,ldv,work,lwork,info &
                           )
              end if
           else if (lsvec .and. (.not. rsvec)) then
      ! .......................................................................
             ! The Singular Values And The Left Singular Vectors Requested
      ! .......................................................................""""""""
              if (rtrans) then
                  ! .. apply la_qgesvd to r**t
                  ! .. copy r**t into [u] and overwrite [u] with the right singular
                  ! vectors of r
                 do p = 1,nr
                    do q = p,n
                       u(q,p) = a(p,q)
                    end do
                 end do
                 if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,u(1,2),ldu)
                 ! .. the left singular vectors not computed, the nr right singular
                 ! vectors overwrite [u](1:nr,1:nr) as transposed. these
                 ! will be pre-multiplied by q to build the left singular vectors of a.
                    call la_qgesvd('N','O',n,nr,u,ldu,s,u,ldu,u,ldu,work(n + 1), &
                              lwork - n,info)
                    do p = 1,nr
                        do q = p + 1,nr
                           rtmp = u(q,p)
                           u(q,p) = u(p,q)
                           u(p,q) = rtmp
                        end do
                    end do
              else
                  ! Apply la_Dgesvd To R
                  ! .. copy r into [u] and overwrite [u] with the left singular vectors
                  call la_qlacpy('U',nr,n,a,lda,u,ldu)
                  if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,u(2,1),ldu)

                  ! .. the right singular vectors not computed, the nr left singular
                  ! vectors overwrite [u](1:nr,1:nr)
                     call la_qgesvd('O','N',nr,n,u,ldu,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     ! .. now [u](1:nr,1:nr) contains the nr left singular vectors of
                     ! r. these will be pre-multiplied by q to build the left singular
                     ! vectors of a.
              end if
                 ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
              if ((nr < m) .and. (.not. wntuf)) then
                  call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                  if (nr < n1) then
                     call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                     call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                  end if
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_qormqr('L','N',m,n1,n,a,lda,work,u,ldu,work( &
                        n + 1),lwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_qlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           else if (rsvec .and. (.not. lsvec)) then
      ! .......................................................................
             ! The Singular Values And The Right Singular Vectors Requested
      ! .......................................................................
               if (rtrans) then
                  ! .. apply la_qgesvd to r**t
                  ! .. copy r**t into v and overwrite v with the left singular vectors
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = (a(p,q))
                    end do
                 end do
                 if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 ! .. the left singular vectors of r**t overwrite v, the right singular
                 ! vectors not computed
                 if (wntvr .or. (nr == n)) then
                    call la_qgesvd('O','N',n,nr,v,ldv,s,u,ldu,u,ldu,work(n + 1), &
                              lwork - n,info)
                    do p = 1,nr
                        do q = p + 1,nr
                           rtmp = v(q,p)
                           v(q,p) = v(p,q)
                           v(p,q) = rtmp
                        end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                               v(p,q) = v(q,p)
                           end do
                        end do
                    end if
                    call la_qlapmt(.false.,nr,n,v,ldv,iwork)
                 else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:n,1:nr)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the qr factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                     call la_qlaset('G',n,n - nr,zero,zero,v(1,nr + 1),ldv)
                     call la_qgesvd('O','N',n,n,v,ldv,s,u,ldu,u,ldu,work(n + 1), &
                               lwork - n,info)
                     do p = 1,n
                        do q = p + 1,n
                           rtmp = v(q,p)
                           v(q,p) = v(p,q)
                           v(p,q) = rtmp
                        end do
                     end do
                     call la_qlapmt(.false.,n,n,v,ldv,iwork)
                 end if
               else
                  ! Aply la_Dgesvd To R
                  ! Copy R Into V And Overwrite V With The Right Singular Vectors
                  call la_qlacpy('U',nr,n,a,lda,v,ldv)
                  if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                  ! .. the right singular vectors overwrite v, the nr left singular
                  ! vectors stored in u(1:nr,1:nr)
                  if (wntvr .or. (nr == n)) then
                     call la_qgesvd('N','O',nr,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     call la_qlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**t
                  else
                     ! .. need all n right singular vectors and nr < n
                     ! [!] this is simple implementation that augments [v](1:nr,1:n)
                     ! by padding a zero block. in the case nr << n, a more efficient
                     ! way is to first use the lq factorization. for more details
                     ! how to implement this, see the " full svd " branch.
                      call la_qlaset('G',n - nr,n,zero,zero,v(nr + 1,1),ldv)
                      call la_qgesvd('N','O',n,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                                lwork - n,info)
                      call la_qlapmt(.false.,n,n,v,ldv,iwork)
                  end if
                  ! .. now [v] contains the transposed matrix of the right singular
                  ! vectors of a.
               end if
           else
      ! .......................................................................
             ! Full Svd Requested
      ! .......................................................................
              if (rtrans) then
                  ! .. apply la_qgesvd to r**t [[this option is left for r
                 if (wntvr .or. (nr == n)) then
                  ! .. copy r**t into [v] and overwrite [v] with the left singular
                  ! vectors of r**t
                 do p = 1,nr
                    do q = p,n
                       v(q,p) = a(p,q)
                    end do
                 end do
                 if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                 ! .. the left singular vectors of r**t overwrite [v], the nr right
                 ! singular vectors of r**t stored in [u](1:nr,1:nr) as transposed
                    call la_qgesvd('O','A',n,nr,v,ldv,s,v,ldv,u,ldu,work(n + 1), &
                              lwork - n,info)
                    ! Assemble V
                    do p = 1,nr
                       do q = p + 1,nr
                          rtmp = v(q,p)
                          v(q,p) = v(p,q)
                          v(p,q) = rtmp
                       end do
                    end do
                    if (nr < n) then
                        do p = 1,nr
                           do q = nr + 1,n
                              v(p,q) = v(q,p)
                           end do
                        end do
                    end if
                    call la_qlapmt(.false.,nr,n,v,ldv,iwork)
                     do p = 1,nr
                        do q = p + 1,nr
                           rtmp = u(q,p)
                           u(q,p) = u(p,q)
                           u(p,q) = rtmp
                        end do
                     end do
                     if ((nr < m) .and. .not. (wntuf)) then
                       call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                       end if
                    end if
                 else
                     ! .. need all n right singular vectors and nr < n
                  ! .. copy r**t into [v] and overwrite [v] with the left singular
                  ! vectors of r**t
                     ! [[the optimal ratio n/nr for using qrf instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'dgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                     optratio = 2
                     if (optratio*nr > n) then
                        do p = 1,nr
                           do q = p,n
                              v(q,p) = a(p,q)
                           end do
                        end do
                        if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)

                        call la_qlaset('A',n,n - nr,zero,zero,v(1,nr + 1),ldv)
                        call la_qgesvd('O','A',n,n,v,ldv,s,v,ldv,u,ldu,work(n + 1), &
                                  lwork - n,info)
                        do p = 1,n
                           do q = p + 1,n
                              rtmp = v(q,p)
                              v(q,p) = v(p,q)
                              v(p,q) = rtmp
                           end do
                        end do
                        call la_qlapmt(.false.,n,n,v,ldv,iwork)
                    ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x n1), i.e. (m x n) or (m x m).
                        do p = 1,n
                           do q = p + 1,n
                              rtmp = u(q,p)
                              u(q,p) = u(p,q)
                              u(p,q) = rtmp
                           end do
                        end do
                        if ((n < m) .and. .not. (wntuf)) then
                           call la_qlaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_qlaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                             call la_qlaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                           end if
                        end if
                     else
                        ! .. copy r**t into [u] and overwrite [u] with the right
                        ! singular vectors of r
                        do p = 1,nr
                           do q = p,n
                              u(q,nr + p) = a(p,q)
                           end do
                        end do
                        if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,u(1,nr + 2),ldu)

                        call la_qgeqrf(n,nr,u(1,nr + 1),ldu,work(n + 1),work(n + nr + 1),lwork - &
                                  n - nr,ierr)
                        do p = 1,nr
                            do q = 1,n
                                v(q,p) = u(p,nr + q)
                            end do
                        end do
                       call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                       call la_qgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,work(n + nr + 1) &
                                 ,lwork - n - nr,info)
                       call la_qlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_qlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_qlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       call la_qormqr('R','C',n,n,nr,u(1,nr + 1),ldu,work(n + 1),v,ldv,work( &
                                 n + nr + 1),lwork - n - nr,ierr)
                       call la_qlapmt(.false.,n,n,v,ldv,iwork)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                     end if
                 end if
              else
                  ! .. apply la_qgesvd to r [[this is the recommended option]]
                  if (wntvr .or. (nr == n)) then
                      ! .. copy r into [v] and overwrite v with the right singular vectors
                      call la_qlacpy('U',nr,n,a,lda,v,ldv)
                     if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                     ! .. the right singular vectors of r overwrite [v], the nr left
                     ! singular vectors of r stored in [u](1:nr,1:nr)
                     call la_qgesvd('S','O',nr,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                               lwork - n,info)
                     call la_qlapmt(.false.,nr,n,v,ldv,iwork)
                     ! .. now [v](1:nr,1:n) contains v(1:n,1:nr)**t
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                    if ((nr < m) .and. .not. (wntuf)) then
                       call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                       if (nr < n1) then
                          call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                       end if
                    end if
                  else
                    ! .. need all n right singular vectors and nr < n
                    ! The Requested Number Of The Left Singular Vectors
                     ! is then n1 (n or m)
                     ! [[the optimal ratio n/nr for using lq instead of padding
                       ! with zeros. here hard coded to 2; it must be at least
                       ! two due to work space constraints.]]
                     ! optratio = la_ilaenv(6, 'dgesvd', 's' // 'o', nr,n,0,0)
                     ! optratio = max( optratio, 2 )
                    optratio = 2
                    if (optratio*nr > n) then
                       call la_qlacpy('U',nr,n,a,lda,v,ldv)
                       if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,v(2,1),ldv)

                    ! .. the right singular vectors of r overwrite [v], the nr left
                       ! singular vectors of r stored in [u](1:nr,1:nr)
                       call la_qlaset('A',n - nr,n,zero,zero,v(nr + 1,1),ldv)
                       call la_qgesvd('S','O',n,n,v,ldv,s,u,ldu,v,ldv,work(n + 1), &
                                 lwork - n,info)
                       call la_qlapmt(.false.,n,n,v,ldv,iwork)
                       ! .. now [v] contains the transposed matrix of the right
                       ! singular vectors of a. the leading n left singular vectors
                       ! are in [u](1:n,1:n)
                       ! Assemble The Left Singular Vector Matrix U Of Dimensions
                       ! (m x n1), i.e. (m x n) or (m x m).
                       if ((n < m) .and. .not. (wntuf)) then
                           call la_qlaset('A',m - n,n,zero,zero,u(n + 1,1),ldu)
                           if (n < n1) then
                             call la_qlaset('A',n,n1 - n,zero,zero,u(1,n + 1),ldu)
                             call la_qlaset('A',m - n,n1 - n,zero,one,u(n + 1,n + 1),ldu)
                           end if
                       end if
                    else
                       call la_qlacpy('U',nr,n,a,lda,u(nr + 1,1),ldu)
                       if (nr > 1) call la_qlaset('L',nr - 1,nr - 1,zero,zero,u(nr + 2,1),ldu)

                       call la_qgelqf(nr,n,u(nr + 1,1),ldu,work(n + 1),work(n + nr + 1),lwork - n - &
                                 nr,ierr)
                       call la_qlacpy('L',nr,nr,u(nr + 1,1),ldu,v,ldv)
                       if (nr > 1) call la_qlaset('U',nr - 1,nr - 1,zero,zero,v(1,2),ldv)
                       call la_qgesvd('S','O',nr,nr,v,ldv,s,u,ldu,v,ldv,work(n + nr + &
                                 1),lwork - n - nr,info)
                       call la_qlaset('A',n - nr,nr,zero,zero,v(nr + 1,1),ldv)
                       call la_qlaset('A',nr,n - nr,zero,zero,v(1,nr + 1),ldv)
                       call la_qlaset('A',n - nr,n - nr,zero,one,v(nr + 1,nr + 1),ldv)
                       call la_qormlq('R','N',n,n,nr,u(nr + 1,1),ldu,work(n + 1),v,ldv,work(n + &
                                 nr + 1),lwork - n - nr,ierr)
                       call la_qlapmt(.false.,n,n,v,ldv,iwork)
                     ! Assemble The Left Singular Vector Matrix U Of Dimensions
                    ! (m x nr) or (m x n) or (m x m).
                       if ((nr < m) .and. .not. (wntuf)) then
                          call la_qlaset('A',m - nr,nr,zero,zero,u(nr + 1,1),ldu)
                          if (nr < n1) then
                          call la_qlaset('A',nr,n1 - nr,zero,zero,u(1,nr + 1),ldu)
                          call la_qlaset('A',m - nr,n1 - nr,zero,one,u(nr + 1,nr + 1),ldu)
                          end if
                       end if
                    end if
                  end if
              ! .. end of the "r**t or r" branch
              end if
                 ! the q matrix from the first qrf is built into the left singular
                 ! vectors matrix u.
              if (.not. wntuf) call la_qormqr('L','N',m,n1,n,a,lda,work,u,ldu,work( &
                        n + 1),lwork - n,ierr)
              if (rowprm .and. .not. wntuf) call la_qlaswp(n1,u,ldu,1,m - 1,iwork(n + 1),- &
                        1)
           ! ... end of the "full svd" branch
           end if
           ! check whether some singular values are returned as zeros, e.g.
           ! due to underflow, and update the numerical rank.
           p = nr
           do q = p,1,-1
               if (s(q) > zero) go to 4002
               nr = nr - 1
           end do
           4002 continue
           ! .. if numerical rank deficiency is detected, the truncated
           ! singular values are set to zero.
           if (nr < n) call la_qlaset('G',n - nr,1,zero,zero,s(nr + 1),n)
           ! .. undo scaling; this may cause overflow in the largest singular
           ! values.
           if (ascaled) call la_qlascl('G',0,0,one,sqrt(real(m,KIND=qp)),nr,1,s,n,ierr &
                     )
           if (conda) rwork(1) = sconda
           rwork(2) = p - nr
           ! .. p-nr is the number of singular values that are computed as
           ! exact zeros in la_qgesvd() applied to the (possibly truncated)
           ! full row rank triangular (trapezoidal) factor of a.
           numrank = nr
           return
     end subroutine la_qgesvdq

     !> DGESVJ: computes the singular value decomposition (SVD) of a real
     !> M-by-N matrix A, where M >= N. The SVD of A is written as
     !> [++]   [xx]   [x0]   [xx]
     !> A = U * SIGMA * V^t,  [++] = [xx] * [ox] * [xx]
     !> [++]   [xx]
     !> where SIGMA is an N-by-N diagonal matrix, U is an M-by-N orthonormal
     !> matrix, and V is an N-by-N orthogonal matrix. The diagonal elements
     !> of SIGMA are the singular values of A. The columns of U and V are the
     !> left and the right singular vectors of A, respectively.
     !> DGESVJ can sometimes compute tiny singular values and their singular vectors much
     !> more accurately than other SVD routines, see below under Further Details.

     pure subroutine la_qgesvj(joba,jobu,jobv,m,n,a,lda,sva,mv,v,ldv,work,lwork, &
               info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldv,lwork,m,mv,n
           character,intent(in) :: joba,jobu,jobv
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),v(ldv,*),work(lwork)
           real(qp),intent(out) :: sva(n)
        ! =====================================================================
           ! Local Parameters
           integer(ilp),parameter :: nsweep = 30

           ! Local Scalars
           real(qp) :: aapp,aapp0,aapq,aaqq,apoaq,aqoap,big,bigtheta,cs,ctol,epsln, &
           large,mxaapq,mxsinj,rootbig,rooteps,rootsfmin,roottol,skl,sfmin,small,sn,t, &
                     temp1,theta,thsign,tol
           integer(ilp) :: blskip,emptsw,i,ibr,ierr,igl,ijblsk,ir1,iswrot,jbc,jgl,kbl, &
                     lkahead,mvl,n2,n34,n4,nbl,notrot,p,pskipped,q,rowskip,swband
           logical(lk) :: applv,goscale,lower,lsvec,noscale,rotok,rsvec,uctol, &
                     upper
           ! Local Arrays
           real(qp) :: fastr(5)
           ! Intrinsic Functions
           intrinsic :: abs,max,min,real,sign,sqrt
           ! from lapack
           ! from lapack
           ! Executable Statements
           ! test the input arguments
           lsvec = la_lsame(jobu,'U')
           uctol = la_lsame(jobu,'C')
           rsvec = la_lsame(jobv,'V')
           applv = la_lsame(jobv,'A')
           upper = la_lsame(joba,'U')
           lower = la_lsame(joba,'L')
           if (.not. (upper .or. lower .or. la_lsame(joba,'G'))) then
              info = -1
           else if (.not. (lsvec .or. uctol .or. la_lsame(jobu,'N'))) then
              info = -2
           else if (.not. (rsvec .or. applv .or. la_lsame(jobv,'N'))) then
              info = -3
           else if (m < 0) then
              info = -4
           else if ((n < 0) .or. (n > m)) then
              info = -5
           else if (lda < m) then
              info = -7
           else if (mv < 0) then
              info = -9
           else if ((rsvec .and. (ldv < n)) .or. (applv .and. (ldv < mv))) then
              info = -11
           else if (uctol .and. (work(1) <= one)) then
              info = -12
           else if (lwork < max(m + n,6)) then
              info = -13
           else
              info = 0
           end if
           ! #:(
           if (info /= 0) then
              call la_xerbla('DGESVJ',-info)
              return
           end if
       ! #:) quick return for void matrix
           if ((m == 0) .or. (n == 0)) return
           ! set numerical parameters
           ! the stopping criterion for jacobi rotations is
           ! max_{i<>j}|a(:,i)^t * a(:,j)|/(||a(:,i)||*||a(:,j)||) < ctol*eps
           ! where eps is the round-off and ctol is defined as follows:
           if (uctol) then
              ! ... user controlled
              ctol = work(1)
           else
              ! ... default
              if (lsvec .or. rsvec .or. applv) then
                 ctol = sqrt(real(m,KIND=qp))
              else
                 ctol = real(m,KIND=qp)
              end if
           end if
           ! ... and the machine dependent parameters are
      ! [!]  (make sure that la_qlamch() works properly on the target machine.)
           epsln = la_qlamch('EPSILON')
           rooteps = sqrt(epsln)
           sfmin = la_qlamch('SAFEMINIMUM')
           rootsfmin = sqrt(sfmin)
           small = sfmin/epsln
           big = la_qlamch('OVERFLOW')
           ! big         = one    / sfmin
           rootbig = one/rootsfmin
           large = big/sqrt(real(m*n,KIND=qp))
           bigtheta = one/rooteps
           tol = ctol*epsln
           roottol = sqrt(tol)
           if (real(m,KIND=qp)*epsln >= one) then
              info = -4
              call la_xerbla('DGESVJ',-info)
              return
           end if
           ! initialize the right singular vector matrix.
           if (rsvec) then
              mvl = n
              call la_qlaset('A',mvl,n,zero,one,v,ldv)
           else if (applv) then
              mvl = mv
           end if
           rsvec = rsvec .or. applv
           ! initialize sva( 1:n ) = ( ||a e_i||_2, i = 1:n )
      ! (!)  if necessary, scale a to protect the largest singular value
           ! from overflow. it is possible that saving the largest singular
           ! value destroys the information about the small ones.
           ! this initial scaling is almost minimal in the sense that the
           ! goal is to make sure that no column norm overflows, and that
           ! sqrt(n)*max_i sva(i) does not overflow. if infinite entries
           ! in a are detected, the procedure returns with info=-6.
           skl = one/sqrt(real(m,KIND=qp)*real(n,KIND=qp))
           noscale = .true.
           goscale = .true.
           if (lower) then
              ! the input matrix is m-by-n lower triangular (trapezoidal)
              do p = 1,n
                 aapp = zero
                 aaqq = one
                 call la_qlassq(m - p + 1,a(p,p),1,aapp,aaqq)
                 if (aapp > big) then
                    info = -6
                    call la_xerbla('DGESVJ',-info)
                    return
                 end if
                 aaqq = sqrt(aaqq)
                 if ((aapp < (big/aaqq)) .and. noscale) then
                    sva(p) = aapp*aaqq
                 else
                    noscale = .false.
                    sva(p) = aapp*(aaqq*skl)
                    if (goscale) then
                       goscale = .false.
                       do q = 1,p - 1
                          sva(q) = sva(q)*skl
                       end do
                    end if
                 end if
              end do
           else if (upper) then
              ! the input matrix is m-by-n upper triangular (trapezoidal)
              do p = 1,n
                 aapp = zero
                 aaqq = one
                 call la_qlassq(p,a(1,p),1,aapp,aaqq)
                 if (aapp > big) then
                    info = -6
                    call la_xerbla('DGESVJ',-info)
                    return
                 end if
                 aaqq = sqrt(aaqq)
                 if ((aapp < (big/aaqq)) .and. noscale) then
                    sva(p) = aapp*aaqq
                 else
                    noscale = .false.
                    sva(p) = aapp*(aaqq*skl)
                    if (goscale) then
                       goscale = .false.
                       do q = 1,p - 1
                          sva(q) = sva(q)*skl
                       end do
                    end if
                 end if
              end do
           else
              ! the input matrix is m-by-n general dense
              do p = 1,n
                 aapp = zero
                 aaqq = one
                 call la_qlassq(m,a(1,p),1,aapp,aaqq)
                 if (aapp > big) then
                    info = -6
                    call la_xerbla('DGESVJ',-info)
                    return
                 end if
                 aaqq = sqrt(aaqq)
                 if ((aapp < (big/aaqq)) .and. noscale) then
                    sva(p) = aapp*aaqq
                 else
                    noscale = .false.
                    sva(p) = aapp*(aaqq*skl)
                    if (goscale) then
                       goscale = .false.
                       do q = 1,p - 1
                          sva(q) = sva(q)*skl
                       end do
                    end if
                 end if
              end do
           end if
           if (noscale) skl = one
           ! move the smaller part of the spectrum from the underflow threshold
      ! (!)  start by determining the position of the nonzero entries of the
           ! array sva() relative to ( sfmin, big ).
           aapp = zero
           aaqq = big
           do p = 1,n
              if (sva(p) /= zero) aaqq = min(aaqq,sva(p))
              aapp = max(aapp,sva(p))
           end do
       ! #:) quick return for zero matrix
           if (aapp == zero) then
              if (lsvec) call la_qlaset('G',m,n,zero,one,a,lda)
              work(1) = one
              work(2) = zero
              work(3) = zero
              work(4) = zero
              work(5) = zero
              work(6) = zero
              return
           end if
       ! #:) quick return for one-column matrix
           if (n == 1) then
              if (lsvec) call la_qlascl('G',0,0,sva(1),skl,m,1,a(1,1),lda,ierr)

              work(1) = one/skl
              if (sva(1) >= sfmin) then
                 work(2) = one
              else
                 work(2) = zero
              end if
              work(3) = zero
              work(4) = zero
              work(5) = zero
              work(6) = zero
              return
           end if
           ! protect small singular values from underflow, and try to
           ! avoid underflows/overflows in computing jacobi rotations.
           sn = sqrt(sfmin/epsln)
           temp1 = sqrt(big/real(n,KIND=qp))
           if ((aapp <= sn) .or. (aaqq >= temp1) .or. ((sn <= aaqq) .and. (aapp <= temp1))) &
                     then
              temp1 = min(big,temp1/aapp)
               ! aaqq  = aaqq*temp1
               ! aapp  = aapp*temp1
           else if ((aaqq <= sn) .and. (aapp <= temp1)) then
              temp1 = min(sn/aaqq,big/(aapp*sqrt(real(n,KIND=qp))))
               ! aaqq  = aaqq*temp1
               ! aapp  = aapp*temp1
           else if ((aaqq >= sn) .and. (aapp >= temp1)) then
              temp1 = max(sn/aaqq,temp1/aapp)
               ! aaqq  = aaqq*temp1
               ! aapp  = aapp*temp1
           else if ((aaqq <= sn) .and. (aapp >= temp1)) then
              temp1 = min(sn/aaqq,big/(sqrt(real(n,KIND=qp))*aapp))
               ! aaqq  = aaqq*temp1
               ! aapp  = aapp*temp1
           else
              temp1 = one
           end if
           ! scale, if necessary
           if (temp1 /= one) then
              call la_qlascl('G',0,0,one,temp1,n,1,sva,n,ierr)
           end if
           skl = temp1*skl
           if (skl /= one) then
              call la_qlascl(joba,0,0,one,skl,m,n,a,lda,ierr)
              skl = one/skl
           end if
           ! row-cyclic jacobi svd algorithm with column pivoting
           emptsw = (n*(n - 1))/2
           notrot = 0
           fastr(1) = zero
           ! a is represented in factored form a = a * diag(work), where diag(work)
           ! is initialized to identity. work is updated during fast scaled
           ! rotations.
           do q = 1,n
              work(q) = one
           end do
           swband = 3
      ! [tp] swband is a tuning parameter [tp]. it is meaningful and effective
           ! if la_qgesvj is used as a computational routine in the preconditioned
           ! jacobi svd algorithm la_qgesvj. for sweeps i=1:swband the procedure
           ! works on pivots inside a band-like region around the diagonal.
           ! the boundaries are determined dynamically, based on the number of
           ! pivots above a threshold.
           kbl = min(8,n)
      ! [tp] kbl is a tuning parameter that defines the tile size in the
           ! tiling of the p-q loops of pivot pairs. in general, an optimal
           ! value of kbl depends on the matrix dimensions and on the
           ! parameters of the computer's memory.
           nbl = n/kbl
           if ((nbl*kbl) /= n) nbl = nbl + 1
           blskip = kbl**2
      ! [tp] blkskip is a tuning parameter that depends on swband and kbl.
           rowskip = min(5,kbl)
      ! [tp] rowskip is a tuning parameter.
           lkahead = 1
      ! [tp] lkahead is a tuning parameter.
           ! quasi block transformations, using the lower (upper) triangular
           ! structure of the input matrix. the quasi-block-cycling usually
           ! invokes cubic convergence. big part of this cycle is done inside
           ! canonical subspaces of dimensions less than m.
           if ((lower .or. upper) .and. (n > max(64,4*kbl))) then
      ! [tp] the number of partition levels and the actual partition are
           ! tuning parameters.
              n4 = n/4
              n2 = n/2
              n34 = 3*n4
              if (applv) then
                 q = 0
              else
                 q = 1
              end if
              if (lower) then
           ! this works very well on lower triangular matrices, in particular
           ! in the framework of the preconditioned jacobi svd (xgejsv).
           ! the idea is simple:
           ! [+ 0 0 0]   note that jacobi transformations of [0 0]
           ! [+ + 0 0]                                       [0 0]
           ! [+ + x 0]   actually work on [x 0]              [x 0]
           ! [+ + x x]                    [x x].             [x x]
                 call la_qgsvj0(jobv,m - n34,n - n34,a(n34 + 1,n34 + 1),lda,work(n34 + 1), &
                 sva(n34 + 1),mvl,v(n34*q + 1,n34 + 1),ldv,epsln,sfmin,tol,2,work(n + 1), &
                           lwork - n,ierr)
                 call la_qgsvj0(jobv,m - n2,n34 - n2,a(n2 + 1,n2 + 1),lda,work(n2 + 1),sva( &
                 n2 + 1),mvl,v(n2*q + 1,n2 + 1),ldv,epsln,sfmin,tol,2,work(n + 1),lwork - n, &
                           ierr)
                 call la_qgsvj1(jobv,m - n2,n - n2,n4,a(n2 + 1,n2 + 1),lda,work(n2 + 1),sva( &
                  n2 + 1),mvl,v(n2*q + 1,n2 + 1),ldv,epsln,sfmin,tol,1,work(n + 1),lwork - n, &
                            ierr)
                 call la_qgsvj0(jobv,m - n4,n2 - n4,a(n4 + 1,n4 + 1),lda,work(n4 + 1),sva( &
                 n4 + 1),mvl,v(n4*q + 1,n4 + 1),ldv,epsln,sfmin,tol,1,work(n + 1),lwork - n, &
                           ierr)
                 call la_qgsvj0(jobv,m,n4,a,lda,work,sva,mvl,v,ldv,epsln,sfmin, &
                           tol,1,work(n + 1),lwork - n,ierr)
                 call la_qgsvj1(jobv,m,n2,n4,a,lda,work,sva,mvl,v,ldv,epsln,sfmin, &
                            tol,1,work(n + 1),lwork - n,ierr)
              else if (upper) then
                 call la_qgsvj0(jobv,n4,n4,a,lda,work,sva,mvl,v,ldv,epsln,sfmin, &
                           tol,2,work(n + 1),lwork - n,ierr)
                 call la_qgsvj0(jobv,n2,n4,a(1,n4 + 1),lda,work(n4 + 1),sva(n4 + 1), &
                 mvl,v(n4*q + 1,n4 + 1),ldv,epsln,sfmin,tol,1,work(n + 1),lwork - n,ierr)

                 call la_qgsvj1(jobv,n2,n2,n4,a,lda,work,sva,mvl,v,ldv,epsln, &
                           sfmin,tol,1,work(n + 1),lwork - n,ierr)
                 call la_qgsvj0(jobv,n2 + n4,n4,a(1,n2 + 1),lda,work(n2 + 1),sva(n2 + 1), &
                  mvl,v(n2*q + 1,n2 + 1),ldv,epsln,sfmin,tol,1,work(n + 1),lwork - n,ierr)

              end if
           end if
           ! .. row-cyclic pivot strategy with de rijk's pivoting ..
           loop_1993: do i = 1,nsweep
           ! .. go go go ...
              mxaapq = zero
              mxsinj = zero
              iswrot = 0
              notrot = 0
              pskipped = 0
           ! each sweep is unrolled using kbl-by-kbl tiles over the pivot pairs
           ! 1 <= p < q <= n. this is the first step toward a blocked implementation
           ! of the rotations. new implementation, based on block transformations,
           ! is under development.
              loop_2000: do ibr = 1,nbl
                 igl = (ibr - 1)*kbl + 1
                 loop_1002: do ir1 = 0,min(lkahead,nbl - ibr)
                    igl = igl + ir1*kbl
                    loop_2001: do p = igl,min(igl + kbl - 1,n - 1)
           ! .. de rijk's pivoting
                       q = la_iqamax(n - p + 1,sva(p),1) + p - 1
                       if (p /= q) then
                          call la_qswap(m,a(1,p),1,a(1,q),1)
                          if (rsvec) call la_qswap(mvl,v(1,p),1,v(1,q),1)
                          temp1 = sva(p)
                          sva(p) = sva(q)
                          sva(q) = temp1
                          temp1 = work(p)
                          work(p) = work(q)
                          work(q) = temp1
                       end if
                       if (ir1 == 0) then
              ! column norms are periodically updated by explicit
              ! norm computation.
              ! caveat:
              ! unfortunately, some blas implementations compute la_qnrm2(m,a(1,p),1)
              ! as sqrt(la_qdot(m,a(1,p),1,a(1,p),1)), which may cause the result to
              ! overflow for ||a(:,p)||_2 > sqrt(overflow_threshold), and to
              ! underflow for ||a(:,p)||_2 < sqrt(underflow_threshold).
              ! hence, la_qnrm2 cannot be trusted, not even in the case when
              ! the true norm is far from the under(over)flow boundaries.
              ! if properly implemented la_qnrm2 is available, the if-then-else
              ! below should read "aapp = la_qnrm2( m, a(1,p), 1 ) * work(p)".
                          if ((sva(p) < rootbig) .and. (sva(p) > rootsfmin)) then
                             sva(p) = la_qnrm2(m,a(1,p),1)*work(p)
                          else
                             temp1 = zero
                             aapp = one
                             call la_qlassq(m,a(1,p),1,temp1,aapp)
                             sva(p) = temp1*sqrt(aapp)*work(p)
                          end if
                          aapp = sva(p)
                       else
                          aapp = sva(p)
                       end if
                       if (aapp > zero) then
                          pskipped = 0
                          loop_2002: do q = p + 1,min(igl + kbl - 1,n)
                             aaqq = sva(q)
                             if (aaqq > zero) then
                                aapp0 = aapp
                                if (aaqq >= one) then
                                   rotok = (small*aapp) <= aaqq
                                   if (aapp < (big/aaqq)) then
                                      aapq = (la_qdot(m,a(1,p),1,a(1,q),1)*work( &
                                                p)*work(q)/aaqq)/aapp
                                   else
                                      call la_qcopy(m,a(1,p),1,work(n + 1),1)
                                      call la_qlascl('G',0,0,aapp,work(p),m,1,work(n + &
                                                1),lda,ierr)
                                      aapq = la_qdot(m,work(n + 1),1,a(1,q),1)*work( &
                                                q)/aaqq
                                   end if
                                else
                                   rotok = aapp <= (aaqq/small)
                                   if (aapp > (small/aaqq)) then
                                      aapq = (la_qdot(m,a(1,p),1,a(1,q),1)*work( &
                                                p)*work(q)/aaqq)/aapp
                                   else
                                      call la_qcopy(m,a(1,q),1,work(n + 1),1)
                                      call la_qlascl('G',0,0,aaqq,work(q),m,1,work(n + &
                                                1),lda,ierr)
                                      aapq = la_qdot(m,work(n + 1),1,a(1,p),1)*work( &
                                                p)/aapp
                                   end if
                                end if
                                mxaapq = max(mxaapq,abs(aapq))
              ! to rotate or not to rotate, that is the question ...
                                if (abs(aapq) > tol) then
                 ! Rotate
      ! [rtd]      rotated = rotated + one
                                   if (ir1 == 0) then
                                      notrot = 0
                                      pskipped = 0
                                      iswrot = iswrot + 1
                                   end if
                                   if (rotok) then
                                      aqoap = aaqq/aapp
                                      apoaq = aapp/aaqq
                                      theta = -half*abs(aqoap - apoaq)/aapq
                                      if (abs(theta) > bigtheta) then
                                         t = half/theta
                                         fastr(3) = t*work(p)/work(q)
                                         fastr(4) = -t*work(q)/work(p)
                                         call la_qrotm(m,a(1,p),1,a(1,q),1,fastr)

                                         if (rsvec) call la_qrotm(mvl,v(1,p),1,v(1,q), &
                                                    1,fastr)
                                         sva(q) = aaqq*sqrt(max(zero,one + t*apoaq*aapq))

                                         aapp = aapp*sqrt(max(zero,one - t*aqoap*aapq))
                                         mxsinj = max(mxsinj,abs(t))
                                      else
                       ! Choose Correct Signum For Theta And Rotate
                                         thsign = -sign(one,aapq)
                                         t = one/(theta + thsign*sqrt(one + theta*theta))

                                         cs = sqrt(one/(one + t*t))
                                         sn = t*cs
                                         mxsinj = max(mxsinj,abs(sn))
                                         sva(q) = aaqq*sqrt(max(zero,one + t*apoaq*aapq))

                                         aapp = aapp*sqrt(max(zero,one - t*aqoap*aapq))
                                         apoaq = work(p)/work(q)
                                         aqoap = work(q)/work(p)
                                         if (work(p) >= one) then
                                            if (work(q) >= one) then
                                               fastr(3) = t*apoaq
                                               fastr(4) = -t*aqoap
                                               work(p) = work(p)*cs
                                               work(q) = work(q)*cs
                                               call la_qrotm(m,a(1,p),1,a(1,q),1, &
                                                         fastr)
                                               if (rsvec) call la_qrotm(mvl,v(1,p),1,v( &
                                                         1,q),1,fastr)
                                            else
                                               call la_qaxpy(m,-t*aqoap,a(1,q),1,a(1, &
                                                         p),1)
                                               call la_qaxpy(m,cs*sn*apoaq,a(1,p),1,a( &
                                                         1,q),1)
                                               work(p) = work(p)*cs
                                               work(q) = work(q)/cs
                                               if (rsvec) then
                                                  call la_qaxpy(mvl,-t*aqoap,v(1,q),1,v( &
                                                             1,p),1)
                                                  call la_qaxpy(mvl,cs*sn*apoaq,v(1,p),1, &
                                                            v(1,q),1)
                                               end if
                                            end if
                                         else
                                            if (work(q) >= one) then
                                               call la_qaxpy(m,t*apoaq,a(1,p),1,a(1,q &
                                                         ),1)
                                               call la_qaxpy(m,-cs*sn*aqoap,a(1,q),1,a( &
                                                         1,p),1)
                                               work(p) = work(p)/cs
                                               work(q) = work(q)*cs
                                               if (rsvec) then
                                                  call la_qaxpy(mvl,t*apoaq,v(1,p),1,v( &
                                                            1,q),1)
                                                  call la_qaxpy(mvl,-cs*sn*aqoap,v(1,q), &
                                                            1,v(1,p),1)
                                               end if
                                            else
                                               if (work(p) >= work(q)) then
                                                  call la_qaxpy(m,-t*aqoap,a(1,q),1,a( &
                                                            1,p),1)
                                                  call la_qaxpy(m,cs*sn*apoaq,a(1,p),1, &
                                                            a(1,q),1)
                                                  work(p) = work(p)*cs
                                                  work(q) = work(q)/cs
                                                  if (rsvec) then
                                                     call la_qaxpy(mvl,-t*aqoap,v(1,q),1, &
                                                               v(1,p),1)
                                                     call la_qaxpy(mvl,cs*sn*apoaq,v(1,p), &
                                                                1,v(1,q),1)
                                                  end if
                                               else
                                                  call la_qaxpy(m,t*apoaq,a(1,p),1,a(1, &
                                                             q),1)
                                                  call la_qaxpy(m,-cs*sn*aqoap,a(1,q),1, &
                                                            a(1,p),1)
                                                  work(p) = work(p)/cs
                                                  work(q) = work(q)*cs
                                                  if (rsvec) then
                                                     call la_qaxpy(mvl,t*apoaq,v(1,p),1, &
                                                               v(1,q),1)
                                                     call la_qaxpy(mvl,-cs*sn*aqoap,v(1,q) &
                                                               ,1,v(1,p),1)
                                                  end if
                                               end if
                                            end if
                                         end if
                                      end if
                                   else
                    ! .. have to use modified gram-schmidt like transformation
                                      call la_qcopy(m,a(1,p),1,work(n + 1),1)
                                      call la_qlascl('G',0,0,aapp,one,m,1,work(n + 1), &
                                                lda,ierr)
                                      call la_qlascl('G',0,0,aaqq,one,m,1,a(1,q), &
                                                lda,ierr)
                                      temp1 = -aapq*work(p)/work(q)
                                      call la_qaxpy(m,temp1,work(n + 1),1,a(1,q),1)

                                      call la_qlascl('G',0,0,one,aaqq,m,1,a(1,q), &
                                                lda,ierr)
                                      sva(q) = aaqq*sqrt(max(zero,one - aapq*aapq))
                                      mxsinj = max(mxsinj,sfmin)
                                   end if
                 ! end if rotok then ... else
                 ! in the case of cancellation in updating sva(q), sva(p)
                 ! recompute sva(q), sva(p).
                                   if ((sva(q)/aaqq)**2 <= rooteps) then
                                      if ((aaqq < rootbig) .and. (aaqq > rootsfmin)) then
                                         sva(q) = la_qnrm2(m,a(1,q),1)*work(q)

                                      else
                                         t = zero
                                         aaqq = one
                                         call la_qlassq(m,a(1,q),1,t,aaqq)
                                         sva(q) = t*sqrt(aaqq)*work(q)
                                      end if
                                   end if
                                   if ((aapp/aapp0) <= rooteps) then
                                      if ((aapp < rootbig) .and. (aapp > rootsfmin)) then
                                         aapp = la_qnrm2(m,a(1,p),1)*work(p)
                                      else
                                         t = zero
                                         aapp = one
                                         call la_qlassq(m,a(1,p),1,t,aapp)
                                         aapp = t*sqrt(aapp)*work(p)
                                      end if
                                      sva(p) = aapp
                                   end if
                                else
              ! a(:,p) and a(:,q) already numerically orthogonal
                                   if (ir1 == 0) notrot = notrot + 1
      ! [rtd]      skipped  = skipped  + 1
                                   pskipped = pskipped + 1
                                end if
                             else
              ! a(:,q) is zero column
                                if (ir1 == 0) notrot = notrot + 1
                                pskipped = pskipped + 1
                             end if
                             if ((i <= swband) .and. (pskipped > rowskip)) then
                                if (ir1 == 0) aapp = -aapp
                                notrot = 0
                                go to 2103
                             end if
                          end do loop_2002
           ! end q-loop
           2103 continue
           ! bailed out of q-loop
                          sva(p) = aapp
                       else
                          sva(p) = aapp
                          if ((ir1 == 0) .and. (aapp == zero)) notrot = notrot + min(igl + kbl - 1, &
                                    n) - p
                       end if
                    end do loop_2001
           ! end of the p-loop
           ! end of doing the block ( ibr, ibr )
                 end do loop_1002
           ! end of ir1-loop
       ! ... go to the off diagonal blocks
                 igl = (ibr - 1)*kbl + 1
                 loop_2010: do jbc = ibr + 1,nbl
                    jgl = (jbc - 1)*kbl + 1
              ! doing the block at ( ibr, jbc )
                    ijblsk = 0
                    loop_2100: do p = igl,min(igl + kbl - 1,n)
                       aapp = sva(p)
                       if (aapp > zero) then
                          pskipped = 0
                          loop_2200: do q = jgl,min(jgl + kbl - 1,n)
                             aaqq = sva(q)
                             if (aaqq > zero) then
                                aapp0 = aapp
           ! M X 2 Jacobi Svd
              ! safe gram matrix computation
                                if (aaqq >= one) then
                                   if (aapp >= aaqq) then
                                      rotok = (small*aapp) <= aaqq
                                   else
                                      rotok = (small*aaqq) <= aapp
                                   end if
                                   if (aapp < (big/aaqq)) then
                                      aapq = (la_qdot(m,a(1,p),1,a(1,q),1)*work( &
                                                p)*work(q)/aaqq)/aapp
                                   else
                                      call la_qcopy(m,a(1,p),1,work(n + 1),1)
                                      call la_qlascl('G',0,0,aapp,work(p),m,1,work(n + &
                                                1),lda,ierr)
                                      aapq = la_qdot(m,work(n + 1),1,a(1,q),1)*work( &
                                                q)/aaqq
                                   end if
                                else
                                   if (aapp >= aaqq) then
                                      rotok = aapp <= (aaqq/small)
                                   else
                                      rotok = aaqq <= (aapp/small)
                                   end if
                                   if (aapp > (small/aaqq)) then
                                      aapq = (la_qdot(m,a(1,p),1,a(1,q),1)*work( &
                                                p)*work(q)/aaqq)/aapp
                                   else
                                      call la_qcopy(m,a(1,q),1,work(n + 1),1)
                                      call la_qlascl('G',0,0,aaqq,work(q),m,1,work(n + &
                                                1),lda,ierr)
                                      aapq = la_qdot(m,work(n + 1),1,a(1,p),1)*work( &
                                                p)/aapp
                                   end if
                                end if
                                mxaapq = max(mxaapq,abs(aapq))
              ! to rotate or not to rotate, that is the question ...
                                if (abs(aapq) > tol) then
                                   notrot = 0
      ! [rtd]      rotated  = rotated + 1
                                   pskipped = 0
                                   iswrot = iswrot + 1
                                   if (rotok) then
                                      aqoap = aaqq/aapp
                                      apoaq = aapp/aaqq
                                      theta = -half*abs(aqoap - apoaq)/aapq
                                      if (aaqq > aapp0) theta = -theta
                                      if (abs(theta) > bigtheta) then
                                         t = half/theta
                                         fastr(3) = t*work(p)/work(q)
                                         fastr(4) = -t*work(q)/work(p)
                                         call la_qrotm(m,a(1,p),1,a(1,q),1,fastr)

                                         if (rsvec) call la_qrotm(mvl,v(1,p),1,v(1,q), &
                                                    1,fastr)
                                         sva(q) = aaqq*sqrt(max(zero,one + t*apoaq*aapq))

                                         aapp = aapp*sqrt(max(zero,one - t*aqoap*aapq))
                                         mxsinj = max(mxsinj,abs(t))
                                      else
                       ! Choose Correct Signum For Theta And Rotate
                                         thsign = -sign(one,aapq)
                                         if (aaqq > aapp0) thsign = -thsign
                                         t = one/(theta + thsign*sqrt(one + theta*theta))

                                         cs = sqrt(one/(one + t*t))
                                         sn = t*cs
                                         mxsinj = max(mxsinj,abs(sn))
                                         sva(q) = aaqq*sqrt(max(zero,one + t*apoaq*aapq))

                                         aapp = aapp*sqrt(max(zero,one - t*aqoap*aapq))
                                         apoaq = work(p)/work(q)
                                         aqoap = work(q)/work(p)
                                         if (work(p) >= one) then
                                            if (work(q) >= one) then
                                               fastr(3) = t*apoaq
                                               fastr(4) = -t*aqoap
                                               work(p) = work(p)*cs
                                               work(q) = work(q)*cs
                                               call la_qrotm(m,a(1,p),1,a(1,q),1, &
                                                         fastr)
                                               if (rsvec) call la_qrotm(mvl,v(1,p),1,v( &
                                                         1,q),1,fastr)
                                            else
                                               call la_qaxpy(m,-t*aqoap,a(1,q),1,a(1, &
                                                         p),1)
                                               call la_qaxpy(m,cs*sn*apoaq,a(1,p),1,a( &
                                                         1,q),1)
                                               if (rsvec) then
                                                  call la_qaxpy(mvl,-t*aqoap,v(1,q),1,v( &
                                                             1,p),1)
                                                  call la_qaxpy(mvl,cs*sn*apoaq,v(1,p),1, &
                                                            v(1,q),1)
                                               end if
                                               work(p) = work(p)*cs
                                               work(q) = work(q)/cs
                                            end if
                                         else
                                            if (work(q) >= one) then
                                               call la_qaxpy(m,t*apoaq,a(1,p),1,a(1,q &
                                                         ),1)
                                               call la_qaxpy(m,-cs*sn*aqoap,a(1,q),1,a( &
                                                         1,p),1)
                                               if (rsvec) then
                                                  call la_qaxpy(mvl,t*apoaq,v(1,p),1,v( &
                                                            1,q),1)
                                                  call la_qaxpy(mvl,-cs*sn*aqoap,v(1,q), &
                                                            1,v(1,p),1)
                                               end if
                                               work(p) = work(p)/cs
                                               work(q) = work(q)*cs
                                            else
                                               if (work(p) >= work(q)) then
                                                  call la_qaxpy(m,-t*aqoap,a(1,q),1,a( &
                                                            1,p),1)
                                                  call la_qaxpy(m,cs*sn*apoaq,a(1,p),1, &
                                                            a(1,q),1)
                                                  work(p) = work(p)*cs
                                                  work(q) = work(q)/cs
                                                  if (rsvec) then
                                                     call la_qaxpy(mvl,-t*aqoap,v(1,q),1, &
                                                               v(1,p),1)
                                                     call la_qaxpy(mvl,cs*sn*apoaq,v(1,p), &
                                                                1,v(1,q),1)
                                                  end if
                                               else
                                                  call la_qaxpy(m,t*apoaq,a(1,p),1,a(1, &
                                                             q),1)
                                                  call la_qaxpy(m,-cs*sn*aqoap,a(1,q),1, &
                                                            a(1,p),1)
                                                  work(p) = work(p)/cs
                                                  work(q) = work(q)*cs
                                                  if (rsvec) then
                                                     call la_qaxpy(mvl,t*apoaq,v(1,p),1, &
                                                               v(1,q),1)
                                                     call la_qaxpy(mvl,-cs*sn*aqoap,v(1,q) &
                                                               ,1,v(1,p),1)
                                                  end if
                                               end if
                                            end if
                                         end if
                                      end if
                                   else
                                      if (aapp > aaqq) then
                                         call la_qcopy(m,a(1,p),1,work(n + 1),1)

                                         call la_qlascl('G',0,0,aapp,one,m,1,work(n + 1 &
                                                   ),lda,ierr)
                                         call la_qlascl('G',0,0,aaqq,one,m,1,a(1,q), &
                                                    lda,ierr)
                                         temp1 = -aapq*work(p)/work(q)
                                         call la_qaxpy(m,temp1,work(n + 1),1,a(1,q),1 &
                                                   )
                                         call la_qlascl('G',0,0,one,aaqq,m,1,a(1,q), &
                                                    lda,ierr)
                                         sva(q) = aaqq*sqrt(max(zero,one - aapq*aapq))
                                         mxsinj = max(mxsinj,sfmin)
                                      else
                                         call la_qcopy(m,a(1,q),1,work(n + 1),1)

                                         call la_qlascl('G',0,0,aaqq,one,m,1,work(n + 1 &
                                                   ),lda,ierr)
                                         call la_qlascl('G',0,0,aapp,one,m,1,a(1,p), &
                                                    lda,ierr)
                                         temp1 = -aapq*work(q)/work(p)
                                         call la_qaxpy(m,temp1,work(n + 1),1,a(1,p),1 &
                                                   )
                                         call la_qlascl('G',0,0,one,aapp,m,1,a(1,p), &
                                                    lda,ierr)
                                         sva(p) = aapp*sqrt(max(zero,one - aapq*aapq))
                                         mxsinj = max(mxsinj,sfmin)
                                      end if
                                   end if
                 ! end if rotok then ... else
                 ! in the case of cancellation in updating sva(q)
                 ! .. recompute sva(q)
                                   if ((sva(q)/aaqq)**2 <= rooteps) then
                                      if ((aaqq < rootbig) .and. (aaqq > rootsfmin)) then
                                         sva(q) = la_qnrm2(m,a(1,q),1)*work(q)

                                      else
                                         t = zero
                                         aaqq = one
                                         call la_qlassq(m,a(1,q),1,t,aaqq)
                                         sva(q) = t*sqrt(aaqq)*work(q)
                                      end if
                                   end if
                                   if ((aapp/aapp0)**2 <= rooteps) then
                                      if ((aapp < rootbig) .and. (aapp > rootsfmin)) then
                                         aapp = la_qnrm2(m,a(1,p),1)*work(p)
                                      else
                                         t = zero
                                         aapp = one
                                         call la_qlassq(m,a(1,p),1,t,aapp)
                                         aapp = t*sqrt(aapp)*work(p)
                                      end if
                                      sva(p) = aapp
                                   end if
                    ! end of ok rotation
                                else
                                   notrot = notrot + 1
      ! [rtd]      skipped  = skipped  + 1
                                   pskipped = pskipped + 1
                                   ijblsk = ijblsk + 1
                                end if
                             else
                                notrot = notrot + 1
                                pskipped = pskipped + 1
                                ijblsk = ijblsk + 1
                             end if
                             if ((i <= swband) .and. (ijblsk >= blskip)) then
                                sva(p) = aapp
                                notrot = 0
                                go to 2011
                             end if
                             if ((i <= swband) .and. (pskipped > rowskip)) then
                                aapp = -aapp
                                notrot = 0
                                go to 2203
                             end if
                          end do loop_2200
              ! end of the q-loop
              2203 continue
                          sva(p) = aapp
                       else
                          if (aapp == zero) notrot = notrot + min(jgl + kbl - 1,n) - jgl + 1
                          if (aapp < zero) notrot = 0
                       end if
                    end do loop_2100
           ! end of the p-loop
                 end do loop_2010
           ! end of the jbc-loop
           2011 continue
      ! 2011 bailed out of the jbc-loop
                 do p = igl,min(igl + kbl - 1,n)
                    sva(p) = abs(sva(p))
                 end do
      ! **
              end do loop_2000
      ! 2000 :: end of the ibr-loop
           ! .. update sva(n)
              if ((sva(n) < rootbig) .and. (sva(n) > rootsfmin)) then
                 sva(n) = la_qnrm2(m,a(1,n),1)*work(n)
              else
                 t = zero
                 aapp = one
                 call la_qlassq(m,a(1,n),1,t,aapp)
                 sva(n) = t*sqrt(aapp)*work(n)
              end if
           ! additional steering devices
              if ((i < swband) .and. ((mxaapq <= roottol) .or. (iswrot <= n))) swband = i
              if ((i > swband + 1) .and. (mxaapq < sqrt(real(n,KIND=qp))*tol) .and. (real(n, &
                        KIND=qp)*mxaapq*mxsinj < tol)) then
                 go to 1994
              end if
              if (notrot >= emptsw) go to 1994
           end do loop_1993
           ! end i=1:nsweep loop
       ! #:( reaching this point means that the procedure has not converged.
           info = nsweep - 1
           go to 1995
           1994 continue
       ! #:) reaching this point means numerical convergence after the i-th
           ! sweep.
           info = 0
       ! #:) info = 0 confirms successful iterations.
       1995 continue
           ! sort the singular values and find how many are above
           ! the underflow threshold.
           n2 = 0
           n4 = 0
           do p = 1,n - 1
              q = la_iqamax(n - p + 1,sva(p),1) + p - 1
              if (p /= q) then
                 temp1 = sva(p)
                 sva(p) = sva(q)
                 sva(q) = temp1
                 temp1 = work(p)
                 work(p) = work(q)
                 work(q) = temp1
                 call la_qswap(m,a(1,p),1,a(1,q),1)
                 if (rsvec) call la_qswap(mvl,v(1,p),1,v(1,q),1)
              end if
              if (sva(p) /= zero) then
                 n4 = n4 + 1
                 if (sva(p)*skl > sfmin) n2 = n2 + 1
              end if
           end do
           if (sva(n) /= zero) then
              n4 = n4 + 1
              if (sva(n)*skl > sfmin) n2 = n2 + 1
           end if
           ! normalize the left singular vectors.
           if (lsvec .or. uctol) then
              do p = 1,n2
                 call la_qscal(m,work(p)/sva(p),a(1,p),1)
              end do
           end if
           ! scale the product of jacobi rotations (assemble the fast rotations).
           if (rsvec) then
              if (applv) then
                 do p = 1,n
                    call la_qscal(mvl,work(p),v(1,p),1)
                 end do
              else
                 do p = 1,n
                    temp1 = one/la_qnrm2(mvl,v(1,p),1)
                    call la_qscal(mvl,temp1,v(1,p),1)
                 end do
              end if
           end if
           ! undo scaling, if necessary (and possible).
           if (((skl > one) .and. (sva(1) < (big/skl))) .or. ((skl < one) .and. (sva(max( &
                      n2,1)) > (sfmin/skl)))) then
              do p = 1,n
                 sva(p) = skl*sva(p)
              end do
              skl = one
           end if
           work(1) = skl
           ! the singular values of a are skl*sva(1:n). if skl/=one
           ! then some of the singular values may overflow or underflow and
           ! the spectrum is given in this factored representation.
           work(2) = real(n4,KIND=qp)
           ! n4 is the number of computed nonzero singular values of a.
           work(3) = real(n2,KIND=qp)
           ! n2 is the number of singular values of a greater than sfmin.
           ! if n2<n, sva(n2:n) contains zeros and/or denormalized numbers
           ! that may carry some information.
           work(4) = real(i,KIND=qp)
           ! i is the index of the last sweep before declaring convergence.
           work(5) = mxaapq
           ! mxaapq is the largest absolute value of scaled pivots in the
           ! last sweep
           work(6) = mxsinj
           ! mxsinj is the largest absolute value of the sines of jacobi angles
           ! in the last sweep
           return
     end subroutine la_qgesvj

     !> DGETSLS: solves overdetermined or underdetermined real linear systems
     !> involving an M-by-N matrix A, using a tall skinny QR or short wide LQ
     !> factorization of A.  It is assumed that A has full rank.
     !> The following options are provided:
     !> 1. If TRANS = 'N' and m >= n:  find the least squares solution of
     !> an overdetermined system, i.e., solve the least squares problem
     !> minimize || B - A*X ||.
     !> 2. If TRANS = 'N' and m < n:  find the minimum norm solution of
     !> an underdetermined system A * X = B.
     !> 3. If TRANS = 'T' and m >= n:  find the minimum norm solution of
     !> an undetermined system A**T * X = B.
     !> 4. If TRANS = 'T' and m < n:  find the least squares solution of
     !> an overdetermined system, i.e., solve the least squares problem
     !> minimize || B - A**T * X ||.
     !> Several right hand side vectors b and solution vectors x can be
     !> handled in a single call; they are stored as the columns of the
     !> M-by-NRHS right hand side matrix B and the N-by-NRHS solution
     !> matrix X.

     subroutine la_qgetsls(trans,m,n,nrhs,a,lda,b,ldb,work,lwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,lwork,m,n,nrhs
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,tran
           integer(ilp) :: i,iascl,ibscl,j,maxmn,brow,scllen,tszo,tszm,lwo,lwm,lw1, &
                     lw2,wsizeo,wsizem,info2
           real(qp) :: anrm,bignum,bnrm,smlnum,tq(5),workq(1)
           ! Intrinsic Functions
           intrinsic :: real,max,min,int
           ! Executable Statements
           ! test the input arguments.
           info = 0
           maxmn = max(m,n)
           tran = la_lsame(trans,'T')
           lquery = (lwork == -1 .or. lwork == -2)
           if (.not. (la_lsame(trans,'N') .or. la_lsame(trans,'T'))) then
              info = -1
           else if (m < 0) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (nrhs < 0) then
              info = -4
           else if (lda < max(1,m)) then
              info = -6
           else if (ldb < max(1,m,n)) then
              info = -8
           end if
           if (info == 0) then
           ! determine the optimum and minimum lwork
            if (m >= n) then
              call la_qgeqr(m,n,a,lda,tq,-1,workq,-1,info2)
              tszo = int(tq(1),KIND=ilp)
              lwo = int(workq(1),KIND=ilp)
              call la_qgemqr('L',trans,m,nrhs,n,a,lda,tq,tszo,b,ldb,workq,-1, &
                        info2)
              lwo = max(lwo,int(workq(1),KIND=ilp))
              call la_qgeqr(m,n,a,lda,tq,-2,workq,-2,info2)
              tszm = int(tq(1),KIND=ilp)
              lwm = int(workq(1),KIND=ilp)
              call la_qgemqr('L',trans,m,nrhs,n,a,lda,tq,tszm,b,ldb,workq,-1, &
                        info2)
              lwm = max(lwm,int(workq(1),KIND=ilp))
              wsizeo = tszo + lwo
              wsizem = tszm + lwm
            else
              call la_qgelq(m,n,a,lda,tq,-1,workq,-1,info2)
              tszo = int(tq(1),KIND=ilp)
              lwo = int(workq(1),KIND=ilp)
              call la_qgemlq('L',trans,n,nrhs,m,a,lda,tq,tszo,b,ldb,workq,-1, &
                        info2)
              lwo = max(lwo,int(workq(1),KIND=ilp))
              call la_qgelq(m,n,a,lda,tq,-2,workq,-2,info2)
              tszm = int(tq(1),KIND=ilp)
              lwm = int(workq(1),KIND=ilp)
              call la_qgemlq('L',trans,n,nrhs,m,a,lda,tq,tszm,b,ldb,workq,-1, &
                        info2)
              lwm = max(lwm,int(workq(1),KIND=ilp))
              wsizeo = tszo + lwo
              wsizem = tszm + lwm
            end if
            if ((lwork < wsizem) .and. (.not. lquery)) then
               info = -10
            end if
            work(1) = real(wsizeo,KIND=qp)
           end if
           if (info /= 0) then
             call la_xerbla('DGETSLS',-info)
             return
           end if
           if (lquery) then
             if (lwork == -2) work(1) = real(wsizem,KIND=qp)
             return
           end if
           if (lwork < wsizeo) then
             lw1 = tszm
             lw2 = lwm
           else
             lw1 = tszo
             lw2 = lwo
           end if
           ! quick return if possible
           if (min(m,n,nrhs) == 0) then
                call la_qlaset('FULL',max(m,n),nrhs,zero,zero,b,ldb)
                return
           end if
           ! get machine parameters
            smlnum = la_qlamch('S')/la_qlamch('P')
            bignum = one/smlnum
            call la_qlabad(smlnum,bignum)
           ! scale a, b if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',m,n,a,lda,work)
           iascl = 0
           if (anrm > zero .and. anrm < smlnum) then
              ! scale matrix norm up to smlnum
              call la_qlascl('G',0,0,anrm,smlnum,m,n,a,lda,info)
              iascl = 1
           else if (anrm > bignum) then
              ! scale matrix norm down to bignum
              call la_qlascl('G',0,0,anrm,bignum,m,n,a,lda,info)
              iascl = 2
           else if (anrm == zero) then
              ! matrix all zero. return zero solution.
              call la_qlaset('F',maxmn,nrhs,zero,zero,b,ldb)
              go to 50
           end if
           brow = m
           if (tran) then
             brow = n
           end if
           bnrm = la_qlange('M',brow,nrhs,b,ldb,work)
           ibscl = 0
           if (bnrm > zero .and. bnrm < smlnum) then
              ! scale matrix norm up to smlnum
              call la_qlascl('G',0,0,bnrm,smlnum,brow,nrhs,b,ldb,info)
              ibscl = 1
           else if (bnrm > bignum) then
              ! scale matrix norm down to bignum
              call la_qlascl('G',0,0,bnrm,bignum,brow,nrhs,b,ldb,info)
              ibscl = 2
           end if
           if (m >= n) then
              ! compute qr factorization of a
             call la_qgeqr(m,n,a,lda,work(lw2 + 1),lw1,work(1),lw2,info)
             if (.not. tran) then
                 ! least-squares problem min || a * x - b ||
                 ! b(1:m,1:nrhs) := q**t * b(1:m,1:nrhs)
               call la_qgemqr('L','T',m,nrhs,n,a,lda,work(lw2 + 1),lw1,b,ldb,work( &
                          1),lw2,info)
                 ! b(1:n,1:nrhs) := inv(r) * b(1:n,1:nrhs)
               call la_qtrtrs('U','N','N',n,nrhs,a,lda,b,ldb,info)
               if (info > 0) then
                 return
               end if
               scllen = n
             else
                 ! overdetermined system of equations a**t * x = b
                 ! b(1:n,1:nrhs) := inv(r**t) * b(1:n,1:nrhs)
                 call la_qtrtrs('U','T','N',n,nrhs,a,lda,b,ldb,info)
                 if (info > 0) then
                    return
                 end if
                 ! b(n+1:m,1:nrhs) = zero
                 do j = 1,nrhs
                    do i = n + 1,m
                       b(i,j) = zero
                    end do
                 end do
                 ! b(1:m,1:nrhs) := q(1:n,:) * b(1:n,1:nrhs)
                 call la_qgemqr('L','N',m,nrhs,n,a,lda,work(lw2 + 1),lw1,b,ldb, &
                           work(1),lw2,info)
                 scllen = m
              end if
           else
              ! compute lq factorization of a
              call la_qgelq(m,n,a,lda,work(lw2 + 1),lw1,work(1),lw2,info)
              ! workspace at least m, optimally m*nb.
              if (.not. tran) then
                 ! underdetermined system of equations a * x = b
                 ! b(1:m,1:nrhs) := inv(l) * b(1:m,1:nrhs)
                 call la_qtrtrs('L','N','N',m,nrhs,a,lda,b,ldb,info)
                 if (info > 0) then
                    return
                 end if
                 ! b(m+1:n,1:nrhs) = 0
                 do j = 1,nrhs
                    do i = m + 1,n
                       b(i,j) = zero
                    end do
                 end do
                 ! b(1:n,1:nrhs) := q(1:n,:)**t * b(1:m,1:nrhs)
                 call la_qgemlq('L','T',n,nrhs,m,a,lda,work(lw2 + 1),lw1,b,ldb, &
                           work(1),lw2,info)
                 ! workspace at least nrhs, optimally nrhs*nb
                 scllen = n
              else
                 ! overdetermined system min || a**t * x - b ||
                 ! b(1:n,1:nrhs) := q * b(1:n,1:nrhs)
                 call la_qgemlq('L','N',n,nrhs,m,a,lda,work(lw2 + 1),lw1,b,ldb, &
                           work(1),lw2,info)
                 ! workspace at least nrhs, optimally nrhs*nb
                 ! b(1:m,1:nrhs) := inv(l**t) * b(1:m,1:nrhs)
                 call la_qtrtrs('LOWER','TRANSPOSE','NON-UNIT',m,nrhs,a,lda,b,ldb, &
                           info)
                 if (info > 0) then
                    return
                 end if
                 scllen = m
              end if
           end if
           ! undo scaling
           if (iascl == 1) then
             call la_qlascl('G',0,0,anrm,smlnum,scllen,nrhs,b,ldb,info)
           else if (iascl == 2) then
             call la_qlascl('G',0,0,anrm,bignum,scllen,nrhs,b,ldb,info)
           end if
           if (ibscl == 1) then
             call la_qlascl('G',0,0,smlnum,bnrm,scllen,nrhs,b,ldb,info)
           else if (ibscl == 2) then
             call la_qlascl('G',0,0,bignum,bnrm,scllen,nrhs,b,ldb,info)
           end if
           50 continue
           work(1) = real(tszo + lwo,KIND=qp)
           return
     end subroutine la_qgetsls

     !> DGGBAK: forms the right or left eigenvectors of a real generalized
     !> eigenvalue problem A*x = lambda*B*x, by backward transformation on
     !> the computed eigenvectors of the balanced pair of matrices output by
     !> DGGBAL.

     pure subroutine la_qggbak(job,side,n,ilo,ihi,lscale,rscale,m,v,ldv,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: job,side
           integer(ilp),intent(in) :: ihi,ilo,ldv,m,n
           integer(ilp),intent(out) :: info
           ! Array Arguments
           real(qp),intent(in) :: lscale(*),rscale(*)
           real(qp),intent(inout) :: v(ldv,*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: leftv,rightv
           integer(ilp) :: i,k
           ! Intrinsic Functions
           intrinsic :: max,int
           ! Executable Statements
           ! test the input parameters
           rightv = la_lsame(side,'R')
           leftv = la_lsame(side,'L')
           info = 0
           if (.not. la_lsame(job,'N') .and. .not. la_lsame(job,'P') &
                     .and. .not. la_lsame(job,'S') .and. .not. la_lsame(job,'B')) then
              info = -1
           else if (.not. rightv .and. .not. leftv) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ilo < 1) then
              info = -4
           else if (n == 0 .and. ihi == 0 .and. ilo /= 1) then
              info = -4
           else if (n > 0 .and. (ihi < ilo .or. ihi > max(1,n))) then
              info = -5
           else if (n == 0 .and. ilo == 1 .and. ihi /= 0) then
              info = -5
           else if (m < 0) then
              info = -8
           else if (ldv < max(1,n)) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('DGGBAK',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (m == 0) return
           if (la_lsame(job,'N')) return
           if (ilo == ihi) go to 30
           ! backward balance
           if (la_lsame(job,'S') .or. la_lsame(job,'B')) then
              ! backward transformation on right eigenvectors
              if (rightv) then
                 do i = ilo,ihi
                    call la_qscal(m,rscale(i),v(i,1),ldv)
                 end do
              end if
              ! backward transformation on left eigenvectors
              if (leftv) then
                 do i = ilo,ihi
                    call la_qscal(m,lscale(i),v(i,1),ldv)
                 end do
              end if
           end if
           ! backward permutation
           30 continue
           if (la_lsame(job,'P') .or. la_lsame(job,'B')) then
              ! backward permutation on right eigenvectors
              if (rightv) then
                 if (ilo == 1) go to 50
                 loop_40: do i = ilo - 1,1,-1
                    k = int(rscale(i),KIND=ilp)
                    if (k == i) cycle loop_40
                    call la_qswap(m,v(i,1),ldv,v(k,1),ldv)
                 end do loop_40
                 50 continue
                 if (ihi == n) go to 70
                 loop_60: do i = ihi + 1,n
                    k = int(rscale(i),KIND=ilp)
                    if (k == i) cycle loop_60
                    call la_qswap(m,v(i,1),ldv,v(k,1),ldv)
                 end do loop_60
              end if
              ! backward permutation on left eigenvectors
              70 continue
              if (leftv) then
                 if (ilo == 1) go to 90
                 loop_80: do i = ilo - 1,1,-1
                    k = int(lscale(i),KIND=ilp)
                    if (k == i) cycle loop_80
                    call la_qswap(m,v(i,1),ldv,v(k,1),ldv)
                 end do loop_80
                 90 continue
                 if (ihi == n) go to 110
                 loop_100: do i = ihi + 1,n
                    k = int(lscale(i),KIND=ilp)
                    if (k == i) cycle loop_100
                    call la_qswap(m,v(i,1),ldv,v(k,1),ldv)
                 end do loop_100
              end if
           end if
           110 continue
           return
     end subroutine la_qggbak

     !> DGGBAL: balances a pair of general real matrices (A,B).  This
     !> involves, first, permuting A and B by similarity transformations to
     !> isolate eigenvalues in the first 1 to ILO$-$1 and last IHI+1 to N
     !> elements on the diagonal; and second, applying a diagonal similarity
     !> transformation to rows and columns ILO to IHI to make the rows
     !> and columns as close in norm as possible. Both steps are optional.
     !> Balancing may reduce the 1-norm of the matrices, and improve the
     !> accuracy of the computed eigenvalues and/or eigenvectors in the
     !> generalized eigenvalue problem A*x = lambda*B*x.

     pure subroutine la_qggbal(job,n,a,lda,b,ldb,ilo,ihi,lscale,rscale,work,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: job
           integer(ilp),intent(out) :: ihi,ilo,info
           integer(ilp),intent(in) :: lda,ldb,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: lscale(*),rscale(*),work(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: sclfac = 1.0e+1_qp

           ! Local Scalars
           integer(ilp) :: i,icab,iflow,ip1,ir,irab,it,j,jc,jp1,k,kount,l,lcab,lm1, &
                     lrab,lsfmax,lsfmin,m,nr,nrp2
           real(qp) :: alpha,basl,beta,cab,cmax,coef,coef2,coef5,cor,ew,ewc,gamma, &
                     pgamma,rab,sfmax,sfmin,sum,t,ta,tb,tc
           ! Intrinsic Functions
           intrinsic :: abs,real,int,log10,max,min,sign
           ! Executable Statements
           ! test the input parameters
           info = 0
           if (.not. la_lsame(job,'N') .and. .not. la_lsame(job,'P') &
                     .and. .not. la_lsame(job,'S') .and. .not. la_lsame(job,'B')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (ldb < max(1,n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('DGGBAL',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) then
              ilo = 1
              ihi = n
              return
           end if
           if (n == 1) then
              ilo = 1
              ihi = n
              lscale(1) = one
              rscale(1) = one
              return
           end if
           if (la_lsame(job,'N')) then
              ilo = 1
              ihi = n
              do i = 1,n
                 lscale(i) = one
                 rscale(i) = one
              end do
              return
           end if
           k = 1
           l = n
           if (la_lsame(job,'S')) go to 190
           go to 30
           ! permute the matrices a and b to isolate the eigenvalues.
           ! find row with one nonzero in columns 1 through l
           20 continue
           l = lm1
           if (l /= 1) go to 30
           rscale(1) = one
           lscale(1) = one
           go to 190
           30 continue
           lm1 = l - 1
           loop_80: do i = l,1,-1
              do j = 1,lm1
                 jp1 = j + 1
                 if (a(i,j) /= zero .or. b(i,j) /= zero) go to 50
              end do
              j = l
              go to 70
              50 continue
              do j = jp1,l
                 if (a(i,j) /= zero .or. b(i,j) /= zero) cycle loop_80
              end do
              j = jp1 - 1
              70 continue
              m = l
              iflow = 1
              go to 160
           end do loop_80
           go to 100
           ! find column with one nonzero in rows k through n
           90 continue
           k = k + 1
           100 continue
           loop_150: do j = k,l
              do i = k,lm1
                 ip1 = i + 1
                 if (a(i,j) /= zero .or. b(i,j) /= zero) go to 120
              end do
              i = l
              go to 140
              120 continue
              do i = ip1,l
                 if (a(i,j) /= zero .or. b(i,j) /= zero) cycle loop_150
              end do
              i = ip1 - 1
              140 continue
              m = k
              iflow = 2
              go to 160
           end do loop_150
           go to 190
           ! permute rows m and i
           160 continue
           lscale(m) = i
           if (i == m) go to 170
           call la_qswap(n - k + 1,a(i,k),lda,a(m,k),lda)
           call la_qswap(n - k + 1,b(i,k),ldb,b(m,k),ldb)
           ! permute columns m and j
           170 continue
           rscale(m) = j
           if (j == m) go to 180
           call la_qswap(l,a(1,j),1,a(1,m),1)
           call la_qswap(l,b(1,j),1,b(1,m),1)
           180 continue
           go to(20,90) iflow
           190 continue
           ilo = k
           ihi = l
           if (la_lsame(job,'P')) then
              do i = ilo,ihi
                 lscale(i) = one
                 rscale(i) = one
              end do
              return
           end if
           if (ilo == ihi) return
           ! balance the submatrix in rows ilo to ihi.
           nr = ihi - ilo + 1
           do i = ilo,ihi
              rscale(i) = zero
              lscale(i) = zero
              work(i) = zero
              work(i + n) = zero
              work(i + 2*n) = zero
              work(i + 3*n) = zero
              work(i + 4*n) = zero
              work(i + 5*n) = zero
           end do
           ! compute right side vector in resulting linear equations
           basl = log10(sclfac)
           do i = ilo,ihi
              do j = ilo,ihi
                 tb = b(i,j)
                 ta = a(i,j)
                 if (ta == zero) go to 210
                 ta = log10(abs(ta))/basl
                 210 continue
                 if (tb == zero) go to 220
                 tb = log10(abs(tb))/basl
                 220 continue
                 work(i + 4*n) = work(i + 4*n) - ta - tb
                 work(j + 5*n) = work(j + 5*n) - ta - tb
              end do
           end do
           coef = one/real(2*nr,KIND=qp)
           coef2 = coef*coef
           coef5 = half*coef2
           nrp2 = nr + 2
           beta = zero
           it = 1
           ! start generalized conjugate gradient iteration
           250 continue
           gamma = la_qdot(nr,work(ilo + 4*n),1,work(ilo + 4*n),1) + la_qdot(nr, &
                     work(ilo + 5*n),1,work(ilo + 5*n),1)
           ew = zero
           ewc = zero
           do i = ilo,ihi
              ew = ew + work(i + 4*n)
              ewc = ewc + work(i + 5*n)
           end do
           gamma = coef*gamma - coef2*(ew**2 + ewc**2) - coef5*(ew - ewc)**2
           if (gamma == zero) go to 350
           if (it /= 1) beta = gamma/pgamma
           t = coef5*(ewc - three*ew)
           tc = coef5*(ew - three*ewc)
           call la_qscal(nr,beta,work(ilo),1)
           call la_qscal(nr,beta,work(ilo + n),1)
           call la_qaxpy(nr,coef,work(ilo + 4*n),1,work(ilo + n),1)
           call la_qaxpy(nr,coef,work(ilo + 5*n),1,work(ilo),1)
           do i = ilo,ihi
              work(i) = work(i) + tc
              work(i + n) = work(i + n) + t
           end do
           ! apply matrix to vector
           do i = ilo,ihi
              kount = 0
              sum = zero
              loop_290: do j = ilo,ihi
                 if (a(i,j) == zero) go to 280
                 kount = kount + 1
                 sum = sum + work(j)
                 280 continue
                 if (b(i,j) == zero) cycle loop_290
                 kount = kount + 1
                 sum = sum + work(j)
              end do loop_290
              work(i + 2*n) = real(kount,KIND=qp)*work(i + n) + sum
           end do
           do j = ilo,ihi
              kount = 0
              sum = zero
              loop_320: do i = ilo,ihi
                 if (a(i,j) == zero) go to 310
                 kount = kount + 1
                 sum = sum + work(i + n)
                 310 continue
                 if (b(i,j) == zero) cycle loop_320
                 kount = kount + 1
                 sum = sum + work(i + n)
              end do loop_320
              work(j + 3*n) = real(kount,KIND=qp)*work(j) + sum
           end do
           sum = la_qdot(nr,work(ilo + n),1,work(ilo + 2*n),1) + la_qdot(nr,work( &
                     ilo),1,work(ilo + 3*n),1)
           alpha = gamma/sum
           ! determine correction to current iteration
           cmax = zero
           do i = ilo,ihi
              cor = alpha*work(i + n)
              if (abs(cor) > cmax) cmax = abs(cor)
              lscale(i) = lscale(i) + cor
              cor = alpha*work(i)
              if (abs(cor) > cmax) cmax = abs(cor)
              rscale(i) = rscale(i) + cor
           end do
           if (cmax < half) go to 350
           call la_qaxpy(nr,-alpha,work(ilo + 2*n),1,work(ilo + 4*n),1)
           call la_qaxpy(nr,-alpha,work(ilo + 3*n),1,work(ilo + 5*n),1)
           pgamma = gamma
           it = it + 1
           if (it <= nrp2) go to 250
           ! end generalized conjugate gradient iteration
           350 continue
           sfmin = la_qlamch('S')
           sfmax = one/sfmin
           lsfmin = int(log10(sfmin)/basl + one,KIND=ilp)
           lsfmax = int(log10(sfmax)/basl,KIND=ilp)
           do i = ilo,ihi
              irab = la_iqamax(n - ilo + 1,a(i,ilo),lda)
              rab = abs(a(i,irab + ilo - 1))
              irab = la_iqamax(n - ilo + 1,b(i,ilo),ldb)
              rab = max(rab,abs(b(i,irab + ilo - 1)))
              lrab = int(log10(rab + sfmin)/basl + one,KIND=ilp)
              ir = int(lscale(i) + sign(half,lscale(i)),KIND=ilp)
              ir = min(max(ir,lsfmin),lsfmax,lsfmax - lrab)
              lscale(i) = sclfac**ir
              icab = la_iqamax(ihi,a(1,i),1)
              cab = abs(a(icab,i))
              icab = la_iqamax(ihi,b(1,i),1)
              cab = max(cab,abs(b(icab,i)))
              lcab = int(log10(cab + sfmin)/basl + one,KIND=ilp)
              jc = int(rscale(i) + sign(half,rscale(i)),KIND=ilp)
              jc = min(max(jc,lsfmin),lsfmax,lsfmax - lcab)
              rscale(i) = sclfac**jc
           end do
           ! row scaling of matrices a and b
           do i = ilo,ihi
              call la_qscal(n - ilo + 1,lscale(i),a(i,ilo),lda)
              call la_qscal(n - ilo + 1,lscale(i),b(i,ilo),ldb)
           end do
           ! column scaling of matrices a and b
           do j = ilo,ihi
              call la_qscal(ihi,rscale(j),a(1,j),1)
              call la_qscal(ihi,rscale(j),b(1,j),1)
           end do
           return
     end subroutine la_qggbal

     !> DGGES: computes for a pair of N-by-N real nonsymmetric matrices (A,B),
     !> the generalized eigenvalues, the generalized real Schur form (S,T),
     !> optionally, the left and/or right matrices of Schur vectors (VSL and
     !> VSR). This gives the generalized Schur factorization
     !> (A,B) = ( (VSL)*S*(VSR)**T, (VSL)*T*(VSR)**T )
     !> Optionally, it also orders the eigenvalues so that a selected cluster
     !> of eigenvalues appears in the leading diagonal blocks of the upper
     !> quasi-triangular matrix S and the upper triangular matrix T.The
     !> leading columns of VSL and VSR then form an orthonormal basis for the
     !> corresponding left and right eigenspaces (deflating subspaces).
     !> (If only the generalized eigenvalues are needed, use the driver
     !> DGGEV instead, which is faster.)
     !> A generalized eigenvalue for a pair of matrices (A,B) is a scalar w
     !> or a ratio alpha/beta = w, such that  A - w*B is singular.  It is
     !> usually represented as the pair (alpha,beta), as there is a
     !> reasonable interpretation for beta=0 or both being zero.
     !> A pair of matrices (S,T) is in generalized real Schur form if T is
     !> upper triangular with non-negative diagonal and S is block upper
     !> triangular with 1-by-1 and 2-by-2 blocks.  1-by-1 blocks correspond
     !> to real generalized eigenvalues, while 2-by-2 blocks of S will be
     !> "standardized" by making the corresponding elements of T have the
     !> form:
     !> [  a  0  ]
     !> [  0  b  ]
     !> and the pair of corresponding 2-by-2 blocks in S and T will have a
     !> complex conjugate pair of generalized eigenvalues.

     subroutine la_qgges(jobvsl,jobvsr,sort,selctg,n,a,lda,b,ldb,sdim,alphar, &
               alphai,beta,vsl,ldvsl,vsr,ldvsr,work,lwork,bwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobvsl,jobvsr,sort
           integer(ilp),intent(out) :: info,sdim
           integer(ilp),intent(in) :: lda,ldb,ldvsl,ldvsr,lwork,n
           ! Array Arguments
           logical(lk),intent(out) :: bwork(*)
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: alphai(*),alphar(*),beta(*),vsl(ldvsl,*),vsr(ldvsr,*), &
                     work(*)
           ! Function Arguments
           procedure(la_selctg_q) :: selctg
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: cursl,ilascl,ilbscl,ilvsl,ilvsr,lastsl,lquery,lst2sl, &
                     wantst
           integer(ilp) :: i,icols,ierr,ihi,ijobvl,ijobvr,ileft,ilo,ip,iright,irows, &
                     itau,iwrk,maxwrk,minwrk
           real(qp) :: anrm,anrmto,bignum,bnrm,bnrmto,eps,pvsl,pvsr,safmax,safmin, &
                     smlnum
           ! Local Arrays
           integer(ilp) :: idum(1)
           real(qp) :: dif(2)
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Executable Statements
           ! decode the input arguments
           if (la_lsame(jobvsl,'N')) then
              ijobvl = 1
              ilvsl = .false.
           else if (la_lsame(jobvsl,'V')) then
              ijobvl = 2
              ilvsl = .true.
           else
              ijobvl = -1
              ilvsl = .false.
           end if
           if (la_lsame(jobvsr,'N')) then
              ijobvr = 1
              ilvsr = .false.
           else if (la_lsame(jobvsr,'V')) then
              ijobvr = 2
              ilvsr = .true.
           else
              ijobvr = -1
              ilvsr = .false.
           end if
           wantst = la_lsame(sort,'S')
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           if (ijobvl <= 0) then
              info = -1
           else if (ijobvr <= 0) then
              info = -2
           else if ((.not. wantst) .and. (.not. la_lsame(sort,'N'))) then
              info = -3
           else if (n < 0) then
              info = -5
           else if (lda < max(1,n)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -9
           else if (ldvsl < 1 .or. (ilvsl .and. ldvsl < n)) then
              info = -15
           else if (ldvsr < 1 .or. (ilvsr .and. ldvsr < n)) then
              info = -17
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv.)
           if (info == 0) then
              if (n > 0) then
                 minwrk = max(8*n,6*n + 16)
                 maxwrk = minwrk - n + n*la_ilaenv(1,'DGEQRF',' ',n,1,n,0)
                 maxwrk = max(maxwrk,minwrk - n + n*la_ilaenv(1,'DORMQR',' ',n,1,n,-1 &
                           ))
                 if (ilvsl) then
                    maxwrk = max(maxwrk,minwrk - n + n*la_ilaenv(1,'DORGQR',' ',n,1,n, &
                              -1))
                 end if
              else
                 minwrk = 1
                 maxwrk = 1
              end if
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) info = -19
           end if
           if (info /= 0) then
              call la_xerbla('DGGES ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) then
              sdim = 0
              return
           end if
           ! get machine constants
           eps = la_qlamch('P')
           safmin = la_qlamch('S')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           smlnum = sqrt(safmin)/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',n,n,a,lda,work)
           ilascl = .false.
           if (anrm > zero .and. anrm < smlnum) then
              anrmto = smlnum
              ilascl = .true.
           else if (anrm > bignum) then
              anrmto = bignum
              ilascl = .true.
           end if
           if (ilascl) call la_qlascl('G',0,0,anrm,anrmto,n,n,a,lda,ierr)
           ! scale b if max element outside range [smlnum,bignum]
           bnrm = la_qlange('M',n,n,b,ldb,work)
           ilbscl = .false.
           if (bnrm > zero .and. bnrm < smlnum) then
              bnrmto = smlnum
              ilbscl = .true.
           else if (bnrm > bignum) then
              bnrmto = bignum
              ilbscl = .true.
           end if
           if (ilbscl) call la_qlascl('G',0,0,bnrm,bnrmto,n,n,b,ldb,ierr)
           ! permute the matrix to make it more nearly triangular
           ! (workspace: need 6*n + 2*n space for storing balancing factors)
           ileft = 1
           iright = n + 1
           iwrk = iright + n
           call la_qggbal('P',n,a,lda,b,ldb,ilo,ihi,work(ileft),work(iright), &
                     work(iwrk),ierr)
           ! reduce b to triangular form (qr decomposition of b)
           ! (workspace: need n, prefer n*nb)
           irows = ihi + 1 - ilo
           icols = n + 1 - ilo
           itau = iwrk
           iwrk = itau + irows
           call la_qgeqrf(irows,icols,b(ilo,ilo),ldb,work(itau),work(iwrk),lwork + &
                     1 - iwrk,ierr)
           ! apply the orthogonal transformation to matrix a
           ! (workspace: need n, prefer n*nb)
           call la_qormqr('L','T',irows,icols,irows,b(ilo,ilo),ldb,work(itau),a( &
                     ilo,ilo),lda,work(iwrk),lwork + 1 - iwrk,ierr)
           ! initialize vsl
           ! (workspace: need n, prefer n*nb)
           if (ilvsl) then
              call la_qlaset('FULL',n,n,zero,one,vsl,ldvsl)
              if (irows > 1) then
                 call la_qlacpy('L',irows - 1,irows - 1,b(ilo + 1,ilo),ldb,vsl(ilo + 1,ilo) &
                           ,ldvsl)
              end if
              call la_qorgqr(irows,irows,irows,vsl(ilo,ilo),ldvsl,work(itau),work( &
                        iwrk),lwork + 1 - iwrk,ierr)
           end if
           ! initialize vsr
           if (ilvsr) call la_qlaset('FULL',n,n,zero,one,vsr,ldvsr)
           ! reduce to generalized hessenberg form
           ! (workspace: none needed)
           call la_qgghrd(jobvsl,jobvsr,n,ilo,ihi,a,lda,b,ldb,vsl,ldvsl,vsr,ldvsr, &
                      ierr)
           ! perform qz algorithm, computing schur vectors if desired
           ! (workspace: need n)
           iwrk = itau
           call la_qhgeqz('S',jobvsl,jobvsr,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                     beta,vsl,ldvsl,vsr,ldvsr,work(iwrk),lwork + 1 - iwrk,ierr)
           if (ierr /= 0) then
              if (ierr > 0 .and. ierr <= n) then
                 info = ierr
              else if (ierr > n .and. ierr <= 2*n) then
                 info = ierr - n
              else
                 info = n + 1
              end if
              go to 50
           end if
           ! sort eigenvalues alpha/beta if desired
           ! (workspace: need 4*n+16 )
           sdim = 0
           if (wantst) then
              ! undo scaling on eigenvalues before selctging
              if (ilascl) then
                 call la_qlascl('G',0,0,anrmto,anrm,n,1,alphar,n,ierr)
                 call la_qlascl('G',0,0,anrmto,anrm,n,1,alphai,n,ierr)
              end if
              if (ilbscl) call la_qlascl('G',0,0,bnrmto,bnrm,n,1,beta,n,ierr)

              ! select eigenvalues
              do i = 1,n
                 bwork(i) = selctg(alphar(i),alphai(i),beta(i))
              end do
              call la_qtgsen(0,ilvsl,ilvsr,bwork,n,a,lda,b,ldb,alphar,alphai,beta, &
              vsl,ldvsl,vsr,ldvsr,sdim,pvsl,pvsr,dif,work(iwrk),lwork - iwrk + 1,idum,1, &
                        ierr)
              if (ierr == 1) info = n + 3
           end if
           ! apply back-permutation to vsl and vsr
           ! (workspace: none needed)
           if (ilvsl) call la_qggbak('P','L',n,ilo,ihi,work(ileft),work(iright),n, &
                     vsl,ldvsl,ierr)
           if (ilvsr) call la_qggbak('P','R',n,ilo,ihi,work(ileft),work(iright),n, &
                     vsr,ldvsr,ierr)
           ! check if unscaling would cause over/underflow, if so, rescale
           ! (alphar(i),alphai(i),beta(i)) so beta(i) is on the order of
           ! b(i,i) and alphar(i) and alphai(i) are on the order of a(i,i)
           if (ilascl) then
              do i = 1,n
                 if (alphai(i) /= zero) then
                    if ((alphar(i)/safmax) > (anrmto/anrm) .or. (safmin/alphar(i)) > ( &
                              anrm/anrmto)) then
                       work(1) = abs(a(i,i)/alphar(i))
                       beta(i) = beta(i)*work(1)
                       alphar(i) = alphar(i)*work(1)
                       alphai(i) = alphai(i)*work(1)
                    else if ((alphai(i)/safmax) > (anrmto/anrm) .or. (safmin/alphai(i) &
                               ) > (anrm/anrmto)) then
                       work(1) = abs(a(i,i + 1)/alphai(i))
                       beta(i) = beta(i)*work(1)
                       alphar(i) = alphar(i)*work(1)
                       alphai(i) = alphai(i)*work(1)
                    end if
                 end if
              end do
           end if
           if (ilbscl) then
              do i = 1,n
                 if (alphai(i) /= zero) then
                    if ((beta(i)/safmax) > (bnrmto/bnrm) .or. (safmin/beta(i)) > ( &
                              bnrm/bnrmto)) then
                       work(1) = abs(b(i,i)/beta(i))
                       beta(i) = beta(i)*work(1)
                       alphar(i) = alphar(i)*work(1)
                       alphai(i) = alphai(i)*work(1)
                    end if
                 end if
              end do
           end if
           ! undo scaling
           if (ilascl) then
              call la_qlascl('H',0,0,anrmto,anrm,n,n,a,lda,ierr)
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphar,n,ierr)
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphai,n,ierr)
           end if
           if (ilbscl) then
              call la_qlascl('U',0,0,bnrmto,bnrm,n,n,b,ldb,ierr)
              call la_qlascl('G',0,0,bnrmto,bnrm,n,1,beta,n,ierr)
           end if
           if (wantst) then
              ! check if reordering is correct
              lastsl = .true.
              lst2sl = .true.
              sdim = 0
              ip = 0
              do i = 1,n
                 cursl = selctg(alphar(i),alphai(i),beta(i))
                 if (alphai(i) == zero) then
                    if (cursl) sdim = sdim + 1
                    ip = 0
                    if (cursl .and. .not. lastsl) info = n + 2
                 else
                    if (ip == 1) then
                       ! last eigenvalue of conjugate pair
                       cursl = cursl .or. lastsl
                       lastsl = cursl
                       if (cursl) sdim = sdim + 2
                       ip = -1
                       if (cursl .and. .not. lst2sl) info = n + 2
                    else
                       ! first eigenvalue of conjugate pair
                       ip = 1
                    end if
                 end if
                 lst2sl = lastsl
                 lastsl = cursl
              end do
           end if
           50 continue
           work(1) = maxwrk
           return
     end subroutine la_qgges

     !> DGGES3: computes for a pair of N-by-N real nonsymmetric matrices (A,B),
     !> the generalized eigenvalues, the generalized real Schur form (S,T),
     !> optionally, the left and/or right matrices of Schur vectors (VSL and
     !> VSR). This gives the generalized Schur factorization
     !> (A,B) = ( (VSL)*S*(VSR)**T, (VSL)*T*(VSR)**T )
     !> Optionally, it also orders the eigenvalues so that a selected cluster
     !> of eigenvalues appears in the leading diagonal blocks of the upper
     !> quasi-triangular matrix S and the upper triangular matrix T.The
     !> leading columns of VSL and VSR then form an orthonormal basis for the
     !> corresponding left and right eigenspaces (deflating subspaces).
     !> (If only the generalized eigenvalues are needed, use the driver
     !> DGGEV instead, which is faster.)
     !> A generalized eigenvalue for a pair of matrices (A,B) is a scalar w
     !> or a ratio alpha/beta = w, such that  A - w*B is singular.  It is
     !> usually represented as the pair (alpha,beta), as there is a
     !> reasonable interpretation for beta=0 or both being zero.
     !> A pair of matrices (S,T) is in generalized real Schur form if T is
     !> upper triangular with non-negative diagonal and S is block upper
     !> triangular with 1-by-1 and 2-by-2 blocks.  1-by-1 blocks correspond
     !> to real generalized eigenvalues, while 2-by-2 blocks of S will be
     !> "standardized" by making the corresponding elements of T have the
     !> form:
     !> [  a  0  ]
     !> [  0  b  ]
     !> and the pair of corresponding 2-by-2 blocks in S and T will have a
     !> complex conjugate pair of generalized eigenvalues.

     subroutine la_qgges3(jobvsl,jobvsr,sort,selctg,n,a,lda,b,ldb,sdim,alphar, &
               alphai,beta,vsl,ldvsl,vsr,ldvsr,work,lwork,bwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobvsl,jobvsr,sort
           integer(ilp),intent(out) :: info,sdim
           integer(ilp),intent(in) :: lda,ldb,ldvsl,ldvsr,lwork,n
           ! Array Arguments
           logical(lk),intent(out) :: bwork(*)
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: alphai(*),alphar(*),beta(*),vsl(ldvsl,*),vsr(ldvsr,*), &
                     work(*)
           ! Function Arguments
           procedure(la_selctg_q) :: selctg
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: cursl,ilascl,ilbscl,ilvsl,ilvsr,lastsl,lquery,lst2sl, &
                     wantst
           integer(ilp) :: i,icols,ierr,ihi,ijobvl,ijobvr,ileft,ilo,ip,iright,irows, &
                     itau,iwrk,lwkopt
           real(qp) :: anrm,anrmto,bignum,bnrm,bnrmto,eps,pvsl,pvsr,safmax,safmin, &
                     smlnum
           ! Local Arrays
           integer(ilp) :: idum(1)
           real(qp) :: dif(2)
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Executable Statements
           ! decode the input arguments
           if (la_lsame(jobvsl,'N')) then
              ijobvl = 1
              ilvsl = .false.
           else if (la_lsame(jobvsl,'V')) then
              ijobvl = 2
              ilvsl = .true.
           else
              ijobvl = -1
              ilvsl = .false.
           end if
           if (la_lsame(jobvsr,'N')) then
              ijobvr = 1
              ilvsr = .false.
           else if (la_lsame(jobvsr,'V')) then
              ijobvr = 2
              ilvsr = .true.
           else
              ijobvr = -1
              ilvsr = .false.
           end if
           wantst = la_lsame(sort,'S')
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           if (ijobvl <= 0) then
              info = -1
           else if (ijobvr <= 0) then
              info = -2
           else if ((.not. wantst) .and. (.not. la_lsame(sort,'N'))) then
              info = -3
           else if (n < 0) then
              info = -5
           else if (lda < max(1,n)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -9
           else if (ldvsl < 1 .or. (ilvsl .and. ldvsl < n)) then
              info = -15
           else if (ldvsr < 1 .or. (ilvsr .and. ldvsr < n)) then
              info = -17
           else if (lwork < 6*n + 16 .and. .not. lquery) then
              info = -19
           end if
           ! compute workspace
           if (info == 0) then
              call la_qgeqrf(n,n,b,ldb,work,work,-1,ierr)
              lwkopt = max(6*n + 16,3*n + int(work(1),KIND=ilp))
              call la_qormqr('L','T',n,n,n,b,ldb,work,a,lda,work,-1,ierr)
              lwkopt = max(lwkopt,3*n + int(work(1),KIND=ilp))
              if (ilvsl) then
                 call la_qorgqr(n,n,n,vsl,ldvsl,work,work,-1,ierr)
                 lwkopt = max(lwkopt,3*n + int(work(1),KIND=ilp))
              end if
              call la_qgghd3(jobvsl,jobvsr,n,1,n,a,lda,b,ldb,vsl,ldvsl,vsr,ldvsr, &
                        work,-1,ierr)
              lwkopt = max(lwkopt,3*n + int(work(1),KIND=ilp))
              call la_qlaqz0('S',jobvsl,jobvsr,n,1,n,a,lda,b,ldb,alphar,alphai, &
                        beta,vsl,ldvsl,vsr,ldvsr,work,-1,0,ierr)
              lwkopt = max(lwkopt,2*n + int(work(1),KIND=ilp))
              if (wantst) then
                 call la_qtgsen(0,ilvsl,ilvsr,bwork,n,a,lda,b,ldb,alphar,alphai, &
                 beta,vsl,ldvsl,vsr,ldvsr,sdim,pvsl,pvsr,dif,work,-1,idum,1,ierr)

                 lwkopt = max(lwkopt,2*n + int(work(1),KIND=ilp))
              end if
              work(1) = lwkopt
           end if
           if (info /= 0) then
              call la_xerbla('DGGES3 ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) then
              sdim = 0
              return
           end if
           ! get machine constants
           eps = la_qlamch('P')
           safmin = la_qlamch('S')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           smlnum = sqrt(safmin)/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',n,n,a,lda,work)
           ilascl = .false.
           if (anrm > zero .and. anrm < smlnum) then
              anrmto = smlnum
              ilascl = .true.
           else if (anrm > bignum) then
              anrmto = bignum
              ilascl = .true.
           end if
           if (ilascl) call la_qlascl('G',0,0,anrm,anrmto,n,n,a,lda,ierr)
           ! scale b if max element outside range [smlnum,bignum]
           bnrm = la_qlange('M',n,n,b,ldb,work)
           ilbscl = .false.
           if (bnrm > zero .and. bnrm < smlnum) then
              bnrmto = smlnum
              ilbscl = .true.
           else if (bnrm > bignum) then
              bnrmto = bignum
              ilbscl = .true.
           end if
           if (ilbscl) call la_qlascl('G',0,0,bnrm,bnrmto,n,n,b,ldb,ierr)
           ! permute the matrix to make it more nearly triangular
           ileft = 1
           iright = n + 1
           iwrk = iright + n
           call la_qggbal('P',n,a,lda,b,ldb,ilo,ihi,work(ileft),work(iright), &
                     work(iwrk),ierr)
           ! reduce b to triangular form (qr decomposition of b)
           irows = ihi + 1 - ilo
           icols = n + 1 - ilo
           itau = iwrk
           iwrk = itau + irows
           call la_qgeqrf(irows,icols,b(ilo,ilo),ldb,work(itau),work(iwrk),lwork + &
                     1 - iwrk,ierr)
           ! apply the orthogonal transformation to matrix a
           call la_qormqr('L','T',irows,icols,irows,b(ilo,ilo),ldb,work(itau),a( &
                     ilo,ilo),lda,work(iwrk),lwork + 1 - iwrk,ierr)
           ! initialize vsl
           if (ilvsl) then
              call la_qlaset('FULL',n,n,zero,one,vsl,ldvsl)
              if (irows > 1) then
                 call la_qlacpy('L',irows - 1,irows - 1,b(ilo + 1,ilo),ldb,vsl(ilo + 1,ilo) &
                           ,ldvsl)
              end if
              call la_qorgqr(irows,irows,irows,vsl(ilo,ilo),ldvsl,work(itau),work( &
                        iwrk),lwork + 1 - iwrk,ierr)
           end if
           ! initialize vsr
           if (ilvsr) call la_qlaset('FULL',n,n,zero,one,vsr,ldvsr)
           ! reduce to generalized hessenberg form
           call la_qgghd3(jobvsl,jobvsr,n,ilo,ihi,a,lda,b,ldb,vsl,ldvsl,vsr,ldvsr, &
                      work(iwrk),lwork + 1 - iwrk,ierr)
           ! perform qz algorithm, computing schur vectors if desired
           iwrk = itau
           call la_qlaqz0('S',jobvsl,jobvsr,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                     beta,vsl,ldvsl,vsr,ldvsr,work(iwrk),lwork + 1 - iwrk,0,ierr)
           if (ierr /= 0) then
              if (ierr > 0 .and. ierr <= n) then
                 info = ierr
              else if (ierr > n .and. ierr <= 2*n) then
                 info = ierr - n
              else
                 info = n + 1
              end if
              go to 50
           end if
           ! sort eigenvalues alpha/beta if desired
           sdim = 0
           if (wantst) then
              ! undo scaling on eigenvalues before selctging
              if (ilascl) then
                 call la_qlascl('G',0,0,anrmto,anrm,n,1,alphar,n,ierr)
                 call la_qlascl('G',0,0,anrmto,anrm,n,1,alphai,n,ierr)
              end if
              if (ilbscl) call la_qlascl('G',0,0,bnrmto,bnrm,n,1,beta,n,ierr)

              ! select eigenvalues
              do i = 1,n
                 bwork(i) = selctg(alphar(i),alphai(i),beta(i))
              end do
              call la_qtgsen(0,ilvsl,ilvsr,bwork,n,a,lda,b,ldb,alphar,alphai,beta, &
              vsl,ldvsl,vsr,ldvsr,sdim,pvsl,pvsr,dif,work(iwrk),lwork - iwrk + 1,idum,1, &
                        ierr)
              if (ierr == 1) info = n + 3
           end if
           ! apply back-permutation to vsl and vsr
           if (ilvsl) call la_qggbak('P','L',n,ilo,ihi,work(ileft),work(iright),n, &
                     vsl,ldvsl,ierr)
           if (ilvsr) call la_qggbak('P','R',n,ilo,ihi,work(ileft),work(iright),n, &
                     vsr,ldvsr,ierr)
           ! check if unscaling would cause over/underflow, if so, rescale
           ! (alphar(i),alphai(i),beta(i)) so beta(i) is on the order of
           ! b(i,i) and alphar(i) and alphai(i) are on the order of a(i,i)
           if (ilascl) then
              do i = 1,n
                 if (alphai(i) /= zero) then
                    if ((alphar(i)/safmax) > (anrmto/anrm) .or. (safmin/alphar(i)) > ( &
                              anrm/anrmto)) then
                       work(1) = abs(a(i,i)/alphar(i))
                       beta(i) = beta(i)*work(1)
                       alphar(i) = alphar(i)*work(1)
                       alphai(i) = alphai(i)*work(1)
                    else if ((alphai(i)/safmax) > (anrmto/anrm) .or. (safmin/alphai(i) &
                               ) > (anrm/anrmto)) then
                       work(1) = abs(a(i,i + 1)/alphai(i))
                       beta(i) = beta(i)*work(1)
                       alphar(i) = alphar(i)*work(1)
                       alphai(i) = alphai(i)*work(1)
                    end if
                 end if
              end do
           end if
           if (ilbscl) then
              do i = 1,n
                 if (alphai(i) /= zero) then
                    if ((beta(i)/safmax) > (bnrmto/bnrm) .or. (safmin/beta(i)) > ( &
                              bnrm/bnrmto)) then
                       work(1) = abs(b(i,i)/beta(i))
                       beta(i) = beta(i)*work(1)
                       alphar(i) = alphar(i)*work(1)
                       alphai(i) = alphai(i)*work(1)
                    end if
                 end if
              end do
           end if
           ! undo scaling
           if (ilascl) then
              call la_qlascl('H',0,0,anrmto,anrm,n,n,a,lda,ierr)
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphar,n,ierr)
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphai,n,ierr)
           end if
           if (ilbscl) then
              call la_qlascl('U',0,0,bnrmto,bnrm,n,n,b,ldb,ierr)
              call la_qlascl('G',0,0,bnrmto,bnrm,n,1,beta,n,ierr)
           end if
           if (wantst) then
              ! check if reordering is correct
              lastsl = .true.
              lst2sl = .true.
              sdim = 0
              ip = 0
              do i = 1,n
                 cursl = selctg(alphar(i),alphai(i),beta(i))
                 if (alphai(i) == zero) then
                    if (cursl) sdim = sdim + 1
                    ip = 0
                    if (cursl .and. .not. lastsl) info = n + 2
                 else
                    if (ip == 1) then
                       ! last eigenvalue of conjugate pair
                       cursl = cursl .or. lastsl
                       lastsl = cursl
                       if (cursl) sdim = sdim + 2
                       ip = -1
                       if (cursl .and. .not. lst2sl) info = n + 2
                    else
                       ! first eigenvalue of conjugate pair
                       ip = 1
                    end if
                 end if
                 lst2sl = lastsl
                 lastsl = cursl
              end do
           end if
           50 continue
           work(1) = lwkopt
           return
     end subroutine la_qgges3

     !> DGGESX: computes for a pair of N-by-N real nonsymmetric matrices
     !> (A,B), the generalized eigenvalues, the real Schur form (S,T), and,
     !> optionally, the left and/or right matrices of Schur vectors (VSL and
     !> VSR).  This gives the generalized Schur factorization
     !> (A,B) = ( (VSL) S (VSR)**T, (VSL) T (VSR)**T )
     !> Optionally, it also orders the eigenvalues so that a selected cluster
     !> of eigenvalues appears in the leading diagonal blocks of the upper
     !> quasi-triangular matrix S and the upper triangular matrix T; computes
     !> a reciprocal condition number for the average of the selected
     !> eigenvalues (RCONDE); and computes a reciprocal condition number for
     !> the right and left deflating subspaces corresponding to the selected
     !> eigenvalues (RCONDV). The leading columns of VSL and VSR then form
     !> an orthonormal basis for the corresponding left and right eigenspaces
     !> (deflating subspaces).
     !> A generalized eigenvalue for a pair of matrices (A,B) is a scalar w
     !> or a ratio alpha/beta = w, such that  A - w*B is singular.  It is
     !> usually represented as the pair (alpha,beta), as there is a
     !> reasonable interpretation for beta=0 or for both being zero.
     !> A pair of matrices (S,T) is in generalized real Schur form if T is
     !> upper triangular with non-negative diagonal and S is block upper
     !> triangular with 1-by-1 and 2-by-2 blocks.  1-by-1 blocks correspond
     !> to real generalized eigenvalues, while 2-by-2 blocks of S will be
     !> "standardized" by making the corresponding elements of T have the
     !> form:
     !> [  a  0  ]
     !> [  0  b  ]
     !> and the pair of corresponding 2-by-2 blocks in S and T will have a
     !> complex conjugate pair of generalized eigenvalues.

     subroutine la_qggesx(jobvsl,jobvsr,sort,selctg,sense,n,a,lda,b,ldb,sdim, &
     alphar,alphai,beta,vsl,ldvsl,vsr,ldvsr,rconde,rcondv,work,lwork,iwork,liwork, &
               bwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobvsl,jobvsr,sense,sort
           integer(ilp),intent(out) :: info,sdim
           integer(ilp),intent(in) :: lda,ldb,ldvsl,ldvsr,liwork,lwork,n
           ! Array Arguments
           logical(lk),intent(out) :: bwork(*)
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: alphai(*),alphar(*),beta(*),rconde(2),rcondv(2),vsl( &
                     ldvsl,*),vsr(ldvsr,*),work(*)
           ! Function Arguments
           procedure(la_selctg_q) :: selctg
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: cursl,ilascl,ilbscl,ilvsl,ilvsr,lastsl,lquery,lst2sl,wantsb, &
                     wantse,wantsn,wantst,wantsv
           integer(ilp) :: i,icols,ierr,ihi,ijob,ijobvl,ijobvr,ileft,ilo,ip,iright, &
                     irows,itau,iwrk,liwmin,lwrk,maxwrk,minwrk
           real(qp) :: anrm,anrmto,bignum,bnrm,bnrmto,eps,pl,pr,safmax,safmin, &
                     smlnum
           ! Local Arrays
           real(qp) :: dif(2)
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Executable Statements
           ! decode the input arguments
           if (la_lsame(jobvsl,'N')) then
              ijobvl = 1
              ilvsl = .false.
           else if (la_lsame(jobvsl,'V')) then
              ijobvl = 2
              ilvsl = .true.
           else
              ijobvl = -1
              ilvsl = .false.
           end if
           if (la_lsame(jobvsr,'N')) then
              ijobvr = 1
              ilvsr = .false.
           else if (la_lsame(jobvsr,'V')) then
              ijobvr = 2
              ilvsr = .true.
           else
              ijobvr = -1
              ilvsr = .false.
           end if
           wantst = la_lsame(sort,'S')
           wantsn = la_lsame(sense,'N')
           wantse = la_lsame(sense,'E')
           wantsv = la_lsame(sense,'V')
           wantsb = la_lsame(sense,'B')
           lquery = (lwork == -1 .or. liwork == -1)
           if (wantsn) then
              ijob = 0
           else if (wantse) then
              ijob = 1
           else if (wantsv) then
              ijob = 2
           else if (wantsb) then
              ijob = 4
           end if
           ! test the input arguments
           info = 0
           if (ijobvl <= 0) then
              info = -1
           else if (ijobvr <= 0) then
              info = -2
           else if ((.not. wantst) .and. (.not. la_lsame(sort,'N'))) then
              info = -3
           else if (.not. (wantsn .or. wantse .or. wantsv .or. wantsb) .or. (.not. wantst .and. &
                     .not. wantsn)) then
              info = -5
           else if (n < 0) then
              info = -6
           else if (lda < max(1,n)) then
              info = -8
           else if (ldb < max(1,n)) then
              info = -10
           else if (ldvsl < 1 .or. (ilvsl .and. ldvsl < n)) then
              info = -16
           else if (ldvsr < 1 .or. (ilvsr .and. ldvsr < n)) then
              info = -18
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv.)
           if (info == 0) then
              if (n > 0) then
                 minwrk = max(8*n,6*n + 16)
                 maxwrk = minwrk - n + n*la_ilaenv(1,'DGEQRF',' ',n,1,n,0)
                 maxwrk = max(maxwrk,minwrk - n + n*la_ilaenv(1,'DORMQR',' ',n,1,n,-1 &
                           ))
                 if (ilvsl) then
                    maxwrk = max(maxwrk,minwrk - n + n*la_ilaenv(1,'DORGQR',' ',n,1,n, &
                              -1))
                 end if
                 lwrk = maxwrk
                 if (ijob >= 1) lwrk = max(lwrk,n*n/2)
              else
                 minwrk = 1
                 maxwrk = 1
                 lwrk = 1
              end if
              work(1) = lwrk
              if (wantsn .or. n == 0) then
                 liwmin = 1
              else
                 liwmin = n + 6
              end if
              iwork(1) = liwmin
              if (lwork < minwrk .and. .not. lquery) then
                 info = -22
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -24
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DGGESX',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) then
              sdim = 0
              return
           end if
           ! get machine constants
           eps = la_qlamch('P')
           safmin = la_qlamch('S')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           smlnum = sqrt(safmin)/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',n,n,a,lda,work)
           ilascl = .false.
           if (anrm > zero .and. anrm < smlnum) then
              anrmto = smlnum
              ilascl = .true.
           else if (anrm > bignum) then
              anrmto = bignum
              ilascl = .true.
           end if
           if (ilascl) call la_qlascl('G',0,0,anrm,anrmto,n,n,a,lda,ierr)
           ! scale b if max element outside range [smlnum,bignum]
           bnrm = la_qlange('M',n,n,b,ldb,work)
           ilbscl = .false.
           if (bnrm > zero .and. bnrm < smlnum) then
              bnrmto = smlnum
              ilbscl = .true.
           else if (bnrm > bignum) then
              bnrmto = bignum
              ilbscl = .true.
           end if
           if (ilbscl) call la_qlascl('G',0,0,bnrm,bnrmto,n,n,b,ldb,ierr)
           ! permute the matrix to make it more nearly triangular
           ! (workspace: need 6*n + 2*n for permutation parameters)
           ileft = 1
           iright = n + 1
           iwrk = iright + n
           call la_qggbal('P',n,a,lda,b,ldb,ilo,ihi,work(ileft),work(iright), &
                     work(iwrk),ierr)
           ! reduce b to triangular form (qr decomposition of b)
           ! (workspace: need n, prefer n*nb)
           irows = ihi + 1 - ilo
           icols = n + 1 - ilo
           itau = iwrk
           iwrk = itau + irows
           call la_qgeqrf(irows,icols,b(ilo,ilo),ldb,work(itau),work(iwrk),lwork + &
                     1 - iwrk,ierr)
           ! apply the orthogonal transformation to matrix a
           ! (workspace: need n, prefer n*nb)
           call la_qormqr('L','T',irows,icols,irows,b(ilo,ilo),ldb,work(itau),a( &
                     ilo,ilo),lda,work(iwrk),lwork + 1 - iwrk,ierr)
           ! initialize vsl
           ! (workspace: need n, prefer n*nb)
           if (ilvsl) then
              call la_qlaset('FULL',n,n,zero,one,vsl,ldvsl)
              if (irows > 1) then
                 call la_qlacpy('L',irows - 1,irows - 1,b(ilo + 1,ilo),ldb,vsl(ilo + 1,ilo) &
                           ,ldvsl)
              end if
              call la_qorgqr(irows,irows,irows,vsl(ilo,ilo),ldvsl,work(itau),work( &
                        iwrk),lwork + 1 - iwrk,ierr)
           end if
           ! initialize vsr
           if (ilvsr) call la_qlaset('FULL',n,n,zero,one,vsr,ldvsr)
           ! reduce to generalized hessenberg form
           ! (workspace: none needed)
           call la_qgghrd(jobvsl,jobvsr,n,ilo,ihi,a,lda,b,ldb,vsl,ldvsl,vsr,ldvsr, &
                      ierr)
           sdim = 0
           ! perform qz algorithm, computing schur vectors if desired
           ! (workspace: need n)
           iwrk = itau
           call la_qhgeqz('S',jobvsl,jobvsr,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                     beta,vsl,ldvsl,vsr,ldvsr,work(iwrk),lwork + 1 - iwrk,ierr)
           if (ierr /= 0) then
              if (ierr > 0 .and. ierr <= n) then
                 info = ierr
              else if (ierr > n .and. ierr <= 2*n) then
                 info = ierr - n
              else
                 info = n + 1
              end if
              go to 60
           end if
           ! sort eigenvalues alpha/beta and compute the reciprocal of
           ! condition number(s)
           ! (workspace: if ijob >= 1, need max( 8*(n+1), 2*sdim*(n-sdim) )
                       ! otherwise, need 8*(n+1) )
           if (wantst) then
              ! undo scaling on eigenvalues before selctging
              if (ilascl) then
                 call la_qlascl('G',0,0,anrmto,anrm,n,1,alphar,n,ierr)
                 call la_qlascl('G',0,0,anrmto,anrm,n,1,alphai,n,ierr)
              end if
              if (ilbscl) call la_qlascl('G',0,0,bnrmto,bnrm,n,1,beta,n,ierr)

              ! select eigenvalues
              do i = 1,n
                 bwork(i) = selctg(alphar(i),alphai(i),beta(i))
              end do
              ! reorder eigenvalues, transform generalized schur vectors, and
              ! compute reciprocal condition numbers
              call la_qtgsen(ijob,ilvsl,ilvsr,bwork,n,a,lda,b,ldb,alphar,alphai, &
              beta,vsl,ldvsl,vsr,ldvsr,sdim,pl,pr,dif,work(iwrk),lwork - iwrk + 1,iwork, &
                        liwork,ierr)
              if (ijob >= 1) maxwrk = max(maxwrk,2*sdim*(n - sdim))
              if (ierr == -22) then
                  ! not enough real workspace
                 info = -22
              else
                 if (ijob == 1 .or. ijob == 4) then
                    rconde(1) = pl
                    rconde(2) = pr
                 end if
                 if (ijob == 2 .or. ijob == 4) then
                    rcondv(1) = dif(1)
                    rcondv(2) = dif(2)
                 end if
                 if (ierr == 1) info = n + 3
              end if
           end if
           ! apply permutation to vsl and vsr
           ! (workspace: none needed)
           if (ilvsl) call la_qggbak('P','L',n,ilo,ihi,work(ileft),work(iright),n, &
                     vsl,ldvsl,ierr)
           if (ilvsr) call la_qggbak('P','R',n,ilo,ihi,work(ileft),work(iright),n, &
                     vsr,ldvsr,ierr)
           ! check if unscaling would cause over/underflow, if so, rescale
           ! (alphar(i),alphai(i),beta(i)) so beta(i) is on the order of
           ! b(i,i) and alphar(i) and alphai(i) are on the order of a(i,i)
           if (ilascl) then
              do i = 1,n
                 if (alphai(i) /= zero) then
                    if ((alphar(i)/safmax) > (anrmto/anrm) .or. (safmin/alphar(i)) > ( &
                              anrm/anrmto)) then
                       work(1) = abs(a(i,i)/alphar(i))
                       beta(i) = beta(i)*work(1)
                       alphar(i) = alphar(i)*work(1)
                       alphai(i) = alphai(i)*work(1)
                    else if ((alphai(i)/safmax) > (anrmto/anrm) .or. (safmin/alphai(i) &
                               ) > (anrm/anrmto)) then
                       work(1) = abs(a(i,i + 1)/alphai(i))
                       beta(i) = beta(i)*work(1)
                       alphar(i) = alphar(i)*work(1)
                       alphai(i) = alphai(i)*work(1)
                    end if
                 end if
              end do
           end if
           if (ilbscl) then
              do i = 1,n
                 if (alphai(i) /= zero) then
                    if ((beta(i)/safmax) > (bnrmto/bnrm) .or. (safmin/beta(i)) > ( &
                              bnrm/bnrmto)) then
                       work(1) = abs(b(i,i)/beta(i))
                       beta(i) = beta(i)*work(1)
                       alphar(i) = alphar(i)*work(1)
                       alphai(i) = alphai(i)*work(1)
                    end if
                 end if
              end do
           end if
           ! undo scaling
           if (ilascl) then
              call la_qlascl('H',0,0,anrmto,anrm,n,n,a,lda,ierr)
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphar,n,ierr)
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphai,n,ierr)
           end if
           if (ilbscl) then
              call la_qlascl('U',0,0,bnrmto,bnrm,n,n,b,ldb,ierr)
              call la_qlascl('G',0,0,bnrmto,bnrm,n,1,beta,n,ierr)
           end if
           if (wantst) then
              ! check if reordering is correct
              lastsl = .true.
              lst2sl = .true.
              sdim = 0
              ip = 0
              do i = 1,n
                 cursl = selctg(alphar(i),alphai(i),beta(i))
                 if (alphai(i) == zero) then
                    if (cursl) sdim = sdim + 1
                    ip = 0
                    if (cursl .and. .not. lastsl) info = n + 2
                 else
                    if (ip == 1) then
                       ! last eigenvalue of conjugate pair
                       cursl = cursl .or. lastsl
                       lastsl = cursl
                       if (cursl) sdim = sdim + 2
                       ip = -1
                       if (cursl .and. .not. lst2sl) info = n + 2
                    else
                       ! first eigenvalue of conjugate pair
                       ip = 1
                    end if
                 end if
                 lst2sl = lastsl
                 lastsl = cursl
              end do
           end if
           60 continue
           work(1) = maxwrk
           iwork(1) = liwmin
           return
     end subroutine la_qggesx

     !> DGGEV: computes for a pair of N-by-N real nonsymmetric matrices (A,B)
     !> the generalized eigenvalues, and optionally, the left and/or right
     !> generalized eigenvectors.
     !> A generalized eigenvalue for a pair of matrices (A,B) is a scalar
     !> lambda or a ratio alpha/beta = lambda, such that A - lambda*B is
     !> singular. It is usually represented as the pair (alpha,beta), as
     !> there is a reasonable interpretation for beta=0, and even for both
     !> being zero.
     !> The right eigenvector v(j) corresponding to the eigenvalue lambda(j)
     !> of (A,B) satisfies
     !> A * v(j) = lambda(j) * B * v(j).
     !> The left eigenvector u(j) corresponding to the eigenvalue lambda(j)
     !> of (A,B) satisfies
     !> u(j)**H * A  = lambda(j) * u(j)**H * B .
     !> where u(j)**H is the conjugate-transpose of u(j).

     subroutine la_qggev(jobvl,jobvr,n,a,lda,b,ldb,alphar,alphai,beta,vl,ldvl,vr, &
               ldvr,work,lwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobvl,jobvr
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,ldvl,ldvr,lwork,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: alphai(*),alphar(*),beta(*),vl(ldvl,*),vr(ldvr,*),work(*)

        ! =====================================================================

           ! Local Scalars
           logical(lk) :: ilascl,ilbscl,ilv,ilvl,ilvr,lquery
           character :: chtemp
           integer(ilp) :: icols,ierr,ihi,ijobvl,ijobvr,ileft,ilo,in,iright,irows,itau, &
                     iwrk,jc,jr,maxwrk,minwrk
           real(qp) :: anrm,anrmto,bignum,bnrm,bnrmto,eps,smlnum,temp
           ! Local Arrays
           logical(lk) :: ldumma(1)
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Executable Statements
           ! decode the input arguments
           if (la_lsame(jobvl,'N')) then
              ijobvl = 1
              ilvl = .false.
           else if (la_lsame(jobvl,'V')) then
              ijobvl = 2
              ilvl = .true.
           else
              ijobvl = -1
              ilvl = .false.
           end if
           if (la_lsame(jobvr,'N')) then
              ijobvr = 1
              ilvr = .false.
           else if (la_lsame(jobvr,'V')) then
              ijobvr = 2
              ilvr = .true.
           else
              ijobvr = -1
              ilvr = .false.
           end if
           ilv = ilvl .or. ilvr
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           if (ijobvl <= 0) then
              info = -1
           else if (ijobvr <= 0) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -7
           else if (ldvl < 1 .or. (ilvl .and. ldvl < n)) then
              info = -12
           else if (ldvr < 1 .or. (ilvr .and. ldvr < n)) then
              info = -14
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv. the workspace is
             ! computed assuming ilo = 1 and ihi = n, the worst case.)
           if (info == 0) then
              minwrk = max(1,8*n)
              maxwrk = max(1,n*(7 + la_ilaenv(1,'DGEQRF',' ',n,1,n,0)))
              maxwrk = max(maxwrk,n*(7 + la_ilaenv(1,'DORMQR',' ',n,1,n,0)))

              if (ilvl) then
                 maxwrk = max(maxwrk,n*(7 + la_ilaenv(1,'DORGQR',' ',n,1,n,-1)))

              end if
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) info = -16
           end if
           if (info /= 0) then
              call la_xerbla('DGGEV ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           smlnum = sqrt(smlnum)/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',n,n,a,lda,work)
           ilascl = .false.
           if (anrm > zero .and. anrm < smlnum) then
              anrmto = smlnum
              ilascl = .true.
           else if (anrm > bignum) then
              anrmto = bignum
              ilascl = .true.
           end if
           if (ilascl) call la_qlascl('G',0,0,anrm,anrmto,n,n,a,lda,ierr)
           ! scale b if max element outside range [smlnum,bignum]
           bnrm = la_qlange('M',n,n,b,ldb,work)
           ilbscl = .false.
           if (bnrm > zero .and. bnrm < smlnum) then
              bnrmto = smlnum
              ilbscl = .true.
           else if (bnrm > bignum) then
              bnrmto = bignum
              ilbscl = .true.
           end if
           if (ilbscl) call la_qlascl('G',0,0,bnrm,bnrmto,n,n,b,ldb,ierr)
           ! permute the matrices a, b to isolate eigenvalues if possible
           ! (workspace: need 6*n)
           ileft = 1
           iright = n + 1
           iwrk = iright + n
           call la_qggbal('P',n,a,lda,b,ldb,ilo,ihi,work(ileft),work(iright), &
                     work(iwrk),ierr)
           ! reduce b to triangular form (qr decomposition of b)
           ! (workspace: need n, prefer n*nb)
           irows = ihi + 1 - ilo
           if (ilv) then
              icols = n + 1 - ilo
           else
              icols = irows
           end if
           itau = iwrk
           iwrk = itau + irows
           call la_qgeqrf(irows,icols,b(ilo,ilo),ldb,work(itau),work(iwrk),lwork + &
                     1 - iwrk,ierr)
           ! apply the orthogonal transformation to matrix a
           ! (workspace: need n, prefer n*nb)
           call la_qormqr('L','T',irows,icols,irows,b(ilo,ilo),ldb,work(itau),a( &
                     ilo,ilo),lda,work(iwrk),lwork + 1 - iwrk,ierr)
           ! initialize vl
           ! (workspace: need n, prefer n*nb)
           if (ilvl) then
              call la_qlaset('FULL',n,n,zero,one,vl,ldvl)
              if (irows > 1) then
                 call la_qlacpy('L',irows - 1,irows - 1,b(ilo + 1,ilo),ldb,vl(ilo + 1,ilo), &
                            ldvl)
              end if
              call la_qorgqr(irows,irows,irows,vl(ilo,ilo),ldvl,work(itau),work( &
                        iwrk),lwork + 1 - iwrk,ierr)
           end if
           ! initialize vr
           if (ilvr) call la_qlaset('FULL',n,n,zero,one,vr,ldvr)
           ! reduce to generalized hessenberg form
           ! (workspace: none needed)
           if (ilv) then
              ! eigenvectors requested -- work on whole matrix.
              call la_qgghrd(jobvl,jobvr,n,ilo,ihi,a,lda,b,ldb,vl,ldvl,vr,ldvr, &
                        ierr)
           else
              call la_qgghrd('N','N',irows,1,irows,a(ilo,ilo),lda,b(ilo,ilo), &
                        ldb,vl,ldvl,vr,ldvr,ierr)
           end if
           ! perform qz algorithm (compute eigenvalues, and optionally, the
           ! schur forms and schur vectors)
           ! (workspace: need n)
           iwrk = itau
           if (ilv) then
              chtemp = 'S'
           else
              chtemp = 'E'
           end if
           call la_qhgeqz(chtemp,jobvl,jobvr,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                     beta,vl,ldvl,vr,ldvr,work(iwrk),lwork + 1 - iwrk,ierr)
           if (ierr /= 0) then
              if (ierr > 0 .and. ierr <= n) then
                 info = ierr
              else if (ierr > n .and. ierr <= 2*n) then
                 info = ierr - n
              else
                 info = n + 1
              end if
              go to 110
           end if
           ! compute eigenvectors
           ! (workspace: need 6*n)
           if (ilv) then
              if (ilvl) then
                 if (ilvr) then
                    chtemp = 'B'
                 else
                    chtemp = 'L'
                 end if
              else
                 chtemp = 'R'
              end if
              call la_qtgevc(chtemp,'B',ldumma,n,a,lda,b,ldb,vl,ldvl,vr,ldvr,n, &
                        in,work(iwrk),ierr)
              if (ierr /= 0) then
                 info = n + 2
                 go to 110
              end if
              ! undo balancing on vl and vr and normalization
              ! (workspace: none needed)
              if (ilvl) then
                 call la_qggbak('P','L',n,ilo,ihi,work(ileft),work(iright),n,vl, &
                           ldvl,ierr)
                 loop_50: do jc = 1,n
                    if (alphai(jc) < zero) cycle loop_50
                    temp = zero
                    if (alphai(jc) == zero) then
                       do jr = 1,n
                          temp = max(temp,abs(vl(jr,jc)))
                       end do
                    else
                       do jr = 1,n
                          temp = max(temp,abs(vl(jr,jc)) + abs(vl(jr,jc + 1)))
                       end do
                    end if
                    if (temp < smlnum) cycle loop_50
                    temp = one/temp
                    if (alphai(jc) == zero) then
                       do jr = 1,n
                          vl(jr,jc) = vl(jr,jc)*temp
                       end do
                    else
                       do jr = 1,n
                          vl(jr,jc) = vl(jr,jc)*temp
                          vl(jr,jc + 1) = vl(jr,jc + 1)*temp
                       end do
                    end if
                 end do loop_50
              end if
              if (ilvr) then
                 call la_qggbak('P','R',n,ilo,ihi,work(ileft),work(iright),n,vr, &
                           ldvr,ierr)
                 loop_100: do jc = 1,n
                    if (alphai(jc) < zero) cycle loop_100
                    temp = zero
                    if (alphai(jc) == zero) then
                       do jr = 1,n
                          temp = max(temp,abs(vr(jr,jc)))
                       end do
                    else
                       do jr = 1,n
                          temp = max(temp,abs(vr(jr,jc)) + abs(vr(jr,jc + 1)))
                       end do
                    end if
                    if (temp < smlnum) cycle loop_100
                    temp = one/temp
                    if (alphai(jc) == zero) then
                       do jr = 1,n
                          vr(jr,jc) = vr(jr,jc)*temp
                       end do
                    else
                       do jr = 1,n
                          vr(jr,jc) = vr(jr,jc)*temp
                          vr(jr,jc + 1) = vr(jr,jc + 1)*temp
                       end do
                    end if
                 end do loop_100
              end if
              ! end of eigenvector calculation
           end if
           ! undo scaling if necessary
           110 continue
           if (ilascl) then
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphar,n,ierr)
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphai,n,ierr)
           end if
           if (ilbscl) then
              call la_qlascl('G',0,0,bnrmto,bnrm,n,1,beta,n,ierr)
           end if
           work(1) = maxwrk
           return
     end subroutine la_qggev

     !> DGGEV3: computes for a pair of N-by-N real nonsymmetric matrices (A,B)
     !> the generalized eigenvalues, and optionally, the left and/or right
     !> generalized eigenvectors.
     !> A generalized eigenvalue for a pair of matrices (A,B) is a scalar
     !> lambda or a ratio alpha/beta = lambda, such that A - lambda*B is
     !> singular. It is usually represented as the pair (alpha,beta), as
     !> there is a reasonable interpretation for beta=0, and even for both
     !> being zero.
     !> The right eigenvector v(j) corresponding to the eigenvalue lambda(j)
     !> of (A,B) satisfies
     !> A * v(j) = lambda(j) * B * v(j).
     !> The left eigenvector u(j) corresponding to the eigenvalue lambda(j)
     !> of (A,B) satisfies
     !> u(j)**H * A  = lambda(j) * u(j)**H * B .
     !> where u(j)**H is the conjugate-transpose of u(j).

     subroutine la_qggev3(jobvl,jobvr,n,a,lda,b,ldb,alphar,alphai,beta,vl,ldvl,vr, &
                ldvr,work,lwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobvl,jobvr
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,ldvl,ldvr,lwork,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: alphai(*),alphar(*),beta(*),vl(ldvl,*),vr(ldvr,*),work(*)

        ! =====================================================================

           ! Local Scalars
           logical(lk) :: ilascl,ilbscl,ilv,ilvl,ilvr,lquery
           character :: chtemp
           integer(ilp) :: icols,ierr,ihi,ijobvl,ijobvr,ileft,ilo,in,iright,irows,itau, &
                     iwrk,jc,jr,lwkopt
           real(qp) :: anrm,anrmto,bignum,bnrm,bnrmto,eps,smlnum,temp
           ! Local Arrays
           logical(lk) :: ldumma(1)
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Executable Statements
           ! decode the input arguments
           if (la_lsame(jobvl,'N')) then
              ijobvl = 1
              ilvl = .false.
           else if (la_lsame(jobvl,'V')) then
              ijobvl = 2
              ilvl = .true.
           else
              ijobvl = -1
              ilvl = .false.
           end if
           if (la_lsame(jobvr,'N')) then
              ijobvr = 1
              ilvr = .false.
           else if (la_lsame(jobvr,'V')) then
              ijobvr = 2
              ilvr = .true.
           else
              ijobvr = -1
              ilvr = .false.
           end if
           ilv = ilvl .or. ilvr
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           if (ijobvl <= 0) then
              info = -1
           else if (ijobvr <= 0) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -7
           else if (ldvl < 1 .or. (ilvl .and. ldvl < n)) then
              info = -12
           else if (ldvr < 1 .or. (ilvr .and. ldvr < n)) then
              info = -14
           else if (lwork < max(1,8*n) .and. .not. lquery) then
              info = -16
           end if
           ! compute workspace
           if (info == 0) then
              call la_qgeqrf(n,n,b,ldb,work,work,-1,ierr)
              lwkopt = max(1,8*n,3*n + int(work(1),KIND=ilp))
              call la_qormqr('L','T',n,n,n,b,ldb,work,a,lda,work,-1,ierr)
              lwkopt = max(lwkopt,3*n + int(work(1),KIND=ilp))
              if (ilvl) then
                 call la_qorgqr(n,n,n,vl,ldvl,work,work,-1,ierr)
                 lwkopt = max(lwkopt,3*n + int(work(1),KIND=ilp))
              end if
              if (ilv) then
                 call la_qgghd3(jobvl,jobvr,n,1,n,a,lda,b,ldb,vl,ldvl,vr,ldvr, &
                           work,-1,ierr)
                 lwkopt = max(lwkopt,3*n + int(work(1),KIND=ilp))
                 call la_qlaqz0('S',jobvl,jobvr,n,1,n,a,lda,b,ldb,alphar,alphai, &
                           beta,vl,ldvl,vr,ldvr,work,-1,0,ierr)
                 lwkopt = max(lwkopt,2*n + int(work(1),KIND=ilp))
              else
                 call la_qgghd3('N','N',n,1,n,a,lda,b,ldb,vl,ldvl,vr,ldvr,work,- &
                           1,ierr)
                 lwkopt = max(lwkopt,3*n + int(work(1),KIND=ilp))
                 call la_qlaqz0('E',jobvl,jobvr,n,1,n,a,lda,b,ldb,alphar,alphai, &
                           beta,vl,ldvl,vr,ldvr,work,-1,0,ierr)
                 lwkopt = max(lwkopt,2*n + int(work(1),KIND=ilp))
              end if
              work(1) = lwkopt
           end if
           if (info /= 0) then
              call la_xerbla('DGGEV3 ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           smlnum = sqrt(smlnum)/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',n,n,a,lda,work)
           ilascl = .false.
           if (anrm > zero .and. anrm < smlnum) then
              anrmto = smlnum
              ilascl = .true.
           else if (anrm > bignum) then
              anrmto = bignum
              ilascl = .true.
           end if
           if (ilascl) call la_qlascl('G',0,0,anrm,anrmto,n,n,a,lda,ierr)
           ! scale b if max element outside range [smlnum,bignum]
           bnrm = la_qlange('M',n,n,b,ldb,work)
           ilbscl = .false.
           if (bnrm > zero .and. bnrm < smlnum) then
              bnrmto = smlnum
              ilbscl = .true.
           else if (bnrm > bignum) then
              bnrmto = bignum
              ilbscl = .true.
           end if
           if (ilbscl) call la_qlascl('G',0,0,bnrm,bnrmto,n,n,b,ldb,ierr)
           ! permute the matrices a, b to isolate eigenvalues if possible
           ileft = 1
           iright = n + 1
           iwrk = iright + n
           call la_qggbal('P',n,a,lda,b,ldb,ilo,ihi,work(ileft),work(iright), &
                     work(iwrk),ierr)
           ! reduce b to triangular form (qr decomposition of b)
           irows = ihi + 1 - ilo
           if (ilv) then
              icols = n + 1 - ilo
           else
              icols = irows
           end if
           itau = iwrk
           iwrk = itau + irows
           call la_qgeqrf(irows,icols,b(ilo,ilo),ldb,work(itau),work(iwrk),lwork + &
                     1 - iwrk,ierr)
           ! apply the orthogonal transformation to matrix a
           call la_qormqr('L','T',irows,icols,irows,b(ilo,ilo),ldb,work(itau),a( &
                     ilo,ilo),lda,work(iwrk),lwork + 1 - iwrk,ierr)
           ! initialize vl
           if (ilvl) then
              call la_qlaset('FULL',n,n,zero,one,vl,ldvl)
              if (irows > 1) then
                 call la_qlacpy('L',irows - 1,irows - 1,b(ilo + 1,ilo),ldb,vl(ilo + 1,ilo), &
                            ldvl)
              end if
              call la_qorgqr(irows,irows,irows,vl(ilo,ilo),ldvl,work(itau),work( &
                        iwrk),lwork + 1 - iwrk,ierr)
           end if
           ! initialize vr
           if (ilvr) call la_qlaset('FULL',n,n,zero,one,vr,ldvr)
           ! reduce to generalized hessenberg form
           if (ilv) then
              ! eigenvectors requested -- work on whole matrix.
              call la_qgghd3(jobvl,jobvr,n,ilo,ihi,a,lda,b,ldb,vl,ldvl,vr,ldvr, &
                        work(iwrk),lwork + 1 - iwrk,ierr)
           else
              call la_qgghd3('N','N',irows,1,irows,a(ilo,ilo),lda,b(ilo,ilo), &
                        ldb,vl,ldvl,vr,ldvr,work(iwrk),lwork + 1 - iwrk,ierr)
           end if
           ! perform qz algorithm (compute eigenvalues, and optionally, the
           ! schur forms and schur vectors)
           iwrk = itau
           if (ilv) then
              chtemp = 'S'
           else
              chtemp = 'E'
           end if
           call la_qlaqz0(chtemp,jobvl,jobvr,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                     beta,vl,ldvl,vr,ldvr,work(iwrk),lwork + 1 - iwrk,0,ierr)
           if (ierr /= 0) then
              if (ierr > 0 .and. ierr <= n) then
                 info = ierr
              else if (ierr > n .and. ierr <= 2*n) then
                 info = ierr - n
              else
                 info = n + 1
              end if
              go to 110
           end if
           ! compute eigenvectors
           if (ilv) then
              if (ilvl) then
                 if (ilvr) then
                    chtemp = 'B'
                 else
                    chtemp = 'L'
                 end if
              else
                 chtemp = 'R'
              end if
              call la_qtgevc(chtemp,'B',ldumma,n,a,lda,b,ldb,vl,ldvl,vr,ldvr,n, &
                        in,work(iwrk),ierr)
              if (ierr /= 0) then
                 info = n + 2
                 go to 110
              end if
              ! undo balancing on vl and vr and normalization
              if (ilvl) then
                 call la_qggbak('P','L',n,ilo,ihi,work(ileft),work(iright),n,vl, &
                           ldvl,ierr)
                 loop_50: do jc = 1,n
                    if (alphai(jc) < zero) cycle loop_50
                    temp = zero
                    if (alphai(jc) == zero) then
                       do jr = 1,n
                          temp = max(temp,abs(vl(jr,jc)))
                       end do
                    else
                       do jr = 1,n
                          temp = max(temp,abs(vl(jr,jc)) + abs(vl(jr,jc + 1)))
                       end do
                    end if
                    if (temp < smlnum) cycle loop_50
                    temp = one/temp
                    if (alphai(jc) == zero) then
                       do jr = 1,n
                          vl(jr,jc) = vl(jr,jc)*temp
                       end do
                    else
                       do jr = 1,n
                          vl(jr,jc) = vl(jr,jc)*temp
                          vl(jr,jc + 1) = vl(jr,jc + 1)*temp
                       end do
                    end if
                 end do loop_50
              end if
              if (ilvr) then
                 call la_qggbak('P','R',n,ilo,ihi,work(ileft),work(iright),n,vr, &
                           ldvr,ierr)
                 loop_100: do jc = 1,n
                    if (alphai(jc) < zero) cycle loop_100
                    temp = zero
                    if (alphai(jc) == zero) then
                       do jr = 1,n
                          temp = max(temp,abs(vr(jr,jc)))
                       end do
                    else
                       do jr = 1,n
                          temp = max(temp,abs(vr(jr,jc)) + abs(vr(jr,jc + 1)))
                       end do
                    end if
                    if (temp < smlnum) cycle loop_100
                    temp = one/temp
                    if (alphai(jc) == zero) then
                       do jr = 1,n
                          vr(jr,jc) = vr(jr,jc)*temp
                       end do
                    else
                       do jr = 1,n
                          vr(jr,jc) = vr(jr,jc)*temp
                          vr(jr,jc + 1) = vr(jr,jc + 1)*temp
                       end do
                    end if
                 end do loop_100
              end if
              ! end of eigenvector calculation
           end if
           ! undo scaling if necessary
           110 continue
           if (ilascl) then
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphar,n,ierr)
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphai,n,ierr)
           end if
           if (ilbscl) then
              call la_qlascl('G',0,0,bnrmto,bnrm,n,1,beta,n,ierr)
           end if
           work(1) = lwkopt
           return
     end subroutine la_qggev3

     !> DGGEVX: computes for a pair of N-by-N real nonsymmetric matrices (A,B)
     !> the generalized eigenvalues, and optionally, the left and/or right
     !> generalized eigenvectors.
     !> Optionally also, it computes a balancing transformation to improve
     !> the conditioning of the eigenvalues and eigenvectors (ILO, IHI,
     !> LSCALE, RSCALE, ABNRM, and BBNRM), reciprocal condition numbers for
     !> the eigenvalues (RCONDE), and reciprocal condition numbers for the
     !> right eigenvectors (RCONDV).
     !> A generalized eigenvalue for a pair of matrices (A,B) is a scalar
     !> lambda or a ratio alpha/beta = lambda, such that A - lambda*B is
     !> singular. It is usually represented as the pair (alpha,beta), as
     !> there is a reasonable interpretation for beta=0, and even for both
     !> being zero.
     !> The right eigenvector v(j) corresponding to the eigenvalue lambda(j)
     !> of (A,B) satisfies
     !> A * v(j) = lambda(j) * B * v(j) .
     !> The left eigenvector u(j) corresponding to the eigenvalue lambda(j)
     !> of (A,B) satisfies
     !> u(j)**H * A  = lambda(j) * u(j)**H * B.
     !> where u(j)**H is the conjugate-transpose of u(j).

     subroutine la_qggevx(balanc,jobvl,jobvr,sense,n,a,lda,b,ldb,alphar,alphai, &
     beta,vl,ldvl,vr,ldvr,ilo,ihi,lscale,rscale,abnrm,bbnrm,rconde,rcondv,work,lwork, &
               iwork,bwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: balanc,jobvl,jobvr,sense
           integer(ilp),intent(out) :: ihi,ilo,info
           integer(ilp),intent(in) :: lda,ldb,ldvl,ldvr,lwork,n
           real(qp),intent(out) :: abnrm,bbnrm
           ! Array Arguments
           logical(lk),intent(out) :: bwork(*)
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: alphai(*),alphar(*),beta(*),lscale(*),rconde(*),rcondv(*) &
                     ,rscale(*),vl(ldvl,*),vr(ldvr,*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: ilascl,ilbscl,ilv,ilvl,ilvr,lquery,noscl,pair,wantsb,wantse, &
                     wantsn,wantsv
           character :: chtemp
           integer(ilp) :: i,icols,ierr,ijobvl,ijobvr,in,irows,itau,iwrk,iwrk1,j,jc, &
                     jr,m,maxwrk,minwrk,mm
           real(qp) :: anrm,anrmto,bignum,bnrm,bnrmto,eps,smlnum,temp
           ! Local Arrays
           logical(lk) :: ldumma(1)
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Executable Statements
           ! decode the input arguments
           if (la_lsame(jobvl,'N')) then
              ijobvl = 1
              ilvl = .false.
           else if (la_lsame(jobvl,'V')) then
              ijobvl = 2
              ilvl = .true.
           else
              ijobvl = -1
              ilvl = .false.
           end if
           if (la_lsame(jobvr,'N')) then
              ijobvr = 1
              ilvr = .false.
           else if (la_lsame(jobvr,'V')) then
              ijobvr = 2
              ilvr = .true.
           else
              ijobvr = -1
              ilvr = .false.
           end if
           ilv = ilvl .or. ilvr
           noscl = la_lsame(balanc,'N') .or. la_lsame(balanc,'P')
           wantsn = la_lsame(sense,'N')
           wantse = la_lsame(sense,'E')
           wantsv = la_lsame(sense,'V')
           wantsb = la_lsame(sense,'B')
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           if (.not. (la_lsame(balanc,'N') .or. la_lsame(balanc,'S') .or. &
                     la_lsame(balanc,'P') .or. la_lsame(balanc,'B'))) then
              info = -1
           else if (ijobvl <= 0) then
              info = -2
           else if (ijobvr <= 0) then
              info = -3
           else if (.not. (wantsn .or. wantse .or. wantsb .or. wantsv)) then
              info = -4
           else if (n < 0) then
              info = -5
           else if (lda < max(1,n)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -9
           else if (ldvl < 1 .or. (ilvl .and. ldvl < n)) then
              info = -14
           else if (ldvr < 1 .or. (ilvr .and. ldvr < n)) then
              info = -16
           end if
           ! compute workspace
            ! (note: comments in the code beginning "workspace:" describe the
             ! minimal amount of workspace needed at that point in the code,
             ! as well as the preferred amount for good performance.
             ! nb refers to the optimal block size for the immediately
             ! following subroutine, as returned by la_ilaenv. the workspace is
             ! computed assuming ilo = 1 and ihi = n, the worst case.)
           if (info == 0) then
              if (n == 0) then
                 minwrk = 1
                 maxwrk = 1
              else
                 if (noscl .and. .not. ilv) then
                    minwrk = 2*n
                 else
                    minwrk = 6*n
                 end if
                 if (wantse .or. wantsb) then
                    minwrk = 10*n
                 end if
                 if (wantsv .or. wantsb) then
                    minwrk = max(minwrk,2*n*(n + 4) + 16)
                 end if
                 maxwrk = minwrk
                 maxwrk = max(maxwrk,n + n*la_ilaenv(1,'DGEQRF',' ',n,1,n,0))

                 maxwrk = max(maxwrk,n + n*la_ilaenv(1,'DORMQR',' ',n,1,n,0))

                 if (ilvl) then
                    maxwrk = max(maxwrk,n + n*la_ilaenv(1,'DORGQR',' ',n,1,n,0))

                 end if
              end if
              work(1) = maxwrk
              if (lwork < minwrk .and. .not. lquery) then
                 info = -26
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DGGEVX',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           smlnum = sqrt(smlnum)/eps
           bignum = one/smlnum
           ! scale a if max element outside range [smlnum,bignum]
           anrm = la_qlange('M',n,n,a,lda,work)
           ilascl = .false.
           if (anrm > zero .and. anrm < smlnum) then
              anrmto = smlnum
              ilascl = .true.
           else if (anrm > bignum) then
              anrmto = bignum
              ilascl = .true.
           end if
           if (ilascl) call la_qlascl('G',0,0,anrm,anrmto,n,n,a,lda,ierr)
           ! scale b if max element outside range [smlnum,bignum]
           bnrm = la_qlange('M',n,n,b,ldb,work)
           ilbscl = .false.
           if (bnrm > zero .and. bnrm < smlnum) then
              bnrmto = smlnum
              ilbscl = .true.
           else if (bnrm > bignum) then
              bnrmto = bignum
              ilbscl = .true.
           end if
           if (ilbscl) call la_qlascl('G',0,0,bnrm,bnrmto,n,n,b,ldb,ierr)
           ! permute and/or balance the matrix pair (a,b)
           ! (workspace: need 6*n if balanc = 's' or 'b', 1 otherwise)
           call la_qggbal(balanc,n,a,lda,b,ldb,ilo,ihi,lscale,rscale,work,ierr)

           ! compute abnrm and bbnrm
           abnrm = la_qlange('1',n,n,a,lda,work(1))
           if (ilascl) then
              work(1) = abnrm
              call la_qlascl('G',0,0,anrmto,anrm,1,1,work(1),1,ierr)
              abnrm = work(1)
           end if
           bbnrm = la_qlange('1',n,n,b,ldb,work(1))
           if (ilbscl) then
              work(1) = bbnrm
              call la_qlascl('G',0,0,bnrmto,bnrm,1,1,work(1),1,ierr)
              bbnrm = work(1)
           end if
           ! reduce b to triangular form (qr decomposition of b)
           ! (workspace: need n, prefer n*nb )
           irows = ihi + 1 - ilo
           if (ilv .or. .not. wantsn) then
              icols = n + 1 - ilo
           else
              icols = irows
           end if
           itau = 1
           iwrk = itau + irows
           call la_qgeqrf(irows,icols,b(ilo,ilo),ldb,work(itau),work(iwrk),lwork + &
                     1 - iwrk,ierr)
           ! apply the orthogonal transformation to a
           ! (workspace: need n, prefer n*nb)
           call la_qormqr('L','T',irows,icols,irows,b(ilo,ilo),ldb,work(itau),a( &
                     ilo,ilo),lda,work(iwrk),lwork + 1 - iwrk,ierr)
           ! initialize vl and/or vr
           ! (workspace: need n, prefer n*nb)
           if (ilvl) then
              call la_qlaset('FULL',n,n,zero,one,vl,ldvl)
              if (irows > 1) then
                 call la_qlacpy('L',irows - 1,irows - 1,b(ilo + 1,ilo),ldb,vl(ilo + 1,ilo), &
                            ldvl)
              end if
              call la_qorgqr(irows,irows,irows,vl(ilo,ilo),ldvl,work(itau),work( &
                        iwrk),lwork + 1 - iwrk,ierr)
           end if
           if (ilvr) call la_qlaset('FULL',n,n,zero,one,vr,ldvr)
           ! reduce to generalized hessenberg form
           ! (workspace: none needed)
           if (ilv .or. .not. wantsn) then
              ! eigenvectors requested -- work on whole matrix.
              call la_qgghrd(jobvl,jobvr,n,ilo,ihi,a,lda,b,ldb,vl,ldvl,vr,ldvr, &
                        ierr)
           else
              call la_qgghrd('N','N',irows,1,irows,a(ilo,ilo),lda,b(ilo,ilo), &
                        ldb,vl,ldvl,vr,ldvr,ierr)
           end if
           ! perform qz algorithm (compute eigenvalues, and optionally, the
           ! schur forms and schur vectors)
           ! (workspace: need n)
           if (ilv .or. .not. wantsn) then
              chtemp = 'S'
           else
              chtemp = 'E'
           end if
           call la_qhgeqz(chtemp,jobvl,jobvr,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                     beta,vl,ldvl,vr,ldvr,work,lwork,ierr)
           if (ierr /= 0) then
              if (ierr > 0 .and. ierr <= n) then
                 info = ierr
              else if (ierr > n .and. ierr <= 2*n) then
                 info = ierr - n
              else
                 info = n + 1
              end if
              go to 130
           end if
           ! compute eigenvectors and estimate condition numbers if desired
           ! (workspace: la_qtgevc: need 6*n
                       ! la_qtgsna: need 2*n*(n+2)+16 if sense = 'v' or 'b',
                               ! need n otherwise )
           if (ilv .or. .not. wantsn) then
              if (ilv) then
                 if (ilvl) then
                    if (ilvr) then
                       chtemp = 'B'
                    else
                       chtemp = 'L'
                    end if
                 else
                    chtemp = 'R'
                 end if
                 call la_qtgevc(chtemp,'B',ldumma,n,a,lda,b,ldb,vl,ldvl,vr,ldvr,n, &
                            in,work,ierr)
                 if (ierr /= 0) then
                    info = n + 2
                    go to 130
                 end if
              end if
              if (.not. wantsn) then
                 ! compute eigenvectors (la_qtgevc) and estimate condition
                 ! numbers (la_qtgsna). note that the definition of the condition
                 ! number is not invariant under transformation (u,v) to
                 ! (q*u, z*v), where (u,v) are eigenvectors of the generalized
                 ! schur form (s,t), q and z are orthogonal matrices. in order
                 ! to avoid using extra 2*n*n workspace, we have to recalculate
                 ! eigenvectors and estimate one condition numbers at a time.
                 pair = .false.
                 loop_20: do i = 1,n
                    if (pair) then
                       pair = .false.
                       cycle loop_20
                    end if
                    mm = 1
                    if (i < n) then
                       if (a(i + 1,i) /= zero) then
                          pair = .true.
                          mm = 2
                       end if
                    end if
                    do j = 1,n
                       bwork(j) = .false.
                    end do
                    if (mm == 1) then
                       bwork(i) = .true.
                    else if (mm == 2) then
                       bwork(i) = .true.
                       bwork(i + 1) = .true.
                    end if
                    iwrk = mm*n + 1
                    iwrk1 = iwrk + mm*n
                    ! compute a pair of left and right eigenvectors.
                    ! (compute workspace: need up to 4*n + 6*n)
                    if (wantse .or. wantsb) then
                       call la_qtgevc('B','S',bwork,n,a,lda,b,ldb,work(1),n,work( &
                                 iwrk),n,mm,m,work(iwrk1),ierr)
                       if (ierr /= 0) then
                          info = n + 2
                          go to 130
                       end if
                    end if
                    call la_qtgsna(sense,'S',bwork,n,a,lda,b,ldb,work(1),n,work( &
                    iwrk),n,rconde(i),rcondv(i),mm,m,work(iwrk1),lwork - iwrk1 + 1,iwork, &
                               ierr)
                 end do loop_20
              end if
           end if
           ! undo balancing on vl and vr and normalization
           ! (workspace: none needed)
           if (ilvl) then
              call la_qggbak(balanc,'L',n,ilo,ihi,lscale,rscale,n,vl,ldvl,ierr)

              loop_70: do jc = 1,n
                 if (alphai(jc) < zero) cycle loop_70
                 temp = zero
                 if (alphai(jc) == zero) then
                    do jr = 1,n
                       temp = max(temp,abs(vl(jr,jc)))
                    end do
                 else
                    do jr = 1,n
                       temp = max(temp,abs(vl(jr,jc)) + abs(vl(jr,jc + 1)))
                    end do
                 end if
                 if (temp < smlnum) cycle loop_70
                 temp = one/temp
                 if (alphai(jc) == zero) then
                    do jr = 1,n
                       vl(jr,jc) = vl(jr,jc)*temp
                    end do
                 else
                    do jr = 1,n
                       vl(jr,jc) = vl(jr,jc)*temp
                       vl(jr,jc + 1) = vl(jr,jc + 1)*temp
                    end do
                 end if
              end do loop_70
           end if
           if (ilvr) then
              call la_qggbak(balanc,'R',n,ilo,ihi,lscale,rscale,n,vr,ldvr,ierr)

              loop_120: do jc = 1,n
                 if (alphai(jc) < zero) cycle loop_120
                 temp = zero
                 if (alphai(jc) == zero) then
                    do jr = 1,n
                       temp = max(temp,abs(vr(jr,jc)))
                    end do
                 else
                    do jr = 1,n
                       temp = max(temp,abs(vr(jr,jc)) + abs(vr(jr,jc + 1)))
                    end do
                 end if
                 if (temp < smlnum) cycle loop_120
                 temp = one/temp
                 if (alphai(jc) == zero) then
                    do jr = 1,n
                       vr(jr,jc) = vr(jr,jc)*temp
                    end do
                 else
                    do jr = 1,n
                       vr(jr,jc) = vr(jr,jc)*temp
                       vr(jr,jc + 1) = vr(jr,jc + 1)*temp
                    end do
                 end if
              end do loop_120
           end if
           ! undo scaling if necessary
           130 continue
           if (ilascl) then
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphar,n,ierr)
              call la_qlascl('G',0,0,anrmto,anrm,n,1,alphai,n,ierr)
           end if
           if (ilbscl) then
              call la_qlascl('G',0,0,bnrmto,bnrm,n,1,beta,n,ierr)
           end if
           work(1) = maxwrk
           return
     end subroutine la_qggevx

     !> DGGHD3: reduces a pair of real matrices (A,B) to generalized upper
     !> Hessenberg form using orthogonal transformations, where A is a
     !> general matrix and B is upper triangular.  The form of the
     !> generalized eigenvalue problem is
     !> A*x = lambda*B*x,
     !> and B is typically made upper triangular by computing its QR
     !> factorization and moving the orthogonal matrix Q to the left side
     !> of the equation.
     !> This subroutine simultaneously reduces A to a Hessenberg matrix H:
     !> Q**T*A*Z = H
     !> and transforms B to another upper triangular matrix T:
     !> Q**T*B*Z = T
     !> in order to reduce the problem to its standard form
     !> H*y = lambda*T*y
     !> where y = Z**T*x.
     !> The orthogonal matrices Q and Z are determined as products of Givens
     !> rotations.  They may either be formed explicitly, or they may be
     !> postmultiplied into input matrices Q1 and Z1, so that
     !> Q1 * A * Z1**T = (Q1*Q) * H * (Z1*Z)**T
     !> Q1 * B * Z1**T = (Q1*Q) * T * (Z1*Z)**T
     !> If Q1 is the orthogonal matrix from the QR factorization of B in the
     !> original equation A*x = lambda*B*x, then DGGHD3 reduces the original
     !> problem to generalized Hessenberg form.
     !> This is a blocked variant of DGGHRD, using matrix-matrix
     !> multiplications for parts of the computation to enhance performance.

     pure subroutine la_qgghd3(compq,compz,n,ilo,ihi,a,lda,b,ldb,q,ldq,z,ldz, &
               work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: compq,compz
           integer(ilp),intent(in) :: ihi,ilo,lda,ldb,ldq,ldz,n,lwork
           integer(ilp),intent(out) :: info
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)
           real(qp),intent(out) :: work(*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: blk22,initq,initz,lquery,wantq,wantz
           character :: compq2,compz2
           integer(ilp) :: cola,i,ierr,j,j0,jcol,jj,jrow,k,kacc22,len,lwkopt,n2nb,nb, &
                      nblst,nbmin,nh,nnb,nx,ppw,ppwo,pw,top,topq
           real(qp) :: c,c1,c2,s,s1,s2,temp,temp1,temp2,temp3
           ! Intrinsic Functions
           intrinsic :: real,max
           ! Executable Statements
           ! decode and test the input parameters.
           info = 0
           nb = la_ilaenv(1,'DGGHD3',' ',n,ilo,ihi,-1)
           lwkopt = max(6*n*nb,1)
           work(1) = real(lwkopt,KIND=qp)
           initq = la_lsame(compq,'I')
           wantq = initq .or. la_lsame(compq,'V')
           initz = la_lsame(compz,'I')
           wantz = initz .or. la_lsame(compz,'V')
           lquery = (lwork == -1)
           if (.not. la_lsame(compq,'N') .and. .not. wantq) then
              info = -1
           else if (.not. la_lsame(compz,'N') .and. .not. wantz) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ilo < 1) then
              info = -4
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -5
           else if (lda < max(1,n)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -9
           else if ((wantq .and. ldq < n) .or. ldq < 1) then
              info = -11
           else if ((wantz .and. ldz < n) .or. ldz < 1) then
              info = -13
           else if (lwork < 1 .and. .not. lquery) then
              info = -15
           end if
           if (info /= 0) then
              call la_xerbla('DGGHD3',-info)
              return
           else if (lquery) then
              return
           end if
           ! initialize q and z if desired.
           if (initq) call la_qlaset('ALL',n,n,zero,one,q,ldq)
           if (initz) call la_qlaset('ALL',n,n,zero,one,z,ldz)
           ! zero out lower triangle of b.
           if (n > 1) call la_qlaset('LOWER',n - 1,n - 1,zero,zero,b(2,1),ldb)
           ! quick return if possible
           nh = ihi - ilo + 1
           if (nh <= 1) then
              work(1) = one
              return
           end if
           ! determine the blocksize.
           nbmin = la_ilaenv(2,'DGGHD3',' ',n,ilo,ihi,-1)
           if (nb > 1 .and. nb < nh) then
              ! determine when to use unblocked instead of blocked code.
              nx = max(nb,la_ilaenv(3,'DGGHD3',' ',n,ilo,ihi,-1))
              if (nx < nh) then
                 ! determine if workspace is large enough for blocked code.
                 if (lwork < lwkopt) then
                    ! not enough workspace to use optimal nb:  determine the
                    ! minimum value of nb, and reduce nb or force use of
                    ! unblocked code.
                    nbmin = max(2,la_ilaenv(2,'DGGHD3',' ',n,ilo,ihi,-1))
                    if (lwork >= 6*n*nbmin) then
                       nb = lwork/(6*n)
                    else
                       nb = 1
                    end if
                 end if
              end if
           end if
           if (nb < nbmin .or. nb >= nh) then
              ! use unblocked code below
              jcol = ilo
           else
              ! use blocked code
              kacc22 = la_ilaenv(16,'DGGHD3',' ',n,ilo,ihi,-1)
              blk22 = kacc22 == 2
              do jcol = ilo,ihi - 2,nb
                 nnb = min(nb,ihi - jcol - 1)
                 ! initialize small orthogonal factors that will hold the
                 ! accumulated givens rotations in workspace.
                 ! n2nb   denotes the number of 2*nnb-by-2*nnb factors
                 ! nblst  denotes the (possibly smaller) order of the last
                        ! factor.
                 n2nb = (ihi - jcol - 1)/nnb - 1
                 nblst = ihi - jcol - n2nb*nnb
                 call la_qlaset('ALL',nblst,nblst,zero,one,work,nblst)
                 pw = nblst*nblst + 1
                 do i = 1,n2nb
                    call la_qlaset('ALL',2*nnb,2*nnb,zero,one,work(pw),2*nnb)
                    pw = pw + 4*nnb*nnb
                 end do
                 ! reduce columns jcol:jcol+nnb-1 of a to hessenberg form.
                 do j = jcol,jcol + nnb - 1
                    ! reduce jth column of a. store cosines and sines in jth
                    ! column of a and b, respectively.
                    do i = ihi,j + 2,-1
                       temp = a(i - 1,j)
                       call la_qlartg(temp,a(i,j),c,s,a(i - 1,j))
                       a(i,j) = c
                       b(i,j) = s
                    end do
                    ! accumulate givens rotations into workspace array.
                    ppw = (nblst + 1)*(nblst - 2) - j + jcol + 1
                    len = 2 + j - jcol
                    jrow = j + n2nb*nnb + 2
                    do i = ihi,jrow,-1
                       c = a(i,j)
                       s = b(i,j)
                       do jj = ppw,ppw + len - 1
                          temp = work(jj + nblst)
                          work(jj + nblst) = c*temp - s*work(jj)
                          work(jj) = s*temp + c*work(jj)
                       end do
                       len = len + 1
                       ppw = ppw - nblst - 1
                    end do
                    ppwo = nblst*nblst + (nnb + j - jcol - 1)*2*nnb + nnb
                    j0 = jrow - nnb
                    do jrow = j0,j + 2,-nnb
                       ppw = ppwo
                       len = 2 + j - jcol
                       do i = jrow + nnb - 1,jrow,-1
                          c = a(i,j)
                          s = b(i,j)
                          do jj = ppw,ppw + len - 1
                             temp = work(jj + 2*nnb)
                             work(jj + 2*nnb) = c*temp - s*work(jj)
                             work(jj) = s*temp + c*work(jj)
                          end do
                          len = len + 1
                          ppw = ppw - 2*nnb - 1
                       end do
                       ppwo = ppwo + 4*nnb*nnb
                    end do
                    ! top denotes the number of top rows in a and b that will
                    ! not be updated during the next steps.
                    if (jcol <= 2) then
                       top = 0
                    else
                       top = jcol
                    end if
                    ! propagate transformations through b and replace stored
                    ! left sines/cosines by right sines/cosines.
                    do jj = n,j + 1,-1
                       ! update jjth column of b.
                       do i = min(jj + 1,ihi),j + 2,-1
                          c = a(i,j)
                          s = b(i,j)
                          temp = b(i,jj)
                          b(i,jj) = c*temp - s*b(i - 1,jj)
                          b(i - 1,jj) = s*temp + c*b(i - 1,jj)
                       end do
                       ! annihilate b( jj+1, jj ).
                       if (jj < ihi) then
                          temp = b(jj + 1,jj + 1)
                          call la_qlartg(temp,b(jj + 1,jj),c,s,b(jj + 1,jj + 1))
                          b(jj + 1,jj) = zero
                          call la_qrot(jj - top,b(top + 1,jj + 1),1,b(top + 1,jj),1,c,s)

                          a(jj + 1,j) = c
                          b(jj + 1,j) = -s
                       end if
                    end do
                    ! update a by transformations from right.
                    ! explicit loop unrolling provides better performance
                    ! compared to la_qlasr.
                     ! call la_qlasr( 'right', 'variable', 'backward', ihi-top,
           ! $                     ihi-j, a( j+2, j ), b( j+2, j ),
           ! $                     a( top+1, j+1 ), lda )
                    jj = mod(ihi - j - 1,3)
                    do i = ihi - j - 3,jj + 1,-3
                       c = a(j + 1 + i,j)
                       s = -b(j + 1 + i,j)
                       c1 = a(j + 2 + i,j)
                       s1 = -b(j + 2 + i,j)
                       c2 = a(j + 3 + i,j)
                       s2 = -b(j + 3 + i,j)
                       do k = top + 1,ihi
                          temp = a(k,j + i)
                          temp1 = a(k,j + i + 1)
                          temp2 = a(k,j + i + 2)
                          temp3 = a(k,j + i + 3)
                          a(k,j + i + 3) = c2*temp3 + s2*temp2
                          temp2 = -s2*temp3 + c2*temp2
                          a(k,j + i + 2) = c1*temp2 + s1*temp1
                          temp1 = -s1*temp2 + c1*temp1
                          a(k,j + i + 1) = c*temp1 + s*temp
                          a(k,j + i) = -s*temp1 + c*temp
                       end do
                    end do
                    if (jj > 0) then
                       do i = jj,1,-1
                          call la_qrot(ihi - top,a(top + 1,j + i + 1),1,a(top + 1,j + i),1,a( &
                                    j + 1 + i,j),-b(j + 1 + i,j))
                       end do
                    end if
                    ! update (j+1)th column of a by transformations from left.
                    if (j < jcol + nnb - 1) then
                       len = 1 + j - jcol
                       ! multiply with the trailing accumulated orthogonal
                       ! matrix, which takes the form
                              ! [  u11  u12  ]
                          ! u = [            ],
                              ! [  u21  u22  ]
                       ! where u21 is a len-by-len matrix and u12 is lower
                       ! triangular.
                       jrow = ihi - nblst + 1
                       call la_qgemv('TRANSPOSE',nblst,len,one,work,nblst,a(jrow,j + 1) &
                                 ,1,zero,work(pw),1)
                       ppw = pw + len
                       do i = jrow,jrow + nblst - len - 1
                          work(ppw) = a(i,j + 1)
                          ppw = ppw + 1
                       end do
                       call la_qtrmv('LOWER','TRANSPOSE','NON-UNIT',nblst - len,work( &
                                 len*nblst + 1),nblst,work(pw + len),1)
                       call la_qgemv('TRANSPOSE',len,nblst - len,one,work((len + 1)*nblst - &
                       len + 1),nblst,a(jrow + nblst - len,j + 1),1,one,work(pw + len),1)

                       ppw = pw
                       do i = jrow,jrow + nblst - 1
                          a(i,j + 1) = work(ppw)
                          ppw = ppw + 1
                       end do
                       ! multiply with the other accumulated orthogonal
                       ! matrices, which take the form
                              ! [  u11  u12   0  ]
                              ! [                ]
                          ! u = [  u21  u22   0  ],
                              ! [                ]
                              ! [   0    0    i  ]
                       ! where i denotes the (nnb-len)-by-(nnb-len) identity
                       ! matrix, u21 is a len-by-len upper triangular matrix
                       ! and u12 is an nnb-by-nnb lower triangular matrix.
                       ppwo = 1 + nblst*nblst
                       j0 = jrow - nnb
                       do jrow = j0,jcol + 1,-nnb
                          ppw = pw + len
                          do i = jrow,jrow + nnb - 1
                             work(ppw) = a(i,j + 1)
                             ppw = ppw + 1
                          end do
                          ppw = pw
                          do i = jrow + nnb,jrow + nnb + len - 1
                             work(ppw) = a(i,j + 1)
                             ppw = ppw + 1
                          end do
                          call la_qtrmv('UPPER','TRANSPOSE','NON-UNIT',len,work(ppwo + &
                                    nnb),2*nnb,work(pw),1)
                          call la_qtrmv('LOWER','TRANSPOSE','NON-UNIT',nnb,work(ppwo + &
                                    2*len*nnb),2*nnb,work(pw + len),1)
                          call la_qgemv('TRANSPOSE',nnb,len,one,work(ppwo),2*nnb,a( &
                                    jrow,j + 1),1,one,work(pw),1)
                          call la_qgemv('TRANSPOSE',len,nnb,one,work(ppwo + 2*len*nnb + &
                                    nnb),2*nnb,a(jrow + nnb,j + 1),1,one,work(pw + len),1)
                          ppw = pw
                          do i = jrow,jrow + len + nnb - 1
                             a(i,j + 1) = work(ppw)
                             ppw = ppw + 1
                          end do
                          ppwo = ppwo + 4*nnb*nnb
                       end do
                    end if
                 end do
                 ! apply accumulated orthogonal matrices to a.
                 cola = n - jcol - nnb + 1
                 j = ihi - nblst + 1
                 call la_qgemm('TRANSPOSE','NO TRANSPOSE',nblst,cola,nblst,one,work, &
                           nblst,a(j,jcol + nnb),lda,zero,work(pw),nblst)
                 call la_qlacpy('ALL',nblst,cola,work(pw),nblst,a(j,jcol + nnb),lda)

                 ppwo = nblst*nblst + 1
                 j0 = j - nnb
                 do j = j0,jcol + 1,-nnb
                    if (blk22) then
                       ! exploit the structure of
                              ! [  u11  u12  ]
                          ! u = [            ]
                              ! [  u21  u22  ],
                       ! where all blocks are nnb-by-nnb, u21 is upper
                       ! triangular and u12 is lower triangular.
                       call la_qorm22('LEFT','TRANSPOSE',2*nnb,cola,nnb,nnb,work(ppwo) &
                                 ,2*nnb,a(j,jcol + nnb),lda,work(pw),lwork - pw + 1,ierr)
                    else
                       ! ignore the structure of u.
                       call la_qgemm('TRANSPOSE','NO TRANSPOSE',2*nnb,cola,2*nnb,one, &
                                 work(ppwo),2*nnb,a(j,jcol + nnb),lda,zero,work(pw),2*nnb)
                       call la_qlacpy('ALL',2*nnb,cola,work(pw),2*nnb,a(j,jcol + nnb), &
                                  lda)
                    end if
                    ppwo = ppwo + 4*nnb*nnb
                 end do
                 ! apply accumulated orthogonal matrices to q.
                 if (wantq) then
                    j = ihi - nblst + 1
                    if (initq) then
                       topq = max(2,j - jcol + 1)
                       nh = ihi - topq + 1
                    else
                       topq = 1
                       nh = n
                    end if
                    call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',nh,nblst,nblst,one,q( &
                              topq,j),ldq,work,nblst,zero,work(pw),nh)
                    call la_qlacpy('ALL',nh,nblst,work(pw),nh,q(topq,j),ldq)

                    ppwo = nblst*nblst + 1
                    j0 = j - nnb
                    do j = j0,jcol + 1,-nnb
                       if (initq) then
                          topq = max(2,j - jcol + 1)
                          nh = ihi - topq + 1
                       end if
                       if (blk22) then
                          ! exploit the structure of u.
                          call la_qorm22('RIGHT','NO TRANSPOSE',nh,2*nnb,nnb,nnb,work( &
                                    ppwo),2*nnb,q(topq,j),ldq,work(pw),lwork - pw + 1,ierr)
                       else
                          ! ignore the structure of u.
                          call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',nh,2*nnb,2*nnb,one, &
                                     q(topq,j),ldq,work(ppwo),2*nnb,zero,work(pw),nh)
                          call la_qlacpy('ALL',nh,2*nnb,work(pw),nh,q(topq,j),ldq)

                       end if
                       ppwo = ppwo + 4*nnb*nnb
                    end do
                 end if
                 ! accumulate right givens rotations if required.
                 if (wantz .or. top > 0) then
                    ! initialize small orthogonal factors that will hold the
                    ! accumulated givens rotations in workspace.
                    call la_qlaset('ALL',nblst,nblst,zero,one,work,nblst)
                    pw = nblst*nblst + 1
                    do i = 1,n2nb
                       call la_qlaset('ALL',2*nnb,2*nnb,zero,one,work(pw),2*nnb)

                       pw = pw + 4*nnb*nnb
                    end do
                    ! accumulate givens rotations into workspace array.
                    do j = jcol,jcol + nnb - 1
                       ppw = (nblst + 1)*(nblst - 2) - j + jcol + 1
                       len = 2 + j - jcol
                       jrow = j + n2nb*nnb + 2
                       do i = ihi,jrow,-1
                          c = a(i,j)
                          a(i,j) = zero
                          s = b(i,j)
                          b(i,j) = zero
                          do jj = ppw,ppw + len - 1
                             temp = work(jj + nblst)
                             work(jj + nblst) = c*temp - s*work(jj)
                             work(jj) = s*temp + c*work(jj)
                          end do
                          len = len + 1
                          ppw = ppw - nblst - 1
                       end do
                       ppwo = nblst*nblst + (nnb + j - jcol - 1)*2*nnb + nnb
                       j0 = jrow - nnb
                       do jrow = j0,j + 2,-nnb
                          ppw = ppwo
                          len = 2 + j - jcol
                          do i = jrow + nnb - 1,jrow,-1
                             c = a(i,j)
                             a(i,j) = zero
                             s = b(i,j)
                             b(i,j) = zero
                             do jj = ppw,ppw + len - 1
                                temp = work(jj + 2*nnb)
                                work(jj + 2*nnb) = c*temp - s*work(jj)
                                work(jj) = s*temp + c*work(jj)
                             end do
                             len = len + 1
                             ppw = ppw - 2*nnb - 1
                          end do
                          ppwo = ppwo + 4*nnb*nnb
                       end do
                    end do
                 else
                    call la_qlaset('LOWER',ihi - jcol - 1,nnb,zero,zero,a(jcol + 2, &
                              jcol),lda)
                    call la_qlaset('LOWER',ihi - jcol - 1,nnb,zero,zero,b(jcol + 2, &
                              jcol),ldb)
                 end if
                 ! apply accumulated orthogonal matrices to a and b.
                 if (top > 0) then
                    j = ihi - nblst + 1
                    call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',top,nblst,nblst,one,a( &
                              1,j),lda,work,nblst,zero,work(pw),top)
                    call la_qlacpy('ALL',top,nblst,work(pw),top,a(1,j),lda)

                    ppwo = nblst*nblst + 1
                    j0 = j - nnb
                    do j = j0,jcol + 1,-nnb
                       if (blk22) then
                          ! exploit the structure of u.
                          call la_qorm22('RIGHT','NO TRANSPOSE',top,2*nnb,nnb,nnb,work( &
                                    ppwo),2*nnb,a(1,j),lda,work(pw),lwork - pw + 1,ierr)
                       else
                          ! ignore the structure of u.
                          call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',top,2*nnb,2*nnb, &
                                    one,a(1,j),lda,work(ppwo),2*nnb,zero,work(pw),top)
                          call la_qlacpy('ALL',top,2*nnb,work(pw),top,a(1,j),lda)

                       end if
                       ppwo = ppwo + 4*nnb*nnb
                    end do
                    j = ihi - nblst + 1
                    call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',top,nblst,nblst,one,b( &
                              1,j),ldb,work,nblst,zero,work(pw),top)
                    call la_qlacpy('ALL',top,nblst,work(pw),top,b(1,j),ldb)

                    ppwo = nblst*nblst + 1
                    j0 = j - nnb
                    do j = j0,jcol + 1,-nnb
                       if (blk22) then
                          ! exploit the structure of u.
                          call la_qorm22('RIGHT','NO TRANSPOSE',top,2*nnb,nnb,nnb,work( &
                                    ppwo),2*nnb,b(1,j),ldb,work(pw),lwork - pw + 1,ierr)
                       else
                          ! ignore the structure of u.
                          call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',top,2*nnb,2*nnb, &
                                    one,b(1,j),ldb,work(ppwo),2*nnb,zero,work(pw),top)
                          call la_qlacpy('ALL',top,2*nnb,work(pw),top,b(1,j),ldb)

                       end if
                       ppwo = ppwo + 4*nnb*nnb
                    end do
                 end if
                 ! apply accumulated orthogonal matrices to z.
                 if (wantz) then
                    j = ihi - nblst + 1
                    if (initq) then
                       topq = max(2,j - jcol + 1)
                       nh = ihi - topq + 1
                    else
                       topq = 1
                       nh = n
                    end if
                    call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',nh,nblst,nblst,one,z( &
                              topq,j),ldz,work,nblst,zero,work(pw),nh)
                    call la_qlacpy('ALL',nh,nblst,work(pw),nh,z(topq,j),ldz)

                    ppwo = nblst*nblst + 1
                    j0 = j - nnb
                    do j = j0,jcol + 1,-nnb
                          if (initq) then
                          topq = max(2,j - jcol + 1)
                          nh = ihi - topq + 1
                       end if
                       if (blk22) then
                          ! exploit the structure of u.
                          call la_qorm22('RIGHT','NO TRANSPOSE',nh,2*nnb,nnb,nnb,work( &
                                    ppwo),2*nnb,z(topq,j),ldz,work(pw),lwork - pw + 1,ierr)
                       else
                          ! ignore the structure of u.
                          call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',nh,2*nnb,2*nnb,one, &
                                     z(topq,j),ldz,work(ppwo),2*nnb,zero,work(pw),nh)
                          call la_qlacpy('ALL',nh,2*nnb,work(pw),nh,z(topq,j),ldz)

                       end if
                       ppwo = ppwo + 4*nnb*nnb
                    end do
                 end if
              end do
           end if
           ! use unblocked code to reduce the rest of the matrix
           ! avoid re-initialization of modified q and z.
           compq2 = compq
           compz2 = compz
           if (jcol /= ilo) then
              if (wantq) compq2 = 'V'
              if (wantz) compz2 = 'V'
           end if
           if (jcol < ihi) call la_qgghrd(compq2,compz2,n,jcol,ihi,a,lda,b,ldb,q,ldq, &
                      z,ldz,ierr)
           work(1) = real(lwkopt,KIND=qp)
           return
     end subroutine la_qgghd3

     !> DGGHRD: reduces a pair of real matrices (A,B) to generalized upper
     !> Hessenberg form using orthogonal transformations, where A is a
     !> general matrix and B is upper triangular.  The form of the
     !> generalized eigenvalue problem is
     !> A*x = lambda*B*x,
     !> and B is typically made upper triangular by computing its QR
     !> factorization and moving the orthogonal matrix Q to the left side
     !> of the equation.
     !> This subroutine simultaneously reduces A to a Hessenberg matrix H:
     !> Q**T*A*Z = H
     !> and transforms B to another upper triangular matrix T:
     !> Q**T*B*Z = T
     !> in order to reduce the problem to its standard form
     !> H*y = lambda*T*y
     !> where y = Z**T*x.
     !> The orthogonal matrices Q and Z are determined as products of Givens
     !> rotations.  They may either be formed explicitly, or they may be
     !> postmultiplied into input matrices Q1 and Z1, so that
     !> Q1 * A * Z1**T = (Q1*Q) * H * (Z1*Z)**T
     !> Q1 * B * Z1**T = (Q1*Q) * T * (Z1*Z)**T
     !> If Q1 is the orthogonal matrix from the QR factorization of B in the
     !> original equation A*x = lambda*B*x, then DGGHRD reduces the original
     !> problem to generalized Hessenberg form.

     pure subroutine la_qgghrd(compq,compz,n,ilo,ihi,a,lda,b,ldb,q,ldq,z,ldz, &
               info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: compq,compz
           integer(ilp),intent(in) :: ihi,ilo,lda,ldb,ldq,ldz,n
           integer(ilp),intent(out) :: info
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: ilq,ilz
           integer(ilp) :: icompq,icompz,jcol,jrow
           real(qp) :: c,s,temp
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! decode compq
           if (la_lsame(compq,'N')) then
              ilq = .false.
              icompq = 1
           else if (la_lsame(compq,'V')) then
              ilq = .true.
              icompq = 2
           else if (la_lsame(compq,'I')) then
              ilq = .true.
              icompq = 3
           else
              icompq = 0
           end if
           ! decode compz
           if (la_lsame(compz,'N')) then
              ilz = .false.
              icompz = 1
           else if (la_lsame(compz,'V')) then
              ilz = .true.
              icompz = 2
           else if (la_lsame(compz,'I')) then
              ilz = .true.
              icompz = 3
           else
              icompz = 0
           end if
           ! test the input parameters.
           info = 0
           if (icompq <= 0) then
              info = -1
           else if (icompz <= 0) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ilo < 1) then
              info = -4
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -5
           else if (lda < max(1,n)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -9
           else if ((ilq .and. ldq < n) .or. ldq < 1) then
              info = -11
           else if ((ilz .and. ldz < n) .or. ldz < 1) then
              info = -13
           end if
           if (info /= 0) then
              call la_xerbla('DGGHRD',-info)
              return
           end if
           ! initialize q and z if desired.
           if (icompq == 3) call la_qlaset('FULL',n,n,zero,one,q,ldq)
           if (icompz == 3) call la_qlaset('FULL',n,n,zero,one,z,ldz)
           ! quick return if possible
           if (n <= 1) return
           ! zero out lower triangle of b
           do jcol = 1,n - 1
              do jrow = jcol + 1,n
                 b(jrow,jcol) = zero
              end do
           end do
           ! reduce a and b
           do jcol = ilo,ihi - 2
              do jrow = ihi,jcol + 2,-1
                 ! step 1: rotate rows jrow-1, jrow to kill a(jrow,jcol)
                 temp = a(jrow - 1,jcol)
                 call la_qlartg(temp,a(jrow,jcol),c,s,a(jrow - 1,jcol))
                 a(jrow,jcol) = zero
                 call la_qrot(n - jcol,a(jrow - 1,jcol + 1),lda,a(jrow,jcol + 1),lda,c,s)

                 call la_qrot(n + 2 - jrow,b(jrow - 1,jrow - 1),ldb,b(jrow,jrow - 1),ldb,c, &
                           s)
                 if (ilq) call la_qrot(n,q(1,jrow - 1),1,q(1,jrow),1,c,s)
                 ! step 2: rotate columns jrow, jrow-1 to kill b(jrow,jrow-1)
                 temp = b(jrow,jrow)
                 call la_qlartg(temp,b(jrow,jrow - 1),c,s,b(jrow,jrow))
                 b(jrow,jrow - 1) = zero
                 call la_qrot(ihi,a(1,jrow),1,a(1,jrow - 1),1,c,s)
                 call la_qrot(jrow - 1,b(1,jrow),1,b(1,jrow - 1),1,c,s)
                 if (ilz) call la_qrot(n,z(1,jrow),1,z(1,jrow - 1),1,c,s)
              end do
           end do
           return
     end subroutine la_qgghrd

     !> DGSVJ0: is called from DGESVJ as a pre-processor and that is its main
     !> purpose. It applies Jacobi rotations in the same way as DGESVJ does, but
     !> it does not check convergence (stopping criterion). Few tuning
     !> parameters (marked by [TP]) are available for the implementer.

     pure subroutine la_qgsvj0(jobv,m,n,a,lda,d,sva,mv,v,ldv,eps,sfmin,tol, &
               nsweep,work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldv,lwork,m,mv,n,nsweep
           real(qp),intent(in) :: eps,sfmin,tol
           character,intent(in) :: jobv
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),sva(n),d(n),v(ldv,*)
           real(qp),intent(out) :: work(lwork)
        ! =====================================================================

           ! Local Scalars
           real(qp) :: aapp,aapp0,aapq,aaqq,apoaq,aqoap,big,bigtheta,cs,mxaapq,mxsinj, &
                     rootbig,rooteps,rootsfmin,roottol,small,sn,t,temp1,theta,thsign
           integer(ilp) :: blskip,emptsw,i,ibr,ierr,igl,ijblsk,ir1,iswrot,jbc,jgl,kbl, &
                     lkahead,mvl,nbl,notrot,p,pskipped,q,rowskip,swband
           logical(lk) :: applv,rotok,rsvec
           ! Local Arrays
           real(qp) :: fastr(5)
           ! Intrinsic Functions
           intrinsic :: abs,max,real,min,sign,sqrt
           ! Executable Statements
           ! test the input parameters.
           applv = la_lsame(jobv,'A')
           rsvec = la_lsame(jobv,'V')
           if (.not. (rsvec .or. applv .or. la_lsame(jobv,'N'))) then
              info = -1
           else if (m < 0) then
              info = -2
           else if ((n < 0) .or. (n > m)) then
              info = -3
           else if (lda < m) then
              info = -5
           else if ((rsvec .or. applv) .and. (mv < 0)) then
              info = -8
           else if ((rsvec .and. (ldv < n)) .or. (applv .and. (ldv < mv))) then
              info = -10
           else if (tol <= eps) then
              info = -13
           else if (nsweep < 0) then
              info = -14
           else if (lwork < m) then
              info = -16
           else
              info = 0
           end if
           ! #:(
           if (info /= 0) then
              call la_xerbla('DGSVJ0',-info)
              return
           end if
           if (rsvec) then
              mvl = n
           else if (applv) then
              mvl = mv
           end if
           rsvec = rsvec .or. applv
           rooteps = sqrt(eps)
           rootsfmin = sqrt(sfmin)
           small = sfmin/eps
           big = one/sfmin
           rootbig = one/rootsfmin
           bigtheta = one/rooteps
           roottol = sqrt(tol)
           ! -#- row-cyclic jacobi svd algorithm with column pivoting -#-
           emptsw = (n*(n - 1))/2
           notrot = 0
           fastr(1) = zero
           ! -#- row-cyclic pivot strategy with de rijk's pivoting -#-
           swband = 0
      ! [tp] swband is a tuning parameter. it is meaningful and effective
           ! if la_dgesvj is used as a computational routine in the preconditioned
           ! jacobi svd algorithm la_dgesvj. for sweeps i=1:swband the procedure
           ! ......
           kbl = min(8,n)
      ! [tp] kbl is a tuning parameter that defines the tile size in the
           ! tiling of the p-q loops of pivot pairs. in general, an optimal
           ! value of kbl depends on the matrix dimensions and on the
           ! parameters of the computer's memory.
           nbl = n/kbl
           if ((nbl*kbl) /= n) nbl = nbl + 1
           blskip = (kbl**2) + 1
      ! [tp] blkskip is a tuning parameter that depends on swband and kbl.
           rowskip = min(5,kbl)
      ! [tp] rowskip is a tuning parameter.
           lkahead = 1
      ! [tp] lkahead is a tuning parameter.
           swband = 0
           pskipped = 0
           loop_1993: do i = 1,nsweep
           ! .. go go go ...
              mxaapq = zero
              mxsinj = zero
              iswrot = 0
              notrot = 0
              pskipped = 0
              loop_2000: do ibr = 1,nbl
                 igl = (ibr - 1)*kbl + 1
                 loop_1002: do ir1 = 0,min(lkahead,nbl - ibr)
                    igl = igl + ir1*kbl
                    loop_2001: do p = igl,min(igl + kbl - 1,n - 1)
           ! .. de rijk's pivoting
                       q = la_iqamax(n - p + 1,sva(p),1) + p - 1
                       if (p /= q) then
                          call la_qswap(m,a(1,p),1,a(1,q),1)
                          if (rsvec) call la_qswap(mvl,v(1,p),1,v(1,q),1)
                          temp1 = sva(p)
                          sva(p) = sva(q)
                          sva(q) = temp1
                          temp1 = d(p)
                          d(p) = d(q)
                          d(q) = temp1
                       end if
                       if (ir1 == 0) then
              ! column norms are periodically updated by explicit
              ! norm computation.
              ! caveat:
              ! some blas implementations compute la_qnrm2(m,a(1,p),1)
              ! as sqrt(la_qdot(m,a(1,p),1,a(1,p),1)), which may result in
              ! overflow for ||a(:,p)||_2 > sqrt(overflow_threshold), and
              ! underflow for ||a(:,p)||_2 < sqrt(underflow_threshold).
              ! hence, la_qnrm2 cannot be trusted, not even in the case when
              ! the true norm is far from the under(over)flow boundaries.
              ! if properly implemented la_qnrm2 is available, the if-then-else
              ! below should read "aapp = la_qnrm2( m, a(1,p), 1 ) * d(p)".
                          if ((sva(p) < rootbig) .and. (sva(p) > rootsfmin)) then
                             sva(p) = la_qnrm2(m,a(1,p),1)*d(p)
                          else
                             temp1 = zero
                             aapp = one
                             call la_qlassq(m,a(1,p),1,temp1,aapp)
                             sva(p) = temp1*sqrt(aapp)*d(p)
                          end if
                          aapp = sva(p)
                       else
                          aapp = sva(p)
                       end if
                       if (aapp > zero) then
                          pskipped = 0
                          loop_2002: do q = p + 1,min(igl + kbl - 1,n)
                             aaqq = sva(q)
                             if (aaqq > zero) then
                                aapp0 = aapp
                                if (aaqq >= one) then
                                   rotok = (small*aapp) <= aaqq
                                   if (aapp < (big/aaqq)) then
                                      aapq = (la_qdot(m,a(1,p),1,a(1,q),1)*d(p) &
                                                *d(q)/aaqq)/aapp
                                   else
                                      call la_qcopy(m,a(1,p),1,work,1)
                                      call la_qlascl('G',0,0,aapp,d(p),m,1,work,lda, &
                                                 ierr)
                                      aapq = la_qdot(m,work,1,a(1,q),1)*d(q)/ &
                                                aaqq
                                   end if
                                else
                                   rotok = aapp <= (aaqq/small)
                                   if (aapp > (small/aaqq)) then
                                      aapq = (la_qdot(m,a(1,p),1,a(1,q),1)*d(p) &
                                                *d(q)/aaqq)/aapp
                                   else
                                      call la_qcopy(m,a(1,q),1,work,1)
                                      call la_qlascl('G',0,0,aaqq,d(q),m,1,work,lda, &
                                                 ierr)
                                      aapq = la_qdot(m,work,1,a(1,p),1)*d(p)/ &
                                                aapp
                                   end if
                                end if
                                mxaapq = max(mxaapq,abs(aapq))
              ! to rotate or not to rotate, that is the question ...
                                if (abs(aapq) > tol) then
                 ! Rotate
                 ! rotated = rotated + one
                                   if (ir1 == 0) then
                                      notrot = 0
                                      pskipped = 0
                                      iswrot = iswrot + 1
                                   end if
                                   if (rotok) then
                                      aqoap = aaqq/aapp
                                      apoaq = aapp/aaqq
                                      theta = -half*abs(aqoap - apoaq)/aapq
                                      if (abs(theta) > bigtheta) then
                                         t = half/theta
                                         fastr(3) = t*d(p)/d(q)
                                         fastr(4) = -t*d(q)/d(p)
                                         call la_qrotm(m,a(1,p),1,a(1,q),1,fastr)

                                         if (rsvec) call la_qrotm(mvl,v(1,p),1,v(1,q), &
                                                    1,fastr)
                                         sva(q) = aaqq*sqrt(max(zero,one + t*apoaq*aapq))

                                         aapp = aapp*sqrt(max(zero,one - t*aqoap*aapq))
                                         mxsinj = max(mxsinj,abs(t))
                                      else
                       ! Choose Correct Signum For Theta And Rotate
                                         thsign = -sign(one,aapq)
                                         t = one/(theta + thsign*sqrt(one + theta*theta))

                                         cs = sqrt(one/(one + t*t))
                                         sn = t*cs
                                         mxsinj = max(mxsinj,abs(sn))
                                         sva(q) = aaqq*sqrt(max(zero,one + t*apoaq*aapq))

                                         aapp = aapp*sqrt(max(zero,one - t*aqoap*aapq))
                                         apoaq = d(p)/d(q)
                                         aqoap = d(q)/d(p)
                                         if (d(p) >= one) then
                                            if (d(q) >= one) then
                                               fastr(3) = t*apoaq
                                               fastr(4) = -t*aqoap
                                               d(p) = d(p)*cs
                                               d(q) = d(q)*cs
                                               call la_qrotm(m,a(1,p),1,a(1,q),1, &
                                                         fastr)
                                               if (rsvec) call la_qrotm(mvl,v(1,p),1,v( &
                                                         1,q),1,fastr)
                                            else
                                               call la_qaxpy(m,-t*aqoap,a(1,q),1,a(1, &
                                                         p),1)
                                               call la_qaxpy(m,cs*sn*apoaq,a(1,p),1,a( &
                                                         1,q),1)
                                               d(p) = d(p)*cs
                                               d(q) = d(q)/cs
                                               if (rsvec) then
                                                  call la_qaxpy(mvl,-t*aqoap,v(1,q),1,v( &
                                                             1,p),1)
                                                  call la_qaxpy(mvl,cs*sn*apoaq,v(1,p),1, &
                                                            v(1,q),1)
                                               end if
                                            end if
                                         else
                                            if (d(q) >= one) then
                                               call la_qaxpy(m,t*apoaq,a(1,p),1,a(1,q &
                                                         ),1)
                                               call la_qaxpy(m,-cs*sn*aqoap,a(1,q),1,a( &
                                                         1,p),1)
                                               d(p) = d(p)/cs
                                               d(q) = d(q)*cs
                                               if (rsvec) then
                                                  call la_qaxpy(mvl,t*apoaq,v(1,p),1,v( &
                                                            1,q),1)
                                                  call la_qaxpy(mvl,-cs*sn*aqoap,v(1,q), &
                                                            1,v(1,p),1)
                                               end if
                                            else
                                               if (d(p) >= d(q)) then
                                                  call la_qaxpy(m,-t*aqoap,a(1,q),1,a( &
                                                            1,p),1)
                                                  call la_qaxpy(m,cs*sn*apoaq,a(1,p),1, &
                                                            a(1,q),1)
                                                  d(p) = d(p)*cs
                                                  d(q) = d(q)/cs
                                                  if (rsvec) then
                                                     call la_qaxpy(mvl,-t*aqoap,v(1,q),1, &
                                                               v(1,p),1)
                                                     call la_qaxpy(mvl,cs*sn*apoaq,v(1,p), &
                                                                1,v(1,q),1)
                                                  end if
                                               else
                                                  call la_qaxpy(m,t*apoaq,a(1,p),1,a(1, &
                                                             q),1)
                                                  call la_qaxpy(m,-cs*sn*aqoap,a(1,q),1, &
                                                            a(1,p),1)
                                                  d(p) = d(p)/cs
                                                  d(q) = d(q)*cs
                                                  if (rsvec) then
                                                     call la_qaxpy(mvl,t*apoaq,v(1,p),1, &
                                                               v(1,q),1)
                                                     call la_qaxpy(mvl,-cs*sn*aqoap,v(1,q) &
                                                               ,1,v(1,p),1)
                                                  end if
                                               end if
                                            end if
                                         end if
                                      end if
                                   else
                    ! .. have to use modified gram-schmidt like transformation
                                      call la_qcopy(m,a(1,p),1,work,1)
                                      call la_qlascl('G',0,0,aapp,one,m,1,work,lda, &
                                                ierr)
                                      call la_qlascl('G',0,0,aaqq,one,m,1,a(1,q), &
                                                lda,ierr)
                                      temp1 = -aapq*d(p)/d(q)
                                      call la_qaxpy(m,temp1,work,1,a(1,q),1)
                                      call la_qlascl('G',0,0,one,aaqq,m,1,a(1,q), &
                                                lda,ierr)
                                      sva(q) = aaqq*sqrt(max(zero,one - aapq*aapq))
                                      mxsinj = max(mxsinj,sfmin)
                                   end if
                 ! end if rotok then ... else
                 ! in the case of cancellation in updating sva(q), sva(p)
                 ! recompute sva(q), sva(p).
                                   if ((sva(q)/aaqq)**2 <= rooteps) then
                                      if ((aaqq < rootbig) .and. (aaqq > rootsfmin)) then
                                         sva(q) = la_qnrm2(m,a(1,q),1)*d(q)
                                      else
                                         t = zero
                                         aaqq = one
                                         call la_qlassq(m,a(1,q),1,t,aaqq)
                                         sva(q) = t*sqrt(aaqq)*d(q)
                                      end if
                                   end if
                                   if ((aapp/aapp0) <= rooteps) then
                                      if ((aapp < rootbig) .and. (aapp > rootsfmin)) then
                                         aapp = la_qnrm2(m,a(1,p),1)*d(p)
                                      else
                                         t = zero
                                         aapp = one
                                         call la_qlassq(m,a(1,p),1,t,aapp)
                                         aapp = t*sqrt(aapp)*d(p)
                                      end if
                                      sva(p) = aapp
                                   end if
                                else
              ! a(:,p) and a(:,q) already numerically orthogonal
                                   if (ir1 == 0) notrot = notrot + 1
                                   pskipped = pskipped + 1
                                end if
                             else
              ! a(:,q) is zero column
                                if (ir1 == 0) notrot = notrot + 1
                                pskipped = pskipped + 1
                             end if
                             if ((i <= swband) .and. (pskipped > rowskip)) then
                                if (ir1 == 0) aapp = -aapp
                                notrot = 0
                                go to 2103
                             end if
                          end do loop_2002
           ! end q-loop
           2103 continue
           ! bailed out of q-loop
                          sva(p) = aapp
                       else
                          sva(p) = aapp
                          if ((ir1 == 0) .and. (aapp == zero)) notrot = notrot + min(igl + kbl - 1, &
                                    n) - p
                       end if
                    end do loop_2001
           ! end of the p-loop
           ! end of doing the block ( ibr, ibr )
                 end do loop_1002
           ! end of ir1-loop
      ! ........................................................
       ! ... go to the off diagonal blocks
                 igl = (ibr - 1)*kbl + 1
                 loop_2010: do jbc = ibr + 1,nbl
                    jgl = (jbc - 1)*kbl + 1
              ! doing the block at ( ibr, jbc )
                    ijblsk = 0
                    loop_2100: do p = igl,min(igl + kbl - 1,n)
                       aapp = sva(p)
                       if (aapp > zero) then
                          pskipped = 0
                          loop_2200: do q = jgl,min(jgl + kbl - 1,n)
                             aaqq = sva(q)
                             if (aaqq > zero) then
                                aapp0 = aapp
           ! -#- m x 2 jacobi svd -#-
              ! -#- safe gram matrix computation -#-
                                if (aaqq >= one) then
                                   if (aapp >= aaqq) then
                                      rotok = (small*aapp) <= aaqq
                                   else
                                      rotok = (small*aaqq) <= aapp
                                   end if
                                   if (aapp < (big/aaqq)) then
                                      aapq = (la_qdot(m,a(1,p),1,a(1,q),1)*d(p) &
                                                *d(q)/aaqq)/aapp
                                   else
                                      call la_qcopy(m,a(1,p),1,work,1)
                                      call la_qlascl('G',0,0,aapp,d(p),m,1,work,lda, &
                                                 ierr)
                                      aapq = la_qdot(m,work,1,a(1,q),1)*d(q)/ &
                                                aaqq
                                   end if
                                else
                                   if (aapp >= aaqq) then
                                      rotok = aapp <= (aaqq/small)
                                   else
                                      rotok = aaqq <= (aapp/small)
                                   end if
                                   if (aapp > (small/aaqq)) then
                                      aapq = (la_qdot(m,a(1,p),1,a(1,q),1)*d(p) &
                                                *d(q)/aaqq)/aapp
                                   else
                                      call la_qcopy(m,a(1,q),1,work,1)
                                      call la_qlascl('G',0,0,aaqq,d(q),m,1,work,lda, &
                                                 ierr)
                                      aapq = la_qdot(m,work,1,a(1,p),1)*d(p)/ &
                                                aapp
                                   end if
                                end if
                                mxaapq = max(mxaapq,abs(aapq))
              ! to rotate or not to rotate, that is the question ...
                                if (abs(aapq) > tol) then
                                   notrot = 0
                 ! rotated  = rotated + 1
                                   pskipped = 0
                                   iswrot = iswrot + 1
                                   if (rotok) then
                                      aqoap = aaqq/aapp
                                      apoaq = aapp/aaqq
                                      theta = -half*abs(aqoap - apoaq)/aapq
                                      if (aaqq > aapp0) theta = -theta
                                      if (abs(theta) > bigtheta) then
                                         t = half/theta
                                         fastr(3) = t*d(p)/d(q)
                                         fastr(4) = -t*d(q)/d(p)
                                         call la_qrotm(m,a(1,p),1,a(1,q),1,fastr)

                                         if (rsvec) call la_qrotm(mvl,v(1,p),1,v(1,q), &
                                                    1,fastr)
                                         sva(q) = aaqq*sqrt(max(zero,one + t*apoaq*aapq))

                                         aapp = aapp*sqrt(max(zero,one - t*aqoap*aapq))
                                         mxsinj = max(mxsinj,abs(t))
                                      else
                       ! Choose Correct Signum For Theta And Rotate
                                         thsign = -sign(one,aapq)
                                         if (aaqq > aapp0) thsign = -thsign
                                         t = one/(theta + thsign*sqrt(one + theta*theta))

                                         cs = sqrt(one/(one + t*t))
                                         sn = t*cs
                                         mxsinj = max(mxsinj,abs(sn))
                                         sva(q) = aaqq*sqrt(max(zero,one + t*apoaq*aapq))

                                         aapp = aapp*sqrt(max(zero,one - t*aqoap*aapq))
                                         apoaq = d(p)/d(q)
                                         aqoap = d(q)/d(p)
                                         if (d(p) >= one) then
                                            if (d(q) >= one) then
                                               fastr(3) = t*apoaq
                                               fastr(4) = -t*aqoap
                                               d(p) = d(p)*cs
                                               d(q) = d(q)*cs
                                               call la_qrotm(m,a(1,p),1,a(1,q),1, &
                                                         fastr)
                                               if (rsvec) call la_qrotm(mvl,v(1,p),1,v( &
                                                         1,q),1,fastr)
                                            else
                                               call la_qaxpy(m,-t*aqoap,a(1,q),1,a(1, &
                                                         p),1)
                                               call la_qaxpy(m,cs*sn*apoaq,a(1,p),1,a( &
                                                         1,q),1)
                                               if (rsvec) then
                                                  call la_qaxpy(mvl,-t*aqoap,v(1,q),1,v( &
                                                             1,p),1)
                                                  call la_qaxpy(mvl,cs*sn*apoaq,v(1,p),1, &
                                                            v(1,q),1)
                                               end if
                                               d(p) = d(p)*cs
                                               d(q) = d(q)/cs
                                            end if
                                         else
                                            if (d(q) >= one) then
                                               call la_qaxpy(m,t*apoaq,a(1,p),1,a(1,q &
                                                         ),1)
                                               call la_qaxpy(m,-cs*sn*aqoap,a(1,q),1,a( &
                                                         1,p),1)
                                               if (rsvec) then
                                                  call la_qaxpy(mvl,t*apoaq,v(1,p),1,v( &
                                                            1,q),1)
                                                  call la_qaxpy(mvl,-cs*sn*aqoap,v(1,q), &
                                                            1,v(1,p),1)
                                               end if
                                               d(p) = d(p)/cs
                                               d(q) = d(q)*cs
                                            else
                                               if (d(p) >= d(q)) then
                                                  call la_qaxpy(m,-t*aqoap,a(1,q),1,a( &
                                                            1,p),1)
                                                  call la_qaxpy(m,cs*sn*apoaq,a(1,p),1, &
                                                            a(1,q),1)
                                                  d(p) = d(p)*cs
                                                  d(q) = d(q)/cs
                                                  if (rsvec) then
                                                     call la_qaxpy(mvl,-t*aqoap,v(1,q),1, &
                                                               v(1,p),1)
                                                     call la_qaxpy(mvl,cs*sn*apoaq,v(1,p), &
                                                                1,v(1,q),1)
                                                  end if
                                               else
                                                  call la_qaxpy(m,t*apoaq,a(1,p),1,a(1, &
                                                             q),1)
                                                  call la_qaxpy(m,-cs*sn*aqoap,a(1,q),1, &
                                                            a(1,p),1)
                                                  d(p) = d(p)/cs
                                                  d(q) = d(q)*cs
                                                  if (rsvec) then
                                                     call la_qaxpy(mvl,t*apoaq,v(1,p),1, &
                                                               v(1,q),1)
                                                     call la_qaxpy(mvl,-cs*sn*aqoap,v(1,q) &
                                                               ,1,v(1,p),1)
                                                  end if
                                               end if
                                            end if
                                         end if
                                      end if
                                   else
                                      if (aapp > aaqq) then
                                         call la_qcopy(m,a(1,p),1,work,1)
                                         call la_qlascl('G',0,0,aapp,one,m,1,work,lda, &
                                                    ierr)
                                         call la_qlascl('G',0,0,aaqq,one,m,1,a(1,q), &
                                                    lda,ierr)
                                         temp1 = -aapq*d(p)/d(q)
                                         call la_qaxpy(m,temp1,work,1,a(1,q),1)

                                         call la_qlascl('G',0,0,one,aaqq,m,1,a(1,q), &
                                                    lda,ierr)
                                         sva(q) = aaqq*sqrt(max(zero,one - aapq*aapq))
                                         mxsinj = max(mxsinj,sfmin)
                                      else
                                         call la_qcopy(m,a(1,q),1,work,1)
                                         call la_qlascl('G',0,0,aaqq,one,m,1,work,lda, &
                                                    ierr)
                                         call la_qlascl('G',0,0,aapp,one,m,1,a(1,p), &
                                                    lda,ierr)
                                         temp1 = -aapq*d(q)/d(p)
                                         call la_qaxpy(m,temp1,work,1,a(1,p),1)

                                         call la_qlascl('G',0,0,one,aapp,m,1,a(1,p), &
                                                    lda,ierr)
                                         sva(p) = aapp*sqrt(max(zero,one - aapq*aapq))
                                         mxsinj = max(mxsinj,sfmin)
                                      end if
                                   end if
                 ! end if rotok then ... else
                 ! in the case of cancellation in updating sva(q)
                 ! .. recompute sva(q)
                                   if ((sva(q)/aaqq)**2 <= rooteps) then
                                      if ((aaqq < rootbig) .and. (aaqq > rootsfmin)) then
                                         sva(q) = la_qnrm2(m,a(1,q),1)*d(q)
                                      else
                                         t = zero
                                         aaqq = one
                                         call la_qlassq(m,a(1,q),1,t,aaqq)
                                         sva(q) = t*sqrt(aaqq)*d(q)
                                      end if
                                   end if
                                   if ((aapp/aapp0)**2 <= rooteps) then
                                      if ((aapp < rootbig) .and. (aapp > rootsfmin)) then
                                         aapp = la_qnrm2(m,a(1,p),1)*d(p)
                                      else
                                         t = zero
                                         aapp = one
                                         call la_qlassq(m,a(1,p),1,t,aapp)
                                         aapp = t*sqrt(aapp)*d(p)
                                      end if
                                      sva(p) = aapp
                                   end if
                    ! end of ok rotation
                                else
                                   notrot = notrot + 1
                                   pskipped = pskipped + 1
                                   ijblsk = ijblsk + 1
                                end if
                             else
                                notrot = notrot + 1
                                pskipped = pskipped + 1
                                ijblsk = ijblsk + 1
                             end if
                             if ((i <= swband) .and. (ijblsk >= blskip)) then
                                sva(p) = aapp
                                notrot = 0
                                go to 2011
                             end if
                             if ((i <= swband) .and. (pskipped > rowskip)) then
                                aapp = -aapp
                                notrot = 0
                                go to 2203
                             end if
                          end do loop_2200
              ! end of the q-loop
              2203 continue
                          sva(p) = aapp
                       else
                          if (aapp == zero) notrot = notrot + min(jgl + kbl - 1,n) - jgl + 1
                          if (aapp < zero) notrot = 0
                       end if
                    end do loop_2100
           ! end of the p-loop
                 end do loop_2010
           ! end of the jbc-loop
           2011 continue
      ! 2011 bailed out of the jbc-loop
                 do p = igl,min(igl + kbl - 1,n)
                    sva(p) = abs(sva(p))
                 end do
              end do loop_2000
      ! 2000 :: end of the ibr-loop
           ! .. update sva(n)
              if ((sva(n) < rootbig) .and. (sva(n) > rootsfmin)) then
                 sva(n) = la_qnrm2(m,a(1,n),1)*d(n)
              else
                 t = zero
                 aapp = one
                 call la_qlassq(m,a(1,n),1,t,aapp)
                 sva(n) = t*sqrt(aapp)*d(n)
              end if
           ! additional steering devices
              if ((i < swband) .and. ((mxaapq <= roottol) .or. (iswrot <= n))) swband = i
              if ((i > swband + 1) .and. (mxaapq < real(n,KIND=qp)*tol) .and. (real(n,KIND=qp) &
                        *mxaapq*mxsinj < tol)) then
                 go to 1994
              end if
              if (notrot >= emptsw) go to 1994
           end do loop_1993
           ! end i=1:nsweep loop
       ! #:) reaching this point means that the procedure has completed the given
           ! number of iterations.
           info = nsweep - 1
           go to 1995
           1994 continue
       ! #:) reaching this point means that during the i-th sweep all pivots were
           ! below the given tolerance, causing early exit.
           info = 0
       ! #:) info = 0 confirms successful iterations.
       1995 continue
           ! sort the vector d.
           do p = 1,n - 1
              q = la_iqamax(n - p + 1,sva(p),1) + p - 1
              if (p /= q) then
                 temp1 = sva(p)
                 sva(p) = sva(q)
                 sva(q) = temp1
                 temp1 = d(p)
                 d(p) = d(q)
                 d(q) = temp1
                 call la_qswap(m,a(1,p),1,a(1,q),1)
                 if (rsvec) call la_qswap(mvl,v(1,p),1,v(1,q),1)
              end if
           end do
           return
     end subroutine la_qgsvj0

     !> DGSVJ1: is called from DGESVJ as a pre-processor and that is its main
     !> purpose. It applies Jacobi rotations in the same way as DGESVJ does, but
     !> it targets only particular pivots and it does not check convergence
     !> (stopping criterion). Few tuning parameters (marked by [TP]) are
     !> available for the implementer.
     !> Further Details
     !> 
     !> DGSVJ1 applies few sweeps of Jacobi rotations in the column space of
     !> the input M-by-N matrix A. The pivot pairs are taken from the (1,2)
     !> off-diagonal block in the corresponding N-by-N Gram matrix A^T * A. The
     !> block-entries (tiles) of the (1,2) off-diagonal block are marked by the
     !> [x]'s in the following scheme:
     !> | *  *  * [x] [x] [x]|
     !> | *  *  * [x] [x] [x]|    Row-cycling in the nblr-by-nblc [x] blocks.
     !> | *  *  * [x] [x] [x]|    Row-cyclic pivoting inside each [x] block.
     !> |[x] [x] [x] *  *  * |
     !> |[x] [x] [x] *  *  * |
     !> |[x] [x] [x] *  *  * |
     !> In terms of the columns of A, the first N1 columns are rotated 'against'
     !> the remaining N-N1 columns, trying to increase the angle between the
     !> corresponding subspaces. The off-diagonal block is N1-by(N-N1) and it is
     !> tiled using quadratic tiles of side KBL. Here, KBL is a tuning parameter.
     !> The number of sweeps is given in NSWEEP and the orthogonality threshold
     !> is given in TOL.

     pure subroutine la_qgsvj1(jobv,m,n,n1,a,lda,d,sva,mv,v,ldv,eps,sfmin,tol, &
               nsweep,work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           real(qp),intent(in) :: eps,sfmin,tol
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldv,lwork,m,mv,n,n1,nsweep
           character,intent(in) :: jobv
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),d(n),sva(n),v(ldv,*)
           real(qp),intent(out) :: work(lwork)
        ! =====================================================================

           ! Local Scalars
           real(qp) :: aapp,aapp0,aapq,aaqq,apoaq,aqoap,big,bigtheta,cs,large,mxaapq, &
           mxsinj,rootbig,rooteps,rootsfmin,roottol,small,sn,t,temp1,theta, &
                     thsign
           integer(ilp) :: blskip,emptsw,i,ibr,igl,ierr,ijblsk,iswrot,jbc,jgl,kbl,mvl, &
                     notrot,nblc,nblr,p,pskipped,q,rowskip,swband
           logical(lk) :: applv,rotok,rsvec
           ! Local Arrays
           real(qp) :: fastr(5)
           ! Intrinsic Functions
           intrinsic :: abs,max,real,min,sign,sqrt
           ! Executable Statements
           ! test the input parameters.
           applv = la_lsame(jobv,'A')
           rsvec = la_lsame(jobv,'V')
           if (.not. (rsvec .or. applv .or. la_lsame(jobv,'N'))) then
              info = -1
           else if (m < 0) then
              info = -2
           else if ((n < 0) .or. (n > m)) then
              info = -3
           else if (n1 < 0) then
              info = -4
           else if (lda < m) then
              info = -6
           else if ((rsvec .or. applv) .and. (mv < 0)) then
              info = -9
           else if ((rsvec .and. (ldv < n)) .or. (applv .and. (ldv < mv))) then
              info = -11
           else if (tol <= eps) then
              info = -14
           else if (nsweep < 0) then
              info = -15
           else if (lwork < m) then
              info = -17
           else
              info = 0
           end if
           ! #:(
           if (info /= 0) then
              call la_xerbla('DGSVJ1',-info)
              return
           end if
           if (rsvec) then
              mvl = n
           else if (applv) then
              mvl = mv
           end if
           rsvec = rsvec .or. applv
           rooteps = sqrt(eps)
           rootsfmin = sqrt(sfmin)
           small = sfmin/eps
           big = one/sfmin
           rootbig = one/rootsfmin
           large = big/sqrt(real(m*n,KIND=qp))
           bigtheta = one/rooteps
           roottol = sqrt(tol)
           ! Initialize The Right Singular Vector Matrix
           ! rsvec = la_lsame( jobv, 'y' )
           emptsw = n1*(n - n1)
           notrot = 0
           fastr(1) = zero
           ! .. row-cyclic pivot strategy with de rijk's pivoting ..
           kbl = min(8,n)
           nblr = n1/kbl
           if ((nblr*kbl) /= n1) nblr = nblr + 1
           ! .. the tiling is nblr-by-nblc [tiles]
           nblc = (n - n1)/kbl
           if ((nblc*kbl) /= (n - n1)) nblc = nblc + 1
           blskip = (kbl**2) + 1
      ! [tp] blkskip is a tuning parameter that depends on swband and kbl.
           rowskip = min(5,kbl)
      ! [tp] rowskip is a tuning parameter.
           swband = 0
      ! [tp] swband is a tuning parameter. it is meaningful and effective
           ! if la_dgesvj is used as a computational routine in the preconditioned
           ! jacobi svd algorithm la_dgesvj.
           ! | *   *   * [x] [x] [x]|
           ! | *   *   * [x] [x] [x]|    row-cycling in the nblr-by-nblc [x] blocks.
           ! | *   *   * [x] [x] [x]|    row-cyclic pivoting inside each [x] block.
           ! |[x] [x] [x] *   *   * |
           ! |[x] [x] [x] *   *   * |
           ! |[x] [x] [x] *   *   * |
           loop_1993: do i = 1,nsweep
           ! .. go go go ...
              mxaapq = zero
              mxsinj = zero
              iswrot = 0
              notrot = 0
              pskipped = 0
              loop_2000: do ibr = 1,nblr
                 igl = (ibr - 1)*kbl + 1
      ! ........................................................
       ! ... go to the off diagonal blocks
                 igl = (ibr - 1)*kbl + 1
                 loop_2010: do jbc = 1,nblc
                    jgl = n1 + (jbc - 1)*kbl + 1
              ! doing the block at ( ibr, jbc )
                    ijblsk = 0
                    loop_2100: do p = igl,min(igl + kbl - 1,n1)
                       aapp = sva(p)
                       if (aapp > zero) then
                          pskipped = 0
                          loop_2200: do q = jgl,min(jgl + kbl - 1,n)
                             aaqq = sva(q)
                             if (aaqq > zero) then
                                aapp0 = aapp
           ! M X 2 Jacobi Svd
              ! Safe Gram Matrix Computation
                                if (aaqq >= one) then
                                   if (aapp >= aaqq) then
                                      rotok = (small*aapp) <= aaqq
                                   else
                                      rotok = (small*aaqq) <= aapp
                                   end if
                                   if (aapp < (big/aaqq)) then
                                      aapq = (la_qdot(m,a(1,p),1,a(1,q),1)*d(p) &
                                                *d(q)/aaqq)/aapp
                                   else
                                      call la_qcopy(m,a(1,p),1,work,1)
                                      call la_qlascl('G',0,0,aapp,d(p),m,1,work,lda, &
                                                 ierr)
                                      aapq = la_qdot(m,work,1,a(1,q),1)*d(q)/ &
                                                aaqq
                                   end if
                                else
                                   if (aapp >= aaqq) then
                                      rotok = aapp <= (aaqq/small)
                                   else
                                      rotok = aaqq <= (aapp/small)
                                   end if
                                   if (aapp > (small/aaqq)) then
                                      aapq = (la_qdot(m,a(1,p),1,a(1,q),1)*d(p) &
                                                *d(q)/aaqq)/aapp
                                   else
                                      call la_qcopy(m,a(1,q),1,work,1)
                                      call la_qlascl('G',0,0,aaqq,d(q),m,1,work,lda, &
                                                 ierr)
                                      aapq = la_qdot(m,work,1,a(1,p),1)*d(p)/ &
                                                aapp
                                   end if
                                end if
                                mxaapq = max(mxaapq,abs(aapq))
              ! to rotate or not to rotate, that is the question ...
                                if (abs(aapq) > tol) then
                                   notrot = 0
                 ! rotated  = rotated + 1
                                   pskipped = 0
                                   iswrot = iswrot + 1
                                   if (rotok) then
                                      aqoap = aaqq/aapp
                                      apoaq = aapp/aaqq
                                      theta = -half*abs(aqoap - apoaq)/aapq
                                      if (aaqq > aapp0) theta = -theta
                                      if (abs(theta) > bigtheta) then
                                         t = half/theta
                                         fastr(3) = t*d(p)/d(q)
                                         fastr(4) = -t*d(q)/d(p)
                                         call la_qrotm(m,a(1,p),1,a(1,q),1,fastr)

                                         if (rsvec) call la_qrotm(mvl,v(1,p),1,v(1,q), &
                                                    1,fastr)
                                         sva(q) = aaqq*sqrt(max(zero,one + t*apoaq*aapq))

                                         aapp = aapp*sqrt(max(zero,one - t*aqoap*aapq))
                                         mxsinj = max(mxsinj,abs(t))
                                      else
                       ! Choose Correct Signum For Theta And Rotate
                                         thsign = -sign(one,aapq)
                                         if (aaqq > aapp0) thsign = -thsign
                                         t = one/(theta + thsign*sqrt(one + theta*theta))

                                         cs = sqrt(one/(one + t*t))
                                         sn = t*cs
                                         mxsinj = max(mxsinj,abs(sn))
                                         sva(q) = aaqq*sqrt(max(zero,one + t*apoaq*aapq))

                                         aapp = aapp*sqrt(max(zero,one - t*aqoap*aapq))
                                         apoaq = d(p)/d(q)
                                         aqoap = d(q)/d(p)
                                         if (d(p) >= one) then
                                            if (d(q) >= one) then
                                               fastr(3) = t*apoaq
                                               fastr(4) = -t*aqoap
                                               d(p) = d(p)*cs
                                               d(q) = d(q)*cs
                                               call la_qrotm(m,a(1,p),1,a(1,q),1, &
                                                         fastr)
                                               if (rsvec) call la_qrotm(mvl,v(1,p),1,v( &
                                                         1,q),1,fastr)
                                            else
                                               call la_qaxpy(m,-t*aqoap,a(1,q),1,a(1, &
                                                         p),1)
                                               call la_qaxpy(m,cs*sn*apoaq,a(1,p),1,a( &
                                                         1,q),1)
                                               if (rsvec) then
                                                  call la_qaxpy(mvl,-t*aqoap,v(1,q),1,v( &
                                                             1,p),1)
                                                  call la_qaxpy(mvl,cs*sn*apoaq,v(1,p),1, &
                                                            v(1,q),1)
                                               end if
                                               d(p) = d(p)*cs
                                               d(q) = d(q)/cs
                                            end if
                                         else
                                            if (d(q) >= one) then
                                               call la_qaxpy(m,t*apoaq,a(1,p),1,a(1,q &
                                                         ),1)
                                               call la_qaxpy(m,-cs*sn*aqoap,a(1,q),1,a( &
                                                         1,p),1)
                                               if (rsvec) then
                                                  call la_qaxpy(mvl,t*apoaq,v(1,p),1,v( &
                                                            1,q),1)
                                                  call la_qaxpy(mvl,-cs*sn*aqoap,v(1,q), &
                                                            1,v(1,p),1)
                                               end if
                                               d(p) = d(p)/cs
                                               d(q) = d(q)*cs
                                            else
                                               if (d(p) >= d(q)) then
                                                  call la_qaxpy(m,-t*aqoap,a(1,q),1,a( &
                                                            1,p),1)
                                                  call la_qaxpy(m,cs*sn*apoaq,a(1,p),1, &
                                                            a(1,q),1)
                                                  d(p) = d(p)*cs
                                                  d(q) = d(q)/cs
                                                  if (rsvec) then
                                                     call la_qaxpy(mvl,-t*aqoap,v(1,q),1, &
                                                               v(1,p),1)
                                                     call la_qaxpy(mvl,cs*sn*apoaq,v(1,p), &
                                                                1,v(1,q),1)
                                                  end if
                                               else
                                                  call la_qaxpy(m,t*apoaq,a(1,p),1,a(1, &
                                                             q),1)
                                                  call la_qaxpy(m,-cs*sn*aqoap,a(1,q),1, &
                                                            a(1,p),1)
                                                  d(p) = d(p)/cs
                                                  d(q) = d(q)*cs
                                                  if (rsvec) then
                                                     call la_qaxpy(mvl,t*apoaq,v(1,p),1, &
                                                               v(1,q),1)
                                                     call la_qaxpy(mvl,-cs*sn*aqoap,v(1,q) &
                                                               ,1,v(1,p),1)
                                                  end if
                                               end if
                                            end if
                                         end if
                                      end if
                                   else
                                      if (aapp > aaqq) then
                                         call la_qcopy(m,a(1,p),1,work,1)
                                         call la_qlascl('G',0,0,aapp,one,m,1,work,lda, &
                                                    ierr)
                                         call la_qlascl('G',0,0,aaqq,one,m,1,a(1,q), &
                                                    lda,ierr)
                                         temp1 = -aapq*d(p)/d(q)
                                         call la_qaxpy(m,temp1,work,1,a(1,q),1)

                                         call la_qlascl('G',0,0,one,aaqq,m,1,a(1,q), &
                                                    lda,ierr)
                                         sva(q) = aaqq*sqrt(max(zero,one - aapq*aapq))
                                         mxsinj = max(mxsinj,sfmin)
                                      else
                                         call la_qcopy(m,a(1,q),1,work,1)
                                         call la_qlascl('G',0,0,aaqq,one,m,1,work,lda, &
                                                    ierr)
                                         call la_qlascl('G',0,0,aapp,one,m,1,a(1,p), &
                                                    lda,ierr)
                                         temp1 = -aapq*d(q)/d(p)
                                         call la_qaxpy(m,temp1,work,1,a(1,p),1)

                                         call la_qlascl('G',0,0,one,aapp,m,1,a(1,p), &
                                                    lda,ierr)
                                         sva(p) = aapp*sqrt(max(zero,one - aapq*aapq))
                                         mxsinj = max(mxsinj,sfmin)
                                      end if
                                   end if
                 ! end if rotok then ... else
                 ! in the case of cancellation in updating sva(q)
                 ! .. recompute sva(q)
                                   if ((sva(q)/aaqq)**2 <= rooteps) then
                                      if ((aaqq < rootbig) .and. (aaqq > rootsfmin)) then
                                         sva(q) = la_qnrm2(m,a(1,q),1)*d(q)
                                      else
                                         t = zero
                                         aaqq = one
                                         call la_qlassq(m,a(1,q),1,t,aaqq)
                                         sva(q) = t*sqrt(aaqq)*d(q)
                                      end if
                                   end if
                                   if ((aapp/aapp0)**2 <= rooteps) then
                                      if ((aapp < rootbig) .and. (aapp > rootsfmin)) then
                                         aapp = la_qnrm2(m,a(1,p),1)*d(p)
                                      else
                                         t = zero
                                         aapp = one
                                         call la_qlassq(m,a(1,p),1,t,aapp)
                                         aapp = t*sqrt(aapp)*d(p)
                                      end if
                                      sva(p) = aapp
                                   end if
                    ! end of ok rotation
                                else
                                   notrot = notrot + 1
                 ! skipped  = skipped  + 1
                                   pskipped = pskipped + 1
                                   ijblsk = ijblsk + 1
                                end if
                             else
                                notrot = notrot + 1
                                pskipped = pskipped + 1
                                ijblsk = ijblsk + 1
                             end if
            ! if ( notrot >= emptsw )  go to 2011
                             if ((i <= swband) .and. (ijblsk >= blskip)) then
                                sva(p) = aapp
                                notrot = 0
                                go to 2011
                             end if
                             if ((i <= swband) .and. (pskipped > rowskip)) then
                                aapp = -aapp
                                notrot = 0
                                go to 2203
                             end if
                          end do loop_2200
              ! end of the q-loop
              2203 continue
                          sva(p) = aapp
                       else
                          if (aapp == zero) notrot = notrot + min(jgl + kbl - 1,n) - jgl + 1
                          if (aapp < zero) notrot = 0
      ! **      if ( notrot >= emptsw )  go to 2011
                       end if
                    end do loop_2100
           ! end of the p-loop
                 end do loop_2010
           ! end of the jbc-loop
           2011 continue
      ! 2011 bailed out of the jbc-loop
                 do p = igl,min(igl + kbl - 1,n)
                    sva(p) = abs(sva(p))
                 end do
      ! **   if ( notrot >= emptsw ) go to 1994
              end do loop_2000
      ! 2000 :: end of the ibr-loop
           ! .. update sva(n)
              if ((sva(n) < rootbig) .and. (sva(n) > rootsfmin)) then
                 sva(n) = la_qnrm2(m,a(1,n),1)*d(n)
              else
                 t = zero
                 aapp = one
                 call la_qlassq(m,a(1,n),1,t,aapp)
                 sva(n) = t*sqrt(aapp)*d(n)
              end if
           ! additional steering devices
              if ((i < swband) .and. ((mxaapq <= roottol) .or. (iswrot <= n))) swband = i
              if ((i > swband + 1) .and. (mxaapq < real(n,KIND=qp)*tol) .and. (real(n,KIND=qp) &
                        *mxaapq*mxsinj < tol)) then
                 go to 1994
              end if
              if (notrot >= emptsw) go to 1994
           end do loop_1993
           ! end i=1:nsweep loop
       ! #:) reaching this point means that the procedure has completed the given
           ! number of sweeps.
           info = nsweep - 1
           go to 1995
           1994 continue
       ! #:) reaching this point means that during the i-th sweep all pivots were
           ! below the given threshold, causing early exit.
           info = 0
       ! #:) info = 0 confirms successful iterations.
       1995 continue
           ! sort the vector d
           do p = 1,n - 1
              q = la_iqamax(n - p + 1,sva(p),1) + p - 1
              if (p /= q) then
                 temp1 = sva(p)
                 sva(p) = sva(q)
                 sva(q) = temp1
                 temp1 = d(p)
                 d(p) = d(q)
                 d(q) = temp1
                 call la_qswap(m,a(1,p),1,a(1,q),1)
                 if (rsvec) call la_qswap(mvl,v(1,p),1,v(1,q),1)
              end if
           end do
           return
     end subroutine la_qgsvj1

     !> DHGEQZ: computes the eigenvalues of a real matrix pair (H,T),
     !> where H is an upper Hessenberg matrix and T is upper triangular,
     !> using the double-shift QZ method.
     !> Matrix pairs of this type are produced by the reduction to
     !> generalized upper Hessenberg form of a real matrix pair (A,B):
     !> A = Q1*H*Z1**T,  B = Q1*T*Z1**T,
     !> as computed by DGGHRD.
     !> If JOB='S', then the Hessenberg-triangular pair (H,T) is
     !> also reduced to generalized Schur form,
     !> H = Q*S*Z**T,  T = Q*P*Z**T,
     !> where Q and Z are orthogonal matrices, P is an upper triangular
     !> matrix, and S is a quasi-triangular matrix with 1-by-1 and 2-by-2
     !> diagonal blocks.
     !> The 1-by-1 blocks correspond to real eigenvalues of the matrix pair
     !> (H,T) and the 2-by-2 blocks correspond to complex conjugate pairs of
     !> eigenvalues.
     !> Additionally, the 2-by-2 upper triangular diagonal blocks of P
     !> corresponding to 2-by-2 blocks of S are reduced to positive diagonal
     !> form, i.e., if S(j+1,j) is non-zero, then P(j+1,j) = P(j,j+1) = 0,
     !> P(j,j) > 0, and P(j+1,j+1) > 0.
     !> Optionally, the orthogonal matrix Q from the generalized Schur
     !> factorization may be postmultiplied into an input matrix Q1, and the
     !> orthogonal matrix Z may be postmultiplied into an input matrix Z1.
     !> If Q1 and Z1 are the orthogonal matrices from DGGHRD that reduced
     !> the matrix pair (A,B) to generalized upper Hessenberg form, then the
     !> output matrices Q1*Q and Z1*Z are the orthogonal factors from the
     !> generalized Schur factorization of (A,B):
     !> A = (Q1*Q)*S*(Z1*Z)**T,  B = (Q1*Q)*P*(Z1*Z)**T.
     !> To avoid overflow, eigenvalues of the matrix pair (H,T) (equivalently,
     !> of (A,B)) are computed as a pair of values (alpha,beta), where alpha is
     !> complex and beta real.
     !> If beta is nonzero, lambda = alpha / beta is an eigenvalue of the
     !> generalized nonsymmetric eigenvalue problem (GNEP)
     !> A*x = lambda*B*x
     !> and if alpha is nonzero, mu = beta / alpha is an eigenvalue of the
     !> alternate form of the GNEP
     !> mu*A*y = B*y.
     !> Real eigenvalues can be read directly from the generalized Schur
     !> form:
     !> alpha = S(i,i), beta = P(i,i).
     !> Ref: C.B. Moler
     !> Eigenvalue Problems", SIAM J. Numer. Anal., 10(1973),
     !> pp. 241--256.

     subroutine la_qhgeqz(job,compq,compz,n,ilo,ihi,h,ldh,t,ldt,alphar,alphai, &
               beta,q,ldq,z,ldz,work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: compq,compz,job
           integer(ilp),intent(in) :: ihi,ilo,ldh,ldq,ldt,ldz,lwork,n
           integer(ilp),intent(out) :: info
           ! Array Arguments
           real(qp),intent(out) :: alphai(*),alphar(*),beta(*),work(*)
           real(qp),intent(inout) :: h(ldh,*),q(ldq,*),t(ldt,*),z(ldz,*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: safety = 1.0e+2_qp
          ! $                     safety = one )

           ! Local Scalars
           logical(lk) :: ilazr2,ilazro,ilpivt,ilq,ilschr,ilz,lquery
           integer(ilp) :: icompq,icompz,ifirst,ifrstm,iiter,ilast,ilastm,in,ischur, &
                     istart,j,jc,jch,jiter,jr,maxit
           real(qp) :: a11,a12,a1i,a1r,a21,a22,a2i,a2r,ad11,ad11l,ad12,ad12l,ad21, &
           ad21l,ad22,ad22l,ad32l,an,anorm,ascale,atol,b11,b1a,b1i,b1r,b22,b2a,b2i, &
           b2r,bn,bnorm,bscale,btol,c,c11i,c11r,c12,c21,c22i,c22r,cl,cq,cr,cz, &
           eshift,s,s1,s1inv,s2,safmax,safmin,scale,sl,sqi,sqr,sr,szi,szr,t1,tau, &
           temp,temp2,tempi,tempr,u1,u12,u12l,u2,ulp,vs,w11,w12,w21,w22,wabs,wi, &
                     wr,wr2
           ! Local Arrays
           real(qp) :: v(3)
           ! Intrinsic Functions
           intrinsic :: abs,real,max,min,sqrt
           ! Executable Statements
           ! decode job, compq, compz
           if (la_lsame(job,'E')) then
              ilschr = .false.
              ischur = 1
           else if (la_lsame(job,'S')) then
              ilschr = .true.
              ischur = 2
           else
              ischur = 0
           end if
           if (la_lsame(compq,'N')) then
              ilq = .false.
              icompq = 1
           else if (la_lsame(compq,'V')) then
              ilq = .true.
              icompq = 2
           else if (la_lsame(compq,'I')) then
              ilq = .true.
              icompq = 3
           else
              icompq = 0
           end if
           if (la_lsame(compz,'N')) then
              ilz = .false.
              icompz = 1
           else if (la_lsame(compz,'V')) then
              ilz = .true.
              icompz = 2
           else if (la_lsame(compz,'I')) then
              ilz = .true.
              icompz = 3
           else
              icompz = 0
           end if
           ! check argument values
           info = 0
           work(1) = max(1,n)
           lquery = (lwork == -1)
           if (ischur == 0) then
              info = -1
           else if (icompq == 0) then
              info = -2
           else if (icompz == 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ilo < 1) then
              info = -5
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -6
           else if (ldh < n) then
              info = -8
           else if (ldt < n) then
              info = -10
           else if (ldq < 1 .or. (ilq .and. ldq < n)) then
              info = -15
           else if (ldz < 1 .or. (ilz .and. ldz < n)) then
              info = -17
           else if (lwork < max(1,n) .and. .not. lquery) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('DHGEQZ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = real(1,KIND=qp)
              return
           end if
           ! initialize q and z
           if (icompq == 3) call la_qlaset('FULL',n,n,zero,one,q,ldq)
           if (icompz == 3) call la_qlaset('FULL',n,n,zero,one,z,ldz)
           ! machine constants
           in = ihi + 1 - ilo
           safmin = la_qlamch('S')
           safmax = one/safmin
           ulp = la_qlamch('E')*la_qlamch('B')
           anorm = la_qlanhs('F',in,h(ilo,ilo),ldh,work)
           bnorm = la_qlanhs('F',in,t(ilo,ilo),ldt,work)
           atol = max(safmin,ulp*anorm)
           btol = max(safmin,ulp*bnorm)
           ascale = one/max(safmin,anorm)
           bscale = one/max(safmin,bnorm)
           ! set eigenvalues ihi+1:n
           do j = ihi + 1,n
              if (t(j,j) < zero) then
                 if (ilschr) then
                    do jr = 1,j
                       h(jr,j) = -h(jr,j)
                       t(jr,j) = -t(jr,j)
                    end do
                 else
                    h(j,j) = -h(j,j)
                    t(j,j) = -t(j,j)
                 end if
                 if (ilz) then
                    do jr = 1,n
                       z(jr,j) = -z(jr,j)
                    end do
                 end if
              end if
              alphar(j) = h(j,j)
              alphai(j) = zero
              beta(j) = t(j,j)
           end do
           ! if ihi < ilo, skip qz steps
           if (ihi < ilo) go to 380
           ! main qz iteration loop
           ! initialize dynamic indices
           ! eigenvalues ilast+1:n have been found.
              ! column operations modify rows ifrstm:whatever.
              ! row operations modify columns whatever:ilastm.
           ! if only eigenvalues are being computed, then
              ! ifrstm is the row of the last splitting row above row ilast;
              ! this is always at least ilo.
           ! iiter counts iterations since the last eigenvalue was found,
              ! to tell when to use an extraordinary shift.
           ! maxit is the maximum number of qz sweeps allowed.
           ilast = ihi
           if (ilschr) then
              ifrstm = 1
              ilastm = n
           else
              ifrstm = ilo
              ilastm = ihi
           end if
           iiter = 0
           eshift = zero
           maxit = 30*(ihi - ilo + 1)
           loop_360: do jiter = 1,maxit
              ! split the matrix if possible.
              ! two tests:
                 ! 1: h(j,j-1)=0  or  j=ilo
                 ! 2: t(j,j)=0
              if (ilast == ilo) then
                 ! special case: j=ilast
                 go to 80
              else
                 if (abs(h(ilast,ilast - 1)) <= max(safmin,ulp*(abs(h(ilast,ilast)) + abs( &
                            h(ilast - 1,ilast - 1))))) then
                    h(ilast,ilast - 1) = zero
                    go to 80
                 end if
              end if
              if (abs(t(ilast,ilast)) <= max(safmin,ulp*(abs(t(ilast - 1,ilast)) + abs( &
                        t(ilast - 1,ilast - 1))))) then
                 t(ilast,ilast) = zero
                 go to 70
              end if
              ! general case: j<ilast
              loop_60: do j = ilast - 1,ilo,-1
                 ! test 1: for h(j,j-1)=0 or j=ilo
                 if (j == ilo) then
                    ilazro = .true.
                 else
                    if (abs(h(j,j - 1)) <= max(safmin,ulp*(abs(h(j,j)) + abs(h(j - 1,j - 1 &
                              ))))) then
                       h(j,j - 1) = zero
                       ilazro = .true.
                    else
                       ilazro = .false.
                    end if
                 end if
                 ! test 2: for t(j,j)=0
                 temp = abs(t(j,j + 1))
                 if (j > ilo) temp = temp + abs(t(j - 1,j))
                 if (abs(t(j,j)) < max(safmin,ulp*temp)) then
                    t(j,j) = zero
                    ! test 1a: check for 2 consecutive small subdiagonals in a
                    ilazr2 = .false.
                    if (.not. ilazro) then
                       temp = abs(h(j,j - 1))
                       temp2 = abs(h(j,j))
                       tempr = max(temp,temp2)
                       if (tempr < one .and. tempr /= zero) then
                          temp = temp/tempr
                          temp2 = temp2/tempr
                       end if
                       if (temp*(ascale*abs(h(j + 1,j))) <= temp2*(ascale*atol)) ilazr2 = &
                                 .true.
                    end if
                    ! if both tests pass (1
                    ! element of b in the block is zero, split a 1x1 block off
                    ! at the top. (i.e., at the j-th row/column) the leading
                    ! diagonal element of the remainder can also be zero, so
                    ! this may have to be done repeatedly.
                    if (ilazro .or. ilazr2) then
                       do jch = j,ilast - 1
                          temp = h(jch,jch)
                          call la_qlartg(temp,h(jch + 1,jch),c,s,h(jch,jch))
                          h(jch + 1,jch) = zero
                          call la_qrot(ilastm - jch,h(jch,jch + 1),ldh,h(jch + 1,jch + 1), &
                                    ldh,c,s)
                          call la_qrot(ilastm - jch,t(jch,jch + 1),ldt,t(jch + 1,jch + 1), &
                                    ldt,c,s)
                          if (ilq) call la_qrot(n,q(1,jch),1,q(1,jch + 1),1,c,s)

                          if (ilazr2) h(jch,jch - 1) = h(jch,jch - 1)*c
                          ilazr2 = .false.
                          if (abs(t(jch + 1,jch + 1)) >= btol) then
                             if (jch + 1 >= ilast) then
                                go to 80
                             else
                                ifirst = jch + 1
                                go to 110
                             end if
                          end if
                          t(jch + 1,jch + 1) = zero
                       end do
                       go to 70
                    else
                       ! only test 2 passed -- chase the zero to t(ilast,ilast)
                       ! then process as in the case t(ilast,ilast)=0
                       do jch = j,ilast - 1
                          temp = t(jch,jch + 1)
                          call la_qlartg(temp,t(jch + 1,jch + 1),c,s,t(jch,jch + 1))

                          t(jch + 1,jch + 1) = zero
                          if (jch < ilastm - 1) call la_qrot(ilastm - jch - 1,t(jch,jch + 2),ldt, &
                                    t(jch + 1,jch + 2),ldt,c,s)
                          call la_qrot(ilastm - jch + 2,h(jch,jch - 1),ldh,h(jch + 1,jch - 1), &
                                    ldh,c,s)
                          if (ilq) call la_qrot(n,q(1,jch),1,q(1,jch + 1),1,c,s)

                          temp = h(jch + 1,jch)
                          call la_qlartg(temp,h(jch + 1,jch - 1),c,s,h(jch + 1,jch))

                          h(jch + 1,jch - 1) = zero
                          call la_qrot(jch + 1 - ifrstm,h(ifrstm,jch),1,h(ifrstm,jch - 1), &
                                    1,c,s)
                          call la_qrot(jch - ifrstm,t(ifrstm,jch),1,t(ifrstm,jch - 1),1, &
                                     c,s)
                          if (ilz) call la_qrot(n,z(1,jch),1,z(1,jch - 1),1,c,s)

                       end do
                       go to 70
                    end if
                 else if (ilazro) then
                    ! only test 1 passed -- work on j:ilast
                    ifirst = j
                    go to 110
                 end if
                 ! neither test passed -- try next j
              end do loop_60
              ! (drop-through is "impossible")
              info = n + 1
              go to 420
              ! t(ilast,ilast)=0 -- clear h(ilast,ilast-1) to split off a
              ! 1x1 block.
              70 continue
              temp = h(ilast,ilast)
              call la_qlartg(temp,h(ilast,ilast - 1),c,s,h(ilast,ilast))
              h(ilast,ilast - 1) = zero
              call la_qrot(ilast - ifrstm,h(ifrstm,ilast),1,h(ifrstm,ilast - 1),1,c,s &
                        )
              call la_qrot(ilast - ifrstm,t(ifrstm,ilast),1,t(ifrstm,ilast - 1),1,c,s &
                        )
              if (ilz) call la_qrot(n,z(1,ilast),1,z(1,ilast - 1),1,c,s)
              ! h(ilast,ilast-1)=0 -- standardize b, set alphar, alphai,
                                    ! and beta
                                    80 continue
              if (t(ilast,ilast) < zero) then
                 if (ilschr) then
                    do j = ifrstm,ilast
                       h(j,ilast) = -h(j,ilast)
                       t(j,ilast) = -t(j,ilast)
                    end do
                 else
                    h(ilast,ilast) = -h(ilast,ilast)
                    t(ilast,ilast) = -t(ilast,ilast)
                 end if
                 if (ilz) then
                    do j = 1,n
                       z(j,ilast) = -z(j,ilast)
                    end do
                 end if
              end if
              alphar(ilast) = h(ilast,ilast)
              alphai(ilast) = zero
              beta(ilast) = t(ilast,ilast)
              ! go to next block -- exit if finished.
              ilast = ilast - 1
              if (ilast < ilo) go to 380
              ! reset counters
              iiter = 0
              eshift = zero
              if (.not. ilschr) then
                 ilastm = ilast
                 if (ifrstm > ilast) ifrstm = ilo
              end if
              go to 350
              ! qz step
              ! this iteration only involves rows/columns ifirst:ilast. we
              ! assume ifirst < ilast, and that the diagonal of b is non-zero.
              110 continue
              iiter = iiter + 1
              if (.not. ilschr) then
                 ifrstm = ifirst
              end if
              ! compute single shifts.
              ! at this point, ifirst < ilast, and the diagonal elements of
              ! t(ifirst:ilast,ifirst,ilast) are larger than btol (in
              ! magnitude)
              if ((iiter/10)*10 == iiter) then
                 ! exceptional shift.  chosen for no particularly good reason.
                 ! (single shift only.)
                 if ((real(maxit,KIND=qp)*safmin)*abs(h(ilast,ilast - 1)) < abs(t(ilast - 1, &
                           ilast - 1))) then
                    eshift = h(ilast,ilast - 1)/t(ilast - 1,ilast - 1)
                 else
                    eshift = eshift + one/(safmin*real(maxit,KIND=qp))
                 end if
                 s1 = one
                 wr = eshift
              else
                 ! shifts based on the generalized eigenvalues of the
                 ! bottom-right 2x2 block of a and b. the first eigenvalue
                 ! returned by la_qlag2 is the wilkinson shift (aep p.512_qp),
                 call la_qlag2(h(ilast - 1,ilast - 1),ldh,t(ilast - 1,ilast - 1),ldt, &
                           safmin*safety,s1,s2,wr,wr2,wi)
                 if (abs((wr/s1)*t(ilast,ilast) - h(ilast,ilast)) > abs((wr2/s2)*t( &
                           ilast,ilast) - h(ilast,ilast))) then
                    temp = wr
                    wr = wr2
                    wr2 = temp
                    temp = s1
                    s1 = s2
                    s2 = temp
                 end if
                 temp = max(s1,safmin*max(one,abs(wr),abs(wi)))
                 if (wi /= zero) go to 200
              end if
              ! fiddle with shift to avoid overflow
              temp = min(ascale,one)*(half*safmax)
              if (s1 > temp) then
                 scale = temp/s1
              else
                 scale = one
              end if
              temp = min(bscale,one)*(half*safmax)
              if (abs(wr) > temp) scale = min(scale,temp/abs(wr))
              s1 = scale*s1
              wr = scale*wr
              ! now check for two consecutive small subdiagonals.
              do j = ilast - 1,ifirst + 1,-1
                 istart = j
                 temp = abs(s1*h(j,j - 1))
                 temp2 = abs(s1*h(j,j) - wr*t(j,j))
                 tempr = max(temp,temp2)
                 if (tempr < one .and. tempr /= zero) then
                    temp = temp/tempr
                    temp2 = temp2/tempr
                 end if
                 if (abs((ascale*h(j + 1,j))*temp) <= (ascale*atol)*temp2) go to 130
              end do
              istart = ifirst
              130 continue
              ! do an implicit single-shift qz sweep.
              ! initial q
              temp = s1*h(istart,istart) - wr*t(istart,istart)
              temp2 = s1*h(istart + 1,istart)
              call la_qlartg(temp,temp2,c,s,tempr)
              ! sweep
              loop_190: do j = istart,ilast - 1
                 if (j > istart) then
                    temp = h(j,j - 1)
                    call la_qlartg(temp,h(j + 1,j - 1),c,s,h(j,j - 1))
                    h(j + 1,j - 1) = zero
                 end if
                 do jc = j,ilastm
                    temp = c*h(j,jc) + s*h(j + 1,jc)
                    h(j + 1,jc) = -s*h(j,jc) + c*h(j + 1,jc)
                    h(j,jc) = temp
                    temp2 = c*t(j,jc) + s*t(j + 1,jc)
                    t(j + 1,jc) = -s*t(j,jc) + c*t(j + 1,jc)
                    t(j,jc) = temp2
                 end do
                 if (ilq) then
                    do jr = 1,n
                       temp = c*q(jr,j) + s*q(jr,j + 1)
                       q(jr,j + 1) = -s*q(jr,j) + c*q(jr,j + 1)
                       q(jr,j) = temp
                    end do
                 end if
                 temp = t(j + 1,j + 1)
                 call la_qlartg(temp,t(j + 1,j),c,s,t(j + 1,j + 1))
                 t(j + 1,j) = zero
                 do jr = ifrstm,min(j + 2,ilast)
                    temp = c*h(jr,j + 1) + s*h(jr,j)
                    h(jr,j) = -s*h(jr,j + 1) + c*h(jr,j)
                    h(jr,j + 1) = temp
                 end do
                 do jr = ifrstm,j
                    temp = c*t(jr,j + 1) + s*t(jr,j)
                    t(jr,j) = -s*t(jr,j + 1) + c*t(jr,j)
                    t(jr,j + 1) = temp
                 end do
                 if (ilz) then
                    do jr = 1,n
                       temp = c*z(jr,j + 1) + s*z(jr,j)
                       z(jr,j) = -s*z(jr,j + 1) + c*z(jr,j)
                       z(jr,j + 1) = temp
                    end do
                 end if
              end do loop_190
              go to 350
              ! use francis double-shift
              ! note: the francis double-shift should work with real shifts,
                    ! but only if the block is at least 3x3.
                    ! this code may break if this point is reached with
                    ! a 2x2 block with real eigenvalues.
                    200 continue
              if (ifirst + 1 == ilast) then
                 ! special case -- 2x2 block with complex eigenvectors
                 ! step 1: standardize, that is, rotate so that
                             ! ( b11  0  )
                         ! b = (         )  with b11 non-negative.
                             ! (  0  b22 )
                 call la_qlasv2(t(ilast - 1,ilast - 1),t(ilast - 1,ilast),t(ilast,ilast), &
                            b22,b11,sr,cr,sl,cl)
                 if (b11 < zero) then
                    cr = -cr
                    sr = -sr
                    b11 = -b11
                    b22 = -b22
                 end if
                 call la_qrot(ilastm + 1 - ifirst,h(ilast - 1,ilast - 1),ldh,h(ilast,ilast - 1) &
                           ,ldh,cl,sl)
                 call la_qrot(ilast + 1 - ifrstm,h(ifrstm,ilast - 1),1,h(ifrstm,ilast),1, &
                           cr,sr)
                 if (ilast < ilastm) call la_qrot(ilastm - ilast,t(ilast - 1,ilast + 1),ldt,t( &
                           ilast,ilast + 1),ldt,cl,sl)
                 if (ifrstm < ilast - 1) call la_qrot(ifirst - ifrstm,t(ifrstm,ilast - 1),1,t( &
                           ifrstm,ilast),1,cr,sr)
                 if (ilq) call la_qrot(n,q(1,ilast - 1),1,q(1,ilast),1,cl,sl)

                 if (ilz) call la_qrot(n,z(1,ilast - 1),1,z(1,ilast),1,cr,sr)

                 t(ilast - 1,ilast - 1) = b11
                 t(ilast - 1,ilast) = zero
                 t(ilast,ilast - 1) = zero
                 t(ilast,ilast) = b22
                 ! if b22 is negative, negate column ilast
                 if (b22 < zero) then
                    do j = ifrstm,ilast
                       h(j,ilast) = -h(j,ilast)
                       t(j,ilast) = -t(j,ilast)
                    end do
                    if (ilz) then
                       do j = 1,n
                          z(j,ilast) = -z(j,ilast)
                       end do
                    end if
                    b22 = -b22
                 end if
                 ! step 2: compute alphar, alphai, and beta (see refs.)
                 ! recompute shift
                 call la_qlag2(h(ilast - 1,ilast - 1),ldh,t(ilast - 1,ilast - 1),ldt, &
                           safmin*safety,s1,temp,wr,temp2,wi)
                 ! if standardization has perturbed the shift onto real line,
                 ! do another (real single-shift) qr step.
                 if (wi == zero) go to 350
                 s1inv = one/s1
                 ! do eispack (qzval) computation of alpha and beta
                 a11 = h(ilast - 1,ilast - 1)
                 a21 = h(ilast,ilast - 1)
                 a12 = h(ilast - 1,ilast)
                 a22 = h(ilast,ilast)
                 ! compute complex givens rotation on right
                 ! (assume some element of c = (sa - wb) > unfl )
                                  ! __
                 ! (sa - wb) ( cz   -sz )
                           ! ( sz    cz )
                 c11r = s1*a11 - wr*b11
                 c11i = -wi*b11
                 c12 = s1*a12
                 c21 = s1*a21
                 c22r = s1*a22 - wr*b22
                 c22i = -wi*b22
                 if (abs(c11r) + abs(c11i) + abs(c12) > abs(c21) + abs(c22r) + abs(c22i)) &
                           then
                    t1 = la_qlapy3(c12,c11r,c11i)
                    cz = c12/t1
                    szr = -c11r/t1
                    szi = -c11i/t1
                 else
                    cz = la_qlapy2(c22r,c22i)
                    if (cz <= safmin) then
                       cz = zero
                       szr = one
                       szi = zero
                    else
                       tempr = c22r/cz
                       tempi = c22i/cz
                       t1 = la_qlapy2(cz,c21)
                       cz = cz/t1
                       szr = -c21*tempr/t1
                       szi = c21*tempi/t1
                    end if
                 end if
                 ! compute givens rotation on left
                 ! (  cq   sq )
                 ! (  __      )  a or b
                 ! ( -sq   cq )
                 an = abs(a11) + abs(a12) + abs(a21) + abs(a22)
                 bn = abs(b11) + abs(b22)
                 wabs = abs(wr) + abs(wi)
                 if (s1*an > wabs*bn) then
                    cq = cz*b11
                    sqr = szr*b22
                    sqi = -szi*b22
                 else
                    a1r = cz*a11 + szr*a12
                    a1i = szi*a12
                    a2r = cz*a21 + szr*a22
                    a2i = szi*a22
                    cq = la_qlapy2(a1r,a1i)
                    if (cq <= safmin) then
                       cq = zero
                       sqr = one
                       sqi = zero
                    else
                       tempr = a1r/cq
                       tempi = a1i/cq
                       sqr = tempr*a2r + tempi*a2i
                       sqi = tempi*a2r - tempr*a2i
                    end if
                 end if
                 t1 = la_qlapy3(cq,sqr,sqi)
                 cq = cq/t1
                 sqr = sqr/t1
                 sqi = sqi/t1
                 ! compute diagonal elements of qbz
                 tempr = sqr*szr - sqi*szi
                 tempi = sqr*szi + sqi*szr
                 b1r = cq*cz*b11 + tempr*b22
                 b1i = tempi*b22
                 b1a = la_qlapy2(b1r,b1i)
                 b2r = cq*cz*b22 + tempr*b11
                 b2i = -tempi*b11
                 b2a = la_qlapy2(b2r,b2i)
                 ! normalize so beta > 0, and im( alpha1 ) > 0
                 beta(ilast - 1) = b1a
                 beta(ilast) = b2a
                 alphar(ilast - 1) = (wr*b1a)*s1inv
                 alphai(ilast - 1) = (wi*b1a)*s1inv
                 alphar(ilast) = (wr*b2a)*s1inv
                 alphai(ilast) = -(wi*b2a)*s1inv
                 ! step 3: go to next block -- exit if finished.
                 ilast = ifirst - 1
                 if (ilast < ilo) go to 380
                 ! reset counters
                 iiter = 0
                 eshift = zero
                 if (.not. ilschr) then
                    ilastm = ilast
                    if (ifrstm > ilast) ifrstm = ilo
                 end if
                 go to 350
              else
                 ! usual case: 3x3 or larger block, using francis implicit
                             ! double-shift
                                          ! 2
                 ! eigenvalue equation is  w  - c w + d = 0,
                                               ! -1 2        -1
                 ! so compute 1st column of  (a b  )  - c a b   + d
                 ! using the formula in qzit (from eispack)
                 ! we assume that the block is at least 3x3
                 ad11 = (ascale*h(ilast - 1,ilast - 1))/(bscale*t(ilast - 1,ilast - 1))
                 ad21 = (ascale*h(ilast,ilast - 1))/(bscale*t(ilast - 1,ilast - 1))
                 ad12 = (ascale*h(ilast - 1,ilast))/(bscale*t(ilast,ilast))
                 ad22 = (ascale*h(ilast,ilast))/(bscale*t(ilast,ilast))
                 u12 = t(ilast - 1,ilast)/t(ilast,ilast)
                 ad11l = (ascale*h(ifirst,ifirst))/(bscale*t(ifirst,ifirst))
                 ad21l = (ascale*h(ifirst + 1,ifirst))/(bscale*t(ifirst,ifirst))
                 ad12l = (ascale*h(ifirst,ifirst + 1))/(bscale*t(ifirst + 1,ifirst + 1))

                 ad22l = (ascale*h(ifirst + 1,ifirst + 1))/(bscale*t(ifirst + 1,ifirst + 1))

                 ad32l = (ascale*h(ifirst + 2,ifirst + 1))/(bscale*t(ifirst + 1,ifirst + 1))

                 u12l = t(ifirst,ifirst + 1)/t(ifirst + 1,ifirst + 1)
                 v(1) = (ad11 - ad11l)*(ad22 - ad11l) - ad12*ad21 + ad21*u12*ad11l + (ad12l - &
                           ad11l*u12l)*ad21l
                 v(2) = ((ad22l - ad11l) - ad21l*u12l - (ad11 - ad11l) - (ad22 - ad11l) + ad21*u12) &
                           *ad21l
                 v(3) = ad32l*ad21l
                 istart = ifirst
                 call la_qlarfg(3,v(1),v(2),1,tau)
                 v(1) = one
                 ! sweep
                 loop_290: do j = istart,ilast - 2
                    ! all but last elements: use 3x3 householder transforms.
                    ! zero (j-1)st column of a
                    if (j > istart) then
                       v(1) = h(j,j - 1)
                       v(2) = h(j + 1,j - 1)
                       v(3) = h(j + 2,j - 1)
                       call la_qlarfg(3,h(j,j - 1),v(2),1,tau)
                       v(1) = one
                       h(j + 1,j - 1) = zero
                       h(j + 2,j - 1) = zero
                    end if
                    do jc = j,ilastm
                       temp = tau*(h(j,jc) + v(2)*h(j + 1,jc) + v(3)*h(j + 2,jc))
                       h(j,jc) = h(j,jc) - temp
                       h(j + 1,jc) = h(j + 1,jc) - temp*v(2)
                       h(j + 2,jc) = h(j + 2,jc) - temp*v(3)
                       temp2 = tau*(t(j,jc) + v(2)*t(j + 1,jc) + v(3)*t(j + 2,jc))
                       t(j,jc) = t(j,jc) - temp2
                       t(j + 1,jc) = t(j + 1,jc) - temp2*v(2)
                       t(j + 2,jc) = t(j + 2,jc) - temp2*v(3)
                    end do
                    if (ilq) then
                       do jr = 1,n
                          temp = tau*(q(jr,j) + v(2)*q(jr,j + 1) + v(3)*q(jr,j + 2))

                          q(jr,j) = q(jr,j) - temp
                          q(jr,j + 1) = q(jr,j + 1) - temp*v(2)
                          q(jr,j + 2) = q(jr,j + 2) - temp*v(3)
                       end do
                    end if
                    ! zero j-th column of b (see dlagbc for details)
                    ! swap rows to pivot
                    ilpivt = .false.
                    temp = max(abs(t(j + 1,j + 1)),abs(t(j + 1,j + 2)))
                    temp2 = max(abs(t(j + 2,j + 1)),abs(t(j + 2,j + 2)))
                    if (max(temp,temp2) < safmin) then
                       scale = zero
                       u1 = one
                       u2 = zero
                       go to 250
                    else if (temp >= temp2) then
                       w11 = t(j + 1,j + 1)
                       w21 = t(j + 2,j + 1)
                       w12 = t(j + 1,j + 2)
                       w22 = t(j + 2,j + 2)
                       u1 = t(j + 1,j)
                       u2 = t(j + 2,j)
                    else
                       w21 = t(j + 1,j + 1)
                       w11 = t(j + 2,j + 1)
                       w22 = t(j + 1,j + 2)
                       w12 = t(j + 2,j + 2)
                       u2 = t(j + 1,j)
                       u1 = t(j + 2,j)
                    end if
                    ! swap columns if nec.
                    if (abs(w12) > abs(w11)) then
                       ilpivt = .true.
                       temp = w12
                       temp2 = w22
                       w12 = w11
                       w22 = w21
                       w11 = temp
                       w21 = temp2
                    end if
                    ! lu-factor
                    temp = w21/w11
                    u2 = u2 - temp*u1
                    w22 = w22 - temp*w12
                    w21 = zero
                    ! compute scale
                    scale = one
                    if (abs(w22) < safmin) then
                       scale = zero
                       u2 = one
                       u1 = -w12/w11
                       go to 250
                    end if
                    if (abs(w22) < abs(u2)) scale = abs(w22/u2)
                    if (abs(w11) < abs(u1)) scale = min(scale,abs(w11/u1))
                    ! solve
                    u2 = (scale*u2)/w22
                    u1 = (scale*u1 - w12*u2)/w11
                    250 continue
                    if (ilpivt) then
                       temp = u2
                       u2 = u1
                       u1 = temp
                    end if
                    ! compute householder vector
                    t1 = sqrt(scale**2 + u1**2 + u2**2)
                    tau = one + scale/t1
                    vs = -one/(scale + t1)
                    v(1) = one
                    v(2) = vs*u1
                    v(3) = vs*u2
                    ! apply transformations from the right.
                    do jr = ifrstm,min(j + 3,ilast)
                       temp = tau*(h(jr,j) + v(2)*h(jr,j + 1) + v(3)*h(jr,j + 2))
                       h(jr,j) = h(jr,j) - temp
                       h(jr,j + 1) = h(jr,j + 1) - temp*v(2)
                       h(jr,j + 2) = h(jr,j + 2) - temp*v(3)
                    end do
                    do jr = ifrstm,j + 2
                       temp = tau*(t(jr,j) + v(2)*t(jr,j + 1) + v(3)*t(jr,j + 2))
                       t(jr,j) = t(jr,j) - temp
                       t(jr,j + 1) = t(jr,j + 1) - temp*v(2)
                       t(jr,j + 2) = t(jr,j + 2) - temp*v(3)
                    end do
                    if (ilz) then
                       do jr = 1,n
                          temp = tau*(z(jr,j) + v(2)*z(jr,j + 1) + v(3)*z(jr,j + 2))

                          z(jr,j) = z(jr,j) - temp
                          z(jr,j + 1) = z(jr,j + 1) - temp*v(2)
                          z(jr,j + 2) = z(jr,j + 2) - temp*v(3)
                       end do
                    end if
                    t(j + 1,j) = zero
                    t(j + 2,j) = zero
                 end do loop_290
                 ! last elements: use givens rotations
                 ! rotations from the left
                 j = ilast - 1
                 temp = h(j,j - 1)
                 call la_qlartg(temp,h(j + 1,j - 1),c,s,h(j,j - 1))
                 h(j + 1,j - 1) = zero
                 do jc = j,ilastm
                    temp = c*h(j,jc) + s*h(j + 1,jc)
                    h(j + 1,jc) = -s*h(j,jc) + c*h(j + 1,jc)
                    h(j,jc) = temp
                    temp2 = c*t(j,jc) + s*t(j + 1,jc)
                    t(j + 1,jc) = -s*t(j,jc) + c*t(j + 1,jc)
                    t(j,jc) = temp2
                 end do
                 if (ilq) then
                    do jr = 1,n
                       temp = c*q(jr,j) + s*q(jr,j + 1)
                       q(jr,j + 1) = -s*q(jr,j) + c*q(jr,j + 1)
                       q(jr,j) = temp
                    end do
                 end if
                 ! rotations from the right.
                 temp = t(j + 1,j + 1)
                 call la_qlartg(temp,t(j + 1,j),c,s,t(j + 1,j + 1))
                 t(j + 1,j) = zero
                 do jr = ifrstm,ilast
                    temp = c*h(jr,j + 1) + s*h(jr,j)
                    h(jr,j) = -s*h(jr,j + 1) + c*h(jr,j)
                    h(jr,j + 1) = temp
                 end do
                 do jr = ifrstm,ilast - 1
                    temp = c*t(jr,j + 1) + s*t(jr,j)
                    t(jr,j) = -s*t(jr,j + 1) + c*t(jr,j)
                    t(jr,j + 1) = temp
                 end do
                 if (ilz) then
                    do jr = 1,n
                       temp = c*z(jr,j + 1) + s*z(jr,j)
                       z(jr,j) = -s*z(jr,j + 1) + c*z(jr,j)
                       z(jr,j + 1) = temp
                    end do
                 end if
                 ! end of double-shift code
              end if
              go to 350
              ! end of iteration loop
              350 continue
           end do loop_360
           ! drop-through = non-convergence
           info = ilast
           go to 420
           ! successful completion of all qz steps
           380 continue
           ! set eigenvalues 1:ilo-1
           do j = 1,ilo - 1
              if (t(j,j) < zero) then
                 if (ilschr) then
                    do jr = 1,j
                       h(jr,j) = -h(jr,j)
                       t(jr,j) = -t(jr,j)
                    end do
                 else
                    h(j,j) = -h(j,j)
                    t(j,j) = -t(j,j)
                 end if
                 if (ilz) then
                    do jr = 1,n
                       z(jr,j) = -z(jr,j)
                    end do
                 end if
              end if
              alphar(j) = h(j,j)
              alphai(j) = zero
              beta(j) = t(j,j)
           end do
           ! normal termination
           info = 0
           ! exit (other than argument error) -- return optimal workspace size
           420 continue
           work(1) = real(n,KIND=qp)
           return
     end subroutine la_qhgeqz

     !> DHSEIN: uses inverse iteration to find specified right and/or left
     !> eigenvectors of a real upper Hessenberg matrix H.
     !> The right eigenvector x and the left eigenvector y of the matrix H
     !> corresponding to an eigenvalue w are defined by:
     !> H * x = w * x,     y**h * H = w * y**h
     !> where y**h denotes the conjugate transpose of the vector y.

     subroutine la_qhsein(side,eigsrc,initv,select,n,h,ldh,wr,wi,vl,ldvl,vr,ldvr, &
               mm,m,work,ifaill,ifailr,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: eigsrc,initv,side
           integer(ilp),intent(out) :: info,m
           integer(ilp),intent(in) :: ldh,ldvl,ldvr,mm,n
           ! Array Arguments
           logical(lk),intent(inout) :: select(*)
           integer(ilp),intent(out) :: ifaill(*),ifailr(*)
           real(qp),intent(in) :: h(ldh,*),wi(*)
           real(qp),intent(inout) :: vl(ldvl,*),vr(ldvr,*),wr(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: bothv,fromqr,leftv,noinit,pair,rightv
           integer(ilp) :: i,iinfo,k,kl,kln,kr,ksi,ksr,ldwork
           real(qp) :: bignum,eps3,hnorm,smlnum,ulp,unfl,wki,wkr
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! decode and test the input parameters.
           bothv = la_lsame(side,'B')
           rightv = la_lsame(side,'R') .or. bothv
           leftv = la_lsame(side,'L') .or. bothv
           fromqr = la_lsame(eigsrc,'Q')
           noinit = la_lsame(initv,'N')
           ! set m to the number of columns required to store the selected
           ! eigenvectors, and standardize the array select.
           m = 0
           pair = .false.
           do k = 1,n
              if (pair) then
                 pair = .false.
                 select(k) = .false.
              else
                 if (wi(k) == zero) then
                    if (select(k)) m = m + 1
                 else
                    pair = .true.
                    if (select(k) .or. select(k + 1)) then
                       select(k) = .true.
                       m = m + 2
                    end if
                 end if
              end if
           end do
           info = 0
           if (.not. rightv .and. .not. leftv) then
              info = -1
           else if (.not. fromqr .and. .not. la_lsame(eigsrc,'N')) then
              info = -2
           else if (.not. noinit .and. .not. la_lsame(initv,'U')) then
              info = -3
           else if (n < 0) then
              info = -5
           else if (ldh < max(1,n)) then
              info = -7
           else if (ldvl < 1 .or. (leftv .and. ldvl < n)) then
              info = -11
           else if (ldvr < 1 .or. (rightv .and. ldvr < n)) then
              info = -13
           else if (mm < m) then
              info = -14
           end if
           if (info /= 0) then
              call la_xerbla('DHSEIN',-info)
              return
           end if
           ! quick return if possible.
           if (n == 0) return
           ! set machine-dependent constants.
           unfl = la_qlamch('SAFE MINIMUM')
           ulp = la_qlamch('PRECISION')
           smlnum = unfl*(n/ulp)
           bignum = (one - ulp)/smlnum
           ldwork = n + 1
           kl = 1
           kln = 0
           if (fromqr) then
              kr = 0
           else
              kr = n
           end if
           ksr = 1
           loop_120: do k = 1,n
              if (select(k)) then
                 ! compute eigenvector(s) corresponding to w(k).
                 if (fromqr) then
                    ! if affiliation of eigenvalues is known, check whether
                    ! the matrix splits.
                    ! determine kl and kr such that 1 <= kl <= k <= kr <= n
                    ! and h(kl,kl-1) and h(kr+1,kr) are zero (or kl = 1 or
                    ! kr = n).
                    ! then inverse iteration can be performed with the
                    ! submatrix h(kl:n,kl:n) for a left eigenvector, and with
                    ! the submatrix h(1:kr,1:kr) for a right eigenvector.
                    do i = k,kl + 1,-1
                       if (h(i,i - 1) == zero) go to 30
                    end do
                    30 continue
                    kl = i
                    if (k > kr) then
                       do i = k,n - 1
                          if (h(i + 1,i) == zero) go to 50
                       end do
                       50 continue
                       kr = i
                    end if
                 end if
                 if (kl /= kln) then
                    kln = kl
                    ! compute infinity-norm of submatrix h(kl:kr,kl:kr) if it
                    ! has not ben computed before.
                    hnorm = la_qlanhs('I',kr - kl + 1,h(kl,kl),ldh,work)
                    if (la_qisnan(hnorm)) then
                       info = -6
                       return
                    else if (hnorm > zero) then
                       eps3 = hnorm*ulp
                    else
                       eps3 = smlnum
                    end if
                 end if
                 ! perturb eigenvalue if it is close to any previous
                 ! selected eigenvalues affiliated to the submatrix
                 ! h(kl:kr,kl:kr). close roots are modified by eps3.
                 wkr = wr(k)
                 wki = wi(k)
                 60 continue
                 do i = k - 1,kl,-1
                    if (select(i) .and. abs(wr(i) - wkr) + abs(wi(i) - wki) < eps3) &
                              then
                       wkr = wkr + eps3
                       go to 60
                    end if
                 end do
                 wr(k) = wkr
                 pair = wki /= zero
                 if (pair) then
                    ksi = ksr + 1
                 else
                    ksi = ksr
                 end if
                 if (leftv) then
                    ! compute left eigenvector.
                    call la_qlaein(.false.,noinit,n - kl + 1,h(kl,kl),ldh,wkr,wki,vl( &
                    kl,ksr),vl(kl,ksi),work,ldwork,work(n*n + n + 1),eps3,smlnum,bignum, &
                              iinfo)
                    if (iinfo > 0) then
                       if (pair) then
                          info = info + 2
                       else
                          info = info + 1
                       end if
                       ifaill(ksr) = k
                       ifaill(ksi) = k
                    else
                       ifaill(ksr) = 0
                       ifaill(ksi) = 0
                    end if
                    do i = 1,kl - 1
                       vl(i,ksr) = zero
                    end do
                    if (pair) then
                       do i = 1,kl - 1
                          vl(i,ksi) = zero
                       end do
                    end if
                 end if
                 if (rightv) then
                    ! compute right eigenvector.
                    call la_qlaein(.true.,noinit,kr,h,ldh,wkr,wki,vr(1,ksr),vr(1, &
                              ksi),work,ldwork,work(n*n + n + 1),eps3,smlnum,bignum,iinfo)
                    if (iinfo > 0) then
                       if (pair) then
                          info = info + 2
                       else
                          info = info + 1
                       end if
                       ifailr(ksr) = k
                       ifailr(ksi) = k
                    else
                       ifailr(ksr) = 0
                       ifailr(ksi) = 0
                    end if
                    do i = kr + 1,n
                       vr(i,ksr) = zero
                    end do
                    if (pair) then
                       do i = kr + 1,n
                          vr(i,ksi) = zero
                       end do
                    end if
                 end if
                 if (pair) then
                    ksr = ksr + 2
                 else
                    ksr = ksr + 1
                 end if
              end if
           end do loop_120
           return
     end subroutine la_qhsein

     !> DHSEQR: computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_qhseqr(job,compz,n,ilo,ihi,h,ldh,wr,wi,z,ldz,work,lwork,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ilo,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           character,intent(in) :: compz,job
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(qp),intent(out) :: wi(*),work(*),wr(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: nl = 49
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_qlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== nl allocates some local workspace to help small matrices
           ! .    through a rare la_qlahqr failure.  nl > ntiny = 15 is
           ! .    required and nl <= nmin = la_ilaenv(ispec=12,...) is recom-
           ! .    mended.  (the default value of nmin is 75.)  using nl = 49
           ! .    allows up to six simultaneous shifts and a 16-by-16
           ! .    deflation window.  ====

           ! Local Arrays
           real(qp) :: hl(nl,nl),workl(nl)
           ! Local Scalars
           integer(ilp) :: i,kbot,nmin
           logical(lk) :: initz,lquery,wantt,wantz
           ! Intrinsic Functions
           intrinsic :: real,max,min
           ! Executable Statements
           ! ==== decode and check the input parameters. ====
           wantt = la_lsame(job,'S')
           initz = la_lsame(compz,'I')
           wantz = initz .or. la_lsame(compz,'V')
           work(1) = real(max(1,n),KIND=qp)
           lquery = lwork == -1
           info = 0
           if (.not. la_lsame(job,'E') .and. .not. wantt) then
              info = -1
           else if (.not. la_lsame(compz,'N') .and. .not. wantz) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ilo < 1 .or. ilo > max(1,n)) then
              info = -4
           else if (ihi < min(ilo,n) .or. ihi > n) then
              info = -5
           else if (ldh < max(1,n)) then
              info = -7
           else if (ldz < 1 .or. (wantz .and. ldz < max(1,n))) then
              info = -11
           else if (lwork < max(1,n) .and. .not. lquery) then
              info = -13
           end if
           if (info /= 0) then
              ! ==== quick return in case of invalid argument. ====
              call la_xerbla('DHSEQR',-info)
              return
           else if (n == 0) then
              ! ==== quick return in case n = 0; nothing to do. ====
              return
           else if (lquery) then
              ! ==== quick return in case of a workspace query ====
              call la_qlaqr0(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,ilo,ihi,z,ldz, &
                        work,lwork,info)
              ! ==== ensure reported workspace size is backward-compatible with
              ! .    previous lapack versions. ====
              work(1) = max(real(max(1,n),KIND=qp),work(1))
              return
           else
              ! ==== copy eigenvalues isolated by la_qgebal ====
              do i = 1,ilo - 1
                 wr(i) = h(i,i)
                 wi(i) = zero
              end do
              do i = ihi + 1,n
                 wr(i) = h(i,i)
                 wi(i) = zero
              end do
              ! ==== initialize z, if requested ====
              if (initz) call la_qlaset('A',n,n,zero,one,z,ldz)
              ! ==== quick return if possible ====
              if (ilo == ihi) then
                 wr(ilo) = h(ilo,ilo)
                 wi(ilo) = zero
                 return
              end if
              ! ==== la_qlahqr/la_qlaqr0 crossover point ====
              nmin = la_ilaenv(12,'DHSEQR',job(:1)//compz(:1),n,ilo,ihi,lwork)

              nmin = max(ntiny,nmin)
              ! ==== la_qlaqr0 for big matrices; la_qlahqr for small ones ====
              if (n > nmin) then
                 call la_qlaqr0(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,ilo,ihi,z,ldz, &
                           work,lwork,info)
              else
                 ! ==== small matrix ====
                 call la_qlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,ilo,ihi,z,ldz, &
                           info)
                 if (info > 0) then
                    ! ==== a rare la_qlahqr failure!  la_qlaqr0 sometimes succeeds
                    ! .    when la_qlahqr fails. ====
                    kbot = info
                    if (n >= nl) then
                       ! ==== larger matrices have enough subdiagonal scratch
                       ! .    space to call la_qlaqr0 directly. ====
                       call la_qlaqr0(wantt,wantz,n,ilo,kbot,h,ldh,wr,wi,ilo,ihi,z, &
                                  ldz,work,lwork,info)
                    else
                       ! ==== tiny matrices don't have enough subdiagonal
                       ! .    scratch space to benefit from la_qlaqr0.  hence,
                       ! .    tiny matrices must be copied into a larger
                       ! .    array before calling la_qlaqr0. ====
                       call la_qlacpy('A',n,n,h,ldh,hl,nl)
                       hl(n + 1,n) = zero
                       call la_qlaset('A',nl,nl - n,zero,zero,hl(1,n + 1),nl)
                       call la_qlaqr0(wantt,wantz,nl,ilo,kbot,hl,nl,wr,wi,ilo,ihi, &
                                 z,ldz,workl,nl,info)
                       if (wantt .or. info /= 0) call la_qlacpy('A',n,n,hl,nl,h,ldh)

                    end if
                 end if
              end if
              ! ==== clear out the trash, if necessary. ====
              if ((wantt .or. info /= 0) .and. n > 2) call la_qlaset('L',n - 2,n - 2,zero,zero, &
                         h(3,1),ldh)
              ! ==== ensure reported workspace size is backward-compatible with
              ! .    previous lapack versions. ====
              work(1) = max(real(max(1,n),KIND=qp),work(1))
           end if
     end subroutine la_qhseqr

     !> DLAE2:  computes the eigenvalues of a 2-by-2 symmetric matrix
     !> [  A   B  ]
     !> [  B   C  ].
     !> On return, RT1 is the eigenvalue of larger absolute value, and RT2
     !> is the eigenvalue of smaller absolute value.

     pure subroutine la_qlae2(a,b,c,rt1,rt2)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           real(qp),intent(in) :: a,b,c
           real(qp),intent(out) :: rt1,rt2
       ! =====================================================================

           ! Local Scalars
           real(qp) :: ab,acmn,acmx,adf,df,rt,sm,tb
           ! Intrinsic Functions
           intrinsic :: abs,sqrt
           ! Executable Statements
           ! compute the eigenvalues
           sm = a + c
           df = a - c
           adf = abs(df)
           tb = b + b
           ab = abs(tb)
           if (abs(a) > abs(c)) then
              acmx = a
              acmn = c
           else
              acmx = c
              acmn = a
           end if
           if (adf > ab) then
              rt = adf*sqrt(one + (ab/adf)**2)
           else if (adf < ab) then
              rt = ab*sqrt(one + (adf/ab)**2)
           else
              ! includes case ab=adf=0
              rt = ab*sqrt(two)
           end if
           if (sm < zero) then
              rt1 = half*(sm - rt)
              ! order of execution important.
              ! to get fully accurate smaller eigenvalue,
              ! next line needs to be executed in higher precision.
              rt2 = (acmx/rt1)*acmn - (b/rt1)*b
           else if (sm > zero) then
              rt1 = half*(sm + rt)
              ! order of execution important.
              ! to get fully accurate smaller eigenvalue,
              ! next line needs to be executed in higher precision.
              rt2 = (acmx/rt1)*acmn - (b/rt1)*b
           else
              ! includes case rt1 = rt2 = 0
              rt1 = half*rt
              rt2 = -half*rt
           end if
           return
     end subroutine la_qlae2

     !> DLAEBZ: contains the iteration loops which compute and use the
     !> function N(w), which is the count of eigenvalues of a symmetric
     !> tridiagonal matrix T less than or equal to its argument  w.  It
     !> performs a choice of two types of loops:
     !> IJOB=1, followed by
     !> IJOB=2: It takes as input a list of intervals and returns a list of
     !> sufficiently small intervals whose union contains the same
     !> eigenvalues as the union of the original intervals.
     !> The input intervals are (AB(j,1),AB(j,2)], j=1,...,MINP.
     !> The output interval (AB(j,1),AB(j,2)] will contain
     !> eigenvalues NAB(j,1)+1,...,NAB(j,2), where 1 <= j <= MOUT.
     !> IJOB=3: It performs a binary search in each input interval
     !> (AB(j,1),AB(j,2)] for a point  w(j)  such that
     !> N(w(j))=NVAL(j), and uses  C(j)  as the starting point of
     !> the search.  If such a w(j) is found, then on output
     !> AB(j,1)=AB(j,2)=w.  If no such w(j) is found, then on output
     !> (AB(j,1),AB(j,2)] will be a small interval containing the
     !> point where N(w) jumps through NVAL(j), unless that point
     !> lies outside the initial interval.
     !> Note that the intervals are in all cases half-open intervals,
     !> i.e., of the form  (a,b] , which includes  b  but not  a .
     !> To avoid underflow, the matrix should be scaled so that its largest
     !> element is no greater than  overflow**(1/2) * underflow**(1/4)
     !> in absolute value.  To assure the most accurate computation
     !> of small eigenvalues, the matrix should be scaled to be
     !> not much smaller than that, either.
     !> See W. Kahan "Accurate Eigenvalues of a Symmetric Tridiagonal
     !> Matrix", Report CS41, Computer Science Dept., Stanford
     !> University, July 21, 1966
     !> Note: the arguments are, in general, *not* checked for unreasonable
     !> values.

     pure subroutine la_qlaebz(ijob,nitmax,n,mmax,minp,nbmin,abstol,reltol,pivmin,d, &
               e,e2,nval,ab,c,mout,nab,work,iwork,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ijob,minp,mmax,n,nbmin,nitmax
           integer(ilp),intent(out) :: info,mout
           real(qp),intent(in) :: abstol,pivmin,reltol
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           integer(ilp),intent(inout) :: nab(mmax,*),nval(*)
           real(qp),intent(inout) :: ab(mmax,*),c(*)
           real(qp),intent(in) :: d(*),e(*),e2(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: itmp1,itmp2,j,ji,jit,jp,kf,kfnew,kl,klnew
           real(qp) :: tmp1,tmp2
           ! Intrinsic Functions
           intrinsic :: abs,max,min
           ! Executable Statements
           ! check for errors
           info = 0
           if (ijob < 1 .or. ijob > 3) then
              info = -1
              return
           end if
           ! initialize nab
           if (ijob == 1) then
              ! compute the number of eigenvalues in the initial intervals.
              mout = 0
              do ji = 1,minp
                 do jp = 1,2
                    tmp1 = d(1) - ab(ji,jp)
                    if (abs(tmp1) < pivmin) tmp1 = -pivmin
                    nab(ji,jp) = 0
                    if (tmp1 <= zero) nab(ji,jp) = 1
                    do j = 2,n
                       tmp1 = d(j) - e2(j - 1)/tmp1 - ab(ji,jp)
                       if (abs(tmp1) < pivmin) tmp1 = -pivmin
                       if (tmp1 <= zero) nab(ji,jp) = nab(ji,jp) + 1
                    end do
                 end do
                 mout = mout + nab(ji,2) - nab(ji,1)
              end do
              return
           end if
           ! initialize for loop
           ! kf and kl have the following meaning:
              ! intervals 1,...,kf-1 have converged.
              ! intervals kf,...,kl  still need to be refined.
           kf = 1
           kl = minp
           ! if ijob=2, initialize c.
           ! if ijob=3, use the user-supplied starting point.
           if (ijob == 2) then
              do ji = 1,minp
                 c(ji) = half*(ab(ji,1) + ab(ji,2))
              end do
           end if
           ! iteration loop
           loop_130: do jit = 1,nitmax
              ! loop over intervals
              if (kl - kf + 1 >= nbmin .and. nbmin > 0) then
                 ! begin of parallel version of the loop
                 do ji = kf,kl
                    ! compute n(c), the number of eigenvalues less than c
                    work(ji) = d(1) - c(ji)
                    iwork(ji) = 0
                    if (work(ji) <= pivmin) then
                       iwork(ji) = 1
                       work(ji) = min(work(ji),-pivmin)
                    end if
                    do j = 2,n
                       work(ji) = d(j) - e2(j - 1)/work(ji) - c(ji)
                       if (work(ji) <= pivmin) then
                          iwork(ji) = iwork(ji) + 1
                          work(ji) = min(work(ji),-pivmin)
                       end if
                    end do
                 end do
                 if (ijob <= 2) then
                    ! ijob=2: choose all intervals containing eigenvalues.
                    klnew = kl
                    loop_70: do ji = kf,kl
                       ! insure that n(w) is monotone
                       iwork(ji) = min(nab(ji,2),max(nab(ji,1),iwork(ji)))
                       ! update the queue -- add intervals if both halves
                       ! contain eigenvalues.
                       if (iwork(ji) == nab(ji,2)) then
                          ! no eigenvalue in the upper interval:
                          ! just use the lower interval.
                          ab(ji,2) = c(ji)
                       else if (iwork(ji) == nab(ji,1)) then
                          ! no eigenvalue in the lower interval:
                          ! just use the upper interval.
                          ab(ji,1) = c(ji)
                       else
                          klnew = klnew + 1
                          if (klnew <= mmax) then
                             ! eigenvalue in both intervals -- add upper to
                             ! queue.
                             ab(klnew,2) = ab(ji,2)
                             nab(klnew,2) = nab(ji,2)
                             ab(klnew,1) = c(ji)
                             nab(klnew,1) = iwork(ji)
                             ab(ji,2) = c(ji)
                             nab(ji,2) = iwork(ji)
                          else
                             info = mmax + 1
                          end if
                       end if
                    end do loop_70
                    if (info /= 0) return
                    kl = klnew
                 else
                    ! ijob=3: binary search.  keep only the interval containing
                            ! w   s.t. n(w) = nval
                    do ji = kf,kl
                       if (iwork(ji) <= nval(ji)) then
                          ab(ji,1) = c(ji)
                          nab(ji,1) = iwork(ji)
                       end if
                       if (iwork(ji) >= nval(ji)) then
                          ab(ji,2) = c(ji)
                          nab(ji,2) = iwork(ji)
                       end if
                    end do
                 end if
              else
                 ! end of parallel version of the loop
                 ! begin of serial version of the loop
                 klnew = kl
                 loop_100: do ji = kf,kl
                    ! compute n(w), the number of eigenvalues less than w
                    tmp1 = c(ji)
                    tmp2 = d(1) - tmp1
                    itmp1 = 0
                    if (tmp2 <= pivmin) then
                       itmp1 = 1
                       tmp2 = min(tmp2,-pivmin)
                    end if
                    do j = 2,n
                       tmp2 = d(j) - e2(j - 1)/tmp2 - tmp1
                       if (tmp2 <= pivmin) then
                          itmp1 = itmp1 + 1
                          tmp2 = min(tmp2,-pivmin)
                       end if
                    end do
                    if (ijob <= 2) then
                       ! ijob=2: choose all intervals containing eigenvalues.
                       ! insure that n(w) is monotone
                       itmp1 = min(nab(ji,2),max(nab(ji,1),itmp1))
                       ! update the queue -- add intervals if both halves
                       ! contain eigenvalues.
                       if (itmp1 == nab(ji,2)) then
                          ! no eigenvalue in the upper interval:
                          ! just use the lower interval.
                          ab(ji,2) = tmp1
                       else if (itmp1 == nab(ji,1)) then
                          ! no eigenvalue in the lower interval:
                          ! just use the upper interval.
                          ab(ji,1) = tmp1
                       else if (klnew < mmax) then
                          ! eigenvalue in both intervals -- add upper to queue.
                          klnew = klnew + 1
                          ab(klnew,2) = ab(ji,2)
                          nab(klnew,2) = nab(ji,2)
                          ab(klnew,1) = tmp1
                          nab(klnew,1) = itmp1
                          ab(ji,2) = tmp1
                          nab(ji,2) = itmp1
                       else
                          info = mmax + 1
                          return
                       end if
                    else
                       ! ijob=3: binary search.  keep only the interval
                               ! containing  w  s.t. n(w) = nval
                       if (itmp1 <= nval(ji)) then
                          ab(ji,1) = tmp1
                          nab(ji,1) = itmp1
                       end if
                       if (itmp1 >= nval(ji)) then
                          ab(ji,2) = tmp1
                          nab(ji,2) = itmp1
                       end if
                    end if
                 end do loop_100
                 kl = klnew
              end if
              ! check for convergence
              kfnew = kf
              loop_110: do ji = kf,kl
                 tmp1 = abs(ab(ji,2) - ab(ji,1))
                 tmp2 = max(abs(ab(ji,2)),abs(ab(ji,1)))
                 if (tmp1 < max(abstol,pivmin,reltol*tmp2) .or. nab(ji,1) >= nab(ji,2)) &
                           then
                    ! converged -- swap with position kfnew,
                                 ! then increment kfnew
                    if (ji > kfnew) then
                       tmp1 = ab(ji,1)
                       tmp2 = ab(ji,2)
                       itmp1 = nab(ji,1)
                       itmp2 = nab(ji,2)
                       ab(ji,1) = ab(kfnew,1)
                       ab(ji,2) = ab(kfnew,2)
                       nab(ji,1) = nab(kfnew,1)
                       nab(ji,2) = nab(kfnew,2)
                       ab(kfnew,1) = tmp1
                       ab(kfnew,2) = tmp2
                       nab(kfnew,1) = itmp1
                       nab(kfnew,2) = itmp2
                       if (ijob == 3) then
                          itmp1 = nval(ji)
                          nval(ji) = nval(kfnew)
                          nval(kfnew) = itmp1
                       end if
                    end if
                    kfnew = kfnew + 1
                 end if
              end do loop_110
              kf = kfnew
              ! choose midpoints
              do ji = kf,kl
                 c(ji) = half*(ab(ji,1) + ab(ji,2))
              end do
              ! if no more intervals to refine, quit.
              if (kf > kl) go to 140
           end do loop_130
           ! converged
           140 continue
           info = max(kl + 1 - kf,0)
           mout = kl
           return
     end subroutine la_qlaebz

     !> DLAED0: computes all eigenvalues and corresponding eigenvectors of a
     !> symmetric tridiagonal matrix using the divide and conquer method.

     pure subroutine la_qlaed0(icompq,qsiz,n,d,e,q,ldq,qstore,ldqs,work,iwork,info &
               )
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: icompq,ldq,ldqs,n,qsiz
           integer(ilp),intent(out) :: info
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: d(*),e(*),q(ldq,*)
           real(qp),intent(out) :: qstore(ldqs,*),work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: curlvl,curprb,curr,i,igivcl,igivnm,igivpt,indxq,iperm,iprmpt, &
           iq,iqptr,iwrem,j,k,lgn,matsiz,msd2,smlsiz,smm1,spm1,spm2,submat,subpbs, &
                     tlvls
           real(qp) :: temp
           ! Intrinsic Functions
           intrinsic :: abs,real,int,log,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (icompq < 0 .or. icompq > 2) then
              info = -1
           else if ((icompq == 1) .and. (qsiz < max(0,n))) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ldq < max(1,n)) then
              info = -7
           else if (ldqs < max(1,n)) then
              info = -9
           end if
           if (info /= 0) then
              call la_xerbla('DLAED0',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           smlsiz = la_ilaenv(9,'DLAED0',' ',0,0,0,0)
           ! determine the size and placement of the submatrices, and save in
           ! the leading elements of iwork.
           iwork(1) = n
           subpbs = 1
           tlvls = 0
           10 continue
           if (iwork(subpbs) > smlsiz) then
              do j = subpbs,1,-1
                 iwork(2*j) = (iwork(j) + 1)/2
                 iwork(2*j - 1) = iwork(j)/2
              end do
              tlvls = tlvls + 1
              subpbs = 2*subpbs
              go to 10
           end if
           do j = 2,subpbs
              iwork(j) = iwork(j) + iwork(j - 1)
           end do
           ! divide the matrix into subpbs submatrices of size at most smlsiz+1
           ! using rank-1 modifications (cuts).
           spm1 = subpbs - 1
           do i = 1,spm1
              submat = iwork(i) + 1
              smm1 = submat - 1
              d(smm1) = d(smm1) - abs(e(smm1))
              d(submat) = d(submat) - abs(e(smm1))
           end do
           indxq = 4*n + 3
           if (icompq /= 2) then
              ! set up workspaces for eigenvalues only/accumulate new vectors
              ! routine
              temp = log(real(n,KIND=qp))/log(two)
              lgn = int(temp,KIND=ilp)
              if (2**lgn < n) lgn = lgn + 1
              if (2**lgn < n) lgn = lgn + 1
              iprmpt = indxq + n + 1
              iperm = iprmpt + n*lgn
              iqptr = iperm + n*lgn
              igivpt = iqptr + n + 2
              igivcl = igivpt + n*lgn
              igivnm = 1
              iq = igivnm + 2*n*lgn
              iwrem = iq + n**2 + 1
              ! initialize pointers
              do i = 0,subpbs
                 iwork(iprmpt + i) = 1
                 iwork(igivpt + i) = 1
              end do
              iwork(iqptr) = 1
           end if
           ! solve each submatrix eigenproblem at the bottom of the divide and
           ! conquer tree.
           curr = 0
           loop_70: do i = 0,spm1
              if (i == 0) then
                 submat = 1
                 matsiz = iwork(1)
              else
                 submat = iwork(i) + 1
                 matsiz = iwork(i + 1) - iwork(i)
              end if
              if (icompq == 2) then
                 call la_qsteqr('I',matsiz,d(submat),e(submat),q(submat,submat), &
                           ldq,work,info)
                 if (info /= 0) go to 130
              else
                 call la_qsteqr('I',matsiz,d(submat),e(submat),work(iq - 1 + iwork( &
                           iqptr + curr)),matsiz,work,info)
                 if (info /= 0) go to 130
                 if (icompq == 1) then
                    call la_qgemm('N','N',qsiz,matsiz,matsiz,one,q(1,submat),ldq, &
                    work(iq - 1 + iwork(iqptr + curr)),matsiz,zero,qstore(1,submat),ldqs)

                 end if
                 iwork(iqptr + curr + 1) = iwork(iqptr + curr) + matsiz**2
                 curr = curr + 1
              end if
              k = 1
              do j = submat,iwork(i + 1)
                 iwork(indxq + j) = k
                 k = k + 1
              end do
           end do loop_70
           ! successively merge eigensystems of adjacent submatrices
           ! into eigensystem for the corresponding larger matrix.
           ! while ( subpbs > 1 )
           curlvl = 1
           80 continue
           if (subpbs > 1) then
              spm2 = subpbs - 2
              loop_90: do i = 0,spm2,2
                 if (i == 0) then
                    submat = 1
                    matsiz = iwork(2)
                    msd2 = iwork(1)
                    curprb = 0
                 else
                    submat = iwork(i) + 1
                    matsiz = iwork(i + 2) - iwork(i)
                    msd2 = matsiz/2
                    curprb = curprb + 1
                 end if
           ! merge lower order eigensystems (of size msd2 and matsiz - msd2)
           ! into an eigensystem of size matsiz.
           ! la_qlaed1 is used only for the full eigensystem of a tridiagonal
           ! matrix.
           ! la_qlaed7 handles the cases in which eigenvalues only or eigenvalues
           ! and eigenvectors of a full symmetric matrix (which was reduced to
           ! tridiagonal form) are desired.
                 if (icompq == 2) then
                    call la_qlaed1(matsiz,d(submat),q(submat,submat),ldq,iwork( &
                    indxq + submat),e(submat + msd2 - 1),msd2,work,iwork(subpbs + 1),info)

                 else
                    call la_qlaed7(icompq,matsiz,qsiz,tlvls,curlvl,curprb,d(submat), &
                    qstore(1,submat),ldqs,iwork(indxq + submat),e(submat + msd2 - 1),msd2, &
                    work(iq),iwork(iqptr),iwork(iprmpt),iwork(iperm),iwork(igivpt), &
                    iwork(igivcl),work(igivnm),work(iwrem),iwork(subpbs + 1),info)

                 end if
                 if (info /= 0) go to 130
                 iwork(i/2 + 1) = iwork(i + 2)
              end do loop_90
              subpbs = subpbs/2
              curlvl = curlvl + 1
              go to 80
           end if
           ! end while
           ! re-merge the eigenvalues/vectors which were deflated at the final
           ! merge step.
           if (icompq == 1) then
              do i = 1,n
                 j = iwork(indxq + i)
                 work(i) = d(j)
                 call la_qcopy(qsiz,qstore(1,j),1,q(1,i),1)
              end do
              call la_qcopy(n,work,1,d,1)
           else if (icompq == 2) then
              do i = 1,n
                 j = iwork(indxq + i)
                 work(i) = d(j)
                 call la_qcopy(n,q(1,j),1,work(n*i + 1),1)
              end do
              call la_qcopy(n,work,1,d,1)
              call la_qlacpy('A',n,n,work(n + 1),n,q,ldq)
           else
              do i = 1,n
                 j = iwork(indxq + i)
                 work(i) = d(j)
              end do
              call la_qcopy(n,work,1,d,1)
           end if
           go to 140
           130 continue
           info = submat*(n + 1) + submat + matsiz - 1
           140 continue
           return
     end subroutine la_qlaed0

     !> DLAED1: computes the updated eigensystem of a diagonal
     !> matrix after modification by a rank-one symmetric matrix.  This
     !> routine is used only for the eigenproblem which requires all
     !> eigenvalues and eigenvectors of a tridiagonal matrix.  DLAED7 handles
     !> the case in which eigenvalues only or eigenvalues and eigenvectors
     !> of a full symmetric matrix (which was reduced to tridiagonal form)
     !> are desired.
     !> T = Q(in) ( D(in) + RHO * Z*Z**T ) Q**T(in) = Q(out) * D(out) * Q**T(out)
     !> where Z = Q**T*u, u is a vector of length N with ones in the
     !> CUTPNT and CUTPNT + 1 th elements and zeros elsewhere.
     !> The eigenvectors of the original matrix are stored in Q, and the
     !> eigenvalues are in D.  The algorithm consists of three stages:
     !> The first stage consists of deflating the size of the problem
     !> when there are multiple eigenvalues or if there is a zero in
     !> the Z vector.  For each such occurrence the dimension of the
     !> secular equation problem is reduced by one.  This stage is
     !> performed by the routine DLAED2.
     !> The second stage consists of calculating the updated
     !> eigenvalues. This is done by finding the roots of the secular
     !> equation via the routine DLAED4 (as called by DLAED3).
     !> This routine also calculates the eigenvectors of the current
     !> problem.
     !> The final stage consists of computing the updated eigenvectors
     !> directly using the updated eigenvalues.  The eigenvectors for
     !> the current problem are multiplied with the eigenvectors from
     !> the overall problem.

     pure subroutine la_qlaed1(n,d,q,ldq,indxq,rho,cutpnt,work,iwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: cutpnt,ldq,n
           integer(ilp),intent(out) :: info
           real(qp),intent(inout) :: rho
           ! Array Arguments
           integer(ilp),intent(inout) :: indxq(*)
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: d(*),q(ldq,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================
           ! Local Scalars
           integer(ilp) :: coltyp,i,idlmda,indx,indxc,indxp,iq2,is,iw,iz,k,n1,n2, &
                     zpp1
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (n < 0) then
              info = -1
           else if (ldq < max(1,n)) then
              info = -4
           else if (min(1,n/2) > cutpnt .or. (n/2) < cutpnt) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('DLAED1',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! the following values are integer pointers which indicate
           ! the portion of the workspace
           ! used by a particular array in la_qlaed2 and la_qlaed3.
           iz = 1
           idlmda = iz + n
           iw = idlmda + n
           iq2 = iw + n
           indx = 1
           indxc = indx + n
           coltyp = indxc + n
           indxp = coltyp + n
           ! form the z-vector which consists of the last row of q_1 and the
           ! first row of q_2.
           call la_qcopy(cutpnt,q(cutpnt,1),ldq,work(iz),1)
           zpp1 = cutpnt + 1
           call la_qcopy(n - cutpnt,q(zpp1,zpp1),ldq,work(iz + cutpnt),1)
           ! deflate eigenvalues.
           call la_qlaed2(k,n,cutpnt,d,q,ldq,indxq,rho,work(iz),work(idlmda), &
           work(iw),work(iq2),iwork(indx),iwork(indxc),iwork(indxp),iwork(coltyp), &
                     info)
           if (info /= 0) go to 20
           ! solve secular equation.
           if (k /= 0) then
              is = (iwork(coltyp) + iwork(coltyp + 1))*cutpnt + (iwork(coltyp + 1) + iwork( &
                        coltyp + 2))*(n - cutpnt) + iq2
              call la_qlaed3(k,n,cutpnt,d,q,ldq,rho,work(idlmda),work(iq2),iwork( &
                         indxc),iwork(coltyp),work(iw),work(is),info)
              if (info /= 0) go to 20
           ! prepare the indxq sorting permutation.
              n1 = k
              n2 = n - k
              call la_qlamrg(n1,n2,d,1,-1,indxq)
           else
              do i = 1,n
                 indxq(i) = i
              end do
           end if
           20 continue
           return
     end subroutine la_qlaed1

     !> DLAED2: merges the two sets of eigenvalues together into a single
     !> sorted set.  Then it tries to deflate the size of the problem.
     !> There are two ways in which deflation can occur:  when two or more
     !> eigenvalues are close together or if there is a tiny entry in the
     !> Z vector.  For each such occurrence the order of the related secular
     !> equation problem is reduced by one.

     pure subroutine la_qlaed2(k,n,n1,d,q,ldq,indxq,rho,z,dlamda,w,q2,indx,indxc, &
                indxp,coltyp,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info,k
           integer(ilp),intent(in) :: ldq,n,n1
           real(qp),intent(inout) :: rho
           ! Array Arguments
           integer(ilp),intent(out) :: coltyp(*),indx(*),indxc(*),indxp(*)
           integer(ilp),intent(inout) :: indxq(*)
           real(qp),intent(inout) :: d(*),q(ldq,*),z(*)
           real(qp),intent(out) :: dlamda(*),q2(*),w(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: mone = -1.0_qp

           ! Local Arrays
           integer(ilp) :: ctot(4),psm(4)
           ! Local Scalars
           integer(ilp) :: ct,i,imax,iq1,iq2,j,jmax,js,k2,n1p1,n2,nj,pj
           real(qp) :: c,eps,s,t,tau,tol
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (n < 0) then
              info = -2
           else if (ldq < max(1,n)) then
              info = -6
           else if (min(1, (n/2)) > n1 .or. (n/2) < n1) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('DLAED2',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           n2 = n - n1
           n1p1 = n1 + 1
           if (rho < zero) then
              call la_qscal(n2,mone,z(n1p1),1)
           end if
           ! normalize z so that norm(z) = 1.  since z is the concatenation of
           ! two normalized vectors, norm2(z) = sqrt(2).
           t = one/sqrt(two)
           call la_qscal(n,t,z,1)
           ! rho = abs( norm(z)**2 * rho )
           rho = abs(two*rho)
           ! sort the eigenvalues into increasing order
           do i = n1p1,n
              indxq(i) = indxq(i) + n1
           end do
           ! re-integrate the deflated parts from the last pass
           do i = 1,n
              dlamda(i) = d(indxq(i))
           end do
           call la_qlamrg(n1,n2,dlamda,1,1,indxc)
           do i = 1,n
              indx(i) = indxq(indxc(i))
           end do
           ! calculate the allowable deflation tolerance
           imax = la_iqamax(n,z,1)
           jmax = la_iqamax(n,d,1)
           eps = la_qlamch('EPSILON')
           tol = eight*eps*max(abs(d(jmax)),abs(z(imax)))
           ! if the rank-1 modifier is small enough, no more needs to be done
           ! except to reorganize q so that its columns correspond with the
           ! elements in d.
           if (rho*abs(z(imax)) <= tol) then
              k = 0
              iq2 = 1
              do j = 1,n
                 i = indx(j)
                 call la_qcopy(n,q(1,i),1,q2(iq2),1)
                 dlamda(j) = d(i)
                 iq2 = iq2 + n
              end do
              call la_qlacpy('A',n,n,q2,n,q,ldq)
              call la_qcopy(n,dlamda,1,d,1)
              go to 190
           end if
           ! if there are multiple eigenvalues then the problem deflates.  here
           ! the number of equal eigenvalues are found.  as each equal
           ! eigenvalue is found, an elementary reflector is computed to rotate
           ! the corresponding eigensubspace so that the corresponding
           ! components of z are zero in this new basis.
           do i = 1,n1
              coltyp(i) = 1
           end do
           do i = n1p1,n
              coltyp(i) = 3
           end do
           k = 0
           k2 = n + 1
           do j = 1,n
              nj = indx(j)
              if (rho*abs(z(nj)) <= tol) then
                 ! deflate due to small z component.
                 k2 = k2 - 1
                 coltyp(nj) = 4
                 indxp(k2) = nj
                 if (j == n) go to 100
              else
                 pj = nj
                 go to 80
              end if
           end do
           80 continue
           j = j + 1
           nj = indx(j)
           if (j > n) go to 100
           if (rho*abs(z(nj)) <= tol) then
              ! deflate due to small z component.
              k2 = k2 - 1
              coltyp(nj) = 4
              indxp(k2) = nj
           else
              ! check if eigenvalues are close enough to allow deflation.
              s = z(pj)
              c = z(nj)
              ! find sqrt(a**2+b**2) without overflow or
              ! destructive underflow.
              tau = la_qlapy2(c,s)
              t = d(nj) - d(pj)
              c = c/tau
              s = -s/tau
              if (abs(t*c*s) <= tol) then
                 ! deflation is possible.
                 z(nj) = tau
                 z(pj) = zero
                 if (coltyp(nj) /= coltyp(pj)) coltyp(nj) = 2
                 coltyp(pj) = 4
                 call la_qrot(n,q(1,pj),1,q(1,nj),1,c,s)
                 t = d(pj)*c**2 + d(nj)*s**2
                 d(nj) = d(pj)*s**2 + d(nj)*c**2
                 d(pj) = t
                 k2 = k2 - 1
                 i = 1
                 90 continue
                 if (k2 + i <= n) then
                    if (d(pj) < d(indxp(k2 + i))) then
                       indxp(k2 + i - 1) = indxp(k2 + i)
                       indxp(k2 + i) = pj
                       i = i + 1
                       go to 90
                    else
                       indxp(k2 + i - 1) = pj
                    end if
                 else
                    indxp(k2 + i - 1) = pj
                 end if
                 pj = nj
              else
                 k = k + 1
                 dlamda(k) = d(pj)
                 w(k) = z(pj)
                 indxp(k) = pj
                 pj = nj
              end if
           end if
           go to 80
           100 continue
           ! record the last eigenvalue.
           k = k + 1
           dlamda(k) = d(pj)
           w(k) = z(pj)
           indxp(k) = pj
           ! count up the total number of the various types of columns, then
           ! form a permutation which positions the four column types into
           ! four uniform groups (although one or more of these groups may be
           ! empty).
           do j = 1,4
              ctot(j) = 0
           end do
           do j = 1,n
              ct = coltyp(j)
              ctot(ct) = ctot(ct) + 1
           end do
           ! psm(*) = position in submatrix (of types 1 through 4)
           psm(1) = 1
           psm(2) = 1 + ctot(1)
           psm(3) = psm(2) + ctot(2)
           psm(4) = psm(3) + ctot(3)
           k = n - ctot(4)
           ! fill out the indxc array so that the permutation which it induces
           ! will place all type-1 columns first, all type-2 columns next,
           ! then all type-3's, and finally all type-4's.
           do j = 1,n
              js = indxp(j)
              ct = coltyp(js)
              indx(psm(ct)) = js
              indxc(psm(ct)) = j
              psm(ct) = psm(ct) + 1
           end do
           ! sort the eigenvalues and corresponding eigenvectors into dlamda
           ! and q2 respectively.  the eigenvalues/vectors which were not
           ! deflated go into the first k slots of dlamda and q2 respectively,
           ! while those which were deflated go into the last n - k slots.
           i = 1
           iq1 = 1
           iq2 = 1 + (ctot(1) + ctot(2))*n1
           do j = 1,ctot(1)
              js = indx(i)
              call la_qcopy(n1,q(1,js),1,q2(iq1),1)
              z(i) = d(js)
              i = i + 1
              iq1 = iq1 + n1
           end do
           do j = 1,ctot(2)
              js = indx(i)
              call la_qcopy(n1,q(1,js),1,q2(iq1),1)
              call la_qcopy(n2,q(n1 + 1,js),1,q2(iq2),1)
              z(i) = d(js)
              i = i + 1
              iq1 = iq1 + n1
              iq2 = iq2 + n2
           end do
           do j = 1,ctot(3)
              js = indx(i)
              call la_qcopy(n2,q(n1 + 1,js),1,q2(iq2),1)
              z(i) = d(js)
              i = i + 1
              iq2 = iq2 + n2
           end do
           iq1 = iq2
           do j = 1,ctot(4)
              js = indx(i)
              call la_qcopy(n,q(1,js),1,q2(iq2),1)
              iq2 = iq2 + n
              z(i) = d(js)
              i = i + 1
           end do
           ! the deflated eigenvalues and their corresponding vectors go back
           ! into the last n - k slots of d and q respectively.
           if (k < n) then
              call la_qlacpy('A',n,ctot(4),q2(iq1),n,q(1,k + 1),ldq)
              call la_qcopy(n - k,z(k + 1),1,d(k + 1),1)
           end if
           ! copy ctot into coltyp for referencing in la_qlaed3.
           do j = 1,4
              coltyp(j) = ctot(j)
           end do
           190 continue
           return
     end subroutine la_qlaed2

     !> DLAED3: finds the roots of the secular equation, as defined by the
     !> values in D, W, and RHO, between 1 and K.  It makes the
     !> appropriate calls to DLAED4 and then updates the eigenvectors by
     !> multiplying the matrix of eigenvectors of the pair of eigensystems
     !> being combined by the matrix of eigenvectors of the K-by-K system
     !> which is solved here.
     !> This code makes very mild assumptions about floating point
     !> arithmetic. It will work on machines with a guard digit in
     !> add/subtract, or on those binary machines without guard digits
     !> which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or Cray-2.
     !> It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.

     pure subroutine la_qlaed3(k,n,n1,d,q,ldq,rho,dlamda,q2,indx,ctot,w,s,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,ldq,n,n1
           real(qp),intent(in) :: rho
           ! Array Arguments
           integer(ilp),intent(in) :: ctot(*),indx(*)
           real(qp),intent(out) :: d(*),q(ldq,*),s(*)
           real(qp),intent(inout) :: dlamda(*),w(*)
           real(qp),intent(in) :: q2(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,ii,iq2,j,n12,n2,n23
           real(qp) :: temp
           ! Intrinsic Functions
           intrinsic :: max,sign,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (k < 0) then
              info = -1
           else if (n < k) then
              info = -2
           else if (ldq < max(1,n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('DLAED3',-info)
              return
           end if
           ! quick return if possible
           if (k == 0) return
           ! modify values dlamda(i) to make sure all dlamda(i)-dlamda(j) can
           ! be computed with high relative accuracy (barring over/underflow).
           ! this is a problem on machines without a guard digit in
           ! add/subtract (cray xmp, cray ymp, cray c 90 and cray 2).
           ! the following code replaces dlamda(i) by 2*dlamda(i)-dlamda(i),
           ! which on any of these machines zeros out the bottommost
           ! bit of dlamda(i) if it is 1; this makes the subsequent
           ! subtractions dlamda(i)-dlamda(j) unproblematic when cancellation
           ! occurs. on binary machines with a guard digit (almost all
           ! machines) it does not change dlamda(i) at all. on hexadecimal
           ! and decimal machines with a guard digit, it slightly
           ! changes the bottommost bits of dlamda(i). it does not account
           ! for hexadecimal or decimal machines without guard digits
           ! (we know of none). we use a subroutine call to compute
           ! 2*dlambda(i) to prevent optimizing compilers from eliminating
           ! this code.
           do i = 1,k
              dlamda(i) = la_qlamc3(dlamda(i),dlamda(i)) - dlamda(i)
           end do
           do j = 1,k
              call la_qlaed4(k,j,dlamda,w,q(1,j),rho,d(j),info)
              ! if the zero finder fails, the computation is terminated.
              if (info /= 0) go to 120
           end do
           if (k == 1) go to 110
           if (k == 2) then
              do j = 1,k
                 w(1) = q(1,j)
                 w(2) = q(2,j)
                 ii = indx(1)
                 q(1,j) = w(ii)
                 ii = indx(2)
                 q(2,j) = w(ii)
              end do
              go to 110
           end if
           ! compute updated w.
           call la_qcopy(k,w,1,s,1)
           ! initialize w(i) = q(i,i)
           call la_qcopy(k,q,ldq + 1,w,1)
           do j = 1,k
              do i = 1,j - 1
                 w(i) = w(i)*(q(i,j)/(dlamda(i) - dlamda(j)))
              end do
              do i = j + 1,k
                 w(i) = w(i)*(q(i,j)/(dlamda(i) - dlamda(j)))
              end do
           end do
           do i = 1,k
              w(i) = sign(sqrt(-w(i)),s(i))
           end do
           ! compute eigenvectors of the modified rank-1 modification.
           do j = 1,k
              do i = 1,k
                 s(i) = w(i)/q(i,j)
              end do
              temp = la_qnrm2(k,s,1)
              do i = 1,k
                 ii = indx(i)
                 q(i,j) = s(ii)/temp
              end do
           end do
           ! compute the updated eigenvectors.
           110 continue
           n2 = n - n1
           n12 = ctot(1) + ctot(2)
           n23 = ctot(2) + ctot(3)
           call la_qlacpy('A',n23,k,q(ctot(1) + 1,1),ldq,s,n23)
           iq2 = n1*n12 + 1
           if (n23 /= 0) then
              call la_qgemm('N','N',n2,k,n23,one,q2(iq2),n2,s,n23,zero,q(n1 + 1, &
                        1),ldq)
           else
              call la_qlaset('A',n2,k,zero,zero,q(n1 + 1,1),ldq)
           end if
           call la_qlacpy('A',n12,k,q,ldq,s,n12)
           if (n12 /= 0) then
              call la_qgemm('N','N',n1,k,n12,one,q2,n1,s,n12,zero,q,ldq)
           else
              call la_qlaset('A',n1,k,zero,zero,q(1,1),ldq)
           end if
           120 continue
           return
     end subroutine la_qlaed3

     !> This subroutine computes the I-th updated eigenvalue of a symmetric
     !> rank-one modification to a diagonal matrix whose elements are
     !> given in the array d, and that
     !> D(i) < D(j)  for  i < j
     !> and that RHO > 0.  This is arranged by the calling routine, and is
     !> no loss in generality.  The rank-one modified system is thus
     !> diag( D )  +  RHO * Z * Z_transpose.
     !> where we assume the Euclidean norm of Z is 1.
     !> The method consists of approximating the rational functions in the
     !> secular equation by simpler interpolating rational functions.

     pure subroutine la_qlaed4(n,i,d,z,delta,rho,dlam,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: i,n
           integer(ilp),intent(out) :: info
           real(qp),intent(out) :: dlam
           real(qp),intent(in) :: rho
           ! Array Arguments
           real(qp),intent(in) :: d(*),z(*)
           real(qp),intent(out) :: delta(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: maxit = 30

           ! Local Scalars
           logical(lk) :: orgati,swtch,swtch3
           integer(ilp) :: ii,iim1,iip1,ip1,iter,j,niter
           real(qp) :: a,b,c,del,dltlb,dltub,dphi,dpsi,dw,eps,erretm,eta,midpt,phi, &
                     prew,psi,rhoinv,tau,temp,temp1,w
           ! Local Arrays
           real(qp) :: zz(3)
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           ! since this routine is called in an inner loop, we do no argument
           ! checking.
           ! quick return for n=1 and 2.
           info = 0
           if (n == 1) then
               ! presumably, i=1 upon entry
              dlam = d(1) + rho*z(1)*z(1)
              delta(1) = one
              return
           end if
           if (n == 2) then
              call la_qlaed5(i,d,z,delta,rho,dlam)
              return
           end if
           ! compute machine epsilon
           eps = la_qlamch('EPSILON')
           rhoinv = one/rho
           ! the case i = n
           if (i == n) then
              ! initialize some basic variables
              ii = n - 1
              niter = 1
              ! calculate initial guess
              midpt = rho/two
              ! if ||z||_2 is not one, then temp should be set to
              ! rho * ||z||_2^2 / two
              do j = 1,n
                 delta(j) = (d(j) - d(i)) - midpt
              end do
              psi = zero
              do j = 1,n - 2
                 psi = psi + z(j)*z(j)/delta(j)
              end do
              c = rhoinv + psi
              w = c + z(ii)*z(ii)/delta(ii) + z(n)*z(n)/delta(n)
              if (w <= zero) then
                 temp = z(n - 1)*z(n - 1)/(d(n) - d(n - 1) + rho) + z(n)*z(n)/rho
                 if (c <= temp) then
                    tau = rho
                 else
                    del = d(n) - d(n - 1)
                    a = -c*del + z(n - 1)*z(n - 1) + z(n)*z(n)
                    b = z(n)*z(n)*del
                    if (a < zero) then
                       tau = two*b/(sqrt(a*a + four*b*c) - a)
                    else
                       tau = (a + sqrt(a*a + four*b*c))/(two*c)
                    end if
                 end if
                 ! it can be proved that
                     ! d(n)+rho/2 <= lambda(n) < d(n)+tau <= d(n)+rho
                 dltlb = midpt
                 dltub = rho
              else
                 del = d(n) - d(n - 1)
                 a = -c*del + z(n - 1)*z(n - 1) + z(n)*z(n)
                 b = z(n)*z(n)*del
                 if (a < zero) then
                    tau = two*b/(sqrt(a*a + four*b*c) - a)
                 else
                    tau = (a + sqrt(a*a + four*b*c))/(two*c)
                 end if
                 ! it can be proved that
                     ! d(n) < d(n)+tau < lambda(n) < d(n)+rho/2
                 dltlb = zero
                 dltub = midpt
              end if
              do j = 1,n
                 delta(j) = (d(j) - d(i)) - tau
              end do
              ! evaluate psi and the derivative dpsi
              dpsi = zero
              psi = zero
              erretm = zero
              do j = 1,ii
                 temp = z(j)/delta(j)
                 psi = psi + z(j)*temp
                 dpsi = dpsi + temp*temp
                 erretm = erretm + psi
              end do
              erretm = abs(erretm)
              ! evaluate phi and the derivative dphi
              temp = z(n)/delta(n)
              phi = z(n)*temp
              dphi = temp*temp
              erretm = eight*(-phi - psi) + erretm - phi + rhoinv + abs(tau)*(dpsi + dphi)

              w = rhoinv + phi + psi
              ! test for convergence
              if (abs(w) <= eps*erretm) then
                 dlam = d(i) + tau
                 go to 250
              end if
              if (w <= zero) then
                 dltlb = max(dltlb,tau)
              else
                 dltub = min(dltub,tau)
              end if
              ! calculate the new step
              niter = niter + 1
              c = w - delta(n - 1)*dpsi - delta(n)*dphi
              a = (delta(n - 1) + delta(n))*w - delta(n - 1)*delta(n)*(dpsi + dphi)
              b = delta(n - 1)*delta(n)*w
              if (c < zero) c = abs(c)
              if (c == zero) then
                ! eta = b/a
                 ! eta = rho - tau
                 eta = dltub - tau
              else if (a >= zero) then
                 eta = (a + sqrt(abs(a*a - four*b*c)))/(two*c)
              else
                 eta = two*b/(a - sqrt(abs(a*a - four*b*c)))
              end if
              ! note, eta should be positive if w is negative, and
              ! eta should be negative otherwise. however,
              ! if for some reason caused by roundoff, eta*w > 0,
              ! we simply use one newton step instead. this way
              ! will guarantee eta*w < 0.
              if (w*eta > zero) eta = -w/(dpsi + dphi)
              temp = tau + eta
              if (temp > dltub .or. temp < dltlb) then
                 if (w < zero) then
                    eta = (dltub - tau)/two
                 else
                    eta = (dltlb - tau)/two
                 end if
              end if
              do j = 1,n
                 delta(j) = delta(j) - eta
              end do
              tau = tau + eta
              ! evaluate psi and the derivative dpsi
              dpsi = zero
              psi = zero
              erretm = zero
              do j = 1,ii
                 temp = z(j)/delta(j)
                 psi = psi + z(j)*temp
                 dpsi = dpsi + temp*temp
                 erretm = erretm + psi
              end do
              erretm = abs(erretm)
              ! evaluate phi and the derivative dphi
              temp = z(n)/delta(n)
              phi = z(n)*temp
              dphi = temp*temp
              erretm = eight*(-phi - psi) + erretm - phi + rhoinv + abs(tau)*(dpsi + dphi)

              w = rhoinv + phi + psi
              ! main loop to update the values of the array   delta
              iter = niter + 1
              loop_90: do niter = iter,maxit
                 ! test for convergence
                 if (abs(w) <= eps*erretm) then
                    dlam = d(i) + tau
                    go to 250
                 end if
                 if (w <= zero) then
                    dltlb = max(dltlb,tau)
                 else
                    dltub = min(dltub,tau)
                 end if
                 ! calculate the new step
                 c = w - delta(n - 1)*dpsi - delta(n)*dphi
                 a = (delta(n - 1) + delta(n))*w - delta(n - 1)*delta(n)*(dpsi + dphi)
                 b = delta(n - 1)*delta(n)*w
                 if (a >= zero) then
                    eta = (a + sqrt(abs(a*a - four*b*c)))/(two*c)
                 else
                    eta = two*b/(a - sqrt(abs(a*a - four*b*c)))
                 end if
                 ! note, eta should be positive if w is negative, and
                 ! eta should be negative otherwise. however,
                 ! if for some reason caused by roundoff, eta*w > 0,
                 ! we simply use one newton step instead. this way
                 ! will guarantee eta*w < 0.
                 if (w*eta > zero) eta = -w/(dpsi + dphi)
                 temp = tau + eta
                 if (temp > dltub .or. temp < dltlb) then
                    if (w < zero) then
                       eta = (dltub - tau)/two
                    else
                       eta = (dltlb - tau)/two
                    end if
                 end if
                 do j = 1,n
                    delta(j) = delta(j) - eta
                 end do
                 tau = tau + eta
                 ! evaluate psi and the derivative dpsi
                 dpsi = zero
                 psi = zero
                 erretm = zero
                 do j = 1,ii
                    temp = z(j)/delta(j)
                    psi = psi + z(j)*temp
                    dpsi = dpsi + temp*temp
                    erretm = erretm + psi
                 end do
                 erretm = abs(erretm)
                 ! evaluate phi and the derivative dphi
                 temp = z(n)/delta(n)
                 phi = z(n)*temp
                 dphi = temp*temp
                 erretm = eight*(-phi - psi) + erretm - phi + rhoinv + abs(tau)*(dpsi + dphi)

                 w = rhoinv + phi + psi
              end do loop_90
              ! return with info = 1, niter = maxit and not converged
              info = 1
              dlam = d(i) + tau
              go to 250
              ! end for the case i = n
           else
              ! the case for i < n
              niter = 1
              ip1 = i + 1
              ! calculate initial guess
              del = d(ip1) - d(i)
              midpt = del/two
              do j = 1,n
                 delta(j) = (d(j) - d(i)) - midpt
              end do
              psi = zero
              do j = 1,i - 1
                 psi = psi + z(j)*z(j)/delta(j)
              end do
              phi = zero
              do j = n,i + 2,-1
                 phi = phi + z(j)*z(j)/delta(j)
              end do
              c = rhoinv + psi + phi
              w = c + z(i)*z(i)/delta(i) + z(ip1)*z(ip1)/delta(ip1)
              if (w > zero) then
                 ! d(i)< the ith eigenvalue < (d(i)+d(i+1))/2
                 ! we choose d(i) as origin.
                 orgati = .true.
                 a = c*del + z(i)*z(i) + z(ip1)*z(ip1)
                 b = z(i)*z(i)*del
                 if (a > zero) then
                    tau = two*b/(a + sqrt(abs(a*a - four*b*c)))
                 else
                    tau = (a - sqrt(abs(a*a - four*b*c)))/(two*c)
                 end if
                 dltlb = zero
                 dltub = midpt
              else
                 ! (d(i)+d(i+1))/2 <= the ith eigenvalue < d(i+1)
                 ! we choose d(i+1) as origin.
                 orgati = .false.
                 a = c*del - z(i)*z(i) - z(ip1)*z(ip1)
                 b = z(ip1)*z(ip1)*del
                 if (a < zero) then
                    tau = two*b/(a - sqrt(abs(a*a + four*b*c)))
                 else
                    tau = -(a + sqrt(abs(a*a + four*b*c)))/(two*c)
                 end if
                 dltlb = -midpt
                 dltub = zero
              end if
              if (orgati) then
                 do j = 1,n
                    delta(j) = (d(j) - d(i)) - tau
                 end do
              else
                 do j = 1,n
                    delta(j) = (d(j) - d(ip1)) - tau
                 end do
              end if
              if (orgati) then
                 ii = i
              else
                 ii = i + 1
              end if
              iim1 = ii - 1
              iip1 = ii + 1
              ! evaluate psi and the derivative dpsi
              dpsi = zero
              psi = zero
              erretm = zero
              do j = 1,iim1
                 temp = z(j)/delta(j)
                 psi = psi + z(j)*temp
                 dpsi = dpsi + temp*temp
                 erretm = erretm + psi
              end do
              erretm = abs(erretm)
              ! evaluate phi and the derivative dphi
              dphi = zero
              phi = zero
              do j = n,iip1,-1
                 temp = z(j)/delta(j)
                 phi = phi + z(j)*temp
                 dphi = dphi + temp*temp
                 erretm = erretm + phi
              end do
              w = rhoinv + phi + psi
              ! w is the value of the secular function with
              ! its ii-th element removed.
              swtch3 = .false.
              if (orgati) then
                 if (w < zero) swtch3 = .true.
              else
                 if (w > zero) swtch3 = .true.
              end if
              if (ii == 1 .or. ii == n) swtch3 = .false.
              temp = z(ii)/delta(ii)
              dw = dpsi + dphi + temp*temp
              temp = z(ii)*temp
              w = w + temp
              erretm = eight*(phi - psi) + erretm + two*rhoinv + three*abs(temp) + abs(tau) &
                        *dw
              ! test for convergence
              if (abs(w) <= eps*erretm) then
                 if (orgati) then
                    dlam = d(i) + tau
                 else
                    dlam = d(ip1) + tau
                 end if
                 go to 250
              end if
              if (w <= zero) then
                 dltlb = max(dltlb,tau)
              else
                 dltub = min(dltub,tau)
              end if
              ! calculate the new step
              niter = niter + 1
              if (.not. swtch3) then
                 if (orgati) then
                    c = w - delta(ip1)*dw - (d(i) - d(ip1))*(z(i)/delta(i)) &
                              **2
                 else
                    c = w - delta(i)*dw - (d(ip1) - d(i))*(z(ip1)/delta(ip1)) &
                              **2
                 end if
                 a = (delta(i) + delta(ip1))*w - delta(i)*delta(ip1)*dw
                 b = delta(i)*delta(ip1)*w
                 if (c == zero) then
                    if (a == zero) then
                       if (orgati) then
                          a = z(i)*z(i) + delta(ip1)*delta(ip1)*(dpsi + dphi)
                       else
                          a = z(ip1)*z(ip1) + delta(i)*delta(i)*(dpsi + dphi)
                       end if
                    end if
                    eta = b/a
                 else if (a <= zero) then
                    eta = (a - sqrt(abs(a*a - four*b*c)))/(two*c)
                 else
                    eta = two*b/(a + sqrt(abs(a*a - four*b*c)))
                 end if
              else
                 ! interpolation using three most relevant poles
                 temp = rhoinv + psi + phi
                 if (orgati) then
                    temp1 = z(iim1)/delta(iim1)
                    temp1 = temp1*temp1
                    c = temp - delta(iip1)*(dpsi + dphi) - (d(iim1) - d(iip1))*temp1
                    zz(1) = z(iim1)*z(iim1)
                    zz(3) = delta(iip1)*delta(iip1)*((dpsi - temp1) + dphi)
                 else
                    temp1 = z(iip1)/delta(iip1)
                    temp1 = temp1*temp1
                    c = temp - delta(iim1)*(dpsi + dphi) - (d(iip1) - d(iim1))*temp1
                    zz(1) = delta(iim1)*delta(iim1)*(dpsi + (dphi - temp1))
                    zz(3) = z(iip1)*z(iip1)
                 end if
                 zz(2) = z(ii)*z(ii)
                 call la_qlaed6(niter,orgati,c,delta(iim1),zz,w,eta,info)
                 if (info /= 0) go to 250
              end if
              ! note, eta should be positive if w is negative, and
              ! eta should be negative otherwise. however,
              ! if for some reason caused by roundoff, eta*w > 0,
              ! we simply use one newton step instead. this way
              ! will guarantee eta*w < 0.
              if (w*eta >= zero) eta = -w/dw
              temp = tau + eta
              if (temp > dltub .or. temp < dltlb) then
                 if (w < zero) then
                    eta = (dltub - tau)/two
                 else
                    eta = (dltlb - tau)/two
                 end if
              end if
              prew = w
              do j = 1,n
                 delta(j) = delta(j) - eta
              end do
              ! evaluate psi and the derivative dpsi
              dpsi = zero
              psi = zero
              erretm = zero
              do j = 1,iim1
                 temp = z(j)/delta(j)
                 psi = psi + z(j)*temp
                 dpsi = dpsi + temp*temp
                 erretm = erretm + psi
              end do
              erretm = abs(erretm)
              ! evaluate phi and the derivative dphi
              dphi = zero
              phi = zero
              do j = n,iip1,-1
                 temp = z(j)/delta(j)
                 phi = phi + z(j)*temp
                 dphi = dphi + temp*temp
                 erretm = erretm + phi
              end do
              temp = z(ii)/delta(ii)
              dw = dpsi + dphi + temp*temp
              temp = z(ii)*temp
              w = rhoinv + phi + psi + temp
              erretm = eight*(phi - psi) + erretm + two*rhoinv + three*abs(temp) + abs(tau + eta) &
                        *dw
              swtch = .false.
              if (orgati) then
                 if (-w > abs(prew)/ten) swtch = .true.
              else
                 if (w > abs(prew)/ten) swtch = .true.
              end if
              tau = tau + eta
              ! main loop to update the values of the array   delta
              iter = niter + 1
              loop_240: do niter = iter,maxit
                 ! test for convergence
                 if (abs(w) <= eps*erretm) then
                    if (orgati) then
                       dlam = d(i) + tau
                    else
                       dlam = d(ip1) + tau
                    end if
                    go to 250
                 end if
                 if (w <= zero) then
                    dltlb = max(dltlb,tau)
                 else
                    dltub = min(dltub,tau)
                 end if
                 ! calculate the new step
                 if (.not. swtch3) then
                    if (.not. swtch) then
                       if (orgati) then
                          c = w - delta(ip1)*dw - (d(i) - d(ip1))*(z(i)/delta(i)) &
                                    **2
                       else
                          c = w - delta(i)*dw - (d(ip1) - d(i))*(z(ip1)/delta(ip1)) &
                                    **2
                       end if
                    else
                       temp = z(ii)/delta(ii)
                       if (orgati) then
                          dpsi = dpsi + temp*temp
                       else
                          dphi = dphi + temp*temp
                       end if
                       c = w - delta(i)*dpsi - delta(ip1)*dphi
                    end if
                    a = (delta(i) + delta(ip1))*w - delta(i)*delta(ip1)*dw
                    b = delta(i)*delta(ip1)*w
                    if (c == zero) then
                       if (a == zero) then
                          if (.not. swtch) then
                             if (orgati) then
                                a = z(i)*z(i) + delta(ip1)*delta(ip1)*(dpsi + dphi)

                             else
                                a = z(ip1)*z(ip1) + delta(i)*delta(i)*(dpsi + dphi)
                             end if
                          else
                             a = delta(i)*delta(i)*dpsi + delta(ip1)*delta(ip1) &
                                       *dphi
                          end if
                       end if
                       eta = b/a
                    else if (a <= zero) then
                       eta = (a - sqrt(abs(a*a - four*b*c)))/(two*c)
                    else
                       eta = two*b/(a + sqrt(abs(a*a - four*b*c)))
                    end if
                 else
                    ! interpolation using three most relevant poles
                    temp = rhoinv + psi + phi
                    if (swtch) then
                       c = temp - delta(iim1)*dpsi - delta(iip1)*dphi
                       zz(1) = delta(iim1)*delta(iim1)*dpsi
                       zz(3) = delta(iip1)*delta(iip1)*dphi
                    else
                       if (orgati) then
                          temp1 = z(iim1)/delta(iim1)
                          temp1 = temp1*temp1
                          c = temp - delta(iip1)*(dpsi + dphi) - (d(iim1) - d(iip1)) &
                                    *temp1
                          zz(1) = z(iim1)*z(iim1)
                          zz(3) = delta(iip1)*delta(iip1)*((dpsi - temp1) + dphi)
                       else
                          temp1 = z(iip1)/delta(iip1)
                          temp1 = temp1*temp1
                          c = temp - delta(iim1)*(dpsi + dphi) - (d(iip1) - d(iim1)) &
                                    *temp1
                          zz(1) = delta(iim1)*delta(iim1)*(dpsi + (dphi - temp1))
                          zz(3) = z(iip1)*z(iip1)
                       end if
                    end if
                    call la_qlaed6(niter,orgati,c,delta(iim1),zz,w,eta,info)
                    if (info /= 0) go to 250
                 end if
                 ! note, eta should be positive if w is negative, and
                 ! eta should be negative otherwise. however,
                 ! if for some reason caused by roundoff, eta*w > 0,
                 ! we simply use one newton step instead. this way
                 ! will guarantee eta*w < 0.
                 if (w*eta >= zero) eta = -w/dw
                 temp = tau + eta
                 if (temp > dltub .or. temp < dltlb) then
                    if (w < zero) then
                       eta = (dltub - tau)/two
                    else
                       eta = (dltlb - tau)/two
                    end if
                 end if
                 do j = 1,n
                    delta(j) = delta(j) - eta
                 end do
                 tau = tau + eta
                 prew = w
                 ! evaluate psi and the derivative dpsi
                 dpsi = zero
                 psi = zero
                 erretm = zero
                 do j = 1,iim1
                    temp = z(j)/delta(j)
                    psi = psi + z(j)*temp
                    dpsi = dpsi + temp*temp
                    erretm = erretm + psi
                 end do
                 erretm = abs(erretm)
                 ! evaluate phi and the derivative dphi
                 dphi = zero
                 phi = zero
                 do j = n,iip1,-1
                    temp = z(j)/delta(j)
                    phi = phi + z(j)*temp
                    dphi = dphi + temp*temp
                    erretm = erretm + phi
                 end do
                 temp = z(ii)/delta(ii)
                 dw = dpsi + dphi + temp*temp
                 temp = z(ii)*temp
                 w = rhoinv + phi + psi + temp
                 erretm = eight*(phi - psi) + erretm + two*rhoinv + three*abs(temp) + abs(tau) &
                           *dw
                 if (w*prew > zero .and. abs(w) > abs(prew)/ten) swtch = .not. swtch
              end do loop_240
              ! return with info = 1, niter = maxit and not converged
              info = 1
              if (orgati) then
                 dlam = d(i) + tau
              else
                 dlam = d(ip1) + tau
              end if
           end if
           250 continue
           return
     end subroutine la_qlaed4

     !> This subroutine computes the I-th eigenvalue of a symmetric rank-one
     !> modification of a 2-by-2 diagonal matrix
     !> diag( D )  +  RHO * Z * transpose(Z) .
     !> The diagonal elements in the array D are assumed to satisfy
     !> D(i) < D(j)  for  i < j .
     !> We also assume RHO > 0 and that the Euclidean norm of the vector
     !> Z is one.

     pure subroutine la_qlaed5(i,d,z,delta,rho,dlam)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: i
           real(qp),intent(out) :: dlam
           real(qp),intent(in) :: rho
           ! Array Arguments
           real(qp),intent(in) :: d(2),z(2)
           real(qp),intent(out) :: delta(2)
        ! =====================================================================

           ! Local Scalars
           real(qp) :: b,c,del,tau,temp,w
           ! Intrinsic Functions
           intrinsic :: abs,sqrt
           ! Executable Statements
           del = d(2) - d(1)
           if (i == 1) then
              w = one + two*rho*(z(2)*z(2) - z(1)*z(1))/del
              if (w > zero) then
                 b = del + rho*(z(1)*z(1) + z(2)*z(2))
                 c = rho*z(1)*z(1)*del
                 ! b > zero, always
                 tau = two*c/(b + sqrt(abs(b*b - four*c)))
                 dlam = d(1) + tau
                 delta(1) = -z(1)/tau
                 delta(2) = z(2)/(del - tau)
              else
                 b = -del + rho*(z(1)*z(1) + z(2)*z(2))
                 c = rho*z(2)*z(2)*del
                 if (b > zero) then
                    tau = -two*c/(b + sqrt(b*b + four*c))
                 else
                    tau = (b - sqrt(b*b + four*c))/two
                 end if
                 dlam = d(2) + tau
                 delta(1) = -z(1)/(del + tau)
                 delta(2) = -z(2)/tau
              end if
              temp = sqrt(delta(1)*delta(1) + delta(2)*delta(2))
              delta(1) = delta(1)/temp
              delta(2) = delta(2)/temp
           else
           ! now i=2
              b = -del + rho*(z(1)*z(1) + z(2)*z(2))
              c = rho*z(2)*z(2)*del
              if (b > zero) then
                 tau = (b + sqrt(b*b + four*c))/two
              else
                 tau = two*c/(-b + sqrt(b*b + four*c))
              end if
              dlam = d(2) + tau
              delta(1) = -z(1)/(del + tau)
              delta(2) = -z(2)/tau
              temp = sqrt(delta(1)*delta(1) + delta(2)*delta(2))
              delta(1) = delta(1)/temp
              delta(2) = delta(2)/temp
           end if
           return
     end subroutine la_qlaed5

     !> DLAED6: computes the positive or negative root (closest to the origin)
     !> of
     !> z(1)        z(2)        z(3)
     !> f(x) =   rho + --------- + ---------- + ---------
     !> d(1)-x      d(2)-x      d(3)-x
     !> It is assumed that
     !> if ORGATI = .true. the root is between d(2) and d(3);
     !> otherwise it is between d(1) and d(2)
     !> This routine will be called by DLAED4 when necessary. In most cases,
     !> the root sought is the smallest in magnitude, though it might not be
     !> in some extremely rare situations.

     pure subroutine la_qlaed6(kniter,orgati,rho,d,z,finit,tau,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: orgati
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kniter
           real(qp),intent(in) :: finit,rho
           real(qp),intent(out) :: tau
           ! Array Arguments
           real(qp),intent(in) :: d(3),z(3)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: maxit = 40

           ! Local Arrays
           real(qp) :: dscale(3),zscale(3)
           ! Local Scalars
           logical(lk) :: scale
           integer(ilp) :: i,iter,niter
           real(qp) :: a,b,base,c,ddf,df,eps,erretm,eta,f,fc,sclfac,sclinv,small1, &
                     small2,sminv1,sminv2,temp,temp1,temp2,temp3,temp4,lbd,ubd
           ! Intrinsic Functions
           intrinsic :: abs,int,log,max,min,sqrt
           ! Executable Statements
           info = 0
           if (orgati) then
              lbd = d(2)
              ubd = d(3)
           else
              lbd = d(1)
              ubd = d(2)
           end if
           if (finit < zero) then
              lbd = zero
           else
              ubd = zero
           end if
           niter = 1
           tau = zero
           if (kniter == 2) then
              if (orgati) then
                 temp = (d(3) - d(2))/two
                 c = rho + z(1)/((d(1) - d(2)) - temp)
                 a = c*(d(2) + d(3)) + z(2) + z(3)
                 b = c*d(2)*d(3) + z(2)*d(3) + z(3)*d(2)
              else
                 temp = (d(1) - d(2))/two
                 c = rho + z(3)/((d(3) - d(2)) - temp)
                 a = c*(d(1) + d(2)) + z(1) + z(2)
                 b = c*d(1)*d(2) + z(1)*d(2) + z(2)*d(1)
              end if
              temp = max(abs(a),abs(b),abs(c))
              a = a/temp
              b = b/temp
              c = c/temp
              if (c == zero) then
                 tau = b/a
              else if (a <= zero) then
                 tau = (a - sqrt(abs(a*a - four*b*c)))/(two*c)
              else
                 tau = two*b/(a + sqrt(abs(a*a - four*b*c)))
              end if
              if (tau < lbd .or. tau > ubd) tau = (lbd + ubd)/two
              if (d(1) == tau .or. d(2) == tau .or. d(3) == tau) then
                 tau = zero
              else
                 temp = finit + tau*z(1)/(d(1)*(d(1) - tau)) + tau*z(2)/(d(2)*(d(2) - tau)) &
                            + tau*z(3)/(d(3)*(d(3) - tau))
                 if (temp <= zero) then
                    lbd = tau
                 else
                    ubd = tau
                 end if
                 if (abs(finit) <= abs(temp)) tau = zero
              end if
           end if
           ! get machine parameters for possible scaling to avoid overflow
           ! modified by sven: parameters small1, sminv1, small2,
           ! sminv2, eps are not saved anymore between one call to the
           ! others but recomputed at each call
           eps = la_qlamch('EPSILON')
           base = la_qlamch('BASE')
           small1 = base**(int(log(la_qlamch('SAFMIN'))/log(base)/three,KIND=ilp))

           sminv1 = one/small1
           small2 = small1*small1
           sminv2 = sminv1*sminv1
           ! determine if scaling of inputs necessary to avoid overflow
           ! when computing 1/temp**3
           if (orgati) then
              temp = min(abs(d(2) - tau),abs(d(3) - tau))
           else
              temp = min(abs(d(1) - tau),abs(d(2) - tau))
           end if
           scale = .false.
           if (temp <= small1) then
              scale = .true.
              if (temp <= small2) then
              ! scale up by power of radix nearest 1/safmin**(2/3)
                 sclfac = sminv2
                 sclinv = small2
              else
              ! scale up by power of radix nearest 1/safmin**(1/3)
                 sclfac = sminv1
                 sclinv = small1
              end if
              ! scaling up safe because d, z, tau scaled elsewhere to be o(1)
              do i = 1,3
                 dscale(i) = d(i)*sclfac
                 zscale(i) = z(i)*sclfac
              end do
              tau = tau*sclfac
              lbd = lbd*sclfac
              ubd = ubd*sclfac
           else
              ! copy d and z to dscale and zscale
              do i = 1,3
                 dscale(i) = d(i)
                 zscale(i) = z(i)
              end do
           end if
           fc = zero
           df = zero
           ddf = zero
           do i = 1,3
              temp = one/(dscale(i) - tau)
              temp1 = zscale(i)*temp
              temp2 = temp1*temp
              temp3 = temp2*temp
              fc = fc + temp1/dscale(i)
              df = df + temp2
              ddf = ddf + temp3
           end do
           f = finit + tau*fc
           if (abs(f) <= zero) go to 60
           if (f <= zero) then
              lbd = tau
           else
              ubd = tau
           end if
              ! iteration begins -- use gragg-thornton-warner cubic convergent
                                  ! scheme
           ! it is not hard to see that
                 ! 1) iterations will go up monotonically
                    ! if finit < 0;
                 ! 2) iterations will go down monotonically
                    ! if finit > 0.
           iter = niter + 1
           loop_50: do niter = iter,maxit
              if (orgati) then
                 temp1 = dscale(2) - tau
                 temp2 = dscale(3) - tau
              else
                 temp1 = dscale(1) - tau
                 temp2 = dscale(2) - tau
              end if
              a = (temp1 + temp2)*f - temp1*temp2*df
              b = temp1*temp2*f
              c = f - (temp1 + temp2)*df + temp1*temp2*ddf
              temp = max(abs(a),abs(b),abs(c))
              a = a/temp
              b = b/temp
              c = c/temp
              if (c == zero) then
                 eta = b/a
              else if (a <= zero) then
                 eta = (a - sqrt(abs(a*a - four*b*c)))/(two*c)
              else
                 eta = two*b/(a + sqrt(abs(a*a - four*b*c)))
              end if
              if (f*eta >= zero) then
                 eta = -f/df
              end if
              tau = tau + eta
              if (tau < lbd .or. tau > ubd) tau = (lbd + ubd)/two
              fc = zero
              erretm = zero
              df = zero
              ddf = zero
              do i = 1,3
                 if ((dscale(i) - tau) /= zero) then
                    temp = one/(dscale(i) - tau)
                    temp1 = zscale(i)*temp
                    temp2 = temp1*temp
                    temp3 = temp2*temp
                    temp4 = temp1/dscale(i)
                    fc = fc + temp4
                    erretm = erretm + abs(temp4)
                    df = df + temp2
                    ddf = ddf + temp3
                 else
                    go to 60
                 end if
              end do
              f = finit + tau*fc
              erretm = eight*(abs(finit) + abs(tau)*erretm) + abs(tau)*df
              if ((abs(f) <= four*eps*erretm) .or. ((ubd - lbd) <= four*eps*abs(tau))) go to &
                        60
              if (f <= zero) then
                 lbd = tau
              else
                 ubd = tau
              end if
           end do loop_50
           info = 1
           60 continue
           ! undo scaling
           if (scale) tau = tau*sclinv
           return
     end subroutine la_qlaed6

     !> DLAED7: computes the updated eigensystem of a diagonal
     !> matrix after modification by a rank-one symmetric matrix. This
     !> routine is used only for the eigenproblem which requires all
     !> eigenvalues and optionally eigenvectors of a dense symmetric matrix
     !> that has been reduced to tridiagonal form.  DLAED1 handles
     !> the case in which all eigenvalues and eigenvectors of a symmetric
     !> tridiagonal matrix are desired.
     !> T = Q(in) ( D(in) + RHO * Z*Z**T ) Q**T(in) = Q(out) * D(out) * Q**T(out)
     !> where Z = Q**Tu, u is a vector of length N with ones in the
     !> CUTPNT and CUTPNT + 1 th elements and zeros elsewhere.
     !> The eigenvectors of the original matrix are stored in Q, and the
     !> eigenvalues are in D.  The algorithm consists of three stages:
     !> The first stage consists of deflating the size of the problem
     !> when there are multiple eigenvalues or if there is a zero in
     !> the Z vector.  For each such occurrence the dimension of the
     !> secular equation problem is reduced by one.  This stage is
     !> performed by the routine DLAED8.
     !> The second stage consists of calculating the updated
     !> eigenvalues. This is done by finding the roots of the secular
     !> equation via the routine DLAED4 (as called by DLAED9).
     !> This routine also calculates the eigenvectors of the current
     !> problem.
     !> The final stage consists of computing the updated eigenvectors
     !> directly using the updated eigenvalues.  The eigenvectors for
     !> the current problem are multiplied with the eigenvectors from
     !> the overall problem.

     pure subroutine la_qlaed7(icompq,n,qsiz,tlvls,curlvl,curpbm,d,q,ldq,indxq,rho, &
               cutpnt,qstore,qptr,prmptr,perm,givptr,givcol,givnum,work,iwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: curlvl,curpbm,cutpnt,icompq,ldq,n,qsiz,tlvls
           integer(ilp),intent(out) :: info
           real(qp),intent(inout) :: rho
           ! Array Arguments
           integer(ilp),intent(inout) :: givcol(2,*),givptr(*),perm(*),prmptr(*),qptr(*)

           integer(ilp),intent(out) :: indxq(*),iwork(*)
           real(qp),intent(inout) :: d(*),givnum(2,*),q(ldq,*),qstore(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: coltyp,curr,i,idlmda,indx,indxc,indxp,iq2,is,iw,iz,k,ldq2, &
                     n1,n2,ptr
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (icompq < 0 .or. icompq > 1) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (icompq == 1 .and. qsiz < n) then
              info = -3
           else if (ldq < max(1,n)) then
              info = -9
           else if (min(1,n) > cutpnt .or. n < cutpnt) then
              info = -12
           end if
           if (info /= 0) then
              call la_xerbla('DLAED7',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! the following values are for bookkeeping purposes only.  they are
           ! integer pointers which indicate the portion of the workspace
           ! used by a particular array in la_qlaed8 and la_qlaed9.
           if (icompq == 1) then
              ldq2 = qsiz
           else
              ldq2 = n
           end if
           iz = 1
           idlmda = iz + n
           iw = idlmda + n
           iq2 = iw + n
           is = iq2 + n*ldq2
           indx = 1
           indxc = indx + n
           coltyp = indxc + n
           indxp = coltyp + n
           ! form the z-vector which consists of the last row of q_1 and the
           ! first row of q_2.
           ptr = 1 + 2**tlvls
           do i = 1,curlvl - 1
              ptr = ptr + 2**(tlvls - i)
           end do
           curr = ptr + curpbm
           call la_qlaeda(n,tlvls,curlvl,curpbm,prmptr,perm,givptr,givcol,givnum, &
                     qstore,qptr,work(iz),work(iz + n),info)
           ! when solving the final problem, we no longer need the stored data,
           ! so we will overwrite the data from this level onto the previously
           ! used storage space.
           if (curlvl == tlvls) then
              qptr(curr) = 1
              prmptr(curr) = 1
              givptr(curr) = 1
           end if
           ! sort and deflate eigenvalues.
           call la_qlaed8(icompq,k,n,qsiz,d,q,ldq,indxq,rho,cutpnt,work(iz),work( &
            idlmda),work(iq2),ldq2,work(iw),perm(prmptr(curr)),givptr(curr + 1), &
            givcol(1,givptr(curr)),givnum(1,givptr(curr)),iwork(indxp),iwork(indx), &
                       info)
           prmptr(curr + 1) = prmptr(curr) + n
           givptr(curr + 1) = givptr(curr + 1) + givptr(curr)
           ! solve secular equation.
           if (k /= 0) then
              call la_qlaed9(k,1,k,n,d,work(is),k,rho,work(idlmda),work(iw), &
                        qstore(qptr(curr)),k,info)
              if (info /= 0) go to 30
              if (icompq == 1) then
                 call la_qgemm('N','N',qsiz,k,k,one,work(iq2),ldq2,qstore(qptr( &
                           curr)),k,zero,q,ldq)
              end if
              qptr(curr + 1) = qptr(curr) + k**2
           ! prepare the indxq sorting permutation.
              n1 = k
              n2 = n - k
              call la_qlamrg(n1,n2,d,1,-1,indxq)
           else
              qptr(curr + 1) = qptr(curr)
              do i = 1,n
                 indxq(i) = i
              end do
           end if
           30 continue
           return
     end subroutine la_qlaed7

     !> DLAED8: merges the two sets of eigenvalues together into a single
     !> sorted set.  Then it tries to deflate the size of the problem.
     !> There are two ways in which deflation can occur:  when two or more
     !> eigenvalues are close together or if there is a tiny element in the
     !> Z vector.  For each such occurrence the order of the related secular
     !> equation problem is reduced by one.

     pure subroutine la_qlaed8(icompq,k,n,qsiz,d,q,ldq,indxq,rho,cutpnt,z,dlamda, &
               q2,ldq2,w,perm,givptr,givcol,givnum,indxp,indx,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: cutpnt,icompq,ldq,ldq2,n,qsiz
           integer(ilp),intent(out) :: givptr,info,k
           real(qp),intent(inout) :: rho
           ! Array Arguments
           integer(ilp),intent(out) :: givcol(2,*),indx(*),indxp(*),perm(*)
           integer(ilp),intent(inout) :: indxq(*)
           real(qp),intent(inout) :: d(*),q(ldq,*),z(*)
           real(qp),intent(out) :: dlamda(*),givnum(2,*),q2(ldq2,*),w(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: mone = -1.0_qp

           ! Local Scalars
           integer(ilp) :: i,imax,j,jlam,jmax,jp,k2,n1,n1p1,n2
           real(qp) :: c,eps,s,t,tau,tol
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (icompq < 0 .or. icompq > 1) then
              info = -1
           else if (n < 0) then
              info = -3
           else if (icompq == 1 .and. qsiz < n) then
              info = -4
           else if (ldq < max(1,n)) then
              info = -7
           else if (cutpnt < min(1,n) .or. cutpnt > n) then
              info = -10
           else if (ldq2 < max(1,n)) then
              info = -14
           end if
           if (info /= 0) then
              call la_xerbla('DLAED8',-info)
              return
           end if
           ! need to initialize givptr to o here in case of quick exit
           ! to prevent an unspecified code behavior (usually sigfault)
           ! when iwork array on entry to *stedc is not zeroed
           ! (or at least some iwork entries which used in *laed7 for givptr).
           givptr = 0
           ! quick return if possible
           if (n == 0) return
           n1 = cutpnt
           n2 = n - n1
           n1p1 = n1 + 1
           if (rho < zero) then
              call la_qscal(n2,mone,z(n1p1),1)
           end if
           ! normalize z so that norm(z) = 1
           t = one/sqrt(two)
           do j = 1,n
              indx(j) = j
           end do
           call la_qscal(n,t,z,1)
           rho = abs(two*rho)
           ! sort the eigenvalues into increasing order
           do i = cutpnt + 1,n
              indxq(i) = indxq(i) + cutpnt
           end do
           do i = 1,n
              dlamda(i) = d(indxq(i))
              w(i) = z(indxq(i))
           end do
           i = 1
           j = cutpnt + 1
           call la_qlamrg(n1,n2,dlamda,1,1,indx)
           do i = 1,n
              d(i) = dlamda(indx(i))
              z(i) = w(indx(i))
           end do
           ! calculate the allowable deflation tolerance
           imax = la_iqamax(n,z,1)
           jmax = la_iqamax(n,d,1)
           eps = la_qlamch('EPSILON')
           tol = eight*eps*abs(d(jmax))
           ! if the rank-1 modifier is small enough, no more needs to be done
           ! except to reorganize q so that its columns correspond with the
           ! elements in d.
           if (rho*abs(z(imax)) <= tol) then
              k = 0
              if (icompq == 0) then
                 do j = 1,n
                    perm(j) = indxq(indx(j))
                 end do
              else
                 do j = 1,n
                    perm(j) = indxq(indx(j))
                    call la_qcopy(qsiz,q(1,perm(j)),1,q2(1,j),1)
                 end do
                 call la_qlacpy('A',qsiz,n,q2(1,1),ldq2,q(1,1),ldq)
              end if
              return
           end if
           ! if there are multiple eigenvalues then the problem deflates.  here
           ! the number of equal eigenvalues are found.  as each equal
           ! eigenvalue is found, an elementary reflector is computed to rotate
           ! the corresponding eigensubspace so that the corresponding
           ! components of z are zero in this new basis.
           k = 0
           k2 = n + 1
           do j = 1,n
              if (rho*abs(z(j)) <= tol) then
                 ! deflate due to small z component.
                 k2 = k2 - 1
                 indxp(k2) = j
                 if (j == n) go to 110
              else
                 jlam = j
                 go to 80
              end if
           end do
           80 continue
           j = j + 1
           if (j > n) go to 100
           if (rho*abs(z(j)) <= tol) then
              ! deflate due to small z component.
              k2 = k2 - 1
              indxp(k2) = j
           else
              ! check if eigenvalues are close enough to allow deflation.
              s = z(jlam)
              c = z(j)
              ! find sqrt(a**2+b**2) without overflow or
              ! destructive underflow.
              tau = la_qlapy2(c,s)
              t = d(j) - d(jlam)
              c = c/tau
              s = -s/tau
              if (abs(t*c*s) <= tol) then
                 ! deflation is possible.
                 z(j) = tau
                 z(jlam) = zero
                 ! record the appropriate givens rotation
                 givptr = givptr + 1
                 givcol(1,givptr) = indxq(indx(jlam))
                 givcol(2,givptr) = indxq(indx(j))
                 givnum(1,givptr) = c
                 givnum(2,givptr) = s
                 if (icompq == 1) then
                    call la_qrot(qsiz,q(1,indxq(indx(jlam))),1,q(1,indxq(indx(j &
                              ))),1,c,s)
                 end if
                 t = d(jlam)*c*c + d(j)*s*s
                 d(j) = d(jlam)*s*s + d(j)*c*c
                 d(jlam) = t
                 k2 = k2 - 1
                 i = 1
                 90 continue
                 if (k2 + i <= n) then
                    if (d(jlam) < d(indxp(k2 + i))) then
                       indxp(k2 + i - 1) = indxp(k2 + i)
                       indxp(k2 + i) = jlam
                       i = i + 1
                       go to 90
                    else
                       indxp(k2 + i - 1) = jlam
                    end if
                 else
                    indxp(k2 + i - 1) = jlam
                 end if
                 jlam = j
              else
                 k = k + 1
                 w(k) = z(jlam)
                 dlamda(k) = d(jlam)
                 indxp(k) = jlam
                 jlam = j
              end if
           end if
           go to 80
           100 continue
           ! record the last eigenvalue.
           k = k + 1
           w(k) = z(jlam)
           dlamda(k) = d(jlam)
           indxp(k) = jlam
           110 continue
           ! sort the eigenvalues and corresponding eigenvectors into dlamda
           ! and q2 respectively.  the eigenvalues/vectors which were not
           ! deflated go into the first k slots of dlamda and q2 respectively,
           ! while those which were deflated go into the last n - k slots.
           if (icompq == 0) then
              do j = 1,n
                 jp = indxp(j)
                 dlamda(j) = d(jp)
                 perm(j) = indxq(indx(jp))
              end do
           else
              do j = 1,n
                 jp = indxp(j)
                 dlamda(j) = d(jp)
                 perm(j) = indxq(indx(jp))
                 call la_qcopy(qsiz,q(1,perm(j)),1,q2(1,j),1)
              end do
           end if
           ! the deflated eigenvalues and their corresponding vectors go back
           ! into the last n - k slots of d and q respectively.
           if (k < n) then
              if (icompq == 0) then
                 call la_qcopy(n - k,dlamda(k + 1),1,d(k + 1),1)
              else
                 call la_qcopy(n - k,dlamda(k + 1),1,d(k + 1),1)
                 call la_qlacpy('A',qsiz,n - k,q2(1,k + 1),ldq2,q(1,k + 1),ldq)
              end if
           end if
           return
     end subroutine la_qlaed8

     !> DLAED9: finds the roots of the secular equation, as defined by the
     !> values in D, Z, and RHO, between KSTART and KSTOP.  It makes the
     !> appropriate calls to DLAED4 and then stores the new matrix of
     !> eigenvectors for use in calculating the next level of Z vectors.

     pure subroutine la_qlaed9(k,kstart,kstop,n,d,q,ldq,rho,dlamda,w,s,lds,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,kstart,kstop,ldq,lds,n
           real(qp),intent(in) :: rho
           ! Array Arguments
           real(qp),intent(out) :: d(*),q(ldq,*),s(lds,*)
           real(qp),intent(inout) :: dlamda(*),w(*)
        ! =====================================================================
           ! Local Scalars
           integer(ilp) :: i,j
           real(qp) :: temp
           ! Intrinsic Functions
           intrinsic :: max,sign,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (k < 0) then
              info = -1
           else if (kstart < 1 .or. kstart > max(1,k)) then
              info = -2
           else if (max(1,kstop) < kstart .or. kstop > max(1,k)) then
              info = -3
           else if (n < k) then
              info = -4
           else if (ldq < max(1,k)) then
              info = -7
           else if (lds < max(1,k)) then
              info = -12
           end if
           if (info /= 0) then
              call la_xerbla('DLAED9',-info)
              return
           end if
           ! quick return if possible
           if (k == 0) return
           ! modify values dlamda(i) to make sure all dlamda(i)-dlamda(j) can
           ! be computed with high relative accuracy (barring over/underflow).
           ! this is a problem on machines without a guard digit in
           ! add/subtract (cray xmp, cray ymp, cray c 90 and cray 2).
           ! the following code replaces dlamda(i) by 2*dlamda(i)-dlamda(i),
           ! which on any of these machines zeros out the bottommost
           ! bit of dlamda(i) if it is 1; this makes the subsequent
           ! subtractions dlamda(i)-dlamda(j) unproblematic when cancellation
           ! occurs. on binary machines with a guard digit (almost all
           ! machines) it does not change dlamda(i) at all. on hexadecimal
           ! and decimal machines with a guard digit, it slightly
           ! changes the bottommost bits of dlamda(i). it does not account
           ! for hexadecimal or decimal machines without guard digits
           ! (we know of none). we use a subroutine call to compute
           ! 2*dlambda(i) to prevent optimizing compilers from eliminating
           ! this code.
           do i = 1,n
              dlamda(i) = la_qlamc3(dlamda(i),dlamda(i)) - dlamda(i)
           end do
           do j = kstart,kstop
              call la_qlaed4(k,j,dlamda,w,q(1,j),rho,d(j),info)
              ! if the zero finder fails, the computation is terminated.
              if (info /= 0) go to 120
           end do
           if (k == 1 .or. k == 2) then
              do i = 1,k
                 do j = 1,k
                    s(j,i) = q(j,i)
                 end do
              end do
              go to 120
           end if
           ! compute updated w.
           call la_qcopy(k,w,1,s,1)
           ! initialize w(i) = q(i,i)
           call la_qcopy(k,q,ldq + 1,w,1)
           do j = 1,k
              do i = 1,j - 1
                 w(i) = w(i)*(q(i,j)/(dlamda(i) - dlamda(j)))
              end do
              do i = j + 1,k
                 w(i) = w(i)*(q(i,j)/(dlamda(i) - dlamda(j)))
              end do
           end do
           do i = 1,k
              w(i) = sign(sqrt(-w(i)),s(i,1))
           end do
           ! compute eigenvectors of the modified rank-1 modification.
           do j = 1,k
              do i = 1,k
                 q(i,j) = w(i)/q(i,j)
              end do
              temp = la_qnrm2(k,q(1,j),1)
              do i = 1,k
                 s(i,j) = q(i,j)/temp
              end do
           end do
           120 continue
           return
     end subroutine la_qlaed9

     !> DLAEDA: computes the Z vector corresponding to the merge step in the
     !> CURLVLth step of the merge process with TLVLS steps for the CURPBMth
     !> problem.

     pure subroutine la_qlaeda(n,tlvls,curlvl,curpbm,prmptr,perm,givptr,givcol,givnum, &
                q,qptr,z,ztemp,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: curlvl,curpbm,n,tlvls
           integer(ilp),intent(out) :: info
           ! Array Arguments
           integer(ilp),intent(in) :: givcol(2,*),givptr(*),perm(*),prmptr(*),qptr(*)
           real(qp),intent(in) :: givnum(2,*),q(*)
           real(qp),intent(out) :: z(*),ztemp(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: bsiz1,bsiz2,curr,i,k,mid,psiz1,psiz2,ptr,zptr1
           ! Intrinsic Functions
           intrinsic :: real,int,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (n < 0) then
              info = -1
           end if
           if (info /= 0) then
              call la_xerbla('DLAEDA',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! determine location of first number in second half.
           mid = n/2 + 1
           ! gather last/first rows of appropriate eigenblocks into center of z
           ptr = 1
           ! determine location of lowest level subproblem in the full storage
           ! scheme
           curr = ptr + curpbm*2**curlvl + 2**(curlvl - 1) - 1
           ! determine size of these matrices.  we add half to the value of
           ! the sqrt in case the machine underestimates one of these square
           ! roots.
           bsiz1 = int(half + sqrt(real(qptr(curr + 1) - qptr(curr),KIND=qp)),KIND=ilp)
           bsiz2 = int(half + sqrt(real(qptr(curr + 2) - qptr(curr + 1),KIND=qp)),KIND=ilp)

           do k = 1,mid - bsiz1 - 1
              z(k) = zero
           end do
           call la_qcopy(bsiz1,q(qptr(curr) + bsiz1 - 1),bsiz1,z(mid - bsiz1),1)
           call la_qcopy(bsiz2,q(qptr(curr + 1)),bsiz2,z(mid),1)
           do k = mid + bsiz2,n
              z(k) = zero
           end do
           ! loop through remaining levels 1 -> curlvl applying the givens
           ! rotations and permutation and then multiplying the center matrices
           ! against the current z.
           ptr = 2**tlvls + 1
           loop_70: do k = 1,curlvl - 1
              curr = ptr + curpbm*2**(curlvl - k) + 2**(curlvl - k - 1) - 1
              psiz1 = prmptr(curr + 1) - prmptr(curr)
              psiz2 = prmptr(curr + 2) - prmptr(curr + 1)
              zptr1 = mid - psiz1
             ! apply givens at curr and curr+1
              do i = givptr(curr),givptr(curr + 1) - 1
                 call la_qrot(1,z(zptr1 + givcol(1,i) - 1),1,z(zptr1 + givcol(2,i) - 1), &
                           1,givnum(1,i),givnum(2,i))
              end do
              do i = givptr(curr + 1),givptr(curr + 2) - 1
                 call la_qrot(1,z(mid - 1 + givcol(1,i)),1,z(mid - 1 + givcol(2,i)),1, &
                           givnum(1,i),givnum(2,i))
              end do
              psiz1 = prmptr(curr + 1) - prmptr(curr)
              psiz2 = prmptr(curr + 2) - prmptr(curr + 1)
              do i = 0,psiz1 - 1
                 ztemp(i + 1) = z(zptr1 + perm(prmptr(curr) + i) - 1)
              end do
              do i = 0,psiz2 - 1
                 ztemp(psiz1 + i + 1) = z(mid + perm(prmptr(curr + 1) + i) - 1)
              end do
              ! multiply blocks at curr and curr+1
              ! determine size of these matrices.  we add half to the value of
              ! the sqrt in case the machine underestimates one of these
              ! square roots.
              bsiz1 = int(half + sqrt(real(qptr(curr + 1) - qptr(curr),KIND=qp)),KIND=ilp)

              bsiz2 = int(half + sqrt(real(qptr(curr + 2) - qptr(curr + 1),KIND=qp)),KIND=ilp)

              if (bsiz1 > 0) then
                 call la_qgemv('T',bsiz1,bsiz1,one,q(qptr(curr)),bsiz1,ztemp(1), &
                           1,zero,z(zptr1),1)
              end if
              call la_qcopy(psiz1 - bsiz1,ztemp(bsiz1 + 1),1,z(zptr1 + bsiz1),1)
              if (bsiz2 > 0) then
                 call la_qgemv('T',bsiz2,bsiz2,one,q(qptr(curr + 1)),bsiz2,ztemp( &
                           psiz1 + 1),1,zero,z(mid),1)
              end if
              call la_qcopy(psiz2 - bsiz2,ztemp(psiz1 + bsiz2 + 1),1,z(mid + bsiz2),1)

              ptr = ptr + 2**(tlvls - k)
           end do loop_70
           return
     end subroutine la_qlaeda

     !> DLAEIN: uses inverse iteration to find a right or left eigenvector
     !> corresponding to the eigenvalue (WR,WI) of a real upper Hessenberg
     !> matrix H.

     pure subroutine la_qlaein(rightv,noinit,n,h,ldh,wr,wi,vr,vi,b,ldb,work,eps3, &
               smlnum,bignum,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: noinit,rightv
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,ldh,n
           real(qp),intent(in) :: bignum,eps3,smlnum,wi,wr
           ! Array Arguments
           real(qp),intent(out) :: b(ldb,*),work(*)
           real(qp),intent(in) :: h(ldh,*)
           real(qp),intent(inout) :: vi(*),vr(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: tenth = 1.0e-1_qp

           ! Local Scalars
           character :: normin,trans
           integer(ilp) :: i,i1,i2,i3,ierr,its,j
           real(qp) :: absbii,absbjj,ei,ej,growto,norm,nrmsml,rec,rootn,scale,temp, &
                     vcrit,vmax,vnorm,w,w1,x,xi,xr,y
           ! Intrinsic Functions
           intrinsic :: abs,real,max,sqrt
           ! Executable Statements
           info = 0
           ! growto is the threshold used in the acceptance test for an
           ! eigenvector.
           rootn = sqrt(real(n,KIND=qp))
           growto = tenth/rootn
           nrmsml = max(one,eps3*rootn)*smlnum
           ! form b = h - (wr,wi)*i (except that the subdiagonal elements and
           ! the imaginary parts of the diagonal elements are not stored).
           do j = 1,n
              do i = 1,j - 1
                 b(i,j) = h(i,j)
              end do
              b(j,j) = h(j,j) - wr
           end do
           if (wi == zero) then
              ! real eigenvalue.
              if (noinit) then
                 ! set initial vector.
                 do i = 1,n
                    vr(i) = eps3
                 end do
              else
                 ! scale supplied initial vector.
                 vnorm = la_qnrm2(n,vr,1)
                 call la_qscal(n, (eps3*rootn)/max(vnorm,nrmsml),vr,1)
              end if
              if (rightv) then
                 ! lu decomposition with partial pivoting of b, replacing zero
                 ! pivots by eps3.
                 do i = 1,n - 1
                    ei = h(i + 1,i)
                    if (abs(b(i,i)) < abs(ei)) then
                       ! interchange rows and eliminate.
                       x = b(i,i)/ei
                       b(i,i) = ei
                       do j = i + 1,n
                          temp = b(i + 1,j)
                          b(i + 1,j) = b(i,j) - x*temp
                          b(i,j) = temp
                       end do
                    else
                       ! eliminate without interchange.
                       if (b(i,i) == zero) b(i,i) = eps3
                       x = ei/b(i,i)
                       if (x /= zero) then
                          do j = i + 1,n
                             b(i + 1,j) = b(i + 1,j) - x*b(i,j)
                          end do
                       end if
                    end if
                 end do
                 if (b(n,n) == zero) b(n,n) = eps3
                 trans = 'N'
              else
                 ! ul decomposition with partial pivoting of b, replacing zero
                 ! pivots by eps3.
                 do j = n,2,-1
                    ej = h(j,j - 1)
                    if (abs(b(j,j)) < abs(ej)) then
                       ! interchange columns and eliminate.
                       x = b(j,j)/ej
                       b(j,j) = ej
                       do i = 1,j - 1
                          temp = b(i,j - 1)
                          b(i,j - 1) = b(i,j) - x*temp
                          b(i,j) = temp
                       end do
                    else
                       ! eliminate without interchange.
                       if (b(j,j) == zero) b(j,j) = eps3
                       x = ej/b(j,j)
                       if (x /= zero) then
                          do i = 1,j - 1
                             b(i,j - 1) = b(i,j - 1) - x*b(i,j)
                          end do
                       end if
                    end if
                 end do
                 if (b(1,1) == zero) b(1,1) = eps3
                 trans = 'T'
              end if
              normin = 'N'
              do its = 1,n
                 ! solve u*x = scale*v for a right eigenvector
                   ! or u**t*x = scale*v for a left eigenvector,
                 ! overwriting x on v.
                 call la_qlatrs('UPPER',trans,'NONUNIT',normin,n,b,ldb,vr,scale,work, &
                            ierr)
                 normin = 'Y'
                 ! test for sufficient growth in the norm of v.
                 vnorm = la_qasum(n,vr,1)
                 if (vnorm >= growto*scale) go to 120
                 ! choose new orthogonal starting vector and try again.
                 temp = eps3/(rootn + one)
                 vr(1) = eps3
                 do i = 2,n
                    vr(i) = temp
                 end do
                 vr(n - its + 1) = vr(n - its + 1) - eps3*rootn
              end do
              ! failure to find eigenvector in n iterations.
              info = 1
              120 continue
              ! normalize eigenvector.
              i = la_iqamax(n,vr,1)
              call la_qscal(n,one/abs(vr(i)),vr,1)
           else
              ! complex eigenvalue.
              if (noinit) then
                 ! set initial vector.
                 do i = 1,n
                    vr(i) = eps3
                    vi(i) = zero
                 end do
              else
                 ! scale supplied initial vector.
                 norm = la_qlapy2(la_qnrm2(n,vr,1),la_qnrm2(n,vi,1))

                 rec = (eps3*rootn)/max(norm,nrmsml)
                 call la_qscal(n,rec,vr,1)
                 call la_qscal(n,rec,vi,1)
              end if
              if (rightv) then
                 ! lu decomposition with partial pivoting of b, replacing zero
                 ! pivots by eps3.
                 ! the imaginary part of the (i,j)-th element of u is stored in
                 ! b(j+1,i).
                 b(2,1) = -wi
                 do i = 2,n
                    b(i + 1,1) = zero
                 end do
                 loop_170: do i = 1,n - 1
                    absbii = la_qlapy2(b(i,i),b(i + 1,i))
                    ei = h(i + 1,i)
                    if (absbii < abs(ei)) then
                       ! interchange rows and eliminate.
                       xr = b(i,i)/ei
                       xi = b(i + 1,i)/ei
                       b(i,i) = ei
                       b(i + 1,i) = zero
                       do j = i + 1,n
                          temp = b(i + 1,j)
                          b(i + 1,j) = b(i,j) - xr*temp
                          b(j + 1,i + 1) = b(j + 1,i) - xi*temp
                          b(i,j) = temp
                          b(j + 1,i) = zero
                       end do
                       b(i + 2,i) = -wi
                       b(i + 1,i + 1) = b(i + 1,i + 1) - xi*wi
                       b(i + 2,i + 1) = b(i + 2,i + 1) + xr*wi
                    else
                       ! eliminate without interchanging rows.
                       if (absbii == zero) then
                          b(i,i) = eps3
                          b(i + 1,i) = zero
                          absbii = eps3
                       end if
                       ei = (ei/absbii)/absbii
                       xr = b(i,i)*ei
                       xi = -b(i + 1,i)*ei
                       do j = i + 1,n
                          b(i + 1,j) = b(i + 1,j) - xr*b(i,j) + xi*b(j + 1,i)
                          b(j + 1,i + 1) = -xr*b(j + 1,i) - xi*b(i,j)
                       end do
                       b(i + 2,i + 1) = b(i + 2,i + 1) - wi
                    end if
                    ! compute 1-norm of offdiagonal elements of i-th row.
                    work(i) = la_qasum(n - i,b(i,i + 1),ldb) + la_qasum(n - i,b(i + 2, &
                              i),1)
                 end do loop_170
                 if (b(n,n) == zero .and. b(n + 1,n) == zero) b(n,n) = eps3
                 work(n) = zero
                 i1 = n
                 i2 = 1
                 i3 = -1
              else
                 ! ul decomposition with partial pivoting of conjg(b),
                 ! replacing zero pivots by eps3.
                 ! the imaginary part of the (i,j)-th element of u is stored in
                 ! b(j+1,i).
                 b(n + 1,n) = wi
                 do j = 1,n - 1
                    b(n + 1,j) = zero
                 end do
                 loop_210: do j = n,2,-1
                    ej = h(j,j - 1)
                    absbjj = la_qlapy2(b(j,j),b(j + 1,j))
                    if (absbjj < abs(ej)) then
                       ! interchange columns and eliminate
                       xr = b(j,j)/ej
                       xi = b(j + 1,j)/ej
                       b(j,j) = ej
                       b(j + 1,j) = zero
                       do i = 1,j - 1
                          temp = b(i,j - 1)
                          b(i,j - 1) = b(i,j) - xr*temp
                          b(j,i) = b(j + 1,i) - xi*temp
                          b(i,j) = temp
                          b(j + 1,i) = zero
                       end do
                       b(j + 1,j - 1) = wi
                       b(j - 1,j - 1) = b(j - 1,j - 1) + xi*wi
                       b(j,j - 1) = b(j,j - 1) - xr*wi
                    else
                       ! eliminate without interchange.
                       if (absbjj == zero) then
                          b(j,j) = eps3
                          b(j + 1,j) = zero
                          absbjj = eps3
                       end if
                       ej = (ej/absbjj)/absbjj
                       xr = b(j,j)*ej
                       xi = -b(j + 1,j)*ej
                       do i = 1,j - 1
                          b(i,j - 1) = b(i,j - 1) - xr*b(i,j) + xi*b(j + 1,i)
                          b(j,i) = -xr*b(j + 1,i) - xi*b(i,j)
                       end do
                       b(j,j - 1) = b(j,j - 1) + wi
                    end if
                    ! compute 1-norm of offdiagonal elements of j-th column.
                    work(j) = la_qasum(j - 1,b(1,j),1) + la_qasum(j - 1,b(j + 1,1), &
                               ldb)
                 end do loop_210
                 if (b(1,1) == zero .and. b(2,1) == zero) b(1,1) = eps3
                 work(1) = zero
                 i1 = 1
                 i2 = n
                 i3 = 1
              end if
              loop_270: do its = 1,n
                 scale = one
                 vmax = one
                 vcrit = bignum
                 ! solve u*(xr,xi) = scale*(vr,vi) for a right eigenvector,
                   ! or u**t*(xr,xi) = scale*(vr,vi) for a left eigenvector,
                 ! overwriting (xr,xi) on (vr,vi).
                 loop_250: do i = i1,i2,i3
                    if (work(i) > vcrit) then
                       rec = one/vmax
                       call la_qscal(n,rec,vr,1)
                       call la_qscal(n,rec,vi,1)
                       scale = scale*rec
                       vmax = one
                       vcrit = bignum
                    end if
                    xr = vr(i)
                    xi = vi(i)
                    if (rightv) then
                       do j = i + 1,n
                          xr = xr - b(i,j)*vr(j) + b(j + 1,i)*vi(j)
                          xi = xi - b(i,j)*vi(j) - b(j + 1,i)*vr(j)
                       end do
                    else
                       do j = 1,i - 1
                          xr = xr - b(j,i)*vr(j) + b(i + 1,j)*vi(j)
                          xi = xi - b(j,i)*vi(j) - b(i + 1,j)*vr(j)
                       end do
                    end if
                    w = abs(b(i,i)) + abs(b(i + 1,i))
                    if (w > smlnum) then
                       if (w < one) then
                          w1 = abs(xr) + abs(xi)
                          if (w1 > w*bignum) then
                             rec = one/w1
                             call la_qscal(n,rec,vr,1)
                             call la_qscal(n,rec,vi,1)
                             xr = vr(i)
                             xi = vi(i)
                             scale = scale*rec
                             vmax = vmax*rec
                          end if
                       end if
                       ! divide by diagonal element of b.
                       call la_qladiv(xr,xi,b(i,i),b(i + 1,i),vr(i),vi(i))

                       vmax = max(abs(vr(i)) + abs(vi(i)),vmax)
                       vcrit = bignum/vmax
                    else
                       do j = 1,n
                          vr(j) = zero
                          vi(j) = zero
                       end do
                       vr(i) = one
                       vi(i) = one
                       scale = zero
                       vmax = one
                       vcrit = bignum
                    end if
                 end do loop_250
                 ! test for sufficient growth in the norm of (vr,vi).
                 vnorm = la_qasum(n,vr,1) + la_qasum(n,vi,1)
                 if (vnorm >= growto*scale) go to 280
                 ! choose a new orthogonal starting vector and try again.
                 y = eps3/(rootn + one)
                 vr(1) = eps3
                 vi(1) = zero
                 do i = 2,n
                    vr(i) = y
                    vi(i) = zero
                 end do
                 vr(n - its + 1) = vr(n - its + 1) - eps3*rootn
              end do loop_270
              ! failure to find eigenvector in n iterations
              info = 1
              280 continue
              ! normalize eigenvector.
              vnorm = zero
              do i = 1,n
                 vnorm = max(vnorm,abs(vr(i)) + abs(vi(i)))
              end do
              call la_qscal(n,one/vnorm,vr,1)
              call la_qscal(n,one/vnorm,vi,1)
           end if
           return
     end subroutine la_qlaein

     !> DLAEV2: computes the eigendecomposition of a 2-by-2 symmetric matrix
     !> [  A   B  ]
     !> [  B   C  ].
     !> On return, RT1 is the eigenvalue of larger absolute value, RT2 is the
     !> eigenvalue of smaller absolute value, and (CS1,SN1) is the unit right
     !> eigenvector for RT1, giving the decomposition
     !> [ CS1  SN1 ] [  A   B  ] [ CS1 -SN1 ]  =  [ RT1  0  ]
     !> [-SN1  CS1 ] [  B   C  ] [ SN1  CS1 ]     [  0  RT2 ].

     pure subroutine la_qlaev2(a,b,c,rt1,rt2,cs1,sn1)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           real(qp),intent(in) :: a,b,c
           real(qp),intent(out) :: cs1,rt1,rt2,sn1
       ! =====================================================================

           ! Local Scalars
           integer(ilp) :: sgn1,sgn2
           real(qp) :: ab,acmn,acmx,acs,adf,cs,ct,df,rt,sm,tb,tn
           ! Intrinsic Functions
           intrinsic :: abs,sqrt
           ! Executable Statements
           ! compute the eigenvalues
           sm = a + c
           df = a - c
           adf = abs(df)
           tb = b + b
           ab = abs(tb)
           if (abs(a) > abs(c)) then
              acmx = a
              acmn = c
           else
              acmx = c
              acmn = a
           end if
           if (adf > ab) then
              rt = adf*sqrt(one + (ab/adf)**2)
           else if (adf < ab) then
              rt = ab*sqrt(one + (adf/ab)**2)
           else
              ! includes case ab=adf=0
              rt = ab*sqrt(two)
           end if
           if (sm < zero) then
              rt1 = half*(sm - rt)
              sgn1 = -1
              ! order of execution important.
              ! to get fully accurate smaller eigenvalue,
              ! next line needs to be executed in higher precision.
              rt2 = (acmx/rt1)*acmn - (b/rt1)*b
           else if (sm > zero) then
              rt1 = half*(sm + rt)
              sgn1 = 1
              ! order of execution important.
              ! to get fully accurate smaller eigenvalue,
              ! next line needs to be executed in higher precision.
              rt2 = (acmx/rt1)*acmn - (b/rt1)*b
           else
              ! includes case rt1 = rt2 = 0
              rt1 = half*rt
              rt2 = -half*rt
              sgn1 = 1
           end if
           ! compute the eigenvector
           if (df >= zero) then
              cs = df + rt
              sgn2 = 1
           else
              cs = df - rt
              sgn2 = -1
           end if
           acs = abs(cs)
           if (acs > ab) then
              ct = -tb/cs
              sn1 = one/sqrt(one + ct*ct)
              cs1 = ct*sn1
           else
              if (ab == zero) then
                 cs1 = one
                 sn1 = zero
              else
                 tn = -cs/tb
                 cs1 = one/sqrt(one + tn*tn)
                 sn1 = tn*cs1
              end if
           end if
           if (sgn1 == sgn2) then
              tn = cs1
              cs1 = -sn1
              sn1 = tn
           end if
           return
     end subroutine la_qlaev2

     !> DLAG2: computes the eigenvalues of a 2 x 2 generalized eigenvalue
     !> problem  A - w B, with scaling as necessary to avoid over-/underflow.
     !> The scaling factor "s" results in a modified eigenvalue equation
     !> s A - w B
     !> where  s  is a non-negative scaling factor chosen so that  w,  w B,
     !> and  s A  do not overflow and, if possible, do not underflow, either.

     pure subroutine la_qlag2(a,lda,b,ldb,safmin,scale1,scale2,wr1,wr2,wi)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: lda,ldb
           real(qp),intent(in) :: safmin
           real(qp),intent(out) :: scale1,scale2,wi,wr1,wr2
           ! Array Arguments
           real(qp),intent(in) :: a(lda,*),b(ldb,*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: fuzzy1 = one + 1.0e-5_qp

           ! Local Scalars
           real(qp) :: a11,a12,a21,a22,abi22,anorm,as11,as12,as22,ascale,b11,b12,b22, &
           binv11,binv22,bmin,bnorm,bscale,bsize,c1,c2,c3,c4,c5,diff,discr,pp,qq,r, &
            rtmax,rtmin,s1,s2,safmax,shift,ss,sum,wabs,wbig,wdet,wscale,wsize, &
                      wsmall
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sign,sqrt
           ! Executable Statements
           rtmin = sqrt(safmin)
           rtmax = one/rtmin
           safmax = one/safmin
           ! scale a
           anorm = max(abs(a(1,1)) + abs(a(2,1)),abs(a(1,2)) + abs(a(2,2)), &
                     safmin)
           ascale = one/anorm
           a11 = ascale*a(1,1)
           a21 = ascale*a(2,1)
           a12 = ascale*a(1,2)
           a22 = ascale*a(2,2)
           ! perturb b if necessary to insure non-singularity
           b11 = b(1,1)
           b12 = b(1,2)
           b22 = b(2,2)
           bmin = rtmin*max(abs(b11),abs(b12),abs(b22),rtmin)
           if (abs(b11) < bmin) b11 = sign(bmin,b11)
           if (abs(b22) < bmin) b22 = sign(bmin,b22)
           ! scale b
           bnorm = max(abs(b11),abs(b12) + abs(b22),safmin)
           bsize = max(abs(b11),abs(b22))
           bscale = one/bsize
           b11 = b11*bscale
           b12 = b12*bscale
           b22 = b22*bscale
           ! compute larger eigenvalue by method described by c. van loan
           ! ( as is a shifted by -shift*b )
           binv11 = one/b11
           binv22 = one/b22
           s1 = a11*binv11
           s2 = a22*binv22
           if (abs(s1) <= abs(s2)) then
              as12 = a12 - s1*b12
              as22 = a22 - s1*b22
              ss = a21*(binv11*binv22)
              abi22 = as22*binv22 - ss*b12
              pp = half*abi22
              shift = s1
           else
              as12 = a12 - s2*b12
              as11 = a11 - s2*b11
              ss = a21*(binv11*binv22)
              abi22 = -ss*b12
              pp = half*(as11*binv11 + abi22)
              shift = s2
           end if
           qq = ss*as12
           if (abs(pp*rtmin) >= one) then
              discr = (rtmin*pp)**2 + qq*safmin
              r = sqrt(abs(discr))*rtmax
           else
              if (pp**2 + abs(qq) <= safmin) then
                 discr = (rtmax*pp)**2 + qq*safmax
                 r = sqrt(abs(discr))*rtmin
              else
                 discr = pp**2 + qq
                 r = sqrt(abs(discr))
              end if
           end if
           ! note: the test of r in the following if is to cover the case when
                 ! discr is small and negative and is flushed to zero during
                 ! the calculation of r.  on machines which have a consistent
                 ! flush-to-zero threshold and handle numbers above that
                 ! threshold correctly, it would not be necessary.
           if (discr >= zero .or. r == zero) then
              sum = pp + sign(r,pp)
              diff = pp - sign(r,pp)
              wbig = shift + sum
              ! compute smaller eigenvalue
              wsmall = shift + diff
              if (half*abs(wbig) > max(abs(wsmall),safmin)) then
                 wdet = (a11*a22 - a12*a21)*(binv11*binv22)
                 wsmall = wdet/wbig
              end if
              ! choose (real) eigenvalue closest to 2,2 element of a*b**(-1)
              ! for wr1.
              if (pp > abi22) then
                 wr1 = min(wbig,wsmall)
                 wr2 = max(wbig,wsmall)
              else
                 wr1 = max(wbig,wsmall)
                 wr2 = min(wbig,wsmall)
              end if
              wi = zero
           else
              ! complex eigenvalues
              wr1 = shift + pp
              wr2 = wr1
              wi = r
           end if
           ! further scaling to avoid underflow and overflow in computing
           ! scale1 and overflow in computing w*b.
           ! this scale factor (wscale) is bounded from above using c1 and c2,
           ! and from below using c3 and c4.
              ! c1 implements the condition  s a  must never overflow.
              ! c2 implements the condition  w b  must never overflow.
              ! c3, with c2,
                 ! implement the condition that s a - w b must never overflow.
              ! c4 implements the condition  s    should not underflow.
              ! c5 implements the condition  max(s,|w|) should be at least 2.
           c1 = bsize*(safmin*max(one,ascale))
           c2 = safmin*max(one,bnorm)
           c3 = bsize*safmin
           if (ascale <= one .and. bsize <= one) then
              c4 = min(one, (ascale/safmin)*bsize)
           else
              c4 = one
           end if
           if (ascale <= one .or. bsize <= one) then
              c5 = min(one,ascale*bsize)
           else
              c5 = one
           end if
           ! scale first eigenvalue
           wabs = abs(wr1) + abs(wi)
           wsize = max(safmin,c1,fuzzy1*(wabs*c2 + c3),min(c4,half*max(wabs,c5)))

           if (wsize /= one) then
              wscale = one/wsize
              if (wsize > one) then
                 scale1 = (max(ascale,bsize)*wscale)*min(ascale,bsize)
              else
                 scale1 = (min(ascale,bsize)*wscale)*max(ascale,bsize)
              end if
              wr1 = wr1*wscale
              if (wi /= zero) then
                 wi = wi*wscale
                 wr2 = wr1
                 scale2 = scale1
              end if
           else
              scale1 = ascale*bsize
              scale2 = scale1
           end if
           ! scale second eigenvalue (if real)
           if (wi == zero) then
              wsize = max(safmin,c1,fuzzy1*(abs(wr2)*c2 + c3),min(c4,half*max(abs(wr2), &
                        c5)))
              if (wsize /= one) then
                 wscale = one/wsize
                 if (wsize > one) then
                    scale2 = (max(ascale,bsize)*wscale)*min(ascale,bsize)
                 else
                    scale2 = (min(ascale,bsize)*wscale)*max(ascale,bsize)
                 end if
                 wr2 = wr2*wscale
              else
                 scale2 = ascale*bsize
              end if
           end if
           return
     end subroutine la_qlag2

     !> DLAGTF: factorizes the matrix (T - lambda*I), where T is an n by n
     !> tridiagonal matrix and lambda is a scalar, as
     !> T - lambda*I = PLU,
     !> where P is a permutation matrix, L is a unit lower tridiagonal matrix
     !> with at most one non-zero sub-diagonal elements per column and U is
     !> an upper triangular matrix with at most two non-zero super-diagonal
     !> elements per column.
     !> The factorization is obtained by Gaussian elimination with partial
     !> pivoting and implicit row scaling.
     !> The parameter LAMBDA is included in the routine so that DLAGTF may
     !> be used, in conjunction with DLAGTS, to obtain eigenvectors of T by
     !> inverse iteration.

     pure subroutine la_qlagtf(n,a,lambda,b,c,tol,d,in,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           real(qp),intent(in) :: lambda,tol
           ! Array Arguments
           integer(ilp),intent(out) :: in(*)
           real(qp),intent(inout) :: a(*),b(*),c(*)
           real(qp),intent(out) :: d(*)
       ! =====================================================================

           ! Local Scalars
           integer(ilp) :: k
           real(qp) :: eps,mult,piv1,piv2,scale1,scale2,temp,tl
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           info = 0
           if (n < 0) then
              info = -1
              call la_xerbla('DLAGTF',-info)
              return
           end if
           if (n == 0) return
           a(1) = a(1) - lambda
           in(n) = 0
           if (n == 1) then
              if (a(1) == zero) in(1) = 1
              return
           end if
           eps = la_qlamch('EPSILON')
           tl = max(tol,eps)
           scale1 = abs(a(1)) + abs(b(1))
           loop_10: do k = 1,n - 1
              a(k + 1) = a(k + 1) - lambda
              scale2 = abs(c(k)) + abs(a(k + 1))
              if (k < (n - 1)) scale2 = scale2 + abs(b(k + 1))
              if (a(k) == zero) then
                 piv1 = zero
              else
                 piv1 = abs(a(k))/scale1
              end if
              if (c(k) == zero) then
                 in(k) = 0
                 piv2 = zero
                 scale1 = scale2
                 if (k < (n - 1)) d(k) = zero
              else
                 piv2 = abs(c(k))/scale2
                 if (piv2 <= piv1) then
                    in(k) = 0
                    scale1 = scale2
                    c(k) = c(k)/a(k)
                    a(k + 1) = a(k + 1) - c(k)*b(k)
                    if (k < (n - 1)) d(k) = zero
                 else
                    in(k) = 1
                    mult = a(k)/c(k)
                    a(k) = c(k)
                    temp = a(k + 1)
                    a(k + 1) = b(k) - mult*temp
                    if (k < (n - 1)) then
                       d(k) = b(k + 1)
                       b(k + 1) = -mult*d(k)
                    end if
                    b(k) = temp
                    c(k) = mult
                 end if
              end if
              if ((max(piv1,piv2) <= tl) .and. (in(n) == 0)) in(n) = k
           end do loop_10
           if ((abs(a(n)) <= scale1*tl) .and. (in(n) == 0)) in(n) = n
           return
     end subroutine la_qlagtf

     !> DLAGTS: may be used to solve one of the systems of equations
     !> (T - lambda*I)*x = y   or   (T - lambda*I)**T*x = y,
     !> where T is an n by n tridiagonal matrix, for x, following the
     !> factorization of (T - lambda*I) as
     !> (T - lambda*I) = P*L*U ,
     !> by routine DLAGTF. The choice of equation to be solved is
     !> controlled by the argument JOB, and in each case there is an option
     !> to perturb zero or very small diagonal elements of U, this option
     !> being intended for use in applications such as inverse iteration.

     pure subroutine la_qlagts(job,n,a,b,c,d,in,y,tol,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: job,n
           real(qp),intent(inout) :: tol
           ! Array Arguments
           integer(ilp),intent(in) :: in(*)
           real(qp),intent(in) :: a(*),b(*),c(*),d(*)
           real(qp),intent(inout) :: y(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: k
           real(qp) :: absak,ak,bignum,eps,pert,sfmin,temp
           ! Intrinsic Functions
           intrinsic :: abs,max,sign
           ! Executable Statements
           info = 0
           if ((abs(job) > 2) .or. (job == 0)) then
              info = -1
           else if (n < 0) then
              info = -2
           end if
           if (info /= 0) then
              call la_xerbla('DLAGTS',-info)
              return
           end if
           if (n == 0) return
           eps = la_qlamch('EPSILON')
           sfmin = la_qlamch('SAFE MINIMUM')
           bignum = one/sfmin
           if (job < 0) then
              if (tol <= zero) then
                 tol = abs(a(1))
                 if (n > 1) tol = max(tol,abs(a(2)),abs(b(1)))
                 do k = 3,n
                    tol = max(tol,abs(a(k)),abs(b(k - 1)),abs(d(k - 2)))
                 end do
                 tol = tol*eps
                 if (tol == zero) tol = eps
              end if
           end if
           if (abs(job) == 1) then
              do k = 2,n
                 if (in(k - 1) == 0) then
                    y(k) = y(k) - c(k - 1)*y(k - 1)
                 else
                    temp = y(k - 1)
                    y(k - 1) = y(k)
                    y(k) = temp - c(k - 1)*y(k)
                 end if
              end do
              if (job == 1) then
                 loop_30: do k = n,1,-1
                    if (k <= n - 2) then
                       temp = y(k) - b(k)*y(k + 1) - d(k)*y(k + 2)
                    else if (k == n - 1) then
                       temp = y(k) - b(k)*y(k + 1)
                    else
                       temp = y(k)
                    end if
                    ak = a(k)
                    absak = abs(ak)
                    if (absak < one) then
                       if (absak < sfmin) then
                          if (absak == zero .or. abs(temp)*sfmin > absak) then
                             info = k
                             return
                          else
                             temp = temp*bignum
                             ak = ak*bignum
                          end if
                       else if (abs(temp) > absak*bignum) then
                          info = k
                          return
                       end if
                    end if
                    y(k) = temp/ak
                 end do loop_30
              else
                 loop_50: do k = n,1,-1
                    if (k <= n - 2) then
                       temp = y(k) - b(k)*y(k + 1) - d(k)*y(k + 2)
                    else if (k == n - 1) then
                       temp = y(k) - b(k)*y(k + 1)
                    else
                       temp = y(k)
                    end if
                    ak = a(k)
                    pert = sign(tol,ak)
                    40 continue
                    absak = abs(ak)
                    if (absak < one) then
                       if (absak < sfmin) then
                          if (absak == zero .or. abs(temp)*sfmin > absak) then
                             ak = ak + pert
                             pert = 2*pert
                             go to 40
                          else
                             temp = temp*bignum
                             ak = ak*bignum
                          end if
                       else if (abs(temp) > absak*bignum) then
                          ak = ak + pert
                          pert = 2*pert
                          go to 40
                       end if
                    end if
                    y(k) = temp/ak
                 end do loop_50
              end if
           else
              ! come to here if  job = 2 or -2
              if (job == 2) then
                 loop_60: do k = 1,n
                    if (k >= 3) then
                       temp = y(k) - b(k - 1)*y(k - 1) - d(k - 2)*y(k - 2)
                    else if (k == 2) then
                       temp = y(k) - b(k - 1)*y(k - 1)
                    else
                       temp = y(k)
                    end if
                    ak = a(k)
                    absak = abs(ak)
                    if (absak < one) then
                       if (absak < sfmin) then
                          if (absak == zero .or. abs(temp)*sfmin > absak) then
                             info = k
                             return
                          else
                             temp = temp*bignum
                             ak = ak*bignum
                          end if
                       else if (abs(temp) > absak*bignum) then
                          info = k
                          return
                       end if
                    end if
                    y(k) = temp/ak
                 end do loop_60
              else
                 loop_80: do k = 1,n
                    if (k >= 3) then
                       temp = y(k) - b(k - 1)*y(k - 1) - d(k - 2)*y(k - 2)
                    else if (k == 2) then
                       temp = y(k) - b(k - 1)*y(k - 1)
                    else
                       temp = y(k)
                    end if
                    ak = a(k)
                    pert = sign(tol,ak)
                    70 continue
                    absak = abs(ak)
                    if (absak < one) then
                       if (absak < sfmin) then
                          if (absak == zero .or. abs(temp)*sfmin > absak) then
                             ak = ak + pert
                             pert = 2*pert
                             go to 70
                          else
                             temp = temp*bignum
                             ak = ak*bignum
                          end if
                       else if (abs(temp) > absak*bignum) then
                          ak = ak + pert
                          pert = 2*pert
                          go to 70
                       end if
                    end if
                    y(k) = temp/ak
                 end do loop_80
              end if
              do k = n,2,-1
                 if (in(k - 1) == 0) then
                    y(k - 1) = y(k - 1) - c(k - 1)*y(k)
                 else
                    temp = y(k - 1)
                    y(k - 1) = y(k)
                    y(k) = temp - c(k - 1)*y(k)
                 end if
              end do
           end if
     end subroutine la_qlagts

     !> DLAGV2: computes the Generalized Schur factorization of a real 2-by-2
     !> matrix pencil (A,B) where B is upper triangular. This routine
     !> computes orthogonal (rotation) matrices given by CSL, SNL and CSR,
     !> SNR such that
     !> 1) if the pencil (A,B) has two real eigenvalues (include 0/0 or 1/0
     !> types), then
     !> [ a11 a12 ] := [  CSL  SNL ] [ a11 a12 ] [  CSR -SNR ]
     !> [  0  a22 ]    [ -SNL  CSL ] [ a21 a22 ] [  SNR  CSR ]
     !> [ b11 b12 ] := [  CSL  SNL ] [ b11 b12 ] [  CSR -SNR ]
     !> [  0  b22 ]    [ -SNL  CSL ] [  0  b22 ] [  SNR  CSR ],
     !> 2) if the pencil (A,B) has a pair of complex conjugate eigenvalues,
     !> then
     !> [ a11 a12 ] := [  CSL  SNL ] [ a11 a12 ] [  CSR -SNR ]
     !> [ a21 a22 ]    [ -SNL  CSL ] [ a21 a22 ] [  SNR  CSR ]
     !> [ b11  0  ] := [  CSL  SNL ] [ b11 b12 ] [  CSR -SNR ]
     !> [  0  b22 ]    [ -SNL  CSL ] [  0  b22 ] [  SNR  CSR ]
     !> where b11 >= b22 > 0.

     pure subroutine la_qlagv2(a,lda,b,ldb,alphar,alphai,beta,csl,snl,csr,snr)

        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: lda,ldb
           real(qp),intent(out) :: csl,csr,snl,snr
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: alphai(2),alphar(2),beta(2)
        ! =====================================================================

           ! Local Scalars
           real(qp) :: anorm,ascale,bnorm,bscale,h1,h2,h3,qq,r,rr,safmin,scale1, &
                     scale2,t,ulp,wi,wr1,wr2
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           safmin = la_qlamch('S')
           ulp = la_qlamch('P')
           ! scale a
           anorm = max(abs(a(1,1)) + abs(a(2,1)),abs(a(1,2)) + abs(a(2,2)), &
                     safmin)
           ascale = one/anorm
           a(1,1) = ascale*a(1,1)
           a(1,2) = ascale*a(1,2)
           a(2,1) = ascale*a(2,1)
           a(2,2) = ascale*a(2,2)
           ! scale b
           bnorm = max(abs(b(1,1)),abs(b(1,2)) + abs(b(2,2)),safmin)
           bscale = one/bnorm
           b(1,1) = bscale*b(1,1)
           b(1,2) = bscale*b(1,2)
           b(2,2) = bscale*b(2,2)
           ! check if a can be deflated
           if (abs(a(2,1)) <= ulp) then
              csl = one
              snl = zero
              csr = one
              snr = zero
              a(2,1) = zero
              b(2,1) = zero
              wi = zero
           ! check if b is singular
           else if (abs(b(1,1)) <= ulp) then
              call la_qlartg(a(1,1),a(2,1),csl,snl,r)
              csr = one
              snr = zero
              call la_qrot(2,a(1,1),lda,a(2,1),lda,csl,snl)
              call la_qrot(2,b(1,1),ldb,b(2,1),ldb,csl,snl)
              a(2,1) = zero
              b(1,1) = zero
              b(2,1) = zero
              wi = zero
           else if (abs(b(2,2)) <= ulp) then
              call la_qlartg(a(2,2),a(2,1),csr,snr,t)
              snr = -snr
              call la_qrot(2,a(1,1),1,a(1,2),1,csr,snr)
              call la_qrot(2,b(1,1),1,b(1,2),1,csr,snr)
              csl = one
              snl = zero
              a(2,1) = zero
              b(2,1) = zero
              b(2,2) = zero
              wi = zero
           else
              ! b is nonsingular, first compute the eigenvalues of (a,b)
              call la_qlag2(a,lda,b,ldb,safmin,scale1,scale2,wr1,wr2,wi)
              if (wi == zero) then
                 ! two real eigenvalues, compute s*a-w*b
                 h1 = scale1*a(1,1) - wr1*b(1,1)
                 h2 = scale1*a(1,2) - wr1*b(1,2)
                 h3 = scale1*a(2,2) - wr1*b(2,2)
                 rr = la_qlapy2(h1,h2)
                 qq = la_qlapy2(scale1*a(2,1),h3)
                 if (rr > qq) then
                    ! find right rotation matrix to zero 1,1 element of
                    ! (sa - wb)
                    call la_qlartg(h2,h1,csr,snr,t)
                 else
                    ! find right rotation matrix to zero 2,1 element of
                    ! (sa - wb)
                    call la_qlartg(h3,scale1*a(2,1),csr,snr,t)
                 end if
                 snr = -snr
                 call la_qrot(2,a(1,1),1,a(1,2),1,csr,snr)
                 call la_qrot(2,b(1,1),1,b(1,2),1,csr,snr)
                 ! compute inf norms of a and b
                 h1 = max(abs(a(1,1)) + abs(a(1,2)),abs(a(2,1)) + abs(a(2,2)))

                 h2 = max(abs(b(1,1)) + abs(b(1,2)),abs(b(2,1)) + abs(b(2,2)))

                 if ((scale1*h1) >= abs(wr1)*h2) then
                    ! find left rotation matrix q to zero out b(2,1)
                    call la_qlartg(b(1,1),b(2,1),csl,snl,r)
                 else
                    ! find left rotation matrix q to zero out a(2,1)
                    call la_qlartg(a(1,1),a(2,1),csl,snl,r)
                 end if
                 call la_qrot(2,a(1,1),lda,a(2,1),lda,csl,snl)
                 call la_qrot(2,b(1,1),ldb,b(2,1),ldb,csl,snl)
                 a(2,1) = zero
                 b(2,1) = zero
              else
                 ! a pair of complex conjugate eigenvalues
                 ! first compute the svd of the matrix b
                 call la_qlasv2(b(1,1),b(1,2),b(2,2),r,t,snr,csr,snl,csl)

                 ! form (a,b) := q(a,b)z**t where q is left rotation matrix and
                 ! z is right rotation matrix computed from la_qlasv2
                 call la_qrot(2,a(1,1),lda,a(2,1),lda,csl,snl)
                 call la_qrot(2,b(1,1),ldb,b(2,1),ldb,csl,snl)
                 call la_qrot(2,a(1,1),1,a(1,2),1,csr,snr)
                 call la_qrot(2,b(1,1),1,b(1,2),1,csr,snr)
                 b(2,1) = zero
                 b(1,2) = zero
              end if
           end if
           ! unscaling
           a(1,1) = anorm*a(1,1)
           a(2,1) = anorm*a(2,1)
           a(1,2) = anorm*a(1,2)
           a(2,2) = anorm*a(2,2)
           b(1,1) = bnorm*b(1,1)
           b(2,1) = bnorm*b(2,1)
           b(1,2) = bnorm*b(1,2)
           b(2,2) = bnorm*b(2,2)
           if (wi == zero) then
              alphar(1) = a(1,1)
              alphar(2) = a(2,2)
              alphai(1) = zero
              alphai(2) = zero
              beta(1) = b(1,1)
              beta(2) = b(2,2)
           else
              alphar(1) = anorm*wr1/scale1/bnorm
              alphai(1) = anorm*wi/scale1/bnorm
              alphar(2) = alphar(1)
              alphai(2) = -alphai(1)
              beta(1) = one
              beta(2) = one
           end if
           return
     end subroutine la_qlagv2

     !> DLAHQR: is an auxiliary routine called by DHSEQR to update the
     !> eigenvalues and Schur decomposition already computed by DHSEQR, by
     !> dealing with the Hessenberg submatrix in rows and columns ILO to
     !> IHI.

     pure subroutine la_qlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz, &
               info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(qp),intent(out) :: wi(*),wr(*)
        ! =========================================================
           ! Parameters
           real(qp),parameter :: dat1 = 3.0_qp/4.0_qp
           real(qp),parameter :: dat2 = -0.4375_qp
           integer(ilp),parameter :: kexsh = 10

           ! Local Scalars
           real(qp) :: aa,ab,ba,bb,cs,det,h11,h12,h21,h21s,h22,rt1i,rt1r,rt2i,rt2r, &
                     rtdisc,s,safmax,safmin,smlnum,sn,sum,t1,t2,t3,tr,tst,ulp,v2,v3
           integer(ilp) :: i,i1,i2,its,itmax,j,k,l,m,nh,nr,nz,kdefl
           ! Local Arrays
           real(qp) :: v(3)
           ! Intrinsic Functions
           intrinsic :: abs,real,max,min,sqrt
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n == 0) return
           if (ilo == ihi) then
              wr(ilo) = h(ilo,ilo)
              wi(ilo) = zero
              return
           end if
           ! ==== clear out the trash ====
           do j = ilo,ihi - 3
              h(j + 2,j) = zero
              h(j + 3,j) = zero
           end do
           if (ilo <= ihi - 2) h(ihi,ihi - 2) = zero
           nh = ihi - ilo + 1
           nz = ihiz - iloz + 1
           ! set machine-dependent constants for the stopping criterion.
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(nh,KIND=qp)/ulp)
           ! i1 and i2 are the indices of the first row and last column of h
           ! to which transformations must be applied. if eigenvalues only are
           ! being computed, i1 and i2 are set inside the main loop.
           if (wantt) then
              i1 = 1
              i2 = n
           end if
           ! itmax is the total number of qr iterations allowed.
           itmax = 30*max(10,nh)
           ! kdefl counts the number of iterations since a deflation
           kdefl = 0
           ! the main loop begins here. i is the loop index and decreases from
           ! ihi to ilo in steps of 1 or 2. each iteration of the loop works
           ! with the active submatrix in rows and columns l to i.
           ! eigenvalues i+1 to ihi have already converged. either l = ilo or
           ! h(l,l-1) is negligible so that the matrix splits.
           i = ihi
           20 continue
           l = ilo
           if (i < ilo) go to 160
           ! perform qr iterations on rows and columns ilo to i until a
           ! submatrix of order 1 or 2 splits off at the bottom because a
           ! subdiagonal element has become negligible.
           loop_140: do its = 0,itmax
              ! look for a single small subdiagonal element.
              do k = i,l + 1,-1
                 if (abs(h(k,k - 1)) <= smlnum) go to 40
                 tst = abs(h(k - 1,k - 1)) + abs(h(k,k))
                 if (tst == zero) then
                    if (k - 2 >= ilo) tst = tst + abs(h(k - 1,k - 2))
                    if (k + 1 <= ihi) tst = tst + abs(h(k + 1,k))
                 end if
                 ! ==== the following is a conservative small subdiagonal
                 ! .    deflation  criterion due to ahues
                 ! .    1997). it has better mathematical foundation and
                 ! .    improves accuracy in some cases.  ====
                 if (abs(h(k,k - 1)) <= ulp*tst) then
                    ab = max(abs(h(k,k - 1)),abs(h(k - 1,k)))
                    ba = min(abs(h(k,k - 1)),abs(h(k - 1,k)))
                    aa = max(abs(h(k,k)),abs(h(k - 1,k - 1) - h(k,k)))
                    bb = min(abs(h(k,k)),abs(h(k - 1,k - 1) - h(k,k)))
                    s = aa + ab
                    if (ba*(ab/s) <= max(smlnum,ulp*(bb*(aa/s)))) go to 40
                 end if
              end do
              40 continue
              l = k
              if (l > ilo) then
                 ! h(l,l-1) is negligible
                 h(l,l - 1) = zero
              end if
              ! exit from loop if a submatrix of order 1 or 2 has split off.
              if (l >= i - 1) go to 150
              kdefl = kdefl + 1
              ! now the active submatrix is in rows and columns l to i. if
              ! eigenvalues only are being computed, only the active submatrix
              ! need be transformed.
              if (.not. wantt) then
                 i1 = l
                 i2 = i
              end if
              if (mod(kdefl,2*kexsh) == 0) then
                 ! exceptional shift.
                 s = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                 h11 = dat1*s + h(i,i)
                 h12 = dat2*s
                 h21 = s
                 h22 = h11
              else if (mod(kdefl,kexsh) == 0) then
                 ! exceptional shift.
                 s = abs(h(l + 1,l)) + abs(h(l + 2,l + 1))
                 h11 = dat1*s + h(l,l)
                 h12 = dat2*s
                 h21 = s
                 h22 = h11
              else
                 ! prepare to use francis' double shift
                 ! (i.e. 2nd degree generalized rayleigh quotient)
                 h11 = h(i - 1,i - 1)
                 h21 = h(i,i - 1)
                 h12 = h(i - 1,i)
                 h22 = h(i,i)
              end if
              s = abs(h11) + abs(h12) + abs(h21) + abs(h22)
              if (s == zero) then
                 rt1r = zero
                 rt1i = zero
                 rt2r = zero
                 rt2i = zero
              else
                 h11 = h11/s
                 h21 = h21/s
                 h12 = h12/s
                 h22 = h22/s
                 tr = (h11 + h22)/two
                 det = (h11 - tr)*(h22 - tr) - h12*h21
                 rtdisc = sqrt(abs(det))
                 if (det >= zero) then
                    ! ==== complex conjugate shifts ====
                    rt1r = tr*s
                    rt2r = rt1r
                    rt1i = rtdisc*s
                    rt2i = -rt1i
                 else
                    ! ==== realshifts (use only one of them,KIND=qp)  ====
                    rt1r = tr + rtdisc
                    rt2r = tr - rtdisc
                    if (abs(rt1r - h22) <= abs(rt2r - h22)) then
                       rt1r = rt1r*s
                       rt2r = rt1r
                    else
                       rt2r = rt2r*s
                       rt1r = rt2r
                    end if
                    rt1i = zero
                    rt2i = zero
                 end if
              end if
              ! look for two consecutive small subdiagonal elements.
              do m = i - 2,l,-1
                 ! determine the effect of starting the double-shift qr
                 ! iteration at row m, and see if this would make h(m,m-1)
                 ! negligible.  (the following uses scaling to avoid
                 ! overflows and most underflows.)
                 h21s = h(m + 1,m)
                 s = abs(h(m,m) - rt2r) + abs(rt2i) + abs(h21s)
                 h21s = h(m + 1,m)/s
                 v(1) = h21s*h(m,m + 1) + (h(m,m) - rt1r)*((h(m,m) - rt2r)/s) - &
                           rt1i*(rt2i/s)
                 v(2) = h21s*(h(m,m) + h(m + 1,m + 1) - rt1r - rt2r)
                 v(3) = h21s*h(m + 2,m + 1)
                 s = abs(v(1)) + abs(v(2)) + abs(v(3))
                 v(1) = v(1)/s
                 v(2) = v(2)/s
                 v(3) = v(3)/s
                 if (m == l) go to 60
                 if (abs(h(m,m - 1))*(abs(v(2)) + abs(v(3))) <= ulp*abs(v(1))*(abs( &
                           h(m - 1,m - 1)) + abs(h(m,m)) + abs(h(m + 1,m + 1)))) go to 60
              end do
              60 continue
              ! double-shift qr step
              loop_130: do k = m,i - 1
                 ! the first iteration of this loop determines a reflection g
                 ! from the vector v and applies it from left and right to h,
                 ! thus creating a nonzero bulge below the subdiagonal.
                 ! each subsequent iteration determines a reflection g to
                 ! restore the hessenberg form in the (k-1)th column, and thus
                 ! chases the bulge one step toward the bottom of the active
                 ! submatrix. nr is the order of g.
                 nr = min(3,i - k + 1)
                 if (k > m) call la_qcopy(nr,h(k,k - 1),1,v,1)
                 call la_qlarfg(nr,v(1),v(2),1,t1)
                 if (k > m) then
                    h(k,k - 1) = v(1)
                    h(k + 1,k - 1) = zero
                    if (k < i - 1) h(k + 2,k - 1) = zero
                 else if (m > l) then
                     ! ==== use the following instead of
                     ! .    h( k, k-1 ) = -h( k, k-1 ) to
                     ! .    avoid a bug when v(2) and v(3)
                     ! .    underflow. ====
                    h(k,k - 1) = h(k,k - 1)*(one - t1)
                 end if
                 v2 = v(2)
                 t2 = t1*v2
                 if (nr == 3) then
                    v3 = v(3)
                    t3 = t1*v3
                    ! apply g from the left to transform the rows of the matrix
                    ! in columns k to i2.
                    do j = k,i2
                       sum = h(k,j) + v2*h(k + 1,j) + v3*h(k + 2,j)
                       h(k,j) = h(k,j) - sum*t1
                       h(k + 1,j) = h(k + 1,j) - sum*t2
                       h(k + 2,j) = h(k + 2,j) - sum*t3
                    end do
                    ! apply g from the right to transform the columns of the
                    ! matrix in rows i1 to min(k+3,i).
                    do j = i1,min(k + 3,i)
                       sum = h(j,k) + v2*h(j,k + 1) + v3*h(j,k + 2)
                       h(j,k) = h(j,k) - sum*t1
                       h(j,k + 1) = h(j,k + 1) - sum*t2
                       h(j,k + 2) = h(j,k + 2) - sum*t3
                    end do
                    if (wantz) then
                       ! accumulate transformations in the matrix z
                       do j = iloz,ihiz
                          sum = z(j,k) + v2*z(j,k + 1) + v3*z(j,k + 2)
                          z(j,k) = z(j,k) - sum*t1
                          z(j,k + 1) = z(j,k + 1) - sum*t2
                          z(j,k + 2) = z(j,k + 2) - sum*t3
                       end do
                    end if
                 else if (nr == 2) then
                    ! apply g from the left to transform the rows of the matrix
                    ! in columns k to i2.
                    do j = k,i2
                       sum = h(k,j) + v2*h(k + 1,j)
                       h(k,j) = h(k,j) - sum*t1
                       h(k + 1,j) = h(k + 1,j) - sum*t2
                    end do
                    ! apply g from the right to transform the columns of the
                    ! matrix in rows i1 to min(k+3,i).
                    do j = i1,i
                       sum = h(j,k) + v2*h(j,k + 1)
                       h(j,k) = h(j,k) - sum*t1
                       h(j,k + 1) = h(j,k + 1) - sum*t2
                    end do
                    if (wantz) then
                       ! accumulate transformations in the matrix z
                       do j = iloz,ihiz
                          sum = z(j,k) + v2*z(j,k + 1)
                          z(j,k) = z(j,k) - sum*t1
                          z(j,k + 1) = z(j,k + 1) - sum*t2
                       end do
                    end if
                 end if
              end do loop_130
           end do loop_140
           ! failure to converge in remaining number of iterations
           info = i
           return
           150 continue
           if (l == i) then
              ! h(i,i-1) is negligible: one eigenvalue has converged.
              wr(i) = h(i,i)
              wi(i) = zero
           else if (l == i - 1) then
              ! h(i-1,i-2) is negligible: a pair of eigenvalues have converged.
              ! transform the 2-by-2 submatrix to standard schur form,
              ! and compute and store the eigenvalues.
              call la_qlanv2(h(i - 1,i - 1),h(i - 1,i),h(i,i - 1),h(i,i),wr(i - 1), &
                        wi(i - 1),wr(i),wi(i),cs,sn)
              if (wantt) then
                 ! apply the transformation to the rest of h.
                 if (i2 > i) call la_qrot(i2 - i,h(i - 1,i + 1),ldh,h(i,i + 1),ldh,cs,sn)

                 call la_qrot(i - i1 - 1,h(i1,i - 1),1,h(i1,i),1,cs,sn)
              end if
              if (wantz) then
                 ! apply the transformation to z.
                 call la_qrot(nz,z(iloz,i - 1),1,z(iloz,i),1,cs,sn)
              end if
           end if
           ! reset deflation counter
           kdefl = 0
           ! return to start of the main loop with new value of i.
           i = l - 1
           go to 20
           160 continue
           return
     end subroutine la_qlahqr

     !> DLAIC1: applies one step of incremental condition estimation in
     !> its simplest version:
     !> Let x, twonorm(x) = 1, be an approximate singular vector of an j-by-j
     !> lower triangular matrix L, such that
     !> twonorm(L*x) = sest
     !> Then DLAIC1 computes sestpr, s, c such that
     !> the vector
     !> [ s*x ]
     !> xhat = [  c  ]
     !> is an approximate singular vector of
     !> [ L       0  ]
     !> Lhat = [ w**T gamma ]
     !> in the sense that
     !> twonorm(Lhat*xhat) = sestpr.
     !> Depending on JOB, an estimate for the largest or smallest singular
     !> value is computed.
     !> Note that [s c]**T and sestpr**2 is an eigenpair of the system
     !> diag(sest*sest, 0) + [alpha  gamma] * [ alpha ]
     !> [ gamma ]
     !> where  alpha =  x**T*w.

     pure subroutine la_qlaic1(job,j,x,sest,w,gamma,sestpr,s,c)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: j,job
           real(qp),intent(out) :: c,s,sestpr
           real(qp),intent(in) :: gamma,sest
           ! Array Arguments
           real(qp),intent(in) :: w(j),x(j)
        ! =====================================================================

           ! Local Scalars
           real(qp) :: absalp,absest,absgam,alpha,b,cosine,eps,norma,s1,s2,sine,t, &
                     test,tmp,zeta1,zeta2
           ! Intrinsic Functions
           intrinsic :: abs,max,sign,sqrt
           ! Executable Statements
           eps = la_qlamch('EPSILON')
           alpha = la_qdot(j,x,1,w,1)
           absalp = abs(alpha)
           absgam = abs(gamma)
           absest = abs(sest)
           if (job == 1) then
              ! estimating largest singular value
              ! special cases
              if (sest == zero) then
                 s1 = max(absgam,absalp)
                 if (s1 == zero) then
                    s = zero
                    c = one
                    sestpr = zero
                 else
                    s = alpha/s1
                    c = gamma/s1
                    tmp = sqrt(s*s + c*c)
                    s = s/tmp
                    c = c/tmp
                    sestpr = s1*tmp
                 end if
                 return
              else if (absgam <= eps*absest) then
                 s = one
                 c = zero
                 tmp = max(absest,absalp)
                 s1 = absest/tmp
                 s2 = absalp/tmp
                 sestpr = tmp*sqrt(s1*s1 + s2*s2)
                 return
              else if (absalp <= eps*absest) then
                 s1 = absgam
                 s2 = absest
                 if (s1 <= s2) then
                    s = one
                    c = zero
                    sestpr = s2
                 else
                    s = zero
                    c = one
                    sestpr = s1
                 end if
                 return
              else if (absest <= eps*absalp .or. absest <= eps*absgam) then
                 s1 = absgam
                 s2 = absalp
                 if (s1 <= s2) then
                    tmp = s1/s2
                    s = sqrt(one + tmp*tmp)
                    sestpr = s2*s
                    c = (gamma/s2)/s
                    s = sign(one,alpha)/s
                 else
                    tmp = s2/s1
                    c = sqrt(one + tmp*tmp)
                    sestpr = s1*c
                    s = (alpha/s1)/c
                    c = sign(one,gamma)/c
                 end if
                 return
              else
                 ! normal case
                 zeta1 = alpha/absest
                 zeta2 = gamma/absest
                 b = (one - zeta1*zeta1 - zeta2*zeta2)*half
                 c = zeta1*zeta1
                 if (b > zero) then
                    t = c/(b + sqrt(b*b + c))
                 else
                    t = sqrt(b*b + c) - b
                 end if
                 sine = -zeta1/t
                 cosine = -zeta2/(one + t)
                 tmp = sqrt(sine*sine + cosine*cosine)
                 s = sine/tmp
                 c = cosine/tmp
                 sestpr = sqrt(t + one)*absest
                 return
              end if
           else if (job == 2) then
              ! estimating smallest singular value
              ! special cases
              if (sest == zero) then
                 sestpr = zero
                 if (max(absgam,absalp) == zero) then
                    sine = one
                    cosine = zero
                 else
                    sine = -gamma
                    cosine = alpha
                 end if
                 s1 = max(abs(sine),abs(cosine))
                 s = sine/s1
                 c = cosine/s1
                 tmp = sqrt(s*s + c*c)
                 s = s/tmp
                 c = c/tmp
                 return
              else if (absgam <= eps*absest) then
                 s = zero
                 c = one
                 sestpr = absgam
                 return
              else if (absalp <= eps*absest) then
                 s1 = absgam
                 s2 = absest
                 if (s1 <= s2) then
                    s = zero
                    c = one
                    sestpr = s1
                 else
                    s = one
                    c = zero
                    sestpr = s2
                 end if
                 return
              else if (absest <= eps*absalp .or. absest <= eps*absgam) then
                 s1 = absgam
                 s2 = absalp
                 if (s1 <= s2) then
                    tmp = s1/s2
                    c = sqrt(one + tmp*tmp)
                    sestpr = absest*(tmp/c)
                    s = -(gamma/s2)/c
                    c = sign(one,alpha)/c
                 else
                    tmp = s2/s1
                    s = sqrt(one + tmp*tmp)
                    sestpr = absest/s
                    c = (alpha/s1)/s
                    s = -sign(one,gamma)/s
                 end if
                 return
              else
                 ! normal case
                 zeta1 = alpha/absest
                 zeta2 = gamma/absest
                 norma = max(one + zeta1*zeta1 + abs(zeta1*zeta2),abs(zeta1*zeta2) + zeta2*zeta2)

                 ! see if root is closer to zero or to one
                 test = one + two*(zeta1 - zeta2)*(zeta1 + zeta2)
                 if (test >= zero) then
                    ! root is close to zero, compute directly
                    b = (zeta1*zeta1 + zeta2*zeta2 + one)*half
                    c = zeta2*zeta2
                    t = c/(b + sqrt(abs(b*b - c)))
                    sine = zeta1/(one - t)
                    cosine = -zeta2/t
                    sestpr = sqrt(t + four*eps*eps*norma)*absest
                 else
                    ! root is closer to one, shift by that amount
                    b = (zeta2*zeta2 + zeta1*zeta1 - one)*half
                    c = zeta1*zeta1
                    if (b >= zero) then
                       t = -c/(b + sqrt(b*b + c))
                    else
                       t = b - sqrt(b*b + c)
                    end if
                    sine = -zeta1/t
                    cosine = -zeta2/(one + t)
                    sestpr = sqrt(one + t + four*eps*eps*norma)*absest
                 end if
                 tmp = sqrt(sine*sine + cosine*cosine)
                 s = sine/tmp
                 c = cosine/tmp
                 return
              end if
           end if
           return
     end subroutine la_qlaic1

     !> DLALS0: applies back the multiplying factors of either the left or the
     !> right singular vector matrix of a diagonal matrix appended by a row
     !> to the right hand side matrix B in solving the least squares problem
     !> using the divide-and-conquer SVD approach.
     !> For the left singular vector matrix, three types of orthogonal
     !> matrices are involved:
     !> (1L) Givens rotations: the number of such rotations is GIVPTR; the
     !> pairs of columns/rows they were applied to are stored in GIVCOL;
     !> and the C- and S-values of these rotations are stored in GIVNUM.
     !> (2L) Permutation. The (NL+1)-st row of B is to be moved to the first
     !> row, and for J=2:N, PERM(J)-th row of B is to be moved to the
     !> J-th row.
     !> (3L) The left singular vector matrix of the remaining matrix.
     !> For the right singular vector matrix, four types of orthogonal
     !> matrices are involved:
     !> (1R) The right singular vector matrix of the remaining matrix.
     !> (2R) If SQRE = 1, one extra Givens rotation to generate the right
     !> null space.
     !> (3R) The inverse transformation of (2L).
     !> (4R) The inverse transformation of (1L).

     pure subroutine la_qlals0(icompq,nl,nr,sqre,nrhs,b,ldb,bx,ldbx,perm,givptr, &
               givcol,ldgcol,givnum,ldgnum,poles,difl,difr,z,k,c,s,work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: givptr,icompq,k,ldb,ldbx,ldgcol,ldgnum,nl,nr,nrhs, &
                      sqre
           integer(ilp),intent(out) :: info
           real(qp),intent(in) :: c,s
           ! Array Arguments
           integer(ilp),intent(in) :: givcol(ldgcol,*),perm(*)
           real(qp),intent(inout) :: b(ldb,*)
           real(qp),intent(out) :: bx(ldbx,*),work(*)
           real(qp),intent(in) :: difl(*),difr(ldgnum,*),givnum(ldgnum,*),poles(ldgnum,*),z( &
                     *)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,j,m,n,nlp1
           real(qp) :: diflj,difrj,dj,dsigj,dsigjp,temp
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           n = nl + nr + 1
           if ((icompq < 0) .or. (icompq > 1)) then
              info = -1
           else if (nl < 1) then
              info = -2
           else if (nr < 1) then
              info = -3
           else if ((sqre < 0) .or. (sqre > 1)) then
              info = -4
           else if (nrhs < 1) then
              info = -5
           else if (ldb < n) then
              info = -7
           else if (ldbx < n) then
              info = -9
           else if (givptr < 0) then
              info = -11
           else if (ldgcol < n) then
              info = -13
           else if (ldgnum < n) then
              info = -15
           else if (k < 1) then
              info = -20
           end if
           if (info /= 0) then
              call la_xerbla('DLALS0',-info)
              return
           end if
           m = n + sqre
           nlp1 = nl + 1
           if (icompq == 0) then
              ! apply back orthogonal transformations from the left.
              ! step (1l): apply back the givens rotations performed.
              do i = 1,givptr
                 call la_qrot(nrhs,b(givcol(i,2),1),ldb,b(givcol(i,1),1),ldb, &
                           givnum(i,2),givnum(i,1))
              end do
              ! step (2l): permute rows of b.
              call la_qcopy(nrhs,b(nlp1,1),ldb,bx(1,1),ldbx)
              do i = 2,n
                 call la_qcopy(nrhs,b(perm(i),1),ldb,bx(i,1),ldbx)
              end do
              ! step (3l): apply the inverse of the left singular vector
              ! matrix to bx.
              if (k == 1) then
                 call la_qcopy(nrhs,bx,ldbx,b,ldb)
                 if (z(1) < zero) then
                    call la_qscal(nrhs,negone,b,ldb)
                 end if
              else
                 loop_50: do j = 1,k
                    diflj = difl(j)
                    dj = poles(j,1)
                    dsigj = -poles(j,2)
                    if (j < k) then
                       difrj = -difr(j,1)
                       dsigjp = -poles(j + 1,2)
                    end if
                    if ((z(j) == zero) .or. (poles(j,2) == zero)) then
                       work(j) = zero
                    else
                       work(j) = -poles(j,2)*z(j)/diflj/(poles(j,2) + dj)
                    end if
                    do i = 1,j - 1
                       if ((z(i) == zero) .or. (poles(i,2) == zero)) then
                          work(i) = zero
                       else
                          work(i) = poles(i,2)*z(i)/(la_qlamc3(poles(i,2),dsigj &
                                    ) - diflj)/(poles(i,2) + dj)
                       end if
                    end do
                    do i = j + 1,k
                       if ((z(i) == zero) .or. (poles(i,2) == zero)) then
                          work(i) = zero
                       else
                          work(i) = poles(i,2)*z(i)/(la_qlamc3(poles(i,2), &
                                    dsigjp) + difrj)/(poles(i,2) + dj)
                       end if
                    end do
                    work(1) = negone
                    temp = la_qnrm2(k,work,1)
                    call la_qgemv('T',k,nrhs,one,bx,ldbx,work,1,zero,b(j,1),ldb)

                    call la_qlascl('G',0,0,temp,one,1,nrhs,b(j,1),ldb,info)

                 end do loop_50
              end if
              ! move the deflated rows of bx to b also.
              if (k < max(m,n)) call la_qlacpy('A',n - k,nrhs,bx(k + 1,1),ldbx,b(k + 1,1 &
                        ),ldb)
           else
              ! apply back the right orthogonal transformations.
              ! step (1r): apply back the new right singular vector matrix
              ! to b.
              if (k == 1) then
                 call la_qcopy(nrhs,b,ldb,bx,ldbx)
              else
                 do j = 1,k
                    dsigj = poles(j,2)
                    if (z(j) == zero) then
                       work(j) = zero
                    else
                       work(j) = -z(j)/difl(j)/(dsigj + poles(j,1))/difr(j,2)

                    end if
                    do i = 1,j - 1
                       if (z(j) == zero) then
                          work(i) = zero
                       else
                          work(i) = z(j)/(la_qlamc3(dsigj,-poles(i + 1,2)) - difr(i, &
                                    1))/(dsigj + poles(i,1))/difr(i,2)
                       end if
                    end do
                    do i = j + 1,k
                       if (z(j) == zero) then
                          work(i) = zero
                       else
                          work(i) = z(j)/(la_qlamc3(dsigj,-poles(i,2)) - difl(i)) &
                                     /(dsigj + poles(i,1))/difr(i,2)
                       end if
                    end do
                    call la_qgemv('T',k,nrhs,one,b,ldb,work,1,zero,bx(j,1),ldbx)

                 end do
              end if
              ! step (2r): if sqre = 1, apply back the rotation that is
              ! related to the right null space of the subproblem.
              if (sqre == 1) then
                 call la_qcopy(nrhs,b(m,1),ldb,bx(m,1),ldbx)
                 call la_qrot(nrhs,bx(1,1),ldbx,bx(m,1),ldbx,c,s)
              end if
              if (k < max(m,n)) call la_qlacpy('A',n - k,nrhs,b(k + 1,1),ldb,bx(k + 1,1 &
                        ),ldbx)
              ! step (3r): permute rows of b.
              call la_qcopy(nrhs,bx(1,1),ldbx,b(nlp1,1),ldb)
              if (sqre == 1) then
                 call la_qcopy(nrhs,bx(m,1),ldbx,b(m,1),ldb)
              end if
              do i = 2,n
                 call la_qcopy(nrhs,bx(i,1),ldbx,b(perm(i),1),ldb)
              end do
              ! step (4r): apply back the givens rotations performed.
              do i = givptr,1,-1
                 call la_qrot(nrhs,b(givcol(i,2),1),ldb,b(givcol(i,1),1),ldb, &
                           givnum(i,2),-givnum(i,1))
              end do
           end if
           return
     end subroutine la_qlals0

     !> DLALSA: is an itermediate step in solving the least squares problem
     !> by computing the SVD of the coefficient matrix in compact form (The
     !> singular vectors are computed as products of simple orthorgonal
     !> matrices.).
     !> If ICOMPQ = 0, DLALSA applies the inverse of the left singular vector
     !> matrix of an upper bidiagonal matrix to the right hand side; and if
     !> ICOMPQ = 1, DLALSA applies the right singular vector matrix to the
     !> right hand side. The singular vector matrices were generated in
     !> compact form by DLALSA.

     pure subroutine la_qlalsa(icompq,smlsiz,n,nrhs,b,ldb,bx,ldbx,u,ldu,vt,k,difl, &
                difr,z,poles,givptr,givcol,ldgcol,perm,givnum,c,s,work,iwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: icompq,ldb,ldbx,ldgcol,ldu,n,nrhs,smlsiz
           integer(ilp),intent(out) :: info
           ! Array Arguments
           integer(ilp),intent(in) :: givcol(ldgcol,*),givptr(*),k(*),perm(ldgcol,*)
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: b(ldb,*)
           real(qp),intent(out) :: bx(ldbx,*),work(*)
           real(qp),intent(in) :: c(*),difl(ldu,*),difr(ldu,*),givnum(ldu,*),poles(ldu,*),s( &
                     *),u(ldu,*),vt(ldu,*),z(ldu,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,i1,ic,im1,inode,j,lf,ll,lvl,lvl2,nd,ndb1,ndiml,ndimr, &
                     nl,nlf,nlp1,nlvl,nr,nrf,nrp1,sqre
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if ((icompq < 0) .or. (icompq > 1)) then
              info = -1
           else if (smlsiz < 3) then
              info = -2
           else if (n < smlsiz) then
              info = -3
           else if (nrhs < 1) then
              info = -4
           else if (ldb < n) then
              info = -6
           else if (ldbx < n) then
              info = -8
           else if (ldu < n) then
              info = -10
           else if (ldgcol < n) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('DLALSA',-info)
              return
           end if
           ! book-keeping and  setting up the computation tree.
           inode = 1
           ndiml = inode + n
           ndimr = ndiml + n
           call la_qlasdt(n,nlvl,nd,iwork(inode),iwork(ndiml),iwork(ndimr),smlsiz &
                     )
           ! the following code applies back the left singular vector factors.
           ! for applying back the right singular vector factors, go to 50.
           if (icompq == 1) then
              go to 50
           end if
           ! the nodes on the bottom level of the tree were solved
           ! by la_qlasdq. the corresponding left and right singular vector
           ! matrices are in explicit form. first apply back the left
           ! singular vector matrices.
           ndb1 = (nd + 1)/2
           do i = ndb1,nd
              ! ic : center row of each node
              ! nl : number of rows of left  subproblem
              ! nr : number of rows of right subproblem
              ! nlf: starting row of the left   subproblem
              ! nrf: starting row of the right  subproblem
              i1 = i - 1
              ic = iwork(inode + i1)
              nl = iwork(ndiml + i1)
              nr = iwork(ndimr + i1)
              nlf = ic - nl
              nrf = ic + 1
              call la_qgemm('T','N',nl,nrhs,nl,one,u(nlf,1),ldu,b(nlf,1),ldb, &
                        zero,bx(nlf,1),ldbx)
              call la_qgemm('T','N',nr,nrhs,nr,one,u(nrf,1),ldu,b(nrf,1),ldb, &
                        zero,bx(nrf,1),ldbx)
           end do
           ! next copy the rows of b that correspond to unchanged rows
           ! in the bidiagonal matrix to bx.
           do i = 1,nd
              ic = iwork(inode + i - 1)
              call la_qcopy(nrhs,b(ic,1),ldb,bx(ic,1),ldbx)
           end do
           ! finally go through the left singular vector matrices of all
           ! the other subproblems bottom-up on the tree.
           j = 2**nlvl
           sqre = 0
           do lvl = nlvl,1,-1
              lvl2 = 2*lvl - 1
              ! find the first node lf and last node ll on
              ! the current level lvl
              if (lvl == 1) then
                 lf = 1
                 ll = 1
              else
                 lf = 2**(lvl - 1)
                 ll = 2*lf - 1
              end if
              do i = lf,ll
                 im1 = i - 1
                 ic = iwork(inode + im1)
                 nl = iwork(ndiml + im1)
                 nr = iwork(ndimr + im1)
                 nlf = ic - nl
                 nrf = ic + 1
                 j = j - 1
                 call la_qlals0(icompq,nl,nr,sqre,nrhs,bx(nlf,1),ldbx,b(nlf,1), &
                 ldb,perm(nlf,lvl),givptr(j),givcol(nlf,lvl2),ldgcol,givnum(nlf,lvl2 &
                 ),ldu,poles(nlf,lvl2),difl(nlf,lvl),difr(nlf,lvl2),z(nlf,lvl),k( &
                           j),c(j),s(j),work,info)
              end do
           end do
           go to 90
           ! icompq = 1: applying back the right singular vector factors.
           50 continue
           ! first now go through the right singular vector matrices of all
           ! the tree nodes top-down.
           j = 0
           loop_70: do lvl = 1,nlvl
              lvl2 = 2*lvl - 1
              ! find the first node lf and last node ll on
              ! the current level lvl.
              if (lvl == 1) then
                 lf = 1
                 ll = 1
              else
                 lf = 2**(lvl - 1)
                 ll = 2*lf - 1
              end if
              do i = ll,lf,-1
                 im1 = i - 1
                 ic = iwork(inode + im1)
                 nl = iwork(ndiml + im1)
                 nr = iwork(ndimr + im1)
                 nlf = ic - nl
                 nrf = ic + 1
                 if (i == ll) then
                    sqre = 0
                 else
                    sqre = 1
                 end if
                 j = j + 1
                 call la_qlals0(icompq,nl,nr,sqre,nrhs,b(nlf,1),ldb,bx(nlf,1), &
                 ldbx,perm(nlf,lvl),givptr(j),givcol(nlf,lvl2),ldgcol,givnum(nlf, &
                 lvl2),ldu,poles(nlf,lvl2),difl(nlf,lvl),difr(nlf,lvl2),z(nlf,lvl) &
                           ,k(j),c(j),s(j),work,info)
              end do
           end do loop_70
           ! the nodes on the bottom level of the tree were solved
           ! by la_qlasdq. the corresponding right singular vector
           ! matrices are in explicit form. apply them back.
           ndb1 = (nd + 1)/2
           do i = ndb1,nd
              i1 = i - 1
              ic = iwork(inode + i1)
              nl = iwork(ndiml + i1)
              nr = iwork(ndimr + i1)
              nlp1 = nl + 1
              if (i == nd) then
                 nrp1 = nr
              else
                 nrp1 = nr + 1
              end if
              nlf = ic - nl
              nrf = ic + 1
              call la_qgemm('T','N',nlp1,nrhs,nlp1,one,vt(nlf,1),ldu,b(nlf,1), &
                        ldb,zero,bx(nlf,1),ldbx)
              call la_qgemm('T','N',nrp1,nrhs,nrp1,one,vt(nrf,1),ldu,b(nrf,1), &
                        ldb,zero,bx(nrf,1),ldbx)
           end do
           90 continue
           return
     end subroutine la_qlalsa

     !> DLALSD: uses the singular value decomposition of A to solve the least
     !> squares problem of finding X to minimize the Euclidean norm of each
     !> column of A*X-B, where A is N-by-N upper bidiagonal, and X and B
     !> are N-by-NRHS. The solution X overwrites B.
     !> The singular values of A smaller than RCOND times the largest
     !> singular value are treated as zero in solving the least squares
     !> problem; in this case a minimum norm solution is returned.
     !> The actual singular values are returned in D in ascending order.
     !> This code makes very mild assumptions about floating point
     !> arithmetic. It will work on machines with a guard digit in
     !> add/subtract, or on those binary machines without guard digits
     !> which subtract like the Cray XMP, Cray YMP, Cray C 90, or Cray 2.
     !> It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.

     pure subroutine la_qlalsd(uplo,smlsiz,n,nrhs,d,e,b,ldb,rcond,rank,work,iwork, &
               info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info,rank
           integer(ilp),intent(in) :: ldb,n,nrhs,smlsiz
           real(qp),intent(in) :: rcond
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: b(ldb,*),d(*),e(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: bx,bxst,c,difl,difr,givcol,givnum,givptr,i,icmpq1,icmpq2, &
           iwk,j,k,nlvl,nm1,nsize,nsub,nwork,perm,poles,s,sizei,smlszp,sqre,st,st1, &
                      u,vt,z
           real(qp) :: cs,eps,orgnrm,r,rcnd,sn,tol
           ! Intrinsic Functions
           intrinsic :: abs,real,int,log,sign
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (n < 0) then
              info = -3
           else if (nrhs < 1) then
              info = -4
           else if ((ldb < 1) .or. (ldb < n)) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('DLALSD',-info)
              return
           end if
           eps = la_qlamch('EPSILON')
           ! set up the tolerance.
           if ((rcond <= zero) .or. (rcond >= one)) then
              rcnd = eps
           else
              rcnd = rcond
           end if
           rank = 0
           ! quick return if possible.
           if (n == 0) then
              return
           else if (n == 1) then
              if (d(1) == zero) then
                 call la_qlaset('A',1,nrhs,zero,zero,b,ldb)
              else
                 rank = 1
                 call la_qlascl('G',0,0,d(1),one,1,nrhs,b,ldb,info)
                 d(1) = abs(d(1))
              end if
              return
           end if
           ! rotate the matrix if it is lower bidiagonal.
           if (uplo == 'L') then
              do i = 1,n - 1
                 call la_qlartg(d(i),e(i),cs,sn,r)
                 d(i) = r
                 e(i) = sn*d(i + 1)
                 d(i + 1) = cs*d(i + 1)
                 if (nrhs == 1) then
                    call la_qrot(1,b(i,1),1,b(i + 1,1),1,cs,sn)
                 else
                    work(i*2 - 1) = cs
                    work(i*2) = sn
                 end if
              end do
              if (nrhs > 1) then
                 do i = 1,nrhs
                    do j = 1,n - 1
                       cs = work(j*2 - 1)
                       sn = work(j*2)
                       call la_qrot(1,b(j,i),1,b(j + 1,i),1,cs,sn)
                    end do
                 end do
              end if
           end if
           ! scale.
           nm1 = n - 1
           orgnrm = la_qlanst('M',n,d,e)
           if (orgnrm == zero) then
              call la_qlaset('A',n,nrhs,zero,zero,b,ldb)
              return
           end if
           call la_qlascl('G',0,0,orgnrm,one,n,1,d,n,info)
           call la_qlascl('G',0,0,orgnrm,one,nm1,1,e,nm1,info)
           ! if n is smaller than the minimum divide size smlsiz, then solve
           ! the problem with another solver.
           if (n <= smlsiz) then
              nwork = 1 + n*n
              call la_qlaset('A',n,n,zero,one,work,n)
              call la_qlasdq('U',0,n,n,0,nrhs,d,e,work,n,work,n,b,ldb,work( &
                        nwork),info)
              if (info /= 0) then
                 return
              end if
              tol = rcnd*abs(d(la_iqamax(n,d,1)))
              do i = 1,n
                 if (d(i) <= tol) then
                    call la_qlaset('A',1,nrhs,zero,zero,b(i,1),ldb)
                 else
                    call la_qlascl('G',0,0,d(i),one,1,nrhs,b(i,1),ldb,info)

                    rank = rank + 1
                 end if
              end do
              call la_qgemm('T','N',n,nrhs,n,one,work,n,b,ldb,zero,work(nwork), &
                        n)
              call la_qlacpy('A',n,nrhs,work(nwork),n,b,ldb)
              ! unscale.
              call la_qlascl('G',0,0,one,orgnrm,n,1,d,n,info)
              call la_qlasrt('D',n,d,info)
              call la_qlascl('G',0,0,orgnrm,one,n,nrhs,b,ldb,info)
              return
           end if
           ! book-keeping and setting up some constants.
           nlvl = int(log(real(n,KIND=qp)/real(smlsiz + 1,KIND=qp))/log(two),KIND=ilp) + &
                     1
           smlszp = smlsiz + 1
           u = 1
           vt = 1 + smlsiz*n
           difl = vt + smlszp*n
           difr = difl + nlvl*n
           z = difr + nlvl*n*2
           c = z + nlvl*n
           s = c + n
           poles = s + n
           givnum = poles + 2*nlvl*n
           bx = givnum + 2*nlvl*n
           nwork = bx + n*nrhs
           sizei = 1 + n
           k = sizei + n
           givptr = k + n
           perm = givptr + n
           givcol = perm + nlvl*n
           iwk = givcol + nlvl*n*2
           st = 1
           sqre = 0
           icmpq1 = 1
           icmpq2 = 0
           nsub = 0
           do i = 1,n
              if (abs(d(i)) < eps) then
                 d(i) = sign(eps,d(i))
              end if
           end do
           loop_60: do i = 1,nm1
              if ((abs(e(i)) < eps) .or. (i == nm1)) then
                 nsub = nsub + 1
                 iwork(nsub) = st
                 ! subproblem found. first determine its size and then
                 ! apply divide and conquer on it.
                 if (i < nm1) then
                    ! a subproblem with e(i) small for i < nm1.
                    nsize = i - st + 1
                    iwork(sizei + nsub - 1) = nsize
                 else if (abs(e(i)) >= eps) then
                    ! a subproblem with e(nm1) not too small but i = nm1.
                    nsize = n - st + 1
                    iwork(sizei + nsub - 1) = nsize
                 else
                    ! a subproblem with e(nm1) small. this implies an
                    ! 1-by-1 subproblem at d(n), which is not solved
                    ! explicitly.
                    nsize = i - st + 1
                    iwork(sizei + nsub - 1) = nsize
                    nsub = nsub + 1
                    iwork(nsub) = n
                    iwork(sizei + nsub - 1) = 1
                    call la_qcopy(nrhs,b(n,1),ldb,work(bx + nm1),n)
                 end if
                 st1 = st - 1
                 if (nsize == 1) then
                    ! this is a 1-by-1 subproblem and is not solved
                    ! explicitly.
                    call la_qcopy(nrhs,b(st,1),ldb,work(bx + st1),n)
                 else if (nsize <= smlsiz) then
                    ! this is a small subproblem and is solved by la_qlasdq.
                    call la_qlaset('A',nsize,nsize,zero,one,work(vt + st1),n)
                    call la_qlasdq('U',0,nsize,nsize,0,nrhs,d(st),e(st),work(vt + &
                              st1),n,work(nwork),n,b(st,1),ldb,work(nwork),info)
                    if (info /= 0) then
                       return
                    end if
                    call la_qlacpy('A',nsize,nrhs,b(st,1),ldb,work(bx + st1),n)

                 else
                    ! a large problem. solve it using divide and conquer.
                    call la_qlasda(icmpq1,smlsiz,nsize,sqre,d(st),e(st),work(u + st1 &
                    ),n,work(vt + st1),iwork(k + st1),work(difl + st1),work(difr + st1),work( &
                    z + st1),work(poles + st1),iwork(givptr + st1),iwork(givcol + st1),n,iwork( &
                    perm + st1),work(givnum + st1),work(c + st1),work(s + st1),work(nwork), &
                              iwork(iwk),info)
                    if (info /= 0) then
                       return
                    end if
                    bxst = bx + st1
                    call la_qlalsa(icmpq2,smlsiz,nsize,nrhs,b(st,1),ldb,work(bxst), &
                     n,work(u + st1),n,work(vt + st1),iwork(k + st1),work(difl + st1),work( &
                     difr + st1),work(z + st1),work(poles + st1),iwork(givptr + st1),iwork( &
                     givcol + st1),n,iwork(perm + st1),work(givnum + st1),work(c + st1),work(s + &
                               st1),work(nwork),iwork(iwk),info)
                    if (info /= 0) then
                       return
                    end if
                 end if
                 st = i + 1
              end if
           end do loop_60
           ! apply the singular values and treat the tiny ones as zero.
           tol = rcnd*abs(d(la_iqamax(n,d,1)))
           do i = 1,n
              ! some of the elements in d can be negative because 1-by-1
              ! subproblems were not solved explicitly.
              if (abs(d(i)) <= tol) then
                 call la_qlaset('A',1,nrhs,zero,zero,work(bx + i - 1),n)
              else
                 rank = rank + 1
                 call la_qlascl('G',0,0,d(i),one,1,nrhs,work(bx + i - 1),n,info)

              end if
              d(i) = abs(d(i))
           end do
           ! now apply back the right singular vectors.
           icmpq2 = 1
           do i = 1,nsub
              st = iwork(i)
              st1 = st - 1
              nsize = iwork(sizei + i - 1)
              bxst = bx + st1
              if (nsize == 1) then
                 call la_qcopy(nrhs,work(bxst),n,b(st,1),ldb)
              else if (nsize <= smlsiz) then
                 call la_qgemm('T','N',nsize,nrhs,nsize,one,work(vt + st1),n,work( &
                           bxst),n,zero,b(st,1),ldb)
              else
                 call la_qlalsa(icmpq2,smlsiz,nsize,nrhs,work(bxst),n,b(st,1),ldb, &
                  work(u + st1),n,work(vt + st1),iwork(k + st1),work(difl + st1),work(difr + &
                  st1),work(z + st1),work(poles + st1),iwork(givptr + st1),iwork(givcol + st1), &
                   n,iwork(perm + st1),work(givnum + st1),work(c + st1),work(s + st1),work( &
                             nwork),iwork(iwk),info)
                 if (info /= 0) then
                    return
                 end if
              end if
           end do
           ! unscale and sort the singular values.
           call la_qlascl('G',0,0,one,orgnrm,n,1,d,n,info)
           call la_qlasrt('D',n,d,info)
           call la_qlascl('G',0,0,orgnrm,one,n,nrhs,b,ldb,info)
           return
     end subroutine la_qlalsd

     !> DLAMRG: will create a permutation list which will merge the elements
     !> of A (which is composed of two independently sorted sets) into a
     !> single set which is sorted in ascending order.

     pure subroutine la_qlamrg(n1,n2,a,dtrd1,dtrd2,index)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: dtrd1,dtrd2,n1,n2
           ! Array Arguments
           integer(ilp),intent(out) :: index(*)
           real(qp),intent(in) :: a(*)
        ! =====================================================================
           ! Local Scalars
           integer(ilp) :: i,ind1,ind2,n1sv,n2sv
           ! Executable Statements
           n1sv = n1
           n2sv = n2
           if (dtrd1 > 0) then
              ind1 = 1
           else
              ind1 = n1
           end if
           if (dtrd2 > 0) then
              ind2 = 1 + n1
           else
              ind2 = n1 + n2
           end if
           i = 1
           ! while ( (n1sv > 0)
           10 continue
           if (n1sv > 0 .and. n2sv > 0) then
              if (a(ind1) <= a(ind2)) then
                 index(i) = ind1
                 i = i + 1
                 ind1 = ind1 + dtrd1
                 n1sv = n1sv - 1
              else
                 index(i) = ind2
                 i = i + 1
                 ind2 = ind2 + dtrd2
                 n2sv = n2sv - 1
              end if
              go to 10
           end if
           ! end while
           if (n1sv == 0) then
              do n1sv = 1,n2sv
                 index(i) = ind2
                 i = i + 1
                 ind2 = ind2 + dtrd2
              end do
           else
           ! n2sv == 0
              do n2sv = 1,n1sv
                 index(i) = ind1
                 i = i + 1
                 ind1 = ind1 + dtrd1
              end do
           end if
           return
     end subroutine la_qlamrg

     !> DLANEG: computes the Sturm count, the number of negative pivots
     !> encountered while factoring tridiagonal T - sigma I = L D L^T.
     !> This implementation works directly on the factors without forming
     !> the tridiagonal matrix T.  The Sturm count is also the number of
     !> eigenvalues of T less than sigma.
     !> This routine is called from DLARRB.
     !> The current routine does not use the PIVMIN parameter but rather
     !> requires IEEE-754 propagation of Infinities and NaNs.  This
     !> routine also has no input range restrictions but does require
     !> default exception handling such that x/0 produces Inf when x is
     !> non-zero, and Inf/Inf produces NaN.  For more information, see:
     !> Marques, Riedy, and Voemel, "Benefits of IEEE-754 Features in
     !> Modern Symmetric Tridiagonal Eigensolvers," SIAM Journal on
     !> Scientific Computing, v28, n5, 2006.  DOI 10.1137/050641624
     !> (Tech report version in LAWN 172 with the same title.)

     pure integer(ilp) function la_qlaneg(n,d,lld,sigma,pivmin,r)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: n,r
           real(qp),intent(in) :: pivmin,sigma
           ! Array Arguments
           real(qp),intent(in) :: d(*),lld(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: blklen = 128

           ! some architectures propagate infinities and nans very slowly, so
           ! the code computes counts in blklen chunks.  then a nan can
           ! propagate at most blklen columns before being detected.  this is
           ! not a general tuning parameter; it needs only to be just large
           ! enough that the overhead is tiny in common cases.

           ! Local Scalars
           integer(ilp) :: bj,j,neg1,neg2,negcnt
           real(qp) :: bsav,dminus,dplus,gamma,p,t,tmp
           logical(lk) :: sawnan
           ! Intrinsic Functions
           intrinsic :: min,max
           ! Executable Statements
           negcnt = 0
           ! i) upper part: l d l^t - sigma i = l+ d+ l+^t
           t = -sigma
           loop_210: do bj = 1,r - 1,blklen
              neg1 = 0
              bsav = t
              do j = bj,min(bj + blklen - 1,r - 1)
                 dplus = d(j) + t
                 if (dplus < zero) neg1 = neg1 + 1
                 tmp = t/dplus
                 t = tmp*lld(j) - sigma
              end do
              sawnan = la_qisnan(t)
           ! run a slower version of the above loop if a nan is detected.
           ! a nan should occur only with a zero pivot after an infinite
           ! pivot.  in that case, substituting 1 for t/dplus is the
           ! correct limit.
              if (sawnan) then
                 neg1 = 0
                 t = bsav
                 do j = bj,min(bj + blklen - 1,r - 1)
                    dplus = d(j) + t
                    if (dplus < zero) neg1 = neg1 + 1
                    tmp = t/dplus
                    if (la_qisnan(tmp)) tmp = one
                    t = tmp*lld(j) - sigma
                 end do
              end if
              negcnt = negcnt + neg1
           end do loop_210
           ! ii) lower part: l d l^t - sigma i = u- d- u-^t
           p = d(n) - sigma
           do bj = n - 1,r,-blklen
              neg2 = 0
              bsav = p
              do j = bj,max(bj - blklen + 1,r),-1
                 dminus = lld(j) + p
                 if (dminus < zero) neg2 = neg2 + 1
                 tmp = p/dminus
                 p = tmp*d(j) - sigma
              end do
              sawnan = la_qisnan(p)
           ! as above, run a slower version that substitutes 1 for inf/inf.
              if (sawnan) then
                 neg2 = 0
                 p = bsav
                 do j = bj,max(bj - blklen + 1,r),-1
                    dminus = lld(j) + p
                    if (dminus < zero) neg2 = neg2 + 1
                    tmp = p/dminus
                    if (la_qisnan(tmp)) tmp = one
                    p = tmp*d(j) - sigma
                 end do
              end if
              negcnt = negcnt + neg2
           end do
           ! iii) twist index
             ! t was shifted by sigma initially.
           gamma = (t + sigma) + p
           if (gamma < zero) negcnt = negcnt + 1
           la_qlaneg = negcnt
     end function la_qlaneg

     !> DLAQR0: computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_qlaqr0(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz,work, &
                lwork,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(qp),intent(out) :: wi(*),work(*),wr(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(qp),parameter :: wilk1 = 0.75_qp
           real(qp),parameter :: wilk2 = -0.4375_qp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_qlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constants wilk1 and wilk2 are used to form the
           ! .    exceptional shifts. ====

           ! Local Scalars
           real(qp) :: aa,bb,cc,cs,dd,sn,ss,swap
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           real(qp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,mod
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = one
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_qlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_qlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz, &
                        ihiz,z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'DLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'DLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_qlaqr3 ====
              call la_qlaqr3(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,wr,wi,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_qlaqr5, la_qlaqr3) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = real(lwkopt,KIND=qp)
                 return
              end if
              ! ==== la_qlahqr/la_qlaqr0 crossover point ====
              nmin = la_ilaenv(12,'DLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'DLAQR0',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'DLAQR0',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_80: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 90
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == zero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (abs(h(kwtop,kwtop - 1)) > abs(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_qlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,wr,wi,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh, &
                           work,lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_qlaqr3
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_qlaqr3 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,max(ks + 1,ktop + 2),-2
                          ss = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                          aa = wilk1*ss + h(i,i)
                          bb = ss
                          cc = wilk2*ss
                          dd = aa
                          call la_qlanv2(aa,bb,cc,dd,wr(i - 1),wi(i - 1),wr(i),wi(i &
                                    ),cs,sn)
                       end do
                       if (ks == ktop) then
                          wr(ks + 1) = h(ks + 1,ks + 1)
                          wi(ks + 1) = zero
                          wr(ks) = wr(ks + 1)
                          wi(ks) = wi(ks + 1)
                       end if
                    else
                       ! ==== got ns/2 or fewer shifts? use la_qlaqr4 or
                       ! .    la_qlahqr on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_qlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          if (ns > nmin) then
                             call la_qlaqr4(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr( &
                                       ks),wi(ks),1,1,zdum,1,work,lwork,inf)
                          else
                             call la_qlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr( &
                                       ks),wi(ks),1,1,zdum,1,inf)
                          end if
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  ====
                          if (ks >= kbot) then
                             aa = h(kbot - 1,kbot - 1)
                             cc = h(kbot,kbot - 1)
                             bb = h(kbot - 1,kbot)
                             dd = h(kbot,kbot)
                             call la_qlanv2(aa,bb,cc,dd,wr(kbot - 1),wi(kbot - 1),wr( &
                                       kbot),wi(kbot),cs,sn)
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little)
                          ! .    bubble sort keeps complex conjugate
                          ! .    pairs together. ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (abs(wr(i)) + abs(wi(i)) < abs(wr(i + 1)) + abs(wi(i + 1) &
                                          )) then
                                   sorted = .false.
                                   swap = wr(i)
                                   wr(i) = wr(i + 1)
                                   wr(i + 1) = swap
                                   swap = wi(i)
                                   wi(i) = wi(i + 1)
                                   wi(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                       ! ==== shuffle shifts into pairs of real shifts
                       ! .    and pairs of complex conjugate shifts
                       ! .    assuming complex conjugate shifts are
                       ! .    already adjacent to one another. (yes,
                       ! .    they are.)  ====
                       do i = kbot,ks + 2,-2
                          if (wi(i) /= -wi(i - 1)) then
                             swap = wr(i)
                             wr(i) = wr(i - 1)
                             wr(i - 1) = wr(i - 2)
                             wr(i - 2) = swap
                             swap = wi(i)
                             wi(i) = wi(i - 1)
                             wi(i - 1) = wi(i - 2)
                             wi(i - 2) = swap
                          end if
                       end do
                    end if
                    ! ==== if there are only two shifts and both are
                    ! .    real, then use only one.  ====
                    if (kbot - ks + 1 == 2) then
                       if (wi(kbot) == zero) then
                          if (abs(wr(kbot) - h(kbot,kbot)) < abs(wr(kbot - 1) - h(kbot,kbot) &
                                    )) then
                             wr(kbot - 1) = wr(kbot)
                          else
                             wr(kbot) = wr(kbot - 1)
                          end if
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping one to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_qlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,wr(ks),wi(ks) &
                    ,h,ldh,iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh, &
                              nho,h(ku,kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_80
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              90 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = real(lwkopt,KIND=qp)
     end subroutine la_qlaqr0

     !> Given a 2-by-2 or 3-by-3 matrix H, DLAQR1: sets v to a
     !> scalar multiple of the first column of the product
     !> (*)  K = (H - (sr1 + i*si1)*I)*(H - (sr2 + i*si2)*I)
     !> scaling to avoid overflows and most underflows. It
     !> is assumed that either
     !> 1) sr1 = sr2 and si1 = -si2
     !> or
     !> 2) si1 = si2 = 0.
     !> This is useful for starting double implicit shift bulges
     !> in the QR algorithm.

     pure subroutine la_qlaqr1(n,h,ldh,sr1,si1,sr2,si2,v)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           real(qp),intent(in) :: si1,si2,sr1,sr2
           integer(ilp),intent(in) :: ldh,n
           ! Array Arguments
           real(qp),intent(in) :: h(ldh,*)
           real(qp),intent(out) :: v(*)
        ! ================================================================

           ! Local Scalars
           real(qp) :: h21s,h31s,s
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           ! quick return if possible
           if (n /= 2 .and. n /= 3) then
              return
           end if
           if (n == 2) then
              s = abs(h(1,1) - sr2) + abs(si2) + abs(h(2,1))
              if (s == zero) then
                 v(1) = zero
                 v(2) = zero
              else
                 h21s = h(2,1)/s
                 v(1) = h21s*h(1,2) + (h(1,1) - sr1)*((h(1,1) - sr2)/s) - si1*( &
                           si2/s)
                 v(2) = h21s*(h(1,1) + h(2,2) - sr1 - sr2)
              end if
           else
              s = abs(h(1,1) - sr2) + abs(si2) + abs(h(2,1)) + abs(h(3,1))
              if (s == zero) then
                 v(1) = zero
                 v(2) = zero
                 v(3) = zero
              else
                 h21s = h(2,1)/s
                 h31s = h(3,1)/s
                 v(1) = (h(1,1) - sr1)*((h(1,1) - sr2)/s) - si1*(si2/s) + h(1,2) &
                           *h21s + h(1,3)*h31s
                 v(2) = h21s*(h(1,1) + h(2,2) - sr1 - sr2) + h(2,3)*h31s
                 v(3) = h31s*(h(1,1) + h(3,3) - sr1 - sr2) + h21s*h(3,2)
              end if
           end if
     end subroutine la_qlaqr1

     !> DLAQR2: is identical to DLAQR3 except that it avoids
     !> recursion by calling DLAHQR instead of DLAQR4.
     !> Aggressive early deflation:
     !> This subroutine accepts as input an upper Hessenberg matrix
     !> H and performs an orthogonal similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an orthogonal similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     subroutine la_qlaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz,ns,nd, &
                sr,si,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(qp),intent(out) :: si(*),sr(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(qp) :: aa,bb,beta,cc,cs,dd,evi,evk,foo,s,safmax,safmin,smlnum,sn, &
                     tau,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,k,kcol,kend,kln,krow,kwtop, &
                     ltop,lwk1,lwk2,lwkopt
           logical(lk) :: bulge,sorted
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,sqrt
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_qgehrd ====
              call la_qgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_qormhr ====
              call la_qormhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = jw + max(lwk1,lwk2)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = real(lwkopt,KIND=qp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = one
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = zero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sr(kwtop) = h(kwtop,kwtop)
              si(kwtop) = zero
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = zero
              end if
              work(1) = one
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_qlacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_qcopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_qlaset('A',jw,jw,zero,one,v,ldv)
           call la_qlahqr(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1,jw, &
                     v,ldv,infqr)
           ! ==== la_qtrexc needs a clean margin near the diagonal ====
           do j = 1,jw - 3
              t(j + 2,j) = zero
              t(j + 3,j) = zero
           end do
           if (jw > 2) t(jw,jw - 2) = zero
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           20 continue
           if (ilst <= ns) then
              if (ns == 1) then
                 bulge = .false.
              else
                 bulge = t(ns,ns - 1) /= zero
              end if
              ! ==== small spike tip test for deflation ====
              if (.not. bulge) then
                 ! ==== real eigenvalue ====
                 foo = abs(t(ns,ns))
                 if (foo == zero) foo = abs(s)
                 if (abs(s*v(1,ns)) <= max(smlnum,ulp*foo)) then
                    ! ==== deflatable ====
                    ns = ns - 1
                 else
                    ! ==== undeflatable.   move it up out of the way.
                    ! .    (la_qtrexc can not fail in this case.) ====
                    ifst = ns
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 1
                 end if
              else
                 ! ==== complex conjugate pair ====
                 foo = abs(t(ns,ns)) + sqrt(abs(t(ns,ns - 1)))*sqrt(abs(t(ns - 1,ns) &
                           ))
                 if (foo == zero) foo = abs(s)
                 if (max(abs(s*v(1,ns)),abs(s*v(1,ns - 1))) <= max(smlnum,ulp*foo)) &
                           then
                    ! ==== deflatable ====
                    ns = ns - 2
                 else
                    ! ==== undeflatable. move them up out of the way.
                    ! .    fortunately, la_qtrexc does the right thing with
                    ! .    ilst in case of a rare exchange failure. ====
                    ifst = ns
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 2
                 end if
              end if
              ! ==== end deflation detection loop ====
              go to 20
           end if
              ! ==== return to hessenberg form ====
           if (ns == 0) s = zero
           if (ns < jw) then
              ! ==== sorting diagonal blocks of t improves accuracy for
              ! .    graded matrices.  bubble sort deals well with
              ! .    exchange failures. ====
              sorted = .false.
              i = ns + 1
              30 continue
              if (sorted) go to 50
              sorted = .true.
              kend = i - 1
              i = infqr + 1
              if (i == ns) then
                 k = i + 1
              else if (t(i + 1,i) == zero) then
                 k = i + 1
              else
                 k = i + 2
              end if
              40 continue
              if (k <= kend) then
                 if (k == i + 1) then
                    evi = abs(t(i,i))
                 else
                    evi = abs(t(i,i)) + sqrt(abs(t(i + 1,i)))*sqrt(abs(t(i,i + 1)))

                 end if
                 if (k == kend) then
                    evk = abs(t(k,k))
                 else if (t(k + 1,k) == zero) then
                    evk = abs(t(k,k))
                 else
                    evk = abs(t(k,k)) + sqrt(abs(t(k + 1,k)))*sqrt(abs(t(k,k + 1)))

                 end if
                 if (evi >= evk) then
                    i = k
                 else
                    sorted = .false.
                    ifst = i
                    ilst = k
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    if (info == 0) then
                       i = ilst
                    else
                       i = k
                    end if
                 end if
                 if (i == kend) then
                    k = i + 1
                 else if (t(i + 1,i) == zero) then
                    k = i + 1
                 else
                    k = i + 2
                 end if
                 go to 40
              end if
              go to 30
              50 continue
           end if
           ! ==== restore shift/eigenvalue array from t ====
           i = jw
           60 continue
           if (i >= infqr + 1) then
              if (i == infqr + 1) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else if (t(i,i - 1) == zero) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else
                 aa = t(i - 1,i - 1)
                 cc = t(i,i - 1)
                 bb = t(i - 1,i)
                 dd = t(i,i)
                 call la_qlanv2(aa,bb,cc,dd,sr(kwtop + i - 2),si(kwtop + i - 2),sr(kwtop + i - &
                           1),si(kwtop + i - 1),cs,sn)
                 i = i - 2
              end if
              go to 60
           end if
           if (ns < jw .or. s == zero) then
              if (ns > 1 .and. s /= zero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_qcopy(ns,v,ldv,work,1)
                 beta = work(1)
                 call la_qlarfg(ns,beta,work(2),1,tau)
                 work(1) = one
                 call la_qlaset('L',jw - 2,jw - 2,zero,zero,t(3,1),ldt)
                 call la_qlarf('L',ns,jw,work,1,tau,t,ldt,work(jw + 1))
                 call la_qlarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_qlarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_qgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*v(1,1)
              call la_qlacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_qcopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= zero) call la_qormhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_qgemm('N','N',kln,jw,jw,one,h(krow,kwtop),ldh,v,ldv, &
                           zero,wv,ldwv)
                 call la_qlacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_qgemm('C','N',jw,kln,jw,one,v,ldv,h(kwtop,kcol),ldh, &
                              zero,t,ldt)
                    call la_qlacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_qgemm('N','N',kln,jw,jw,one,z(krow,kwtop),ldz,v,ldv, &
                              zero,wv,ldwv)
                    call la_qlacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = real(lwkopt,KIND=qp)
     end subroutine la_qlaqr2

     !> Aggressive early deflation:
     !> DLAQR3: accepts as input an upper Hessenberg matrix
     !> H and performs an orthogonal similarity transformation
     !> designed to detect and deflate fully converged eigenvalues from
     !> a trailing principal submatrix.  On output H has been over-
     !> written by a new Hessenberg matrix that is a perturbation of
     !> an orthogonal similarity transformation of H.  It is to be
     !> hoped that the final version of H has many zero subdiagonal
     !> entries.

     subroutine la_qlaqr3(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz,ns,nd, &
                sr,si,v,ldv,nh,t,ldt,nv,wv,ldwv,work,lwork)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kbot,ktop,ldh,ldt,ldv,ldwv,ldz,lwork,n, &
                      nh,nv,nw
           integer(ilp),intent(out) :: nd,ns
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(qp),intent(out) :: si(*),sr(*),t(ldt,*),v(ldv,*),work(*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(qp) :: aa,bb,beta,cc,cs,dd,evi,evk,foo,s,safmax,safmin,smlnum,sn, &
                     tau,ulp
           integer(ilp) :: i,ifst,ilst,info,infqr,j,jw,k,kcol,kend,kln,krow,kwtop, &
                     ltop,lwk1,lwk2,lwk3,lwkopt,nmin
           logical(lk) :: bulge,sorted
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,sqrt
           ! Executable Statements
           ! ==== estimate optimal workspace. ====
           jw = min(nw,kbot - ktop + 1)
           if (jw <= 2) then
              lwkopt = 1
           else
              ! ==== workspace query call to la_qgehrd ====
              call la_qgehrd(jw,1,jw - 1,t,ldt,work,work,-1,info)
              lwk1 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_qormhr ====
              call la_qormhr('R','N',jw,jw,1,jw - 1,t,ldt,work,v,ldv,work,-1,info)

              lwk2 = int(work(1),KIND=ilp)
              ! ==== workspace query call to la_qlaqr4 ====
              call la_qlaqr4(.true.,.true.,jw,1,jw,t,ldt,sr,si,1,jw,v,ldv,work,- &
                        1,infqr)
              lwk3 = int(work(1),KIND=ilp)
              ! ==== optimal workspace ====
              lwkopt = max(jw + max(lwk1,lwk2),lwk3)
           end if
           ! ==== quick return in case of workspace query. ====
           if (lwork == -1) then
              work(1) = real(lwkopt,KIND=qp)
              return
           end if
           ! ==== nothing to do ...
           ! ... for an empty active block ... ====
           ns = 0
           nd = 0
           work(1) = one
           if (ktop > kbot) return
           ! ... nor for an empty deflation window. ====
           if (nw < 1) return
           ! ==== machine constants ====
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           ! ==== setup deflation window ====
           jw = min(nw,kbot - ktop + 1)
           kwtop = kbot - jw + 1
           if (kwtop == ktop) then
              s = zero
           else
              s = h(kwtop,kwtop - 1)
           end if
           if (kbot == kwtop) then
              ! ==== 1-by-1 deflation window: not much to do ====
              sr(kwtop) = h(kwtop,kwtop)
              si(kwtop) = zero
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(h(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ktop) h(kwtop,kwtop - 1) = zero
              end if
              work(1) = one
              return
           end if
           ! ==== convert to spike-triangular form.  (in case of a
           ! .    rare qr failure, this routine continues to do
           ! .    aggressive early deflation using that part of
           ! .    the deflation window that converged using infqr
           ! .    here and there to keep track.) ====
           call la_qlacpy('U',jw,jw,h(kwtop,kwtop),ldh,t,ldt)
           call la_qcopy(jw - 1,h(kwtop + 1,kwtop),ldh + 1,t(2,1),ldt + 1)
           call la_qlaset('A',jw,jw,zero,one,v,ldv)
           nmin = la_ilaenv(12,'DLAQR3','SV',jw,1,jw,lwork)
           if (jw > nmin) then
              call la_qlaqr4(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1, &
                        jw,v,ldv,work,lwork,infqr)
           else
              call la_qlahqr(.true.,.true.,jw,1,jw,t,ldt,sr(kwtop),si(kwtop),1, &
                        jw,v,ldv,infqr)
           end if
           ! ==== la_qtrexc needs a clean margin near the diagonal ====
           do j = 1,jw - 3
              t(j + 2,j) = zero
              t(j + 3,j) = zero
           end do
           if (jw > 2) t(jw,jw - 2) = zero
           ! ==== deflation detection loop ====
           ns = jw
           ilst = infqr + 1
           20 continue
           if (ilst <= ns) then
              if (ns == 1) then
                 bulge = .false.
              else
                 bulge = t(ns,ns - 1) /= zero
              end if
              ! ==== small spike tip test for deflation ====
              if (.not. bulge) then
                 ! ==== real eigenvalue ====
                 foo = abs(t(ns,ns))
                 if (foo == zero) foo = abs(s)
                 if (abs(s*v(1,ns)) <= max(smlnum,ulp*foo)) then
                    ! ==== deflatable ====
                    ns = ns - 1
                 else
                    ! ==== undeflatable.   move it up out of the way.
                    ! .    (la_qtrexc can not fail in this case.) ====
                    ifst = ns
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 1
                 end if
              else
                 ! ==== complex conjugate pair ====
                 foo = abs(t(ns,ns)) + sqrt(abs(t(ns,ns - 1)))*sqrt(abs(t(ns - 1,ns) &
                           ))
                 if (foo == zero) foo = abs(s)
                 if (max(abs(s*v(1,ns)),abs(s*v(1,ns - 1))) <= max(smlnum,ulp*foo)) &
                           then
                    ! ==== deflatable ====
                    ns = ns - 2
                 else
                    ! ==== undeflatable. move them up out of the way.
                    ! .    fortunately, la_qtrexc does the right thing with
                    ! .    ilst in case of a rare exchange failure. ====
                    ifst = ns
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    ilst = ilst + 2
                 end if
              end if
              ! ==== end deflation detection loop ====
              go to 20
           end if
              ! ==== return to hessenberg form ====
           if (ns == 0) s = zero
           if (ns < jw) then
              ! ==== sorting diagonal blocks of t improves accuracy for
              ! .    graded matrices.  bubble sort deals well with
              ! .    exchange failures. ====
              sorted = .false.
              i = ns + 1
              30 continue
              if (sorted) go to 50
              sorted = .true.
              kend = i - 1
              i = infqr + 1
              if (i == ns) then
                 k = i + 1
              else if (t(i + 1,i) == zero) then
                 k = i + 1
              else
                 k = i + 2
              end if
              40 continue
              if (k <= kend) then
                 if (k == i + 1) then
                    evi = abs(t(i,i))
                 else
                    evi = abs(t(i,i)) + sqrt(abs(t(i + 1,i)))*sqrt(abs(t(i,i + 1)))

                 end if
                 if (k == kend) then
                    evk = abs(t(k,k))
                 else if (t(k + 1,k) == zero) then
                    evk = abs(t(k,k))
                 else
                    evk = abs(t(k,k)) + sqrt(abs(t(k + 1,k)))*sqrt(abs(t(k,k + 1)))

                 end if
                 if (evi >= evk) then
                    i = k
                 else
                    sorted = .false.
                    ifst = i
                    ilst = k
                    call la_qtrexc('V',jw,t,ldt,v,ldv,ifst,ilst,work,info)
                    if (info == 0) then
                       i = ilst
                    else
                       i = k
                    end if
                 end if
                 if (i == kend) then
                    k = i + 1
                 else if (t(i + 1,i) == zero) then
                    k = i + 1
                 else
                    k = i + 2
                 end if
                 go to 40
              end if
              go to 30
              50 continue
           end if
           ! ==== restore shift/eigenvalue array from t ====
           i = jw
           60 continue
           if (i >= infqr + 1) then
              if (i == infqr + 1) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else if (t(i,i - 1) == zero) then
                 sr(kwtop + i - 1) = t(i,i)
                 si(kwtop + i - 1) = zero
                 i = i - 1
              else
                 aa = t(i - 1,i - 1)
                 cc = t(i,i - 1)
                 bb = t(i - 1,i)
                 dd = t(i,i)
                 call la_qlanv2(aa,bb,cc,dd,sr(kwtop + i - 2),si(kwtop + i - 2),sr(kwtop + i - &
                           1),si(kwtop + i - 1),cs,sn)
                 i = i - 2
              end if
              go to 60
           end if
           if (ns < jw .or. s == zero) then
              if (ns > 1 .and. s /= zero) then
                 ! ==== reflect spike back into lower triangle ====
                 call la_qcopy(ns,v,ldv,work,1)
                 beta = work(1)
                 call la_qlarfg(ns,beta,work(2),1,tau)
                 work(1) = one
                 call la_qlaset('L',jw - 2,jw - 2,zero,zero,t(3,1),ldt)
                 call la_qlarf('L',ns,jw,work,1,tau,t,ldt,work(jw + 1))
                 call la_qlarf('R',ns,ns,work,1,tau,t,ldt,work(jw + 1))
                 call la_qlarf('R',jw,ns,work,1,tau,v,ldv,work(jw + 1))
                 call la_qgehrd(jw,1,ns,t,ldt,work,work(jw + 1),lwork - jw,info)

              end if
              ! ==== copy updated reduced window into place ====
              if (kwtop > 1) h(kwtop,kwtop - 1) = s*v(1,1)
              call la_qlacpy('U',jw,jw,t,ldt,h(kwtop,kwtop),ldh)
              call la_qcopy(jw - 1,t(2,1),ldt + 1,h(kwtop + 1,kwtop),ldh + 1)
              ! ==== accumulate orthogonal matrix in order update
              ! .    h and z, if requested.  ====
              if (ns > 1 .and. s /= zero) call la_qormhr('R','N',jw,ns,1,ns,t,ldt,work, &
                        v,ldv,work(jw + 1),lwork - jw,info)
              ! ==== update vertical slab in h ====
              if (wantt) then
                 ltop = 1
              else
                 ltop = ktop
              end if
              do krow = ltop,kwtop - 1,nv
                 kln = min(nv,kwtop - krow)
                 call la_qgemm('N','N',kln,jw,jw,one,h(krow,kwtop),ldh,v,ldv, &
                           zero,wv,ldwv)
                 call la_qlacpy('A',kln,jw,wv,ldwv,h(krow,kwtop),ldh)
              end do
              ! ==== update horizontal slab in h ====
              if (wantt) then
                 do kcol = kbot + 1,n,nh
                    kln = min(nh,n - kcol + 1)
                    call la_qgemm('C','N',jw,kln,jw,one,v,ldv,h(kwtop,kcol),ldh, &
                              zero,t,ldt)
                    call la_qlacpy('A',jw,kln,t,ldt,h(kwtop,kcol),ldh)
                 end do
              end if
              ! ==== update vertical slab in z ====
              if (wantz) then
                 do krow = iloz,ihiz,nv
                    kln = min(nv,ihiz - krow + 1)
                    call la_qgemm('N','N',kln,jw,jw,one,z(krow,kwtop),ldz,v,ldv, &
                              zero,wv,ldwv)
                    call la_qlacpy('A',kln,jw,wv,ldwv,z(krow,kwtop),ldz)
                 end do
              end if
           end if
           ! ==== return the number of deflations ... ====
           nd = jw - ns
           ! ==== ... and the number of shifts. (subtracting
           ! .    infqr from the spike length takes care
           ! .    of the case of a rare qr failure while
           ! .    calculating eigenvalues of the deflation
           ! .    window.)  ====
           ns = ns - infqr
            ! ==== return optimal workspace. ====
           work(1) = real(lwkopt,KIND=qp)
     end subroutine la_qlaqr3

     !> DLAQR4: implements one level of recursion for DLAQR0.
     !> It is a complete implementation of the small bulge multi-shift
     !> QR algorithm.  It may be called by DLAQR0 and, for large enough
     !> deflation window size, it may be called by DLAQR3.  This
     !> subroutine is identical to DLAQR0 except that it calls DLAQR2
     !> instead of DLAQR3.
     !> DLAQR4 computes the eigenvalues of a Hessenberg matrix H
     !> and, optionally, the matrices T and Z from the Schur decomposition
     !> H = Z T Z**T, where T is an upper quasi-triangular matrix (the
     !> Schur form), and Z is the orthogonal matrix of Schur vectors.
     !> Optionally Z may be postmultiplied into an input orthogonal
     !> matrix Q so that this routine can give the Schur factorization
     !> of a matrix A which has been reduced to the Hessenberg form H
     !> by the orthogonal matrix Q:  A = Q*H*Q**T = (QZ)*T*(QZ)**T.

     subroutine la_qlaqr4(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz,ihiz,z,ldz,work, &
                lwork,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihi,ihiz,ilo,iloz,ldh,ldz,lwork,n
           integer(ilp),intent(out) :: info
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),z(ldz,*)
           real(qp),intent(out) :: wi(*),work(*),wr(*)
        ! ================================================================
           ! Parameters
           integer(ilp),parameter :: ntiny = 15
           integer(ilp),parameter :: kexnw = 5
           integer(ilp),parameter :: kexsh = 6
           real(qp),parameter :: wilk1 = 0.75_qp
           real(qp),parameter :: wilk2 = -0.4375_qp
           ! ==== matrices of order ntiny or smaller must be processed by
           ! .    la_qlahqr because of insufficient subdiagonal scratch space.
           ! .    (this is a hard limit.) ====

           ! ==== exceptional deflation windows:  try to cure rare
           ! .    slow convergence by varying the size of the
           ! .    deflation window after kexnw iterations. ====

           ! ==== exceptional shifts: try to cure rare slow convergence
           ! .    with ad-hoc exceptional shifts every kexsh iterations.
           ! .    ====

           ! ==== the constants wilk1 and wilk2 are used to form the
           ! .    exceptional shifts. ====

           ! Local Scalars
           real(qp) :: aa,bb,cc,cs,dd,sn,ss,swap
           integer(ilp) :: i,inf,it,itmax,k,kacc22,kbot,kdu,ks,kt,ktop,ku,kv,kwh, &
           kwtop,kwv,ld,ls,lwkopt,ndec,ndfl,nh,nho,nibble,nmin,ns,nsmax,nsr,nve,nw, &
                      nwmax,nwr,nwupbd
           logical(lk) :: sorted
           character :: jbcmpz*2
           ! Local Arrays
           real(qp) :: zdum(1,1)
           ! Intrinsic Functions
           intrinsic :: abs,real,int,max,min,mod
           ! Executable Statements
           info = 0
           ! ==== quick return for n = 0: nothing to do. ====
           if (n == 0) then
              work(1) = one
              return
           end if
           if (n <= ntiny) then
              ! ==== tiny matrices must use la_qlahqr. ====
              lwkopt = 1
              if (lwork /= -1) call la_qlahqr(wantt,wantz,n,ilo,ihi,h,ldh,wr,wi,iloz, &
                        ihiz,z,ldz,info)
           else
              ! ==== use small bulge multi-shift qr with aggressive early
              ! .    deflation on larger-than-tiny matrices. ====
              ! ==== hope for the best. ====
              info = 0
              ! ==== set up job flags for la_ilaenv. ====
              if (wantt) then
                 jbcmpz(1:1) = 'S'
              else
                 jbcmpz(1:1) = 'E'
              end if
              if (wantz) then
                 jbcmpz(2:2) = 'V'
              else
                 jbcmpz(2:2) = 'N'
              end if
              ! ==== nwr = recommended deflation window size.  at this
              ! .    point,  n > ntiny = 15, so there is enough
              ! .    subdiagonal workspace for nwr>=2 as required.
              ! .    (in fact, there is enough subdiagonal space for
              ! .    nwr>=4.) ====
              nwr = la_ilaenv(13,'DLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nwr = max(2,nwr)
              nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
              ! ==== nsr = recommended number of simultaneous shifts.
              ! .    at this point n > ntiny = 15, so there is at
              ! .    enough subdiagonal workspace for nsr to be even
              ! .    and greater than or equal to two as required. ====
              nsr = la_ilaenv(15,'DLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nsr = min(nsr, (n - 3)/6,ihi - ilo)
              nsr = max(2,nsr - mod(nsr,2))
              ! ==== estimate optimal workspace ====
              ! ==== workspace query call to la_qlaqr2 ====
              call la_qlaqr2(wantt,wantz,n,ilo,ihi,nwr + 1,h,ldh,iloz,ihiz,z,ldz,ls, &
                         ld,wr,wi,h,ldh,n,h,ldh,n,h,ldh,work,-1)
              ! ==== optimal workspace = max(la_qlaqr5, la_qlaqr2) ====
              lwkopt = max(3*nsr/2,int(work(1),KIND=ilp))
              ! ==== quick return in case of workspace query. ====
              if (lwork == -1) then
                 work(1) = real(lwkopt,KIND=qp)
                 return
              end if
              ! ==== la_qlahqr/la_qlaqr0 crossover point ====
              nmin = la_ilaenv(12,'DLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nmin = max(ntiny,nmin)
              ! ==== nibble crossover point ====
              nibble = la_ilaenv(14,'DLAQR4',jbcmpz,n,ilo,ihi,lwork)
              nibble = max(0,nibble)
              ! ==== accumulate reflections during ttswp?  use block
              ! .    2-by-2 structure during matrix-matrix multiply? ====
              kacc22 = la_ilaenv(16,'DLAQR4',jbcmpz,n,ilo,ihi,lwork)
              kacc22 = max(0,kacc22)
              kacc22 = min(2,kacc22)
              ! ==== nwmax = the largest possible deflation window for
              ! .    which there is sufficient workspace. ====
              nwmax = min((n - 1)/3,lwork/2)
              nw = nwmax
              ! ==== nsmax = the largest number of simultaneous shifts
              ! .    for which there is sufficient workspace. ====
              nsmax = min((n - 3)/6,2*lwork/3)
              nsmax = nsmax - mod(nsmax,2)
              ! ==== ndfl: an iteration count restarted at deflation. ====
              ndfl = 1
              ! ==== itmax = iteration limit ====
              itmax = max(30,2*kexsh)*max(10, (ihi - ilo + 1))
              ! ==== last row and column in the active block ====
              kbot = ihi
              ! ==== main loop ====
              loop_80: do it = 1,itmax
                 ! ==== done when kbot falls below ilo ====
                 if (kbot < ilo) go to 90
                 ! ==== locate active block ====
                 do k = kbot,ilo + 1,-1
                    if (h(k,k - 1) == zero) go to 20
                 end do
                 k = ilo
                 20 continue
                 ktop = k
                 ! ==== select deflation window size:
                 ! .    typical case:
                 ! .      if possible and advisable, nibble the entire
                 ! .      active block.  if not, use size min(nwr,nwmax)
                 ! .      or min(nwr+1,nwmax) depending upon which has
                 ! .      the smaller corresponding subdiagonal entry
                 ! .      (a heuristic).
                 ! .    exceptional case:
                 ! .      if there have been no deflations in kexnw or
                 ! .      more iterations, then vary the deflation window
                 ! .      size.   at first, because, larger windows are,
                 ! .      in general, more powerful than smaller ones,
                 ! .      rapidly increase the window to the maximum possible.
                 ! .      then, gradually reduce the window size. ====
                 nh = kbot - ktop + 1
                 nwupbd = min(nh,nwmax)
                 if (ndfl < kexnw) then
                    nw = min(nwupbd,nwr)
                 else
                    nw = min(nwupbd,2*nw)
                 end if
                 if (nw < nwmax) then
                    if (nw >= nh - 1) then
                       nw = nh
                    else
                       kwtop = kbot - nw + 1
                       if (abs(h(kwtop,kwtop - 1)) > abs(h(kwtop - 1,kwtop - 2))) nw = nw + &
                                 1
                    end if
                 end if
                 if (ndfl < kexnw) then
                    ndec = -1
                 else if (ndec >= 0 .or. nw >= nwupbd) then
                    ndec = ndec + 1
                    if (nw - ndec < 2) ndec = 0
                    nw = nw - ndec
                 end if
                 ! ==== aggressive early deflation:
                 ! .    split workspace under the subdiagonal into
                 ! .      - an nw-by-nw work array v in the lower
                 ! .        left-hand-corner,
                 ! .      - an nw-by-at-least-nw-but-more-is-better
                 ! .        (nw-by-nho) horizontal work array along
                 ! .        the bottom edge,
                 ! .      - an at-least-nw-but-more-is-better (nhv-by-nw)
                 ! .        vertical work array along the left-hand-edge.
                 ! .        ====
                 kv = n - nw + 1
                 kt = nw + 1
                 nho = (n - nw - 1) - kt + 1
                 kwv = nw + 2
                 nve = (n - nw) - kwv + 1
                 ! ==== aggressive early deflation ====
                 call la_qlaqr2(wantt,wantz,n,ktop,kbot,nw,h,ldh,iloz,ihiz,z,ldz, &
                 ls,ld,wr,wi,h(kv,1),ldh,nho,h(kv,kt),ldh,nve,h(kwv,1),ldh, &
                           work,lwork)
                 ! ==== adjust kbot accounting for new deflations. ====
                 kbot = kbot - ld
                 ! ==== ks points to the shifts. ====
                 ks = kbot - ls + 1
                 ! ==== skip an expensive qr sweep if there is a (partly
                 ! .    heuristic) reason to expect that many eigenvalues
                 ! .    will deflate without it.  here, the qr sweep is
                 ! .    skipped if many eigenvalues have just been deflated
                 ! .    or if the remaining active block is small.
                 if ((ld == 0) .or. ((100*ld <= nw*nibble) .and. (kbot - ktop + 1 > min(nmin,nwmax) &
                            ))) then
                    ! ==== ns = nominal number of simultaneous shifts.
                    ! .    this may be lowered (slightly) if la_qlaqr2
                    ! .    did not provide that many shifts. ====
                    ns = min(nsmax,nsr,max(2,kbot - ktop))
                    ns = ns - mod(ns,2)
                    ! ==== if there have been no deflations
                    ! .    in a multiple of kexsh iterations,
                    ! .    then try exceptional shifts.
                    ! .    otherwise use shifts provided by
                    ! .    la_qlaqr2 above or from the eigenvalues
                    ! .    of a trailing principal submatrix. ====
                    if (mod(ndfl,kexsh) == 0) then
                       ks = kbot - ns + 1
                       do i = kbot,max(ks + 1,ktop + 2),-2
                          ss = abs(h(i,i - 1)) + abs(h(i - 1,i - 2))
                          aa = wilk1*ss + h(i,i)
                          bb = ss
                          cc = wilk2*ss
                          dd = aa
                          call la_qlanv2(aa,bb,cc,dd,wr(i - 1),wi(i - 1),wr(i),wi(i &
                                    ),cs,sn)
                       end do
                       if (ks == ktop) then
                          wr(ks + 1) = h(ks + 1,ks + 1)
                          wi(ks + 1) = zero
                          wr(ks) = wr(ks + 1)
                          wi(ks) = wi(ks + 1)
                       end if
                    else
                       ! ==== got ns/2 or fewer shifts? use la_qlahqr
                       ! .    on a trailing principal submatrix to
                       ! .    get more. (since ns<=nsmax<=(n-3)/6,
                       ! .    there is enough space below the subdiagonal
                       ! .    to fit an ns-by-ns scratch array.) ====
                       if (kbot - ks + 1 <= ns/2) then
                          ks = kbot - ns + 1
                          kt = n - ns + 1
                          call la_qlacpy('A',ns,ns,h(ks,ks),ldh,h(kt,1),ldh)

                          call la_qlahqr(.false.,.false.,ns,1,ns,h(kt,1),ldh,wr(ks &
                                    ),wi(ks),1,1,zdum,1,inf)
                          ks = ks + inf
                          ! ==== in case of a rare qr failure use
                          ! .    eigenvalues of the trailing 2-by-2
                          ! .    principal submatrix.  ====
                          if (ks >= kbot) then
                             aa = h(kbot - 1,kbot - 1)
                             cc = h(kbot,kbot - 1)
                             bb = h(kbot - 1,kbot)
                             dd = h(kbot,kbot)
                             call la_qlanv2(aa,bb,cc,dd,wr(kbot - 1),wi(kbot - 1),wr( &
                                       kbot),wi(kbot),cs,sn)
                             ks = kbot - 1
                          end if
                       end if
                       if (kbot - ks + 1 > ns) then
                          ! ==== sort the shifts (helps a little)
                          ! .    bubble sort keeps complex conjugate
                          ! .    pairs together. ====
                          sorted = .false.
                          do k = kbot,ks + 1,-1
                             if (sorted) go to 60
                             sorted = .true.
                             do i = ks,k - 1
                                if (abs(wr(i)) + abs(wi(i)) < abs(wr(i + 1)) + abs(wi(i + 1) &
                                          )) then
                                   sorted = .false.
                                   swap = wr(i)
                                   wr(i) = wr(i + 1)
                                   wr(i + 1) = swap
                                   swap = wi(i)
                                   wi(i) = wi(i + 1)
                                   wi(i + 1) = swap
                                end if
                             end do
                          end do
                          60 continue
                       end if
                       ! ==== shuffle shifts into pairs of real shifts
                       ! .    and pairs of complex conjugate shifts
                       ! .    assuming complex conjugate shifts are
                       ! .    already adjacent to one another. (yes,
                       ! .    they are.)  ====
                       do i = kbot,ks + 2,-2
                          if (wi(i) /= -wi(i - 1)) then
                             swap = wr(i)
                             wr(i) = wr(i - 1)
                             wr(i - 1) = wr(i - 2)
                             wr(i - 2) = swap
                             swap = wi(i)
                             wi(i) = wi(i - 1)
                             wi(i - 1) = wi(i - 2)
                             wi(i - 2) = swap
                          end if
                       end do
                    end if
                    ! ==== if there are only two shifts and both are
                    ! .    real, then use only one.  ====
                    if (kbot - ks + 1 == 2) then
                       if (wi(kbot) == zero) then
                          if (abs(wr(kbot) - h(kbot,kbot)) < abs(wr(kbot - 1) - h(kbot,kbot) &
                                    )) then
                             wr(kbot - 1) = wr(kbot)
                          else
                             wr(kbot) = wr(kbot - 1)
                          end if
                       end if
                    end if
                    ! ==== use up to ns of the the smallest magnitude
                    ! .    shifts.  if there aren't ns shifts available,
                    ! .    then use them all, possibly dropping one to
                    ! .    make the number of shifts even. ====
                    ns = min(ns,kbot - ks + 1)
                    ns = ns - mod(ns,2)
                    ks = kbot - ns + 1
                    ! ==== small-bulge multi-shift qr sweep:
                    ! .    split workspace under the subdiagonal into
                    ! .    - a kdu-by-kdu work array u in the lower
                    ! .      left-hand-corner,
                    ! .    - a kdu-by-at-least-kdu-but-more-is-better
                    ! .      (kdu-by-nho) horizontal work array wh along
                    ! .      the bottom edge,
                    ! .    - and an at-least-kdu-but-more-is-better-by-kdu
                    ! .      (nve-by-kdu) vertical work wv arrow along
                    ! .      the left-hand-edge. ====
                    kdu = 2*ns
                    ku = n - kdu + 1
                    kwh = kdu + 1
                    nho = (n - kdu + 1 - 4) - (kdu + 1) + 1
                    kwv = kdu + 4
                    nve = n - kdu - kwv + 1
                    ! ==== small-bulge multi-shift qr sweep ====
                    call la_qlaqr5(wantt,wantz,kacc22,n,ktop,kbot,ns,wr(ks),wi(ks) &
                    ,h,ldh,iloz,ihiz,z,ldz,work,3,h(ku,1),ldh,nve,h(kwv,1),ldh, &
                              nho,h(ku,kwh),ldh)
                 end if
                 ! ==== note progress (or the lack of it). ====
                 if (ld > 0) then
                    ndfl = 1
                 else
                    ndfl = ndfl + 1
                 end if
                 ! ==== end of main loop ====
              end do loop_80
              ! ==== iteration limit exceeded.  set info to show where
              ! .    the problem occurred and exit. ====
              info = kbot
              90 continue
           end if
           ! ==== return the optimal value of lwork. ====
           work(1) = real(lwkopt,KIND=qp)
     end subroutine la_qlaqr4

     !> DLAQR5:, called by DLAQR0, performs a
     !> single small-bulge multi-shift QR sweep.

     pure subroutine la_qlaqr5(wantt,wantz,kacc22,n,ktop,kbot,nshfts,sr,si,h,ldh, &
               iloz,ihiz,z,ldz,v,ldv,u,ldu,nv,wv,ldwv,nh,wh,ldwh)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ihiz,iloz,kacc22,kbot,ktop,ldh,ldu,ldv,ldwh,ldwv, &
                     ldz,n,nh,nshfts,nv
           logical(lk),intent(in) :: wantt,wantz
           ! Array Arguments
           real(qp),intent(inout) :: h(ldh,*),si(*),sr(*),z(ldz,*)
           real(qp),intent(out) :: u(ldu,*),v(ldv,*),wh(ldwh,*),wv(ldwv,*)
        ! ================================================================

           ! Local Scalars
           real(qp) :: alpha,beta,h11,h12,h21,h22,refsum,safmax,safmin,scl,smlnum,swap, &
                      tst1,tst2,ulp
           integer(ilp) :: i,i2,i4,incol,j,jbot,jcol,jlen,jrow,jtop,k,k1,kdu,kms, &
                     krcol,m,m22,mbot,mtop,nbmps,ndcol,ns,nu
           logical(lk) :: accum,bmp22
           ! Intrinsic Functions
           intrinsic :: abs,real,max,min,mod
           ! Local Arrays
           real(qp) :: vt(3)
           ! Executable Statements
           ! ==== if there are no shifts, then there is nothing to do. ====
           if (nshfts < 2) return
           ! ==== if the active block is empty or 1-by-1, then there
           ! .    is nothing to do. ====
           if (ktop >= kbot) return
           ! ==== shuffle shifts into pairs of real shifts and pairs
           ! .    of complex conjugate shifts assuming complex
           ! .    conjugate shifts are already adjacent to one
           ! .    another. ====
           do i = 1,nshfts - 2,2
              if (si(i) /= -si(i + 1)) then
                 swap = sr(i)
                 sr(i) = sr(i + 1)
                 sr(i + 1) = sr(i + 2)
                 sr(i + 2) = swap
                 swap = si(i)
                 si(i) = si(i + 1)
                 si(i + 1) = si(i + 2)
                 si(i + 2) = swap
              end if
           end do
           ! ==== nshfts is supposed to be even, but if it is odd,
           ! .    then simply reduce it by one.  the shuffle above
           ! .    ensures that the dropped shift is real and that
           ! .    the remaining shifts are paired. ====
           ns = nshfts - mod(nshfts,2)
           ! ==== machine constants for deflation ====
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           ! ==== use accumulated reflections to update far-from-diagonal
           ! .    entries ? ====
           accum = (kacc22 == 1) .or. (kacc22 == 2)
           ! ==== clear trash ====
           if (ktop + 2 <= kbot) h(ktop + 2,ktop) = zero
           ! ==== nbmps = number of 2-shift bulges in the chain ====
           nbmps = ns/2
           ! ==== kdu = width of slab ====
           kdu = 4*nbmps
           ! ==== create and chase chains of nbmps bulges ====
           loop_180: do incol = ktop - 2*nbmps + 1,kbot - 2,2*nbmps
              ! jtop = index from which updates from the right start.
              if (accum) then
                 jtop = max(ktop,incol)
              else if (wantt) then
                 jtop = 1
              else
                 jtop = ktop
              end if
              ndcol = incol + kdu
              if (accum) call la_qlaset('ALL',kdu,kdu,zero,one,u,ldu)
              ! ==== near-the-diagonal bulge chase.  the following loop
              ! .    performs the near-the-diagonal part of a small bulge
              ! .    multi-shift qr sweep.  each 4*nbmps column diagonal
              ! .    chunk extends from column incol to column ndcol
              ! .    (including both column incol and column ndcol). the
              ! .    following loop chases a 2*nbmps+1 column long chain of
              ! .    nbmps bulges 2*nbmps columns to the right.  (incol
              ! .    may be less than ktop and and ndcol may be greater than
              ! .    kbot indicating phantom columns from which to chase
              ! .    bulges before they are actually introduced or to which
              ! .    to chase bulges beyond column kbot.)  ====
              loop_145: do krcol = incol,min(incol + 2*nbmps - 1,kbot - 2)
                 ! ==== bulges number mtop to mbot are active double implicit
                 ! .    shift bulges.  there may or may not also be small
                 ! .    2-by-2 bulge, if there is room.  the inactive bulges
                 ! .    (if any) must wait until the active bulges have moved
                 ! .    down the diagonal to make room.  the phantom matrix
                 ! .    paradigm described above helps keep track.  ====
                 mtop = max(1, (ktop - krcol)/2 + 1)
                 mbot = min(nbmps, (kbot - krcol - 1)/2)
                 m22 = mbot + 1
                 bmp22 = (mbot < nbmps) .and. (krcol + 2*(m22 - 1)) == (kbot - 2)
                 ! ==== generate reflections to chase the chain right
                 ! .    one column.  (the minimum value of k is ktop-1.) ====
                 if (bmp22) then
                    ! ==== special case: 2-by-2 reflection at bottom treated
                    ! .    separately ====
                    k = krcol + 2*(m22 - 1)
                    if (k == ktop - 1) then
                       call la_qlaqr1(2,h(k + 1,k + 1),ldh,sr(2*m22 - 1),si(2*m22 - 1),sr( &
                                  2*m22),si(2*m22),v(1,m22))
                       beta = v(1,m22)
                       call la_qlarfg(2,beta,v(2,m22),1,v(1,m22))
                    else
                       beta = h(k + 1,k)
                       v(2,m22) = h(k + 2,k)
                       call la_qlarfg(2,beta,v(2,m22),1,v(1,m22))
                       h(k + 1,k) = beta
                       h(k + 2,k) = zero
                    end if
                    ! ==== perform update from right within
                    ! .    computational window. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m22)*(h(j,k + 1) + v(2,m22)*h(j,k + 2))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*v(2,m22)
                    end do
                    ! ==== perform update from left within
                    ! .    computational window. ====
                    if (accum) then
                       jbot = min(ndcol,kbot)
                    else if (wantt) then
                       jbot = n
                    else
                       jbot = kbot
                    end if
                    do j = k + 1,jbot
                       refsum = v(1,m22)*(h(k + 1,j) + v(2,m22)*h(k + 2,j))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m22)
                    end do
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is zero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k >= ktop) then
                       if (h(k + 1,k) /= zero) then
                          tst1 = abs(h(k,k)) + abs(h(k + 1,k + 1))
                          if (tst1 == zero) then
                             if (k >= ktop + 1) tst1 = tst1 + abs(h(k,k - 1))
                             if (k >= ktop + 2) tst1 = tst1 + abs(h(k,k - 2))
                             if (k >= ktop + 3) tst1 = tst1 + abs(h(k,k - 3))
                             if (k <= kbot - 2) tst1 = tst1 + abs(h(k + 2,k + 1))
                             if (k <= kbot - 3) tst1 = tst1 + abs(h(k + 3,k + 1))
                             if (k <= kbot - 4) tst1 = tst1 + abs(h(k + 4,k + 1))
                          end if
                          if (abs(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                             h12 = max(abs(h(k + 1,k)),abs(h(k,k + 1)))
                             h21 = min(abs(h(k + 1,k)),abs(h(k,k + 1)))
                             h11 = max(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))

                             h22 = min(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))

                             scl = h11 + h12
                             tst2 = h22*(h11/scl)
                             if (tst2 == zero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) &
                                       then
                                h(k + 1,k) = zero
                             end if
                          end if
                       end if
                    end if
                    ! ==== accumulate orthogonal transformations. ====
                    if (accum) then
                       kms = k - incol
                       do j = max(1,ktop - incol),kdu
                          refsum = v(1,m22)*(u(j,kms + 1) + v(2,m22)*u(j,kms + 2))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*v(2,m22)
                       end do
                    else if (wantz) then
                       do j = iloz,ihiz
                          refsum = v(1,m22)*(z(j,k + 1) + v(2,m22)*z(j,k + 2))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*v(2,m22)
                       end do
                    end if
                 end if
                 ! ==== normal case: chain of 3-by-3 reflections ====
                 loop_80: do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    if (k == ktop - 1) then
                       call la_qlaqr1(3,h(ktop,ktop),ldh,sr(2*m - 1),si(2*m - 1),sr( &
                                 2*m),si(2*m),v(1,m))
                       alpha = v(1,m)
                       call la_qlarfg(3,alpha,v(2,m),1,v(1,m))
                    else
                       ! ==== perform delayed transformation of row below
                       ! .    mth bulge. exploit fact that first two elements
                       ! .    of row are actually zero. ====
                       refsum = v(1,m)*v(3,m)*h(k + 3,k + 2)
                       h(k + 3,k) = -refsum
                       h(k + 3,k + 1) = -refsum*v(2,m)
                       h(k + 3,k + 2) = h(k + 3,k + 2) - refsum*v(3,m)
                       ! ==== calculate reflection to move
                       ! .    mth bulge one step. ====
                       beta = h(k + 1,k)
                       v(2,m) = h(k + 2,k)
                       v(3,m) = h(k + 3,k)
                       call la_qlarfg(3,beta,v(2,m),1,v(1,m))
                       ! ==== a bulge may collapse because of vigilant
                       ! .    deflation or destructive underflow.  in the
                       ! .    underflow case, try the two-small-subdiagonals
                       ! .    trick to try to reinflate the bulge.  ====
                       if (h(k + 3,k) /= zero .or. h(k + 3,k + 1) /= zero .or. h(k + 3,k + 2) == zero) &
                                 then
                          ! ==== typical case: not collapsed (yet). ====
                          h(k + 1,k) = beta
                          h(k + 2,k) = zero
                          h(k + 3,k) = zero
                       else
                          ! ==== atypical case: collapsed.  attempt to
                          ! .    reintroduce ignoring h(k+1,k) and h(k+2,k).
                          ! .    if the fill resulting from the new
                          ! .    reflector is too large, then abandon it.
                          ! .    otherwise, use the new one. ====
                          call la_qlaqr1(3,h(k + 1,k + 1),ldh,sr(2*m - 1),si(2*m - 1),sr( &
                                    2*m),si(2*m),vt)
                          alpha = vt(1)
                          call la_qlarfg(3,alpha,vt(2),1,vt(1))
                          refsum = vt(1)*(h(k + 1,k) + vt(2)*h(k + 2,k))
                          if (abs(h(k + 2,k) - refsum*vt(2)) + abs(refsum*vt(3)) > ulp*(abs( &
                                    h(k,k)) + abs(h(k + 1,k + 1)) + abs(h(k + 2,k + 2)))) then
                             ! ==== starting a new bulge here would
                             ! .    create non-negligible fill.  use
                             ! .    the old one with trepidation. ====
                             h(k + 1,k) = beta
                             h(k + 2,k) = zero
                             h(k + 3,k) = zero
                          else
                             ! ==== starting a new bulge here would
                             ! .    create only negligible fill.
                             ! .    replace the old reflector with
                             ! .    the new one. ====
                             h(k + 1,k) = h(k + 1,k) - refsum
                             h(k + 2,k) = zero
                             h(k + 3,k) = zero
                             v(1,m) = vt(1)
                             v(2,m) = vt(2)
                             v(3,m) = vt(3)
                          end if
                       end if
                    end if
                    ! ====  apply reflection from the right and
                    ! .     the first column of update from the left.
                    ! .     these updates are required for the vigilant
                    ! .     deflation check. we still delay most of the
                    ! .     updates from the left for efficiency. ====
                    do j = jtop,min(kbot,k + 3)
                       refsum = v(1,m)*(h(j,k + 1) + v(2,m)*h(j,k + 2) + v(3,m)*h(j,k + 3 &
                                 ))
                       h(j,k + 1) = h(j,k + 1) - refsum
                       h(j,k + 2) = h(j,k + 2) - refsum*v(2,m)
                       h(j,k + 3) = h(j,k + 3) - refsum*v(3,m)
                    end do
                    ! ==== perform update from left for subsequent
                    ! .    column. ====
                    refsum = v(1,m)*(h(k + 1,k + 1) + v(2,m)*h(k + 2,k + 1) + v(3,m)*h(k + 3, &
                              k + 1))
                    h(k + 1,k + 1) = h(k + 1,k + 1) - refsum
                    h(k + 2,k + 1) = h(k + 2,k + 1) - refsum*v(2,m)
                    h(k + 3,k + 1) = h(k + 3,k + 1) - refsum*v(3,m)
                    ! ==== the following convergence test requires that
                    ! .    the tradition small-compared-to-nearby-diagonals
                    ! .    criterion and the ahues
                    ! .    criteria both be satisfied.  the latter improves
                    ! .    accuracy in some examples. falling back on an
                    ! .    alternate convergence criterion when tst1 or tst2
                    ! .    is zero (as done here) is traditional but probably
                    ! .    unnecessary. ====
                    if (k < ktop) cycle
                    if (h(k + 1,k) /= zero) then
                       tst1 = abs(h(k,k)) + abs(h(k + 1,k + 1))
                       if (tst1 == zero) then
                          if (k >= ktop + 1) tst1 = tst1 + abs(h(k,k - 1))
                          if (k >= ktop + 2) tst1 = tst1 + abs(h(k,k - 2))
                          if (k >= ktop + 3) tst1 = tst1 + abs(h(k,k - 3))
                          if (k <= kbot - 2) tst1 = tst1 + abs(h(k + 2,k + 1))
                          if (k <= kbot - 3) tst1 = tst1 + abs(h(k + 3,k + 1))
                          if (k <= kbot - 4) tst1 = tst1 + abs(h(k + 4,k + 1))
                       end if
                       if (abs(h(k + 1,k)) <= max(smlnum,ulp*tst1)) then
                          h12 = max(abs(h(k + 1,k)),abs(h(k,k + 1)))
                          h21 = min(abs(h(k + 1,k)),abs(h(k,k + 1)))
                          h11 = max(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))
                          h22 = min(abs(h(k + 1,k + 1)),abs(h(k,k) - h(k + 1,k + 1)))
                          scl = h11 + h12
                          tst2 = h22*(h11/scl)
                          if (tst2 == zero .or. h21*(h12/scl) <= max(smlnum,ulp*tst2)) &
                                    then
                             h(k + 1,k) = zero
                          end if
                       end if
                    end if
                 end do loop_80
                 ! ==== multiply h by reflections from the left ====
                 if (accum) then
                    jbot = min(ndcol,kbot)
                 else if (wantt) then
                    jbot = n
                 else
                    jbot = kbot
                 end if
                 do m = mbot,mtop,-1
                    k = krcol + 2*(m - 1)
                    do j = max(ktop,krcol + 2*m),jbot
                       refsum = v(1,m)*(h(k + 1,j) + v(2,m)*h(k + 2,j) + v(3,m)*h(k + 3,j &
                                 ))
                       h(k + 1,j) = h(k + 1,j) - refsum
                       h(k + 2,j) = h(k + 2,j) - refsum*v(2,m)
                       h(k + 3,j) = h(k + 3,j) - refsum*v(3,m)
                    end do
                 end do
                 ! ==== accumulate orthogonal transformations. ====
                 if (accum) then
                    ! ==== accumulate u. (if needed, update z later
                    ! .    with an efficient matrix-matrix
                    ! .    multiply.) ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       kms = k - incol
                       i2 = max(1,ktop - incol)
                       i2 = max(i2,kms - (krcol - incol) + 1)
                       i4 = min(kdu,krcol + 2*(mbot - 1) - incol + 5)
                       do j = i2,i4
                          refsum = v(1,m)*(u(j,kms + 1) + v(2,m)*u(j,kms + 2) + v(3,m)*u( &
                                    j,kms + 3))
                          u(j,kms + 1) = u(j,kms + 1) - refsum
                          u(j,kms + 2) = u(j,kms + 2) - refsum*v(2,m)
                          u(j,kms + 3) = u(j,kms + 3) - refsum*v(3,m)
                       end do
                    end do
                 else if (wantz) then
                    ! ==== u is not accumulated, so update z
                    ! .    now by multiplying by reflections
                    ! .    from the right. ====
                    do m = mbot,mtop,-1
                       k = krcol + 2*(m - 1)
                       do j = iloz,ihiz
                          refsum = v(1,m)*(z(j,k + 1) + v(2,m)*z(j,k + 2) + v(3,m)*z(j, &
                                    k + 3))
                          z(j,k + 1) = z(j,k + 1) - refsum
                          z(j,k + 2) = z(j,k + 2) - refsum*v(2,m)
                          z(j,k + 3) = z(j,k + 3) - refsum*v(3,m)
                       end do
                    end do
                 end if
                 ! ==== end of near-the-diagonal bulge chase. ====
              end do loop_145
              ! ==== use u (if accumulated) to update far-from-diagonal
              ! .    entries in h.  if required, use u to update z as
              ! .    well. ====
              if (accum) then
                 if (wantt) then
                    jtop = 1
                    jbot = n
                 else
                    jtop = ktop
                    jbot = kbot
                 end if
                 k1 = max(1,ktop - incol)
                 nu = (kdu - max(0,ndcol - kbot)) - k1 + 1
                 ! ==== horizontal multiply ====
                 do jcol = min(ndcol,kbot) + 1,jbot,nh
                    jlen = min(nh,jbot - jcol + 1)
                    call la_qgemm('C','N',nu,jlen,nu,one,u(k1,k1),ldu,h(incol + k1, &
                              jcol),ldh,zero,wh,ldwh)
                    call la_qlacpy('ALL',nu,jlen,wh,ldwh,h(incol + k1,jcol),ldh)

                 end do
                 ! ==== vertical multiply ====
                 do jrow = jtop,max(ktop,incol) - 1,nv
                    jlen = min(nv,max(ktop,incol) - jrow)
                    call la_qgemm('N','N',jlen,nu,nu,one,h(jrow,incol + k1),ldh,u( &
                              k1,k1),ldu,zero,wv,ldwv)
                    call la_qlacpy('ALL',jlen,nu,wv,ldwv,h(jrow,incol + k1),ldh)

                 end do
                 ! ==== z multiply (also vertical) ====
                 if (wantz) then
                    do jrow = iloz,ihiz,nv
                       jlen = min(nv,ihiz - jrow + 1)
                       call la_qgemm('N','N',jlen,nu,nu,one,z(jrow,incol + k1),ldz,u( &
                                  k1,k1),ldu,zero,wv,ldwv)
                       call la_qlacpy('ALL',jlen,nu,wv,ldwv,z(jrow,incol + k1),ldz)

                    end do
                 end if
              end if
           end do loop_180
     end subroutine la_qlaqr5

     !> DLAQTR: solves the real quasi-triangular system
     !> op(T)*p = scale*c,               if LREAL = .TRUE.
     !> or the complex quasi-triangular systems
     !> op(T + iB)*(p+iq) = scale*(c+id),  if LREAL = .FALSE.
     !> in real arithmetic, where T is upper quasi-triangular.
     !> If LREAL = .FALSE., then the first diagonal block of T must be
     !> 1 by 1, B is the specially structured matrix
     !> B = [ b(1) b(2) ... b(n) ]
     !> [       w            ]
     !> [           w        ]
     !> [              .     ]
     !> [                 w  ]
     !> op(A) = A or A**T, A**T denotes the transpose of
     !> matrix A.
     !> On input, X = [ c ].  On output, X = [ p ].
     !> [ d ]                  [ q ]
     !> This subroutine is designed for the condition number estimation
     !> in routine DTRSNA.

     subroutine la_qlaqtr(ltran,lreal,n,t,ldt,b,w,scale,x,work,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: lreal,ltran
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldt,n
           real(qp),intent(out) :: scale
           real(qp),intent(in) :: w
           ! Array Arguments
           real(qp),intent(in) :: b(*),t(ldt,*)
           real(qp),intent(out) :: work(*)
           real(qp),intent(inout) :: x(*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: notran
           integer(ilp) :: i,ierr,j,j1,j2,jnext,k,n1,n2
           real(qp) :: bignum,eps,rec,scaloc,si,smin,sminw,smlnum,sr,tjj,tmp,xj,xmax, &
                     xnorm,z
           ! Local Arrays
           real(qp) :: d(2,2),v(2,2)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! do not test the input parameters for errors
           notran = .not. ltran
           info = 0
           ! quick return if possible
           if (n == 0) return
           ! set constants to control overflow
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')/eps
           bignum = one/smlnum
           xnorm = la_qlange('M',n,n,t,ldt,d)
           if (.not. lreal) xnorm = max(xnorm,abs(w),la_qlange('M',n,1,b,n,d))

           smin = max(smlnum,eps*xnorm)
           ! compute 1-norm of each column of strictly upper triangular
           ! part of t to control overflow in triangular solver.
           work(1) = zero
           do j = 2,n
              work(j) = la_qasum(j - 1,t(1,j),1)
           end do
           if (.not. lreal) then
              do i = 2,n
                 work(i) = work(i) + abs(b(i))
              end do
           end if
           n2 = 2*n
           n1 = n
           if (.not. lreal) n1 = n2
           k = la_iqamax(n1,x,1)
           xmax = abs(x(k))
           scale = one
           if (xmax > bignum) then
              scale = bignum/xmax
              call la_qscal(n1,scale,x,1)
              xmax = bignum
           end if
           if (lreal) then
              if (notran) then
                 ! solve t*p = scale*c
                 jnext = n
                 loop_30: do j = n,1,-1
                    if (j > jnext) cycle loop_30
                    j1 = j
                    j2 = j
                    jnext = j - 1
                    if (j > 1) then
                       if (t(j,j - 1) /= zero) then
                          j1 = j - 1
                          jnext = j - 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! meet 1 by 1 diagonal block
                       ! scale to avoid overflow when computing
                           ! x(j) = b(j)/t(j,j)
                       xj = abs(x(j1))
                       tjj = abs(t(j1,j1))
                       tmp = t(j1,j1)
                       if (tjj < smin) then
                          tmp = smin
                          tjj = smin
                          info = 1
                       end if
                       if (xj == zero) cycle loop_30
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1)/tmp
                       xj = abs(x(j1))
                       ! scale x if necessary to avoid overflow when adding a
                       ! multiple of column j1 of t.
                       if (xj > one) then
                          rec = one/xj
                          if (work(j1) > (bignum - xmax)*rec) then
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       if (j1 > 1) then
                          call la_qaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          k = la_iqamax(j1 - 1,x,1)
                          xmax = abs(x(k))
                       end if
                    else
                       ! meet 2 by 2 diagonal block
                       ! call 2 by 2 linear system solve, to take
                       ! care of possible overflow by scaling factor.
                       d(1,1) = x(j1)
                       d(2,1) = x(j2)
                       call la_qlaln2(.false.,2,1,smin,one,t(j1,j1),ldt,one,one,d, &
                                  2,zero,zero,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_qscal(n,scaloc,x,1)
                          scale = scale*scaloc
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       ! scale v(1,1) (= x(j1)) and/or v(2,1) (=x(j2))
                       ! to avoid overflow in updating right-hand side.
                       xj = max(abs(v(1,1)),abs(v(2,1)))
                       if (xj > one) then
                          rec = one/xj
                          if (max(work(j1),work(j2)) > (bignum - xmax)*rec) then
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       ! update right-hand side
                       if (j1 > 1) then
                          call la_qaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_qaxpy(j1 - 1,-x(j2),t(1,j2),1,x,1)
                          k = la_iqamax(j1 - 1,x,1)
                          xmax = abs(x(k))
                       end if
                    end if
                 end do loop_30
              else
                 ! solve t**t*p = scale*c
                 jnext = 1
                 loop_40: do j = 1,n
                    if (j < jnext) cycle loop_40
                    j1 = j
                    j2 = j
                    jnext = j + 1
                    if (j < n) then
                       if (t(j + 1,j) /= zero) then
                          j2 = j + 1
                          jnext = j + 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = abs(x(j1))
                       if (xmax > one) then
                          rec = one/xmax
                          if (work(j1) > (bignum - xj)*rec) then
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1) - la_qdot(j1 - 1,t(1,j1),1,x,1)
                       xj = abs(x(j1))
                       tjj = abs(t(j1,j1))
                       tmp = t(j1,j1)
                       if (tjj < smin) then
                          tmp = smin
                          tjj = smin
                          info = 1
                       end if
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1)/tmp
                       xmax = max(xmax,abs(x(j1)))
                    else
                       ! 2 by 2 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side elements by inner product.
                       xj = max(abs(x(j1)),abs(x(j2)))
                       if (xmax > one) then
                          rec = one/xmax
                          if (max(work(j2),work(j1)) > (bignum - xj)*rec) then
                             call la_qscal(n,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       d(1,1) = x(j1) - la_qdot(j1 - 1,t(1,j1),1,x,1)
                       d(2,1) = x(j2) - la_qdot(j1 - 1,t(1,j2),1,x,1)
                       call la_qlaln2(.true.,2,1,smin,one,t(j1,j1),ldt,one,one,d, &
                                 2,zero,zero,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_qscal(n,scaloc,x,1)
                          scale = scale*scaloc
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       xmax = max(abs(x(j1)),abs(x(j2)),xmax)
                    end if
                 end do loop_40
              end if
           else
              sminw = max(eps*abs(w),smin)
              if (notran) then
                 ! solve (t + ib)*(p+iq) = c+id
                 jnext = n
                 loop_70: do j = n,1,-1
                    if (j > jnext) cycle loop_70
                    j1 = j
                    j2 = j
                    jnext = j - 1
                    if (j > 1) then
                       if (t(j,j - 1) /= zero) then
                          j1 = j - 1
                          jnext = j - 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in division
                       z = w
                       if (j1 == 1) z = b(1)
                       xj = abs(x(j1)) + abs(x(n + j1))
                       tjj = abs(t(j1,j1)) + abs(z)
                       tmp = t(j1,j1)
                       if (tjj < sminw) then
                          tmp = sminw
                          tjj = sminw
                          info = 1
                       end if
                       if (xj == zero) cycle loop_70
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       call la_qladiv(x(j1),x(n + j1),tmp,z,sr,si)
                       x(j1) = sr
                       x(n + j1) = si
                       xj = abs(x(j1)) + abs(x(n + j1))
                       ! scale x if necessary to avoid overflow when adding a
                       ! multiple of column j1 of t.
                       if (xj > one) then
                          rec = one/xj
                          if (work(j1) > (bignum - xmax)*rec) then
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       if (j1 > 1) then
                          call la_qaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_qaxpy(j1 - 1,-x(n + j1),t(1,j1),1,x(n + 1),1)
                          x(1) = x(1) + b(j1)*x(n + j1)
                          x(n + 1) = x(n + 1) - b(j1)*x(j1)
                          xmax = zero
                          do k = 1,j1 - 1
                             xmax = max(xmax,abs(x(k)) + abs(x(k + n)))
                          end do
                       end if
                    else
                       ! meet 2 by 2 diagonal block
                       d(1,1) = x(j1)
                       d(2,1) = x(j2)
                       d(1,2) = x(n + j1)
                       d(2,2) = x(n + j2)
                       call la_qlaln2(.false.,2,2,sminw,one,t(j1,j1),ldt,one,one, &
                                 d,2,zero,-w,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_qscal(2*n,scaloc,x,1)
                          scale = scaloc*scale
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       x(n + j1) = v(1,2)
                       x(n + j2) = v(2,2)
                       ! scale x(j1), .... to avoid overflow in
                       ! updating right hand side.
                       xj = max(abs(v(1,1)) + abs(v(1,2)),abs(v(2,1)) + abs(v(2,2) &
                                  ))
                       if (xj > one) then
                          rec = one/xj
                          if (max(work(j1),work(j2)) > (bignum - xmax)*rec) then
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                          end if
                       end if
                       ! update the right-hand side.
                       if (j1 > 1) then
                          call la_qaxpy(j1 - 1,-x(j1),t(1,j1),1,x,1)
                          call la_qaxpy(j1 - 1,-x(j2),t(1,j2),1,x,1)
                          call la_qaxpy(j1 - 1,-x(n + j1),t(1,j1),1,x(n + 1),1)
                          call la_qaxpy(j1 - 1,-x(n + j2),t(1,j2),1,x(n + 1),1)
                          x(1) = x(1) + b(j1)*x(n + j1) + b(j2)*x(n + j2)
                          x(n + 1) = x(n + 1) - b(j1)*x(j1) - b(j2)*x(j2)
                          xmax = zero
                          do k = 1,j1 - 1
                             xmax = max(abs(x(k)) + abs(x(k + n)),xmax)
                          end do
                       end if
                    end if
                 end do loop_70
              else
                 ! solve (t + ib)**t*(p+iq) = c+id
                 jnext = 1
                 loop_80: do j = 1,n
                    if (j < jnext) cycle loop_80
                    j1 = j
                    j2 = j
                    jnext = j + 1
                    if (j < n) then
                       if (t(j + 1,j) /= zero) then
                          j2 = j + 1
                          jnext = j + 2
                       end if
                    end if
                    if (j1 == j2) then
                       ! 1 by 1 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = abs(x(j1)) + abs(x(j1 + n))
                       if (xmax > one) then
                          rec = one/xmax
                          if (work(j1) > (bignum - xj)*rec) then
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       x(j1) = x(j1) - la_qdot(j1 - 1,t(1,j1),1,x,1)
                       x(n + j1) = x(n + j1) - la_qdot(j1 - 1,t(1,j1),1,x(n + 1),1)

                       if (j1 > 1) then
                          x(j1) = x(j1) - b(j1)*x(n + 1)
                          x(n + j1) = x(n + j1) + b(j1)*x(1)
                       end if
                       xj = abs(x(j1)) + abs(x(j1 + n))
                       z = w
                       if (j1 == 1) z = b(1)
                       ! scale if necessary to avoid overflow in
                       ! complex division
                       tjj = abs(t(j1,j1)) + abs(z)
                       tmp = t(j1,j1)
                       if (tjj < sminw) then
                          tmp = sminw
                          tjj = sminw
                          info = 1
                       end if
                       if (tjj < one) then
                          if (xj > bignum*tjj) then
                             rec = one/xj
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       call la_qladiv(x(j1),x(n + j1),tmp,-z,sr,si)
                       x(j1) = sr
                       x(j1 + n) = si
                       xmax = max(abs(x(j1)) + abs(x(j1 + n)),xmax)
                    else
                       ! 2 by 2 diagonal block
                       ! scale if necessary to avoid overflow in forming the
                       ! right-hand side element by inner product.
                       xj = max(abs(x(j1)) + abs(x(n + j1)),abs(x(j2)) + abs(x(n + j2)))

                       if (xmax > one) then
                          rec = one/xmax
                          if (max(work(j1),work(j2)) > (bignum - xj)/xmax) then
                             call la_qscal(n2,rec,x,1)
                             scale = scale*rec
                             xmax = xmax*rec
                          end if
                       end if
                       d(1,1) = x(j1) - la_qdot(j1 - 1,t(1,j1),1,x,1)
                       d(2,1) = x(j2) - la_qdot(j1 - 1,t(1,j2),1,x,1)
                       d(1,2) = x(n + j1) - la_qdot(j1 - 1,t(1,j1),1,x(n + 1),1)

                       d(2,2) = x(n + j2) - la_qdot(j1 - 1,t(1,j2),1,x(n + 1),1)

                       d(1,1) = d(1,1) - b(j1)*x(n + 1)
                       d(2,1) = d(2,1) - b(j2)*x(n + 1)
                       d(1,2) = d(1,2) + b(j1)*x(1)
                       d(2,2) = d(2,2) + b(j2)*x(1)
                       call la_qlaln2(.true.,2,2,sminw,one,t(j1,j1),ldt,one,one,d, &
                                  2,zero,w,v,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 2
                       if (scaloc /= one) then
                          call la_qscal(n2,scaloc,x,1)
                          scale = scaloc*scale
                       end if
                       x(j1) = v(1,1)
                       x(j2) = v(2,1)
                       x(n + j1) = v(1,2)
                       x(n + j2) = v(2,2)
                       xmax = max(abs(x(j1)) + abs(x(n + j1)),abs(x(j2)) + abs(x(n + j2)) &
                                 ,xmax)
                    end if
                 end do loop_80
              end if
           end if
           return
     end subroutine la_qlaqtr

     !> DLAQZ0: computes the eigenvalues of a real matrix pair (H,T),
     !> where H is an upper Hessenberg matrix and T is upper triangular,
     !> using the double-shift QZ method.
     !> Matrix pairs of this type are produced by the reduction to
     !> generalized upper Hessenberg form of a real matrix pair (A,B):
     !> A = Q1*H*Z1**T,  B = Q1*T*Z1**T,
     !> as computed by DGGHRD.
     !> If JOB='S', then the Hessenberg-triangular pair (H,T) is
     !> also reduced to generalized Schur form,
     !> H = Q*S*Z**T,  T = Q*P*Z**T,
     !> where Q and Z are orthogonal matrices, P is an upper triangular
     !> matrix, and S is a quasi-triangular matrix with 1-by-1 and 2-by-2
     !> diagonal blocks.
     !> The 1-by-1 blocks correspond to real eigenvalues of the matrix pair
     !> (H,T) and the 2-by-2 blocks correspond to complex conjugate pairs of
     !> eigenvalues.
     !> Additionally, the 2-by-2 upper triangular diagonal blocks of P
     !> corresponding to 2-by-2 blocks of S are reduced to positive diagonal
     !> form, i.e., if S(j+1,j) is non-zero, then P(j+1,j) = P(j,j+1) = 0,
     !> P(j,j) > 0, and P(j+1,j+1) > 0.
     !> Optionally, the orthogonal matrix Q from the generalized Schur
     !> factorization may be postmultiplied into an input matrix Q1, and the
     !> orthogonal matrix Z may be postmultiplied into an input matrix Z1.
     !> If Q1 and Z1 are the orthogonal matrices from DGGHRD that reduced
     !> the matrix pair (A,B) to generalized upper Hessenberg form, then the
     !> output matrices Q1*Q and Z1*Z are the orthogonal factors from the
     !> generalized Schur factorization of (A,B):
     !> A = (Q1*Q)*S*(Z1*Z)**T,  B = (Q1*Q)*P*(Z1*Z)**T.
     !> To avoid overflow, eigenvalues of the matrix pair (H,T) (equivalently,
     !> of (A,B)) are computed as a pair of values (alpha,beta), where alpha is
     !> complex and beta real.
     !> If beta is nonzero, lambda = alpha / beta is an eigenvalue of the
     !> generalized nonsymmetric eigenvalue problem (GNEP)
     !> A*x = lambda*B*x
     !> and if alpha is nonzero, mu = beta / alpha is an eigenvalue of the
     !> alternate form of the GNEP
     !> mu*A*y = B*y.
     !> Real eigenvalues can be read directly from the generalized Schur
     !> form:
     !> alpha = S(i,i), beta = P(i,i).
     !> Ref: C.B. Moler
     !> Eigenvalue Problems", SIAM J. Numer. Anal., 10(1973),
     !> pp. 241--256.
     !> Ref: B. Kagstrom, D. Kressner, "Multishift Variants of the QZ
     !> Algorithm with Aggressive Early Deflation", SIAM J. Numer.
     !> Anal., 29(2006), pp. 199--227.
     !> Ref: T. Steel, D. Camps, K. Meerbergen, R. Vandebril "A multishift,
     !> multipole rational QZ method with agressive early deflation"

     recursive subroutine la_qlaqz0(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar, &
               alphai,beta,q,ldq,z,ldz,work,lwork,rec,info)
           ! arguments
           character,intent(in) :: wants,wantq,wantz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,rec
           integer(ilp),intent(out) :: info
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),alphar( &
                      *),alphai(*),beta(*),work(*)

           ! local scalars
           real(qp) :: smlnum,ulp,eshift,safmin,safmax,c1,s1,temp,swap
           integer(ilp) :: istart,istop,iiter,maxit,istart2,k,ld,nshifts,nblock,nw,nmin, &
            nibble,n_undeflated,n_qeflated,ns,sweep_info,shiftpos,lworkreq,k2,istartm, &
            istopm,iwants,iwantq,iwantz,norm_info,aed_info,nwr,nbr,nsr,itemp1,itemp2, &
                      rcost,i
           logical(lk) :: ilschur,ilq,ilz
           character :: jbcmpz*3
           if (la_lsame(wants,'E')) then
              ilschur = .false.
              iwants = 1
           else if (la_lsame(wants,'S')) then
              ilschur = .true.
              iwants = 2
           else
              iwants = 0
           end if
           if (la_lsame(wantq,'N')) then
              ilq = .false.
              iwantq = 1
           else if (la_lsame(wantq,'V')) then
              ilq = .true.
              iwantq = 2
           else if (la_lsame(wantq,'I')) then
              ilq = .true.
              iwantq = 3
           else
              iwantq = 0
           end if
           if (la_lsame(wantz,'N')) then
              ilz = .false.
              iwantz = 1
           else if (la_lsame(wantz,'V')) then
              ilz = .true.
              iwantz = 2
           else if (la_lsame(wantz,'I')) then
              ilz = .true.
              iwantz = 3
           else
              iwantz = 0
           end if
           ! check argument values
           info = 0
           if (iwants == 0) then
              info = -1
           else if (iwantq == 0) then
              info = -2
           else if (iwantz == 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ilo < 1) then
              info = -5
           else if (ihi > n .or. ihi < ilo - 1) then
              info = -6
           else if (lda < n) then
              info = -8
           else if (ldb < n) then
              info = -10
           else if (ldq < 1 .or. (ilq .and. ldq < n)) then
              info = -15
           else if (ldz < 1 .or. (ilz .and. ldz < n)) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('DLAQZ0',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) then
              work(1) = real(1,KIND=qp)
              return
           end if
           ! get the parameters
           jbcmpz(1:1) = wants
           jbcmpz(2:2) = wantq
           jbcmpz(3:3) = wantz
           nmin = la_ilaenv(12,'DLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = la_ilaenv(13,'DLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nwr = max(2,nwr)
           nwr = min(ihi - ilo + 1, (n - 1)/3,nwr)
           nibble = la_ilaenv(14,'DLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = la_ilaenv(15,'DLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           nsr = min(nsr, (n + 6)/9,ihi - ilo)
           nsr = max(2,nsr - mod(nsr,2))
           rcost = la_ilaenv(17,'DLAQZ0',jbcmpz,n,ilo,ihi,lwork)
           itemp1 = int(nsr/sqrt(1 + 2*nsr/(real(rcost,KIND=qp)/100*n)),KIND=ilp)
           itemp1 = ((itemp1 - 1)/4)*4 + 4
           nbr = nsr + itemp1
           if (n < nmin .or. rec >= 2) then
              call la_qhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                         beta,q,ldq,z,ldz,work,lwork,info)
              return
           end if
           ! find out required workspace
           ! workspace query to la_qlaqz3
           nw = max(nwr,nmin)
           call la_qlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q,ldq,z,ldz, &
           n_undeflated,n_qeflated,alphar,alphai,beta,work,nw,work,nw,work,-1,rec, &
                     aed_info)
           itemp1 = int(work(1),KIND=ilp)
           ! workspace query to la_qlaqz4
           call la_qlaqz4(ilschur,ilq,ilz,n,ilo,ihi,nsr,nbr,alphar,alphai,beta,a, &
                     lda,b,ldb,q,ldq,z,ldz,work,nbr,work,nbr,work,-1,sweep_info)
           itemp2 = int(work(1),KIND=ilp)
           lworkreq = max(itemp1 + 2*nw**2,itemp2 + 2*nbr**2)
           if (lwork == -1) then
              work(1) = real(lworkreq,KIND=qp)
              return
           else if (lwork < lworkreq) then
              info = -19
           end if
           if (info /= 0) then
              call la_xerbla('DLAQZ0',info)
              return
           end if
           ! initialize q and z
           if (iwantq == 3) call la_qlaset('FULL',n,n,zero,one,q,ldq)
           if (iwantz == 3) call la_qlaset('FULL',n,n,zero,one,z,ldz)
           ! get machine constants
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           istart = ilo
           istop = ihi
           maxit = 3*(ihi - ilo + 1)
           ld = 0
           do iiter = 1,maxit
              if (iiter >= maxit) then
                 info = istop + 1
                 goto 80
              end if
              if (istart + 1 >= istop) then
                 istop = istart
                 exit
              end if
              ! check deflations at the end
              if (abs(a(istop - 1,istop - 2)) <= max(smlnum,ulp*(abs(a(istop - 1,istop - 1)) + &
                        abs(a(istop - 2,istop - 2))))) then
                 a(istop - 1,istop - 2) = zero
                 istop = istop - 2
                 ld = 0
                 eshift = zero
              else if (abs(a(istop,istop - 1)) <= max(smlnum,ulp*(abs(a(istop,istop)) + &
                        abs(a(istop - 1,istop - 1))))) then
                 a(istop,istop - 1) = zero
                 istop = istop - 1
                 ld = 0
                 eshift = zero
              end if
              ! check deflations at the start
              if (abs(a(istart + 2,istart + 1)) <= max(smlnum,ulp*(abs(a(istart + 1,istart + 1 &
                        )) + abs(a(istart + 2,istart + 2))))) then
                 a(istart + 2,istart + 1) = zero
                 istart = istart + 2
                 ld = 0
                 eshift = zero
              else if (abs(a(istart + 1,istart)) <= max(smlnum,ulp*(abs(a(istart,istart) &
                         ) + abs(a(istart + 1,istart + 1))))) then
                 a(istart + 1,istart) = zero
                 istart = istart + 1
                 ld = 0
                 eshift = zero
              end if
              if (istart + 1 >= istop) then
                 exit
              end if
              ! check interior deflations
              istart2 = istart
              do k = istop,istart + 1,-1
                 if (abs(a(k,k - 1)) <= max(smlnum,ulp*(abs(a(k,k)) + abs(a(k - 1,k - 1) &
                           )))) then
                    a(k,k - 1) = zero
                    istart2 = k
                    exit
                 end if
              end do
              ! get range to apply rotations to
              if (ilschur) then
                 istartm = 1
                 istopm = n
              else
                 istartm = istart2
                 istopm = istop
              end if
              ! check infinite eigenvalues, this is done without blocking so might
              ! slow down the method when many infinite eigenvalues are present
              k = istop
              do while (k >= istart2)
                 temp = zero
                 if (k < istop) then
                    temp = temp + abs(b(k,k + 1))
                 end if
                 if (k > istart2) then
                    temp = temp + abs(b(k - 1,k))
                 end if
                 if (abs(b(k,k)) < max(smlnum,ulp*temp)) then
                    ! a diagonal element of b is negligable, move it
                    ! to the top and deflate it
                    do k2 = k,istart2 + 1,-1
                       call la_qlartg(b(k2 - 1,k2),b(k2 - 1,k2 - 1),c1,s1,temp)
                       b(k2 - 1,k2) = temp
                       b(k2 - 1,k2 - 1) = zero
                       call la_qrot(k2 - 2 - istartm + 1,b(istartm,k2),1,b(istartm,k2 - 1), &
                                 1,c1,s1)
                       call la_qrot(min(k2 + 1,istop) - istartm + 1,a(istartm,k2),1,a( &
                                 istartm,k2 - 1),1,c1,s1)
                       if (ilz) then
                          call la_qrot(n,z(1,k2),1,z(1,k2 - 1),1,c1,s1)
                       end if
                       if (k2 < istop) then
                          call la_qlartg(a(k2,k2 - 1),a(k2 + 1,k2 - 1),c1,s1,temp)

                          a(k2,k2 - 1) = temp
                          a(k2 + 1,k2 - 1) = zero
                          call la_qrot(istopm - k2 + 1,a(k2,k2),lda,a(k2 + 1,k2),lda,c1, &
                                    s1)
                          call la_qrot(istopm - k2 + 1,b(k2,k2),ldb,b(k2 + 1,k2),ldb,c1, &
                                    s1)
                          if (ilq) then
                             call la_qrot(n,q(1,k2),1,q(1,k2 + 1),1,c1,s1)
                          end if
                       end if
                    end do
                    if (istart2 < istop) then
                       call la_qlartg(a(istart2,istart2),a(istart2 + 1,istart2),c1,s1, &
                                 temp)
                       a(istart2,istart2) = temp
                       a(istart2 + 1,istart2) = zero
                       call la_qrot(istopm - (istart2 + 1) + 1,a(istart2,istart2 + 1),lda,a( &
                                 istart2 + 1,istart2 + 1),lda,c1,s1)
                       call la_qrot(istopm - (istart2 + 1) + 1,b(istart2,istart2 + 1),ldb,b( &
                                 istart2 + 1,istart2 + 1),ldb,c1,s1)
                       if (ilq) then
                          call la_qrot(n,q(1,istart2),1,q(1,istart2 + 1),1,c1,s1)

                       end if
                    end if
                    istart2 = istart2 + 1
                 end if
                 k = k - 1
              end do
              ! istart2 now points to the top of the bottom right
              ! unreduced hessenberg block
              if (istart2 >= istop) then
                 istop = istart2 - 1
                 ld = 0
                 eshift = zero
                 cycle
              end if
              nw = nwr
              nshifts = nsr
              nblock = nbr
              if (istop - istart2 + 1 < nmin) then
                 ! setting nw to the size of the subblock will make aed deflate
                 ! all the eigenvalues. this is slightly more efficient than just
                 ! using la_qhgeqz because the off diagonal part gets updated via blas.
                 if (istop - istart + 1 < nmin) then
                    nw = istop - istart + 1
                    istart2 = istart
                 else
                    nw = istop - istart2 + 1
                 end if
              end if
              ! time for aed
              call la_qlaqz3(ilschur,ilq,ilz,n,istart2,istop,nw,a,lda,b,ldb,q,ldq, &
               z,ldz,n_undeflated,n_qeflated,alphar,alphai,beta,work,nw,work(nw**2 + 1), &
                         nw,work(2*nw**2 + 1),lwork - 2*nw**2,rec,aed_info)
              if (n_qeflated > 0) then
                 istop = istop - n_qeflated
                 ld = 0
                 eshift = zero
              end if
              if (100*n_qeflated > nibble*(n_qeflated + n_undeflated) .or. istop - istart2 + 1 < nmin &
                        ) then
                 ! aed has uncovered many eigenvalues. skip a qz sweep and run
                 ! aed again.
                 cycle
              end if
              ld = ld + 1
              ns = min(nshifts,istop - istart2)
              ns = min(ns,n_undeflated)
              shiftpos = istop - n_qeflated - n_undeflated + 1
              ! shuffle shifts to put double shifts in front
              ! this ensures that we don't split up a double shift
              do i = shiftpos,shiftpos + n_undeflated - 1,2
                 if (alphai(i) /= -alphai(i + 1)) then
                    swap = alphar(i)
                    alphar(i) = alphar(i + 1)
                    alphar(i + 1) = alphar(i + 2)
                    alphar(i + 2) = swap
                    swap = alphai(i)
                    alphai(i) = alphai(i + 1)
                    alphai(i + 1) = alphai(i + 2)
                    alphai(i + 2) = swap
                    swap = beta(i)
                    beta(i) = beta(i + 1)
                    beta(i + 1) = beta(i + 2)
                    beta(i + 2) = swap
                 end if
              end do
              if (mod(ld,6) == 0) then
                 ! exceptional shift.  chosen for no particularly good reason.
                 if ((real(maxit,KIND=qp)*safmin)*abs(a(istop,istop - 1)) < abs(a(istop - 1, &
                           istop - 1))) then
                    eshift = a(istop,istop - 1)/b(istop - 1,istop - 1)
                 else
                    eshift = eshift + one/(safmin*real(maxit,KIND=qp))
                 end if
                 alphar(shiftpos) = one
                 alphar(shiftpos + 1) = zero
                 alphai(shiftpos) = zero
                 alphai(shiftpos + 1) = zero
                 beta(shiftpos) = eshift
                 beta(shiftpos + 1) = eshift
                 ns = 2
              end if
              ! time for a qz sweep
              call la_qlaqz4(ilschur,ilq,ilz,n,istart2,istop,ns,nblock,alphar( &
              shiftpos),alphai(shiftpos),beta(shiftpos),a,lda,b,ldb,q,ldq,z,ldz, &
              work,nblock,work(nblock**2 + 1),nblock,work(2*nblock**2 + 1),lwork - 2*nblock**2, &
                        sweep_info)
           end do
           ! call la_qhgeqz to normalize the eigenvalue blocks and set the eigenvalues
           ! if all the eigenvalues have been found, la_qhgeqz will not do any iterations
           ! and only normalize the blocks. in case of a rare convergence failure,
           ! the single shift might perform better.
80      call la_qhgeqz(wants,wantq,wantz,n,ilo,ihi,a,lda,b,ldb,alphar,alphai, &
                  beta,q,ldq,z,ldz,work,lwork,norm_info)
           info = norm_info
     end subroutine la_qlaqz0

     !> Given a 3-by-3 matrix pencil (A,B), DLAQZ1: sets v to a
     !> scalar multiple of the first column of the product
     !> (*)  K = (A - (beta2*sr2 - i*si)*B)*B^(-1)*(beta1*A - (sr2 + i*si2)*B)*B^(-1).
     !> It is assumed that either
     !> 1) sr1 = sr2
     !> or
     !> 2) si = 0.
     !> This is useful for starting double implicit shift bulges
     !> in the QZ algorithm.

     pure subroutine la_qlaqz1(a,lda,b,ldb,sr1,sr2,si,beta1,beta2,v)
           ! arguments
           integer(ilp),intent(in) :: lda,ldb
           real(qp),intent(in) :: a(lda,*),b(ldb,*),sr1,sr2,si,beta1,beta2
           real(qp),intent(out) :: v(*)

           ! local scalars
           real(qp) :: w(2),safmin,safmax,scale1,scale2
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           ! calculate first shifted vector
           w(1) = beta1*a(1,1) - sr1*b(1,1)
           w(2) = beta1*a(2,1) - sr1*b(2,1)
           scale1 = sqrt(abs(w(1)))*sqrt(abs(w(2)))
           if (scale1 >= safmin .and. scale1 <= safmax) then
              w(1) = w(1)/scale1
              w(2) = w(2)/scale1
           end if
           ! solve linear system
           w(2) = w(2)/b(2,2)
           w(1) = (w(1) - b(1,2)*w(2))/b(1,1)
           scale2 = sqrt(abs(w(1)))*sqrt(abs(w(2)))
           if (scale2 >= safmin .and. scale2 <= safmax) then
              w(1) = w(1)/scale2
              w(2) = w(2)/scale2
           end if
           ! apply second shift
           v(1) = beta2*(a(1,1)*w(1) + a(1,2)*w(2)) - sr2*(b(1,1)*w(1) + b(1,2)*w( &
                      2))
           v(2) = beta2*(a(2,1)*w(1) + a(2,2)*w(2)) - sr2*(b(2,1)*w(1) + b(2,2)*w( &
                      2))
           v(3) = beta2*(a(3,1)*w(1) + a(3,2)*w(2)) - sr2*(b(3,1)*w(1) + b(3,2)*w( &
                      2))
           ! account for imaginary part
           v(1) = v(1) + si*si*b(1,1)/scale1/scale2
           ! check for overflow
           if (abs(v(1)) > safmax .or. abs(v(2)) > safmax .or. abs(v(3)) > safmax .or. &
           la_qisnan(v(1)) .or. la_qisnan(v(2)) .or. la_qisnan(v(3))) &
                     then
              v(1) = zero
              v(2) = zero
              v(3) = zero
           end if
     end subroutine la_qlaqz1

     !> DLAQZ2: chases a 2x2 shift bulge in a matrix pencil down a single position

     pure subroutine la_qlaqz2(ilq,ilz,k,istartm,istopm,ihi,a,lda,b,ldb,nq,qstart, &
               q,ldq,nz,zstart,z,ldz)
           ! arguments
           logical(lk),intent(in) :: ilq,ilz
           integer(ilp),intent(in) :: k,lda,ldb,ldq,ldz,istartm,istopm,nq,nz,qstart, &
                     zstart,ihi
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)

           ! local variables
           real(qp) :: h(2,3),c1,s1,c2,s2,temp
           if (k + 2 == ihi) then
              ! shift is located on the edge of the matrix, remove it
              h = b(ihi - 1:ihi,ihi - 2:ihi)
              ! make h upper triangular
              call la_qlartg(h(1,1),h(2,1),c1,s1,temp)
              h(2,1) = zero
              h(1,1) = temp
              call la_qrot(2,h(1,2),2,h(2,2),2,c1,s1)
              call la_qlartg(h(2,3),h(2,2),c1,s1,temp)
              call la_qrot(1,h(1,3),1,h(1,2),1,c1,s1)
              call la_qlartg(h(1,2),h(1,1),c2,s2,temp)
              call la_qrot(ihi - istartm + 1,b(istartm,ihi),1,b(istartm,ihi - 1),1,c1, &
                        s1)
              call la_qrot(ihi - istartm + 1,b(istartm,ihi - 1),1,b(istartm,ihi - 2),1,c2, &
                        s2)
              b(ihi - 1,ihi - 2) = zero
              b(ihi,ihi - 2) = zero
              call la_qrot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c1, &
                        s1)
              call la_qrot(ihi - istartm + 1,a(istartm,ihi - 1),1,a(istartm,ihi - 2),1,c2, &
                        s2)
              if (ilz) then
                 call la_qrot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c1,s1 &
                           )
                 call la_qrot(nz,z(1,ihi - 1 - zstart + 1),1,z(1,ihi - 2 - zstart + 1),1,c2, &
                           s2)
              end if
              call la_qlartg(a(ihi - 1,ihi - 2),a(ihi,ihi - 2),c1,s1,temp)
              a(ihi - 1,ihi - 2) = temp
              a(ihi,ihi - 2) = zero
              call la_qrot(istopm - ihi + 2,a(ihi - 1,ihi - 1),lda,a(ihi,ihi - 1),lda,c1,s1 &
                        )
              call la_qrot(istopm - ihi + 2,b(ihi - 1,ihi - 1),ldb,b(ihi,ihi - 1),ldb,c1,s1 &
                        )
              if (ilq) then
                 call la_qrot(nq,q(1,ihi - 1 - qstart + 1),1,q(1,ihi - qstart + 1),1,c1,s1 &
                           )
              end if
              call la_qlartg(b(ihi,ihi),b(ihi,ihi - 1),c1,s1,temp)
              b(ihi,ihi) = temp
              b(ihi,ihi - 1) = zero
              call la_qrot(ihi - istartm,b(istartm,ihi),1,b(istartm,ihi - 1),1,c1,s1)

              call la_qrot(ihi - istartm + 1,a(istartm,ihi),1,a(istartm,ihi - 1),1,c1, &
                        s1)
              if (ilz) then
                 call la_qrot(nz,z(1,ihi - zstart + 1),1,z(1,ihi - 1 - zstart + 1),1,c1,s1 &
                           )
              end if
           else
              ! normal operation, move bulge down
              h = b(k + 1:k + 2,k:k + 2)
              ! make h upper triangular
              call la_qlartg(h(1,1),h(2,1),c1,s1,temp)
              h(2,1) = zero
              h(1,1) = temp
              call la_qrot(2,h(1,2),2,h(2,2),2,c1,s1)
              ! calculate z1 and z2
              call la_qlartg(h(2,3),h(2,2),c1,s1,temp)
              call la_qrot(1,h(1,3),1,h(1,2),1,c1,s1)
              call la_qlartg(h(1,2),h(1,1),c2,s2,temp)
              ! apply transformations from the right
              call la_qrot(k + 3 - istartm + 1,a(istartm,k + 2),1,a(istartm,k + 1),1,c1,s1)

              call la_qrot(k + 3 - istartm + 1,a(istartm,k + 1),1,a(istartm,k),1,c2,s2)

              call la_qrot(k + 2 - istartm + 1,b(istartm,k + 2),1,b(istartm,k + 1),1,c1,s1)

              call la_qrot(k + 2 - istartm + 1,b(istartm,k + 1),1,b(istartm,k),1,c2,s2)

              if (ilz) then
                 call la_qrot(nz,z(1,k + 2 - zstart + 1),1,z(1,k + 1 - zstart + 1),1,c1,s1)

                 call la_qrot(nz,z(1,k + 1 - zstart + 1),1,z(1,k - zstart + 1),1,c2,s2)

              end if
              b(k + 1,k) = zero
              b(k + 2,k) = zero
              ! calculate q1 and q2
              call la_qlartg(a(k + 2,k),a(k + 3,k),c1,s1,temp)
              a(k + 2,k) = temp
              a(k + 3,k) = zero
              call la_qlartg(a(k + 1,k),a(k + 2,k),c2,s2,temp)
              a(k + 1,k) = temp
              a(k + 2,k) = zero
              ! apply transformations from the left
              call la_qrot(istopm - k,a(k + 2,k + 1),lda,a(k + 3,k + 1),lda,c1,s1)
              call la_qrot(istopm - k,a(k + 1,k + 1),lda,a(k + 2,k + 1),lda,c2,s2)
              call la_qrot(istopm - k,b(k + 2,k + 1),ldb,b(k + 3,k + 1),ldb,c1,s1)
              call la_qrot(istopm - k,b(k + 1,k + 1),ldb,b(k + 2,k + 1),ldb,c2,s2)
              if (ilq) then
                 call la_qrot(nq,q(1,k + 2 - qstart + 1),1,q(1,k + 3 - qstart + 1),1,c1,s1)

                 call la_qrot(nq,q(1,k + 1 - qstart + 1),1,q(1,k + 2 - qstart + 1),1,c2,s2)

              end if
           end if
     end subroutine la_qlaqz2

     !> DLAQZ3: performs AED

     recursive subroutine la_qlaqz3(ilschur,ilq,ilz,n,ilo,ihi,nw,a,lda,b,ldb,q, &
               ldq,z,ldz,ns,nd,alphar,alphai,beta,qc,ldqc,zc,ldzc,work,lwork,rec,info)
           ! arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,nw,lda,ldb,ldq,ldz,ldqc,ldzc,lwork, &
                     rec
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),alphar( &
                      *),alphai(*),beta(*)
           integer(ilp),intent(out) :: ns,nd,info
           real(qp),intent(inout) :: qc(ldqc,*),zc(ldzc,*)
           real(qp),intent(out) :: work(*)

           ! local scalars
           logical(lk) :: bulge
           integer(ilp) :: jw,kwtop,kwbot,istopm,istartm,k,k2,dtgexc_info,ifst,ilst, &
                     lworkreq,qz_small_info
           real(qp) :: s,smlnum,ulp,safmin,safmax,c1,s1,temp
           info = 0
           ! set up deflation window
           jw = min(nw,ihi - ilo + 1)
           kwtop = ihi - jw + 1
           if (kwtop == ilo) then
              s = zero
           else
              s = a(kwtop,kwtop - 1)
           end if
           ! determine required workspace
           ifst = 1
           ilst = jw
           call la_qtgexc(.true.,.true.,jw,a,lda,b,ldb,qc,ldqc,zc,ldzc,ifst,ilst, &
                     work,-1,dtgexc_info)
           lworkreq = int(work(1),KIND=ilp)
           call la_qlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
                      ldb,alphar,alphai,beta,qc,ldqc,zc,ldzc,work,-1,rec + 1,qz_small_info)
           lworkreq = max(lworkreq,int(work(1),KIND=ilp) + 2*jw**2)
           lworkreq = max(lworkreq,n*nw,2*nw**2 + n)
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = lworkreq
              return
           else if (lwork < lworkreq) then
              info = -26
           end if
           if (info /= 0) then
              call la_xerbla('DLAQZ3',-info)
              return
           end if
           ! get machine constants
           safmin = la_qlamch('SAFE MINIMUM')
           safmax = one/safmin
           call la_qlabad(safmin,safmax)
           ulp = la_qlamch('PRECISION')
           smlnum = safmin*(real(n,KIND=qp)/ulp)
           if (ihi == kwtop) then
              ! 1 by 1 deflation window, just try a regular deflation
              alphar(kwtop) = a(kwtop,kwtop)
              alphai(kwtop) = zero
              beta(kwtop) = b(kwtop,kwtop)
              ns = 1
              nd = 0
              if (abs(s) <= max(smlnum,ulp*abs(a(kwtop,kwtop)))) then
                 ns = 0
                 nd = 1
                 if (kwtop > ilo) then
                    a(kwtop,kwtop - 1) = zero
                 end if
              end if
           end if
           ! store window in case of convergence failure
           call la_qlacpy('ALL',jw,jw,a(kwtop,kwtop),lda,work,jw)
           call la_qlacpy('ALL',jw,jw,b(kwtop,kwtop),ldb,work(jw**2 + 1),jw)

           ! transform window to real schur form
           call la_qlaset('FULL',jw,jw,zero,one,qc,ldqc)
           call la_qlaset('FULL',jw,jw,zero,one,zc,ldzc)
           call la_qlaqz0('S','V','V',jw,1,jw,a(kwtop,kwtop),lda,b(kwtop,kwtop), &
            ldb,alphar,alphai,beta,qc,ldqc,zc,ldzc,work(2*jw**2 + 1),lwork - 2*jw**2,rec + 1, &
                      qz_small_info)
           if (qz_small_info /= 0) then
              ! convergence failure, restore the window and exit
              nd = 0
              ns = jw - qz_small_info
              call la_qlacpy('ALL',jw,jw,work,jw,a(kwtop,kwtop),lda)
              call la_qlacpy('ALL',jw,jw,work(jw**2 + 1),jw,b(kwtop,kwtop),ldb)

              return
           end if
           ! deflation detection loop
           if (kwtop == ilo .or. s == zero) then
              kwbot = kwtop - 1
           else
              kwbot = ihi
              k = 1
              k2 = 1
              do while (k <= jw)
                 bulge = .false.
                 if (kwbot - kwtop + 1 >= 2) then
                    bulge = a(kwbot,kwbot - 1) /= zero
                 end if
                 if (bulge) then
                    ! try to deflate complex conjugate eigenvalue pair
                    temp = abs(a(kwbot,kwbot)) + sqrt(abs(a(kwbot,kwbot - 1)))*sqrt(abs( &
                              a(kwbot - 1,kwbot)))
                    if (temp == zero) then
                       temp = abs(s)
                    end if
                    if (max(abs(s*qc(1,kwbot - kwtop)),abs(s*qc(1,kwbot - kwtop + 1))) <= &
                              max(smlnum,ulp*temp)) then
                       ! deflatable
                       kwbot = kwbot - 2
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_qtgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                       kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,work,lwork,dtgexc_info)

                       k2 = k2 + 2
                    end if
                    k = k + 2
                 else
                    ! try to deflate real eigenvalue
                    temp = abs(a(kwbot,kwbot))
                    if (temp == zero) then
                       temp = abs(s)
                    end if
                    if ((abs(s*qc(1,kwbot - kwtop + 1))) <= max(ulp*temp,smlnum)) &
                              then
                       ! deflatable
                       kwbot = kwbot - 1
                    else
                       ! not deflatable, move out of the way
                       ifst = kwbot - kwtop + 1
                       ilst = k2
                       call la_qtgexc(.true.,.true.,jw,a(kwtop,kwtop),lda,b(kwtop, &
                       kwtop),ldb,qc,ldqc,zc,ldzc,ifst,ilst,work,lwork,dtgexc_info)

                       k2 = k2 + 1
                    end if
                    k = k + 1
                 end if
              end do
           end if
           ! store eigenvalues
           nd = ihi - kwbot
           ns = jw - nd
           k = kwtop
           do while (k <= ihi)
              bulge = .false.
              if (k < ihi) then
                 if (a(k + 1,k) /= zero) then
                    bulge = .true.
                 end if
              end if
              if (bulge) then
                 ! 2x2 eigenvalue block
                 call la_qlag2(a(k,k),lda,b(k,k),ldb,safmin,beta(k),beta(k + 1), &
                            alphar(k),alphar(k + 1),alphai(k))
                 alphai(k + 1) = -alphai(k)
                 k = k + 2
              else
                 ! 1x1 eigenvalue block
                 alphar(k) = a(k,k)
                 alphai(k) = zero
                 beta(k) = b(k,k)
                 k = k + 1
              end if
           end do
           if (kwtop /= ilo .and. s /= zero) then
              ! reflect spike back, this will create optimally packed bulges
              a(kwtop:kwbot,kwtop - 1) = a(kwtop,kwtop - 1)*qc(1,1:jw - nd)
              do k = kwbot - 1,kwtop,-1
                 call la_qlartg(a(k,kwtop - 1),a(k + 1,kwtop - 1),c1,s1,temp)
                 a(k,kwtop - 1) = temp
                 a(k + 1,kwtop - 1) = zero
                 k2 = max(kwtop,k - 1)
                 call la_qrot(ihi - k2 + 1,a(k,k2),lda,a(k + 1,k2),lda,c1,s1)
                 call la_qrot(ihi - (k - 1) + 1,b(k,k - 1),ldb,b(k + 1,k - 1),ldb,c1,s1)

                 call la_qrot(jw,qc(1,k - kwtop + 1),1,qc(1,k + 1 - kwtop + 1),1,c1,s1)

              end do
              ! chase bulges down
              istartm = kwtop
              istopm = ihi
              k = kwbot - 1
              do while (k >= kwtop)
                 if ((k >= kwtop + 1) .and. a(k + 1,k - 1) /= zero) then
                    ! move double pole block down and remove it
                    do k2 = k - 1,kwbot - 2
                       call la_qlaqz2(.true.,.true.,k2,kwtop,kwtop + jw - 1,kwbot,a,lda,b, &
                                  ldb,jw,kwtop,qc,ldqc,jw,kwtop,zc,ldzc)
                    end do
                    k = k - 2
                 else
                    ! k points to single shift
                    do k2 = k,kwbot - 2
                       ! move shift down
                       call la_qlartg(b(k2 + 1,k2 + 1),b(k2 + 1,k2),c1,s1,temp)
                       b(k2 + 1,k2 + 1) = temp
                       b(k2 + 1,k2) = zero
                       call la_qrot(k2 + 2 - istartm + 1,a(istartm,k2 + 1),1,a(istartm,k2), &
                                 1,c1,s1)
                       call la_qrot(k2 - istartm + 1,b(istartm,k2 + 1),1,b(istartm,k2),1, &
                                 c1,s1)
                       call la_qrot(jw,zc(1,k2 + 1 - kwtop + 1),1,zc(1,k2 - kwtop + 1),1,c1, &
                                 s1)
                       call la_qlartg(a(k2 + 1,k2),a(k2 + 2,k2),c1,s1,temp)
                       a(k2 + 1,k2) = temp
                       a(k2 + 2,k2) = zero
                       call la_qrot(istopm - k2,a(k2 + 1,k2 + 1),lda,a(k2 + 2,k2 + 1),lda,c1, &
                                  s1)
                       call la_qrot(istopm - k2,b(k2 + 1,k2 + 1),ldb,b(k2 + 2,k2 + 1),ldb,c1, &
                                  s1)
                       call la_qrot(jw,qc(1,k2 + 1 - kwtop + 1),1,qc(1,k2 + 2 - kwtop + 1),1, &
                                 c1,s1)
                    end do
                    ! remove the shift
                    call la_qlartg(b(kwbot,kwbot),b(kwbot,kwbot - 1),c1,s1,temp)

                    b(kwbot,kwbot) = temp
                    b(kwbot,kwbot - 1) = zero
                    call la_qrot(kwbot - istartm,b(istartm,kwbot),1,b(istartm,kwbot - 1), &
                               1,c1,s1)
                    call la_qrot(kwbot - istartm + 1,a(istartm,kwbot),1,a(istartm,kwbot - 1 &
                              ),1,c1,s1)
                    call la_qrot(jw,zc(1,kwbot - kwtop + 1),1,zc(1,kwbot - 1 - kwtop + 1),1, &
                              c1,s1)
                    k = k - 1
                 end if
              end do
           end if
           ! apply qc and zc to rest of the matrix
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           if (istopm - ihi > 0) then
              call la_qgemm('T','N',jw,istopm - ihi,jw,one,qc,ldqc,a(kwtop,ihi + 1), &
                        lda,zero,work,jw)
              call la_qlacpy('ALL',jw,istopm - ihi,work,jw,a(kwtop,ihi + 1),lda)
              call la_qgemm('T','N',jw,istopm - ihi,jw,one,qc,ldqc,b(kwtop,ihi + 1), &
                        ldb,zero,work,jw)
              call la_qlacpy('ALL',jw,istopm - ihi,work,jw,b(kwtop,ihi + 1),ldb)
           end if
           if (ilq) then
              call la_qgemm('N','N',n,jw,jw,one,q(1,kwtop),ldq,qc,ldqc,zero, &
                        work,n)
              call la_qlacpy('ALL',n,jw,work,n,q(1,kwtop),ldq)
           end if
           if (kwtop - 1 - istartm + 1 > 0) then
              call la_qgemm('N','N',kwtop - istartm,jw,jw,one,a(istartm,kwtop),lda, &
                        zc,ldzc,zero,work,kwtop - istartm)
              call la_qlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,a(istartm,kwtop &
                        ),lda)
              call la_qgemm('N','N',kwtop - istartm,jw,jw,one,b(istartm,kwtop),ldb, &
                        zc,ldzc,zero,work,kwtop - istartm)
              call la_qlacpy('ALL',kwtop - istartm,jw,work,kwtop - istartm,b(istartm,kwtop &
                        ),ldb)
           end if
           if (ilz) then
              call la_qgemm('N','N',n,jw,jw,one,z(1,kwtop),ldz,zc,ldzc,zero, &
                        work,n)
              call la_qlacpy('ALL',n,jw,work,n,z(1,kwtop),ldz)
           end if
     end subroutine la_qlaqz3

     !> DLAQZ4: Executes a single multishift QZ sweep

     pure subroutine la_qlaqz4(ilschur,ilq,ilz,n,ilo,ihi,nshifts,nblock_qesired,sr, &
               si,ss,a,lda,b,ldb,q,ldq,z,ldz,qc,ldqc,zc,ldzc,work,lwork,info)
           ! function arguments
           logical(lk),intent(in) :: ilschur,ilq,ilz
           integer(ilp),intent(in) :: n,ilo,ihi,lda,ldb,ldq,ldz,lwork,nshifts, &
                     nblock_qesired,ldqc,ldzc
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*),qc( &
                     ldqc,*),zc(ldzc,*),work(*),sr(*),si(*),ss(*)
           integer(ilp),intent(out) :: info

           ! local scalars
           integer(ilp) :: i,j,ns,istartm,istopm,sheight,swidth,k,np,istartb,istopb, &
                     ishift,nblock,npos
           real(qp) :: temp,v(3),c1,s1,c2,s2,swap
           info = 0
           if (nblock_qesired < nshifts + 1) then
              info = -8
           end if
           if (lwork == -1) then
              ! workspace query, quick return
              work(1) = n*nblock_qesired
              return
           else if (lwork < n*nblock_qesired) then
              info = -25
           end if
           if (info /= 0) then
              call la_xerbla('DLAQZ4',-info)
              return
           end if
           ! executable statements
           if (nshifts < 2) then
              return
           end if
           if (ilo >= ihi) then
              return
           end if
           if (ilschur) then
              istartm = 1
              istopm = n
           else
              istartm = ilo
              istopm = ihi
           end if
           ! shuffle shifts into pairs of real shifts and pairs
           ! of complex conjugate shifts assuming complex
           ! conjugate shifts are already adjacent to one
           ! another
           do i = 1,nshifts - 2,2
              if (si(i) /= -si(i + 1)) then
                 swap = sr(i)
                 sr(i) = sr(i + 1)
                 sr(i + 1) = sr(i + 2)
                 sr(i + 2) = swap
                 swap = si(i)
                 si(i) = si(i + 1)
                 si(i + 1) = si(i + 2)
                 si(i + 2) = swap
                 swap = ss(i)
                 ss(i) = ss(i + 1)
                 ss(i + 1) = ss(i + 2)
                 ss(i + 2) = swap
              end if
           end do
           ! nshfts is supposed to be even, but if it is odd,
           ! then simply reduce it by one.  the shuffle above
           ! ensures that the dropped shift is real and that
           ! the remaining shifts are paired.
           ns = nshifts - mod(nshifts,2)
           npos = max(nblock_qesired - ns,1)
           ! the following block introduces the shifts and chases
           ! them down one by one just enough to make space for
           ! the other shifts. the near-the-diagonal block is
           ! of size (ns+1) x ns.
           call la_qlaset('FULL',ns + 1,ns + 1,zero,one,qc,ldqc)
           call la_qlaset('FULL',ns,ns,zero,one,zc,ldzc)
           do i = 1,ns,2
              ! introduce the shift
              call la_qlaqz1(a(ilo,ilo),lda,b(ilo,ilo),ldb,sr(i),sr(i + 1),si( &
                        i),ss(i),ss(i + 1),v)
              temp = v(2)
              call la_qlartg(temp,v(3),c1,s1,v(2))
              call la_qlartg(v(1),v(2),c2,s2,temp)
              call la_qrot(ns,a(ilo + 1,ilo),lda,a(ilo + 2,ilo),lda,c1,s1)
              call la_qrot(ns,a(ilo,ilo),lda,a(ilo + 1,ilo),lda,c2,s2)
              call la_qrot(ns,b(ilo + 1,ilo),ldb,b(ilo + 2,ilo),ldb,c1,s1)
              call la_qrot(ns,b(ilo,ilo),ldb,b(ilo + 1,ilo),ldb,c2,s2)
              call la_qrot(ns + 1,qc(1,2),1,qc(1,3),1,c1,s1)
              call la_qrot(ns + 1,qc(1,1),1,qc(1,2),1,c2,s2)
              ! chase the shift down
              do j = 1,ns - 1 - i
                 call la_qlaqz2(.true.,.true.,j,1,ns,ihi - ilo + 1,a(ilo,ilo),lda,b( &
                           ilo,ilo),ldb,ns + 1,1,qc,ldqc,ns,1,zc,ldzc)
              end do
           end do
           ! update the rest of the pencil
           ! update a(ilo:ilo+ns,ilo+ns:istopm) and b(ilo:ilo+ns,ilo+ns:istopm)
           ! from the left with qc(1:ns+1,1:ns+1)'
           sheight = ns + 1
           swidth = istopm - (ilo + ns) + 1
           if (swidth > 0) then
              call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(ilo,ilo + ns &
                        ),lda,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,a(ilo,ilo + ns),lda)

              call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(ilo,ilo + ns &
                        ),ldb,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,b(ilo,ilo + ns),ldb)

           end if
           if (ilq) then
              call la_qgemm('N','N',n,sheight,sheight,one,q(1,ilo),ldq,qc,ldqc, &
                        zero,work,n)
              call la_qlacpy('ALL',n,sheight,work,n,q(1,ilo),ldq)
           end if
           ! update a(istartm:ilo-1,ilo:ilo+ns-1) and b(istartm:ilo-1,ilo:ilo+ns-1)
           ! from the right with zc(1:ns,1:ns)
           sheight = ilo - 1 - istartm + 1
           swidth = ns
           if (sheight > 0) then
              call la_qgemm('N','N',sheight,swidth,swidth,one,a(istartm,ilo),lda, &
                        zc,ldzc,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ilo),lda)

              call la_qgemm('N','N',sheight,swidth,swidth,one,b(istartm,ilo),ldb, &
                        zc,ldzc,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ilo),ldb)

           end if
           if (ilz) then
              call la_qgemm('N','N',n,swidth,swidth,one,z(1,ilo),ldz,zc,ldzc, &
                        zero,work,n)
              call la_qlacpy('ALL',n,swidth,work,n,z(1,ilo),ldz)
           end if
           ! the following block chases the shifts down to the bottom
           ! right block. if possible, a shift is moved down npos
           ! positions at a time
           k = ilo
           do while (k < ihi - ns)
              np = min(ihi - ns - k,npos)
              ! size of the near-the-diagonal block
              nblock = ns + np
              ! istartb points to the first row we will be updating
              istartb = k + 1
              ! istopb points to the last column we will be updating
              istopb = k + nblock - 1
              call la_qlaset('FULL',ns + np,ns + np,zero,one,qc,ldqc)
              call la_qlaset('FULL',ns + np,ns + np,zero,one,zc,ldzc)
              ! near the diagonal shift chase
              do i = ns - 1,0,-2
                 do j = 0,np - 1
                    ! move down the block with index k+i+j-1, updating
                    ! the (ns+np x ns+np) block:
                    ! (k:k+ns+np,k:k+ns+np-1)
                    call la_qlaqz2(.true.,.true.,k + i + j - 1,istartb,istopb,ihi,a,lda,b, &
                              ldb,nblock,k + 1,qc,ldqc,nblock,k,zc,ldzc)
                 end do
              end do
              ! update rest of the pencil
              ! update a(k+1:k+ns+np, k+ns+np:istopm) and
              ! b(k+1:k+ns+np, k+ns+np:istopm)
              ! from the left with qc(1:ns+np,1:ns+np)'
              sheight = ns + np
              swidth = istopm - (k + ns + np) + 1
              if (swidth > 0) then
                 call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(k + 1,k + &
                           ns + np),lda,zero,work,sheight)
                 call la_qlacpy('ALL',sheight,swidth,work,sheight,a(k + 1,k + ns + np),lda &
                           )
                 call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(k + 1,k + &
                           ns + np),ldb,zero,work,sheight)
                 call la_qlacpy('ALL',sheight,swidth,work,sheight,b(k + 1,k + ns + np),ldb &
                           )
              end if
              if (ilq) then
                 call la_qgemm('N','N',n,nblock,nblock,one,q(1,k + 1),ldq,qc,ldqc, &
                           zero,work,n)
                 call la_qlacpy('ALL',n,nblock,work,n,q(1,k + 1),ldq)
              end if
              ! update a(istartm:k,k:k+ns+npos-1) and b(istartm:k,k:k+ns+npos-1)
              ! from the right with zc(1:ns+np,1:ns+np)
              sheight = k - istartm + 1
              swidth = nblock
              if (sheight > 0) then
                 call la_qgemm('N','N',sheight,swidth,swidth,one,a(istartm,k),lda, &
                           zc,ldzc,zero,work,sheight)
                 call la_qlacpy('ALL',sheight,swidth,work,sheight,a(istartm,k),lda)

                 call la_qgemm('N','N',sheight,swidth,swidth,one,b(istartm,k),ldb, &
                           zc,ldzc,zero,work,sheight)
                 call la_qlacpy('ALL',sheight,swidth,work,sheight,b(istartm,k),ldb)

              end if
              if (ilz) then
                 call la_qgemm('N','N',n,nblock,nblock,one,z(1,k),ldz,zc,ldzc, &
                           zero,work,n)
                 call la_qlacpy('ALL',n,nblock,work,n,z(1,k),ldz)
              end if
              k = k + np
           end do
           ! the following block removes the shifts from the bottom right corner
           ! one by one. updates are initially applied to a(ihi-ns+1:ihi,ihi-ns:ihi).
           call la_qlaset('FULL',ns,ns,zero,one,qc,ldqc)
           call la_qlaset('FULL',ns + 1,ns + 1,zero,one,zc,ldzc)
           ! istartb points to the first row we will be updating
           istartb = ihi - ns + 1
           ! istopb points to the last column we will be updating
           istopb = ihi
           do i = 1,ns,2
              ! chase the shift down to the bottom right corner
              do ishift = ihi - i - 1,ihi - 2
                 call la_qlaqz2(.true.,.true.,ishift,istartb,istopb,ihi,a,lda,b,ldb, &
                           ns,ihi - ns + 1,qc,ldqc,ns + 1,ihi - ns,zc,ldzc)
              end do
           end do
           ! update rest of the pencil
           ! update a(ihi-ns+1:ihi, ihi+1:istopm)
           ! from the left with qc(1:ns,1:ns)'
           sheight = ns
           swidth = istopm - (ihi + 1) + 1
           if (swidth > 0) then
              call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,a(ihi - ns + 1, &
                        ihi + 1),lda,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,a(ihi - ns + 1,ihi + 1),lda &
                        )
              call la_qgemm('T','N',sheight,swidth,sheight,one,qc,ldqc,b(ihi - ns + 1, &
                        ihi + 1),ldb,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,b(ihi - ns + 1,ihi + 1),ldb &
                        )
           end if
           if (ilq) then
              call la_qgemm('N','N',n,ns,ns,one,q(1,ihi - ns + 1),ldq,qc,ldqc,zero, &
                        work,n)
              call la_qlacpy('ALL',n,ns,work,n,q(1,ihi - ns + 1),ldq)
           end if
           ! update a(istartm:ihi-ns,ihi-ns:ihi)
           ! from the right with zc(1:ns+1,1:ns+1)
           sheight = ihi - ns - istartm + 1
           swidth = ns + 1
           if (sheight > 0) then
              call la_qgemm('N','N',sheight,swidth,swidth,one,a(istartm,ihi - ns),lda, &
                         zc,ldzc,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,a(istartm,ihi - ns),lda &
                        )
              call la_qgemm('N','N',sheight,swidth,swidth,one,b(istartm,ihi - ns),ldb, &
                         zc,ldzc,zero,work,sheight)
              call la_qlacpy('ALL',sheight,swidth,work,sheight,b(istartm,ihi - ns),ldb &
                        )
           end if
           if (ilz) then
              call la_qgemm('N','N',n,ns + 1,ns + 1,one,z(1,ihi - ns),ldz,zc,ldzc,zero, &
                         work,n)
              call la_qlacpy('ALL',n,ns + 1,work,n,z(1,ihi - ns),ldz)
           end if
     end subroutine la_qlaqz4

     !> DLAR1V: computes the (scaled) r-th column of the inverse of
     !> the sumbmatrix in rows B1 through BN of the tridiagonal matrix
     !> L D L**T - sigma I. When sigma is close to an eigenvalue, the
     !> computed vector is an accurate eigenvector. Usually, r corresponds
     !> to the index where the eigenvector is largest in magnitude.
     !> The following steps accomplish this computation :
     !> (a) Stationary qd transform,  L D L**T - sigma I = L(+) D(+) L(+)**T,
     !> (b) Progressive qd transform, L D L**T - sigma I = U(-) D(-) U(-)**T,
     !> (c) Computation of the diagonal elements of the inverse of
     !> L D L**T - sigma I by combining the above transforms, and choosing
     !> r as the index where the diagonal of the inverse is (one of the)
     !> largest in magnitude.
     !> (d) Computation of the (scaled) r-th column of the inverse using the
     !> twisted factorization obtained by combining the top part of the
     !> the stationary and the bottom part of the progressive transform.

     pure subroutine la_qlar1v(n,b1,bn,lambda,d,l,ld,lld,pivmin,gaptol,z,wantnc, &
               negcnt,ztz,mingma,r,isuppz,nrminv,resid,rqcorr,work)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: wantnc
           integer(ilp),intent(in) :: b1,bn,n
           integer(ilp),intent(out) :: negcnt
           integer(ilp),intent(inout) :: r
           real(qp),intent(in) :: gaptol,lambda,pivmin
           real(qp),intent(out) :: mingma,nrminv,resid,rqcorr,ztz
           ! Array Arguments
           integer(ilp),intent(out) :: isuppz(*)
           real(qp),intent(in) :: d(*),l(*),ld(*),lld(*)
           real(qp),intent(out) :: work(*)
           real(qp),intent(inout) :: z(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: sawnan1,sawnan2
           integer(ilp) :: i,indlpl,indp,inds,indumn,neg1,neg2,r1,r2
           real(qp) :: dminus,dplus,eps,s,tmp
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           eps = la_qlamch('PRECISION')
           if (r == 0) then
              r1 = b1
              r2 = bn
           else
              r1 = r
              r2 = r
           end if
           ! storage for lplus
           indlpl = 0
           ! storage for uminus
           indumn = n
           inds = 2*n + 1
           indp = 3*n + 1
           if (b1 == 1) then
              work(inds) = zero
           else
              work(inds + b1 - 1) = lld(b1 - 1)
           end if
           ! compute the stationary transform (using the differential form)
           ! until the index r2.
           sawnan1 = .false.
           neg1 = 0
           s = work(inds + b1 - 1) - lambda
           do i = b1,r1 - 1
              dplus = d(i) + s
              work(indlpl + i) = ld(i)/dplus
              if (dplus < zero) neg1 = neg1 + 1
              work(inds + i) = s*work(indlpl + i)*l(i)
              s = work(inds + i) - lambda
           end do
           sawnan1 = la_qisnan(s)
           if (sawnan1) goto 60
           do i = r1,r2 - 1
              dplus = d(i) + s
              work(indlpl + i) = ld(i)/dplus
              work(inds + i) = s*work(indlpl + i)*l(i)
              s = work(inds + i) - lambda
           end do
           sawnan1 = la_qisnan(s)
           60 continue
           if (sawnan1) then
              ! runs a slower version of the above loop if a nan is detected
              neg1 = 0
              s = work(inds + b1 - 1) - lambda
              do i = b1,r1 - 1
                 dplus = d(i) + s
                 if (abs(dplus) < pivmin) dplus = -pivmin
                 work(indlpl + i) = ld(i)/dplus
                 if (dplus < zero) neg1 = neg1 + 1
                 work(inds + i) = s*work(indlpl + i)*l(i)
                 if (work(indlpl + i) == zero) work(inds + i) = lld(i)
                 s = work(inds + i) - lambda
              end do
              do i = r1,r2 - 1
                 dplus = d(i) + s
                 if (abs(dplus) < pivmin) dplus = -pivmin
                 work(indlpl + i) = ld(i)/dplus
                 work(inds + i) = s*work(indlpl + i)*l(i)
                 if (work(indlpl + i) == zero) work(inds + i) = lld(i)
                 s = work(inds + i) - lambda
              end do
           end if
           ! compute the progressive transform (using the differential form)
           ! until the index r1
           sawnan2 = .false.
           neg2 = 0
           work(indp + bn - 1) = d(bn) - lambda
           do i = bn - 1,r1,-1
              dminus = lld(i) + work(indp + i)
              tmp = d(i)/dminus
              if (dminus < zero) neg2 = neg2 + 1
              work(indumn + i) = l(i)*tmp
              work(indp + i - 1) = work(indp + i)*tmp - lambda
           end do
           tmp = work(indp + r1 - 1)
           sawnan2 = la_qisnan(tmp)
           if (sawnan2) then
              ! runs a slower version of the above loop if a nan is detected
              neg2 = 0
              do i = bn - 1,r1,-1
                 dminus = lld(i) + work(indp + i)
                 if (abs(dminus) < pivmin) dminus = -pivmin
                 tmp = d(i)/dminus
                 if (dminus < zero) neg2 = neg2 + 1
                 work(indumn + i) = l(i)*tmp
                 work(indp + i - 1) = work(indp + i)*tmp - lambda
                 if (tmp == zero) work(indp + i - 1) = d(i) - lambda
              end do
           end if
           ! find the index (from r1 to r2) of the largest (in magnitude)
           ! diagonal element of the inverse
           mingma = work(inds + r1 - 1) + work(indp + r1 - 1)
           if (mingma < zero) neg1 = neg1 + 1
           if (wantnc) then
              negcnt = neg1 + neg2
           else
              negcnt = -1
           end if
           if (abs(mingma) == zero) mingma = eps*work(inds + r1 - 1)
           r = r1
           do i = r1,r2 - 1
              tmp = work(inds + i) + work(indp + i)
              if (tmp == zero) tmp = eps*work(inds + i)
              if (abs(tmp) <= abs(mingma)) then
                 mingma = tmp
                 r = i + 1
              end if
           end do
           ! compute the fp vector: solve n^t v = e_r
           isuppz(1) = b1
           isuppz(2) = bn
           z(r) = one
           ztz = one
           ! compute the fp vector upwards from r
           if (.not. sawnan1 .and. .not. sawnan2) then
              do i = r - 1,b1,-1
                 z(i) = -(work(indlpl + i)*z(i + 1))
                 if ((abs(z(i)) + abs(z(i + 1)))*abs(ld(i)) < gaptol) then
                    z(i) = zero
                    isuppz(1) = i + 1
                    goto 220
                 end if
                 ztz = ztz + z(i)*z(i)
              end do
              220 continue
           else
              ! run slower loop if nan occurred.
              do i = r - 1,b1,-1
                 if (z(i + 1) == zero) then
                    z(i) = -(ld(i + 1)/ld(i))*z(i + 2)
                 else
                    z(i) = -(work(indlpl + i)*z(i + 1))
                 end if
                 if ((abs(z(i)) + abs(z(i + 1)))*abs(ld(i)) < gaptol) then
                    z(i) = zero
                    isuppz(1) = i + 1
                    go to 240
                 end if
                 ztz = ztz + z(i)*z(i)
              end do
              240 continue
           end if
           ! compute the fp vector downwards from r in blocks of size blksiz
           if (.not. sawnan1 .and. .not. sawnan2) then
              do i = r,bn - 1
                 z(i + 1) = -(work(indumn + i)*z(i))
                 if ((abs(z(i)) + abs(z(i + 1)))*abs(ld(i)) < gaptol) then
                    z(i + 1) = zero
                    isuppz(2) = i
                    go to 260
                 end if
                 ztz = ztz + z(i + 1)*z(i + 1)
              end do
              260 continue
           else
              ! run slower loop if nan occurred.
              do i = r,bn - 1
                 if (z(i) == zero) then
                    z(i + 1) = -(ld(i - 1)/ld(i))*z(i - 1)
                 else
                    z(i + 1) = -(work(indumn + i)*z(i))
                 end if
                 if ((abs(z(i)) + abs(z(i + 1)))*abs(ld(i)) < gaptol) then
                    z(i + 1) = zero
                    isuppz(2) = i
                    go to 280
                 end if
                 ztz = ztz + z(i + 1)*z(i + 1)
              end do
              280 continue
           end if
           ! compute quantities for convergence test
           tmp = one/ztz
           nrminv = sqrt(tmp)
           resid = abs(mingma)*nrminv
           rqcorr = mingma*tmp
           return
     end subroutine la_qlar1v

     !> Compute the splitting points with threshold SPLTOL.
     !> DLARRA: sets any "small" off-diagonal elements to zero.

     pure subroutine la_qlarra(n,d,e,e2,spltol,tnrm,nsplit,isplit,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info,nsplit
           integer(ilp),intent(in) :: n
           real(qp),intent(in) :: spltol,tnrm
           ! Array Arguments
           integer(ilp),intent(out) :: isplit(*)
           real(qp),intent(in) :: d(*)
           real(qp),intent(inout) :: e(*),e2(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i
           real(qp) :: eabs,tmp1
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n <= 0) then
              return
           end if
           ! compute splitting points
           nsplit = 1
           if (spltol < zero) then
              ! criterion based on absolute off-diagonal value
              tmp1 = abs(spltol)*tnrm
              do i = 1,n - 1
                 eabs = abs(e(i))
                 if (eabs <= tmp1) then
                    e(i) = zero
                    e2(i) = zero
                    isplit(nsplit) = i
                    nsplit = nsplit + 1
                 end if
              end do
           else
              ! criterion that guarantees relative accuracy
              do i = 1,n - 1
                 eabs = abs(e(i))
                 if (eabs <= spltol*sqrt(abs(d(i)))*sqrt(abs(d(i + 1)))) then
                    e(i) = zero
                    e2(i) = zero
                    isplit(nsplit) = i
                    nsplit = nsplit + 1
                 end if
              end do
           end if
           isplit(nsplit) = n
           return
     end subroutine la_qlarra

     !> Given the relatively robust representation(RRR) L D L^T, DLARRB:
     !> does "limited" bisection to refine the eigenvalues of L D L^T,
     !> W( IFIRST-OFFSET ) through W( ILAST-OFFSET ), to more accuracy. Initial
     !> guesses for these eigenvalues are input in W, the corresponding estimate
     !> of the error in these guesses and their gaps are input in WERR
     !> and WGAP, respectively. During bisection, intervals
     !> [left, right] are maintained by storing their mid-points and
     !> semi-widths in the arrays W and WERR respectively.

     pure subroutine la_qlarrb(n,d,lld,ifirst,ilast,rtol1,rtol2,offset,w,wgap,werr, &
               work,iwork,pivmin,spdiam,twist,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ifirst,ilast,n,offset,twist
           integer(ilp),intent(out) :: info
           real(qp),intent(in) :: pivmin,rtol1,rtol2,spdiam
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(in) :: d(*),lld(*)
           real(qp),intent(inout) :: w(*),werr(*),wgap(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           integer(ilp) :: maxitr
           ! Local Scalars
           integer(ilp) :: i,i1,ii,ip,iter,k,negcnt,next,nint,olnint,prev,r
           real(qp) :: back,cvrgd,gap,left,lgap,mid,mnwdth,rgap,right,tmp,width
           ! Intrinsic Functions
           intrinsic :: abs,max,min
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n <= 0) then
              return
           end if
           maxitr = int((log(spdiam + pivmin) - log(pivmin))/log(two),KIND=ilp) + 2
           mnwdth = two*pivmin
           r = twist
           if ((r < 1) .or. (r > n)) r = n
           ! initialize unconverged intervals in [ work(2*i-1), work(2*i) ].
           ! the sturm count, count( work(2*i-1) ) is arranged to be i-1, while
           ! count( work(2*i) ) is stored in iwork( 2*i ). the integer iwork( 2*i-1 )
           ! for an unconverged interval is set to the index of the next unconverged
           ! interval, and is -1 or 0 for a converged interval. thus a linked
           ! list of unconverged intervals is set up.
           i1 = ifirst
           ! the number of unconverged intervals
           nint = 0
           ! the last unconverged interval found
           prev = 0
           rgap = wgap(i1 - offset)
           loop_75: do i = i1,ilast
              k = 2*i
              ii = i - offset
              left = w(ii) - werr(ii)
              right = w(ii) + werr(ii)
              lgap = rgap
              rgap = wgap(ii)
              gap = min(lgap,rgap)
              ! make sure that [left,right] contains the desired eigenvalue
              ! compute negcount from dstqds facto l+d+l+^t = l d l^t - left
              ! do while( negcnt(left)>i-1 )
              back = werr(ii)
              20 continue
              negcnt = la_qlaneg(n,d,lld,left,pivmin,r)
              if (negcnt > i - 1) then
                 left = left - back
                 back = two*back
                 go to 20
              end if
              ! do while( negcnt(right)<i )
              ! compute negcount from dstqds facto l+d+l+^t = l d l^t - right
              back = werr(ii)
              50 continue
              negcnt = la_qlaneg(n,d,lld,right,pivmin,r)
               if (negcnt < i) then
                  right = right + back
                  back = two*back
                  go to 50
               end if
              width = half*abs(left - right)
              tmp = max(abs(left),abs(right))
              cvrgd = max(rtol1*gap,rtol2*tmp)
              if (width <= cvrgd .or. width <= mnwdth) then
                 ! this interval has already converged and does not need refinement.
                 ! (note that the gaps might change through refining the
                  ! eigenvalues, however, they can only get bigger.)
                 ! remove it from the list.
                 iwork(k - 1) = -1
                 ! make sure that i1 always points to the first unconverged interval
                 if ((i == i1) .and. (i < ilast)) i1 = i + 1
                 if ((prev >= i1) .and. (i <= ilast)) iwork(2*prev - 1) = i + 1
              else
                 ! unconverged interval found
                 prev = i
                 nint = nint + 1
                 iwork(k - 1) = i + 1
                 iwork(k) = negcnt
              end if
              work(k - 1) = left
              work(k) = right
           end do loop_75
           ! do while( nint>0 ), i.e. there are still unconverged intervals
           ! and while (iter<maxitr)
           iter = 0
           80 continue
           prev = i1 - 1
           i = i1
           olnint = nint
           loop_100: do ip = 1,olnint
              k = 2*i
              ii = i - offset
              rgap = wgap(ii)
              lgap = rgap
              if (ii > 1) lgap = wgap(ii - 1)
              gap = min(lgap,rgap)
              next = iwork(k - 1)
              left = work(k - 1)
              right = work(k)
              mid = half*(left + right)
              ! semiwidth of interval
              width = right - mid
              tmp = max(abs(left),abs(right))
              cvrgd = max(rtol1*gap,rtol2*tmp)
              if ((width <= cvrgd) .or. (width <= mnwdth) .or. (iter == maxitr)) then
                 ! reduce number of unconverged intervals
                 nint = nint - 1
                 ! mark interval as converged.
                 iwork(k - 1) = 0
                 if (i1 == i) then
                    i1 = next
                 else
                    ! prev holds the last unconverged interval previously examined
                    if (prev >= i1) iwork(2*prev - 1) = next
                 end if
                 i = next
                 cycle loop_100
              end if
              prev = i
              ! perform one bisection step
              negcnt = la_qlaneg(n,d,lld,mid,pivmin,r)
              if (negcnt <= i - 1) then
                 work(k - 1) = mid
              else
                 work(k) = mid
              end if
              i = next
           end do loop_100
           iter = iter + 1
           ! do another loop if there are still unconverged intervals
           ! however, in the last iteration, all intervals are accepted
           ! since this is the best we can do.
           if ((nint > 0) .and. (iter <= maxitr)) go to 80
           ! at this point, all the intervals have converged
           do i = ifirst,ilast
              k = 2*i
              ii = i - offset
              ! all intervals marked by '0' have been refined.
              if (iwork(k - 1) == 0) then
                 w(ii) = half*(work(k - 1) + work(k))
                 werr(ii) = work(k) - w(ii)
              end if
           end do
           do i = ifirst + 1,ilast
              k = 2*i
              ii = i - offset
              wgap(ii - 1) = max(zero,w(ii) - werr(ii) - w(ii - 1) - werr(ii - 1))
           end do
           return
     end subroutine la_qlarrb

     !> Find the number of eigenvalues of the symmetric tridiagonal matrix T
     !> that are in the interval (VL,VU] if JOBT = 'T', and of L D L^T
     !> if JOBT = 'L'.

     pure subroutine la_qlarrc(jobt,n,vl,vu,d,e,pivmin,eigcnt,lcnt,rcnt,info)

        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobt
           integer(ilp),intent(out) :: eigcnt,info,lcnt,rcnt
           integer(ilp),intent(in) :: n
           real(qp),intent(in) :: pivmin,vl,vu
           ! Array Arguments
           real(qp),intent(in) :: d(*),e(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i
           logical(lk) :: matt
           real(qp) :: lpivot,rpivot,sl,su,tmp,tmp2
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n <= 0) then
              return
           end if
           lcnt = 0
           rcnt = 0
           eigcnt = 0
           matt = la_lsame(jobt,'T')
           if (matt) then
              ! sturm sequence count on t
              lpivot = d(1) - vl
              rpivot = d(1) - vu
              if (lpivot <= zero) then
                 lcnt = lcnt + 1
              end if
              if (rpivot <= zero) then
                 rcnt = rcnt + 1
              end if
              do i = 1,n - 1
                 tmp = e(i)**2
                 lpivot = (d(i + 1) - vl) - tmp/lpivot
                 rpivot = (d(i + 1) - vu) - tmp/rpivot
                 if (lpivot <= zero) then
                    lcnt = lcnt + 1
                 end if
                 if (rpivot <= zero) then
                    rcnt = rcnt + 1
                 end if
              end do
           else
              ! sturm sequence count on l d l^t
              sl = -vl
              su = -vu
              do i = 1,n - 1
                 lpivot = d(i) + sl
                 rpivot = d(i) + su
                 if (lpivot <= zero) then
                    lcnt = lcnt + 1
                 end if
                 if (rpivot <= zero) then
                    rcnt = rcnt + 1
                 end if
                 tmp = e(i)*d(i)*e(i)
                 tmp2 = tmp/lpivot
                 if (tmp2 == zero) then
                    sl = tmp - vl
                 else
                    sl = sl*tmp2 - vl
                 end if
                 tmp2 = tmp/rpivot
                 if (tmp2 == zero) then
                    su = tmp - vu
                 else
                    su = su*tmp2 - vu
                 end if
              end do
              lpivot = d(n) + sl
              rpivot = d(n) + su
              if (lpivot <= zero) then
                 lcnt = lcnt + 1
              end if
              if (rpivot <= zero) then
                 rcnt = rcnt + 1
              end if
           end if
           eigcnt = rcnt - lcnt
           return
     end subroutine la_qlarrc

     !> DLARRD: computes the eigenvalues of a symmetric tridiagonal
     !> matrix T to suitable accuracy. This is an auxiliary code to be
     !> called from DSTEMR.
     !> The user may ask for all eigenvalues, all eigenvalues
     !> in the half-open interval (VL, VU], or the IL-th through IU-th
     !> eigenvalues.
     !> To avoid overflow, the matrix must be scaled so that its
     !> largest element is no greater than overflow**(1/2) * underflow**(1/4) in absolute value, and for greatest
     !> accuracy, it should not be much smaller than that.
     !> See W. Kahan "Accurate Eigenvalues of a Symmetric Tridiagonal
     !> Matrix", Report CS41, Computer Science Dept., Stanford
     !> University, July 21, 1966.

     pure subroutine la_qlarrd(range,order,n,vl,vu,il,iu,gers,reltol,d,e,e2, &
               pivmin,nsplit,isplit,m,w,werr,wl,wu,iblock,indexw,work,iwork,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: order,range
           integer(ilp),intent(in) :: il,iu,n,nsplit
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: pivmin,reltol,vl,vu
           real(qp),intent(out) :: wl,wu
           ! Array Arguments
           integer(ilp),intent(out) :: iblock(*),indexw(*),iwork(*)
           integer(ilp),intent(in) :: isplit(*)
           real(qp),intent(in) :: d(*),e(*),e2(*),gers(*)
           real(qp),intent(out) :: w(*),werr(*),work(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: fudge = two
           integer(ilp),parameter :: allrng = 1
           integer(ilp),parameter :: valrng = 2
           integer(ilp),parameter :: indrng = 3

           ! Local Scalars
           logical(lk) :: ncnvrg,toofew
           integer(ilp) :: i,ib,ibegin,idiscl,idiscu,ie,iend,iinfo,im,in,ioff,iout, &
                     irange,itmax,itmp1,itmp2,iw,iwoff,j,jblk,jdisc,je,jee,nb,nwl,nwu
           real(qp) :: atoli,eps,gl,gu,rtoli,tmp1,tmp2,tnorm,uflow,wkill,wlu, &
                     wul
           ! Local Arrays
           integer(ilp) :: idumma(1)
           ! Intrinsic Functions
           intrinsic :: abs,int,log,max,min
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n <= 0) then
              return
           end if
           ! decode range
           if (la_lsame(range,'A')) then
              irange = allrng
           else if (la_lsame(range,'V')) then
              irange = valrng
           else if (la_lsame(range,'I')) then
              irange = indrng
           else
              irange = 0
           end if
           ! check for errors
           if (irange <= 0) then
              info = -1
           else if (.not. (la_lsame(order,'B') .or. la_lsame(order,'E'))) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (irange == valrng) then
              if (vl >= vu) info = -5
           else if (irange == indrng .and. (il < 1 .or. il > max(1,n))) then
              info = -6
           else if (irange == indrng .and. (iu < min(n,il) .or. iu > n)) then
              info = -7
           end if
           if (info /= 0) then
              return
           end if
           ! initialize error flags
           info = 0
           ncnvrg = .false.
           toofew = .false.
           ! quick return if possible
           m = 0
           if (n == 0) return
           ! simplification:
           if (irange == indrng .and. il == 1 .and. iu == n) irange = 1
           ! get machine constants
           eps = la_qlamch('P')
           uflow = la_qlamch('U')
           ! special case when n=1
           ! treat case of 1x1 matrix for quick return
           if (n == 1) then
              if ((irange == allrng) .or. ((irange == valrng) .and. (d(1) > vl) .and. (d(1) <= vu)) .or. (( &
                        irange == indrng) .and. (il == 1) .and. (iu == 1))) then
                 m = 1
                 w(1) = d(1)
                 ! the computation error of the eigenvalue is zero
                 werr(1) = zero
                 iblock(1) = 1
                 indexw(1) = 1
              end if
              return
           end if
           ! nb is the minimum vector length for vector bisection, or 0
           ! if only scalar is to be done.
           nb = la_ilaenv(1,'DSTEBZ',' ',n,-1,-1,-1)
           if (nb <= 1) nb = 0
           ! find global spectral radius
           gl = d(1)
           gu = d(1)
           do i = 1,n
              gl = min(gl,gers(2*i - 1))
              gu = max(gu,gers(2*i))
           end do
           ! compute global gerschgorin bounds and spectral diameter
           tnorm = max(abs(gl),abs(gu))
           gl = gl - fudge*tnorm*eps*n - fudge*two*pivmin
           gu = gu + fudge*tnorm*eps*n + fudge*two*pivmin
           ! [jan/28/2009] remove the line below since spdiam variable not use
           ! spdiam = gu - gl
           ! input arguments for la_qlaebz:
           ! the relative tolerance.  an interval (a,b] lies within
           ! "relative tolerance" if  b-a < reltol*max(|a|,|b|),
           rtoli = reltol
           ! set the absolute tolerance for interval convergence to zero to force
           ! interval convergence based on relative size of the interval.
           ! this is dangerous because intervals might not converge when reltol is
           ! small. but at least a very small number should be selected so that for
           ! strongly graded matrices, the code can get relatively accurate
           ! eigenvalues.
           atoli = fudge*two*uflow + fudge*two*pivmin
           if (irange == indrng) then
              ! range='i': compute an interval containing eigenvalues
              ! il through iu. the initial interval [gl,gu] from the global
              ! gerschgorin bounds gl and gu is refined by la_qlaebz.
              itmax = int((log(tnorm + pivmin) - log(pivmin))/log(two),KIND=ilp) + 2
              work(n + 1) = gl
              work(n + 2) = gl
              work(n + 3) = gu
              work(n + 4) = gu
              work(n + 5) = gl
              work(n + 6) = gu
              iwork(1) = -1
              iwork(2) = -1
              iwork(3) = n + 1
              iwork(4) = n + 1
              iwork(5) = il - 1
              iwork(6) = iu
              call la_qlaebz(3,itmax,n,2,2,nb,atoli,rtoli,pivmin,d,e,e2,iwork(5) &
                        ,work(n + 1),work(n + 5),iout,iwork,w,iblock,iinfo)
              if (iinfo /= 0) then
                 info = iinfo
                 return
              end if
              ! on exit, output intervals may not be ordered by ascending negcount
              if (iwork(6) == iu) then
                 wl = work(n + 1)
                 wlu = work(n + 3)
                 nwl = iwork(1)
                 wu = work(n + 4)
                 wul = work(n + 2)
                 nwu = iwork(4)
              else
                 wl = work(n + 2)
                 wlu = work(n + 4)
                 nwl = iwork(2)
                 wu = work(n + 3)
                 wul = work(n + 1)
                 nwu = iwork(3)
              end if
              ! on exit, the interval [wl, wlu] contains a value with negcount nwl,
              ! and [wul, wu] contains a value with negcount nwu.
              if (nwl < 0 .or. nwl >= n .or. nwu < 1 .or. nwu > n) then
                 info = 4
                 return
              end if
           elseif (irange == valrng) then
              wl = vl
              wu = vu
           elseif (irange == allrng) then
              wl = gl
              wu = gu
           end if
           ! find eigenvalues -- loop over blocks and recompute nwl and nwu.
           ! nwl accumulates the number of eigenvalues .le. wl,
           ! nwu accumulates the number of eigenvalues .le. wu
           m = 0
           iend = 0
           info = 0
           nwl = 0
           nwu = 0
           loop_70: do jblk = 1,nsplit
              ioff = iend
              ibegin = ioff + 1
              iend = isplit(jblk)
              in = iend - ioff
              if (in == 1) then
                 ! 1x1 block
                 if (wl >= d(ibegin) - pivmin) nwl = nwl + 1
                 if (wu >= d(ibegin) - pivmin) nwu = nwu + 1
                 if (irange == allrng .or. (wl < d(ibegin) - pivmin .and. wu >= d(ibegin) - pivmin)) &
                           then
                    m = m + 1
                    w(m) = d(ibegin)
                    werr(m) = zero
                    ! the gap for a single block doesn't matter for the later
                    ! algorithm and is assigned an arbitrary large value
                    iblock(m) = jblk
                    indexw(m) = 1
                 end if
              ! disabled 2x2 case because of a failure on the following matrix
              ! range = 'i', il = iu = 4
                ! original tridiagonal, d = [
                 ! -0.150102010615740e+00_qp
                 ! -0.849897989384260e+00_qp
                 ! -0.128208148052635e-15_qp
                  ! 0.128257718286320e-15_qp
                ! ];
                ! e = [
                 ! -0.357171383266986e+00_qp
                 ! -0.180411241501588e-15_qp
                 ! -0.175152352710251e-15_qp
                ! ];
               ! else if( in==2 ) then
      ! *           2x2 block
                  ! disc = sqrt( (half*(d(ibegin)-d(iend)))**2 + e(ibegin)**2 )
                  ! tmp1 = half*(d(ibegin)+d(iend))
                  ! l1 = tmp1 - disc
                  ! if( wl>= l1-pivmin )
           ! $         nwl = nwl + 1
                  ! if( wu>= l1-pivmin )
           ! $         nwu = nwu + 1
                  ! if( irange==allrng .or. ( wl<l1-pivmin .and. wu>=
           ! $          l1-pivmin ) ) then
                     ! m = m + 1
                     ! w( m ) = l1
      ! *              the uncertainty of eigenvalues of a 2x2 matrix is very small
                     ! werr( m ) = eps * abs( w( m ) ) * two
                     ! iblock( m ) = jblk
                     ! indexw( m ) = 1
                  ! endif
                  ! l2 = tmp1 + disc
                  ! if( wl>= l2-pivmin )
           ! $         nwl = nwl + 1
                  ! if( wu>= l2-pivmin )
           ! $         nwu = nwu + 1
                  ! if( irange==allrng .or. ( wl<l2-pivmin .and. wu>=
           ! $          l2-pivmin ) ) then
                     ! m = m + 1
                     ! w( m ) = l2
      ! *              the uncertainty of eigenvalues of a 2x2 matrix is very small
                     ! werr( m ) = eps * abs( w( m ) ) * two
                     ! iblock( m ) = jblk
                     ! indexw( m ) = 2
                  ! endif
              else
                 ! general case - block of size in >= 2
                 ! compute local gerschgorin interval and use it as the initial
                 ! interval for la_qlaebz
                 gu = d(ibegin)
                 gl = d(ibegin)
                 tmp1 = zero
                 do j = ibegin,iend
                    gl = min(gl,gers(2*j - 1))
                    gu = max(gu,gers(2*j))
                 end do
                 ! [jan/28/2009]
                 ! change spdiam by tnorm in lines 2 and 3 thereafter
                 ! line 1: remove computation of spdiam (not useful anymore)
                 ! spdiam = gu - gl
                 ! gl = gl - fudge*spdiam*eps*in - fudge*pivmin
                 ! gu = gu + fudge*spdiam*eps*in + fudge*pivmin
                 gl = gl - fudge*tnorm*eps*in - fudge*pivmin
                 gu = gu + fudge*tnorm*eps*in + fudge*pivmin
                 if (irange > 1) then
                    if (gu < wl) then
                       ! the local block contains none of the wanted eigenvalues
                       nwl = nwl + in
                       nwu = nwu + in
                       cycle loop_70
                    end if
                    ! refine search interval if possible, only range (wl,wu] matters
                    gl = max(gl,wl)
                    gu = min(gu,wu)
                    if (gl >= gu) cycle loop_70
                 end if
                 ! find negcount of initial interval boundaries gl and gu
                 work(n + 1) = gl
                 work(n + in + 1) = gu
                 call la_qlaebz(1,0,in,in,1,nb,atoli,rtoli,pivmin,d(ibegin),e( &
                 ibegin),e2(ibegin),idumma,work(n + 1),work(n + 2*in + 1),im,iwork,w(m + 1), &
                            iblock(m + 1),iinfo)
                 if (iinfo /= 0) then
                    info = iinfo
                    return
                 end if
                 nwl = nwl + iwork(1)
                 nwu = nwu + iwork(in + 1)
                 iwoff = m - iwork(1)
                 ! compute eigenvalues
                 itmax = int((log(gu - gl + pivmin) - log(pivmin))/log(two),KIND=ilp) + &
                           2
                 call la_qlaebz(2,itmax,in,in,1,nb,atoli,rtoli,pivmin,d(ibegin),e( &
                  ibegin),e2(ibegin),idumma,work(n + 1),work(n + 2*in + 1),iout,iwork,w(m + &
                            1),iblock(m + 1),iinfo)
                 if (iinfo /= 0) then
                    info = iinfo
                    return
                 end if
                 ! copy eigenvalues into w and iblock
                 ! use -jblk for block number for unconverged eigenvalues.
                 ! loop over the number of output intervals from la_qlaebz
                 do j = 1,iout
                    ! eigenvalue approximation is middle point of interval
                    tmp1 = half*(work(j + n) + work(j + in + n))
                    ! semi length of error interval
                    tmp2 = half*abs(work(j + n) - work(j + in + n))
                    if (j > iout - iinfo) then
                       ! flag non-convergence.
                       ncnvrg = .true.
                       ib = -jblk
                    else
                       ib = jblk
                    end if
                    do je = iwork(j) + 1 + iwoff,iwork(j + in) + iwoff
                       w(je) = tmp1
                       werr(je) = tmp2
                       indexw(je) = je - iwoff
                       iblock(je) = ib
                    end do
                 end do
                 m = m + im
              end if
           end do loop_70
           ! if range='i', then (wl,wu) contains eigenvalues nwl+1,...,nwu
           ! if nwl+1 < il or nwu > iu, discard extra eigenvalues.
           if (irange == indrng) then
              idiscl = il - 1 - nwl
              idiscu = nwu - iu
              if (idiscl > 0) then
                 im = 0
                 do je = 1,m
                    ! remove some of the smallest eigenvalues from the left so that
                    ! at the end idiscl =0. move all eigenvalues up to the left.
                    if (w(je) <= wlu .and. idiscl > 0) then
                       idiscl = idiscl - 1
                    else
                       im = im + 1
                       w(im) = w(je)
                       werr(im) = werr(je)
                       indexw(im) = indexw(je)
                       iblock(im) = iblock(je)
                    end if
                 end do
                 m = im
              end if
              if (idiscu > 0) then
                 ! remove some of the largest eigenvalues from the right so that
                 ! at the end idiscu =0. move all eigenvalues up to the left.
                 im = m + 1
                 do je = m,1,-1
                    if (w(je) >= wul .and. idiscu > 0) then
                       idiscu = idiscu - 1
                    else
                       im = im - 1
                       w(im) = w(je)
                       werr(im) = werr(je)
                       indexw(im) = indexw(je)
                       iblock(im) = iblock(je)
                    end if
                 end do
                 jee = 0
                 do je = im,m
                    jee = jee + 1
                    w(jee) = w(je)
                    werr(jee) = werr(je)
                    indexw(jee) = indexw(je)
                    iblock(jee) = iblock(je)
                 end do
                 m = m - im + 1
              end if
              if (idiscl > 0 .or. idiscu > 0) then
                 ! code to deal with effects of bad arithmetic. (if n(w) is
                 ! monotone non-decreasing, this should never happen.)
                 ! some low eigenvalues to be discarded are not in (wl,wlu],
                 ! or high eigenvalues to be discarded are not in (wul,wu]
                 ! so just kill off the smallest idiscl/largest idiscu
                 ! eigenvalues, by marking the corresponding iblock = 0
                 if (idiscl > 0) then
                    wkill = wu
                    do jdisc = 1,idiscl
                       iw = 0
                       do je = 1,m
                          if (iblock(je) /= 0 .and. (w(je) < wkill .or. iw == 0)) then
                             iw = je
                             wkill = w(je)
                          end if
                       end do
                       iblock(iw) = 0
                    end do
                 end if
                 if (idiscu > 0) then
                    wkill = wl
                    do jdisc = 1,idiscu
                       iw = 0
                       do je = 1,m
                          if (iblock(je) /= 0 .and. (w(je) >= wkill .or. iw == 0)) then
                             iw = je
                             wkill = w(je)
                          end if
                       end do
                       iblock(iw) = 0
                    end do
                 end if
                 ! now erase all eigenvalues with iblock set to zero
                 im = 0
                 do je = 1,m
                    if (iblock(je) /= 0) then
                       im = im + 1
                       w(im) = w(je)
                       werr(im) = werr(je)
                       indexw(im) = indexw(je)
                       iblock(im) = iblock(je)
                    end if
                 end do
                 m = im
              end if
              if (idiscl < 0 .or. idiscu < 0) then
                 toofew = .true.
              end if
           end if
           if ((irange == allrng .and. m /= n) .or. (irange == indrng .and. m /= iu - il + 1)) then
              toofew = .true.
           end if
           ! if order='b', do nothing the eigenvalues are already sorted by
              ! block.
           ! if order='e', sort the eigenvalues from smallest to largest
           if (la_lsame(order,'E') .and. nsplit > 1) then
              do je = 1,m - 1
                 ie = 0
                 tmp1 = w(je)
                 do j = je + 1,m
                    if (w(j) < tmp1) then
                       ie = j
                       tmp1 = w(j)
                    end if
                 end do
                 if (ie /= 0) then
                    tmp2 = werr(ie)
                    itmp1 = iblock(ie)
                    itmp2 = indexw(ie)
                    w(ie) = w(je)
                    werr(ie) = werr(je)
                    iblock(ie) = iblock(je)
                    indexw(ie) = indexw(je)
                    w(je) = tmp1
                    werr(je) = tmp2
                    iblock(je) = itmp1
                    indexw(je) = itmp2
                 end if
              end do
           end if
           info = 0
           if (ncnvrg) info = info + 1
           if (toofew) info = info + 2
           return
     end subroutine la_qlarrd

     !> To find the desired eigenvalues of a given real symmetric
     !> tridiagonal matrix T, DLARRE: sets any "small" off-diagonal
     !> elements to zero, and for each unreduced block T_i, it finds
     !> (a) a suitable shift at one end of the block's spectrum,
     !> (b) the base representation, T_i - sigma_i I = L_i D_i L_i^T, and
     !> (c) eigenvalues of each L_i D_i L_i^T.
     !> The representations and eigenvalues found are then used by
     !> DSTEMR to compute the eigenvectors of T.
     !> The accuracy varies depending on whether bisection is used to
     !> find a few eigenvalues or the dqds algorithm (subroutine DLASQ2) to
     !> conpute all and then discard any unwanted one.
     !> As an added benefit, DLARRE also outputs the n
     !> Gerschgorin intervals for the matrices L_i D_i L_i^T.

     pure subroutine la_qlarre(range,n,vl,vu,il,iu,d,e,e2,rtol1,rtol2,spltol, &
               nsplit,isplit,m,w,werr,wgap,iblock,indexw,gers,pivmin,work,iwork,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: range
           integer(ilp),intent(in) :: il,iu,n
           integer(ilp),intent(out) :: info,m,nsplit
           real(qp),intent(out) :: pivmin
           real(qp),intent(in) :: rtol1,rtol2,spltol
           real(qp),intent(inout) :: vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: iblock(*),isplit(*),iwork(*),indexw(*)
           real(qp),intent(inout) :: d(*),e(*),e2(*)
           real(qp),intent(out) :: gers(*),w(*),werr(*),wgap(*),work(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: hndrd = 100.0_qp
           real(qp),parameter :: pert = 8.0_qp
           real(qp),parameter :: fourth = one/four
           real(qp),parameter :: fac = half
           real(qp),parameter :: maxgrowth = 64.0_qp
           real(qp),parameter :: fudge = 2.0_qp
           integer(ilp),parameter :: maxtry = 6
           integer(ilp),parameter :: allrng = 1
           integer(ilp),parameter :: indrng = 2
           integer(ilp),parameter :: valrng = 3

           ! Local Scalars
           logical(lk) :: forceb,norep,usedqd
           integer(ilp) :: cnt,cnt1,cnt2,i,ibegin,idum,iend,iinfo,in,indl,indu,irange, &
                     j,jblk,mb,mm,wbegin,wend
           real(qp) :: avgap,bsrtol,clwdth,dmax,dpivot,eabs,emax,eold,eps,gl,gu,isleft, &
                      isrght,rtl,rtol,s1,s2,safmin,sgndef,sigma,spdiam,tau,tmp,tmp1
           ! Local Arrays
           integer(ilp) :: iseed(4)
           ! Intrinsic Functions
           intrinsic :: abs,max,min
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n <= 0) then
              return
           end if
           ! decode range
           if (la_lsame(range,'A')) then
              irange = allrng
           else if (la_lsame(range,'V')) then
              irange = valrng
           else if (la_lsame(range,'I')) then
              irange = indrng
           end if
           m = 0
           ! get machine constants
           safmin = la_qlamch('S')
           eps = la_qlamch('P')
           ! set parameters
           rtl = sqrt(eps)
           bsrtol = sqrt(eps)
           ! treat case of 1x1 matrix for quick return
           if (n == 1) then
              if ((irange == allrng) .or. ((irange == valrng) .and. (d(1) > vl) .and. (d(1) <= vu)) .or. (( &
                        irange == indrng) .and. (il == 1) .and. (iu == 1))) then
                 m = 1
                 w(1) = d(1)
                 ! the computation error of the eigenvalue is zero
                 werr(1) = zero
                 wgap(1) = zero
                 iblock(1) = 1
                 indexw(1) = 1
                 gers(1) = d(1)
                 gers(2) = d(1)
              end if
              ! store the shift for the initial rrr, which is zero in this case
              e(1) = zero
              return
           end if
           ! general case: tridiagonal matrix of order > 1
           ! init werr, wgap. compute gerschgorin intervals and spectral diameter.
           ! compute maximum off-diagonal entry and pivmin.
           gl = d(1)
           gu = d(1)
           eold = zero
           emax = zero
           e(n) = zero
           do i = 1,n
              werr(i) = zero
              wgap(i) = zero
              eabs = abs(e(i))
              if (eabs >= emax) then
                 emax = eabs
              end if
              tmp1 = eabs + eold
              gers(2*i - 1) = d(i) - tmp1
              gl = min(gl,gers(2*i - 1))
              gers(2*i) = d(i) + tmp1
              gu = max(gu,gers(2*i))
              eold = eabs
           end do
           ! the minimum pivot allowed in the sturm sequence for t
           pivmin = safmin*max(one,emax**2)
           ! compute spectral diameter. the gerschgorin bounds give an
           ! estimate that is wrong by at most a factor of sqrt(2)
           spdiam = gu - gl
           ! compute splitting points
           call la_qlarra(n,d,e,e2,spltol,spdiam,nsplit,isplit,iinfo)
           ! can force use of bisection instead of faster dqds.
           ! option left in the code for future multisection work.
           forceb = .false.
           ! initialize usedqd, dqds should be used for allrng unless someone
           ! explicitly wants bisection.
           usedqd = ((irange == allrng) .and. (.not. forceb))
           if ((irange == allrng) .and. (.not. forceb)) then
              ! set interval [vl,vu] that contains all eigenvalues
              vl = gl
              vu = gu
           else
              ! we call la_qlarrd to find crude approximations to the eigenvalues
              ! in the desired range. in case irange = indrng, we also obtain the
              ! interval (vl,vu] that contains all the wanted eigenvalues.
              ! an interval [left,right] has converged if
              ! right-left<rtol*max(abs(left),abs(right))
              ! la_qlarrd needs a work of size 4*n, iwork of size 3*n
              call la_qlarrd(range,'B',n,vl,vu,il,iu,gers,bsrtol,d,e,e2,pivmin, &
                        nsplit,isplit,mm,w,werr,vl,vu,iblock,indexw,work,iwork,iinfo)
              if (iinfo /= 0) then
                 info = -1
                 return
              end if
              ! make sure that the entries m+1 to n in w, werr, iblock, indexw are 0
              do i = mm + 1,n
                 w(i) = zero
                 werr(i) = zero
                 iblock(i) = 0
                 indexw(i) = 0
              end do
           end if
      ! **
           ! loop over unreduced blocks
           ibegin = 1
           wbegin = 1
           loop_170: do jblk = 1,nsplit
              iend = isplit(jblk)
              in = iend - ibegin + 1
              ! 1 x 1 block
              if (in == 1) then
                 if ((irange == allrng) .or. ((irange == valrng) .and. (d(ibegin) > vl) .and. (d( &
                           ibegin) <= vu)) .or. ((irange == indrng) .and. (iblock(wbegin) == jblk))) then
                    m = m + 1
                    w(m) = d(ibegin)
                    werr(m) = zero
                    ! the gap for a single block doesn't matter for the later
                    ! algorithm and is assigned an arbitrary large value
                    wgap(m) = zero
                    iblock(m) = jblk
                    indexw(m) = 1
                    wbegin = wbegin + 1
                 end if
                 ! e( iend ) holds the shift for the initial rrr
                 e(iend) = zero
                 ibegin = iend + 1
                 cycle loop_170
              end if
              ! blocks of size larger than 1x1
              ! e( iend ) will hold the shift for the initial rrr, for now set it =0
              e(iend) = zero
              ! find local outer bounds gl,gu for the block
              gl = d(ibegin)
              gu = d(ibegin)
              do i = ibegin,iend
                 gl = min(gers(2*i - 1),gl)
                 gu = max(gers(2*i),gu)
              end do
              spdiam = gu - gl
              if (.not. ((irange == allrng) .and. (.not. forceb))) then
                 ! count the number of eigenvalues in the current block.
                 mb = 0
                 do i = wbegin,mm
                    if (iblock(i) == jblk) then
                       mb = mb + 1
                    else
                       goto 21
                    end if
                 end do
                 21 continue
                 if (mb == 0) then
                    ! no eigenvalue in the current block lies in the desired range
                    ! e( iend ) holds the shift for the initial rrr
                    e(iend) = zero
                    ibegin = iend + 1
                    cycle loop_170
                 else
                    ! decide whether dqds or bisection is more efficient
                    usedqd = ((mb > fac*in) .and. (.not. forceb))
                    wend = wbegin + mb - 1
                    ! calculate gaps for the current block
                    ! in later stages, when representations for individual
                    ! eigenvalues are different, we use sigma = e( iend ).
                    sigma = zero
                    do i = wbegin,wend - 1
                       wgap(i) = max(zero,w(i + 1) - werr(i + 1) - (w(i) + werr(i)))
                    end do
                    wgap(wend) = max(zero,vu - sigma - (w(wend) + werr(wend)))
                    ! find local index of the first and last desired evalue.
                    indl = indexw(wbegin)
                    indu = indexw(wend)
                 end if
              end if
              if (((irange == allrng) .and. (.not. forceb)) .or. usedqd) then
                 ! case of dqds
                 ! find approximations to the extremal eigenvalues of the block
                 call la_qlarrk(in,1,gl,gu,d(ibegin),e2(ibegin),pivmin,rtl,tmp,tmp1, &
                           iinfo)
                 if (iinfo /= 0) then
                    info = -1
                    return
                 end if
                 isleft = max(gl,tmp - tmp1 - hndrd*eps*abs(tmp - tmp1))
                 call la_qlarrk(in,in,gl,gu,d(ibegin),e2(ibegin),pivmin,rtl,tmp,tmp1, &
                            iinfo)
                 if (iinfo /= 0) then
                    info = -1
                    return
                 end if
                 isrght = min(gu,tmp + tmp1 + hndrd*eps*abs(tmp + tmp1))
                 ! improve the estimate of the spectral diameter
                 spdiam = isrght - isleft
              else
                 ! case of bisection
                 ! find approximations to the wanted extremal eigenvalues
                 isleft = max(gl,w(wbegin) - werr(wbegin) - hndrd*eps*abs(w(wbegin) - werr( &
                           wbegin)))
                 isrght = min(gu,w(wend) + werr(wend) + hndrd*eps*abs(w(wend) + werr(wend)))

              end if
              ! decide whether the base representation for the current block
              ! l_jblk d_jblk l_jblk^t = t_jblk - sigma_jblk i
              ! should be on the left or the right end of the current block.
              ! the strategy is to shift to the end which is "more populated"
              ! furthermore, decide whether to use dqds for the computation of
              ! dqds is chosen if all eigenvalues are desired or the number of
              ! eigenvalues to be computed is large compared to the blocksize.
              if ((irange == allrng) .and. (.not. forceb)) then
                 ! if all the eigenvalues have to be computed, we use dqd
                 usedqd = .true.
                 ! indl is the local index of the first eigenvalue to compute
                 indl = 1
                 indu = in
                 ! mb =  number of eigenvalues to compute
                 mb = in
                 wend = wbegin + mb - 1
                 ! define 1/4 and 3/4 points of the spectrum
                 s1 = isleft + fourth*spdiam
                 s2 = isrght - fourth*spdiam
              else
                 ! la_qlarrd has computed iblock and indexw for each eigenvalue
                 ! approximation.
                 ! choose sigma
                 if (usedqd) then
                    s1 = isleft + fourth*spdiam
                    s2 = isrght - fourth*spdiam
                 else
                    tmp = min(isrght,vu) - max(isleft,vl)
                    s1 = max(isleft,vl) + fourth*tmp
                    s2 = min(isrght,vu) - fourth*tmp
                 end if
              end if
              ! compute the negcount at the 1/4 and 3/4 points
              if (mb > 1) then
                 call la_qlarrc('T',in,s1,s2,d(ibegin),e(ibegin),pivmin,cnt,cnt1, &
                           cnt2,iinfo)
              end if
              if (mb == 1) then
                 sigma = gl
                 sgndef = one
              elseif (cnt1 - indl >= indu - cnt2) then
                 if ((irange == allrng) .and. (.not. forceb)) then
                    sigma = max(isleft,gl)
                 elseif (usedqd) then
                    ! use gerschgorin bound as shift to get pos def matrix
                    ! for dqds
                    sigma = isleft
                 else
                    ! use approximation of the first desired eigenvalue of the
                    ! block as shift
                    sigma = max(isleft,vl)
                 end if
                 sgndef = one
              else
                 if ((irange == allrng) .and. (.not. forceb)) then
                    sigma = min(isrght,gu)
                 elseif (usedqd) then
                    ! use gerschgorin bound as shift to get neg def matrix
                    ! for dqds
                    sigma = isrght
                 else
                    ! use approximation of the first desired eigenvalue of the
                    ! block as shift
                    sigma = min(isrght,vu)
                 end if
                 sgndef = -one
              end if
              ! an initial sigma has been chosen that will be used for computing
              ! t - sigma i = l d l^t
              ! define the increment tau of the shift in case the initial shift
              ! needs to be refined to obtain a factorization with not too much
              ! element growth.
              if (usedqd) then
                 ! the initial sigma was to the outer end of the spectrum
                 ! the matrix is definite and we need not retreat.
                 tau = spdiam*eps*n + two*pivmin
                 tau = max(tau,two*eps*abs(sigma))
              else
                 if (mb > 1) then
                    clwdth = w(wend) + werr(wend) - w(wbegin) - werr(wbegin)
                    avgap = abs(clwdth/real(wend - wbegin,KIND=qp))
                    if (sgndef == one) then
                       tau = half*max(wgap(wbegin),avgap)
                       tau = max(tau,werr(wbegin))
                    else
                       tau = half*max(wgap(wend - 1),avgap)
                       tau = max(tau,werr(wend))
                    end if
                 else
                    tau = werr(wbegin)
                 end if
              end if
              loop_80: do idum = 1,maxtry
                 ! compute l d l^t factorization of tridiagonal matrix t - sigma i.
                 ! store d in work(1:in), l in work(in+1:2*in), and reciprocals of
                 ! pivots in work(2*in+1:3*in)
                 dpivot = d(ibegin) - sigma
                 work(1) = dpivot
                 dmax = abs(work(1))
                 j = ibegin
                 do i = 1,in - 1
                    work(2*in + i) = one/work(i)
                    tmp = e(j)*work(2*in + i)
                    work(in + i) = tmp
                    dpivot = (d(j + 1) - sigma) - tmp*e(j)
                    work(i + 1) = dpivot
                    dmax = max(dmax,abs(dpivot))
                    j = j + 1
                 end do
                 ! check for element growth
                 if (dmax > maxgrowth*spdiam) then
                    norep = .true.
                 else
                    norep = .false.
                 end if
                 if (usedqd .and. .not. norep) then
                    ! ensure the definiteness of the representation
                    ! all entries of d (of l d l^t) must have the same sign
                    do i = 1,in
                       tmp = sgndef*work(i)
                       if (tmp < zero) norep = .true.
                    end do
                 end if
                 if (norep) then
                    ! note that in the case of irange=allrng, we use the gerschgorin
                    ! shift which makes the matrix definite. so we should end up
                    ! here really only in the case of irange = valrng or indrng.
                    if (idum == maxtry - 1) then
                       if (sgndef == one) then
                          ! the fudged gerschgorin shift should succeed
                          sigma = gl - fudge*spdiam*eps*n - fudge*two*pivmin
                       else
                          sigma = gu + fudge*spdiam*eps*n + fudge*two*pivmin
                       end if
                    else
                       sigma = sigma - sgndef*tau
                       tau = two*tau
                    end if
                 else
                    ! an initial rrr is found
                    go to 83
                 end if
              end do loop_80
              ! if the program reaches this point, no base representation could be
              ! found in maxtry iterations.
              info = 2
              return
              83 continue
              ! at this point, we have found an initial base representation
              ! t - sigma i = l d l^t with not too much element growth.
              ! store the shift.
              e(iend) = sigma
              ! store d and l.
              call la_qcopy(in,work,1,d(ibegin),1)
              call la_qcopy(in - 1,work(in + 1),1,e(ibegin),1)
              if (mb > 1) then
                 ! perturb each entry of the base representation by a small
                 ! (but random) relative amount to overcome difficulties with
                 ! glued matrices.
                 do i = 1,4
                    iseed(i) = 1
                 end do
                 call la_qlarnv(2,iseed,2*in - 1,work(1))
                 do i = 1,in - 1
                    d(ibegin + i - 1) = d(ibegin + i - 1)*(one + eps*pert*work(i))
                    e(ibegin + i - 1) = e(ibegin + i - 1)*(one + eps*pert*work(in + i))
                 end do
                 d(iend) = d(iend)*(one + eps*four*work(in))
              end if
              ! don't update the gerschgorin intervals because keeping track
              ! of the updates would be too much work in la_qlarrv.
              ! we update w instead and use it to locate the proper gerschgorin
              ! intervals.
              ! compute the required eigenvalues of l d l' by bisection or dqds
              if (.not. usedqd) then
                 ! if la_qlarrd has been used, shift the eigenvalue approximations
                 ! according to their representation. this is necessary for
                 ! a uniform la_qlarrv since dqds computes eigenvalues of the
                 ! shifted representation. in la_qlarrv, w will always hold the
                 ! unshifted eigenvalue approximation.
                 do j = wbegin,wend
                    w(j) = w(j) - sigma
                    werr(j) = werr(j) + abs(w(j))*eps
                 end do
                 ! call la_qlarrb to reduce eigenvalue error of the approximations
                 ! from la_qlarrd
                 do i = ibegin,iend - 1
                    work(i) = d(i)*e(i)**2
                 end do
                 ! use bisection to find ev from indl to indu
                 call la_qlarrb(in,d(ibegin),work(ibegin),indl,indu,rtol1,rtol2,indl - 1, &
                 w(wbegin),wgap(wbegin),werr(wbegin),work(2*n + 1),iwork,pivmin,spdiam,in, &
                           iinfo)
                 if (iinfo /= 0) then
                    info = -4
                    return
                 end if
                 ! la_qlarrb computes all gaps correctly except for the last one
                 ! record distance to vu/gu
                 wgap(wend) = max(zero, (vu - sigma) - (w(wend) + werr(wend)))
                 do i = indl,indu
                    m = m + 1
                    iblock(m) = jblk
                    indexw(m) = i
                 end do
              else
                 ! call dqds to get all eigs (and then possibly delete unwanted
                 ! eigenvalues).
                 ! note that dqds finds the eigenvalues of the l d l^t representation
                 ! of t to high relative accuracy. high relative accuracy
                 ! might be lost when the shift of the rrr is subtracted to obtain
                 ! the eigenvalues of t. however, t is not guaranteed to define its
                 ! eigenvalues to high relative accuracy anyway.
                 ! set rtol to the order of the tolerance used in la_qlasq2
                 ! this is an estimated error, the worst case bound is 4*n*eps
                 ! which is usually too large and requires unnecessary work to be
                 ! done by bisection when computing the eigenvectors
                 rtol = log(real(in,KIND=qp))*four*eps
                 j = ibegin
                 do i = 1,in - 1
                    work(2*i - 1) = abs(d(j))
                    work(2*i) = e(j)*e(j)*work(2*i - 1)
                    j = j + 1
                 end do
                 work(2*in - 1) = abs(d(iend))
                 work(2*in) = zero
                 call la_qlasq2(in,work,iinfo)
                 if (iinfo /= 0) then
                    ! if iinfo = -5 then an index is part of a tight cluster
                    ! and should be changed. the index is in iwork(1) and the
                    ! gap is in work(n+1)
                    info = -5
                    return
                 else
                    ! test that all eigenvalues are positive as expected
                    do i = 1,in
                       if (work(i) < zero) then
                          info = -6
                          return
                       end if
                    end do
                 end if
                 if (sgndef > zero) then
                    do i = indl,indu
                       m = m + 1
                       w(m) = work(in - i + 1)
                       iblock(m) = jblk
                       indexw(m) = i
                    end do
                 else
                    do i = indl,indu
                       m = m + 1
                       w(m) = -work(i)
                       iblock(m) = jblk
                       indexw(m) = i
                    end do
                 end if
                 do i = m - mb + 1,m
                    ! the value of rtol below should be the tolerance in la_qlasq2
                    werr(i) = rtol*abs(w(i))
                 end do
                 do i = m - mb + 1,m - 1
                    ! compute the right gap between the intervals
                    wgap(i) = max(zero,w(i + 1) - werr(i + 1) - (w(i) + werr(i)))
                 end do
                 wgap(m) = max(zero, (vu - sigma) - (w(m) + werr(m)))
              end if
              ! proceed with next block
              ibegin = iend + 1
              wbegin = wend + 1
           end do loop_170
           return
     end subroutine la_qlarre

     !> Given the initial representation L D L^T and its cluster of close
     !> eigenvalues (in a relative measure), W( CLSTRT ), W( CLSTRT+1 ), ...
     !> W( CLEND ), DLARRF: finds a new relatively robust representation
     !> L D L^T - SIGMA I = L(+) D(+) L(+)^T such that at least one of the
     !> eigenvalues of L(+) D(+) L(+)^T is relatively isolated.

     pure subroutine la_qlarrf(n,d,l,ld,clstrt,clend,w,wgap,werr,spdiam,clgapl, &
               clgapr,pivmin,sigma,dplus,lplus,work,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: clstrt,clend,n
           integer(ilp),intent(out) :: info
           real(qp),intent(in) :: clgapl,clgapr,pivmin,spdiam
           real(qp),intent(out) :: sigma
           ! Array Arguments
           real(qp),intent(in) :: d(*),l(*),ld(*),w(*),werr(*)
           real(qp),intent(out) :: dplus(*),lplus(*),work(*)
           real(qp),intent(inout) :: wgap(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: quart = 0.25_qp
           real(qp),parameter :: maxgrowth1 = 8._qp
           real(qp),parameter :: maxgrowth2 = 8._qp
           integer(ilp),parameter :: ktrymax = 1
           integer(ilp),parameter :: sleft = 1
           integer(ilp),parameter :: sright = 2

           ! Local Scalars
           logical(lk) :: dorrr1,forcer,nofail,sawnan1,sawnan2,tryrrr1
           integer(ilp) :: i,indx,ktry,shift
           real(qp) :: avgap,bestshift,clwdth,eps,fact,fail,fail2,growthbound,ldelta, &
           ldmax,lsigma,max1,max2,mingap,oldp,prod,rdelta,rdmax,rrr1,rrr2,rsigma,s, &
                     smlgrowth,tmp,znm2
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n <= 0) then
              return
           end if
           fact = real(2**ktrymax,KIND=qp)
           eps = la_qlamch('PRECISION')
           shift = 0
           forcer = .false.
           ! note that we cannot guarantee that for any of the shifts tried,
           ! the factorization has a small or even moderate element growth.
           ! there could be ritz values at both ends of the cluster and despite
           ! backing off, there are examples where all factorizations tried
           ! (in ieee mode, allowing zero pivots
           ! element growth.
           ! for this reason, we should use pivmin in this subroutine so that at
           ! least the l d l^t factorization exists. it can be checked afterwards
           ! whether the element growth caused bad residuals/orthogonality.
           ! decide whether the code should accept the best among all
           ! representations despite large element growth or signal info=1
           ! setting nofail to .false. for quick fix for bug 113
           nofail = .false.
           ! compute the average gap length of the cluster
           clwdth = abs(w(clend) - w(clstrt)) + werr(clend) + werr(clstrt)
           avgap = clwdth/real(clend - clstrt,KIND=qp)
           mingap = min(clgapl,clgapr)
           ! initial values for shifts to both ends of cluster
           lsigma = min(w(clstrt),w(clend)) - werr(clstrt)
           rsigma = max(w(clstrt),w(clend)) + werr(clend)
           ! use a small fudge to make sure that we really shift to the outside
           lsigma = lsigma - abs(lsigma)*four*eps
           rsigma = rsigma + abs(rsigma)*four*eps
           ! compute upper bounds for how much to back off the initial shifts
           ldmax = quart*mingap + two*pivmin
           rdmax = quart*mingap + two*pivmin
           ldelta = max(avgap,wgap(clstrt))/fact
           rdelta = max(avgap,wgap(clend - 1))/fact
           ! initialize the record of the best representation found
           s = la_qlamch('S')
           smlgrowth = one/s
           fail = real(n - 1,KIND=qp)*mingap/(spdiam*eps)
           fail2 = real(n - 1,KIND=qp)*mingap/(spdiam*sqrt(eps))
           bestshift = lsigma
           ! while (ktry <= ktrymax)
           ktry = 0
           growthbound = maxgrowth1*spdiam
           5 continue
           sawnan1 = .false.
           sawnan2 = .false.
           ! ensure that we do not back off too much of the initial shifts
           ldelta = min(ldmax,ldelta)
           rdelta = min(rdmax,rdelta)
           ! compute the element growth when shifting to both ends of the cluster
           ! accept the shift if there is no element growth at one of the two ends
           ! left end
           s = -lsigma
           dplus(1) = d(1) + s
           if (abs(dplus(1)) < pivmin) then
              dplus(1) = -pivmin
              ! need to set sawnan1 because refined rrr test should not be used
              ! in this case
              sawnan1 = .true.
           end if
           max1 = abs(dplus(1))
           do i = 1,n - 1
              lplus(i) = ld(i)/dplus(i)
              s = s*lplus(i)*l(i) - lsigma
              dplus(i + 1) = d(i + 1) + s
              if (abs(dplus(i + 1)) < pivmin) then
                 dplus(i + 1) = -pivmin
                 ! need to set sawnan1 because refined rrr test should not be used
                 ! in this case
                 sawnan1 = .true.
              end if
              max1 = max(max1,abs(dplus(i + 1)))
           end do
           sawnan1 = sawnan1 .or. la_qisnan(max1)
           if (forcer .or. (max1 <= growthbound .and. .not. sawnan1)) then
              sigma = lsigma
              shift = sleft
              goto 100
           end if
           ! right end
           s = -rsigma
           work(1) = d(1) + s
           if (abs(work(1)) < pivmin) then
              work(1) = -pivmin
              ! need to set sawnan2 because refined rrr test should not be used
              ! in this case
              sawnan2 = .true.
           end if
           max2 = abs(work(1))
           do i = 1,n - 1
              work(n + i) = ld(i)/work(i)
              s = s*work(n + i)*l(i) - rsigma
              work(i + 1) = d(i + 1) + s
              if (abs(work(i + 1)) < pivmin) then
                 work(i + 1) = -pivmin
                 ! need to set sawnan2 because refined rrr test should not be used
                 ! in this case
                 sawnan2 = .true.
              end if
              max2 = max(max2,abs(work(i + 1)))
           end do
           sawnan2 = sawnan2 .or. la_qisnan(max2)
           if (forcer .or. (max2 <= growthbound .and. .not. sawnan2)) then
              sigma = rsigma
              shift = sright
              goto 100
           end if
           ! if we are at this point, both shifts led to too much element growth
           ! record the better of the two shifts (provided it didn't lead to nan)
           if (sawnan1 .and. sawnan2) then
              ! both max1 and max2 are nan
              goto 50
           else
              if (.not. sawnan1) then
                 indx = 1
                 if (max1 <= smlgrowth) then
                    smlgrowth = max1
                    bestshift = lsigma
                 end if
              end if
              if (.not. sawnan2) then
                 if (sawnan1 .or. max2 <= max1) indx = 2
                 if (max2 <= smlgrowth) then
                    smlgrowth = max2
                    bestshift = rsigma
                 end if
              end if
           end if
           ! if we are here, both the left and the right shift led to
           ! element growth. if the element growth is moderate, then
           ! we may still accept the representation, if it passes a
           ! refined test for rrr. this test supposes that no nan occurred.
           ! moreover, we use the refined rrr test only for isolated clusters.
           if ((clwdth < mingap/real(128,KIND=qp)) .and. (min(max1,max2) < fail2) .and. (.not. sawnan1) &
                     .and. (.not. sawnan2)) then
              dorrr1 = .true.
           else
              dorrr1 = .false.
           end if
           tryrrr1 = .true.
           if (tryrrr1 .and. dorrr1) then
           if (indx == 1) then
              tmp = abs(dplus(n))
              znm2 = one
              prod = one
              oldp = one
              do i = n - 1,1,-1
                 if (prod <= eps) then
                    prod = ((dplus(i + 1)*work(n + i + 1))/(dplus(i)*work(n + i)))*oldp
                 else
                    prod = prod*abs(work(n + i))
                 end if
                 oldp = prod
                 znm2 = znm2 + prod**2
                 tmp = max(tmp,abs(dplus(i)*prod))
              end do
              rrr1 = tmp/(spdiam*sqrt(znm2))
              if (rrr1 <= maxgrowth2) then
                 sigma = lsigma
                 shift = sleft
                 goto 100
              end if
           else if (indx == 2) then
              tmp = abs(work(n))
              znm2 = one
              prod = one
              oldp = one
              do i = n - 1,1,-1
                 if (prod <= eps) then
                    prod = ((work(i + 1)*lplus(i + 1))/(work(i)*lplus(i)))*oldp
                 else
                    prod = prod*abs(lplus(i))
                 end if
                 oldp = prod
                 znm2 = znm2 + prod**2
                 tmp = max(tmp,abs(work(i)*prod))
              end do
              rrr2 = tmp/(spdiam*sqrt(znm2))
              if (rrr2 <= maxgrowth2) then
                 sigma = rsigma
                 shift = sright
                 goto 100
              end if
           end if
           end if
           50 continue
           if (ktry < ktrymax) then
              ! if we are here, both shifts failed also the rrr test.
              ! back off to the outside
              lsigma = max(lsigma - ldelta,lsigma - ldmax)
              rsigma = min(rsigma + rdelta,rsigma + rdmax)
              ldelta = two*ldelta
              rdelta = two*rdelta
              ktry = ktry + 1
              goto 5
           else
              ! none of the representations investigated satisfied our
              ! criteria. take the best one we found.
              if ((smlgrowth < fail) .or. nofail) then
                 lsigma = bestshift
                 rsigma = bestshift
                 forcer = .true.
                 goto 5
              else
                 info = 1
                 return
              end if
           end if
           100 continue
           if (shift == sleft) then
           elseif (shift == sright) then
              ! store new l and d back into dplus, lplus
              call la_qcopy(n,work,1,dplus,1)
              call la_qcopy(n - 1,work(n + 1),1,lplus,1)
           end if
           return
     end subroutine la_qlarrf

     !> Given the initial eigenvalue approximations of T, DLARRJ:
     !> does  bisection to refine the eigenvalues of T,
     !> W( IFIRST-OFFSET ) through W( ILAST-OFFSET ), to more accuracy. Initial
     !> guesses for these eigenvalues are input in W, the corresponding estimate
     !> of the error in these guesses in WERR. During bisection, intervals
     !> [left, right] are maintained by storing their mid-points and
     !> semi-widths in the arrays W and WERR respectively.

     pure subroutine la_qlarrj(n,d,e2,ifirst,ilast,rtol,offset,w,werr,work,iwork, &
               pivmin,spdiam,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: ifirst,ilast,n,offset
           integer(ilp),intent(out) :: info
           real(qp),intent(in) :: pivmin,rtol,spdiam
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(in) :: d(*),e2(*)
           real(qp),intent(inout) :: w(*),werr(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           integer(ilp) :: maxitr
           ! Local Scalars
           integer(ilp) :: cnt,i,i1,i2,ii,iter,j,k,next,nint,olnint,p,prev, &
                     savi1
           real(qp) :: dplus,fac,left,mid,right,s,tmp,width
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n <= 0) then
              return
           end if
           maxitr = int((log(spdiam + pivmin) - log(pivmin))/log(two),KIND=ilp) + 2
           ! initialize unconverged intervals in [ work(2*i-1), work(2*i) ].
           ! the sturm count, count( work(2*i-1) ) is arranged to be i-1, while
           ! count( work(2*i) ) is stored in iwork( 2*i ). the integer iwork( 2*i-1 )
           ! for an unconverged interval is set to the index of the next unconverged
           ! interval, and is -1 or 0 for a converged interval. thus a linked
           ! list of unconverged intervals is set up.
           i1 = ifirst
           i2 = ilast
           ! the number of unconverged intervals
           nint = 0
           ! the last unconverged interval found
           prev = 0
           loop_75: do i = i1,i2
              k = 2*i
              ii = i - offset
              left = w(ii) - werr(ii)
              mid = w(ii)
              right = w(ii) + werr(ii)
              width = right - mid
              tmp = max(abs(left),abs(right))
              ! the following test prevents the test of converged intervals
              if (width < rtol*tmp) then
                 ! this interval has already converged and does not need refinement.
                 ! (note that the gaps might change through refining the
                  ! eigenvalues, however, they can only get bigger.)
                 ! remove it from the list.
                 iwork(k - 1) = -1
                 ! make sure that i1 always points to the first unconverged interval
                 if ((i == i1) .and. (i < i2)) i1 = i + 1
                 if ((prev >= i1) .and. (i <= i2)) iwork(2*prev - 1) = i + 1
              else
                 ! unconverged interval found
                 prev = i
                 ! make sure that [left,right] contains the desired eigenvalue
                 ! do while( cnt(left)>i-1 )
                 fac = one
                 20 continue
                 cnt = 0
                 s = left
                 dplus = d(1) - s
                 if (dplus < zero) cnt = cnt + 1
                 do j = 2,n
                    dplus = d(j) - s - e2(j - 1)/dplus
                    if (dplus < zero) cnt = cnt + 1
                 end do
                 if (cnt > i - 1) then
                    left = left - werr(ii)*fac
                    fac = two*fac
                    go to 20
                 end if
                 ! do while( cnt(right)<i )
                 fac = one
                 50 continue
                 cnt = 0
                 s = right
                 dplus = d(1) - s
                 if (dplus < zero) cnt = cnt + 1
                 do j = 2,n
                    dplus = d(j) - s - e2(j - 1)/dplus
                    if (dplus < zero) cnt = cnt + 1
                 end do
                 if (cnt < i) then
                    right = right + werr(ii)*fac
                    fac = two*fac
                    go to 50
                 end if
                 nint = nint + 1
                 iwork(k - 1) = i + 1
                 iwork(k) = cnt
              end if
              work(k - 1) = left
              work(k) = right
           end do loop_75
           savi1 = i1
           ! do while( nint>0 ), i.e. there are still unconverged intervals
           ! and while (iter<maxitr)
           iter = 0
           80 continue
           prev = i1 - 1
           i = i1
           olnint = nint
           loop_100: do p = 1,olnint
              k = 2*i
              ii = i - offset
              next = iwork(k - 1)
              left = work(k - 1)
              right = work(k)
              mid = half*(left + right)
              ! semiwidth of interval
              width = right - mid
              tmp = max(abs(left),abs(right))
              if ((width < rtol*tmp) .or. (iter == maxitr)) then
                 ! reduce number of unconverged intervals
                 nint = nint - 1
                 ! mark interval as converged.
                 iwork(k - 1) = 0
                 if (i1 == i) then
                    i1 = next
                 else
                    ! prev holds the last unconverged interval previously examined
                    if (prev >= i1) iwork(2*prev - 1) = next
                 end if
                 i = next
                 cycle loop_100
              end if
              prev = i
              ! perform one bisection step
              cnt = 0
              s = mid
              dplus = d(1) - s
              if (dplus < zero) cnt = cnt + 1
              do j = 2,n
                 dplus = d(j) - s - e2(j - 1)/dplus
                 if (dplus < zero) cnt = cnt + 1
              end do
              if (cnt <= i - 1) then
                 work(k - 1) = mid
              else
                 work(k) = mid
              end if
              i = next
           end do loop_100
           iter = iter + 1
           ! do another loop if there are still unconverged intervals
           ! however, in the last iteration, all intervals are accepted
           ! since this is the best we can do.
           if ((nint > 0) .and. (iter <= maxitr)) go to 80
           ! at this point, all the intervals have converged
           do i = savi1,ilast
              k = 2*i
              ii = i - offset
              ! all intervals marked by '0' have been refined.
              if (iwork(k - 1) == 0) then
                 w(ii) = half*(work(k - 1) + work(k))
                 werr(ii) = work(k) - w(ii)
              end if
           end do
           return
     end subroutine la_qlarrj

     !> DLARRK: computes one eigenvalue of a symmetric tridiagonal
     !> matrix T to suitable accuracy. This is an auxiliary code to be
     !> called from DSTEMR.
     !> To avoid overflow, the matrix must be scaled so that its
     !> largest element is no greater than overflow**(1/2) * underflow**(1/4) in absolute value, and for greatest
     !> accuracy, it should not be much smaller than that.
     !> See W. Kahan "Accurate Eigenvalues of a Symmetric Tridiagonal
     !> Matrix", Report CS41, Computer Science Dept., Stanford
     !> University, July 21, 1966.

     pure subroutine la_qlarrk(n,iw,gl,gu,d,e2,pivmin,reltol,w,werr,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: iw,n
           real(qp),intent(in) :: pivmin,reltol,gl,gu
           real(qp),intent(out) :: w,werr
           ! Array Arguments
           real(qp),intent(in) :: d(*),e2(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: fudge = two

           ! Local Scalars
           integer(ilp) :: i,it,itmax,negcnt
           real(qp) :: atoli,eps,left,mid,right,rtoli,tmp1,tmp2,tnorm
           ! Intrinsic Functions
           intrinsic :: abs,int,log,max
           ! Executable Statements
           ! quick return if possible
           if (n <= 0) then
              info = 0
              return
           end if
           ! get machine constants
           eps = la_qlamch('P')
           tnorm = max(abs(gl),abs(gu))
           rtoli = reltol
           atoli = fudge*two*pivmin
           itmax = int((log(tnorm + pivmin) - log(pivmin))/log(two),KIND=ilp) + 2
           info = -1
           left = gl - fudge*tnorm*eps*n - fudge*two*pivmin
           right = gu + fudge*tnorm*eps*n + fudge*two*pivmin
           it = 0
           10 continue
           ! check if interval converged or maximum number of iterations reached
           tmp1 = abs(right - left)
           tmp2 = max(abs(right),abs(left))
           if (tmp1 < max(atoli,pivmin,rtoli*tmp2)) then
              info = 0
              goto 30
           end if
           if (it > itmax) goto 30
           ! count number of negative pivots for mid-point
           it = it + 1
           mid = half*(left + right)
           negcnt = 0
           tmp1 = d(1) - mid
           if (abs(tmp1) < pivmin) tmp1 = -pivmin
           if (tmp1 <= zero) negcnt = negcnt + 1
           do i = 2,n
              tmp1 = d(i) - e2(i - 1)/tmp1 - mid
              if (abs(tmp1) < pivmin) tmp1 = -pivmin
              if (tmp1 <= zero) negcnt = negcnt + 1
           end do
           if (negcnt >= iw) then
              right = mid
           else
              left = mid
           end if
           goto 10
           30 continue
           ! converged or maximum number of iterations reached
           w = half*(left + right)
           werr = half*abs(right - left)
           return
     end subroutine la_qlarrk

     !> Perform tests to decide whether the symmetric tridiagonal matrix T
     !> warrants expensive computations which guarantee high relative accuracy
     !> in the eigenvalues.

     pure subroutine la_qlarrr(n,d,e,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: n
           integer(ilp),intent(out) :: info
           ! Array Arguments
           real(qp),intent(in) :: d(*)
           real(qp),intent(inout) :: e(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: relcond = 0.999_qp

           ! Local Scalars
           integer(ilp) :: i
           logical(lk) :: yesrel
           real(qp) :: eps,safmin,smlnum,rmin,tmp,tmp2,offdig,offdig2
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           ! quick return if possible
           if (n <= 0) then
              info = 0
              return
           end if
           ! as a default, do not go for relative-accuracy preserving computations.
           info = 1
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           rmin = sqrt(smlnum)
           ! tests for relative accuracy
           ! test for scaled diagonal dominance
           ! scale the diagonal entries to one and check whether the sum of the
           ! off-diagonals is less than one
           ! the sdd relative error bounds have a 1/(1- 2*x) factor in them,
           ! x = max(offdig + offdig2), so when x is close to 1/2, no relative
           ! accuracy is promised.  in the notation of the code fragment below,
           ! 1/(1 - (offdig + offdig2)) is the condition number.
           ! we don't think it is worth going into "sdd mode" unless the relative
           ! condition number is reasonable, not 1/macheps.
           ! the threshold should be compatible with other thresholds used in the
           ! code. we set  offdig + offdig2 <= .999_qp =: relcond, it corresponds
           ! to losing at most 3 decimal digits: 1 / (1 - (offdig + offdig2)) <= 1000
           ! instead of the current offdig + offdig2 < 1
           yesrel = .true.
           offdig = zero
           tmp = sqrt(abs(d(1)))
           if (tmp < rmin) yesrel = .false.
           if (.not. yesrel) goto 11
           do i = 2,n
              tmp2 = sqrt(abs(d(i)))
              if (tmp2 < rmin) yesrel = .false.
              if (.not. yesrel) goto 11
              offdig2 = abs(e(i - 1))/(tmp*tmp2)
              if (offdig + offdig2 >= relcond) yesrel = .false.
              if (.not. yesrel) goto 11
              tmp = tmp2
              offdig = offdig2
           end do
           11 continue
           if (yesrel) then
              info = 0
              return
           else
           end if
           ! *** more to be implemented ***
           ! test if the lower bidiagonal matrix l from t = l d l^t
           ! (zero shift facto) is well conditioned
           ! test if the upper bidiagonal matrix u from t = u d u^t
           ! (zero shift facto) is well conditioned.
           ! in this case, the matrix needs to be flipped and, at the end
           ! of the eigenvector computation, the flip needs to be applied
           ! to the computed eigenvectors (and the support)
           return
     end subroutine la_qlarrr

     !> DLARRV: computes the eigenvectors of the tridiagonal matrix
     !> T = L D L**T given L, D and APPROXIMATIONS to the eigenvalues of L D L**T.
     !> The input eigenvalues should have been computed by DLARRE.

     pure subroutine la_qlarrv(n,vl,vu,d,l,pivmin,isplit,m,dol,dou,minrgp,rtol1, &
               rtol2,w,werr,wgap,iblock,indexw,gers,z,ldz,isuppz,work,iwork,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: dol,dou,ldz,m,n
           integer(ilp),intent(out) :: info
           real(qp),intent(in) :: minrgp,pivmin,vl,vu
           real(qp),intent(inout) :: rtol1,rtol2
           ! Array Arguments
           integer(ilp),intent(in) :: iblock(*),indexw(*),isplit(*)
           integer(ilp),intent(out) :: isuppz(*),iwork(*)
           real(qp),intent(inout) :: d(*),l(*),w(*),werr(*),wgap(*)
           real(qp),intent(in) :: gers(*)
           real(qp),intent(out) :: work(*)
           real(qp),intent(out) :: z(ldz,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: maxitr = 10

           ! Local Scalars
           logical(lk) :: eskip,needbs,stp2ii,tryrqc,usedbs,usedrq
           integer(ilp) :: done,i,ibegin,idone,iend,ii,iindc1,iindc2,iindr,iindwk,iinfo, &
            im,in,indeig,indld,indlld,indwrk,isupmn,isupmx,iter,itmp1,j,jblk,k, &
            miniwsize,minwsize,nclus,ndepth,negcnt,newcls,newfst,newftt,newlst,newsiz, &
            offset,oldcls,oldfst,oldien,oldlst,oldncl,p,parity,q,wbegin,wend,windex, &
                      windmn,windpl,zfrom,zto,zusedl,zusedu,zusedw
           real(qp) :: bstres,bstw,eps,fudge,gap,gaptol,gl,gu,lambda,left,lgap,mingma, &
           nrminv,resid,rgap,right,rqcorr,rqtol,savgap,sgndef,sigma,spdiam,ssigma,tau, &
                     tmp,tol,ztz
           ! Intrinsic Functions
           intrinsic :: abs,real,max,min
           ! Executable Statements
           info = 0
           ! quick return if possible
           if ((n <= 0) .or. (m <= 0)) then
              return
           end if
           ! the first n entries of work are reserved for the eigenvalues
           indld = n + 1
           indlld = 2*n + 1
           indwrk = 3*n + 1
           minwsize = 12*n
           do i = 1,minwsize
              work(i) = zero
           end do
           ! iwork(iindr+1:iindr+n) hold the twist indices r for the
           ! factorization used to compute the fp vector
           iindr = 0
           ! iwork(iindc1+1:iinc2+n) are used to store the clusters of the current
           ! layer and the one above.
           iindc1 = n
           iindc2 = 2*n
           iindwk = 3*n + 1
           miniwsize = 7*n
           do i = 1,miniwsize
              iwork(i) = 0
           end do
           zusedl = 1
           if (dol > 1) then
              ! set lower bound for use of z
              zusedl = dol - 1
           end if
           zusedu = m
           if (dou < m) then
              ! set lower bound for use of z
              zusedu = dou + 1
           end if
           ! the width of the part of z that is used
           zusedw = zusedu - zusedl + 1
           call la_qlaset('FULL',n,zusedw,zero,zero,z(1,zusedl),ldz)
           eps = la_qlamch('PRECISION')
           rqtol = two*eps
           ! set expert flags for standard code.
           tryrqc = .true.
           if ((dol == 1) .and. (dou == m)) then
           else
              ! only selected eigenpairs are computed. since the other evalues
              ! are not refined by rq iteration, bisection has to compute to full
              ! accuracy.
              rtol1 = four*eps
              rtol2 = four*eps
           end if
           ! the entries wbegin:wend in w, werr, wgap correspond to the
           ! desired eigenvalues. the support of the nonzero eigenvector
           ! entries is contained in the interval ibegin:iend.
           ! remark that if k eigenpairs are desired, then the eigenvectors
           ! are stored in k contiguous columns of z.
           ! done is the number of eigenvectors already computed
           done = 0
           ibegin = 1
           wbegin = 1
           loop_170: do jblk = 1,iblock(m)
              iend = isplit(jblk)
              sigma = l(iend)
              ! find the eigenvectors of the submatrix indexed ibegin
              ! through iend.
              wend = wbegin - 1
              15 continue
              if (wend < m) then
                 if (iblock(wend + 1) == jblk) then
                    wend = wend + 1
                    go to 15
                 end if
              end if
              if (wend < wbegin) then
                 ibegin = iend + 1
                 cycle loop_170
              elseif ((wend < dol) .or. (wbegin > dou)) then
                 ibegin = iend + 1
                 wbegin = wend + 1
                 cycle loop_170
              end if
              ! find local spectral diameter of the block
              gl = gers(2*ibegin - 1)
              gu = gers(2*ibegin)
              do i = ibegin + 1,iend
                 gl = min(gers(2*i - 1),gl)
                 gu = max(gers(2*i),gu)
              end do
              spdiam = gu - gl
              ! oldien is the last index of the previous block
              oldien = ibegin - 1
              ! calculate the size of the current block
              in = iend - ibegin + 1
              ! the number of eigenvalues in the current block
              im = wend - wbegin + 1
              ! this is for a 1x1 block
              if (ibegin == iend) then
                 done = done + 1
                 z(ibegin,wbegin) = one
                 isuppz(2*wbegin - 1) = ibegin
                 isuppz(2*wbegin) = ibegin
                 w(wbegin) = w(wbegin) + sigma
                 work(wbegin) = w(wbegin)
                 ibegin = iend + 1
                 wbegin = wbegin + 1
                 cycle loop_170
              end if
              ! the desired (shifted) eigenvalues are stored in w(wbegin:wend)
              ! note that these can be approximations, in this case, the corresp.
              ! entries of werr give the size of the uncertainty interval.
              ! the eigenvalue approximations will be refined when necessary as
              ! high relative accuracy is required for the computation of the
              ! corresponding eigenvectors.
              call la_qcopy(im,w(wbegin),1,work(wbegin),1)
              ! we store in w the eigenvalue approximations w.r.t. the original
              ! matrix t.
              do i = 1,im
                 w(wbegin + i - 1) = w(wbegin + i - 1) + sigma
              end do
              ! ndepth is the current depth of the representation tree
              ndepth = 0
              ! parity is either 1 or 0
              parity = 1
              ! nclus is the number of clusters for the next level of the
              ! representation tree, we start with nclus = 1 for the root
              nclus = 1
              iwork(iindc1 + 1) = 1
              iwork(iindc1 + 2) = im
              ! idone is the number of eigenvectors already computed in the current
              ! block
              idone = 0
              ! loop while( idone<im )
              ! generate the representation tree for the current block and
              ! compute the eigenvectors
              40 continue
              if (idone < im) then
                 ! this is a crude protection against infinitely deep trees
                 if (ndepth > m) then
                    info = -2
                    return
                 end if
                 ! breadth first processing of the current level of the representation
                 ! tree: oldncl = number of clusters on current level
                 oldncl = nclus
                 ! reset nclus to count the number of child clusters
                 nclus = 0
                 parity = 1 - parity
                 if (parity == 0) then
                    oldcls = iindc1
                    newcls = iindc2
                 else
                    oldcls = iindc2
                    newcls = iindc1
                 end if
                 ! process the clusters on the current level
                 loop_150: do i = 1,oldncl
                    j = oldcls + 2*i
                    ! oldfst, oldlst = first, last index of current cluster.
                                     ! cluster indices start with 1 and are relative
                                     ! to wbegin when accessing w, wgap, werr, z
                    oldfst = iwork(j - 1)
                    oldlst = iwork(j)
                    if (ndepth > 0) then
                       ! retrieve relatively robust representation (rrr) of cluster
                       ! that has been computed at the previous level
                       ! the rrr is stored in z and overwritten once the eigenvectors
                       ! have been computed or when the cluster is refined
                       if ((dol == 1) .and. (dou == m)) then
                          ! get representation from location of the leftmost evalue
                          ! of the cluster
                          j = wbegin + oldfst - 1
                       else
                          if (wbegin + oldfst - 1 < dol) then
                             ! get representation from the left end of z array
                             j = dol - 1
                          elseif (wbegin + oldfst - 1 > dou) then
                             ! get representation from the right end of z array
                             j = dou
                          else
                             j = wbegin + oldfst - 1
                          end if
                       end if
                       call la_qcopy(in,z(ibegin,j),1,d(ibegin),1)
                       call la_qcopy(in - 1,z(ibegin,j + 1),1,l(ibegin),1)
                       sigma = z(iend,j + 1)
                       ! set the corresponding entries in z to zero
                       call la_qlaset('FULL',in,2,zero,zero,z(ibegin,j),ldz)
                    end if
                    ! compute dl and dll of current rrr
                    do j = ibegin,iend - 1
                       tmp = d(j)*l(j)
                       work(indld - 1 + j) = tmp
                       work(indlld - 1 + j) = tmp*l(j)
                    end do
                    if (ndepth > 0) then
                       ! p and q are index of the first and last eigenvalue to compute
                       ! within the current block
                       p = indexw(wbegin - 1 + oldfst)
                       q = indexw(wbegin - 1 + oldlst)
                       ! offset for the arrays work, wgap and werr, i.e., the p-offset
                       ! through the q-offset elements of these arrays are to be used.
                        ! offset = p-oldfst
                       offset = indexw(wbegin) - 1
                       ! perform limited bisection (if necessary) to get approximate
                       ! eigenvalues to the precision needed.
                       call la_qlarrb(in,d(ibegin),work(indlld + ibegin - 1),p,q,rtol1, &
                       rtol2,offset,work(wbegin),wgap(wbegin),werr(wbegin),work(indwrk),iwork( &
                                  iindwk),pivmin,spdiam,in,iinfo)
                       if (iinfo /= 0) then
                          info = -1
                          return
                       end if
                       ! we also recompute the extremal gaps. w holds all eigenvalues
                       ! of the unshifted matrix and must be used for computation
                       ! of wgap, the entries of work might stem from rrrs with
                       ! different shifts. the gaps from wbegin-1+oldfst to
                       ! wbegin-1+oldlst are correctly computed in la_qlarrb.
                       ! however, we only allow the gaps to become greater since
                       ! this is what should happen when we decrease werr
                       if (oldfst > 1) then
                          wgap(wbegin + oldfst - 2) = max(wgap(wbegin + oldfst - 2),w(wbegin + oldfst - 1) - &
                          werr(wbegin + oldfst - 1) - w(wbegin + oldfst - 2) - werr(wbegin + oldfst - 2))

                       end if
                       if (wbegin + oldlst - 1 < wend) then
                          wgap(wbegin + oldlst - 1) = max(wgap(wbegin + oldlst - 1),w(wbegin + oldlst) - &
                                    werr(wbegin + oldlst) - w(wbegin + oldlst - 1) - werr(wbegin + oldlst - 1))
                       end if
                       ! each time the eigenvalues in work get refined, we store
                       ! the newly found approximation with all shifts applied in w
                       do j = oldfst,oldlst
                          w(wbegin + j - 1) = work(wbegin + j - 1) + sigma
                       end do
                    end if
                    ! process the current node.
                    newfst = oldfst
                    loop_140: do j = oldfst,oldlst
                       if (j == oldlst) then
                          ! we are at the right end of the cluster, this is also the
                          ! boundary of the child cluster
                          newlst = j
                       else if (wgap(wbegin + j - 1) >= minrgp*abs(work(wbegin + j - 1))) &
                                 then
                          ! the right relative gap is big enough, the child cluster
                          ! (newfst,..,newlst) is well separated from the following
                          newlst = j
                        else
                          ! inside a child cluster, the relative gap is not
                          ! big enough.
                          cycle loop_140
                       end if
                       ! compute size of child cluster found
                       newsiz = newlst - newfst + 1
                       ! newftt is the place in z where the new rrr or the computed
                       ! eigenvector is to be stored
                       if ((dol == 1) .and. (dou == m)) then
                          ! store representation at location of the leftmost evalue
                          ! of the cluster
                          newftt = wbegin + newfst - 1
                       else
                          if (wbegin + newfst - 1 < dol) then
                             ! store representation at the left end of z array
                             newftt = dol - 1
                          elseif (wbegin + newfst - 1 > dou) then
                             ! store representation at the right end of z array
                             newftt = dou
                          else
                             newftt = wbegin + newfst - 1
                          end if
                       end if
                       if (newsiz > 1) then
                          ! current child is not a singleton but a cluster.
                          ! compute and store new representation of child.
                          ! compute left and right cluster gap.
                          ! lgap and rgap are not computed from work because
                          ! the eigenvalue approximations may stem from rrrs
                          ! different shifts. however, w hold all eigenvalues
                          ! of the unshifted matrix. still, the entries in wgap
                          ! have to be computed from work since the entries
                          ! in w might be of the same order so that gaps are not
                          ! exhibited correctly for very close eigenvalues.
                          if (newfst == 1) then
                             lgap = max(zero,w(wbegin) - werr(wbegin) - vl)
                         else
                             lgap = wgap(wbegin + newfst - 2)
                          end if
                          rgap = wgap(wbegin + newlst - 1)
                          ! compute left- and rightmost eigenvalue of child
                          ! to high precision in order to shift as close
                          ! as possible and obtain as large relative gaps
                          ! as possible
                          do k = 1,2
                             if (k == 1) then
                                p = indexw(wbegin - 1 + newfst)
                             else
                                p = indexw(wbegin - 1 + newlst)
                             end if
                             offset = indexw(wbegin) - 1
                             call la_qlarrb(in,d(ibegin),work(indlld + ibegin - 1),p,p,rqtol, &
                             rqtol,offset,work(wbegin),wgap(wbegin),werr(wbegin),work(indwrk), &
                                       iwork(iindwk),pivmin,spdiam,in,iinfo)
                          end do
                          if ((wbegin + newlst - 1 < dol) .or. (wbegin + newfst - 1 > dou)) then
                             ! if the cluster contains no desired eigenvalues
                             ! skip the computation of that branch of the rep. tree
                             ! we could skip before the refinement of the extremal
                             ! eigenvalues of the child, but then the representation
                             ! tree could be different from the one when nothing is
                             ! skipped. for this reason we skip at this place.
                             idone = idone + newlst - newfst + 1
                             goto 139
                          end if
                          ! compute rrr of child cluster.
                          ! note that the new rrr is stored in z
                          ! la_qlarrf needs lwork = 2*n
                          call la_qlarrf(in,d(ibegin),l(ibegin),work(indld + ibegin - 1), &
                          newfst,newlst,work(wbegin),wgap(wbegin),werr(wbegin),spdiam,lgap, &
                          rgap,pivmin,tau,z(ibegin,newftt),z(ibegin,newftt + 1),work(indwrk), &
                                    iinfo)
                          if (iinfo == 0) then
                             ! a new rrr for the cluster was found by la_qlarrf
                             ! update shift and store it
                             ssigma = sigma + tau
                             z(iend,newftt + 1) = ssigma
                             ! work() are the midpoints and werr() the semi-width
                             ! note that the entries in w are unchanged.
                             do k = newfst,newlst
                                fudge = three*eps*abs(work(wbegin + k - 1))
                                work(wbegin + k - 1) = work(wbegin + k - 1) - tau
                                fudge = fudge + four*eps*abs(work(wbegin + k - 1))
                                ! fudge errors
                                werr(wbegin + k - 1) = werr(wbegin + k - 1) + fudge
                                ! gaps are not fudged. provided that werr is small
                                ! when eigenvalues are close, a zero gap indicates
                                ! that a new representation is needed for resolving
                                ! the cluster. a fudge could lead to a wrong decision
                                ! of judging eigenvalues 'separated' which in
                                ! reality are not. this could have a negative impact
                                ! on the orthogonality of the computed eigenvectors.
                             end do
                             nclus = nclus + 1
                             k = newcls + 2*nclus
                             iwork(k - 1) = newfst
                             iwork(k) = newlst
                          else
                             info = -2
                             return
                          end if
                       else
                          ! compute eigenvector of singleton
                          iter = 0
                          tol = four*log(real(in,KIND=qp))*eps
                          k = newfst
                          windex = wbegin + k - 1
                          windmn = max(windex - 1,1)
                          windpl = min(windex + 1,m)
                          lambda = work(windex)
                          done = done + 1
                          ! check if eigenvector computation is to be skipped
                          if ((windex < dol) .or. (windex > dou)) then
                             eskip = .true.
                             goto 125
                          else
                             eskip = .false.
                          end if
                          left = work(windex) - werr(windex)
                          right = work(windex) + werr(windex)
                          indeig = indexw(windex)
                          ! note that since we compute the eigenpairs for a child,
                          ! all eigenvalue approximations are w.r.t the same shift.
                          ! in this case, the entries in work should be used for
                          ! computing the gaps since they exhibit even very small
                          ! differences in the eigenvalues, as opposed to the
                          ! entries in w which might "look" the same.
                          if (k == 1) then
                             ! in the case range='i' and with not much initial
                             ! accuracy in lambda and vl, the formula
                             ! lgap = max( zero, (sigma - vl) + lambda )
                             ! can lead to an overestimation of the left gap and
                             ! thus to inadequately early rqi 'convergence'.
                             ! prevent this by forcing a small left gap.
                             lgap = eps*max(abs(left),abs(right))
                          else
                             lgap = wgap(windmn)
                          end if
                          if (k == im) then
                             ! in the case range='i' and with not much initial
                             ! accuracy in lambda and vu, the formula
                             ! can lead to an overestimation of the right gap and
                             ! thus to inadequately early rqi 'convergence'.
                             ! prevent this by forcing a small right gap.
                             rgap = eps*max(abs(left),abs(right))
                          else
                             rgap = wgap(windex)
                          end if
                          gap = min(lgap,rgap)
                          if ((k == 1) .or. (k == im)) then
                             ! the eigenvector support can become wrong
                             ! because significant entries could be cut off due to a
                             ! large gaptol parameter in lar1v. prevent this.
                             gaptol = zero
                          else
                             gaptol = gap*eps
                          end if
                          isupmn = in
                          isupmx = 1
                          ! update wgap so that it holds the minimum gap
                          ! to the left or the right. this is crucial in the
                          ! case where bisection is used to ensure that the
                          ! eigenvalue is refined up to the required precision.
                          ! the correct value is restored afterwards.
                          savgap = wgap(windex)
                          wgap(windex) = gap
                          ! we want to use the rayleigh quotient correction
                          ! as often as possible since it converges quadratically
                          ! when we are close enough to the desired eigenvalue.
                          ! however, the rayleigh quotient can have the wrong sign
                          ! and lead us away from the desired eigenvalue. in this
                          ! case, the best we can do is to use bisection.
                          usedbs = .false.
                          usedrq = .false.
                          ! bisection is initially turned off unless it is forced
                          needbs = .not. tryrqc
                          120 continue
                          ! check if bisection should be used to refine eigenvalue
                          if (needbs) then
                             ! take the bisection as new iterate
                             usedbs = .true.
                             itmp1 = iwork(iindr + windex)
                             offset = indexw(wbegin) - 1
                             call la_qlarrb(in,d(ibegin),work(indlld + ibegin - 1),indeig, &
                             indeig,zero,two*eps,offset,work(wbegin),wgap(wbegin),werr(wbegin), &
                                       work(indwrk),iwork(iindwk),pivmin,spdiam,itmp1,iinfo)
                             if (iinfo /= 0) then
                                info = -3
                                return
                             end if
                             lambda = work(windex)
                             ! reset twist index from inaccurate lambda to
                             ! force computation of true mingma
                             iwork(iindr + windex) = 0
                          end if
                          ! given lambda, compute the eigenvector.
                          call la_qlar1v(in,1,in,lambda,d(ibegin),l(ibegin),work( &
                          indld + ibegin - 1),work(indlld + ibegin - 1),pivmin,gaptol,z(ibegin,windex &
                          ),.not. usedbs,negcnt,ztz,mingma,iwork(iindr + windex),isuppz( &
                                    2*windex - 1),nrminv,resid,rqcorr,work(indwrk))
                          if (iter == 0) then
                             bstres = resid
                             bstw = lambda
                          elseif (resid < bstres) then
                             bstres = resid
                             bstw = lambda
                          end if
                          isupmn = min(isupmn,isuppz(2*windex - 1))
                          isupmx = max(isupmx,isuppz(2*windex))
                          iter = iter + 1
                          ! sin alpha <= |resid|/gap
                          ! note that both the residual and the gap are
                          ! proportional to the matrix, so ||t|| doesn't play
                          ! a role in the quotient
                          ! convergence test for rayleigh-quotient iteration
                          ! (omitted when bisection has been used)
                          if (resid > tol*gap .and. abs(rqcorr) > rqtol*abs(lambda) .and. .not. &
                                    usedbs) then
                             ! we need to check that the rqcorr update doesn't
                             ! move the eigenvalue away from the desired one and
                             ! towards a neighbor. -> protection with bisection
                             if (indeig <= negcnt) then
                                ! the wanted eigenvalue lies to the left
                                sgndef = -one
                             else
                                ! the wanted eigenvalue lies to the right
                                sgndef = one
                             end if
                             ! we only use the rqcorr if it improves the
                             ! the iterate reasonably.
                             if ((rqcorr*sgndef >= zero) .and. (lambda + rqcorr <= right) .and. ( &
                                       lambda + rqcorr >= left)) then
                                usedrq = .true.
                                ! store new midpoint of bisection interval in work
                                if (sgndef == one) then
                                   ! the current lambda is on the left of the true
                                   ! eigenvalue
                                   left = lambda
                                   ! we prefer to assume that the error estimate
                                   ! is correct. we could make the interval not
                                   ! as a bracket but to be modified if the rqcorr
                                   ! chooses to. in this case, the right side should
                                   ! be modified as follows:
                                    ! right = max(right, lambda + rqcorr)
                                else
                                   ! the current lambda is on the right of the true
                                   ! eigenvalue
                                   right = lambda
                                   ! see comment about assuming the error estimate is
                                   ! correct above.
                                    ! left = min(left, lambda + rqcorr)
                                end if
                                work(windex) = half*(right + left)
                                ! take rqcorr since it has the correct sign and
                                ! improves the iterate reasonably
                                lambda = lambda + rqcorr
                                ! update width of error interval
                                werr(windex) = half*(right - left)
                             else
                                needbs = .true.
                             end if
                             if (right - left < rqtol*abs(lambda)) then
                                   ! the eigenvalue is computed to bisection accuracy
                                   ! compute eigenvector and stop
                                usedbs = .true.
                                goto 120
                             elseif (iter < maxitr) then
                                goto 120
                             elseif (iter == maxitr) then
                                needbs = .true.
                                goto 120
                             else
                                info = 5
                                return
                             end if
                          else
                             stp2ii = .false.
             if (usedrq .and. usedbs .and. bstres <= resid) then
                                lambda = bstw
                                stp2ii = .true.
                             end if
                             if (stp2ii) then
                                ! improve error angle by second step
                                call la_qlar1v(in,1,in,lambda,d(ibegin),l(ibegin), &
                                work(indld + ibegin - 1),work(indlld + ibegin - 1),pivmin,gaptol,z( &
                                ibegin,windex),.not. usedbs,negcnt,ztz,mingma,iwork(iindr + &
                                windex),isuppz(2*windex - 1),nrminv,resid,rqcorr,work(indwrk &
                                          ))
                             end if
                             work(windex) = lambda
                          end if
                          ! compute fp-vector support w.r.t. whole matrix
                          isuppz(2*windex - 1) = isuppz(2*windex - 1) + oldien
                          isuppz(2*windex) = isuppz(2*windex) + oldien
                          zfrom = isuppz(2*windex - 1)
                          zto = isuppz(2*windex)
                          isupmn = isupmn + oldien
                          isupmx = isupmx + oldien
                          ! ensure vector is ok if support in the rqi has changed
                          if (isupmn < zfrom) then
                             do ii = isupmn,zfrom - 1
                                z(ii,windex) = zero
                             end do
                          end if
                          if (isupmx > zto) then
                             do ii = zto + 1,isupmx
                                z(ii,windex) = zero
                             end do
                          end if
                          call la_qscal(zto - zfrom + 1,nrminv,z(zfrom,windex),1)
                          125 continue
                          ! update w
                          w(windex) = lambda + sigma
                          ! recompute the gaps on the left and right
                          ! but only allow them to become larger and not
                          ! smaller (which can only happen through "bad"
                          ! cancellation and doesn't reflect the theory
                          ! where the initial gaps are underestimated due
                          ! to werr being too crude.)
                          if (.not. eskip) then
                             if (k > 1) then
                                wgap(windmn) = max(wgap(windmn),w(windex) - werr(windex) - w( &
                                          windmn) - werr(windmn))
                             end if
                             if (windex < wend) then
                                wgap(windex) = max(savgap,w(windpl) - werr(windpl) - w( &
                                          windex) - werr(windex))
                             end if
                          end if
                          idone = idone + 1
                       end if
                       ! here ends the code for the current child
                       139 continue
                       ! proceed to any remaining child nodes
                       newfst = j + 1
                    end do loop_140
                 end do loop_150
                 ndepth = ndepth + 1
                 go to 40
              end if
              ibegin = iend + 1
              wbegin = wend + 1
           end do loop_170
           return
     end subroutine la_qlarrv

     !> Using a divide and conquer approach, DLASD0: computes the singular
     !> value decomposition (SVD) of a real upper bidiagonal N-by-M
     !> matrix B with diagonal D and offdiagonal E, where M = N + SQRE.
     !> The algorithm computes orthogonal matrices U and VT such that
     !> B = U * S * VT. The singular values S are overwritten on D.
     !> A related subroutine, DLASDA, computes only the singular values,
     !> and optionally, the singular vectors in compact form.

     pure subroutine la_qlasd0(n,sqre,d,e,u,ldu,vt,ldvt,smlsiz,iwork,work,info)

        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldu,ldvt,n,smlsiz,sqre
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: d(*),e(*)
           real(qp),intent(out) :: u(ldu,*),vt(ldvt,*),work(*)
        ! =====================================================================
           ! Local Scalars
           integer(ilp) :: i,i1,ic,idxq,idxqc,im1,inode,itemp,iwk,j,lf,ll,lvl,m,ncc, &
                      nd,ndb1,ndiml,ndimr,nl,nlf,nlp1,nlvl,nr,nrf,nrp1,sqrei
           real(qp) :: alpha,beta
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (n < 0) then
              info = -1
           else if ((sqre < 0) .or. (sqre > 1)) then
              info = -2
           end if
           m = n + sqre
           if (ldu < n) then
              info = -6
           else if (ldvt < m) then
              info = -8
           else if (smlsiz < 3) then
              info = -9
           end if
           if (info /= 0) then
              call la_xerbla('DLASD0',-info)
              return
           end if
           ! if the input matrix is too small, call la_qlasdq to find the svd.
           if (n <= smlsiz) then
              call la_qlasdq('U',sqre,n,m,n,0,d,e,vt,ldvt,u,ldu,u,ldu,work, &
                        info)
              return
           end if
           ! set up the computation tree.
           inode = 1
           ndiml = inode + n
           ndimr = ndiml + n
           idxq = ndimr + n
           iwk = idxq + n
           call la_qlasdt(n,nlvl,nd,iwork(inode),iwork(ndiml),iwork(ndimr),smlsiz &
                     )
           ! for the nodes on bottom level of the tree, solve
           ! their subproblems by la_qlasdq.
           ndb1 = (nd + 1)/2
           ncc = 0
           loop_30: do i = ndb1,nd
           ! ic : center row of each node
           ! nl : number of rows of left  subproblem
           ! nr : number of rows of right subproblem
           ! nlf: starting row of the left   subproblem
           ! nrf: starting row of the right  subproblem
              i1 = i - 1
              ic = iwork(inode + i1)
              nl = iwork(ndiml + i1)
              nlp1 = nl + 1
              nr = iwork(ndimr + i1)
              nrp1 = nr + 1
              nlf = ic - nl
              nrf = ic + 1
              sqrei = 1
              call la_qlasdq('U',sqrei,nl,nlp1,nl,ncc,d(nlf),e(nlf),vt(nlf,nlf) &
                        ,ldvt,u(nlf,nlf),ldu,u(nlf,nlf),ldu,work,info)
              if (info /= 0) then
                 return
              end if
              itemp = idxq + nlf - 2
              do j = 1,nl
                 iwork(itemp + j) = j
              end do
              if (i == nd) then
                 sqrei = sqre
              else
                 sqrei = 1
              end if
              nrp1 = nr + sqrei
              call la_qlasdq('U',sqrei,nr,nrp1,nr,ncc,d(nrf),e(nrf),vt(nrf,nrf) &
                        ,ldvt,u(nrf,nrf),ldu,u(nrf,nrf),ldu,work,info)
              if (info /= 0) then
                 return
              end if
              itemp = idxq + ic
              do j = 1,nr
                 iwork(itemp + j - 1) = j
              end do
           end do loop_30
           ! now conquer each subproblem bottom-up.
           loop_50: do lvl = nlvl,1,-1
              ! find the first node lf and last node ll on the
              ! current level lvl.
              if (lvl == 1) then
                 lf = 1
                 ll = 1
              else
                 lf = 2**(lvl - 1)
                 ll = 2*lf - 1
              end if
              do i = lf,ll
                 im1 = i - 1
                 ic = iwork(inode + im1)
                 nl = iwork(ndiml + im1)
                 nr = iwork(ndimr + im1)
                 nlf = ic - nl
                 if ((sqre == 0) .and. (i == ll)) then
                    sqrei = sqre
                 else
                    sqrei = 1
                 end if
                 idxqc = idxq + nlf - 1
                 alpha = d(ic)
                 beta = e(ic)
                 call la_qlasd1(nl,nr,sqrei,d(nlf),alpha,beta,u(nlf,nlf),ldu,vt( &
                           nlf,nlf),ldvt,iwork(idxqc),iwork(iwk),work,info)
              ! report the possible convergence failure.
                 if (info /= 0) then
                    return
                 end if
              end do
           end do loop_50
           return
     end subroutine la_qlasd0

     !> DLASD1: computes the SVD of an upper bidiagonal N-by-M matrix B,
     !> where N = NL + NR + 1 and M = N + SQRE. DLASD1 is called from DLASD0.
     !> A related subroutine DLASD7 handles the case in which the singular
     !> values (and the singular vectors in factored form) are desired.
     !> DLASD1 computes the SVD as follows:
     !> ( D1(in)    0    0       0 )
     !> B = U(in) * (   Z1**T   a   Z2**T    b ) * VT(in)
     !> (   0       0   D2(in)   0 )
     !> = U(out) * ( D(out) 0) * VT(out)
     !> where Z**T = (Z1**T a Z2**T b) = u**T VT**T, and u is a vector of dimension M
     !> with ALPHA and BETA in the NL+1 and NL+2 th entries and zeros
     !> elsewhere; and the entry b is empty if SQRE = 0.
     !> The left singular vectors of the original matrix are stored in U, and
     !> the transpose of the right singular vectors are stored in VT, and the
     !> singular values are in D.  The algorithm consists of three stages:
     !> The first stage consists of deflating the size of the problem
     !> when there are multiple singular values or when there are zeros in
     !> the Z vector.  For each such occurrence the dimension of the
     !> secular equation problem is reduced by one.  This stage is
     !> performed by the routine DLASD2.
     !> The second stage consists of calculating the updated
     !> singular values. This is done by finding the square roots of the
     !> roots of the secular equation via the routine DLASD4 (as called
     !> by DLASD3). This routine also calculates the singular vectors of
     !> the current problem.
     !> The final stage consists of computing the updated singular vectors
     !> directly using the updated singular values.  The singular vectors
     !> for the current problem are multiplied with the singular vectors
     !> from the overall problem.

     pure subroutine la_qlasd1(nl,nr,sqre,d,alpha,beta,u,ldu,vt,ldvt,idxq,iwork, &
               work,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldu,ldvt,nl,nr,sqre
           real(qp),intent(inout) :: alpha,beta
           ! Array Arguments
           integer(ilp),intent(inout) :: idxq(*)
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: d(*),u(ldu,*),vt(ldvt,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: coltyp,i,idx,idxc,idxp,iq,isigma,iu2,ivt2,iz,k,ldq,ldu2, &
                     ldvt2,m,n,n1,n2
           real(qp) :: orgnrm
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (nl < 1) then
              info = -1
           else if (nr < 1) then
              info = -2
           else if ((sqre < 0) .or. (sqre > 1)) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('DLASD1',-info)
              return
           end if
           n = nl + nr + 1
           m = n + sqre
           ! the following values are for bookkeeping purposes only.  they are
           ! integer pointers which indicate the portion of the workspace
           ! used by a particular array in la_qlasd2 and la_qlasd3.
           ldu2 = n
           ldvt2 = m
           iz = 1
           isigma = iz + m
           iu2 = isigma + n
           ivt2 = iu2 + ldu2*n
           iq = ivt2 + ldvt2*m
           idx = 1
           idxc = idx + n
           coltyp = idxc + n
           idxp = coltyp + n
           ! scale.
           orgnrm = max(abs(alpha),abs(beta))
           d(nl + 1) = zero
           do i = 1,n
              if (abs(d(i)) > orgnrm) then
                 orgnrm = abs(d(i))
              end if
           end do
           call la_qlascl('G',0,0,orgnrm,one,n,1,d,n,info)
           alpha = alpha/orgnrm
           beta = beta/orgnrm
           ! deflate singular values.
           call la_qlasd2(nl,nr,sqre,k,d,work(iz),alpha,beta,u,ldu,vt,ldvt,work( &
            isigma),work(iu2),ldu2,work(ivt2),ldvt2,iwork(idxp),iwork(idx),iwork( &
                      idxc),idxq,iwork(coltyp),info)
           ! solve secular equation and update singular vectors.
           ldq = k
           call la_qlasd3(nl,nr,sqre,k,d,work(iq),ldq,work(isigma),u,ldu,work( &
           iu2),ldu2,vt,ldvt,work(ivt2),ldvt2,iwork(idxc),iwork(coltyp),work(iz), &
                     info)
           ! report the convergence failure.
           if (info /= 0) then
              return
           end if
           ! unscale.
           call la_qlascl('G',0,0,one,orgnrm,n,1,d,n,info)
           ! prepare the idxq sorting permutation.
           n1 = k
           n2 = n - k
           call la_qlamrg(n1,n2,d,1,-1,idxq)
           return
     end subroutine la_qlasd1

     !> DLASD2: merges the two sets of singular values together into a single
     !> sorted set.  Then it tries to deflate the size of the problem.
     !> There are two ways in which deflation can occur:  when two or more
     !> singular values are close together or if there is a tiny entry in the
     !> Z vector.  For each such occurrence the order of the related secular
     !> equation problem is reduced by one.
     !> DLASD2 is called from DLASD1.

     pure subroutine la_qlasd2(nl,nr,sqre,k,d,z,alpha,beta,u,ldu,vt,ldvt,dsigma, &
               u2,ldu2,vt2,ldvt2,idxp,idx,idxc,idxq,coltyp,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info,k
           integer(ilp),intent(in) :: ldu,ldu2,ldvt,ldvt2,nl,nr,sqre
           real(qp),intent(in) :: alpha,beta
           ! Array Arguments
           integer(ilp),intent(out) :: coltyp(*),idx(*),idxc(*),idxp(*)
           integer(ilp),intent(inout) :: idxq(*)
           real(qp),intent(inout) :: d(*),u(ldu,*),vt(ldvt,*)
           real(qp),intent(out) :: dsigma(*),u2(ldu2,*),vt2(ldvt2,*),z(*)
        ! =====================================================================

           ! Local Arrays
           integer(ilp) :: ctot(4),psm(4)
           ! Local Scalars
           integer(ilp) :: ct,i,idxi,idxj,idxjp,j,jp,jprev,k2,m,n,nlp1,nlp2
           real(qp) :: c,eps,hlftol,s,tau,tol,z1
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (nl < 1) then
              info = -1
           else if (nr < 1) then
              info = -2
           else if ((sqre /= 1) .and. (sqre /= 0)) then
              info = -3
           end if
           n = nl + nr + 1
           m = n + sqre
           if (ldu < n) then
              info = -10
           else if (ldvt < m) then
              info = -12
           else if (ldu2 < n) then
              info = -15
           else if (ldvt2 < m) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('DLASD2',-info)
              return
           end if
           nlp1 = nl + 1
           nlp2 = nl + 2
           ! generate the first part of the vector z; and move the singular
           ! values in the first part of d one position backward.
           z1 = alpha*vt(nlp1,nlp1)
           z(1) = z1
           do i = nl,1,-1
              z(i + 1) = alpha*vt(i,nlp1)
              d(i + 1) = d(i)
              idxq(i + 1) = idxq(i) + 1
           end do
           ! generate the second part of the vector z.
           do i = nlp2,m
              z(i) = beta*vt(i,nlp2)
           end do
           ! initialize some reference arrays.
           do i = 2,nlp1
              coltyp(i) = 1
           end do
           do i = nlp2,n
              coltyp(i) = 2
           end do
           ! sort the singular values into increasing order
           do i = nlp2,n
              idxq(i) = idxq(i) + nlp1
           end do
           ! dsigma, idxc, idxc, and the first column of u2
           ! are used as storage space.
           do i = 2,n
              dsigma(i) = d(idxq(i))
              u2(i,1) = z(idxq(i))
              idxc(i) = coltyp(idxq(i))
           end do
           call la_qlamrg(nl,nr,dsigma(2),1,1,idx(2))
           do i = 2,n
              idxi = 1 + idx(i)
              d(i) = dsigma(idxi)
              z(i) = u2(idxi,1)
              coltyp(i) = idxc(idxi)
           end do
           ! calculate the allowable deflation tolerance
           eps = la_qlamch('EPSILON')
           tol = max(abs(alpha),abs(beta))
           tol = eight*eps*max(abs(d(n)),tol)
           ! there are 2 kinds of deflation -- first a value in the z-vector
           ! is small, second two (or more) singular values are very close
           ! together (their difference is small).
           ! if the value in the z-vector is small, we simply permute the
           ! array so that the corresponding singular value is moved to the
           ! end.
           ! if two values in the d-vector are close, we perform a two-sided
           ! rotation designed to make one of the corresponding z-vector
           ! entries zero, and then permute the array so that the deflated
           ! singular value is moved to the end.
           ! if there are multiple singular values then the problem deflates.
           ! here the number of equal singular values are found.  as each equal
           ! singular value is found, an elementary reflector is computed to
           ! rotate the corresponding singular subspace so that the
           ! corresponding components of z are zero in this new basis.
           k = 1
           k2 = n + 1
           do j = 2,n
              if (abs(z(j)) <= tol) then
                 ! deflate due to small z component.
                 k2 = k2 - 1
                 idxp(k2) = j
                 coltyp(j) = 4
                 if (j == n) go to 120
              else
                 jprev = j
                 go to 90
              end if
           end do
           90 continue
           j = jprev
           100 continue
           j = j + 1
           if (j > n) go to 110
           if (abs(z(j)) <= tol) then
              ! deflate due to small z component.
              k2 = k2 - 1
              idxp(k2) = j
              coltyp(j) = 4
           else
              ! check if singular values are close enough to allow deflation.
              if (abs(d(j) - d(jprev)) <= tol) then
                 ! deflation is possible.
                 s = z(jprev)
                 c = z(j)
                 ! find sqrt(a**2+b**2) without overflow or
                 ! destructive underflow.
                 tau = la_qlapy2(c,s)
                 c = c/tau
                 s = -s/tau
                 z(j) = tau
                 z(jprev) = zero
                 ! apply back the givens rotation to the left and right
                 ! singular vector matrices.
                 idxjp = idxq(idx(jprev) + 1)
                 idxj = idxq(idx(j) + 1)
                 if (idxjp <= nlp1) then
                    idxjp = idxjp - 1
                 end if
                 if (idxj <= nlp1) then
                    idxj = idxj - 1
                 end if
                 call la_qrot(n,u(1,idxjp),1,u(1,idxj),1,c,s)
                 call la_qrot(m,vt(idxjp,1),ldvt,vt(idxj,1),ldvt,c,s)
                 if (coltyp(j) /= coltyp(jprev)) then
                    coltyp(j) = 3
                 end if
                 coltyp(jprev) = 4
                 k2 = k2 - 1
                 idxp(k2) = jprev
                 jprev = j
              else
                 k = k + 1
                 u2(k,1) = z(jprev)
                 dsigma(k) = d(jprev)
                 idxp(k) = jprev
                 jprev = j
              end if
           end if
           go to 100
           110 continue
           ! record the last singular value.
           k = k + 1
           u2(k,1) = z(jprev)
           dsigma(k) = d(jprev)
           idxp(k) = jprev
           120 continue
           ! count up the total number of the various types of columns, then
           ! form a permutation which positions the four column types into
           ! four groups of uniform structure (although one or more of these
           ! groups may be empty).
           do j = 1,4
              ctot(j) = 0
           end do
           do j = 2,n
              ct = coltyp(j)
              ctot(ct) = ctot(ct) + 1
           end do
           ! psm(*) = position in submatrix (of types 1 through 4)
           psm(1) = 2
           psm(2) = 2 + ctot(1)
           psm(3) = psm(2) + ctot(2)
           psm(4) = psm(3) + ctot(3)
           ! fill out the idxc array so that the permutation which it induces
           ! will place all type-1 columns first, all type-2 columns next,
           ! then all type-3's, and finally all type-4's, starting from the
           ! second column. this applies similarly to the rows of vt.
           do j = 2,n
              jp = idxp(j)
              ct = coltyp(jp)
              idxc(psm(ct)) = j
              psm(ct) = psm(ct) + 1
           end do
           ! sort the singular values and corresponding singular vectors into
           ! dsigma, u2, and vt2 respectively.  the singular values/vectors
           ! which were not deflated go into the first k slots of dsigma, u2,
           ! and vt2 respectively, while those which were deflated go into the
           ! last n - k slots, except that the first column/row will be treated
           ! separately.
           do j = 2,n
              jp = idxp(j)
              dsigma(j) = d(jp)
              idxj = idxq(idx(idxp(idxc(j))) + 1)
              if (idxj <= nlp1) then
                 idxj = idxj - 1
              end if
              call la_qcopy(n,u(1,idxj),1,u2(1,j),1)
              call la_qcopy(m,vt(idxj,1),ldvt,vt2(j,1),ldvt2)
           end do
           ! determine dsigma(1), dsigma(2) and z(1)
           dsigma(1) = zero
           hlftol = tol/two
           if (abs(dsigma(2)) <= hlftol) dsigma(2) = hlftol
           if (m > n) then
              z(1) = la_qlapy2(z1,z(m))
              if (z(1) <= tol) then
                 c = one
                 s = zero
                 z(1) = tol
              else
                 c = z1/z(1)
                 s = z(m)/z(1)
              end if
           else
              if (abs(z1) <= tol) then
                 z(1) = tol
              else
                 z(1) = z1
              end if
           end if
           ! move the rest of the updating row to z.
           call la_qcopy(k - 1,u2(2,1),1,z(2),1)
           ! determine the first column of u2, the first row of vt2 and the
           ! last row of vt.
           call la_qlaset('A',n,1,zero,zero,u2,ldu2)
           u2(nlp1,1) = one
           if (m > n) then
              do i = 1,nlp1
                 vt(m,i) = -s*vt(nlp1,i)
                 vt2(1,i) = c*vt(nlp1,i)
              end do
              do i = nlp2,m
                 vt2(1,i) = s*vt(m,i)
                 vt(m,i) = c*vt(m,i)
              end do
           else
              call la_qcopy(m,vt(nlp1,1),ldvt,vt2(1,1),ldvt2)
           end if
           if (m > n) then
              call la_qcopy(m,vt(m,1),ldvt,vt2(m,1),ldvt2)
           end if
           ! the deflated singular values and their corresponding vectors go
           ! into the back of d, u, and v respectively.
           if (n > k) then
              call la_qcopy(n - k,dsigma(k + 1),1,d(k + 1),1)
              call la_qlacpy('A',n,n - k,u2(1,k + 1),ldu2,u(1,k + 1),ldu)
              call la_qlacpy('A',n - k,m,vt2(k + 1,1),ldvt2,vt(k + 1,1),ldvt)
           end if
           ! copy ctot into coltyp for referencing in la_qlasd3.
           do j = 1,4
              coltyp(j) = ctot(j)
           end do
           return
     end subroutine la_qlasd2

     !> DLASD3: finds all the square roots of the roots of the secular
     !> equation, as defined by the values in D and Z.  It makes the
     !> appropriate calls to DLASD4 and then updates the singular
     !> vectors by matrix multiplication.
     !> This code makes very mild assumptions about floating point
     !> arithmetic. It will work on machines with a guard digit in
     !> add/subtract, or on those binary machines without guard digits
     !> which subtract like the Cray XMP, Cray YMP, Cray C 90, or Cray 2.
     !> It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.
     !> DLASD3 is called from DLASD1.

     pure subroutine la_qlasd3(nl,nr,sqre,k,d,q,ldq,dsigma,u,ldu,u2,ldu2,vt,ldvt, &
                vt2,ldvt2,idxc,ctot,z,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,ldq,ldu,ldu2,ldvt,ldvt2,nl,nr,sqre
           ! Array Arguments
           integer(ilp),intent(in) :: ctot(*),idxc(*)
           real(qp),intent(out) :: d(*),q(ldq,*),u(ldu,*),vt(ldvt,*)
           real(qp),intent(inout) :: dsigma(*),vt2(ldvt2,*),z(*)
           real(qp),intent(in) :: u2(ldu2,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: ctemp,i,j,jc,ktemp,m,n,nlp1,nlp2,nrp1
           real(qp) :: rho,temp
           ! Intrinsic Functions
           intrinsic :: abs,sign,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (nl < 1) then
              info = -1
           else if (nr < 1) then
              info = -2
           else if ((sqre /= 1) .and. (sqre /= 0)) then
              info = -3
           end if
           n = nl + nr + 1
           m = n + sqre
           nlp1 = nl + 1
           nlp2 = nl + 2
           if ((k < 1) .or. (k > n)) then
              info = -4
           else if (ldq < k) then
              info = -7
           else if (ldu < n) then
              info = -10
           else if (ldu2 < n) then
              info = -12
           else if (ldvt < m) then
              info = -14
           else if (ldvt2 < m) then
              info = -16
           end if
           if (info /= 0) then
              call la_xerbla('DLASD3',-info)
              return
           end if
           ! quick return if possible
           if (k == 1) then
              d(1) = abs(z(1))
              call la_qcopy(m,vt2(1,1),ldvt2,vt(1,1),ldvt)
              if (z(1) > zero) then
                 call la_qcopy(n,u2(1,1),1,u(1,1),1)
              else
                 do i = 1,n
                    u(i,1) = -u2(i,1)
                 end do
              end if
              return
           end if
           ! modify values dsigma(i) to make sure all dsigma(i)-dsigma(j) can
           ! be computed with high relative accuracy (barring over/underflow).
           ! this is a problem on machines without a guard digit in
           ! add/subtract (cray xmp, cray ymp, cray c 90 and cray 2).
           ! the following code replaces dsigma(i) by 2*dsigma(i)-dsigma(i),
           ! which on any of these machines zeros out the bottommost
           ! bit of dsigma(i) if it is 1; this makes the subsequent
           ! subtractions dsigma(i)-dsigma(j) unproblematic when cancellation
           ! occurs. on binary machines with a guard digit (almost all
           ! machines) it does not change dsigma(i) at all. on hexadecimal
           ! and decimal machines with a guard digit, it slightly
           ! changes the bottommost bits of dsigma(i). it does not account
           ! for hexadecimal or decimal machines without guard digits
           ! (we know of none). we use a subroutine call to compute
           ! 2*dsigma(i) to prevent optimizing compilers from eliminating
           ! this code.
           do i = 1,k
              dsigma(i) = la_qlamc3(dsigma(i),dsigma(i)) - dsigma(i)
           end do
           ! keep a copy of z.
           call la_qcopy(k,z,1,q,1)
           ! normalize z.
           rho = la_qnrm2(k,z,1)
           call la_qlascl('G',0,0,rho,one,k,1,z,k,info)
           rho = rho*rho
           ! find the new singular values.
           do j = 1,k
              call la_qlasd4(k,j,dsigma,z,u(1,j),rho,d(j),vt(1,j),info)

              ! if the zero finder fails, report the convergence failure.
              if (info /= 0) then
                 return
              end if
           end do
           ! compute updated z.
           do i = 1,k
              z(i) = u(i,k)*vt(i,k)
              do j = 1,i - 1
                 z(i) = z(i)*(u(i,j)*vt(i,j)/(dsigma(i) - dsigma(j))/(dsigma(i &
                           ) + dsigma(j)))
              end do
              do j = i,k - 1
                 z(i) = z(i)*(u(i,j)*vt(i,j)/(dsigma(i) - dsigma(j + 1))/(dsigma( &
                           i) + dsigma(j + 1)))
              end do
              z(i) = sign(sqrt(abs(z(i))),q(i,1))
           end do
           ! compute left singular vectors of the modified diagonal matrix,
           ! and store related information for the right singular vectors.
           do i = 1,k
              vt(1,i) = z(1)/u(1,i)/vt(1,i)
              u(1,i) = negone
              do j = 2,k
                 vt(j,i) = z(j)/u(j,i)/vt(j,i)
                 u(j,i) = dsigma(j)*vt(j,i)
              end do
              temp = la_qnrm2(k,u(1,i),1)
              q(1,i) = u(1,i)/temp
              do j = 2,k
                 jc = idxc(j)
                 q(j,i) = u(jc,i)/temp
              end do
           end do
           ! update the left singular vector matrix.
           if (k == 2) then
              call la_qgemm('N','N',n,k,k,one,u2,ldu2,q,ldq,zero,u,ldu)
              go to 100
           end if
           if (ctot(1) > 0) then
              call la_qgemm('N','N',nl,k,ctot(1),one,u2(1,2),ldu2,q(2,1),ldq, &
                         zero,u(1,1),ldu)
              if (ctot(3) > 0) then
                 ktemp = 2 + ctot(1) + ctot(2)
                 call la_qgemm('N','N',nl,k,ctot(3),one,u2(1,ktemp),ldu2,q( &
                           ktemp,1),ldq,one,u(1,1),ldu)
              end if
           else if (ctot(3) > 0) then
              ktemp = 2 + ctot(1) + ctot(2)
              call la_qgemm('N','N',nl,k,ctot(3),one,u2(1,ktemp),ldu2,q(ktemp, &
                        1),ldq,zero,u(1,1),ldu)
           else
              call la_qlacpy('F',nl,k,u2,ldu2,u,ldu)
           end if
           call la_qcopy(k,q(1,1),ldq,u(nlp1,1),ldu)
           ktemp = 2 + ctot(1)
           ctemp = ctot(2) + ctot(3)
           call la_qgemm('N','N',nr,k,ctemp,one,u2(nlp2,ktemp),ldu2,q(ktemp,1), &
                     ldq,zero,u(nlp2,1),ldu)
           ! generate the right singular vectors.
           100 continue
           do i = 1,k
              temp = la_qnrm2(k,vt(1,i),1)
              q(i,1) = vt(1,i)/temp
              do j = 2,k
                 jc = idxc(j)
                 q(i,j) = vt(jc,i)/temp
              end do
           end do
           ! update the right singular vector matrix.
           if (k == 2) then
              call la_qgemm('N','N',k,m,k,one,q,ldq,vt2,ldvt2,zero,vt,ldvt)

              return
           end if
           ktemp = 1 + ctot(1)
           call la_qgemm('N','N',k,nlp1,ktemp,one,q(1,1),ldq,vt2(1,1),ldvt2, &
                     zero,vt(1,1),ldvt)
           ktemp = 2 + ctot(1) + ctot(2)
           if (ktemp <= ldvt2) call la_qgemm('N','N',k,nlp1,ctot(3),one,q(1,ktemp), &
                     ldq,vt2(ktemp,1),ldvt2,one,vt(1,1),ldvt)
           ktemp = ctot(1) + 1
           nrp1 = nr + sqre
           if (ktemp > 1) then
              do i = 1,k
                 q(i,ktemp) = q(i,1)
              end do
              do i = nlp2,m
                 vt2(ktemp,i) = vt2(1,i)
              end do
           end if
           ctemp = 1 + ctot(2) + ctot(3)
           call la_qgemm('N','N',k,nrp1,ctemp,one,q(1,ktemp),ldq,vt2(ktemp,nlp2) &
                     ,ldvt2,zero,vt(1,nlp2),ldvt)
           return
     end subroutine la_qlasd3

     !> This subroutine computes the square root of the I-th updated
     !> eigenvalue of a positive symmetric rank-one modification to
     !> a positive diagonal matrix whose entries are given as the squares
     !> of the corresponding entries in the array d, and that
     !> 0 <= D(i) < D(j)  for  i < j
     !> and that RHO > 0. This is arranged by the calling routine, and is
     !> no loss in generality.  The rank-one modified system is thus
     !> diag( D ) * diag( D ) +  RHO * Z * Z_transpose.
     !> where we assume the Euclidean norm of Z is 1.
     !> The method consists of approximating the rational functions in the
     !> secular equation by simpler interpolating rational functions.

     pure subroutine la_qlasd4(n,i,d,z,delta,rho,sigma,work,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: i,n
           integer(ilp),intent(out) :: info
           real(qp),intent(in) :: rho
           real(qp),intent(out) :: sigma
           ! Array Arguments
           real(qp),intent(in) :: d(*),z(*)
           real(qp),intent(out) :: delta(*),work(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: maxit = 400

           ! Local Scalars
           logical(lk) :: orgati,swtch,swtch3,geomavg
           integer(ilp) :: ii,iim1,iip1,ip1,iter,j,niter
           real(qp) :: a,b,c,delsq,delsq2,sq2,dphi,dpsi,dtiim,dtiip,dtipsq,dtisq, &
           dtnsq,dtnsq1,dw,eps,erretm,eta,phi,prew,psi,rhoinv,sglb,sgub,tau,tau2, &
                     temp,temp1,temp2,w
           ! Local Arrays
           real(qp) :: dd(3),zz(3)
           ! Intrinsic Functions
           intrinsic :: abs,max,min,sqrt
           ! Executable Statements
           ! since this routine is called in an inner loop, we do no argument
           ! checking.
           ! quick return for n=1 and 2.
           info = 0
           if (n == 1) then
              ! presumably, i=1 upon entry
              sigma = sqrt(d(1)*d(1) + rho*z(1)*z(1))
              delta(1) = one
              work(1) = one
              return
           end if
           if (n == 2) then
              call la_qlasd5(i,d,z,delta,rho,sigma,work)
              return
           end if
           ! compute machine epsilon
           eps = la_qlamch('EPSILON')
           rhoinv = one/rho
           tau2 = zero
           ! the case i = n
           if (i == n) then
              ! initialize some basic variables
              ii = n - 1
              niter = 1
              ! calculate initial guess
              temp = rho/two
              ! if ||z||_2 is not one, then temp should be set to
              ! rho * ||z||_2^2 / two
              temp1 = temp/(d(n) + sqrt(d(n)*d(n) + temp))
              do j = 1,n
                 work(j) = d(j) + d(n) + temp1
                 delta(j) = (d(j) - d(n)) - temp1
              end do
              psi = zero
              do j = 1,n - 2
                 psi = psi + z(j)*z(j)/(delta(j)*work(j))
              end do
              c = rhoinv + psi
              w = c + z(ii)*z(ii)/(delta(ii)*work(ii)) + z(n)*z(n)/(delta(n) &
                        *work(n))
              if (w <= zero) then
                 temp1 = sqrt(d(n)*d(n) + rho)
                 temp = z(n - 1)*z(n - 1)/((d(n - 1) + temp1)*(d(n) - d(n - 1) + rho/(d(n) + &
                           temp1))) + z(n)*z(n)/rho
                 ! the following tau2 is to approximate
                 ! sigma_n^2 - d( n )*d( n )
                 if (c <= temp) then
                    tau = rho
                 else
                    delsq = (d(n) - d(n - 1))*(d(n) + d(n - 1))
                    a = -c*delsq + z(n - 1)*z(n - 1) + z(n)*z(n)
                    b = z(n)*z(n)*delsq
                    if (a < zero) then
                       tau2 = two*b/(sqrt(a*a + four*b*c) - a)
                    else
                       tau2 = (a + sqrt(a*a + four*b*c))/(two*c)
                    end if
                    tau = tau2/(d(n) + sqrt(d(n)*d(n) + tau2))
                 end if
                 ! it can be proved that
                     ! d(n)^2+rho/2 <= sigma_n^2 < d(n)^2+tau2 <= d(n)^2+rho
              else
                 delsq = (d(n) - d(n - 1))*(d(n) + d(n - 1))
                 a = -c*delsq + z(n - 1)*z(n - 1) + z(n)*z(n)
                 b = z(n)*z(n)*delsq
                 ! the following tau2 is to approximate
                 ! sigma_n^2 - d( n )*d( n )
                 if (a < zero) then
                    tau2 = two*b/(sqrt(a*a + four*b*c) - a)
                 else
                    tau2 = (a + sqrt(a*a + four*b*c))/(two*c)
                 end if
                 tau = tau2/(d(n) + sqrt(d(n)*d(n) + tau2))
                 ! it can be proved that
                 ! d(n)^2 < d(n)^2+tau2 < sigma(n)^2 < d(n)^2+rho/2
              end if
              ! the following tau is to approximate sigma_n - d( n )
               ! tau = tau2 / ( d( n )+sqrt( d( n )*d( n )+tau2 ) )
              sigma = d(n) + tau
              do j = 1,n
                 delta(j) = (d(j) - d(n)) - tau
                 work(j) = d(j) + d(n) + tau
              end do
              ! evaluate psi and the derivative dpsi
              dpsi = zero
              psi = zero
              erretm = zero
              do j = 1,ii
                 temp = z(j)/(delta(j)*work(j))
                 psi = psi + z(j)*temp
                 dpsi = dpsi + temp*temp
                 erretm = erretm + psi
              end do
              erretm = abs(erretm)
              ! evaluate phi and the derivative dphi
              temp = z(n)/(delta(n)*work(n))
              phi = z(n)*temp
              dphi = temp*temp
              erretm = eight*(-phi - psi) + erretm - phi + rhoinv
          ! $          + abs( tau2 )*( dpsi+dphi )
              w = rhoinv + phi + psi
              ! test for convergence
              if (abs(w) <= eps*erretm) then
                 go to 240
              end if
              ! calculate the new step
              niter = niter + 1
              dtnsq1 = work(n - 1)*delta(n - 1)
              dtnsq = work(n)*delta(n)
              c = w - dtnsq1*dpsi - dtnsq*dphi
              a = (dtnsq + dtnsq1)*w - dtnsq*dtnsq1*(dpsi + dphi)
              b = dtnsq*dtnsq1*w
              if (c < zero) c = abs(c)
              if (c == zero) then
                 eta = rho - sigma*sigma
              else if (a >= zero) then
                 eta = (a + sqrt(abs(a*a - four*b*c)))/(two*c)
              else
                 eta = two*b/(a - sqrt(abs(a*a - four*b*c)))
              end if
              ! note, eta should be positive if w is negative, and
              ! eta should be negative otherwise. however,
              ! if for some reason caused by roundoff, eta*w > 0,
              ! we simply use one newton step instead. this way
              ! will guarantee eta*w < 0.
              if (w*eta > zero) eta = -w/(dpsi + dphi)
              temp = eta - dtnsq
              if (temp > rho) eta = rho + dtnsq
              eta = eta/(sigma + sqrt(eta + sigma*sigma))
              tau = tau + eta
              sigma = sigma + eta
              do j = 1,n
                 delta(j) = delta(j) - eta
                 work(j) = work(j) + eta
              end do
              ! evaluate psi and the derivative dpsi
              dpsi = zero
              psi = zero
              erretm = zero
              do j = 1,ii
                 temp = z(j)/(work(j)*delta(j))
                 psi = psi + z(j)*temp
                 dpsi = dpsi + temp*temp
                 erretm = erretm + psi
              end do
              erretm = abs(erretm)
              ! evaluate phi and the derivative dphi
              tau2 = work(n)*delta(n)
              temp = z(n)/tau2
              phi = z(n)*temp
              dphi = temp*temp
              erretm = eight*(-phi - psi) + erretm - phi + rhoinv
          ! $          + abs( tau2 )*( dpsi+dphi )
              w = rhoinv + phi + psi
              ! main loop to update the values of the array   delta
              iter = niter + 1
              loop_90: do niter = iter,maxit
                 ! test for convergence
                 if (abs(w) <= eps*erretm) then
                    go to 240
                 end if
                 ! calculate the new step
                 dtnsq1 = work(n - 1)*delta(n - 1)
                 dtnsq = work(n)*delta(n)
                 c = w - dtnsq1*dpsi - dtnsq*dphi
                 a = (dtnsq + dtnsq1)*w - dtnsq1*dtnsq*(dpsi + dphi)
                 b = dtnsq1*dtnsq*w
                 if (a >= zero) then
                    eta = (a + sqrt(abs(a*a - four*b*c)))/(two*c)
                 else
                    eta = two*b/(a - sqrt(abs(a*a - four*b*c)))
                 end if
                 ! note, eta should be positive if w is negative, and
                 ! eta should be negative otherwise. however,
                 ! if for some reason caused by roundoff, eta*w > 0,
                 ! we simply use one newton step instead. this way
                 ! will guarantee eta*w < 0.
                 if (w*eta > zero) eta = -w/(dpsi + dphi)
                 temp = eta - dtnsq
                 if (temp <= zero) eta = eta/two
                 eta = eta/(sigma + sqrt(eta + sigma*sigma))
                 tau = tau + eta
                 sigma = sigma + eta
                 do j = 1,n
                    delta(j) = delta(j) - eta
                    work(j) = work(j) + eta
                 end do
                 ! evaluate psi and the derivative dpsi
                 dpsi = zero
                 psi = zero
                 erretm = zero
                 do j = 1,ii
                    temp = z(j)/(work(j)*delta(j))
                    psi = psi + z(j)*temp
                    dpsi = dpsi + temp*temp
                    erretm = erretm + psi
                 end do
                 erretm = abs(erretm)
                 ! evaluate phi and the derivative dphi
                 tau2 = work(n)*delta(n)
                 temp = z(n)/tau2
                 phi = z(n)*temp
                 dphi = temp*temp
                 erretm = eight*(-phi - psi) + erretm - phi + rhoinv
          ! $             + abs( tau2 )*( dpsi+dphi )
                 w = rhoinv + phi + psi
              end do loop_90
              ! return with info = 1, niter = maxit and not converged
              info = 1
              go to 240
              ! end for the case i = n
           else
              ! the case for i < n
              niter = 1
              ip1 = i + 1
              ! calculate initial guess
              delsq = (d(ip1) - d(i))*(d(ip1) + d(i))
              delsq2 = delsq/two
              sq2 = sqrt((d(i)*d(i) + d(ip1)*d(ip1))/two)
              temp = delsq2/(d(i) + sq2)
              do j = 1,n
                 work(j) = d(j) + d(i) + temp
                 delta(j) = (d(j) - d(i)) - temp
              end do
              psi = zero
              do j = 1,i - 1
                 psi = psi + z(j)*z(j)/(work(j)*delta(j))
              end do
              phi = zero
              do j = n,i + 2,-1
                 phi = phi + z(j)*z(j)/(work(j)*delta(j))
              end do
              c = rhoinv + psi + phi
              w = c + z(i)*z(i)/(work(i)*delta(i)) + z(ip1)*z(ip1)/(work(ip1) &
                        *delta(ip1))
              geomavg = .false.
              if (w > zero) then
                 ! d(i)^2 < the ith sigma^2 < (d(i)^2+d(i+1)^2)/2
                 ! we choose d(i) as origin.
                 orgati = .true.
                 ii = i
                 sglb = zero
                 sgub = delsq2/(d(i) + sq2)
                 a = c*delsq + z(i)*z(i) + z(ip1)*z(ip1)
                 b = z(i)*z(i)*delsq
                 if (a > zero) then
                    tau2 = two*b/(a + sqrt(abs(a*a - four*b*c)))
                 else
                    tau2 = (a - sqrt(abs(a*a - four*b*c)))/(two*c)
                 end if
                 ! tau2 now is an estimation of sigma^2 - d( i )^2. the
                 ! following, however, is the corresponding estimation of
                 ! sigma - d( i ).
                 tau = tau2/(d(i) + sqrt(d(i)*d(i) + tau2))
                 temp = sqrt(eps)
                 if ((d(i) <= temp*d(ip1)) .and. (abs(z(i)) <= temp) .and. (d(i) > zero)) then
                    tau = min(ten*d(i),sgub)
                    geomavg = .true.
                 end if
              else
                 ! (d(i)^2+d(i+1)^2)/2 <= the ith sigma^2 < d(i+1)^2/2
                 ! we choose d(i+1) as origin.
                 orgati = .false.
                 ii = ip1
                 sglb = -delsq2/(d(ii) + sq2)
                 sgub = zero
                 a = c*delsq - z(i)*z(i) - z(ip1)*z(ip1)
                 b = z(ip1)*z(ip1)*delsq
                 if (a < zero) then
                    tau2 = two*b/(a - sqrt(abs(a*a + four*b*c)))
                 else
                    tau2 = -(a + sqrt(abs(a*a + four*b*c)))/(two*c)
                 end if
                 ! tau2 now is an estimation of sigma^2 - d( ip1 )^2. the
                 ! following, however, is the corresponding estimation of
                 ! sigma - d( ip1 ).
                 tau = tau2/(d(ip1) + sqrt(abs(d(ip1)*d(ip1) + tau2)))
              end if
              sigma = d(ii) + tau
              do j = 1,n
                 work(j) = d(j) + d(ii) + tau
                 delta(j) = (d(j) - d(ii)) - tau
              end do
              iim1 = ii - 1
              iip1 = ii + 1
              ! evaluate psi and the derivative dpsi
              dpsi = zero
              psi = zero
              erretm = zero
              do j = 1,iim1
                 temp = z(j)/(work(j)*delta(j))
                 psi = psi + z(j)*temp
                 dpsi = dpsi + temp*temp
                 erretm = erretm + psi
              end do
              erretm = abs(erretm)
              ! evaluate phi and the derivative dphi
              dphi = zero
              phi = zero
              do j = n,iip1,-1
                 temp = z(j)/(work(j)*delta(j))
                 phi = phi + z(j)*temp
                 dphi = dphi + temp*temp
                 erretm = erretm + phi
              end do
              w = rhoinv + phi + psi
              ! w is the value of the secular function with
              ! its ii-th element removed.
              swtch3 = .false.
              if (orgati) then
                 if (w < zero) swtch3 = .true.
              else
                 if (w > zero) swtch3 = .true.
              end if
              if (ii == 1 .or. ii == n) swtch3 = .false.
              temp = z(ii)/(work(ii)*delta(ii))
              dw = dpsi + dphi + temp*temp
              temp = z(ii)*temp
              w = w + temp
              erretm = eight*(phi - psi) + erretm + two*rhoinv + three*abs(temp)
          ! $          + abs( tau2 )*dw
              ! test for convergence
              if (abs(w) <= eps*erretm) then
                 go to 240
              end if
              if (w <= zero) then
                 sglb = max(sglb,tau)
              else
                 sgub = min(sgub,tau)
              end if
              ! calculate the new step
              niter = niter + 1
              if (.not. swtch3) then
                 dtipsq = work(ip1)*delta(ip1)
                 dtisq = work(i)*delta(i)
                 if (orgati) then
                    c = w - dtipsq*dw + delsq*(z(i)/dtisq)**2
                 else
                    c = w - dtisq*dw - delsq*(z(ip1)/dtipsq)**2
                 end if
                 a = (dtipsq + dtisq)*w - dtipsq*dtisq*dw
                 b = dtipsq*dtisq*w
                 if (c == zero) then
                    if (a == zero) then
                       if (orgati) then
                          a = z(i)*z(i) + dtipsq*dtipsq*(dpsi + dphi)
                       else
                          a = z(ip1)*z(ip1) + dtisq*dtisq*(dpsi + dphi)
                       end if
                    end if
                    eta = b/a
                 else if (a <= zero) then
                    eta = (a - sqrt(abs(a*a - four*b*c)))/(two*c)
                 else
                    eta = two*b/(a + sqrt(abs(a*a - four*b*c)))
                 end if
              else
                 ! interpolation using three most relevant poles
                 dtiim = work(iim1)*delta(iim1)
                 dtiip = work(iip1)*delta(iip1)
                 temp = rhoinv + psi + phi
                 if (orgati) then
                    temp1 = z(iim1)/dtiim
                    temp1 = temp1*temp1
                    c = (temp - dtiip*(dpsi + dphi)) - (d(iim1) - d(iip1))*(d(iim1) + d( &
                              iip1))*temp1
                    zz(1) = z(iim1)*z(iim1)
                    if (dpsi < temp1) then
                       zz(3) = dtiip*dtiip*dphi
                    else
                       zz(3) = dtiip*dtiip*((dpsi - temp1) + dphi)
                    end if
                 else
                    temp1 = z(iip1)/dtiip
                    temp1 = temp1*temp1
                    c = (temp - dtiim*(dpsi + dphi)) - (d(iip1) - d(iim1))*(d(iim1) + d( &
                              iip1))*temp1
                    if (dphi < temp1) then
                       zz(1) = dtiim*dtiim*dpsi
                    else
                       zz(1) = dtiim*dtiim*(dpsi + (dphi - temp1))
                    end if
                    zz(3) = z(iip1)*z(iip1)
                 end if
                 zz(2) = z(ii)*z(ii)
                 dd(1) = dtiim
                 dd(2) = delta(ii)*work(ii)
                 dd(3) = dtiip
                 call la_qlaed6(niter,orgati,c,dd,zz,w,eta,info)
                 if (info /= 0) then
                    ! if info is not 0, i.e., la_qlaed6 failed, switch back
                    ! to 2 pole interpolation.
                    swtch3 = .false.
                    info = 0
                    dtipsq = work(ip1)*delta(ip1)
                    dtisq = work(i)*delta(i)
                    if (orgati) then
                       c = w - dtipsq*dw + delsq*(z(i)/dtisq)**2
                    else
                       c = w - dtisq*dw - delsq*(z(ip1)/dtipsq)**2
                    end if
                    a = (dtipsq + dtisq)*w - dtipsq*dtisq*dw
                    b = dtipsq*dtisq*w
                    if (c == zero) then
                       if (a == zero) then
                          if (orgati) then
                             a = z(i)*z(i) + dtipsq*dtipsq*(dpsi + dphi)
                          else
                             a = z(ip1)*z(ip1) + dtisq*dtisq*(dpsi + dphi)
                          end if
                       end if
                       eta = b/a
                    else if (a <= zero) then
                       eta = (a - sqrt(abs(a*a - four*b*c)))/(two*c)
                    else
                       eta = two*b/(a + sqrt(abs(a*a - four*b*c)))
                    end if
                 end if
              end if
              ! note, eta should be positive if w is negative, and
              ! eta should be negative otherwise. however,
              ! if for some reason caused by roundoff, eta*w > 0,
              ! we simply use one newton step instead. this way
              ! will guarantee eta*w < 0.
              if (w*eta >= zero) eta = -w/dw
              eta = eta/(sigma + sqrt(sigma*sigma + eta))
              temp = tau + eta
              if (temp > sgub .or. temp < sglb) then
                 if (w < zero) then
                    eta = (sgub - tau)/two
                 else
                    eta = (sglb - tau)/two
                 end if
                 if (geomavg) then
                    if (w < zero) then
                       if (tau > zero) then
                          eta = sqrt(sgub*tau) - tau
                       end if
                    else
                       if (sglb > zero) then
                          eta = sqrt(sglb*tau) - tau
                       end if
                    end if
                 end if
              end if
              prew = w
              tau = tau + eta
              sigma = sigma + eta
              do j = 1,n
                 work(j) = work(j) + eta
                 delta(j) = delta(j) - eta
              end do
              ! evaluate psi and the derivative dpsi
              dpsi = zero
              psi = zero
              erretm = zero
              do j = 1,iim1
                 temp = z(j)/(work(j)*delta(j))
                 psi = psi + z(j)*temp
                 dpsi = dpsi + temp*temp
                 erretm = erretm + psi
              end do
              erretm = abs(erretm)
              ! evaluate phi and the derivative dphi
              dphi = zero
              phi = zero
              do j = n,iip1,-1
                 temp = z(j)/(work(j)*delta(j))
                 phi = phi + z(j)*temp
                 dphi = dphi + temp*temp
                 erretm = erretm + phi
              end do
              tau2 = work(ii)*delta(ii)
              temp = z(ii)/tau2
              dw = dpsi + dphi + temp*temp
              temp = z(ii)*temp
              w = rhoinv + phi + psi + temp
              erretm = eight*(phi - psi) + erretm + two*rhoinv + three*abs(temp)
          ! $          + abs( tau2 )*dw
              swtch = .false.
              if (orgati) then
                 if (-w > abs(prew)/ten) swtch = .true.
              else
                 if (w > abs(prew)/ten) swtch = .true.
              end if
              ! main loop to update the values of the array   delta and work
              iter = niter + 1
              loop_230: do niter = iter,maxit
                 ! test for convergence
                 if (abs(w) <= eps*erretm) then
           ! $          .or. (sgub-sglb)<=eight*abs(sgub+sglb) ) then
                    go to 240
                 end if
                 if (w <= zero) then
                    sglb = max(sglb,tau)
                 else
                    sgub = min(sgub,tau)
                 end if
                 ! calculate the new step
                 if (.not. swtch3) then
                    dtipsq = work(ip1)*delta(ip1)
                    dtisq = work(i)*delta(i)
                    if (.not. swtch) then
                       if (orgati) then
                          c = w - dtipsq*dw + delsq*(z(i)/dtisq)**2
                       else
                          c = w - dtisq*dw - delsq*(z(ip1)/dtipsq)**2
                       end if
                    else
                       temp = z(ii)/(work(ii)*delta(ii))
                       if (orgati) then
                          dpsi = dpsi + temp*temp
                       else
                          dphi = dphi + temp*temp
                       end if
                       c = w - dtisq*dpsi - dtipsq*dphi
                    end if
                    a = (dtipsq + dtisq)*w - dtipsq*dtisq*dw
                    b = dtipsq*dtisq*w
                    if (c == zero) then
                       if (a == zero) then
                          if (.not. swtch) then
                             if (orgati) then
                                a = z(i)*z(i) + dtipsq*dtipsq*(dpsi + dphi)
                             else
                                a = z(ip1)*z(ip1) + dtisq*dtisq*(dpsi + dphi)
                             end if
                          else
                             a = dtisq*dtisq*dpsi + dtipsq*dtipsq*dphi
                          end if
                       end if
                       eta = b/a
                    else if (a <= zero) then
                       eta = (a - sqrt(abs(a*a - four*b*c)))/(two*c)
                    else
                       eta = two*b/(a + sqrt(abs(a*a - four*b*c)))
                    end if
                 else
                    ! interpolation using three most relevant poles
                    dtiim = work(iim1)*delta(iim1)
                    dtiip = work(iip1)*delta(iip1)
                    temp = rhoinv + psi + phi
                    if (swtch) then
                       c = temp - dtiim*dpsi - dtiip*dphi
                       zz(1) = dtiim*dtiim*dpsi
                       zz(3) = dtiip*dtiip*dphi
                    else
                       if (orgati) then
                          temp1 = z(iim1)/dtiim
                          temp1 = temp1*temp1
                          temp2 = (d(iim1) - d(iip1))*(d(iim1) + d(iip1))*temp1
                          c = temp - dtiip*(dpsi + dphi) - temp2
                          zz(1) = z(iim1)*z(iim1)
                          if (dpsi < temp1) then
                             zz(3) = dtiip*dtiip*dphi
                          else
                             zz(3) = dtiip*dtiip*((dpsi - temp1) + dphi)
                          end if
                       else
                          temp1 = z(iip1)/dtiip
                          temp1 = temp1*temp1
                          temp2 = (d(iip1) - d(iim1))*(d(iim1) + d(iip1))*temp1
                          c = temp - dtiim*(dpsi + dphi) - temp2
                          if (dphi < temp1) then
                             zz(1) = dtiim*dtiim*dpsi
                          else
                             zz(1) = dtiim*dtiim*(dpsi + (dphi - temp1))
                          end if
                          zz(3) = z(iip1)*z(iip1)
                       end if
                    end if
                    dd(1) = dtiim
                    dd(2) = delta(ii)*work(ii)
                    dd(3) = dtiip
                    call la_qlaed6(niter,orgati,c,dd,zz,w,eta,info)
                    if (info /= 0) then
                       ! if info is not 0, i.e., la_qlaed6 failed, switch
                       ! back to two pole interpolation
                       swtch3 = .false.
                       info = 0
                       dtipsq = work(ip1)*delta(ip1)
                       dtisq = work(i)*delta(i)
                       if (.not. swtch) then
                          if (orgati) then
                             c = w - dtipsq*dw + delsq*(z(i)/dtisq)**2
                          else
                             c = w - dtisq*dw - delsq*(z(ip1)/dtipsq)**2
                          end if
                       else
                          temp = z(ii)/(work(ii)*delta(ii))
                          if (orgati) then
                             dpsi = dpsi + temp*temp
                          else
                             dphi = dphi + temp*temp
                          end if
                          c = w - dtisq*dpsi - dtipsq*dphi
                       end if
                       a = (dtipsq + dtisq)*w - dtipsq*dtisq*dw
                       b = dtipsq*dtisq*w
                       if (c == zero) then
                          if (a == zero) then
                             if (.not. swtch) then
                                if (orgati) then
                                   a = z(i)*z(i) + dtipsq*dtipsq*(dpsi + dphi)
                                else
                                   a = z(ip1)*z(ip1) + dtisq*dtisq*(dpsi + dphi)
                                end if
                             else
                                a = dtisq*dtisq*dpsi + dtipsq*dtipsq*dphi
                             end if
                          end if
                          eta = b/a
                       else if (a <= zero) then
                          eta = (a - sqrt(abs(a*a - four*b*c)))/(two*c)
                       else
                          eta = two*b/(a + sqrt(abs(a*a - four*b*c)))
                       end if
                    end if
                 end if
                 ! note, eta should be positive if w is negative, and
                 ! eta should be negative otherwise. however,
                 ! if for some reason caused by roundoff, eta*w > 0,
                 ! we simply use one newton step instead. this way
                 ! will guarantee eta*w < 0.
                 if (w*eta >= zero) eta = -w/dw
                 eta = eta/(sigma + sqrt(sigma*sigma + eta))
                 temp = tau + eta
                 if (temp > sgub .or. temp < sglb) then
                    if (w < zero) then
                       eta = (sgub - tau)/two
                    else
                       eta = (sglb - tau)/two
                    end if
                    if (geomavg) then
                       if (w < zero) then
                          if (tau > zero) then
                             eta = sqrt(sgub*tau) - tau
                          end if
                       else
                          if (sglb > zero) then
                             eta = sqrt(sglb*tau) - tau
                          end if
                       end if
                    end if
                 end if
                 prew = w
                 tau = tau + eta
                 sigma = sigma + eta
                 do j = 1,n
                    work(j) = work(j) + eta
                    delta(j) = delta(j) - eta
                 end do
                 ! evaluate psi and the derivative dpsi
                 dpsi = zero
                 psi = zero
                 erretm = zero
                 do j = 1,iim1
                    temp = z(j)/(work(j)*delta(j))
                    psi = psi + z(j)*temp
                    dpsi = dpsi + temp*temp
                    erretm = erretm + psi
                 end do
                 erretm = abs(erretm)
                 ! evaluate phi and the derivative dphi
                 dphi = zero
                 phi = zero
                 do j = n,iip1,-1
                    temp = z(j)/(work(j)*delta(j))
                    phi = phi + z(j)*temp
                    dphi = dphi + temp*temp
                    erretm = erretm + phi
                 end do
                 tau2 = work(ii)*delta(ii)
                 temp = z(ii)/tau2
                 dw = dpsi + dphi + temp*temp
                 temp = z(ii)*temp
                 w = rhoinv + phi + psi + temp
                 erretm = eight*(phi - psi) + erretm + two*rhoinv + three*abs(temp)
          ! $             + abs( tau2 )*dw
                 if (w*prew > zero .and. abs(w) > abs(prew)/ten) swtch = .not. swtch
              end do loop_230
              ! return with info = 1, niter = maxit and not converged
              info = 1
           end if
           240 continue
           return
     end subroutine la_qlasd4

     !> This subroutine computes the square root of the I-th eigenvalue
     !> of a positive symmetric rank-one modification of a 2-by-2 diagonal
     !> matrix
     !> diag( D ) * diag( D ) +  RHO * Z * transpose(Z) .
     !> The diagonal entries in the array D are assumed to satisfy
     !> 0 <= D(i) < D(j)  for  i < j .
     !> We also assume RHO > 0 and that the Euclidean norm of the vector
     !> Z is one.

     pure subroutine la_qlasd5(i,d,z,delta,rho,dsigma,work)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: i
           real(qp),intent(out) :: dsigma
           real(qp),intent(in) :: rho
           ! Array Arguments
           real(qp),intent(in) :: d(2),z(2)
           real(qp),intent(out) :: delta(2),work(2)
        ! =====================================================================

           ! Local Scalars
           real(qp) :: b,c,del,delsq,tau,w
           ! Intrinsic Functions
           intrinsic :: abs,sqrt
           ! Executable Statements
           del = d(2) - d(1)
           delsq = del*(d(2) + d(1))
           if (i == 1) then
              w = one + four*rho*(z(2)*z(2)/(d(1) + three*d(2)) - z(1)*z(1)/( &
                        three*d(1) + d(2)))/del
              if (w > zero) then
                 b = delsq + rho*(z(1)*z(1) + z(2)*z(2))
                 c = rho*z(1)*z(1)*delsq
                 ! b > zero, always
                 ! the following tau is dsigma * dsigma - d( 1 ) * d( 1 )
                 tau = two*c/(b + sqrt(abs(b*b - four*c)))
                 ! the following tau is dsigma - d( 1 )
                 tau = tau/(d(1) + sqrt(d(1)*d(1) + tau))
                 dsigma = d(1) + tau
                 delta(1) = -tau
                 delta(2) = del - tau
                 work(1) = two*d(1) + tau
                 work(2) = (d(1) + tau) + d(2)
                 ! delta( 1 ) = -z( 1 ) / tau
                 ! delta( 2 ) = z( 2 ) / ( del-tau )
              else
                 b = -delsq + rho*(z(1)*z(1) + z(2)*z(2))
                 c = rho*z(2)*z(2)*delsq
                 ! the following tau is dsigma * dsigma - d( 2 ) * d( 2 )
                 if (b > zero) then
                    tau = -two*c/(b + sqrt(b*b + four*c))
                 else
                    tau = (b - sqrt(b*b + four*c))/two
                 end if
                 ! the following tau is dsigma - d( 2 )
                 tau = tau/(d(2) + sqrt(abs(d(2)*d(2) + tau)))
                 dsigma = d(2) + tau
                 delta(1) = -(del + tau)
                 delta(2) = -tau
                 work(1) = d(1) + tau + d(2)
                 work(2) = two*d(2) + tau
                 ! delta( 1 ) = -z( 1 ) / ( del+tau )
                 ! delta( 2 ) = -z( 2 ) / tau
              end if
              ! temp = sqrt( delta( 1 )*delta( 1 )+delta( 2 )*delta( 2 ) )
              ! delta( 1 ) = delta( 1 ) / temp
              ! delta( 2 ) = delta( 2 ) / temp
           else
              ! now i=2
              b = -delsq + rho*(z(1)*z(1) + z(2)*z(2))
              c = rho*z(2)*z(2)*delsq
              ! the following tau is dsigma * dsigma - d( 2 ) * d( 2 )
              if (b > zero) then
                 tau = (b + sqrt(b*b + four*c))/two
              else
                 tau = two*c/(-b + sqrt(b*b + four*c))
              end if
              ! the following tau is dsigma - d( 2 )
              tau = tau/(d(2) + sqrt(d(2)*d(2) + tau))
              dsigma = d(2) + tau
              delta(1) = -(del + tau)
              delta(2) = -tau
              work(1) = d(1) + tau + d(2)
              work(2) = two*d(2) + tau
              ! delta( 1 ) = -z( 1 ) / ( del+tau )
              ! delta( 2 ) = -z( 2 ) / tau
              ! temp = sqrt( delta( 1 )*delta( 1 )+delta( 2 )*delta( 2 ) )
              ! delta( 1 ) = delta( 1 ) / temp
              ! delta( 2 ) = delta( 2 ) / temp
           end if
           return
     end subroutine la_qlasd5

     !> DLASD6: computes the SVD of an updated upper bidiagonal matrix B
     !> obtained by merging two smaller ones by appending a row. This
     !> routine is used only for the problem which requires all singular
     !> values and optionally singular vector matrices in factored form.
     !> B is an N-by-M matrix with N = NL + NR + 1 and M = N + SQRE.
     !> A related subroutine, DLASD1, handles the case in which all singular
     !> values and singular vectors of the bidiagonal matrix are desired.
     !> DLASD6 computes the SVD as follows:
     !> ( D1(in)    0    0       0 )
     !> B = U(in) * (   Z1**T   a   Z2**T    b ) * VT(in)
     !> (   0       0   D2(in)   0 )
     !> = U(out) * ( D(out) 0) * VT(out)
     !> where Z**T = (Z1**T a Z2**T b) = u**T VT**T, and u is a vector of dimension M
     !> with ALPHA and BETA in the NL+1 and NL+2 th entries and zeros
     !> elsewhere; and the entry b is empty if SQRE = 0.
     !> The singular values of B can be computed using D1, D2, the first
     !> components of all the right singular vectors of the lower block, and
     !> the last components of all the right singular vectors of the upper
     !> block. These components are stored and updated in VF and VL,
     !> respectively, in DLASD6. Hence U and VT are not explicitly
     !> referenced.
     !> The singular values are stored in D. The algorithm consists of two
     !> stages:
     !> The first stage consists of deflating the size of the problem
     !> when there are multiple singular values or if there is a zero
     !> in the Z vector. For each such occurrence the dimension of the
     !> secular equation problem is reduced by one. This stage is
     !> performed by the routine DLASD7.
     !> The second stage consists of calculating the updated
     !> singular values. This is done by finding the roots of the
     !> secular equation via the routine DLASD4 (as called by DLASD8).
     !> This routine also updates VF and VL and computes the distances
     !> between the updated singular values and the old singular
     !> values.
     !> DLASD6 is called from DLASDA.

     pure subroutine la_qlasd6(icompq,nl,nr,sqre,d,vf,vl,alpha,beta,idxq,perm, &
     givptr,givcol,ldgcol,givnum,ldgnum,poles,difl,difr,z,k,c,s,work,iwork,info)

        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: givptr,info,k
           integer(ilp),intent(in) :: icompq,ldgcol,ldgnum,nl,nr,sqre
           real(qp),intent(inout) :: alpha,beta
           real(qp),intent(out) :: c,s
           ! Array Arguments
           integer(ilp),intent(out) :: givcol(ldgcol,*),iwork(*),perm(*)
           integer(ilp),intent(inout) :: idxq(*)
           real(qp),intent(inout) :: d(*),vf(*),vl(*)
           real(qp),intent(out) :: difl(*),difr(*),givnum(ldgnum,*),poles(ldgnum,*),work(*), &
                     z(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,idx,idxc,idxp,isigma,ivfw,ivlw,iw,m,n,n1,n2
           real(qp) :: orgnrm
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           n = nl + nr + 1
           m = n + sqre
           if ((icompq < 0) .or. (icompq > 1)) then
              info = -1
           else if (nl < 1) then
              info = -2
           else if (nr < 1) then
              info = -3
           else if ((sqre < 0) .or. (sqre > 1)) then
              info = -4
           else if (ldgcol < n) then
              info = -14
           else if (ldgnum < n) then
              info = -16
           end if
           if (info /= 0) then
              call la_xerbla('DLASD6',-info)
              return
           end if
           ! the following values are for bookkeeping purposes only.  they are
           ! integer pointers which indicate the portion of the workspace
           ! used by a particular array in la_qlasd7 and la_qlasd8.
           isigma = 1
           iw = isigma + n
           ivfw = iw + m
           ivlw = ivfw + m
           idx = 1
           idxc = idx + n
           idxp = idxc + n
           ! scale.
           orgnrm = max(abs(alpha),abs(beta))
           d(nl + 1) = zero
           do i = 1,n
              if (abs(d(i)) > orgnrm) then
                 orgnrm = abs(d(i))
              end if
           end do
           call la_qlascl('G',0,0,orgnrm,one,n,1,d,n,info)
           alpha = alpha/orgnrm
           beta = beta/orgnrm
           ! sort and deflate singular values.
           call la_qlasd7(icompq,nl,nr,sqre,k,d,z,work(iw),vf,work(ivfw),vl, &
           work(ivlw),alpha,beta,work(isigma),iwork(idx),iwork(idxp),idxq,perm, &
                     givptr,givcol,ldgcol,givnum,ldgnum,c,s,info)
           ! solve secular equation, compute difl, difr, and update vf, vl.
           call la_qlasd8(icompq,k,d,z,vf,vl,difl,difr,ldgnum,work(isigma),work( &
                     iw),info)
           ! report the possible convergence failure.
           if (info /= 0) then
              return
           end if
           ! save the poles if icompq = 1.
           if (icompq == 1) then
              call la_qcopy(k,d,1,poles(1,1),1)
              call la_qcopy(k,work(isigma),1,poles(1,2),1)
           end if
           ! unscale.
           call la_qlascl('G',0,0,one,orgnrm,n,1,d,n,info)
           ! prepare the idxq sorting permutation.
           n1 = k
           n2 = n - k
           call la_qlamrg(n1,n2,d,1,-1,idxq)
           return
     end subroutine la_qlasd6

     !> DLASD7: merges the two sets of singular values together into a single
     !> sorted set. Then it tries to deflate the size of the problem. There
     !> are two ways in which deflation can occur:  when two or more singular
     !> values are close together or if there is a tiny entry in the Z
     !> vector. For each such occurrence the order of the related
     !> secular equation problem is reduced by one.
     !> DLASD7 is called from DLASD6.

     pure subroutine la_qlasd7(icompq,nl,nr,sqre,k,d,z,zw,vf,vfw,vl,vlw,alpha, &
     beta,dsigma,idx,idxp,idxq,perm,givptr,givcol,ldgcol,givnum,ldgnum,c,s,info)

        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: givptr,info,k
           integer(ilp),intent(in) :: icompq,ldgcol,ldgnum,nl,nr,sqre
           real(qp),intent(in) :: alpha,beta
           real(qp),intent(out) :: c,s
           ! Array Arguments
           integer(ilp),intent(out) :: givcol(ldgcol,*),idx(*),idxp(*),perm(*)
           integer(ilp),intent(inout) :: idxq(*)
           real(qp),intent(inout) :: d(*),vf(*),vl(*)
           real(qp),intent(out) :: dsigma(*),givnum(ldgnum,*),vfw(*),vlw(*),z(*),zw(*)

        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,idxi,idxj,idxjp,j,jp,jprev,k2,m,n,nlp1,nlp2
           real(qp) :: eps,hlftol,tau,tol,z1
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           n = nl + nr + 1
           m = n + sqre
           if ((icompq < 0) .or. (icompq > 1)) then
              info = -1
           else if (nl < 1) then
              info = -2
           else if (nr < 1) then
              info = -3
           else if ((sqre < 0) .or. (sqre > 1)) then
              info = -4
           else if (ldgcol < n) then
              info = -22
           else if (ldgnum < n) then
              info = -24
           end if
           if (info /= 0) then
              call la_xerbla('DLASD7',-info)
              return
           end if
           nlp1 = nl + 1
           nlp2 = nl + 2
           if (icompq == 1) then
              givptr = 0
           end if
           ! generate the first part of the vector z and move the singular
           ! values in the first part of d one position backward.
           z1 = alpha*vl(nlp1)
           vl(nlp1) = zero
           tau = vf(nlp1)
           do i = nl,1,-1
              z(i + 1) = alpha*vl(i)
              vl(i) = zero
              vf(i + 1) = vf(i)
              d(i + 1) = d(i)
              idxq(i + 1) = idxq(i) + 1
           end do
           vf(1) = tau
           ! generate the second part of the vector z.
           do i = nlp2,m
              z(i) = beta*vf(i)
              vf(i) = zero
           end do
           ! sort the singular values into increasing order
           do i = nlp2,n
              idxq(i) = idxq(i) + nlp1
           end do
           ! dsigma, idxc, idxc, and zw are used as storage space.
           do i = 2,n
              dsigma(i) = d(idxq(i))
              zw(i) = z(idxq(i))
              vfw(i) = vf(idxq(i))
              vlw(i) = vl(idxq(i))
           end do
           call la_qlamrg(nl,nr,dsigma(2),1,1,idx(2))
           do i = 2,n
              idxi = 1 + idx(i)
              d(i) = dsigma(idxi)
              z(i) = zw(idxi)
              vf(i) = vfw(idxi)
              vl(i) = vlw(idxi)
           end do
           ! calculate the allowable deflation tolerance
           eps = la_qlamch('EPSILON')
           tol = max(abs(alpha),abs(beta))
           tol = eight*eight*eps*max(abs(d(n)),tol)
           ! there are 2 kinds of deflation -- first a value in the z-vector
           ! is small, second two (or more) singular values are very close
           ! together (their difference is small).
           ! if the value in the z-vector is small, we simply permute the
           ! array so that the corresponding singular value is moved to the
           ! end.
           ! if two values in the d-vector are close, we perform a two-sided
           ! rotation designed to make one of the corresponding z-vector
           ! entries zero, and then permute the array so that the deflated
           ! singular value is moved to the end.
           ! if there are multiple singular values then the problem deflates.
           ! here the number of equal singular values are found.  as each equal
           ! singular value is found, an elementary reflector is computed to
           ! rotate the corresponding singular subspace so that the
           ! corresponding components of z are zero in this new basis.
           k = 1
           k2 = n + 1
           do j = 2,n
              if (abs(z(j)) <= tol) then
                 ! deflate due to small z component.
                 k2 = k2 - 1
                 idxp(k2) = j
                 if (j == n) go to 100
              else
                 jprev = j
                 go to 70
              end if
           end do
           70 continue
           j = jprev
           80 continue
           j = j + 1
           if (j > n) go to 90
           if (abs(z(j)) <= tol) then
              ! deflate due to small z component.
              k2 = k2 - 1
              idxp(k2) = j
           else
              ! check if singular values are close enough to allow deflation.
              if (abs(d(j) - d(jprev)) <= tol) then
                 ! deflation is possible.
                 s = z(jprev)
                 c = z(j)
                 ! find sqrt(a**2+b**2) without overflow or
                 ! destructive underflow.
                 tau = la_qlapy2(c,s)
                 z(j) = tau
                 z(jprev) = zero
                 c = c/tau
                 s = -s/tau
                 ! record the appropriate givens rotation
                 if (icompq == 1) then
                    givptr = givptr + 1
                    idxjp = idxq(idx(jprev) + 1)
                    idxj = idxq(idx(j) + 1)
                    if (idxjp <= nlp1) then
                       idxjp = idxjp - 1
                    end if
                    if (idxj <= nlp1) then
                       idxj = idxj - 1
                    end if
                    givcol(givptr,2) = idxjp
                    givcol(givptr,1) = idxj
                    givnum(givptr,2) = c
                    givnum(givptr,1) = s
                 end if
                 call la_qrot(1,vf(jprev),1,vf(j),1,c,s)
                 call la_qrot(1,vl(jprev),1,vl(j),1,c,s)
                 k2 = k2 - 1
                 idxp(k2) = jprev
                 jprev = j
              else
                 k = k + 1
                 zw(k) = z(jprev)
                 dsigma(k) = d(jprev)
                 idxp(k) = jprev
                 jprev = j
              end if
           end if
           go to 80
           90 continue
           ! record the last singular value.
           k = k + 1
           zw(k) = z(jprev)
           dsigma(k) = d(jprev)
           idxp(k) = jprev
           100 continue
           ! sort the singular values into dsigma. the singular values which
           ! were not deflated go into the first k slots of dsigma, except
           ! that dsigma(1) is treated separately.
           do j = 2,n
              jp = idxp(j)
              dsigma(j) = d(jp)
              vfw(j) = vf(jp)
              vlw(j) = vl(jp)
           end do
           if (icompq == 1) then
              do j = 2,n
                 jp = idxp(j)
                 perm(j) = idxq(idx(jp) + 1)
                 if (perm(j) <= nlp1) then
                    perm(j) = perm(j) - 1
                 end if
              end do
           end if
           ! the deflated singular values go back into the last n - k slots of
           ! d.
           call la_qcopy(n - k,dsigma(k + 1),1,d(k + 1),1)
           ! determine dsigma(1), dsigma(2), z(1), vf(1), vl(1), vf(m), and
           ! vl(m).
           dsigma(1) = zero
           hlftol = tol/two
           if (abs(dsigma(2)) <= hlftol) dsigma(2) = hlftol
           if (m > n) then
              z(1) = la_qlapy2(z1,z(m))
              if (z(1) <= tol) then
                 c = one
                 s = zero
                 z(1) = tol
              else
                 c = z1/z(1)
                 s = -z(m)/z(1)
              end if
              call la_qrot(1,vf(m),1,vf(1),1,c,s)
              call la_qrot(1,vl(m),1,vl(1),1,c,s)
           else
              if (abs(z1) <= tol) then
                 z(1) = tol
              else
                 z(1) = z1
              end if
           end if
           ! restore z, vf, and vl.
           call la_qcopy(k - 1,zw(2),1,z(2),1)
           call la_qcopy(n - 1,vfw(2),1,vf(2),1)
           call la_qcopy(n - 1,vlw(2),1,vl(2),1)
           return
     end subroutine la_qlasd7

     !> DLASD8: finds the square roots of the roots of the secular equation,
     !> as defined by the values in DSIGMA and Z. It makes the appropriate
     !> calls to DLASD4, and stores, for each  element in D, the distance
     !> to its two nearest poles (elements in DSIGMA). It also updates
     !> the arrays VF and VL, the first and last components of all the
     !> right singular vectors of the original bidiagonal matrix.
     !> DLASD8 is called from DLASD6.

     pure subroutine la_qlasd8(icompq,k,d,z,vf,vl,difl,difr,lddifr,dsigma,work, &
               info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: icompq,k,lddifr
           integer(ilp),intent(out) :: info
           ! Array Arguments
           real(qp),intent(out) :: d(*),difl(*),difr(lddifr,*),work(*)
           real(qp),intent(inout) :: dsigma(*),vf(*),vl(*),z(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,iwk1,iwk2,iwk2i,iwk3,iwk3i,j
           real(qp) :: diflj,difrj,dj,dsigj,dsigjp,rho,temp
           ! Intrinsic Functions
           intrinsic :: abs,sign,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if ((icompq < 0) .or. (icompq > 1)) then
              info = -1
           else if (k < 1) then
              info = -2
           else if (lddifr < k) then
              info = -9
           end if
           if (info /= 0) then
              call la_xerbla('DLASD8',-info)
              return
           end if
           ! quick return if possible
           if (k == 1) then
              d(1) = abs(z(1))
              difl(1) = d(1)
              if (icompq == 1) then
                 difl(2) = one
                 difr(1,2) = one
              end if
              return
           end if
           ! modify values dsigma(i) to make sure all dsigma(i)-dsigma(j) can
           ! be computed with high relative accuracy (barring over/underflow).
           ! this is a problem on machines without a guard digit in
           ! add/subtract (cray xmp, cray ymp, cray c 90 and cray 2).
           ! the following code replaces dsigma(i) by 2*dsigma(i)-dsigma(i),
           ! which on any of these machines zeros out the bottommost
           ! bit of dsigma(i) if it is 1; this makes the subsequent
           ! subtractions dsigma(i)-dsigma(j) unproblematic when cancellation
           ! occurs. on binary machines with a guard digit (almost all
           ! machines) it does not change dsigma(i) at all. on hexadecimal
           ! and decimal machines with a guard digit, it slightly
           ! changes the bottommost bits of dsigma(i). it does not account
           ! for hexadecimal or decimal machines without guard digits
           ! (we know of none). we use a subroutine call to compute
           ! 2*dlambda(i) to prevent optimizing compilers from eliminating
           ! this code.
           do i = 1,k
              dsigma(i) = la_qlamc3(dsigma(i),dsigma(i)) - dsigma(i)
           end do
           ! book keeping.
           iwk1 = 1
           iwk2 = iwk1 + k
           iwk3 = iwk2 + k
           iwk2i = iwk2 - 1
           iwk3i = iwk3 - 1
           ! normalize z.
           rho = la_qnrm2(k,z,1)
           call la_qlascl('G',0,0,rho,one,k,1,z,k,info)
           rho = rho*rho
           ! initialize work(iwk3).
           call la_qlaset('A',k,1,one,one,work(iwk3),k)
           ! compute the updated singular values, the arrays difl, difr,
           ! and the updated z.
           do j = 1,k
              call la_qlasd4(k,j,dsigma,z,work(iwk1),rho,d(j),work(iwk2),info)

              ! if the root finder fails, report the convergence failure.
              if (info /= 0) then
                 return
              end if
              work(iwk3i + j) = work(iwk3i + j)*work(j)*work(iwk2i + j)
              difl(j) = -work(j)
              difr(j,1) = -work(j + 1)
              do i = 1,j - 1
                 work(iwk3i + i) = work(iwk3i + i)*work(i)*work(iwk2i + i)/(dsigma(i) - &
                           dsigma(j))/(dsigma(i) + dsigma(j))
              end do
              do i = j + 1,k
                 work(iwk3i + i) = work(iwk3i + i)*work(i)*work(iwk2i + i)/(dsigma(i) - &
                           dsigma(j))/(dsigma(i) + dsigma(j))
              end do
           end do
           ! compute updated z.
           do i = 1,k
              z(i) = sign(sqrt(abs(work(iwk3i + i))),z(i))
           end do
           ! update vf and vl.
           do j = 1,k
              diflj = difl(j)
              dj = d(j)
              dsigj = -dsigma(j)
              if (j < k) then
                 difrj = -difr(j,1)
                 dsigjp = -dsigma(j + 1)
              end if
              work(j) = -z(j)/diflj/(dsigma(j) + dj)
              do i = 1,j - 1
                 work(i) = z(i)/(la_qlamc3(dsigma(i),dsigj) - diflj)/(dsigma(i) &
                           + dj)
              end do
              do i = j + 1,k
                 work(i) = z(i)/(la_qlamc3(dsigma(i),dsigjp) + difrj)/(dsigma(i &
                           ) + dj)
              end do
              temp = la_qnrm2(k,work,1)
              work(iwk2i + j) = la_qdot(k,work,1,vf,1)/temp
              work(iwk3i + j) = la_qdot(k,work,1,vl,1)/temp
              if (icompq == 1) then
                 difr(j,2) = temp
              end if
           end do
           call la_qcopy(k,work(iwk2),1,vf,1)
           call la_qcopy(k,work(iwk3),1,vl,1)
           return
     end subroutine la_qlasd8

     !> Using a divide and conquer approach, DLASDA: computes the singular
     !> value decomposition (SVD) of a real upper bidiagonal N-by-M matrix
     !> B with diagonal D and offdiagonal E, where M = N + SQRE. The
     !> algorithm computes the singular values in the SVD B = U * S * VT.
     !> The orthogonal matrices U and VT are optionally computed in
     !> compact form.
     !> A related subroutine, DLASD0, computes the singular values and
     !> the singular vectors in explicit form.

     pure subroutine la_qlasda(icompq,smlsiz,n,sqre,d,e,u,ldu,vt,k,difl,difr,z, &
               poles,givptr,givcol,ldgcol,perm,givnum,c,s,work,iwork,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: icompq,ldgcol,ldu,n,smlsiz,sqre
           integer(ilp),intent(out) :: info
           ! Array Arguments
           integer(ilp),intent(out) :: givcol(ldgcol,*),givptr(*),iwork(*),k(*),perm(ldgcol, &
                     *)
           real(qp),intent(out) :: c(*),difl(ldu,*),difr(ldu,*),givnum(ldu,*),poles(ldu,*), &
                     s(*),u(ldu,*),vt(ldu,*),work(*),z(ldu,*)
           real(qp),intent(inout) :: d(*),e(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,i1,ic,idxq,idxqi,im1,inode,itemp,iwk,j,lf,ll,lvl,lvl2, &
           m,ncc,nd,ndb1,ndiml,ndimr,nl,nlf,nlp1,nlvl,nr,nrf,nrp1,nru,nwork1, &
                     nwork2,smlszp,sqrei,vf,vfi,vl,vli
           real(qp) :: alpha,beta
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if ((icompq < 0) .or. (icompq > 1)) then
              info = -1
           else if (smlsiz < 3) then
              info = -2
           else if (n < 0) then
              info = -3
           else if ((sqre < 0) .or. (sqre > 1)) then
              info = -4
           else if (ldu < (n + sqre)) then
              info = -8
           else if (ldgcol < n) then
              info = -17
           end if
           if (info /= 0) then
              call la_xerbla('DLASDA',-info)
              return
           end if
           m = n + sqre
           ! if the input matrix is too small, call la_qlasdq to find the svd.
           if (n <= smlsiz) then
              if (icompq == 0) then
                 call la_qlasdq('U',sqre,n,0,0,0,d,e,vt,ldu,u,ldu,u,ldu,work, &
                           info)
              else
                 call la_qlasdq('U',sqre,n,m,n,0,d,e,vt,ldu,u,ldu,u,ldu,work, &
                           info)
              end if
              return
           end if
           ! book-keeping and  set up the computation tree.
           inode = 1
           ndiml = inode + n
           ndimr = ndiml + n
           idxq = ndimr + n
           iwk = idxq + n
           ncc = 0
           nru = 0
           smlszp = smlsiz + 1
           vf = 1
           vl = vf + m
           nwork1 = vl + m
           nwork2 = nwork1 + smlszp*smlszp
           call la_qlasdt(n,nlvl,nd,iwork(inode),iwork(ndiml),iwork(ndimr),smlsiz &
                     )
           ! for the nodes on bottom level of the tree, solve
           ! their subproblems by la_qlasdq.
           ndb1 = (nd + 1)/2
           loop_30: do i = ndb1,nd
              ! ic : center row of each node
              ! nl : number of rows of left  subproblem
              ! nr : number of rows of right subproblem
              ! nlf: starting row of the left   subproblem
              ! nrf: starting row of the right  subproblem
              i1 = i - 1
              ic = iwork(inode + i1)
              nl = iwork(ndiml + i1)
              nlp1 = nl + 1
              nr = iwork(ndimr + i1)
              nlf = ic - nl
              nrf = ic + 1
              idxqi = idxq + nlf - 2
              vfi = vf + nlf - 1
              vli = vl + nlf - 1
              sqrei = 1
              if (icompq == 0) then
                 call la_qlaset('A',nlp1,nlp1,zero,one,work(nwork1),smlszp)
                 call la_qlasdq('U',sqrei,nl,nlp1,nru,ncc,d(nlf),e(nlf),work( &
                 nwork1),smlszp,work(nwork2),nl,work(nwork2),nl,work(nwork2),info)

                 itemp = nwork1 + nl*smlszp
                 call la_qcopy(nlp1,work(nwork1),1,work(vfi),1)
                 call la_qcopy(nlp1,work(itemp),1,work(vli),1)
              else
                 call la_qlaset('A',nl,nl,zero,one,u(nlf,1),ldu)
                 call la_qlaset('A',nlp1,nlp1,zero,one,vt(nlf,1),ldu)
                 call la_qlasdq('U',sqrei,nl,nlp1,nl,ncc,d(nlf),e(nlf),vt(nlf,1 &
                           ),ldu,u(nlf,1),ldu,u(nlf,1),ldu,work(nwork1),info)
                 call la_qcopy(nlp1,vt(nlf,1),1,work(vfi),1)
                 call la_qcopy(nlp1,vt(nlf,nlp1),1,work(vli),1)
              end if
              if (info /= 0) then
                 return
              end if
              do j = 1,nl
                 iwork(idxqi + j) = j
              end do
              if ((i == nd) .and. (sqre == 0)) then
                 sqrei = 0
              else
                 sqrei = 1
              end if
              idxqi = idxqi + nlp1
              vfi = vfi + nlp1
              vli = vli + nlp1
              nrp1 = nr + sqrei
              if (icompq == 0) then
                 call la_qlaset('A',nrp1,nrp1,zero,one,work(nwork1),smlszp)
                 call la_qlasdq('U',sqrei,nr,nrp1,nru,ncc,d(nrf),e(nrf),work( &
                 nwork1),smlszp,work(nwork2),nr,work(nwork2),nr,work(nwork2),info)

                 itemp = nwork1 + (nrp1 - 1)*smlszp
                 call la_qcopy(nrp1,work(nwork1),1,work(vfi),1)
                 call la_qcopy(nrp1,work(itemp),1,work(vli),1)
              else
                 call la_qlaset('A',nr,nr,zero,one,u(nrf,1),ldu)
                 call la_qlaset('A',nrp1,nrp1,zero,one,vt(nrf,1),ldu)
                 call la_qlasdq('U',sqrei,nr,nrp1,nr,ncc,d(nrf),e(nrf),vt(nrf,1 &
                           ),ldu,u(nrf,1),ldu,u(nrf,1),ldu,work(nwork1),info)
                 call la_qcopy(nrp1,vt(nrf,1),1,work(vfi),1)
                 call la_qcopy(nrp1,vt(nrf,nrp1),1,work(vli),1)
              end if
              if (info /= 0) then
                 return
              end if
              do j = 1,nr
                 iwork(idxqi + j) = j
              end do
           end do loop_30
           ! now conquer each subproblem bottom-up.
           j = 2**nlvl
           loop_50: do lvl = nlvl,1,-1
              lvl2 = lvl*2 - 1
              ! find the first node lf and last node ll on
              ! the current level lvl.
              if (lvl == 1) then
                 lf = 1
                 ll = 1
              else
                 lf = 2**(lvl - 1)
                 ll = 2*lf - 1
              end if
              loop_40: do i = lf,ll
                 im1 = i - 1
                 ic = iwork(inode + im1)
                 nl = iwork(ndiml + im1)
                 nr = iwork(ndimr + im1)
                 nlf = ic - nl
                 nrf = ic + 1
                 if (i == ll) then
                    sqrei = sqre
                 else
                    sqrei = 1
                 end if
                 vfi = vf + nlf - 1
                 vli = vl + nlf - 1
                 idxqi = idxq + nlf - 1
                 alpha = d(ic)
                 beta = e(ic)
                 if (icompq == 0) then
                    call la_qlasd6(icompq,nl,nr,sqrei,d(nlf),work(vfi),work(vli), &
                    alpha,beta,iwork(idxqi),perm,givptr(1),givcol,ldgcol,givnum,ldu, &
                    poles,difl,difr,z,k(1),c(1),s(1),work(nwork1),iwork(iwk), &
                              info)
                 else
                    j = j - 1
                    call la_qlasd6(icompq,nl,nr,sqrei,d(nlf),work(vfi),work(vli), &
                    alpha,beta,iwork(idxqi),perm(nlf,lvl),givptr(j),givcol(nlf,lvl2), &
                     ldgcol,givnum(nlf,lvl2),ldu,poles(nlf,lvl2),difl(nlf,lvl),difr( &
                     nlf,lvl2),z(nlf,lvl),k(j),c(j),s(j),work(nwork1),iwork(iwk &
                               ),info)
                 end if
                 if (info /= 0) then
                    return
                 end if
              end do loop_40
           end do loop_50
           return
     end subroutine la_qlasda

     !> DLASDQ: computes the singular value decomposition (SVD) of a real
     !> (upper or lower) bidiagonal matrix with diagonal D and offdiagonal
     !> E, accumulating the transformations if desired. Letting B denote
     !> the input bidiagonal matrix, the algorithm computes orthogonal
     !> matrices Q and P such that B = Q * S * P**T (P**T denotes the transpose
     !> of P). The singular values S are overwritten on D.
     !> The input matrix U  is changed to U  * Q  if desired.
     !> The input matrix VT is changed to P**T * VT if desired.
     !> The input matrix C  is changed to Q**T * C  if desired.
     !> See "Computing  Small Singular Values of Bidiagonal Matrices With
     !> Guaranteed High Relative Accuracy," by J. Demmel and W. Kahan,
     !> LAPACK Working Note #3, for a detailed description of the algorithm.

     pure subroutine la_qlasdq(uplo,sqre,n,ncvt,nru,ncc,d,e,vt,ldvt,u,ldu,c,ldc, &
               work,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldc,ldu,ldvt,n,ncc,ncvt,nru,sqre
           ! Array Arguments
           real(qp),intent(inout) :: c(ldc,*),d(*),e(*),u(ldu,*),vt(ldvt,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: rotate
           integer(ilp) :: i,isub,iuplo,j,np1,sqre1
           real(qp) :: cs,r,smin,sn
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           iuplo = 0
           if (la_lsame(uplo,'U')) iuplo = 1
           if (la_lsame(uplo,'L')) iuplo = 2
           if (iuplo == 0) then
              info = -1
           else if ((sqre < 0) .or. (sqre > 1)) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ncvt < 0) then
              info = -4
           else if (nru < 0) then
              info = -5
           else if (ncc < 0) then
              info = -6
           else if ((ncvt == 0 .and. ldvt < 1) .or. (ncvt > 0 .and. ldvt < max(1,n))) then
              info = -10
           else if (ldu < max(1,nru)) then
              info = -12
           else if ((ncc == 0 .and. ldc < 1) .or. (ncc > 0 .and. ldc < max(1,n))) then
              info = -14
           end if
           if (info /= 0) then
              call la_xerbla('DLASDQ',-info)
              return
           end if
           if (n == 0) return
           ! rotate is true if any singular vectors desired, false otherwise
           rotate = (ncvt > 0) .or. (nru > 0) .or. (ncc > 0)
           np1 = n + 1
           sqre1 = sqre
           ! if matrix non-square upper bidiagonal, rotate to be lower
           ! bidiagonal.  the rotations are on the right.
           if ((iuplo == 1) .and. (sqre1 == 1)) then
              do i = 1,n - 1
                 call la_qlartg(d(i),e(i),cs,sn,r)
                 d(i) = r
                 e(i) = sn*d(i + 1)
                 d(i + 1) = cs*d(i + 1)
                 if (rotate) then
                    work(i) = cs
                    work(n + i) = sn
                 end if
              end do
              call la_qlartg(d(n),e(n),cs,sn,r)
              d(n) = r
              e(n) = zero
              if (rotate) then
                 work(n) = cs
                 work(n + n) = sn
              end if
              iuplo = 2
              sqre1 = 0
              ! update singular vectors if desired.
              if (ncvt > 0) call la_qlasr('L','V','F',np1,ncvt,work(1),work(np1),vt, &
                        ldvt)
           end if
           ! if matrix lower bidiagonal, rotate to be upper bidiagonal
           ! by applying givens rotations on the left.
           if (iuplo == 2) then
              do i = 1,n - 1
                 call la_qlartg(d(i),e(i),cs,sn,r)
                 d(i) = r
                 e(i) = sn*d(i + 1)
                 d(i + 1) = cs*d(i + 1)
                 if (rotate) then
                    work(i) = cs
                    work(n + i) = sn
                 end if
              end do
              ! if matrix (n+1)-by-n lower bidiagonal, one additional
              ! rotation is needed.
              if (sqre1 == 1) then
                 call la_qlartg(d(n),e(n),cs,sn,r)
                 d(n) = r
                 if (rotate) then
                    work(n) = cs
                    work(n + n) = sn
                 end if
              end if
              ! update singular vectors if desired.
              if (nru > 0) then
                 if (sqre1 == 0) then
                    call la_qlasr('R','V','F',nru,n,work(1),work(np1),u,ldu)

                 else
                    call la_qlasr('R','V','F',nru,np1,work(1),work(np1),u,ldu)

                 end if
              end if
              if (ncc > 0) then
                 if (sqre1 == 0) then
                    call la_qlasr('L','V','F',n,ncc,work(1),work(np1),c,ldc)

                 else
                    call la_qlasr('L','V','F',np1,ncc,work(1),work(np1),c,ldc)

                 end if
              end if
           end if
           ! call la_qbdsqr to compute the svd of the reduced real
           ! n-by-n upper bidiagonal matrix.
           call la_qbdsqr('U',n,ncvt,nru,ncc,d,e,vt,ldvt,u,ldu,c,ldc,work,info)

           ! sort the singular values into ascending order (insertion sort on
           ! singular values, but only one transposition per singular vector)
           do i = 1,n
              ! scan for smallest d(i).
              isub = i
              smin = d(i)
              do j = i + 1,n
                 if (d(j) < smin) then
                    isub = j
                    smin = d(j)
                 end if
              end do
              if (isub /= i) then
                 ! swap singular values and vectors.
                 d(isub) = d(i)
                 d(i) = smin
                 if (ncvt > 0) call la_qswap(ncvt,vt(isub,1),ldvt,vt(i,1),ldvt)

                 if (nru > 0) call la_qswap(nru,u(1,isub),1,u(1,i),1)
                 if (ncc > 0) call la_qswap(ncc,c(isub,1),ldc,c(i,1),ldc)
              end if
           end do
           return
     end subroutine la_qlasdq

     !> DLASDT: creates a tree of subproblems for bidiagonal divide and
     !> conquer.

     pure subroutine la_qlasdt(n,lvl,nd,inode,ndiml,ndimr,msub)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: lvl,nd
           integer(ilp),intent(in) :: msub,n
           ! Array Arguments
           integer(ilp),intent(out) :: inode(*),ndiml(*),ndimr(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,il,ir,llst,maxn,ncrnt,nlvl
           real(qp) :: temp
           ! Intrinsic Functions
           intrinsic :: real,int,log,max
           ! Executable Statements
           ! find the number of levels on the tree.
           maxn = max(1,n)
           temp = log(real(maxn,KIND=qp)/real(msub + 1,KIND=qp))/log(two)
           lvl = int(temp,KIND=ilp) + 1
           i = n/2
           inode(1) = i + 1
           ndiml(1) = i
           ndimr(1) = n - i - 1
           il = 0
           ir = 1
           llst = 1
           do nlvl = 1,lvl - 1
              ! constructing the tree at (nlvl+1)-st level. the number of
              ! nodes created on this level is llst * 2.
              do i = 0,llst - 1
                 il = il + 2
                 ir = ir + 2
                 ncrnt = llst + i
                 ndiml(il) = ndiml(ncrnt)/2
                 ndimr(il) = ndiml(ncrnt) - ndiml(il) - 1
                 inode(il) = inode(ncrnt) - ndimr(il) - 1
                 ndiml(ir) = ndimr(ncrnt)/2
                 ndimr(ir) = ndimr(ncrnt) - ndiml(ir) - 1
                 inode(ir) = inode(ncrnt) + ndiml(ir) + 1
              end do
              llst = llst*2
           end do
           nd = llst*2 - 1
           return
     end subroutine la_qlasdt

     !> DLATRD: reduces NB rows and columns of a real symmetric matrix A to
     !> symmetric tridiagonal form by an orthogonal similarity
     !> transformation Q**T * A * Q, and returns the matrices V and W which are
     !> needed to apply the transformation to the unreduced part of A.
     !> If UPLO = 'U', DLATRD reduces the last NB rows and columns of a
     !> matrix, of which the upper triangle is supplied;
     !> if UPLO = 'L', DLATRD reduces the first NB rows and columns of a
     !> matrix, of which the lower triangle is supplied.
     !> This is an auxiliary routine called by DSYTRD.

     pure subroutine la_qlatrd(uplo,n,nb,a,lda,e,tau,w,ldw)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(in) :: lda,ldw,n,nb
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: e(*),tau(*),w(ldw,*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,iw
           real(qp) :: alpha
           ! Intrinsic Functions
           intrinsic :: min
           ! Executable Statements
           ! quick return if possible
           if (n <= 0) return
           if (la_lsame(uplo,'U')) then
              ! reduce last nb columns of upper triangle
              loop_10: do i = n,n - nb + 1,-1
                 iw = i - n + nb
                 if (i < n) then
                    ! update a(1:i,i)
                    call la_qgemv('NO TRANSPOSE',i,n - i,-one,a(1,i + 1),lda,w(i,iw + 1) &
                              ,ldw,one,a(1,i),1)
                    call la_qgemv('NO TRANSPOSE',i,n - i,-one,w(1,iw + 1),ldw,a(i,i + 1) &
                              ,lda,one,a(1,i),1)
                 end if
                 if (i > 1) then
                    ! generate elementary reflector h(i) to annihilate
                    ! a(1:i-2,i)
                    call la_qlarfg(i - 1,a(i - 1,i),a(1,i),1,tau(i - 1))
                    e(i - 1) = a(i - 1,i)
                    a(i - 1,i) = one
                    ! compute w(1:i-1,i)
                    call la_qsymv('UPPER',i - 1,one,a,lda,a(1,i),1,zero,w(1,iw), &
                              1)
                    if (i < n) then
                       call la_qgemv('TRANSPOSE',i - 1,n - i,one,w(1,iw + 1),ldw,a(1,i), &
                                  1,zero,w(i + 1,iw),1)
                       call la_qgemv('NO TRANSPOSE',i - 1,n - i,-one,a(1,i + 1),lda,w(i + 1, &
                                  iw),1,one,w(1,iw),1)
                       call la_qgemv('TRANSPOSE',i - 1,n - i,one,a(1,i + 1),lda,a(1,i), &
                                 1,zero,w(i + 1,iw),1)
                       call la_qgemv('NO TRANSPOSE',i - 1,n - i,-one,w(1,iw + 1),ldw,w(i + &
                                 1,iw),1,one,w(1,iw),1)
                    end if
                    call la_qscal(i - 1,tau(i - 1),w(1,iw),1)
                    alpha = -half*tau(i - 1)*la_qdot(i - 1,w(1,iw),1,a(1,i),1)

                    call la_qaxpy(i - 1,alpha,a(1,i),1,w(1,iw),1)
                 end if
              end do loop_10
           else
              ! reduce first nb columns of lower triangle
              do i = 1,nb
                 ! update a(i:n,i)
                 call la_qgemv('NO TRANSPOSE',n - i + 1,i - 1,-one,a(i,1),lda,w(i,1), &
                           ldw,one,a(i,i),1)
                 call la_qgemv('NO TRANSPOSE',n - i + 1,i - 1,-one,w(i,1),ldw,a(i,1), &
                           lda,one,a(i,i),1)
                 if (i < n) then
                    ! generate elementary reflector h(i) to annihilate
                    ! a(i+2:n,i)
                    call la_qlarfg(n - i,a(i + 1,i),a(min(i + 2,n),i),1,tau(i))

                    e(i) = a(i + 1,i)
                    a(i + 1,i) = one
                    ! compute w(i+1:n,i)
                    call la_qsymv('LOWER',n - i,one,a(i + 1,i + 1),lda,a(i + 1,i),1,zero, &
                               w(i + 1,i),1)
                    call la_qgemv('TRANSPOSE',n - i,i - 1,one,w(i + 1,1),ldw,a(i + 1,i), &
                              1,zero,w(1,i),1)
                    call la_qgemv('NO TRANSPOSE',n - i,i - 1,-one,a(i + 1,1),lda,w(1,i), &
                               1,one,w(i + 1,i),1)
                    call la_qgemv('TRANSPOSE',n - i,i - 1,one,a(i + 1,1),lda,a(i + 1,i), &
                              1,zero,w(1,i),1)
                    call la_qgemv('NO TRANSPOSE',n - i,i - 1,-one,w(i + 1,1),ldw,w(1,i), &
                               1,one,w(i + 1,i),1)
                    call la_qscal(n - i,tau(i),w(i + 1,i),1)
                    alpha = -half*tau(i)*la_qdot(n - i,w(i + 1,i),1,a(i + 1,i),1)

                    call la_qaxpy(n - i,alpha,a(i + 1,i),1,w(i + 1,i),1)
                 end if
              end do
           end if
           return
     end subroutine la_qlatrd

     !> DOPGTR: generates a real orthogonal matrix Q which is defined as the
     !> product of n-1 elementary reflectors H(i) of order n, as returned by
     !> DSPTRD using packed storage:
     !> if UPLO = 'U', Q = H(n-1) . . . H(2) H(1),
     !> if UPLO = 'L', Q = H(1) H(2) . . . H(n-1).

     pure subroutine la_qopgtr(uplo,n,ap,tau,q,ldq,work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldq,n
           ! Array Arguments
           real(qp),intent(in) :: ap(*),tau(*)
           real(qp),intent(out) :: q(ldq,*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i,iinfo,ij,j
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input arguments
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (ldq < max(1,n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('DOPGTR',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (upper) then
              ! q was determined by a call to la_qsptrd with uplo = 'u'
              ! unpack the vectors which define the elementary reflectors and
              ! set the last row and column of q equal to those of the unit
              ! matrix
              ij = 2
              do j = 1,n - 1
                 do i = 1,j - 1
                    q(i,j) = ap(ij)
                    ij = ij + 1
                 end do
                 ij = ij + 2
                 q(n,j) = zero
              end do
              do i = 1,n - 1
                 q(i,n) = zero
              end do
              q(n,n) = one
              ! generate q(1:n-1,1:n-1)
              call la_qorg2l(n - 1,n - 1,n - 1,q,ldq,tau,work,iinfo)
           else
              ! q was determined by a call to la_qsptrd with uplo = 'l'.
              ! unpack the vectors which define the elementary reflectors and
              ! set the first row and column of q equal to those of the unit
              ! matrix
              q(1,1) = one
              do i = 2,n
                 q(i,1) = zero
              end do
              ij = 3
              do j = 2,n
                 q(1,j) = zero
                 do i = j + 1,n
                    q(i,j) = ap(ij)
                    ij = ij + 1
                 end do
                 ij = ij + 2
              end do
              if (n > 1) then
                 ! generate q(2:n,2:n)
                 call la_qorg2r(n - 1,n - 1,n - 1,q(2,2),ldq,tau,work,iinfo)
              end if
           end if
           return
     end subroutine la_qopgtr

     !> DOPMTR: overwrites the general real M-by-N matrix C with
     !> SIDE = 'L'     SIDE = 'R'
     !> TRANS = 'N':      Q * C          C * Q
     !> TRANS = 'T':      Q**T * C       C * Q**T
     !> where Q is a real orthogonal matrix of order nq, with nq = m if
     !> SIDE = 'L' and nq = n if SIDE = 'R'. Q is defined as the product of
     !> nq-1 elementary reflectors, as returned by DSPTRD using packed
     !> storage:
     !> if UPLO = 'U', Q = H(nq-1) . . . H(2) H(1);
     !> if UPLO = 'L', Q = H(1) H(2) . . . H(nq-1).

     pure subroutine la_qopmtr(side,uplo,trans,m,n,ap,tau,c,ldc,work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: side,trans,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldc,m,n
           ! Array Arguments
           real(qp),intent(inout) :: ap(*),c(ldc,*)
           real(qp),intent(in) :: tau(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: forwrd,left,notran,upper
           integer(ilp) :: i,i1,i2,i3,ic,ii,jc,mi,ni,nq
           real(qp) :: aii
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input arguments
           info = 0
           left = la_lsame(side,'L')
           notran = la_lsame(trans,'N')
           upper = la_lsame(uplo,'U')
           ! nq is the order of q
           if (left) then
              nq = m
           else
              nq = n
           end if
           if (.not. left .and. .not. la_lsame(side,'R')) then
              info = -1
           else if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -2
           else if (.not. notran .and. .not. la_lsame(trans,'T')) then
              info = -3
           else if (m < 0) then
              info = -4
           else if (n < 0) then
              info = -5
           else if (ldc < max(1,m)) then
              info = -9
           end if
           if (info /= 0) then
              call la_xerbla('DOPMTR',-info)
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) return
           if (upper) then
              ! q was determined by a call to la_qsptrd with uplo = 'u'
              forwrd = (left .and. notran) .or. (.not. left .and. .not. notran)
              if (forwrd) then
                 i1 = 1
                 i2 = nq - 1
                 i3 = 1
                 ii = 2
              else
                 i1 = nq - 1
                 i2 = 1
                 i3 = -1
                 ii = nq*(nq + 1)/2 - 1
              end if
              if (left) then
                 ni = n
              else
                 mi = m
              end if
              do i = i1,i2,i3
                 if (left) then
                    ! h(i) is applied to c(1:i,1:n)
                    mi = i
                 else
                    ! h(i) is applied to c(1:m,1:i)
                    ni = i
                 end if
                 ! apply h(i)
                 aii = ap(ii)
                 ap(ii) = one
                 call la_qlarf(side,mi,ni,ap(ii - i + 1),1,tau(i),c,ldc,work)
                 ap(ii) = aii
                 if (forwrd) then
                    ii = ii + i + 2
                 else
                    ii = ii - i - 1
                 end if
              end do
           else
              ! q was determined by a call to la_qsptrd with uplo = 'l'.
              forwrd = (left .and. .not. notran) .or. (.not. left .and. notran)
              if (forwrd) then
                 i1 = 1
                 i2 = nq - 1
                 i3 = 1
                 ii = 2
              else
                 i1 = nq - 1
                 i2 = 1
                 i3 = -1
                 ii = nq*(nq + 1)/2 - 1
              end if
              if (left) then
                 ni = n
                 jc = 1
              else
                 mi = m
                 ic = 1
              end if
              do i = i1,i2,i3
                 aii = ap(ii)
                 ap(ii) = one
                 if (left) then
                    ! h(i) is applied to c(i+1:m,1:n)
                    mi = m - i
                    ic = i + 1
                 else
                    ! h(i) is applied to c(1:m,i+1:n)
                    ni = n - i
                    jc = i + 1
                 end if
                 ! apply h(i)
                 call la_qlarf(side,mi,ni,ap(ii),1,tau(i),c(ic,jc),ldc,work)

                 ap(ii) = aii
                 if (forwrd) then
                    ii = ii + nq - i + 1
                 else
                    ii = ii - nq + i - 2
                 end if
              end do
           end if
           return
     end subroutine la_qopmtr

     !> DORGBR: generates one of the real orthogonal matrices Q or P**T
     !> determined by DGEBRD when reducing a real matrix A to bidiagonal
     !> form: A = Q * B * P**T.  Q and P**T are defined as products of
     !> elementary reflectors H(i) or G(i) respectively.
     !> If VECT = 'Q', A is assumed to have been an M-by-K matrix, and Q
     !> is of order M:
     !> if m >= k, Q = H(1) H(2) . . . H(k) and DORGBR returns the first n
     !> columns of Q, where m >= n >= k;
     !> if m < k, Q = H(1) H(2) . . . H(m-1) and DORGBR returns Q as an
     !> M-by-M matrix.
     !> If VECT = 'P', A is assumed to have been a K-by-N matrix, and P**T
     !> is of order N:
     !> if k < n, P**T = G(k) . . . G(2) G(1) and DORGBR returns the first m
     !> rows of P**T, where n >= m >= k;
     !> if k >= n, P**T = G(n-1) . . . G(2) G(1) and DORGBR returns P**T as
     !> an N-by-N matrix.

     pure subroutine la_qorgbr(vect,m,n,k,a,lda,tau,work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: vect
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,lda,lwork,m,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(in) :: tau(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,wantq
           integer(ilp) :: i,iinfo,j,lwkopt,mn
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           wantq = la_lsame(vect,'Q')
           mn = min(m,n)
           lquery = (lwork == -1)
           if (.not. wantq .and. .not. la_lsame(vect,'P')) then
              info = -1
           else if (m < 0) then
              info = -2
           else if (n < 0 .or. (wantq .and. (n > m .or. n < min(m,k))) .or. (.not. wantq .and. ( &
                     m > n .or. m < min(n,k)))) then
              info = -3
           else if (k < 0) then
              info = -4
           else if (lda < max(1,m)) then
              info = -6
           else if (lwork < max(1,mn) .and. .not. lquery) then
              info = -9
           end if
           if (info == 0) then
              work(1) = 1
              if (wantq) then
                 if (m >= k) then
                    call la_qorgqr(m,n,k,a,lda,tau,work,-1,iinfo)
                 else
                    if (m > 1) then
                       call la_qorgqr(m - 1,m - 1,m - 1,a,lda,tau,work,-1,iinfo)
                    end if
                 end if
              else
                 if (k < n) then
                    call la_qorglq(m,n,k,a,lda,tau,work,-1,iinfo)
                 else
                    if (n > 1) then
                       call la_qorglq(n - 1,n - 1,n - 1,a,lda,tau,work,-1,iinfo)
                    end if
                 end if
              end if
              lwkopt = work(1)
              lwkopt = max(lwkopt,mn)
           end if
           if (info /= 0) then
              call la_xerbla('DORGBR',-info)
              return
           else if (lquery) then
              work(1) = lwkopt
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) then
              work(1) = 1
              return
           end if
           if (wantq) then
              ! form q, determined by a call to la_qgebrd to reduce an m-by-k
              ! matrix
              if (m >= k) then
                 ! if m >= k, assume m >= n >= k
                 call la_qorgqr(m,n,k,a,lda,tau,work,lwork,iinfo)
              else
                 ! if m < k, assume m = n
                 ! shift the vectors which define the elementary reflectors one
                 ! column to the right, and set the first row and column of q
                 ! to those of the unit matrix
                 do j = m,2,-1
                    a(1,j) = zero
                    do i = j + 1,m
                       a(i,j) = a(i,j - 1)
                    end do
                 end do
                 a(1,1) = one
                 do i = 2,m
                    a(i,1) = zero
                 end do
                 if (m > 1) then
                    ! form q(2:m,2:m)
                    call la_qorgqr(m - 1,m - 1,m - 1,a(2,2),lda,tau,work,lwork,iinfo)

                 end if
              end if
           else
              ! form p**t, determined by a call to la_qgebrd to reduce a k-by-n
              ! matrix
              if (k < n) then
                 ! if k < n, assume k <= m <= n
                 call la_qorglq(m,n,k,a,lda,tau,work,lwork,iinfo)
              else
                 ! if k >= n, assume m = n
                 ! shift the vectors which define the elementary reflectors one
                 ! row downward, and set the first row and column of p**t to
                 ! those of the unit matrix
                 a(1,1) = one
                 do i = 2,n
                    a(i,1) = zero
                 end do
                 do j = 2,n
                    do i = j - 1,2,-1
                       a(i,j) = a(i - 1,j)
                    end do
                    a(1,j) = zero
                 end do
                 if (n > 1) then
                    ! form p**t(2:n,2:n)
                    call la_qorglq(n - 1,n - 1,n - 1,a(2,2),lda,tau,work,lwork,iinfo)

                 end if
              end if
           end if
           work(1) = lwkopt
           return
     end subroutine la_qorgbr

     !> DORGTR: generates a real orthogonal matrix Q which is defined as the
     !> product of n-1 elementary reflectors of order N, as returned by
     !> DSYTRD:
     !> if UPLO = 'U', Q = H(n-1) . . . H(2) H(1),
     !> if UPLO = 'L', Q = H(1) H(2) . . . H(n-1).

     pure subroutine la_qorgtr(uplo,n,a,lda,tau,work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,lwork,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(in) :: tau(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,upper
           integer(ilp) :: i,iinfo,j,lwkopt,nb
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input arguments
           info = 0
           lquery = (lwork == -1)
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (lwork < max(1,n - 1) .and. .not. lquery) then
              info = -7
           end if
           if (info == 0) then
              if (upper) then
                 nb = la_ilaenv(1,'DORGQL',' ',n - 1,n - 1,n - 1,-1)
              else
                 nb = la_ilaenv(1,'DORGQR',' ',n - 1,n - 1,n - 1,-1)
              end if
              lwkopt = max(1,n - 1)*nb
              work(1) = lwkopt
           end if
           if (info /= 0) then
              call la_xerbla('DORGTR',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) then
              work(1) = 1
              return
           end if
           if (upper) then
              ! q was determined by a call to la_qsytrd with uplo = 'u'
              ! shift the vectors which define the elementary reflectors one
              ! column to the left, and set the last row and column of q to
              ! those of the unit matrix
              do j = 1,n - 1
                 do i = 1,j - 1
                    a(i,j) = a(i,j + 1)
                 end do
                 a(n,j) = zero
              end do
              do i = 1,n - 1
                 a(i,n) = zero
              end do
              a(n,n) = one
              ! generate q(1:n-1,1:n-1)
              call la_qorgql(n - 1,n - 1,n - 1,a,lda,tau,work,lwork,iinfo)
           else
              ! q was determined by a call to la_qsytrd with uplo = 'l'.
              ! shift the vectors which define the elementary reflectors one
              ! column to the right, and set the first row and column of q to
              ! those of the unit matrix
              do j = n,2,-1
                 a(1,j) = zero
                 do i = j + 1,n
                    a(i,j) = a(i,j - 1)
                 end do
              end do
              a(1,1) = one
              do i = 2,n
                 a(i,1) = zero
              end do
              if (n > 1) then
                 ! generate q(2:n,2:n)
                 call la_qorgqr(n - 1,n - 1,n - 1,a(2,2),lda,tau,work,lwork,iinfo)

              end if
           end if
           work(1) = lwkopt
           return
     end subroutine la_qorgtr

     pure subroutine la_qorm22(side,trans,m,n,n1,n2,q,ldq,c,ldc,work,lwork,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: side,trans
           integer(ilp),intent(in) :: m,n,n1,n2,ldq,ldc,lwork
           integer(ilp),intent(out) :: info
           ! Array Arguments
           real(qp),intent(in) :: q(ldq,*)
           real(qp),intent(inout) :: c(ldc,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: left,lquery,notran
           integer(ilp) :: i,ldwork,len,lwkopt,nb,nq,nw
           ! Intrinsic Functions
           intrinsic :: real,max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           left = la_lsame(side,'L')
           notran = la_lsame(trans,'N')
           lquery = (lwork == -1)
           ! nq is the order of q;
           ! nw is the minimum dimension of work.
           if (left) then
              nq = m
           else
              nq = n
           end if
           nw = nq
           if (n1 == 0 .or. n2 == 0) nw = 1
           if (.not. left .and. .not. la_lsame(side,'R')) then
              info = -1
           else if (.not. la_lsame(trans,'N') .and. .not. la_lsame(trans,'T')) &
                     then
              info = -2
           else if (m < 0) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (n1 < 0 .or. n1 + n2 /= nq) then
              info = -5
           else if (n2 < 0) then
              info = -6
           else if (ldq < max(1,nq)) then
              info = -8
           else if (ldc < max(1,m)) then
              info = -10
           else if (lwork < nw .and. .not. lquery) then
              info = -12
           end if
           if (info == 0) then
              lwkopt = m*n
              work(1) = real(lwkopt,KIND=qp)
           end if
           if (info /= 0) then
              call la_xerbla('DORM22',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) then
              work(1) = 1
              return
           end if
           ! degenerate cases (n1 = 0 or n2 = 0) are handled using la_qtrmm.
           if (n1 == 0) then
              call la_qtrmm(side,'UPPER',trans,'NON-UNIT',m,n,one,q,ldq,c,ldc)

              work(1) = one
              return
           else if (n2 == 0) then
              call la_qtrmm(side,'LOWER',trans,'NON-UNIT',m,n,one,q,ldq,c,ldc)

              work(1) = one
              return
           end if
           ! compute the largest chunk size available from the workspace.
           nb = max(1,min(lwork,lwkopt)/nq)
           if (left) then
              if (notran) then
                 do i = 1,n,nb
                    len = min(nb,n - i + 1)
                    ldwork = m
                    ! multiply bottom part of c by q12.
                    call la_qlacpy('ALL',n1,len,c(n2 + 1,i),ldc,work,ldwork)
                    call la_qtrmm('LEFT','LOWER','NO TRANSPOSE','NON-UNIT',n1,len,one, &
                              q(1,n2 + 1),ldq,work,ldwork)
                    ! multiply top part of c by q11.
                    call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',n1,len,n2,one,q,ldq,c( &
                               1,i),ldc,one,work,ldwork)
                    ! multiply top part of c by q21.
                    call la_qlacpy('ALL',n2,len,c(1,i),ldc,work(n1 + 1),ldwork)

                    call la_qtrmm('LEFT','UPPER','NO TRANSPOSE','NON-UNIT',n2,len,one, &
                              q(n1 + 1,1),ldq,work(n1 + 1),ldwork)
                    ! multiply bottom part of c by q22.
                    call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',n2,len,n1,one,q(n1 + 1, &
                              n2 + 1),ldq,c(n2 + 1,i),ldc,one,work(n1 + 1),ldwork)
                    ! copy everything back.
                    call la_qlacpy('ALL',m,len,work,ldwork,c(1,i),ldc)
                 end do
              else
                 do i = 1,n,nb
                    len = min(nb,n - i + 1)
                    ldwork = m
                    ! multiply bottom part of c by q21**t.
                    call la_qlacpy('ALL',n2,len,c(n1 + 1,i),ldc,work,ldwork)
                    call la_qtrmm('LEFT','UPPER','TRANSPOSE','NON-UNIT',n2,len,one,q( &
                              n1 + 1,1),ldq,work,ldwork)
                    ! multiply top part of c by q11**t.
                    call la_qgemm('TRANSPOSE','NO TRANSPOSE',n2,len,n1,one,q,ldq,c(1, &
                               i),ldc,one,work,ldwork)
                    ! multiply top part of c by q12**t.
                    call la_qlacpy('ALL',n1,len,c(1,i),ldc,work(n2 + 1),ldwork)

                    call la_qtrmm('LEFT','LOWER','TRANSPOSE','NON-UNIT',n1,len,one,q( &
                              1,n2 + 1),ldq,work(n2 + 1),ldwork)
                    ! multiply bottom part of c by q22**t.
                    call la_qgemm('TRANSPOSE','NO TRANSPOSE',n1,len,n2,one,q(n1 + 1,n2 + &
                              1),ldq,c(n1 + 1,i),ldc,one,work(n2 + 1),ldwork)
                    ! copy everything back.
                    call la_qlacpy('ALL',m,len,work,ldwork,c(1,i),ldc)
                 end do
              end if
           else
              if (notran) then
                 do i = 1,m,nb
                    len = min(nb,m - i + 1)
                    ldwork = len
                    ! multiply right part of c by q21.
                    call la_qlacpy('ALL',len,n2,c(i,n1 + 1),ldc,work,ldwork)
                    call la_qtrmm('RIGHT','UPPER','NO TRANSPOSE','NON-UNIT',len,n2,one, &
                              q(n1 + 1,1),ldq,work,ldwork)
                    ! multiply left part of c by q11.
                    call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',len,n2,n1,one,c(i,1), &
                               ldc,q,ldq,one,work,ldwork)
                    ! multiply left part of c by q12.
                    call la_qlacpy('ALL',len,n1,c(i,1),ldc,work(1 + n2*ldwork), &
                              ldwork)
                    call la_qtrmm('RIGHT','LOWER','NO TRANSPOSE','NON-UNIT',len,n1,one, &
                              q(1,n2 + 1),ldq,work(1 + n2*ldwork),ldwork)
                    ! multiply right part of c by q22.
                    call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',len,n1,n2,one,c(i,n1 + &
                              1),ldc,q(n1 + 1,n2 + 1),ldq,one,work(1 + n2*ldwork),ldwork)
                    ! copy everything back.
                    call la_qlacpy('ALL',len,n,work,ldwork,c(i,1),ldc)
                 end do
              else
                 do i = 1,m,nb
                    len = min(nb,m - i + 1)
                    ldwork = len
                    ! multiply right part of c by q12**t.
                    call la_qlacpy('ALL',len,n1,c(i,n2 + 1),ldc,work,ldwork)
                    call la_qtrmm('RIGHT','LOWER','TRANSPOSE','NON-UNIT',len,n1,one,q( &
                              1,n2 + 1),ldq,work,ldwork)
                    ! multiply left part of c by q11**t.
                    call la_qgemm('NO TRANSPOSE','TRANSPOSE',len,n1,n2,one,c(i,1), &
                              ldc,q,ldq,one,work,ldwork)
                    ! multiply left part of c by q21**t.
                    call la_qlacpy('ALL',len,n2,c(i,1),ldc,work(1 + n1*ldwork), &
                              ldwork)
                    call la_qtrmm('RIGHT','UPPER','TRANSPOSE','NON-UNIT',len,n2,one,q( &
                              n1 + 1,1),ldq,work(1 + n1*ldwork),ldwork)
                    ! multiply right part of c by q22**t.
                    call la_qgemm('NO TRANSPOSE','TRANSPOSE',len,n2,n1,one,c(i,n2 + 1), &
                               ldc,q(n1 + 1,n2 + 1),ldq,one,work(1 + n1*ldwork),ldwork)
                    ! copy everything back.
                    call la_qlacpy('ALL',len,n,work,ldwork,c(i,1),ldc)
                 end do
              end if
           end if
           work(1) = real(lwkopt,KIND=qp)
           return
     end subroutine la_qorm22

     !> If VECT = 'Q', DORMBR: overwrites the general real M-by-N matrix C
     !> with
     !> SIDE = 'L'     SIDE = 'R'
     !> TRANS = 'N':      Q * C          C * Q
     !> TRANS = 'T':      Q**T * C       C * Q**T
     !> If VECT = 'P', DORMBR overwrites the general real M-by-N matrix C
     !> with
     !> SIDE = 'L'     SIDE = 'R'
     !> TRANS = 'N':      P * C          C * P
     !> TRANS = 'T':      P**T * C       C * P**T
     !> Here Q and P**T are the orthogonal matrices determined by DGEBRD when
     !> reducing a real matrix A to bidiagonal form: A = Q * B * P**T. Q and
     !> P**T are defined as products of elementary reflectors H(i) and G(i)
     !> respectively.
     !> Let nq = m if SIDE = 'L' and nq = n if SIDE = 'R'. Thus nq is the
     !> order of the orthogonal matrix Q or P**T that is applied.
     !> If VECT = 'Q', A is assumed to have been an NQ-by-K matrix:
     !> if nq >= k, Q = H(1) H(2) . . . H(k);
     !> if nq < k, Q = H(1) H(2) . . . H(nq-1).
     !> If VECT = 'P', A is assumed to have been a K-by-NQ matrix:
     !> if k < nq, P = G(1) G(2) . . . G(k);
     !> if k >= nq, P = G(1) G(2) . . . G(nq-1).

     pure subroutine la_qormbr(vect,side,trans,m,n,k,a,lda,tau,c,ldc,work,lwork, &
               info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: side,trans,vect
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: k,lda,ldc,lwork,m,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),c(ldc,*)
           real(qp),intent(in) :: tau(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: applyq,left,lquery,notran
           character :: transt
           integer(ilp) :: i1,i2,iinfo,lwkopt,mi,nb,ni,nq,nw
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments
           info = 0
           applyq = la_lsame(vect,'Q')
           left = la_lsame(side,'L')
           notran = la_lsame(trans,'N')
           lquery = (lwork == -1)
           ! nq is the order of q or p and nw is the minimum dimension of work
           if (left) then
              nq = m
              nw = max(1,n)
           else
              nq = n
              nw = max(1,m)
           end if
           if (.not. applyq .and. .not. la_lsame(vect,'P')) then
              info = -1
           else if (.not. left .and. .not. la_lsame(side,'R')) then
              info = -2
           else if (.not. notran .and. .not. la_lsame(trans,'T')) then
              info = -3
           else if (m < 0) then
              info = -4
           else if (n < 0) then
              info = -5
           else if (k < 0) then
              info = -6
           else if ((applyq .and. lda < max(1,nq)) .or. (.not. applyq .and. lda < max(1,min(nq, &
                      k)))) then
              info = -8
           else if (ldc < max(1,m)) then
              info = -11
           else if (lwork < nw .and. .not. lquery) then
              info = -13
           end if
           if (info == 0) then
              if (applyq) then
                 if (left) then
                    nb = la_ilaenv(1,'DORMQR',side//trans,m - 1,n,m - 1,-1)
                 else
                    nb = la_ilaenv(1,'DORMQR',side//trans,m,n - 1,n - 1,-1)
                 end if
              else
                 if (left) then
                    nb = la_ilaenv(1,'DORMLQ',side//trans,m - 1,n,m - 1,-1)
                 else
                    nb = la_ilaenv(1,'DORMLQ',side//trans,m,n - 1,n - 1,-1)
                 end if
              end if
              lwkopt = nw*nb
              work(1) = lwkopt
           end if
           if (info /= 0) then
              call la_xerbla('DORMBR',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           work(1) = 1
           if (m == 0 .or. n == 0) return
           if (applyq) then
              ! apply q
              if (nq >= k) then
                 ! q was determined by a call to la_qgebrd with nq >= k
                 call la_qormqr(side,trans,m,n,k,a,lda,tau,c,ldc,work,lwork,iinfo &
                           )
              else if (nq > 1) then
                 ! q was determined by a call to la_qgebrd with nq < k
                 if (left) then
                    mi = m - 1
                    ni = n
                    i1 = 2
                    i2 = 1
                 else
                    mi = m
                    ni = n - 1
                    i1 = 1
                    i2 = 2
                 end if
                 call la_qormqr(side,trans,mi,ni,nq - 1,a(2,1),lda,tau,c(i1,i2), &
                           ldc,work,lwork,iinfo)
              end if
           else
              ! apply p
              if (notran) then
                 transt = 'T'
              else
                 transt = 'N'
              end if
              if (nq > k) then
                 ! p was determined by a call to la_qgebrd with nq > k
                 call la_qormlq(side,transt,m,n,k,a,lda,tau,c,ldc,work,lwork, &
                           iinfo)
              else if (nq > 1) then
                 ! p was determined by a call to la_qgebrd with nq <= k
                 if (left) then
                    mi = m - 1
                    ni = n
                    i1 = 2
                    i2 = 1
                 else
                    mi = m
                    ni = n - 1
                    i1 = 1
                    i2 = 2
                 end if
                 call la_qormlq(side,transt,mi,ni,nq - 1,a(1,2),lda,tau,c(i1,i2), &
                           ldc,work,lwork,iinfo)
              end if
           end if
           work(1) = lwkopt
           return
     end subroutine la_qormbr

     !> DORMTR: overwrites the general real M-by-N matrix C with
     !> SIDE = 'L'     SIDE = 'R'
     !> TRANS = 'N':      Q * C          C * Q
     !> TRANS = 'T':      Q**T * C       C * Q**T
     !> where Q is a real orthogonal matrix of order nq, with nq = m if
     !> SIDE = 'L' and nq = n if SIDE = 'R'. Q is defined as the product of
     !> nq-1 elementary reflectors, as returned by DSYTRD:
     !> if UPLO = 'U', Q = H(nq-1) . . . H(2) H(1);
     !> if UPLO = 'L', Q = H(1) H(2) . . . H(nq-1).

     pure subroutine la_qormtr(side,uplo,trans,m,n,a,lda,tau,c,ldc,work,lwork, &
               info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: side,trans,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldc,lwork,m,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),c(ldc,*)
           real(qp),intent(in) :: tau(*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: left,lquery,upper
           integer(ilp) :: i1,i2,iinfo,lwkopt,mi,nb,ni,nq,nw
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input arguments
           info = 0
           left = la_lsame(side,'L')
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1)
           ! nq is the order of q and nw is the minimum dimension of work
           if (left) then
              nq = m
              nw = max(1,n)
           else
              nq = n
              nw = max(1,m)
           end if
           if (.not. left .and. .not. la_lsame(side,'R')) then
              info = -1
           else if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -2
           else if (.not. la_lsame(trans,'N') .and. .not. la_lsame(trans,'T')) &
                     then
              info = -3
           else if (m < 0) then
              info = -4
           else if (n < 0) then
              info = -5
           else if (lda < max(1,nq)) then
              info = -7
           else if (ldc < max(1,m)) then
              info = -10
           else if (lwork < nw .and. .not. lquery) then
              info = -12
           end if
           if (info == 0) then
              if (upper) then
                 if (left) then
                    nb = la_ilaenv(1,'DORMQL',side//trans,m - 1,n,m - 1,-1)
                 else
                    nb = la_ilaenv(1,'DORMQL',side//trans,m,n - 1,n - 1,-1)
                 end if
              else
                 if (left) then
                    nb = la_ilaenv(1,'DORMQR',side//trans,m - 1,n,m - 1,-1)
                 else
                    nb = la_ilaenv(1,'DORMQR',side//trans,m,n - 1,n - 1,-1)
                 end if
              end if
              lwkopt = nw*nb
              work(1) = lwkopt
           end if
           if (info /= 0) then
              call la_xerbla('DORMTR',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0 .or. nq == 1) then
              work(1) = 1
              return
           end if
           if (left) then
              mi = m - 1
              ni = n
           else
              mi = m
              ni = n - 1
           end if
           if (upper) then
              ! q was determined by a call to la_qsytrd with uplo = 'u'
              call la_qormql(side,trans,mi,ni,nq - 1,a(1,2),lda,tau,c,ldc,work, &
                        lwork,iinfo)
           else
              ! q was determined by a call to la_qsytrd with uplo = 'l'
              if (left) then
                 i1 = 2
                 i2 = 1
              else
                 i1 = 1
                 i2 = 2
              end if
              call la_qormqr(side,trans,mi,ni,nq - 1,a(2,1),lda,tau,c(i1,i2),ldc, &
                         work,lwork,iinfo)
           end if
           work(1) = lwkopt
           return
     end subroutine la_qormtr

     !> DPBSTF: computes a split Cholesky factorization of a real
     !> symmetric positive definite band matrix A.
     !> This routine is designed to be used in conjunction with DSBGST.
     !> The factorization has the form  A = S**T*S  where S is a band matrix
     !> of the same bandwidth as A and the following structure:
     !> S = ( U    )
     !> ( M  L )
     !> where U is upper triangular of order m = (n+kd)/2, and L is lower
     !> triangular of order n-m.

     pure subroutine la_qpbstf(uplo,n,kd,ab,ldab,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kd,ldab,n
           ! Array Arguments
           real(qp),intent(inout) :: ab(ldab,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,kld,km,m
           real(qp) :: ajj
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kd < 0) then
              info = -3
           else if (ldab < kd + 1) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('DPBSTF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           kld = max(1,ldab - 1)
           ! set the splitting point m.
           m = (n + kd)/2
           if (upper) then
              ! factorize a(m+1:n,m+1:n) as l**t*l, and update a(1:m,1:m).
              do j = n,m + 1,-1
                 ! compute s(j,j) and test for non-positive-definiteness.
                 ajj = ab(kd + 1,j)
                 if (ajj <= zero) go to 50
                 ajj = sqrt(ajj)
                 ab(kd + 1,j) = ajj
                 km = min(j - 1,kd)
                 ! compute elements j-km:j-1 of the j-th column and update the
                 ! the leading submatrix within the band.
                 call la_qscal(km,one/ajj,ab(kd + 1 - km,j),1)
                 call la_qsyr('UPPER',km,-one,ab(kd + 1 - km,j),1,ab(kd + 1,j - km),kld)

              end do
              ! factorize the updated submatrix a(1:m,1:m) as u**t*u.
              do j = 1,m
                 ! compute s(j,j) and test for non-positive-definiteness.
                 ajj = ab(kd + 1,j)
                 if (ajj <= zero) go to 50
                 ajj = sqrt(ajj)
                 ab(kd + 1,j) = ajj
                 km = min(kd,m - j)
                 ! compute elements j+1:j+km of the j-th row and update the
                 ! trailing submatrix within the band.
                 if (km > 0) then
                    call la_qscal(km,one/ajj,ab(kd,j + 1),kld)
                    call la_qsyr('UPPER',km,-one,ab(kd,j + 1),kld,ab(kd + 1,j + 1),kld)

                 end if
              end do
           else
              ! factorize a(m+1:n,m+1:n) as l**t*l, and update a(1:m,1:m).
              do j = n,m + 1,-1
                 ! compute s(j,j) and test for non-positive-definiteness.
                 ajj = ab(1,j)
                 if (ajj <= zero) go to 50
                 ajj = sqrt(ajj)
                 ab(1,j) = ajj
                 km = min(j - 1,kd)
                 ! compute elements j-km:j-1 of the j-th row and update the
                 ! trailing submatrix within the band.
                 call la_qscal(km,one/ajj,ab(km + 1,j - km),kld)
                 call la_qsyr('LOWER',km,-one,ab(km + 1,j - km),kld,ab(1,j - km),kld)

              end do
              ! factorize the updated submatrix a(1:m,1:m) as u**t*u.
              do j = 1,m
                 ! compute s(j,j) and test for non-positive-definiteness.
                 ajj = ab(1,j)
                 if (ajj <= zero) go to 50
                 ajj = sqrt(ajj)
                 ab(1,j) = ajj
                 km = min(kd,m - j)
                 ! compute elements j+1:j+km of the j-th column and update the
                 ! trailing submatrix within the band.
                 if (km > 0) then
                    call la_qscal(km,one/ajj,ab(2,j),1)
                    call la_qsyr('LOWER',km,-one,ab(2,j),1,ab(1,j + 1),kld)
                 end if
              end do
           end if
           return
           50 continue
           info = j
           return
     end subroutine la_qpbstf

     !> DPTEQR: computes all eigenvalues and, optionally, eigenvectors of a
     !> symmetric positive definite tridiagonal matrix by first factoring the
     !> matrix using DPTTRF, and then calling DBDSQR to compute the singular
     !> values of the bidiagonal factor.
     !> This routine computes the eigenvalues of the positive definite
     !> tridiagonal matrix to high relative accuracy.  This means that if the
     !> eigenvalues range over many orders of magnitude in size, then the
     !> small eigenvalues and corresponding eigenvectors will be computed
     !> more accurately than, for example, with the standard QR method.
     !> The eigenvectors of a full or band symmetric positive definite matrix
     !> can also be found if DSYTRD, DSPTRD, or DSBTRD has been used to
     !> reduce this matrix to tridiagonal form. (The reduction to tridiagonal
     !> form, however, may preclude the possibility of obtaining high
     !> relative accuracy in the small eigenvalues of the original matrix, if
     !> these eigenvalues range over many orders of magnitude.)

     pure subroutine la_qpteqr(compz,n,d,e,z,ldz,work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: compz
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldz,n
           ! Array Arguments
           real(qp),intent(inout) :: d(*),e(*),z(ldz,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Arrays
           real(qp) :: c(1,1),vt(1,1)
           ! Local Scalars
           integer(ilp) :: i,icompz,nru
           ! Intrinsic Functions
           intrinsic :: max,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (la_lsame(compz,'N')) then
              icompz = 0
           else if (la_lsame(compz,'V')) then
              icompz = 1
           else if (la_lsame(compz,'I')) then
              icompz = 2
           else
              icompz = -1
           end if
           if (icompz < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if ((ldz < 1) .or. (icompz > 0 .and. ldz < max(1,n))) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('DPTEQR',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              if (icompz > 0) z(1,1) = one
              return
           end if
           if (icompz == 2) call la_qlaset('FULL',n,n,zero,one,z,ldz)
           ! call la_qpttrf to factor the matrix.
           call la_qpttrf(n,d,e,info)
           if (info /= 0) return
           do i = 1,n
              d(i) = sqrt(d(i))
           end do
           do i = 1,n - 1
              e(i) = e(i)*d(i)
           end do
           ! call la_qbdsqr to compute the singular values/vectors of the
           ! bidiagonal factor.
           if (icompz > 0) then
              nru = n
           else
              nru = 0
           end if
           call la_qbdsqr('LOWER',n,0,nru,0,d,e,vt,1,z,ldz,c,1,work,info)

           ! square the singular values.
           if (info == 0) then
              do i = 1,n
                 d(i) = d(i)*d(i)
              end do
           else
              info = n + info
           end if
           return
     end subroutine la_qpteqr

     !> DSB2ST_KERNELS: is an internal routine used by the DSYTRD_SB2ST
     !> subroutine.

     pure subroutine la_qsb2st_kernels(uplo,wantz,ttype,st,ed,sweep,n,nb,ib,a,lda, &
               v,tau,ldvt,work)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           logical(lk),intent(in) :: wantz
           integer(ilp),intent(in) :: ttype,st,ed,sweep,n,nb,ib,lda,ldvt
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: v(*),tau(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i,j1,j2,lm,ln,vpos,taupos,dpos,ofdpos,ajeter
           real(qp) :: ctmp
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ajeter = ib + ldvt
           upper = la_lsame(uplo,'U')
           if (upper) then
               dpos = 2*nb + 1
               ofdpos = 2*nb
           else
               dpos = 1
               ofdpos = 2
           end if
           ! upper case
           if (upper) then
               if (wantz) then
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               else
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               end if
               if (ttype == 1) then
                   lm = ed - st + 1
                   v(vpos) = one
                   do i = 1,lm - 1
                       v(vpos + i) = (a(ofdpos - i,st + i))
                       a(ofdpos - i,st + i) = zero
                   end do
                   ctmp = (a(ofdpos,st))
                   call la_qlarfg(lm,ctmp,v(vpos + 1),1,tau(taupos))
                   a(ofdpos,st) = ctmp
                   lm = ed - st + 1
                   call la_qlarfy(uplo,lm,v(vpos),1, (tau(taupos)),a(dpos,st), &
                             lda - 1,work)
               end if
               if (ttype == 3) then
                   lm = ed - st + 1
                   call la_qlarfy(uplo,lm,v(vpos),1, (tau(taupos)),a(dpos,st), &
                             lda - 1,work)
               end if
               if (ttype == 2) then
                   j1 = ed + 1
                   j2 = min(ed + nb,n)
                   ln = ed - st + 1
                   lm = j2 - j1 + 1
                   if (lm > 0) then
                       call la_qlarfx('LEFT',ln,lm,v(vpos), (tau(taupos)),a(dpos - nb, &
                                  j1),lda - 1,work)
                       if (wantz) then
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       else
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       end if
                       v(vpos) = one
                       do i = 1,lm - 1
                           v(vpos + i) = (a(dpos - nb - i,j1 + i))
                           a(dpos - nb - i,j1 + i) = zero
                       end do
                       ctmp = (a(dpos - nb,j1))
                       call la_qlarfg(lm,ctmp,v(vpos + 1),1,tau(taupos))
                       a(dpos - nb,j1) = ctmp
                       call la_qlarfx('RIGHT',ln - 1,lm,v(vpos),tau(taupos),a(dpos - nb + &
                                 1,j1),lda - 1,work)
                   end if
               end if
           ! lower case
           else
               if (wantz) then
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               else
                   vpos = mod(sweep - 1,2)*n + st
                   taupos = mod(sweep - 1,2)*n + st
               end if
               if (ttype == 1) then
                   lm = ed - st + 1
                   v(vpos) = one
                   do i = 1,lm - 1
                       v(vpos + i) = a(ofdpos + i,st - 1)
                       a(ofdpos + i,st - 1) = zero
                   end do
                   call la_qlarfg(lm,a(ofdpos,st - 1),v(vpos + 1),1,tau(taupos))

                   lm = ed - st + 1
                   call la_qlarfy(uplo,lm,v(vpos),1, (tau(taupos)),a(dpos,st), &
                             lda - 1,work)
               end if
               if (ttype == 3) then
                   lm = ed - st + 1
                   call la_qlarfy(uplo,lm,v(vpos),1, (tau(taupos)),a(dpos,st), &
                             lda - 1,work)
               end if
               if (ttype == 2) then
                   j1 = ed + 1
                   j2 = min(ed + nb,n)
                   ln = ed - st + 1
                   lm = j2 - j1 + 1
                   if (lm > 0) then
                       call la_qlarfx('RIGHT',lm,ln,v(vpos),tau(taupos),a(dpos + nb, &
                                 st),lda - 1,work)
                       if (wantz) then
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       else
                           vpos = mod(sweep - 1,2)*n + j1
                           taupos = mod(sweep - 1,2)*n + j1
                       end if
                       v(vpos) = one
                       do i = 1,lm - 1
                           v(vpos + i) = a(dpos + nb + i,st)
                           a(dpos + nb + i,st) = zero
                       end do
                       call la_qlarfg(lm,a(dpos + nb,st),v(vpos + 1),1,tau(taupos))

                       call la_qlarfx('LEFT',lm,ln - 1,v(vpos), (tau(taupos)),a(dpos + &
                                 nb - 1,st + 1),lda - 1,work)
                   end if
               end if
           end if
           return
     end subroutine la_qsb2st_kernels

     !> DSBEV: computes all the eigenvalues and, optionally, eigenvectors of
     !> a real symmetric band matrix A.

     subroutine la_qsbev(jobz,uplo,n,kd,ab,ldab,w,z,ldz,work,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kd,ldab,ldz,n
           ! Array Arguments
           real(qp),intent(inout) :: ab(ldab,*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,wantz
           integer(ilp) :: iinfo,imax,inde,indwrk,iscale
           real(qp) :: anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum
           ! Intrinsic Functions
           intrinsic :: sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           lower = la_lsame(uplo,'L')
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (kd < 0) then
              info = -4
           else if (ldab < kd + 1) then
              info = -6
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -9
           end if
           if (info /= 0) then
              call la_xerbla('DSBEV ',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              if (lower) then
                 w(1) = ab(1,1)
              else
                 w(1) = ab(kd + 1,1)
              end if
              if (wantz) z(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = sqrt(bignum)
           ! scale matrix to allowable range, if necessary.
           anrm = la_qlansb('M',uplo,n,kd,ab,ldab,work)
           iscale = 0
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              if (lower) then
                 call la_qlascl('B',kd,kd,one,sigma,n,n,ab,ldab,info)
              else
                 call la_qlascl('Q',kd,kd,one,sigma,n,n,ab,ldab,info)
              end if
           end if
           ! call la_qsbtrd to reduce symmetric band matrix to tridiagonal form.
           inde = 1
           indwrk = inde + n
           call la_qsbtrd(jobz,uplo,n,kd,ab,ldab,w,work(inde),z,ldz,work(indwrk) &
                     ,iinfo)
           ! for eigenvalues only, call la_qsterf.  for eigenvectors, call la_dsteqr.
           if (.not. wantz) then
              call la_qsterf(n,w,work(inde),info)
           else
              call la_qsteqr(jobz,n,w,work(inde),z,ldz,work(indwrk),info)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           if (iscale == 1) then
              if (info == 0) then
                 imax = n
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           return
     end subroutine la_qsbev

     !> DSBEVD: computes all the eigenvalues and, optionally, eigenvectors of
     !> a real symmetric band matrix A. If eigenvectors are desired, it uses
     !> a divide and conquer algorithm.
     !> The divide and conquer algorithm makes very mild assumptions about
     !> floating point arithmetic. It will work on machines with a guard
     !> digit in add/subtract, or on those binary machines without guard
     !> digits which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or
     !> Cray-2. It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.

     subroutine la_qsbevd(jobz,uplo,n,kd,ab,ldab,w,z,ldz,work,lwork,iwork,liwork, &
               info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kd,ldab,ldz,liwork,lwork,n
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: ab(ldab,*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,lquery,wantz
           integer(ilp) :: iinfo,inde,indwk2,indwrk,iscale,liwmin,llwrk2,lwmin
           real(qp) :: anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum
           ! Intrinsic Functions
           intrinsic :: sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           lower = la_lsame(uplo,'L')
           lquery = (lwork == -1 .or. liwork == -1)
           info = 0
           if (n <= 1) then
              liwmin = 1
              lwmin = 1
           else
              if (wantz) then
                 liwmin = 3 + 5*n
                 lwmin = 1 + 5*n + 2*n**2
              else
                 liwmin = 1
                 lwmin = 2*n
              end if
           end if
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (kd < 0) then
              info = -4
           else if (ldab < kd + 1) then
              info = -6
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -9
           end if
           if (info == 0) then
              work(1) = lwmin
              iwork(1) = liwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -11
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -13
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSBEVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              w(1) = ab(1,1)
              if (wantz) z(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = sqrt(bignum)
           ! scale matrix to allowable range, if necessary.
           anrm = la_qlansb('M',uplo,n,kd,ab,ldab,work)
           iscale = 0
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              if (lower) then
                 call la_qlascl('B',kd,kd,one,sigma,n,n,ab,ldab,info)
              else
                 call la_qlascl('Q',kd,kd,one,sigma,n,n,ab,ldab,info)
              end if
           end if
           ! call la_qsbtrd to reduce symmetric band matrix to tridiagonal form.
           inde = 1
           indwrk = inde + n
           indwk2 = indwrk + n*n
           llwrk2 = lwork - indwk2 + 1
           call la_qsbtrd(jobz,uplo,n,kd,ab,ldab,w,work(inde),z,ldz,work(indwrk) &
                     ,iinfo)
           ! for eigenvalues only, call la_qsterf.  for eigenvectors, call la_dstedc.
           if (.not. wantz) then
              call la_qsterf(n,w,work(inde),info)
           else
              call la_qstedc('I',n,w,work(inde),work(indwrk),n,work(indwk2), &
                        llwrk2,iwork,liwork,info)
              call la_qgemm('N','N',n,n,n,one,z,ldz,work(indwrk),n,zero,work( &
                        indwk2),n)
              call la_qlacpy('A',n,n,work(indwk2),n,z,ldz)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           if (iscale == 1) call la_qscal(n,one/sigma,w,1)
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qsbevd

     !> DSBEVX: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric band matrix A.  Eigenvalues and eigenvectors can
     !> be selected by specifying either a range of values or a range of
     !> indices for the desired eigenvalues.

     subroutine la_qsbevx(jobz,range,uplo,n,kd,ab,ldab,q,ldq,vl,vu,il,iu,abstol, &
               m,w,z,ldz,work,iwork,ifail,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,iu,kd,ldab,ldq,ldz,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: ifail(*),iwork(*)
           real(qp),intent(inout) :: ab(ldab,*)
           real(qp),intent(out) :: q(ldq,*),w(*),work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,lower,test,valeig,wantz
           character :: order
           integer(ilp) :: i,iinfo,imax,indd,inde,indee,indibl,indisp,indiwo,indwrk, &
                     iscale,itmp1,j,jj,nsplit
           real(qp) :: abstll,anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lower = la_lsame(uplo,'L')
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (kd < 0) then
              info = -5
           else if (ldab < kd + 1) then
              info = -7
           else if (wantz .and. ldq < max(1,n)) then
              info = -9
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -11
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -12
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -13
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) info = -18
           end if
           if (info /= 0) then
              call la_xerbla('DSBEVX',-info)
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) return
           if (n == 1) then
              m = 1
              if (lower) then
                 tmp1 = ab(1,1)
              else
                 tmp1 = ab(kd + 1,1)
              end if
              if (valeig) then
                 if (.not. (vl < tmp1 .and. vu >= tmp1)) m = 0
              end if
              if (m == 1) then
                 w(1) = tmp1
                 if (wantz) z(1,1) = one
              end if
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           abstll = abstol
           if (valeig) then
              vll = vl
              vuu = vu
           else
              vll = zero
              vuu = zero
           end if
           anrm = la_qlansb('M',uplo,n,kd,ab,ldab,work)
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              if (lower) then
                 call la_qlascl('B',kd,kd,one,sigma,n,n,ab,ldab,info)
              else
                 call la_qlascl('Q',kd,kd,one,sigma,n,n,ab,ldab,info)
              end if
              if (abstol > 0) abstll = abstol*sigma
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! call la_qsbtrd to reduce symmetric band matrix to tridiagonal form.
           indd = 1
           inde = indd + n
           indwrk = inde + n
           call la_qsbtrd(jobz,uplo,n,kd,ab,ldab,work(indd),work(inde),q,ldq, &
                     work(indwrk),iinfo)
           ! if all eigenvalues are desired and abstol is less than or equal
           ! to zero, then call la_qsterf or la_dsteqr.  if this fails for some
           ! eigenvalue, then try la_qstebz.
           test = .false.
           if (indeig) then
              if (il == 1 .and. iu == n) then
                 test = .true.
              end if
           end if
           if ((alleig .or. test) .and. (abstol <= zero)) then
              call la_qcopy(n,work(indd),1,w,1)
              indee = indwrk + 2*n
              if (.not. wantz) then
                 call la_qcopy(n - 1,work(inde),1,work(indee),1)
                 call la_qsterf(n,w,work(indee),info)
              else
                 call la_qlacpy('A',n,n,q,ldq,z,ldz)
                 call la_qcopy(n - 1,work(inde),1,work(indee),1)
                 call la_qsteqr(jobz,n,w,work(indee),z,ldz,work(indwrk),info)

                 if (info == 0) then
                    do i = 1,n
                       ifail(i) = 0
                    end do
                 end if
              end if
              if (info == 0) then
                 m = n
                 go to 30
              end if
              info = 0
           end if
           ! otherwise, call la_qstebz and, if eigenvectors are desired, la_dstein.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           indibl = 1
           indisp = indibl + n
           indiwo = indisp + n
           call la_qstebz(range,order,n,vll,vuu,il,iu,abstll,work(indd),work(inde &
           ),m,nsplit,w,iwork(indibl),iwork(indisp),work(indwrk),iwork(indiwo),info &
                     )
           if (wantz) then
              call la_qstein(n,work(indd),work(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,work(indwrk),iwork(indiwo),ifail,info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_qstein.
              do j = 1,m
                 call la_qcopy(n,z(1,j),1,work(1),1)
                 call la_qgemv('N',n,n,one,q,ldq,work,1,zero,z(1,j),1)
              end do
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           30 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    itmp1 = iwork(indibl + i - 1)
                    w(i) = w(j)
                    iwork(indibl + i - 1) = iwork(indibl + j - 1)
                    w(j) = tmp1
                    iwork(indibl + j - 1) = itmp1
                    call la_qswap(n,z(1,i),1,z(1,j),1)
                    if (info /= 0) then
                       itmp1 = ifail(i)
                       ifail(i) = ifail(j)
                       ifail(j) = itmp1
                    end if
                 end if
              end do
           end if
           return
     end subroutine la_qsbevx

     !> DSBGST: reduces a real symmetric-definite banded generalized
     !> eigenproblem  A*x = lambda*B*x  to standard form  C*y = lambda*y,
     !> such that C has the same bandwidth as A.
     !> B must have been previously factorized as S**T*S by DPBSTF, using a
     !> split Cholesky factorization. A is overwritten by C = X**T*A*X, where
     !> X = S**(-1)*Q and Q is an orthogonal matrix chosen to preserve the
     !> bandwidth of A.

     pure subroutine la_qsbgst(vect,uplo,n,ka,kb,ab,ldab,bb,ldbb,x,ldx,work,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo,vect
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ka,kb,ldab,ldbb,ldx,n
           ! Array Arguments
           real(qp),intent(inout) :: ab(ldab,*)
           real(qp),intent(in) :: bb(ldbb,*)
           real(qp),intent(out) :: work(*),x(ldx,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: update,upper,wantx
           integer(ilp) :: i,i0,i1,i2,inca,j,j1,j1t,j2,j2t,k,ka1,kb1,kbt,l,m,nr, &
                     nrt,nx
           real(qp) :: bii,ra,ra1,t
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters
           wantx = la_lsame(vect,'V')
           upper = la_lsame(uplo,'U')
           ka1 = ka + 1
           kb1 = kb + 1
           info = 0
           if (.not. wantx .and. .not. la_lsame(vect,'N')) then
              info = -1
           else if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ka < 0) then
              info = -4
           else if (kb < 0 .or. kb > ka) then
              info = -5
           else if (ldab < ka + 1) then
              info = -7
           else if (ldbb < kb + 1) then
              info = -9
           else if (ldx < 1 .or. wantx .and. ldx < max(1,n)) then
              info = -11
           end if
           if (info /= 0) then
              call la_xerbla('DSBGST',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           inca = ldab*ka1
           ! initialize x to the unit matrix, if needed
           if (wantx) call la_qlaset('FULL',n,n,zero,one,x,ldx)
           ! set m to the splitting point m. it must be the same value as is
           ! used in la_qpbstf. the chosen value allows the arrays work and rwork
           ! to be of dimension (n).
           m = (n + kb)/2
           ! the routine works in two phases, corresponding to the two halves
           ! of the split cholesky factorization of b as s**t*s where
           ! s = ( u    )
               ! ( m  l )
           ! with u upper triangular of order m, and l lower triangular of
           ! order n-m. s has the same bandwidth as b.
           ! s is treated as a product of elementary matrices:
           ! s = s(m)*s(m-1)*...*s(2)*s(1)*s(m+1)*s(m+2)*...*s(n-1)*s(n)
           ! where s(i) is determined by the i-th row of s.
           ! in phase 1, the index i takes the values n, n-1, ... , m+1;
           ! in phase 2, it takes the values 1, 2, ... , m.
           ! for each value of i, the current matrix a is updated by forming
           ! inv(s(i))**t*a*inv(s(i)). this creates a triangular bulge outside
           ! the band of a. the bulge is then pushed down toward the bottom of
           ! a in phase 1, and up toward the top of a in phase 2, by applying
           ! plane rotations.
           ! there are kb*(kb+1)/2 elements in the bulge, but at most 2*kb-1
           ! of them are linearly independent, so annihilating a bulge requires
           ! only 2*kb-1 plane rotations. the rotations are divided into a 1st
           ! set of kb-1 rotations, and a 2nd set of kb rotations.
           ! wherever possible, rotations are generated and applied in vector
           ! operations of length nr between the indices j1 and j2 (sometimes
           ! replaced by modified values nrt, j1t or j2t).
           ! the cosines and sines of the rotations are stored in the array
           ! work. the cosines of the 1st set of rotations are stored in
           ! elements n+2:n+m-kb-1 and the sines of the 1st set in elements
           ! 2:m-kb-1; the cosines of the 2nd set are stored in elements
           ! n+m-kb+1:2*n and the sines of the second set in elements m-kb+1:n.
           ! the bulges are not formed explicitly; nonzero elements outside the
           ! band are created only when they are required for generating new
           ! rotations; they are stored in the array work, in positions where
           ! they are later overwritten by the sines of the rotations which
           ! annihilate them.
           ! **************************** phase 1 *****************************
           ! the logical structure of this phase is:
           ! update = .true.
           ! do i = n, m + 1, -1
              ! use s(i) to update a and create a new bulge
              ! apply rotations to push all bulges ka positions downward
           ! end do
           ! update = .false.
           ! do i = m + ka + 1, n - 1
              ! apply rotations to push all bulges ka positions downward
           ! end do
           ! to avoid duplicating code, the two loops are merged.
           update = .true.
           i = n + 1
           10 continue
           if (update) then
              i = i - 1
              kbt = min(kb,i - 1)
              i0 = i - 1
              i1 = min(n,i + ka)
              i2 = i - kbt + ka1
              if (i < m + 1) then
                 update = .false.
                 i = i + 1
                 i0 = m
                 if (ka == 0) go to 480
                 go to 10
              end if
           else
              i = i + ka
              if (i > n - 1) go to 480
           end if
           if (upper) then
              ! transform a, working with the upper triangle
              if (update) then
                 ! form  inv(s(i))**t * a * inv(s(i))
                 bii = bb(kb1,i)
                 do j = i,i1
                    ab(i - j + ka1,j) = ab(i - j + ka1,j)/bii
                 end do
                 do j = max(1,i - ka),i
                    ab(j - i + ka1,i) = ab(j - i + ka1,i)/bii
                 end do
                 do k = i - kbt,i - 1
                    do j = i - kbt,k
                       ab(j - k + ka1,k) = ab(j - k + ka1,k) - bb(j - i + kb1,i)*ab(k - i + ka1,i) - bb( &
                        k - i + kb1,i)*ab(j - i + ka1,i) + ab(ka1,i)*bb(j - i + kb1,i)*bb(k - i + kb1, &
                                  i)
                    end do
                    do j = max(1,i - ka),i - kbt - 1
                       ab(j - k + ka1,k) = ab(j - k + ka1,k) - bb(k - i + kb1,i)*ab(j - i + ka1,i)

                    end do
                 end do
                 do j = i,i1
                    do k = max(j - ka,i - kbt),i - 1
                       ab(k - j + ka1,j) = ab(k - j + ka1,j) - bb(k - i + kb1,i)*ab(i - j + ka1,j)

                    end do
                 end do
                 if (wantx) then
                    ! post-multiply x by inv(s(i))
                    call la_qscal(n - m,one/bii,x(m + 1,i),1)
                    if (kbt > 0) call la_qger(n - m,kbt,-one,x(m + 1,i),1,bb(kb1 - kbt,i), &
                              1,x(m + 1,i - kbt),ldx)
                 end if
                 ! store a(i,i1) in ra1 for use in next loop over k
                 ra1 = ab(i - i1 + ka1,i1)
              end if
              ! generate and apply vectors of rotations to chase all the
              ! existing bulges ka positions down toward the bottom of the
              ! band
              loop_130: do k = 1,kb - 1
                 if (update) then
                    ! determine the rotations which would annihilate the bulge
                    ! which has in theory just been created
                    if (i - k + ka < n .and. i - k > 1) then
                       ! generate rotation to annihilate a(i,i-k+ka+1)
                       call la_qlartg(ab(k + 1,i - k + ka),ra1,work(n + i - k + ka - m),work(i - k + &
                                 ka - m),ra)
                       ! create nonzero element a(i-k,i-k+ka+1) outside the
                       ! band and store it in work(i-k)
                       t = -bb(kb1 - k,i)*ra1
                       work(i - k) = work(n + i - k + ka - m)*t - work(i - k + ka - m)*ab(1,i - k + ka)

                       ab(1,i - k + ka) = work(i - k + ka - m)*t + work(n + i - k + ka - m)*ab(1,i - k + ka)

                       ra1 = ra
                    end if
                 end if
                 j2 = i - k - 1 + max(1,k - i0 + 2)*ka1
                 nr = (n - j2 + ka)/ka1
                 j1 = j2 + (nr - 1)*ka1
                 if (update) then
                    j2t = max(j2,i + 2*ka - k + 1)
                 else
                    j2t = j2
                 end if
                 nrt = (n - j2t + ka)/ka1
                 do j = j2t,j1,ka1
                    ! create nonzero element a(j-ka,j+1) outside the band
                    ! and store it in work(j-m)
                    work(j - m) = work(j - m)*ab(1,j + 1)
                    ab(1,j + 1) = work(n + j - m)*ab(1,j + 1)
                 end do
                 ! generate rotations in 1st set to annihilate elements which
                 ! have been created outside the band
                 if (nrt > 0) call la_qlargv(nrt,ab(1,j2t),inca,work(j2t - m),ka1,work( &
                           n + j2t - m),ka1)
                 if (nr > 0) then
                    ! apply rotations in 1st set from the right
                    do l = 1,ka - 1
                       call la_qlartv(nr,ab(ka1 - l,j2),inca,ab(ka - l,j2 + 1),inca,work( &
                                  n + j2 - m),work(j2 - m),ka1)
                    end do
                    ! apply rotations in 1st set from both sides to diagonal
                    ! blocks
                    call la_qlar2v(nr,ab(ka1,j2),ab(ka1,j2 + 1),ab(ka,j2 + 1),inca, &
                              work(n + j2 - m),work(j2 - m),ka1)
                 end if
                 ! start applying rotations in 1st set from the left
                 do l = ka - 1,kb - k + 1,-1
                    nrt = (n - j2 + l)/ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(l,j2 + ka1 - l),inca,ab(l + 1,j2 + ka1 - l &
                              ),inca,work(n + j2 - m),work(j2 - m),ka1)
                 end do
                 if (wantx) then
                    ! post-multiply x by product of rotations in 1st set
                    do j = j2,j1,ka1
                       call la_qrot(n - m,x(m + 1,j),1,x(m + 1,j + 1),1,work(n + j - m), &
                                 work(j - m))
                    end do
                 end if
              end do loop_130
              if (update) then
                 if (i2 <= n .and. kbt > 0) then
                    ! create nonzero element a(i-kbt,i-kbt+ka+1) outside the
                    ! band and store it in work(i-kbt)
                    work(i - kbt) = -bb(kb1 - kbt,i)*ra1
                 end if
              end if
              loop_170: do k = kb,1,-1
                 if (update) then
                    j2 = i - k - 1 + max(2,k - i0 + 1)*ka1
                 else
                    j2 = i - k - 1 + max(1,k - i0 + 1)*ka1
                 end if
                 ! finish applying rotations in 2nd set from the left
                 do l = kb - k,1,-1
                    nrt = (n - j2 + ka + l)/ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(l,j2 - l + 1),inca,ab(l + 1,j2 - l + 1), &
                              inca,work(n + j2 - ka),work(j2 - ka),ka1)
                 end do
                 nr = (n - j2 + ka)/ka1
                 j1 = j2 + (nr - 1)*ka1
                 do j = j1,j2,-ka1
                    work(j) = work(j - ka)
                    work(n + j) = work(n + j - ka)
                 end do
                 do j = j2,j1,ka1
                    ! create nonzero element a(j-ka,j+1) outside the band
                    ! and store it in work(j)
                    work(j) = work(j)*ab(1,j + 1)
                    ab(1,j + 1) = work(n + j)*ab(1,j + 1)
                 end do
                 if (update) then
                    if (i - k < n - ka .and. k <= kbt) work(i - k + ka) = work(i - k)
                 end if
              end do loop_170
              loop_210: do k = kb,1,-1
                 j2 = i - k - 1 + max(1,k - i0 + 1)*ka1
                 nr = (n - j2 + ka)/ka1
                 j1 = j2 + (nr - 1)*ka1
                 if (nr > 0) then
                    ! generate rotations in 2nd set to annihilate elements
                    ! which have been created outside the band
                    call la_qlargv(nr,ab(1,j2),inca,work(j2),ka1,work(n + j2),ka1)

                    ! apply rotations in 2nd set from the right
                    do l = 1,ka - 1
                       call la_qlartv(nr,ab(ka1 - l,j2),inca,ab(ka - l,j2 + 1),inca,work( &
                                  n + j2),work(j2),ka1)
                    end do
                    ! apply rotations in 2nd set from both sides to diagonal
                    ! blocks
                    call la_qlar2v(nr,ab(ka1,j2),ab(ka1,j2 + 1),ab(ka,j2 + 1),inca, &
                              work(n + j2),work(j2),ka1)
                 end if
                 ! start applying rotations in 2nd set from the left
                 do l = ka - 1,kb - k + 1,-1
                    nrt = (n - j2 + l)/ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(l,j2 + ka1 - l),inca,ab(l + 1,j2 + ka1 - l &
                              ),inca,work(n + j2),work(j2),ka1)
                 end do
                 if (wantx) then
                    ! post-multiply x by product of rotations in 2nd set
                    do j = j2,j1,ka1
                       call la_qrot(n - m,x(m + 1,j),1,x(m + 1,j + 1),1,work(n + j),work( &
                                 j))
                    end do
                 end if
              end do loop_210
              do k = 1,kb - 1
                 j2 = i - k - 1 + max(1,k - i0 + 2)*ka1
                 ! finish applying rotations in 1st set from the left
                 do l = kb - k,1,-1
                    nrt = (n - j2 + l)/ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(l,j2 + ka1 - l),inca,ab(l + 1,j2 + ka1 - l &
                              ),inca,work(n + j2 - m),work(j2 - m),ka1)
                 end do
              end do
              if (kb > 1) then
                 do j = n - 1,i - kb + 2*ka + 1,-1
                    work(n + j - m) = work(n + j - ka - m)
                    work(j - m) = work(j - ka - m)
                 end do
              end if
           else
              ! transform a, working with the lower triangle
              if (update) then
                 ! form  inv(s(i))**t * a * inv(s(i))
                 bii = bb(1,i)
                 do j = i,i1
                    ab(j - i + 1,i) = ab(j - i + 1,i)/bii
                 end do
                 do j = max(1,i - ka),i
                    ab(i - j + 1,j) = ab(i - j + 1,j)/bii
                 end do
                 do k = i - kbt,i - 1
                    do j = i - kbt,k
                       ab(k - j + 1,j) = ab(k - j + 1,j) - bb(i - j + 1,j)*ab(i - k + 1,k) - bb(i - k + 1, &
                                 k)*ab(i - j + 1,j) + ab(1,i)*bb(i - j + 1,j)*bb(i - k + 1,k)
                    end do
                    do j = max(1,i - ka),i - kbt - 1
                       ab(k - j + 1,j) = ab(k - j + 1,j) - bb(i - k + 1,k)*ab(i - j + 1,j)
                    end do
                 end do
                 do j = i,i1
                    do k = max(j - ka,i - kbt),i - 1
                       ab(j - k + 1,k) = ab(j - k + 1,k) - bb(i - k + 1,k)*ab(j - i + 1,i)
                    end do
                 end do
                 if (wantx) then
                    ! post-multiply x by inv(s(i))
                    call la_qscal(n - m,one/bii,x(m + 1,i),1)
                    if (kbt > 0) call la_qger(n - m,kbt,-one,x(m + 1,i),1,bb(kbt + 1,i - kbt) &
                              ,ldbb - 1,x(m + 1,i - kbt),ldx)
                 end if
                 ! store a(i1,i) in ra1 for use in next loop over k
                 ra1 = ab(i1 - i + 1,i)
              end if
              ! generate and apply vectors of rotations to chase all the
              ! existing bulges ka positions down toward the bottom of the
              ! band
              loop_360: do k = 1,kb - 1
                 if (update) then
                    ! determine the rotations which would annihilate the bulge
                    ! which has in theory just been created
                    if (i - k + ka < n .and. i - k > 1) then
                       ! generate rotation to annihilate a(i-k+ka+1,i)
                       call la_qlartg(ab(ka1 - k,i),ra1,work(n + i - k + ka - m),work(i - k + ka - m &
                                 ),ra)
                       ! create nonzero element a(i-k+ka+1,i-k) outside the
                       ! band and store it in work(i-k)
                       t = -bb(k + 1,i - k)*ra1
                       work(i - k) = work(n + i - k + ka - m)*t - work(i - k + ka - m)*ab(ka1,i - k)
                       ab(ka1,i - k) = work(i - k + ka - m)*t + work(n + i - k + ka - m)*ab(ka1,i - k)

                       ra1 = ra
                    end if
                 end if
                 j2 = i - k - 1 + max(1,k - i0 + 2)*ka1
                 nr = (n - j2 + ka)/ka1
                 j1 = j2 + (nr - 1)*ka1
                 if (update) then
                    j2t = max(j2,i + 2*ka - k + 1)
                 else
                    j2t = j2
                 end if
                 nrt = (n - j2t + ka)/ka1
                 do j = j2t,j1,ka1
                    ! create nonzero element a(j+1,j-ka) outside the band
                    ! and store it in work(j-m)
                    work(j - m) = work(j - m)*ab(ka1,j - ka + 1)
                    ab(ka1,j - ka + 1) = work(n + j - m)*ab(ka1,j - ka + 1)
                 end do
                 ! generate rotations in 1st set to annihilate elements which
                 ! have been created outside the band
                 if (nrt > 0) call la_qlargv(nrt,ab(ka1,j2t - ka),inca,work(j2t - m),ka1, &
                           work(n + j2t - m),ka1)
                 if (nr > 0) then
                    ! apply rotations in 1st set from the left
                    do l = 1,ka - 1
                       call la_qlartv(nr,ab(l + 1,j2 - l),inca,ab(l + 2,j2 - l),inca,work( &
                                 n + j2 - m),work(j2 - m),ka1)
                    end do
                    ! apply rotations in 1st set from both sides to diagonal
                    ! blocks
                    call la_qlar2v(nr,ab(1,j2),ab(1,j2 + 1),ab(2,j2),inca,work(n + &
                              j2 - m),work(j2 - m),ka1)
                 end if
                 ! start applying rotations in 1st set from the right
                 do l = ka - 1,kb - k + 1,-1
                    nrt = (n - j2 + l)/ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(ka1 - l + 1,j2),inca,ab(ka1 - l,j2 + 1), &
                               inca,work(n + j2 - m),work(j2 - m),ka1)
                 end do
                 if (wantx) then
                    ! post-multiply x by product of rotations in 1st set
                    do j = j2,j1,ka1
                       call la_qrot(n - m,x(m + 1,j),1,x(m + 1,j + 1),1,work(n + j - m), &
                                 work(j - m))
                    end do
                 end if
              end do loop_360
              if (update) then
                 if (i2 <= n .and. kbt > 0) then
                    ! create nonzero element a(i-kbt+ka+1,i-kbt) outside the
                    ! band and store it in work(i-kbt)
                    work(i - kbt) = -bb(kbt + 1,i - kbt)*ra1
                 end if
              end if
              loop_400: do k = kb,1,-1
                 if (update) then
                    j2 = i - k - 1 + max(2,k - i0 + 1)*ka1
                 else
                    j2 = i - k - 1 + max(1,k - i0 + 1)*ka1
                 end if
                 ! finish applying rotations in 2nd set from the right
                 do l = kb - k,1,-1
                    nrt = (n - j2 + ka + l)/ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(ka1 - l + 1,j2 - ka),inca,ab(ka1 - l,j2 - &
                              ka + 1),inca,work(n + j2 - ka),work(j2 - ka),ka1)
                 end do
                 nr = (n - j2 + ka)/ka1
                 j1 = j2 + (nr - 1)*ka1
                 do j = j1,j2,-ka1
                    work(j) = work(j - ka)
                    work(n + j) = work(n + j - ka)
                 end do
                 do j = j2,j1,ka1
                    ! create nonzero element a(j+1,j-ka) outside the band
                    ! and store it in work(j)
                    work(j) = work(j)*ab(ka1,j - ka + 1)
                    ab(ka1,j - ka + 1) = work(n + j)*ab(ka1,j - ka + 1)
                 end do
                 if (update) then
                    if (i - k < n - ka .and. k <= kbt) work(i - k + ka) = work(i - k)
                 end if
              end do loop_400
              loop_440: do k = kb,1,-1
                 j2 = i - k - 1 + max(1,k - i0 + 1)*ka1
                 nr = (n - j2 + ka)/ka1
                 j1 = j2 + (nr - 1)*ka1
                 if (nr > 0) then
                    ! generate rotations in 2nd set to annihilate elements
                    ! which have been created outside the band
                    call la_qlargv(nr,ab(ka1,j2 - ka),inca,work(j2),ka1,work(n + j2), &
                              ka1)
                    ! apply rotations in 2nd set from the left
                    do l = 1,ka - 1
                       call la_qlartv(nr,ab(l + 1,j2 - l),inca,ab(l + 2,j2 - l),inca,work( &
                                 n + j2),work(j2),ka1)
                    end do
                    ! apply rotations in 2nd set from both sides to diagonal
                    ! blocks
                    call la_qlar2v(nr,ab(1,j2),ab(1,j2 + 1),ab(2,j2),inca,work(n + &
                              j2),work(j2),ka1)
                 end if
                 ! start applying rotations in 2nd set from the right
                 do l = ka - 1,kb - k + 1,-1
                    nrt = (n - j2 + l)/ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(ka1 - l + 1,j2),inca,ab(ka1 - l,j2 + 1), &
                               inca,work(n + j2),work(j2),ka1)
                 end do
                 if (wantx) then
                    ! post-multiply x by product of rotations in 2nd set
                    do j = j2,j1,ka1
                       call la_qrot(n - m,x(m + 1,j),1,x(m + 1,j + 1),1,work(n + j),work( &
                                 j))
                    end do
                 end if
              end do loop_440
              do k = 1,kb - 1
                 j2 = i - k - 1 + max(1,k - i0 + 2)*ka1
                 ! finish applying rotations in 1st set from the right
                 do l = kb - k,1,-1
                    nrt = (n - j2 + l)/ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(ka1 - l + 1,j2),inca,ab(ka1 - l,j2 + 1), &
                               inca,work(n + j2 - m),work(j2 - m),ka1)
                 end do
              end do
              if (kb > 1) then
                 do j = n - 1,i - kb + 2*ka + 1,-1
                    work(n + j - m) = work(n + j - ka - m)
                    work(j - m) = work(j - ka - m)
                 end do
              end if
           end if
           go to 10
           480 continue
           ! **************************** phase 2 *****************************
           ! the logical structure of this phase is:
           ! update = .true.
           ! do i = 1, m
              ! use s(i) to update a and create a new bulge
              ! apply rotations to push all bulges ka positions upward
           ! end do
           ! update = .false.
           ! do i = m - ka - 1, 2, -1
              ! apply rotations to push all bulges ka positions upward
           ! end do
           ! to avoid duplicating code, the two loops are merged.
           update = .true.
           i = 0
           490 continue
           if (update) then
              i = i + 1
              kbt = min(kb,m - i)
              i0 = i + 1
              i1 = max(1,i - ka)
              i2 = i + kbt - ka1
              if (i > m) then
                 update = .false.
                 i = i - 1
                 i0 = m + 1
                 if (ka == 0) return
                 go to 490
              end if
           else
              i = i - ka
              if (i < 2) return
           end if
           if (i < m - kbt) then
              nx = m
           else
              nx = n
           end if
           if (upper) then
              ! transform a, working with the upper triangle
              if (update) then
                 ! form  inv(s(i))**t * a * inv(s(i))
                 bii = bb(kb1,i)
                 do j = i1,i
                    ab(j - i + ka1,i) = ab(j - i + ka1,i)/bii
                 end do
                 do j = i,min(n,i + ka)
                    ab(i - j + ka1,j) = ab(i - j + ka1,j)/bii
                 end do
                 do k = i + 1,i + kbt
                    do j = k,i + kbt
                       ab(k - j + ka1,j) = ab(k - j + ka1,j) - bb(i - j + kb1,j)*ab(i - k + ka1,k) - bb( &
                        i - k + kb1,k)*ab(i - j + ka1,j) + ab(ka1,i)*bb(i - j + kb1,j)*bb(i - k + kb1, &
                                  k)
                    end do
                    do j = i + kbt + 1,min(n,i + ka)
                       ab(k - j + ka1,j) = ab(k - j + ka1,j) - bb(i - k + kb1,k)*ab(i - j + ka1,j)

                    end do
                 end do
                 do j = i1,i
                    do k = i + 1,min(j + ka,i + kbt)
                       ab(j - k + ka1,k) = ab(j - k + ka1,k) - bb(i - k + kb1,k)*ab(j - i + ka1,i)

                    end do
                 end do
                 if (wantx) then
                    ! post-multiply x by inv(s(i))
                    call la_qscal(nx,one/bii,x(1,i),1)
                    if (kbt > 0) call la_qger(nx,kbt,-one,x(1,i),1,bb(kb,i + 1),ldbb - &
                              1,x(1,i + 1),ldx)
                 end if
                 ! store a(i1,i) in ra1 for use in next loop over k
                 ra1 = ab(i1 - i + ka1,i)
              end if
              ! generate and apply vectors of rotations to chase all the
              ! existing bulges ka positions up toward the top of the band
              loop_610: do k = 1,kb - 1
                 if (update) then
                    ! determine the rotations which would annihilate the bulge
                    ! which has in theory just been created
                    if (i + k - ka1 > 0 .and. i + k < m) then
                       ! generate rotation to annihilate a(i+k-ka-1,i)
                       call la_qlartg(ab(k + 1,i),ra1,work(n + i + k - ka),work(i + k - ka),ra &
                                 )
                       ! create nonzero element a(i+k-ka-1,i+k) outside the
                       ! band and store it in work(m-kb+i+k)
                       t = -bb(kb1 - k,i + k)*ra1
                       work(m - kb + i + k) = work(n + i + k - ka)*t - work(i + k - ka)*ab(1,i + k)
                       ab(1,i + k) = work(i + k - ka)*t + work(n + i + k - ka)*ab(1,i + k)
                       ra1 = ra
                    end if
                 end if
                 j2 = i + k + 1 - max(1,k + i0 - m + 1)*ka1
                 nr = (j2 + ka - 1)/ka1
                 j1 = j2 - (nr - 1)*ka1
                 if (update) then
                    j2t = min(j2,i - 2*ka + k - 1)
                 else
                    j2t = j2
                 end if
                 nrt = (j2t + ka - 1)/ka1
                 do j = j1,j2t,ka1
                    ! create nonzero element a(j-1,j+ka) outside the band
                    ! and store it in work(j)
                    work(j) = work(j)*ab(1,j + ka - 1)
                    ab(1,j + ka - 1) = work(n + j)*ab(1,j + ka - 1)
                 end do
                 ! generate rotations in 1st set to annihilate elements which
                 ! have been created outside the band
                 if (nrt > 0) call la_qlargv(nrt,ab(1,j1 + ka),inca,work(j1),ka1,work( &
                           n + j1),ka1)
                 if (nr > 0) then
                    ! apply rotations in 1st set from the left
                    do l = 1,ka - 1
                       call la_qlartv(nr,ab(ka1 - l,j1 + l),inca,ab(ka - l,j1 + l),inca, &
                                 work(n + j1),work(j1),ka1)
                    end do
                    ! apply rotations in 1st set from both sides to diagonal
                    ! blocks
                    call la_qlar2v(nr,ab(ka1,j1),ab(ka1,j1 - 1),ab(ka,j1),inca, &
                              work(n + j1),work(j1),ka1)
                 end if
                 ! start applying rotations in 1st set from the right
                 do l = ka - 1,kb - k + 1,-1
                    nrt = (j2 + l - 1)/ka1
                    j1t = j2 - (nrt - 1)*ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(l,j1t),inca,ab(l + 1,j1t - 1),inca, &
                               work(n + j1t),work(j1t),ka1)
                 end do
                 if (wantx) then
                    ! post-multiply x by product of rotations in 1st set
                    do j = j1,j2,ka1
                       call la_qrot(nx,x(1,j),1,x(1,j - 1),1,work(n + j),work(j))

                    end do
                 end if
              end do loop_610
              if (update) then
                 if (i2 > 0 .and. kbt > 0) then
                    ! create nonzero element a(i+kbt-ka-1,i+kbt) outside the
                    ! band and store it in work(m-kb+i+kbt)
                    work(m - kb + i + kbt) = -bb(kb1 - kbt,i + kbt)*ra1
                 end if
              end if
              loop_650: do k = kb,1,-1
                 if (update) then
                    j2 = i + k + 1 - max(2,k + i0 - m)*ka1
                 else
                    j2 = i + k + 1 - max(1,k + i0 - m)*ka1
                 end if
                 ! finish applying rotations in 2nd set from the right
                 do l = kb - k,1,-1
                    nrt = (j2 + ka + l - 1)/ka1
                    j1t = j2 - (nrt - 1)*ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(l,j1t + ka),inca,ab(l + 1,j1t + ka - 1), &
                               inca,work(n + m - kb + j1t + ka),work(m - kb + j1t + ka),ka1)
                 end do
                 nr = (j2 + ka - 1)/ka1
                 j1 = j2 - (nr - 1)*ka1
                 do j = j1,j2,ka1
                    work(m - kb + j) = work(m - kb + j + ka)
                    work(n + m - kb + j) = work(n + m - kb + j + ka)
                 end do
                 do j = j1,j2,ka1
                    ! create nonzero element a(j-1,j+ka) outside the band
                    ! and store it in work(m-kb+j)
                    work(m - kb + j) = work(m - kb + j)*ab(1,j + ka - 1)
                    ab(1,j + ka - 1) = work(n + m - kb + j)*ab(1,j + ka - 1)
                 end do
                 if (update) then
                    if (i + k > ka1 .and. k <= kbt) work(m - kb + i + k - ka) = work(m - kb + i + k)
                 end if
              end do loop_650
              loop_690: do k = kb,1,-1
                 j2 = i + k + 1 - max(1,k + i0 - m)*ka1
                 nr = (j2 + ka - 1)/ka1
                 j1 = j2 - (nr - 1)*ka1
                 if (nr > 0) then
                    ! generate rotations in 2nd set to annihilate elements
                    ! which have been created outside the band
                    call la_qlargv(nr,ab(1,j1 + ka),inca,work(m - kb + j1),ka1,work(n + m - &
                              kb + j1),ka1)
                    ! apply rotations in 2nd set from the left
                    do l = 1,ka - 1
                       call la_qlartv(nr,ab(ka1 - l,j1 + l),inca,ab(ka - l,j1 + l),inca, &
                                 work(n + m - kb + j1),work(m - kb + j1),ka1)
                    end do
                    ! apply rotations in 2nd set from both sides to diagonal
                    ! blocks
                    call la_qlar2v(nr,ab(ka1,j1),ab(ka1,j1 - 1),ab(ka,j1),inca, &
                              work(n + m - kb + j1),work(m - kb + j1),ka1)
                 end if
                 ! start applying rotations in 2nd set from the right
                 do l = ka - 1,kb - k + 1,-1
                    nrt = (j2 + l - 1)/ka1
                    j1t = j2 - (nrt - 1)*ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(l,j1t),inca,ab(l + 1,j1t - 1),inca, &
                              work(n + m - kb + j1t),work(m - kb + j1t),ka1)
                 end do
                 if (wantx) then
                    ! post-multiply x by product of rotations in 2nd set
                    do j = j1,j2,ka1
                       call la_qrot(nx,x(1,j),1,x(1,j - 1),1,work(n + m - kb + j),work( &
                                 m - kb + j))
                    end do
                 end if
              end do loop_690
              do k = 1,kb - 1
                 j2 = i + k + 1 - max(1,k + i0 - m + 1)*ka1
                 ! finish applying rotations in 1st set from the right
                 do l = kb - k,1,-1
                    nrt = (j2 + l - 1)/ka1
                    j1t = j2 - (nrt - 1)*ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(l,j1t),inca,ab(l + 1,j1t - 1),inca, &
                               work(n + j1t),work(j1t),ka1)
                 end do
              end do
              if (kb > 1) then
                 do j = 2,min(i + kb,m) - 2*ka - 1
                    work(n + j) = work(n + j + ka)
                    work(j) = work(j + ka)
                 end do
              end if
           else
              ! transform a, working with the lower triangle
              if (update) then
                 ! form  inv(s(i))**t * a * inv(s(i))
                 bii = bb(1,i)
                 do j = i1,i
                    ab(i - j + 1,j) = ab(i - j + 1,j)/bii
                 end do
                 do j = i,min(n,i + ka)
                    ab(j - i + 1,i) = ab(j - i + 1,i)/bii
                 end do
                 do k = i + 1,i + kbt
                    do j = k,i + kbt
                       ab(j - k + 1,k) = ab(j - k + 1,k) - bb(j - i + 1,i)*ab(k - i + 1,i) - bb(k - i + 1, &
                                 i)*ab(j - i + 1,i) + ab(1,i)*bb(j - i + 1,i)*bb(k - i + 1,i)
                    end do
                    do j = i + kbt + 1,min(n,i + ka)
                       ab(j - k + 1,k) = ab(j - k + 1,k) - bb(k - i + 1,i)*ab(j - i + 1,i)
                    end do
                 end do
                 do j = i1,i
                    do k = i + 1,min(j + ka,i + kbt)
                       ab(k - j + 1,j) = ab(k - j + 1,j) - bb(k - i + 1,i)*ab(i - j + 1,j)
                    end do
                 end do
                 if (wantx) then
                    ! post-multiply x by inv(s(i))
                    call la_qscal(nx,one/bii,x(1,i),1)
                    if (kbt > 0) call la_qger(nx,kbt,-one,x(1,i),1,bb(2,i),1,x(1, &
                              i + 1),ldx)
                 end if
                 ! store a(i,i1) in ra1 for use in next loop over k
                 ra1 = ab(i - i1 + 1,i1)
              end if
              ! generate and apply vectors of rotations to chase all the
              ! existing bulges ka positions up toward the top of the band
              loop_840: do k = 1,kb - 1
                 if (update) then
                    ! determine the rotations which would annihilate the bulge
                    ! which has in theory just been created
                    if (i + k - ka1 > 0 .and. i + k < m) then
                       ! generate rotation to annihilate a(i,i+k-ka-1)
                       call la_qlartg(ab(ka1 - k,i + k - ka),ra1,work(n + i + k - ka),work(i + k - &
                                 ka),ra)
                       ! create nonzero element a(i+k,i+k-ka-1) outside the
                       ! band and store it in work(m-kb+i+k)
                       t = -bb(k + 1,i)*ra1
                       work(m - kb + i + k) = work(n + i + k - ka)*t - work(i + k - ka)*ab(ka1,i + k - ka)

                       ab(ka1,i + k - ka) = work(i + k - ka)*t + work(n + i + k - ka)*ab(ka1,i + k - ka)

                       ra1 = ra
                    end if
                 end if
                 j2 = i + k + 1 - max(1,k + i0 - m + 1)*ka1
                 nr = (j2 + ka - 1)/ka1
                 j1 = j2 - (nr - 1)*ka1
                 if (update) then
                    j2t = min(j2,i - 2*ka + k - 1)
                 else
                    j2t = j2
                 end if
                 nrt = (j2t + ka - 1)/ka1
                 do j = j1,j2t,ka1
                    ! create nonzero element a(j+ka,j-1) outside the band
                    ! and store it in work(j)
                    work(j) = work(j)*ab(ka1,j - 1)
                    ab(ka1,j - 1) = work(n + j)*ab(ka1,j - 1)
                 end do
                 ! generate rotations in 1st set to annihilate elements which
                 ! have been created outside the band
                 if (nrt > 0) call la_qlargv(nrt,ab(ka1,j1),inca,work(j1),ka1,work(n + &
                           j1),ka1)
                 if (nr > 0) then
                    ! apply rotations in 1st set from the right
                    do l = 1,ka - 1
                       call la_qlartv(nr,ab(l + 1,j1),inca,ab(l + 2,j1 - 1),inca,work(n + &
                                 j1),work(j1),ka1)
                    end do
                    ! apply rotations in 1st set from both sides to diagonal
                    ! blocks
                    call la_qlar2v(nr,ab(1,j1),ab(1,j1 - 1),ab(2,j1 - 1),inca,work( &
                              n + j1),work(j1),ka1)
                 end if
                 ! start applying rotations in 1st set from the left
                 do l = ka - 1,kb - k + 1,-1
                    nrt = (j2 + l - 1)/ka1
                    j1t = j2 - (nrt - 1)*ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(ka1 - l + 1,j1t - ka1 + l),inca,ab(ka1 - l, &
                              j1t - ka1 + l),inca,work(n + j1t),work(j1t),ka1)
                 end do
                 if (wantx) then
                    ! post-multiply x by product of rotations in 1st set
                    do j = j1,j2,ka1
                       call la_qrot(nx,x(1,j),1,x(1,j - 1),1,work(n + j),work(j))

                    end do
                 end if
              end do loop_840
              if (update) then
                 if (i2 > 0 .and. kbt > 0) then
                    ! create nonzero element a(i+kbt,i+kbt-ka-1) outside the
                    ! band and store it in work(m-kb+i+kbt)
                    work(m - kb + i + kbt) = -bb(kbt + 1,i)*ra1
                 end if
              end if
              loop_880: do k = kb,1,-1
                 if (update) then
                    j2 = i + k + 1 - max(2,k + i0 - m)*ka1
                 else
                    j2 = i + k + 1 - max(1,k + i0 - m)*ka1
                 end if
                 ! finish applying rotations in 2nd set from the left
                 do l = kb - k,1,-1
                    nrt = (j2 + ka + l - 1)/ka1
                    j1t = j2 - (nrt - 1)*ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(ka1 - l + 1,j1t + l - 1),inca,ab(ka1 - l, &
                              j1t + l - 1),inca,work(n + m - kb + j1t + ka),work(m - kb + j1t + ka),ka1)
                 end do
                 nr = (j2 + ka - 1)/ka1
                 j1 = j2 - (nr - 1)*ka1
                 do j = j1,j2,ka1
                    work(m - kb + j) = work(m - kb + j + ka)
                    work(n + m - kb + j) = work(n + m - kb + j + ka)
                 end do
                 do j = j1,j2,ka1
                    ! create nonzero element a(j+ka,j-1) outside the band
                    ! and store it in work(m-kb+j)
                    work(m - kb + j) = work(m - kb + j)*ab(ka1,j - 1)
                    ab(ka1,j - 1) = work(n + m - kb + j)*ab(ka1,j - 1)
                 end do
                 if (update) then
                    if (i + k > ka1 .and. k <= kbt) work(m - kb + i + k - ka) = work(m - kb + i + k)
                 end if
              end do loop_880
              loop_920: do k = kb,1,-1
                 j2 = i + k + 1 - max(1,k + i0 - m)*ka1
                 nr = (j2 + ka - 1)/ka1
                 j1 = j2 - (nr - 1)*ka1
                 if (nr > 0) then
                    ! generate rotations in 2nd set to annihilate elements
                    ! which have been created outside the band
                    call la_qlargv(nr,ab(ka1,j1),inca,work(m - kb + j1),ka1,work(n + m - &
                              kb + j1),ka1)
                    ! apply rotations in 2nd set from the right
                    do l = 1,ka - 1
                       call la_qlartv(nr,ab(l + 1,j1),inca,ab(l + 2,j1 - 1),inca,work(n + &
                                 m - kb + j1),work(m - kb + j1),ka1)
                    end do
                    ! apply rotations in 2nd set from both sides to diagonal
                    ! blocks
                    call la_qlar2v(nr,ab(1,j1),ab(1,j1 - 1),ab(2,j1 - 1),inca,work( &
                              n + m - kb + j1),work(m - kb + j1),ka1)
                 end if
                 ! start applying rotations in 2nd set from the left
                 do l = ka - 1,kb - k + 1,-1
                    nrt = (j2 + l - 1)/ka1
                    j1t = j2 - (nrt - 1)*ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(ka1 - l + 1,j1t - ka1 + l),inca,ab(ka1 - l, &
                              j1t - ka1 + l),inca,work(n + m - kb + j1t),work(m - kb + j1t),ka1)
                 end do
                 if (wantx) then
                    ! post-multiply x by product of rotations in 2nd set
                    do j = j1,j2,ka1
                       call la_qrot(nx,x(1,j),1,x(1,j - 1),1,work(n + m - kb + j),work( &
                                 m - kb + j))
                    end do
                 end if
              end do loop_920
              do k = 1,kb - 1
                 j2 = i + k + 1 - max(1,k + i0 - m + 1)*ka1
                 ! finish applying rotations in 1st set from the left
                 do l = kb - k,1,-1
                    nrt = (j2 + l - 1)/ka1
                    j1t = j2 - (nrt - 1)*ka1
                    if (nrt > 0) call la_qlartv(nrt,ab(ka1 - l + 1,j1t - ka1 + l),inca,ab(ka1 - l, &
                              j1t - ka1 + l),inca,work(n + j1t),work(j1t),ka1)
                 end do
              end do
              if (kb > 1) then
                 do j = 2,min(i + kb,m) - 2*ka - 1
                    work(n + j) = work(n + j + ka)
                    work(j) = work(j + ka)
                 end do
              end if
           end if
           go to 490
     end subroutine la_qsbgst

     !> DSBGV: computes all the eigenvalues, and optionally, the eigenvectors
     !> of a real generalized symmetric-definite banded eigenproblem, of
     !> the form A*x=(lambda)*B*x. Here A and B are assumed to be symmetric
     !> and banded, and B is also positive definite.

     pure subroutine la_qsbgv(jobz,uplo,n,ka,kb,ab,ldab,bb,ldbb,w,z,ldz,work, &
               info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ka,kb,ldab,ldbb,ldz,n
           ! Array Arguments
           real(qp),intent(inout) :: ab(ldab,*),bb(ldbb,*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: upper,wantz
           character :: vect
           integer(ilp) :: iinfo,inde,indwrk
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           upper = la_lsame(uplo,'U')
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (upper .or. la_lsame(uplo,'L'))) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ka < 0) then
              info = -4
           else if (kb < 0 .or. kb > ka) then
              info = -5
           else if (ldab < ka + 1) then
              info = -7
           else if (ldbb < kb + 1) then
              info = -9
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -12
           end if
           if (info /= 0) then
              call la_xerbla('DSBGV ',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! form a split cholesky factorization of b.
           call la_qpbstf(uplo,n,kb,bb,ldbb,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem.
           inde = 1
           indwrk = inde + n
           call la_qsbgst(jobz,uplo,n,ka,kb,ab,ldab,bb,ldbb,z,ldz,work(indwrk), &
                     iinfo)
           ! reduce to tridiagonal form.
           if (wantz) then
              vect = 'U'
           else
              vect = 'N'
           end if
           call la_qsbtrd(vect,uplo,n,ka,ab,ldab,w,work(inde),z,ldz,work(indwrk) &
                     ,iinfo)
           ! for eigenvalues only, call la_qsterf.  for eigenvectors, call la_dsteqr.
           if (.not. wantz) then
              call la_qsterf(n,w,work(inde),info)
           else
              call la_qsteqr(jobz,n,w,work(inde),z,ldz,work(indwrk),info)
           end if
           return
     end subroutine la_qsbgv

     !> DSBGVD: computes all the eigenvalues, and optionally, the eigenvectors
     !> of a real generalized symmetric-definite banded eigenproblem, of the
     !> form A*x=(lambda)*B*x.  Here A and B are assumed to be symmetric and
     !> banded, and B is also positive definite.  If eigenvectors are
     !> desired, it uses a divide and conquer algorithm.
     !> The divide and conquer algorithm makes very mild assumptions about
     !> floating point arithmetic. It will work on machines with a guard
     !> digit in add/subtract, or on those binary machines without guard
     !> digits which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or
     !> Cray-2. It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.

     pure subroutine la_qsbgvd(jobz,uplo,n,ka,kb,ab,ldab,bb,ldbb,w,z,ldz,work, &
               lwork,iwork,liwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ka,kb,ldab,ldbb,ldz,liwork,lwork,n
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: ab(ldab,*),bb(ldbb,*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,upper,wantz
           character :: vect
           integer(ilp) :: iinfo,inde,indwk2,indwrk,liwmin,llwrk2,lwmin
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1 .or. liwork == -1)
           info = 0
           if (n <= 1) then
              liwmin = 1
              lwmin = 1
           else if (wantz) then
              liwmin = 3 + 5*n
              lwmin = 1 + 5*n + 2*n**2
           else
              liwmin = 1
              lwmin = 2*n
           end if
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (upper .or. la_lsame(uplo,'L'))) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ka < 0) then
              info = -4
           else if (kb < 0 .or. kb > ka) then
              info = -5
           else if (ldab < ka + 1) then
              info = -7
           else if (ldbb < kb + 1) then
              info = -9
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -12
           end if
           if (info == 0) then
              work(1) = lwmin
              iwork(1) = liwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -14
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -16
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSBGVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! form a split cholesky factorization of b.
           call la_qpbstf(uplo,n,kb,bb,ldbb,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem.
           inde = 1
           indwrk = inde + n
           indwk2 = indwrk + n*n
           llwrk2 = lwork - indwk2 + 1
           call la_qsbgst(jobz,uplo,n,ka,kb,ab,ldab,bb,ldbb,z,ldz,work,iinfo)

           ! reduce to tridiagonal form.
           if (wantz) then
              vect = 'U'
           else
              vect = 'N'
           end if
           call la_qsbtrd(vect,uplo,n,ka,ab,ldab,w,work(inde),z,ldz,work(indwrk) &
                     ,iinfo)
           ! for eigenvalues only, call la_qsterf. for eigenvectors, call la_dstedc.
           if (.not. wantz) then
              call la_qsterf(n,w,work(inde),info)
           else
              call la_qstedc('I',n,w,work(inde),work(indwrk),n,work(indwk2), &
                        llwrk2,iwork,liwork,info)
              call la_qgemm('N','N',n,n,n,one,z,ldz,work(indwrk),n,zero,work( &
                        indwk2),n)
              call la_qlacpy('A',n,n,work(indwk2),n,z,ldz)
           end if
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qsbgvd

     !> DSBGVX: computes selected eigenvalues, and optionally, eigenvectors
     !> of a real generalized symmetric-definite banded eigenproblem, of
     !> the form A*x=(lambda)*B*x.  Here A and B are assumed to be symmetric
     !> and banded, and B is also positive definite.  Eigenvalues and
     !> eigenvectors can be selected by specifying either all eigenvalues,
     !> a range of values or a range of indices for the desired eigenvalues.

     pure subroutine la_qsbgvx(jobz,range,uplo,n,ka,kb,ab,ldab,bb,ldbb,q,ldq,vl, &
               vu,il,iu,abstol,m,w,z,ldz,work,iwork,ifail,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,iu,ka,kb,ldab,ldbb,ldq,ldz,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: ifail(*),iwork(*)
           real(qp),intent(inout) :: ab(ldab,*),bb(ldbb,*)
           real(qp),intent(out) :: q(ldq,*),w(*),work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,test,upper,valeig,wantz
           character :: order,vect
           integer(ilp) :: i,iinfo,indd,inde,indee,indibl,indisp,indiwo,indwrk,itmp1,j, &
                     jj,nsplit
           real(qp) :: tmp1
           ! Intrinsic Functions
           intrinsic :: min
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           upper = la_lsame(uplo,'U')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (.not. (upper .or. la_lsame(uplo,'L'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ka < 0) then
              info = -5
           else if (kb < 0 .or. kb > ka) then
              info = -6
           else if (ldab < ka + 1) then
              info = -8
           else if (ldbb < kb + 1) then
              info = -10
           else if (ldq < 1 .or. (wantz .and. ldq < n)) then
              info = -12
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -14
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -15
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -16
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -21
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSBGVX',-info)
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) return
           ! form a split cholesky factorization of b.
           call la_qpbstf(uplo,n,kb,bb,ldbb,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem.
           call la_qsbgst(jobz,uplo,n,ka,kb,ab,ldab,bb,ldbb,q,ldq,work,iinfo)

           ! reduce symmetric band matrix to tridiagonal form.
           indd = 1
           inde = indd + n
           indwrk = inde + n
           if (wantz) then
              vect = 'U'
           else
              vect = 'N'
           end if
           call la_qsbtrd(vect,uplo,n,ka,ab,ldab,work(indd),work(inde),q,ldq, &
                     work(indwrk),iinfo)
           ! if all eigenvalues are desired and abstol is less than or equal
           ! to zero, then call la_qsterf or la_dsteqr.  if this fails for some
           ! eigenvalue, then try la_qstebz.
           test = .false.
           if (indeig) then
              if (il == 1 .and. iu == n) then
                 test = .true.
              end if
           end if
           if ((alleig .or. test) .and. (abstol <= zero)) then
              call la_qcopy(n,work(indd),1,w,1)
              indee = indwrk + 2*n
              call la_qcopy(n - 1,work(inde),1,work(indee),1)
              if (.not. wantz) then
                 call la_qsterf(n,w,work(indee),info)
              else
                 call la_qlacpy('A',n,n,q,ldq,z,ldz)
                 call la_qsteqr(jobz,n,w,work(indee),z,ldz,work(indwrk),info)

                 if (info == 0) then
                    do i = 1,n
                       ifail(i) = 0
                    end do
                 end if
              end if
              if (info == 0) then
                 m = n
                 go to 30
              end if
              info = 0
           end if
           ! otherwise, call la_qstebz and, if eigenvectors are desired,
           ! call la_qstein.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           indibl = 1
           indisp = indibl + n
           indiwo = indisp + n
           call la_qstebz(range,order,n,vl,vu,il,iu,abstol,work(indd),work(inde), &
            m,nsplit,w,iwork(indibl),iwork(indisp),work(indwrk),iwork(indiwo),info)

           if (wantz) then
              call la_qstein(n,work(indd),work(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,work(indwrk),iwork(indiwo),ifail,info)
              ! apply transformation matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_qstein.
              do j = 1,m
                 call la_qcopy(n,z(1,j),1,work(1),1)
                 call la_qgemv('N',n,n,one,q,ldq,work,1,zero,z(1,j),1)
              end do
           end if
           30 continue
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    itmp1 = iwork(indibl + i - 1)
                    w(i) = w(j)
                    iwork(indibl + i - 1) = iwork(indibl + j - 1)
                    w(j) = tmp1
                    iwork(indibl + j - 1) = itmp1
                    call la_qswap(n,z(1,i),1,z(1,j),1)
                    if (info /= 0) then
                       itmp1 = ifail(i)
                       ifail(i) = ifail(j)
                       ifail(j) = itmp1
                    end if
                 end if
              end do
           end if
           return
     end subroutine la_qsbgvx

     !> DSBTRD: reduces a real symmetric band matrix A to symmetric
     !> tridiagonal form T by an orthogonal similarity transformation:
     !> Q**T * A * Q = T.

     pure subroutine la_qsbtrd(vect,uplo,n,kd,ab,ldab,d,e,q,ldq,work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo,vect
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kd,ldab,ldq,n
           ! Array Arguments
           real(qp),intent(inout) :: ab(ldab,*),q(ldq,*)
           real(qp),intent(out) :: d(*),e(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: initq,upper,wantq
           integer(ilp) :: i,i2,ibl,inca,incx,iqaend,iqb,iqend,j,j1,j1end,j1inc,j2, &
                     jend,jin,jinc,k,kd1,kdm1,kdn,l,last,lend,nq,nr,nrt
           real(qp) :: temp
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters
           initq = la_lsame(vect,'V')
           wantq = initq .or. la_lsame(vect,'U')
           upper = la_lsame(uplo,'U')
           kd1 = kd + 1
           kdm1 = kd - 1
           incx = ldab - 1
           iqend = 1
           info = 0
           if (.not. wantq .and. .not. la_lsame(vect,'N')) then
              info = -1
           else if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (kd < 0) then
              info = -4
           else if (ldab < kd1) then
              info = -6
           else if (ldq < max(1,n) .and. wantq) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('DSBTRD',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! initialize q to the unit matrix, if needed
           if (initq) call la_qlaset('FULL',n,n,zero,one,q,ldq)
           ! wherever possible, plane rotations are generated and applied in
           ! vector operations of length nr over the index set j1:j2:kd1.
           ! the cosines and sines of the plane rotations are stored in the
           ! arrays d and work.
           inca = kd1*ldab
           kdn = min(n - 1,kd)
           if (upper) then
              if (kd > 1) then
                 ! reduce to tridiagonal form, working with upper triangle
                 nr = 0
                 j1 = kdn + 2
                 j2 = 1
                 loop_90: do i = 1,n - 2
                    ! reduce i-th row of matrix to tridiagonal form
                    loop_80: do k = kdn + 1,2,-1
                       j1 = j1 + kdn
                       j2 = j2 + kdn
                       if (nr > 0) then
                          ! generate plane rotations to annihilate nonzero
                          ! elements which have been created outside the band
                          call la_qlargv(nr,ab(1,j1 - 1),inca,work(j1),kd1,d(j1), &
                                    kd1)
                          ! apply rotations from the right
                          ! dependent on the the number of diagonals either
                          ! la_qlartv or la_qrot is used
                          if (nr >= 2*kd - 1) then
                             do l = 1,kd - 1
                                call la_qlartv(nr,ab(l + 1,j1 - 1),inca,ab(l,j1),inca, &
                                          d(j1),work(j1),kd1)
                             end do
                          else
                             jend = j1 + (nr - 1)*kd1
                             do jinc = j1,jend,kd1
                                call la_qrot(kdm1,ab(2,jinc - 1),1,ab(1,jinc),1,d( &
                                          jinc),work(jinc))
                             end do
                          end if
                       end if
                       if (k > 2) then
                          if (k <= n - i + 1) then
                             ! generate plane rotation to annihilate a(i,i+k-1)
                             ! within the band
                             call la_qlartg(ab(kd - k + 3,i + k - 2),ab(kd - k + 2,i + k - 1),d(i + k - &
                                       1),work(i + k - 1),temp)
                             ab(kd - k + 3,i + k - 2) = temp
                             ! apply rotation from the right
                             call la_qrot(k - 3,ab(kd - k + 4,i + k - 2),1,ab(kd - k + 3,i + k - 1),1, &
                                        d(i + k - 1),work(i + k - 1))
                          end if
                          nr = nr + 1
                          j1 = j1 - kdn - 1
                       end if
                       ! apply plane rotations from both sides to diagonal
                       ! blocks
                       if (nr > 0) call la_qlar2v(nr,ab(kd1,j1 - 1),ab(kd1,j1),ab(kd, &
                                 j1),inca,d(j1),work(j1),kd1)
                       ! apply plane rotations from the left
                       if (nr > 0) then
                          if (2*kd - 1 < nr) then
                          ! dependent on the the number of diagonals either
                          ! la_qlartv or la_qrot is used
                             do l = 1,kd - 1
                                if (j2 + l > n) then
                                   nrt = nr - 1
                                else
                                   nrt = nr
                                end if
                                if (nrt > 0) call la_qlartv(nrt,ab(kd - l,j1 + l),inca,ab(kd - &
                                          l + 1,j1 + l),inca,d(j1),work(j1),kd1)
                             end do
                          else
                             j1end = j1 + kd1*(nr - 2)
                             if (j1end >= j1) then
                                do jin = j1,j1end,kd1
                                   call la_qrot(kd - 1,ab(kd - 1,jin + 1),incx,ab(kd,jin + 1) &
                                             ,incx,d(jin),work(jin))
                                end do
                             end if
                             lend = min(kdm1,n - j2)
                             last = j1end + kd1
                             if (lend > 0) call la_qrot(lend,ab(kd - 1,last + 1),incx,ab(kd, &
                                       last + 1),incx,d(last),work(last))
                          end if
                       end if
                       if (wantq) then
                          ! accumulate product of plane rotations in q
                          if (initq) then
                       ! take advantage of the fact that q was
                       ! initially the identity matrix
                             iqend = max(iqend,j2)
                             i2 = max(0,k - 3)
                             iqaend = 1 + i*kd
                             if (k == 2) iqaend = iqaend + kd
                             iqaend = min(iqaend,iqend)
                             do j = j1,j2,kd1
                                ibl = i - i2/kdm1
                                i2 = i2 + 1
                                iqb = max(1,j - ibl)
                                nq = 1 + iqaend - iqb
                                iqaend = min(iqaend + kd,iqend)
                                call la_qrot(nq,q(iqb,j - 1),1,q(iqb,j),1,d(j), &
                                          work(j))
                             end do
                          else
                             do j = j1,j2,kd1
                                call la_qrot(n,q(1,j - 1),1,q(1,j),1,d(j),work(j &
                                          ))
                             end do
                          end if
                       end if
                       if (j2 + kdn > n) then
                          ! adjust j2 to keep within the bounds of the matrix
                          nr = nr - 1
                          j2 = j2 - kdn - 1
                       end if
                       do j = j1,j2,kd1
                          ! create nonzero element a(j-1,j+kd) outside the band
                          ! and store it in work
                          work(j + kd) = work(j)*ab(1,j + kd)
                          ab(1,j + kd) = d(j)*ab(1,j + kd)
                       end do
                    end do loop_80
                 end do loop_90
              end if
              if (kd > 0) then
                 ! copy off-diagonal elements to e
                 do i = 1,n - 1
                    e(i) = ab(kd,i + 1)
                 end do
              else
                 ! set e to zero if original matrix was diagonal
                 do i = 1,n - 1
                    e(i) = zero
                 end do
              end if
              ! copy diagonal elements to d
              do i = 1,n
                 d(i) = ab(kd1,i)
              end do
           else
              if (kd > 1) then
                 ! reduce to tridiagonal form, working with lower triangle
                 nr = 0
                 j1 = kdn + 2
                 j2 = 1
                 loop_210: do i = 1,n - 2
                    ! reduce i-th column of matrix to tridiagonal form
                    loop_200: do k = kdn + 1,2,-1
                       j1 = j1 + kdn
                       j2 = j2 + kdn
                       if (nr > 0) then
                          ! generate plane rotations to annihilate nonzero
                          ! elements which have been created outside the band
                          call la_qlargv(nr,ab(kd1,j1 - kd1),inca,work(j1),kd1,d(j1) &
                                    ,kd1)
                          ! apply plane rotations from one side
                          ! dependent on the the number of diagonals either
                          ! la_qlartv or la_qrot is used
                          if (nr > 2*kd - 1) then
                             do l = 1,kd - 1
                                call la_qlartv(nr,ab(kd1 - l,j1 - kd1 + l),inca,ab(kd1 - l + 1, &
                                          j1 - kd1 + l),inca,d(j1),work(j1),kd1)
                             end do
                          else
                             jend = j1 + kd1*(nr - 1)
                             do jinc = j1,jend,kd1
                                call la_qrot(kdm1,ab(kd,jinc - kd),incx,ab(kd1,jinc - kd) &
                                          ,incx,d(jinc),work(jinc))
                             end do
                          end if
                       end if
                       if (k > 2) then
                          if (k <= n - i + 1) then
                             ! generate plane rotation to annihilate a(i+k-1,i)
                             ! within the band
                             call la_qlartg(ab(k - 1,i),ab(k,i),d(i + k - 1),work(i + k - 1 &
                                       ),temp)
                             ab(k - 1,i) = temp
                             ! apply rotation from the left
                             call la_qrot(k - 3,ab(k - 2,i + 1),ldab - 1,ab(k - 1,i + 1),ldab - 1, &
                                        d(i + k - 1),work(i + k - 1))
                          end if
                          nr = nr + 1
                          j1 = j1 - kdn - 1
                       end if
                       ! apply plane rotations from both sides to diagonal
                       ! blocks
                       if (nr > 0) call la_qlar2v(nr,ab(1,j1 - 1),ab(1,j1),ab(2,j1 - 1), &
                                  inca,d(j1),work(j1),kd1)
                       ! apply plane rotations from the right
                          ! dependent on the the number of diagonals either
                          ! la_qlartv or la_qrot is used
                       if (nr > 0) then
                          if (nr > 2*kd - 1) then
                             do l = 1,kd - 1
                                if (j2 + l > n) then
                                   nrt = nr - 1
                                else
                                   nrt = nr
                                end if
                                if (nrt > 0) call la_qlartv(nrt,ab(l + 2,j1 - 1),inca,ab(l + 1, &
                                           j1),inca,d(j1),work(j1),kd1)
                             end do
                          else
                             j1end = j1 + kd1*(nr - 2)
                             if (j1end >= j1) then
                                do j1inc = j1,j1end,kd1
                                   call la_qrot(kdm1,ab(3,j1inc - 1),1,ab(2,j1inc),1, &
                                             d(j1inc),work(j1inc))
                                end do
                             end if
                             lend = min(kdm1,n - j2)
                             last = j1end + kd1
                             if (lend > 0) call la_qrot(lend,ab(3,last - 1),1,ab(2,last), &
                                        1,d(last),work(last))
                          end if
                       end if
                       if (wantq) then
                          ! accumulate product of plane rotations in q
                          if (initq) then
                       ! take advantage of the fact that q was
                       ! initially the identity matrix
                             iqend = max(iqend,j2)
                             i2 = max(0,k - 3)
                             iqaend = 1 + i*kd
                             if (k == 2) iqaend = iqaend + kd
                             iqaend = min(iqaend,iqend)
                             do j = j1,j2,kd1
                                ibl = i - i2/kdm1
                                i2 = i2 + 1
                                iqb = max(1,j - ibl)
                                nq = 1 + iqaend - iqb
                                iqaend = min(iqaend + kd,iqend)
                                call la_qrot(nq,q(iqb,j - 1),1,q(iqb,j),1,d(j), &
                                          work(j))
                             end do
                          else
                             do j = j1,j2,kd1
                                call la_qrot(n,q(1,j - 1),1,q(1,j),1,d(j),work(j &
                                          ))
                             end do
                          end if
                       end if
                       if (j2 + kdn > n) then
                          ! adjust j2 to keep within the bounds of the matrix
                          nr = nr - 1
                          j2 = j2 - kdn - 1
                       end if
                       do j = j1,j2,kd1
                          ! create nonzero element a(j+kd,j-1) outside the
                          ! band and store it in work
                          work(j + kd) = work(j)*ab(kd1,j)
                          ab(kd1,j) = d(j)*ab(kd1,j)
                       end do
                    end do loop_200
                 end do loop_210
              end if
              if (kd > 0) then
                 ! copy off-diagonal elements to e
                 do i = 1,n - 1
                    e(i) = ab(2,i)
                 end do
              else
                 ! set e to zero if original matrix was diagonal
                 do i = 1,n - 1
                    e(i) = zero
                 end do
              end if
              ! copy diagonal elements to d
              do i = 1,n
                 d(i) = ab(1,i)
              end do
           end if
           return
     end subroutine la_qsbtrd

     !> DSPEV: computes all the eigenvalues and, optionally, eigenvectors of a
     !> real symmetric matrix A in packed storage.

     subroutine la_qspev(jobz,uplo,n,ap,w,z,ldz,work,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldz,n
           ! Array Arguments
           real(qp),intent(inout) :: ap(*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: wantz
           integer(ilp) :: iinfo,imax,inde,indtau,indwrk,iscale
           real(qp) :: anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum
           ! Intrinsic Functions
           intrinsic :: sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (la_lsame(uplo,'U') .or. la_lsame(uplo,'L'))) &
                     then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('DSPEV ',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              w(1) = ap(1)
              if (wantz) z(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = sqrt(bignum)
           ! scale matrix to allowable range, if necessary.
           anrm = la_qlansp('M',uplo,n,ap,work)
           iscale = 0
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              call la_qscal((n*(n + 1))/2,sigma,ap,1)
           end if
           ! call la_qsptrd to reduce symmetric packed matrix to tridiagonal form.
           inde = 1
           indtau = inde + n
           call la_qsptrd(uplo,n,ap,w,work(inde),work(indtau),iinfo)
           ! for eigenvalues only, call la_qsterf.  for eigenvectors, first call
           ! la_qopgtr to generate the orthogonal matrix, then call la_qsteqr.
           if (.not. wantz) then
              call la_qsterf(n,w,work(inde),info)
           else
              indwrk = indtau + n
              call la_qopgtr(uplo,n,ap,work(indtau),z,ldz,work(indwrk),iinfo)

              call la_qsteqr(jobz,n,w,work(inde),z,ldz,work(indtau),info)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           if (iscale == 1) then
              if (info == 0) then
                 imax = n
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           return
     end subroutine la_qspev

     !> DSPEVD: computes all the eigenvalues and, optionally, eigenvectors
     !> of a real symmetric matrix A in packed storage. If eigenvectors are
     !> desired, it uses a divide and conquer algorithm.
     !> The divide and conquer algorithm makes very mild assumptions about
     !> floating point arithmetic. It will work on machines with a guard
     !> digit in add/subtract, or on those binary machines without guard
     !> digits which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or
     !> Cray-2. It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.

     subroutine la_qspevd(jobz,uplo,n,ap,w,z,ldz,work,lwork,iwork,liwork,info)

        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldz,liwork,lwork,n
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: ap(*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,wantz
           integer(ilp) :: iinfo,inde,indtau,indwrk,iscale,liwmin,llwork,lwmin
           real(qp) :: anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum
           ! Intrinsic Functions
           intrinsic :: sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           lquery = (lwork == -1 .or. liwork == -1)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (la_lsame(uplo,'U') .or. la_lsame(uplo,'L'))) &
                     then
              info = -2
           else if (n < 0) then
              info = -3
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -7
           end if
           if (info == 0) then
              if (n <= 1) then
                 liwmin = 1
                 lwmin = 1
              else
                 if (wantz) then
                    liwmin = 3 + 5*n
                    lwmin = 1 + 6*n + n**2
                 else
                    liwmin = 1
                    lwmin = 2*n
                 end if
              end if
              iwork(1) = liwmin
              work(1) = lwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -9
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -11
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSPEVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              w(1) = ap(1)
              if (wantz) z(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = sqrt(bignum)
           ! scale matrix to allowable range, if necessary.
           anrm = la_qlansp('M',uplo,n,ap,work)
           iscale = 0
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              call la_qscal((n*(n + 1))/2,sigma,ap,1)
           end if
           ! call la_qsptrd to reduce symmetric packed matrix to tridiagonal form.
           inde = 1
           indtau = inde + n
           call la_qsptrd(uplo,n,ap,w,work(inde),work(indtau),iinfo)
           ! for eigenvalues only, call la_qsterf.  for eigenvectors, first call
           ! la_qstedc to generate the eigenvector matrix, work(indwrk), of the
           ! tridiagonal matrix, then call la_qopmtr to multiply it by the
           ! householder transformations represented in ap.
           if (.not. wantz) then
              call la_qsterf(n,w,work(inde),info)
           else
              indwrk = indtau + n
              llwork = lwork - indwrk + 1
              call la_qstedc('I',n,w,work(inde),z,ldz,work(indwrk),llwork,iwork, &
                        liwork,info)
              call la_qopmtr('L',uplo,'N',n,n,ap,work(indtau),z,ldz,work(indwrk), &
                         iinfo)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           if (iscale == 1) call la_qscal(n,one/sigma,w,1)
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qspevd

     !> DSPEVX: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric matrix A in packed storage.  Eigenvalues/vectors
     !> can be selected by specifying either a range of values or a range of
     !> indices for the desired eigenvalues.

     subroutine la_qspevx(jobz,range,uplo,n,ap,vl,vu,il,iu,abstol,m,w,z,ldz, &
               work,iwork,ifail,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,iu,ldz,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: ifail(*),iwork(*)
           real(qp),intent(inout) :: ap(*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,test,valeig,wantz
           character :: order
           integer(ilp) :: i,iinfo,imax,indd,inde,indee,indibl,indisp,indiwo,indtau, &
                     indwrk,iscale,itmp1,j,jj,nsplit
           real(qp) :: abstll,anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (.not. (la_lsame(uplo,'L') .or. la_lsame(uplo,'U'))) &
                     then
              info = -3
           else if (n < 0) then
              info = -4
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -7
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -8
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -9
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) info = -14
           end if
           if (info /= 0) then
              call la_xerbla('DSPEVX',-info)
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) return
           if (n == 1) then
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = ap(1)
              else
                 if (vl < ap(1) .and. vu >= ap(1)) then
                    m = 1
                    w(1) = ap(1)
                 end if
              end if
              if (wantz) z(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           abstll = abstol
           if (valeig) then
              vll = vl
              vuu = vu
           else
              vll = zero
              vuu = zero
           end if
           anrm = la_qlansp('M',uplo,n,ap,work)
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              call la_qscal((n*(n + 1))/2,sigma,ap,1)
              if (abstol > 0) abstll = abstol*sigma
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! call la_qsptrd to reduce symmetric packed matrix to tridiagonal form.
           indtau = 1
           inde = indtau + n
           indd = inde + n
           indwrk = indd + n
           call la_qsptrd(uplo,n,ap,work(indd),work(inde),work(indtau),iinfo)

           ! if all eigenvalues are desired and abstol is less than or equal
           ! to zero, then call la_qsterf or la_qopgtr and la_dsteqr.  if this fails
           ! for some eigenvalue, then try la_qstebz.
           test = .false.
           if (indeig) then
              if (il == 1 .and. iu == n) then
                 test = .true.
              end if
           end if
           if ((alleig .or. test) .and. (abstol <= zero)) then
              call la_qcopy(n,work(indd),1,w,1)
              indee = indwrk + 2*n
              if (.not. wantz) then
                 call la_qcopy(n - 1,work(inde),1,work(indee),1)
                 call la_qsterf(n,w,work(indee),info)
              else
                 call la_qopgtr(uplo,n,ap,work(indtau),z,ldz,work(indwrk),iinfo)

                 call la_qcopy(n - 1,work(inde),1,work(indee),1)
                 call la_qsteqr(jobz,n,w,work(indee),z,ldz,work(indwrk),info)

                 if (info == 0) then
                    do i = 1,n
                       ifail(i) = 0
                    end do
                 end if
              end if
              if (info == 0) then
                 m = n
                 go to 20
              end if
              info = 0
           end if
           ! otherwise, call la_qstebz and, if eigenvectors are desired, la_dstein.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           indibl = 1
           indisp = indibl + n
           indiwo = indisp + n
           call la_qstebz(range,order,n,vll,vuu,il,iu,abstll,work(indd),work(inde &
           ),m,nsplit,w,iwork(indibl),iwork(indisp),work(indwrk),iwork(indiwo),info &
                     )
           if (wantz) then
              call la_qstein(n,work(indd),work(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,work(indwrk),iwork(indiwo),ifail,info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_qstein.
              call la_qopmtr('L',uplo,'N',n,m,ap,work(indtau),z,ldz,work(indwrk), &
                         iinfo)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           20 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    itmp1 = iwork(indibl + i - 1)
                    w(i) = w(j)
                    iwork(indibl + i - 1) = iwork(indibl + j - 1)
                    w(j) = tmp1
                    iwork(indibl + j - 1) = itmp1
                    call la_qswap(n,z(1,i),1,z(1,j),1)
                    if (info /= 0) then
                       itmp1 = ifail(i)
                       ifail(i) = ifail(j)
                       ifail(j) = itmp1
                    end if
                 end if
              end do
           end if
           return
     end subroutine la_qspevx

     !> DSPGST: reduces a real symmetric-definite generalized eigenproblem
     !> to standard form, using packed storage.
     !> If ITYPE = 1, the problem is A*x = lambda*B*x,
     !> and A is overwritten by inv(U**T)*A*inv(U) or inv(L)*A*inv(L**T)
     !> If ITYPE = 2 or 3, the problem is A*B*x = lambda*x or
     !> B*A*x = lambda*x, and A is overwritten by U*A*U**T or L**T*A*L.
     !> B must have been previously factorized as U**T*U or L*L**T by DPPTRF.

     pure subroutine la_qspgst(itype,uplo,n,ap,bp,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: itype,n
           ! Array Arguments
           real(qp),intent(inout) :: ap(*)
           real(qp),intent(in) :: bp(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,j1,j1j1,jj,k,k1,k1k1,kk
           real(qp) :: ajj,akk,bjj,bkk,ct
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (itype < 1 .or. itype > 3) then
              info = -1
           else if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('DSPGST',-info)
              return
           end if
           if (itype == 1) then
              if (upper) then
                 ! compute inv(u**t)*a*inv(u)
                 ! j1 and jj are the indices of a(1,j) and a(j,j)
                 jj = 0
                 do j = 1,n
                    j1 = jj + 1
                    jj = jj + j
                    ! compute the j-th column of the upper triangle of a
                    bjj = bp(jj)
                    call la_qtpsv(uplo,'TRANSPOSE','NONUNIT',j,bp,ap(j1),1)
                    call la_qspmv(uplo,j - 1,-one,ap,bp(j1),1,one,ap(j1),1)
                    call la_qscal(j - 1,one/bjj,ap(j1),1)
                    ap(jj) = (ap(jj) - la_qdot(j - 1,ap(j1),1,bp(j1),1))/ &
                              bjj
                 end do
              else
                 ! compute inv(l)*a*inv(l**t)
                 ! kk and k1k1 are the indices of a(k,k) and a(k+1,k+1)
                 kk = 1
                 do k = 1,n
                    k1k1 = kk + n - k + 1
                    ! update the lower triangle of a(k:n,k:n)
                    akk = ap(kk)
                    bkk = bp(kk)
                    akk = akk/bkk**2
                    ap(kk) = akk
                    if (k < n) then
                       call la_qscal(n - k,one/bkk,ap(kk + 1),1)
                       ct = -half*akk
                       call la_qaxpy(n - k,ct,bp(kk + 1),1,ap(kk + 1),1)
                       call la_qspr2(uplo,n - k,-one,ap(kk + 1),1,bp(kk + 1),1,ap(k1k1) &
                                  )
                       call la_qaxpy(n - k,ct,bp(kk + 1),1,ap(kk + 1),1)
                       call la_qtpsv(uplo,'NO TRANSPOSE','NON-UNIT',n - k,bp(k1k1),ap( &
                                 kk + 1),1)
                    end if
                    kk = k1k1
                 end do
              end if
           else
              if (upper) then
                 ! compute u*a*u**t
                 ! k1 and kk are the indices of a(1,k) and a(k,k)
                 kk = 0
                 do k = 1,n
                    k1 = kk + 1
                    kk = kk + k
                    ! update the upper triangle of a(1:k,1:k)
                    akk = ap(kk)
                    bkk = bp(kk)
                    call la_qtpmv(uplo,'NO TRANSPOSE','NON-UNIT',k - 1,bp,ap(k1),1)

                    ct = half*akk
                    call la_qaxpy(k - 1,ct,bp(k1),1,ap(k1),1)
                    call la_qspr2(uplo,k - 1,one,ap(k1),1,bp(k1),1,ap)
                    call la_qaxpy(k - 1,ct,bp(k1),1,ap(k1),1)
                    call la_qscal(k - 1,bkk,ap(k1),1)
                    ap(kk) = akk*bkk**2
                 end do
              else
                 ! compute l**t *a*l
                 ! jj and j1j1 are the indices of a(j,j) and a(j+1,j+1)
                 jj = 1
                 do j = 1,n
                    j1j1 = jj + n - j + 1
                    ! compute the j-th column of the lower triangle of a
                    ajj = ap(jj)
                    bjj = bp(jj)
                    ap(jj) = ajj*bjj + la_qdot(n - j,ap(jj + 1),1,bp(jj + 1),1)
                    call la_qscal(n - j,bjj,ap(jj + 1),1)
                    call la_qspmv(uplo,n - j,one,ap(j1j1),bp(jj + 1),1,one,ap(jj + 1), &
                              1)
                    call la_qtpmv(uplo,'TRANSPOSE','NON-UNIT',n - j + 1,bp(jj),ap(jj),1 &
                              )
                    jj = j1j1
                 end do
              end if
           end if
           return
     end subroutine la_qspgst

     !> DSPGV: computes all the eigenvalues and, optionally, the eigenvectors
     !> of a real generalized symmetric-definite eigenproblem, of the form
     !> A*x=(lambda)*B*x,  A*Bx=(lambda)*x,  or B*A*x=(lambda)*x.
     !> Here A and B are assumed to be symmetric, stored in packed format,
     !> and B is also positive definite.

     subroutine la_qspgv(itype,jobz,uplo,n,ap,bp,w,z,ldz,work,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: itype,ldz,n
           ! Array Arguments
           real(qp),intent(inout) :: ap(*),bp(*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: upper,wantz
           character :: trans
           integer(ilp) :: j,neig
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           upper = la_lsame(uplo,'U')
           info = 0
           if (itype < 1 .or. itype > 3) then
              info = -1
           else if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -2
           else if (.not. (upper .or. la_lsame(uplo,'L'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -9
           end if
           if (info /= 0) then
              call la_xerbla('DSPGV ',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! form a cholesky factorization of b.
           call la_qpptrf(uplo,n,bp,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem and solve.
           call la_qspgst(itype,uplo,n,ap,bp,info)
           call la_qspev(jobz,uplo,n,ap,w,z,ldz,work,info)
           if (wantz) then
              ! backtransform eigenvectors to the original problem.
              neig = n
              if (info > 0) neig = info - 1
              if (itype == 1 .or. itype == 2) then
                 ! for a*x=(lambda)*b*x and a*b*x=(lambda)*x;
                 ! backtransform eigenvectors: x = inv(l)**t*y or inv(u)*y
                 if (upper) then
                    trans = 'N'
                 else
                    trans = 'T'
                 end if
                 do j = 1,neig
                    call la_qtpsv(uplo,trans,'NON-UNIT',n,bp,z(1,j),1)
                 end do
              else if (itype == 3) then
                 ! for b*a*x=(lambda)*x;
                 ! backtransform eigenvectors: x = l*y or u**t*y
                 if (upper) then
                    trans = 'T'
                 else
                    trans = 'N'
                 end if
                 do j = 1,neig
                    call la_qtpmv(uplo,trans,'NON-UNIT',n,bp,z(1,j),1)
                 end do
              end if
           end if
           return
     end subroutine la_qspgv

     !> DSPGVD: computes all the eigenvalues, and optionally, the eigenvectors
     !> of a real generalized symmetric-definite eigenproblem, of the form
     !> A*x=(lambda)*B*x,  A*Bx=(lambda)*x,  or B*A*x=(lambda)*x.  Here A and
     !> B are assumed to be symmetric, stored in packed format, and B is also
     !> positive definite.
     !> If eigenvectors are desired, it uses a divide and conquer algorithm.
     !> The divide and conquer algorithm makes very mild assumptions about
     !> floating point arithmetic. It will work on machines with a guard
     !> digit in add/subtract, or on those binary machines without guard
     !> digits which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or
     !> Cray-2. It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.

     subroutine la_qspgvd(itype,jobz,uplo,n,ap,bp,w,z,ldz,work,lwork,iwork,liwork, &
                info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: itype,ldz,liwork,lwork,n
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: ap(*),bp(*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: lquery,upper,wantz
           character :: trans
           integer(ilp) :: j,liwmin,lwmin,neig
           ! Intrinsic Functions
           intrinsic :: real,max
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1 .or. liwork == -1)
           info = 0
           if (itype < 1 .or. itype > 3) then
              info = -1
           else if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -2
           else if (.not. (upper .or. la_lsame(uplo,'L'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -9
           end if
           if (info == 0) then
              if (n <= 1) then
                 liwmin = 1
                 lwmin = 1
              else
                 if (wantz) then
                    liwmin = 3 + 5*n
                    lwmin = 1 + 6*n + 2*n**2
                 else
                    liwmin = 1
                    lwmin = 2*n
                 end if
              end if
              work(1) = lwmin
              iwork(1) = liwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -11
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -13
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSPGVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! form a cholesky factorization of bp.
           call la_qpptrf(uplo,n,bp,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem and solve.
           call la_qspgst(itype,uplo,n,ap,bp,info)
           call la_qspevd(jobz,uplo,n,ap,w,z,ldz,work,lwork,iwork,liwork,info)

           lwmin = max(real(lwmin,KIND=qp),real(work(1),KIND=qp))
           liwmin = max(real(liwmin,KIND=qp),real(iwork(1),KIND=qp))
           if (wantz) then
              ! backtransform eigenvectors to the original problem.
              neig = n
              if (info > 0) neig = info - 1
              if (itype == 1 .or. itype == 2) then
                 ! for a*x=(lambda)*b*x and a*b*x=(lambda)*x;
                 ! backtransform eigenvectors: x = inv(l)**t *y or inv(u)*y
                 if (upper) then
                    trans = 'N'
                 else
                    trans = 'T'
                 end if
                 do j = 1,neig
                    call la_qtpsv(uplo,trans,'NON-UNIT',n,bp,z(1,j),1)
                 end do
              else if (itype == 3) then
                 ! for b*a*x=(lambda)*x;
                 ! backtransform eigenvectors: x = l*y or u**t *y
                 if (upper) then
                    trans = 'T'
                 else
                    trans = 'N'
                 end if
                 do j = 1,neig
                    call la_qtpmv(uplo,trans,'NON-UNIT',n,bp,z(1,j),1)
                 end do
              end if
           end if
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qspgvd

     !> DSPGVX: computes selected eigenvalues, and optionally, eigenvectors
     !> of a real generalized symmetric-definite eigenproblem, of the form
     !> A*x=(lambda)*B*x,  A*Bx=(lambda)*x,  or B*A*x=(lambda)*x.  Here A
     !> and B are assumed to be symmetric, stored in packed storage, and B
     !> is also positive definite.  Eigenvalues and eigenvectors can be
     !> selected by specifying either a range of values or a range of indices
     !> for the desired eigenvalues.

     subroutine la_qspgvx(itype,jobz,range,uplo,n,ap,bp,vl,vu,il,iu,abstol,m,w, &
               z,ldz,work,iwork,ifail,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,itype,iu,ldz,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: ifail(*),iwork(*)
           real(qp),intent(inout) :: ap(*),bp(*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
       ! =====================================================================
           ! Local Scalars
           logical(lk) :: alleig,indeig,upper,valeig,wantz
           character :: trans
           integer(ilp) :: j
           ! Intrinsic Functions
           intrinsic :: min
           ! Executable Statements
           ! test the input parameters.
           upper = la_lsame(uplo,'U')
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           info = 0
           if (itype < 1 .or. itype > 3) then
              info = -1
           else if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -2
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -3
           else if (.not. (upper .or. la_lsame(uplo,'L'))) then
              info = -4
           else if (n < 0) then
              info = -5
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) then
                    info = -9
                 end if
              else if (indeig) then
                 if (il < 1) then
                    info = -10
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -11
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -16
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSPGVX',-info)
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) return
           ! form a cholesky factorization of b.
           call la_qpptrf(uplo,n,bp,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem and solve.
           call la_qspgst(itype,uplo,n,ap,bp,info)
           call la_qspevx(jobz,range,uplo,n,ap,vl,vu,il,iu,abstol,m,w,z,ldz, &
                     work,iwork,ifail,info)
           if (wantz) then
              ! backtransform eigenvectors to the original problem.
              if (info > 0) m = info - 1
              if (itype == 1 .or. itype == 2) then
                 ! for a*x=(lambda)*b*x and a*b*x=(lambda)*x;
                 ! backtransform eigenvectors: x = inv(l)**t*y or inv(u)*y
                 if (upper) then
                    trans = 'N'
                 else
                    trans = 'T'
                 end if
                 do j = 1,m
                    call la_qtpsv(uplo,trans,'NON-UNIT',n,bp,z(1,j),1)
                 end do
              else if (itype == 3) then
                 ! for b*a*x=(lambda)*x;
                 ! backtransform eigenvectors: x = l*y or u**t*y
                 if (upper) then
                    trans = 'T'
                 else
                    trans = 'N'
                 end if
                 do j = 1,m
                    call la_qtpmv(uplo,trans,'NON-UNIT',n,bp,z(1,j),1)
                 end do
              end if
           end if
           return
     end subroutine la_qspgvx

     !> DSPTRD: reduces a real symmetric matrix A stored in packed form to
     !> symmetric tridiagonal form T by an orthogonal similarity
     !> transformation: Q**T * A * Q = T.

     pure subroutine la_qsptrd(uplo,n,ap,d,e,tau,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           real(qp),intent(inout) :: ap(*)
           real(qp),intent(out) :: d(*),e(*),tau(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i,i1,i1i1,ii
           real(qp) :: alpha,taui
           ! Executable Statements
           ! test the input parameters
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           end if
           if (info /= 0) then
              call la_xerbla('DSPTRD',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) return
           if (upper) then
              ! reduce the upper triangle of a.
              ! i1 is the index in ap of a(1,i+1).
              i1 = n*(n - 1)/2 + 1
              do i = n - 1,1,-1
                 ! generate elementary reflector h(i) = i - tau * v * v**t
                 ! to annihilate a(1:i-1,i+1)
                 call la_qlarfg(i,ap(i1 + i - 1),ap(i1),1,taui)
                 e(i) = ap(i1 + i - 1)
                 if (taui /= zero) then
                    ! apply h(i) from both sides to a(1:i,1:i)
                    ap(i1 + i - 1) = one
                    ! compute  y := tau * a * v  storing y in tau(1:i)
                    call la_qspmv(uplo,i,taui,ap,ap(i1),1,zero,tau,1)
                    ! compute  w := y - 1/2 * tau * (y**t *v) * v
                    alpha = -half*taui*la_qdot(i,tau,1,ap(i1),1)
                    call la_qaxpy(i,alpha,ap(i1),1,tau,1)
                    ! apply the transformation as a rank-2 update:
                       ! a := a - v * w**t - w * v**t
                    call la_qspr2(uplo,i,-one,ap(i1),1,tau,1,ap)
                    ap(i1 + i - 1) = e(i)
                 end if
                 d(i + 1) = ap(i1 + i)
                 tau(i) = taui
                 i1 = i1 - i
              end do
              d(1) = ap(1)
           else
              ! reduce the lower triangle of a. ii is the index in ap of
              ! a(i,i) and i1i1 is the index of a(i+1,i+1).
              ii = 1
              do i = 1,n - 1
                 i1i1 = ii + n - i + 1
                 ! generate elementary reflector h(i) = i - tau * v * v**t
                 ! to annihilate a(i+2:n,i)
                 call la_qlarfg(n - i,ap(ii + 1),ap(ii + 2),1,taui)
                 e(i) = ap(ii + 1)
                 if (taui /= zero) then
                    ! apply h(i) from both sides to a(i+1:n,i+1:n)
                    ap(ii + 1) = one
                    ! compute  y := tau * a * v  storing y in tau(i:n-1)
                    call la_qspmv(uplo,n - i,taui,ap(i1i1),ap(ii + 1),1,zero,tau(i), &
                              1)
                    ! compute  w := y - 1/2 * tau * (y**t *v) * v
                    alpha = -half*taui*la_qdot(n - i,tau(i),1,ap(ii + 1),1)
                    call la_qaxpy(n - i,alpha,ap(ii + 1),1,tau(i),1)
                    ! apply the transformation as a rank-2 update:
                       ! a := a - v * w**t - w * v**t
                    call la_qspr2(uplo,n - i,-one,ap(ii + 1),1,tau(i),1,ap(i1i1))

                    ap(ii + 1) = e(i)
                 end if
                 d(i) = ap(ii)
                 tau(i) = taui
                 ii = i1i1
              end do
              d(n) = ap(ii)
           end if
           return
     end subroutine la_qsptrd

     !> DSTEBZ: computes the eigenvalues of a symmetric tridiagonal
     !> matrix T.  The user may ask for all eigenvalues, all eigenvalues
     !> in the half-open interval (VL, VU], or the IL-th through IU-th
     !> eigenvalues.
     !> To avoid overflow, the matrix must be scaled so that its
     !> largest element is no greater than overflow**(1/2) * underflow**(1/4) in absolute value, and for greatest
     !> accuracy, it should not be much smaller than that.
     !> See W. Kahan "Accurate Eigenvalues of a Symmetric Tridiagonal
     !> Matrix", Report CS41, Computer Science Dept., Stanford
     !> University, July 21, 1966.

     pure subroutine la_qstebz(range,order,n,vl,vu,il,iu,abstol,d,e,m,nsplit,w, &
               iblock,isplit,work,iwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: order,range
           integer(ilp),intent(in) :: il,iu,n
           integer(ilp),intent(out) :: info,m,nsplit
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: iblock(*),isplit(*),iwork(*)
           real(qp),intent(in) :: d(*),e(*)
           real(qp),intent(out) :: w(*),work(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: fudge = 2.1_qp
           real(qp),parameter :: relfac = 2.0_qp

           ! Local Scalars
           logical(lk) :: ncnvrg,toofew
           integer(ilp) :: ib,ibegin,idiscl,idiscu,ie,iend,iinfo,im,in,ioff,iorder, &
                     iout,irange,itmax,itmp1,iw,iwoff,j,jb,jdisc,je,nb,nwl,nwu
           real(qp) :: atoli,bnorm,gl,gu,pivmin,rtoli,safemn,tmp1,tmp2,tnorm,ulp,wkill, &
                      wl,wlu,wu,wul
           ! Local Arrays
           integer(ilp) :: idumma(1)
           ! Intrinsic Functions
           intrinsic :: abs,int,log,max,min,sqrt
           ! Executable Statements
           info = 0
           ! decode range
           if (la_lsame(range,'A')) then
              irange = 1
           else if (la_lsame(range,'V')) then
              irange = 2
           else if (la_lsame(range,'I')) then
              irange = 3
           else
              irange = 0
           end if
           ! decode order
           if (la_lsame(order,'B')) then
              iorder = 2
           else if (la_lsame(order,'E')) then
              iorder = 1
           else
              iorder = 0
           end if
           ! check for errors
           if (irange <= 0) then
              info = -1
           else if (iorder <= 0) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (irange == 2) then
              if (vl >= vu) info = -5
           else if (irange == 3 .and. (il < 1 .or. il > max(1,n))) then
              info = -6
           else if (irange == 3 .and. (iu < min(n,il) .or. iu > n)) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('DSTEBZ',-info)
              return
           end if
           ! initialize error flags
           info = 0
           ncnvrg = .false.
           toofew = .false.
           ! quick return if possible
           m = 0
           if (n == 0) return
           ! simplifications:
           if (irange == 3 .and. il == 1 .and. iu == n) irange = 1
           ! get machine constants
           ! nb is the minimum vector length for vector bisection, or 0
           ! if only scalar is to be done.
           safemn = la_qlamch('S')
           ulp = la_qlamch('P')
           rtoli = ulp*relfac
           nb = la_ilaenv(1,'DSTEBZ',' ',n,-1,-1,-1)
           if (nb <= 1) nb = 0
           ! special case when n=1
           if (n == 1) then
              nsplit = 1
              isplit(1) = 1
              if (irange == 2 .and. (vl >= d(1) .or. vu < d(1))) then
                 m = 0
              else
                 w(1) = d(1)
                 iblock(1) = 1
                 m = 1
              end if
              return
           end if
           ! compute splitting points
           nsplit = 1
           work(n) = zero
           pivmin = one
           do j = 2,n
              tmp1 = e(j - 1)**2
              if (abs(d(j)*d(j - 1))*ulp**2 + safemn > tmp1) then
                 isplit(nsplit) = j - 1
                 nsplit = nsplit + 1
                 work(j - 1) = zero
              else
                 work(j - 1) = tmp1
                 pivmin = max(pivmin,tmp1)
              end if
           end do
           isplit(nsplit) = n
           pivmin = pivmin*safemn
           ! compute interval and atoli
           if (irange == 3) then
              ! range='i': compute the interval containing eigenvalues
                         ! il through iu.
              ! compute gershgorin interval for entire (split) matrix
              ! and use it as the initial interval
              gu = d(1)
              gl = d(1)
              tmp1 = zero
              do j = 1,n - 1
                 tmp2 = sqrt(work(j))
                 gu = max(gu,d(j) + tmp1 + tmp2)
                 gl = min(gl,d(j) - tmp1 - tmp2)
                 tmp1 = tmp2
              end do
              gu = max(gu,d(n) + tmp1)
              gl = min(gl,d(n) - tmp1)
              tnorm = max(abs(gl),abs(gu))
              gl = gl - fudge*tnorm*ulp*n - fudge*two*pivmin
              gu = gu + fudge*tnorm*ulp*n + fudge*pivmin
              ! compute iteration parameters
              itmax = int((log(tnorm + pivmin) - log(pivmin))/log(two),KIND=ilp) + 2
              if (abstol <= zero) then
                 atoli = ulp*tnorm
              else
                 atoli = abstol
              end if
              work(n + 1) = gl
              work(n + 2) = gl
              work(n + 3) = gu
              work(n + 4) = gu
              work(n + 5) = gl
              work(n + 6) = gu
              iwork(1) = -1
              iwork(2) = -1
              iwork(3) = n + 1
              iwork(4) = n + 1
              iwork(5) = il - 1
              iwork(6) = iu
              call la_qlaebz(3,itmax,n,2,2,nb,atoli,rtoli,pivmin,d,e,work,iwork( &
                        5),work(n + 1),work(n + 5),iout,iwork,w,iblock,iinfo)
              if (iwork(6) == iu) then
                 wl = work(n + 1)
                 wlu = work(n + 3)
                 nwl = iwork(1)
                 wu = work(n + 4)
                 wul = work(n + 2)
                 nwu = iwork(4)
              else
                 wl = work(n + 2)
                 wlu = work(n + 4)
                 nwl = iwork(2)
                 wu = work(n + 3)
                 wul = work(n + 1)
                 nwu = iwork(3)
              end if
              if (nwl < 0 .or. nwl >= n .or. nwu < 1 .or. nwu > n) then
                 info = 4
                 return
              end if
           else
              ! range='a' or 'v' -- set atoli
              tnorm = max(abs(d(1)) + abs(e(1)),abs(d(n)) + abs(e(n - 1)))
              do j = 2,n - 1
                 tnorm = max(tnorm,abs(d(j)) + abs(e(j - 1)) + abs(e(j)))
              end do
              if (abstol <= zero) then
                 atoli = ulp*tnorm
              else
                 atoli = abstol
              end if
              if (irange == 2) then
                 wl = vl
                 wu = vu
              else
                 wl = zero
                 wu = zero
              end if
           end if
           ! find eigenvalues -- loop over blocks and recompute nwl and nwu.
           ! nwl accumulates the number of eigenvalues .le. wl,
           ! nwu accumulates the number of eigenvalues .le. wu
           m = 0
           iend = 0
           info = 0
           nwl = 0
           nwu = 0
           loop_70: do jb = 1,nsplit
              ioff = iend
              ibegin = ioff + 1
              iend = isplit(jb)
              in = iend - ioff
              if (in == 1) then
                 ! special case -- in=1
                 if (irange == 1 .or. wl >= d(ibegin) - pivmin) nwl = nwl + 1
                 if (irange == 1 .or. wu >= d(ibegin) - pivmin) nwu = nwu + 1
                 if (irange == 1 .or. (wl < d(ibegin) - pivmin .and. wu >= d(ibegin) - pivmin)) &
                           then
                    m = m + 1
                    w(m) = d(ibegin)
                    iblock(m) = jb
                 end if
              else
                 ! general case -- in > 1
                 ! compute gershgorin interval
                 ! and use it as the initial interval
                 gu = d(ibegin)
                 gl = d(ibegin)
                 tmp1 = zero
                 do j = ibegin,iend - 1
                    tmp2 = abs(e(j))
                    gu = max(gu,d(j) + tmp1 + tmp2)
                    gl = min(gl,d(j) - tmp1 - tmp2)
                    tmp1 = tmp2
                 end do
                 gu = max(gu,d(iend) + tmp1)
                 gl = min(gl,d(iend) - tmp1)
                 bnorm = max(abs(gl),abs(gu))
                 gl = gl - fudge*bnorm*ulp*in - fudge*pivmin
                 gu = gu + fudge*bnorm*ulp*in + fudge*pivmin
                 ! compute atoli for the current submatrix
                 if (abstol <= zero) then
                    atoli = ulp*max(abs(gl),abs(gu))
                 else
                    atoli = abstol
                 end if
                 if (irange > 1) then
                    if (gu < wl) then
                       nwl = nwl + in
                       nwu = nwu + in
                       cycle loop_70
                    end if
                    gl = max(gl,wl)
                    gu = min(gu,wu)
                    if (gl >= gu) cycle loop_70
                 end if
                 ! set up initial interval
                 work(n + 1) = gl
                 work(n + in + 1) = gu
                 call la_qlaebz(1,0,in,in,1,nb,atoli,rtoli,pivmin,d(ibegin),e( &
                 ibegin),work(ibegin),idumma,work(n + 1),work(n + 2*in + 1),im,iwork,w(m + 1 &
                           ),iblock(m + 1),iinfo)
                 nwl = nwl + iwork(1)
                 nwu = nwu + iwork(in + 1)
                 iwoff = m - iwork(1)
                 ! compute eigenvalues
                 itmax = int((log(gu - gl + pivmin) - log(pivmin))/log(two),KIND=ilp) + &
                           2
                 call la_qlaebz(2,itmax,in,in,1,nb,atoli,rtoli,pivmin,d(ibegin),e( &
                  ibegin),work(ibegin),idumma,work(n + 1),work(n + 2*in + 1),iout,iwork,w( &
                            m + 1),iblock(m + 1),iinfo)
                 ! copy eigenvalues into w and iblock
                 ! use -jb for block number for unconverged eigenvalues.
                 do j = 1,iout
                    tmp1 = half*(work(j + n) + work(j + in + n))
                    ! flag non-convergence.
                    if (j > iout - iinfo) then
                       ncnvrg = .true.
                       ib = -jb
                    else
                       ib = jb
                    end if
                    do je = iwork(j) + 1 + iwoff,iwork(j + in) + iwoff
                       w(je) = tmp1
                       iblock(je) = ib
                    end do
                 end do
                 m = m + im
              end if
           end do loop_70
           ! if range='i', then (wl,wu) contains eigenvalues nwl+1,...,nwu
           ! if nwl+1 < il or nwu > iu, discard extra eigenvalues.
           if (irange == 3) then
              im = 0
              idiscl = il - 1 - nwl
              idiscu = nwu - iu
              if (idiscl > 0 .or. idiscu > 0) then
                 do je = 1,m
                    if (w(je) <= wlu .and. idiscl > 0) then
                       idiscl = idiscl - 1
                    else if (w(je) >= wul .and. idiscu > 0) then
                       idiscu = idiscu - 1
                    else
                       im = im + 1
                       w(im) = w(je)
                       iblock(im) = iblock(je)
                    end if
                 end do
                 m = im
              end if
              if (idiscl > 0 .or. idiscu > 0) then
                 ! code to deal with effects of bad arithmetic:
                 ! some low eigenvalues to be discarded are not in (wl,wlu],
                 ! or high eigenvalues to be discarded are not in (wul,wu]
                 ! so just kill off the smallest idiscl/largest idiscu
                 ! eigenvalues, by simply finding the smallest/largest
                 ! eigenvalue(s).
                 ! (if n(w) is monotone non-decreasing, this should never
                     ! happen.)
                 if (idiscl > 0) then
                    wkill = wu
                    do jdisc = 1,idiscl
                       iw = 0
                       do je = 1,m
                          if (iblock(je) /= 0 .and. (w(je) < wkill .or. iw == 0)) then
                             iw = je
                             wkill = w(je)
                          end if
                       end do
                       iblock(iw) = 0
                    end do
                 end if
                 if (idiscu > 0) then
                    wkill = wl
                    do jdisc = 1,idiscu
                       iw = 0
                       do je = 1,m
                          if (iblock(je) /= 0 .and. (w(je) > wkill .or. iw == 0)) then
                             iw = je
                             wkill = w(je)
                          end if
                       end do
                       iblock(iw) = 0
                    end do
                 end if
                 im = 0
                 do je = 1,m
                    if (iblock(je) /= 0) then
                       im = im + 1
                       w(im) = w(je)
                       iblock(im) = iblock(je)
                    end if
                 end do
                 m = im
              end if
              if (idiscl < 0 .or. idiscu < 0) then
                 toofew = .true.
              end if
           end if
           ! if order='b', do nothing -- the eigenvalues are already sorted
              ! by block.
           ! if order='e', sort the eigenvalues from smallest to largest
           if (iorder == 1 .and. nsplit > 1) then
              do je = 1,m - 1
                 ie = 0
                 tmp1 = w(je)
                 do j = je + 1,m
                    if (w(j) < tmp1) then
                       ie = j
                       tmp1 = w(j)
                    end if
                 end do
                 if (ie /= 0) then
                    itmp1 = iblock(ie)
                    w(ie) = w(je)
                    iblock(ie) = iblock(je)
                    w(je) = tmp1
                    iblock(je) = itmp1
                 end if
              end do
           end if
           info = 0
           if (ncnvrg) info = info + 1
           if (toofew) info = info + 2
           return
     end subroutine la_qstebz

     !> DSTEDC: computes all eigenvalues and, optionally, eigenvectors of a
     !> symmetric tridiagonal matrix using the divide and conquer method.
     !> The eigenvectors of a full or band real symmetric matrix can also be
     !> found if DSYTRD or DSPTRD or DSBTRD has been used to reduce this
     !> matrix to tridiagonal form.
     !> This code makes very mild assumptions about floating point
     !> arithmetic. It will work on machines with a guard digit in
     !> add/subtract, or on those binary machines without guard digits
     !> which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or Cray-2.
     !> It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.  See DLAED3 for details.

     pure subroutine la_qstedc(compz,n,d,e,z,ldz,work,lwork,iwork,liwork,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: compz
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldz,liwork,lwork,n
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: d(*),e(*),z(ldz,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: finish,i,icompz,ii,j,k,lgn,liwmin,lwmin,m,smlsiz,start, &
                     storez,strtrw
           real(qp) :: eps,orgnrm,p,tiny
           ! Intrinsic Functions
           intrinsic :: abs,real,int,log,max,mod,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           lquery = (lwork == -1 .or. liwork == -1)
           if (la_lsame(compz,'N')) then
              icompz = 0
           else if (la_lsame(compz,'V')) then
              icompz = 1
           else if (la_lsame(compz,'I')) then
              icompz = 2
           else
              icompz = -1
           end if
           if (icompz < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if ((ldz < 1) .or. (icompz > 0 .and. ldz < max(1,n))) then
              info = -6
           end if
           if (info == 0) then
              ! compute the workspace requirements
              smlsiz = la_ilaenv(9,'DSTEDC',' ',0,0,0,0)
              if (n <= 1 .or. icompz == 0) then
                 liwmin = 1
                 lwmin = 1
              else if (n <= smlsiz) then
                 liwmin = 1
                 lwmin = 2*(n - 1)
              else
                 lgn = int(log(real(n,KIND=qp))/log(two),KIND=ilp)
                 if (2**lgn < n) lgn = lgn + 1
                 if (2**lgn < n) lgn = lgn + 1
                 if (icompz == 1) then
                    lwmin = 1 + 3*n + 2*n*lgn + 4*n**2
                    liwmin = 6 + 6*n + 5*n*lgn
                 else if (icompz == 2) then
                    lwmin = 1 + 4*n + n**2
                    liwmin = 3 + 5*n
                 end if
              end if
              work(1) = lwmin
              iwork(1) = liwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -8
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -10
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSTEDC',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              if (icompz /= 0) z(1,1) = one
              return
           end if
           ! if the following conditional clause is removed, then the routine
           ! will use the divide and conquer routine to compute only the
           ! eigenvalues, which requires (3n + 3n**2) real workspace and
           ! (2 + 5n + 2n lg(n)) integer workspace.
           ! since on many architectures la_qsterf is much faster than any other
           ! algorithm for finding eigenvalues only, it is used here
           ! as the default. if the conditional clause is removed, then
           ! information on the size of workspace needs to be changed.
           ! if compz = 'n', use la_qsterf to compute the eigenvalues.
           if (icompz == 0) then
              call la_qsterf(n,d,e,info)
              go to 50
           end if
           ! if n is smaller than the minimum divide size (smlsiz+1), then
           ! solve the problem with another solver.
           if (n <= smlsiz) then
              call la_qsteqr(compz,n,d,e,z,ldz,work,info)
           else
              ! if compz = 'v', the z matrix must be stored elsewhere for later
              ! use.
              if (icompz == 1) then
                 storez = 1 + n*n
              else
                 storez = 1
              end if
              if (icompz == 2) then
                 call la_qlaset('FULL',n,n,zero,one,z,ldz)
              end if
              ! scale.
              orgnrm = la_qlanst('M',n,d,e)
              if (orgnrm == zero) go to 50
              eps = la_qlamch('EPSILON')
              start = 1
              ! while ( start <= n )
              10 continue
              if (start <= n) then
                 ! let finish be the position of the next subdiagonal entry
                 ! such that e( finish ) <= tiny or finish = n if no such
                 ! subdiagonal exists.  the matrix identified by the elements
                 ! between start and finish constitutes an independent
                 ! sub-problem.
                 finish = start
                 20 continue
                 if (finish < n) then
                    tiny = eps*sqrt(abs(d(finish)))*sqrt(abs(d(finish + 1)))
                    if (abs(e(finish)) > tiny) then
                       finish = finish + 1
                       go to 20
                    end if
                 end if
                 ! (sub) problem determined.  compute its size and solve it.
                 m = finish - start + 1
                 if (m == 1) then
                    start = finish + 1
                    go to 10
                 end if
                 if (m > smlsiz) then
                    ! scale.
                    orgnrm = la_qlanst('M',m,d(start),e(start))
                    call la_qlascl('G',0,0,orgnrm,one,m,1,d(start),m,info)
                    call la_qlascl('G',0,0,orgnrm,one,m - 1,1,e(start),m - 1,info)

                    if (icompz == 1) then
                       strtrw = 1
                    else
                       strtrw = start
                    end if
                    call la_qlaed0(icompz,n,m,d(start),e(start),z(strtrw,start), &
                              ldz,work(1),n,work(storez),iwork,info)
                    if (info /= 0) then
                       info = (info/(m + 1) + start - 1)*(n + 1) + mod(info, (m + 1)) + start - &
                                 1
                       go to 50
                    end if
                    ! scale back.
                    call la_qlascl('G',0,0,one,orgnrm,m,1,d(start),m,info)
                 else
                    if (icompz == 1) then
                       ! since qr won't update a z matrix which is larger than
                       ! the length of d, we must solve the sub-problem in a
                       ! workspace and then multiply back into z.
                       call la_qsteqr('I',m,d(start),e(start),work,m,work(m*m + 1), &
                                 info)
                       call la_qlacpy('A',n,m,z(1,start),ldz,work(storez),n)

                       call la_qgemm('N','N',n,m,m,one,work(storez),n,work,m,zero, &
                                 z(1,start),ldz)
                    else if (icompz == 2) then
                       call la_qsteqr('I',m,d(start),e(start),z(start,start),ldz, &
                                 work,info)
                    else
                       call la_qsterf(m,d(start),e(start),info)
                    end if
                    if (info /= 0) then
                       info = start*(n + 1) + finish
                       go to 50
                    end if
                 end if
                 start = finish + 1
                 go to 10
              end if
              ! endwhile
              if (icompz == 0) then
                ! use quick sort
                call la_qlasrt('I',n,d,info)
              else
                ! use selection sort to minimize swaps of eigenvectors
                do ii = 2,n
                   i = ii - 1
                   k = i
                   p = d(i)
                   do j = ii,n
                      if (d(j) < p) then
                         k = j
                         p = d(j)
                      end if
                   end do
                   if (k /= i) then
                      d(k) = d(i)
                      d(i) = p
                      call la_qswap(n,z(1,i),1,z(1,k),1)
                   end if
                end do
              end if
           end if
           50 continue
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qstedc

     !> DSTEGR: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric tridiagonal matrix T. Any such unreduced matrix has
     !> a well defined set of pairwise different real eigenvalues, the corresponding
     !> real eigenvectors are pairwise orthogonal.
     !> The spectrum may be computed either completely or partially by specifying
     !> either an interval (VL,VU] or a range of indices IL:IU for the desired
     !> eigenvalues.
     !> DSTEGR is a compatibility wrapper around the improved DSTEMR routine.
     !> See DSTEMR for further details.
     !> One important change is that the ABSTOL parameter no longer provides any
     !> benefit and hence is no longer used.
     !> Note : DSTEGR and DSTEMR work only on machines which follow
     !> IEEE-754 floating-point standard in their handling of infinities and
     !> NaNs.  Normal execution may create these exceptiona values and hence
     !> may abort due to a floating point exception in environments which
     !> do not conform to the IEEE-754 standard.

     pure subroutine la_qstegr(jobz,range,n,d,e,vl,vu,il,iu,abstol,m,w,z,ldz, &
               isuppz,work,lwork,iwork,liwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range
           integer(ilp),intent(in) :: il,iu,ldz,liwork,lwork,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: isuppz(*),iwork(*)
           real(qp),intent(inout) :: d(*),e(*)
           real(qp),intent(out) :: w(*),work(*)
           real(qp),intent(out) :: z(ldz,*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: tryrac
           ! Executable Statements
           info = 0
           tryrac = .false.
           call la_qstemr(jobz,range,n,d,e,vl,vu,il,iu,m,w,z,ldz,n,isuppz, &
                     tryrac,work,lwork,iwork,liwork,info)
     end subroutine la_qstegr

     !> DSTEIN: computes the eigenvectors of a real symmetric tridiagonal
     !> matrix T corresponding to specified eigenvalues, using inverse
     !> iteration.
     !> The maximum number of iterations allowed for each eigenvector is
     !> specified by an internal parameter MAXITS (currently set to 5).

     pure subroutine la_qstein(n,d,e,m,w,iblock,isplit,z,ldz,work,iwork,ifail, &
               info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldz,m,n
           ! Array Arguments
           integer(ilp),intent(in) :: iblock(*),isplit(*)
           integer(ilp),intent(out) :: ifail(*),iwork(*)
           real(qp),intent(in) :: d(*),e(*),w(*)
           real(qp),intent(out) :: work(*),z(ldz,*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: odm3 = 1.0e-3_qp
           real(qp),parameter :: odm1 = 1.0e-1_qp
           integer(ilp),parameter :: maxits = 5
           integer(ilp),parameter :: extra = 2

           ! Local Scalars
           integer(ilp) :: b1,blksiz,bn,gpind,i,iinfo,indrv1,indrv2,indrv3,indrv4, &
                     indrv5,its,j,j1,jblk,jmax,nblk,nrmchk
           real(qp) :: dtpcrt,eps,eps1,nrm,onenrm,ortol,pertol,scl,sep,tol,xj,xjm, &
                     ztr
           ! Local Arrays
           integer(ilp) :: iseed(4)
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           do i = 1,m
              ifail(i) = 0
           end do
           if (n < 0) then
              info = -1
           else if (m < 0 .or. m > n) then
              info = -4
           else if (ldz < max(1,n)) then
              info = -9
           else
              do j = 2,m
                 if (iblock(j) < iblock(j - 1)) then
                    info = -6
                    go to 30
                 end if
                 if (iblock(j) == iblock(j - 1) .and. w(j) < w(j - 1)) then
                    info = -5
                    go to 30
                 end if
              end do
              30 continue
           end if
           if (info /= 0) then
              call la_xerbla('DSTEIN',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. m == 0) then
              return
           else if (n == 1) then
              z(1,1) = one
              return
           end if
           ! get machine constants.
           eps = la_qlamch('PRECISION')
           ! initialize seed for random number generator la_qlarnv.
           do i = 1,4
              iseed(i) = 1
           end do
           ! initialize pointers.
           indrv1 = 0
           indrv2 = indrv1 + n
           indrv3 = indrv2 + n
           indrv4 = indrv3 + n
           indrv5 = indrv4 + n
           ! compute eigenvectors of matrix blocks.
           j1 = 1
           loop_160: do nblk = 1,iblock(m)
              ! find starting and ending indices of block nblk.
              if (nblk == 1) then
                 b1 = 1
              else
                 b1 = isplit(nblk - 1) + 1
              end if
              bn = isplit(nblk)
              blksiz = bn - b1 + 1
              if (blksiz == 1) go to 60
              gpind = j1
              ! compute reorthogonalization criterion and stopping criterion.
              onenrm = abs(d(b1)) + abs(e(b1))
              onenrm = max(onenrm,abs(d(bn)) + abs(e(bn - 1)))
              do i = b1 + 1,bn - 1
                 onenrm = max(onenrm,abs(d(i)) + abs(e(i - 1)) + abs(e(i)))
              end do
              ortol = odm3*onenrm
              dtpcrt = sqrt(odm1/blksiz)
              ! loop through eigenvalues of block nblk.
              60 continue
              jblk = 0
              loop_150: do j = j1,m
                 if (iblock(j) /= nblk) then
                    j1 = j
                    cycle loop_160
                 end if
                 jblk = jblk + 1
                 xj = w(j)
                 ! skip all the work if the block size is one.
                 if (blksiz == 1) then
                    work(indrv1 + 1) = one
                    go to 120
                 end if
                 ! if eigenvalues j and j-1 are too close, add a relatively
                 ! small perturbation.
                 if (jblk > 1) then
                    eps1 = abs(eps*xj)
                    pertol = ten*eps1
                    sep = xj - xjm
                    if (sep < pertol) xj = xjm + pertol
                 end if
                 its = 0
                 nrmchk = 0
                 ! get random starting vector.
                 call la_qlarnv(2,iseed,blksiz,work(indrv1 + 1))
                 ! copy the matrix t so it won't be destroyed in factorization.
                 call la_qcopy(blksiz,d(b1),1,work(indrv4 + 1),1)
                 call la_qcopy(blksiz - 1,e(b1),1,work(indrv2 + 2),1)
                 call la_qcopy(blksiz - 1,e(b1),1,work(indrv3 + 1),1)
                 ! compute lu factors with partial pivoting  ( pt = lu )
                 tol = zero
                 call la_qlagtf(blksiz,work(indrv4 + 1),xj,work(indrv2 + 2),work(indrv3 + &
                           1),tol,work(indrv5 + 1),iwork,iinfo)
                 ! update iteration count.
                 70 continue
                 its = its + 1
                 if (its > maxits) go to 100
                 ! normalize and scale the righthand side vector pb.
                 jmax = la_iqamax(blksiz,work(indrv1 + 1),1)
                 scl = blksiz*onenrm*max(eps,abs(work(indrv4 + blksiz)))/abs(work(indrv1 + &
                           jmax))
                 call la_qscal(blksiz,scl,work(indrv1 + 1),1)
                 ! solve the system lu = pb.
                 call la_qlagts(-1,blksiz,work(indrv4 + 1),work(indrv2 + 2),work(indrv3 + &
                           1),work(indrv5 + 1),iwork,work(indrv1 + 1),tol,iinfo)
                 ! reorthogonalize by modified gram-schmidt if eigenvalues are
                 ! close enough.
                 if (jblk == 1) go to 90
                 if (abs(xj - xjm) > ortol) gpind = j
                 if (gpind /= j) then
                    do i = gpind,j - 1
                       ztr = -la_qdot(blksiz,work(indrv1 + 1),1,z(b1,i),1)
                       call la_qaxpy(blksiz,ztr,z(b1,i),1,work(indrv1 + 1),1)
                    end do
                 end if
                 ! check the infinity norm of the iterate.
                 90 continue
                 jmax = la_iqamax(blksiz,work(indrv1 + 1),1)
                 nrm = abs(work(indrv1 + jmax))
                 ! continue for additional iterations after norm reaches
                 ! stopping criterion.
                 if (nrm < dtpcrt) go to 70
                 nrmchk = nrmchk + 1
                 if (nrmchk < extra + 1) go to 70
                 go to 110
                 ! if stopping criterion was not satisfied, update info and
                 ! store eigenvector number in array ifail.
                 100 continue
                 info = info + 1
                 ifail(info) = j
                 ! accept iterate as jth eigenvector.
                 110 continue
                 scl = one/la_qnrm2(blksiz,work(indrv1 + 1),1)
                 jmax = la_iqamax(blksiz,work(indrv1 + 1),1)
                 if (work(indrv1 + jmax) < zero) scl = -scl
                 call la_qscal(blksiz,scl,work(indrv1 + 1),1)
                 120 continue
                 do i = 1,n
                    z(i,j) = zero
                 end do
                 do i = 1,blksiz
                    z(b1 + i - 1,j) = work(indrv1 + i)
                 end do
                 ! save the shift to check eigenvalue spacing at next
                 ! iteration.
                 xjm = xj
              end do loop_150
           end do loop_160
           return
     end subroutine la_qstein

     !> DSTEMR: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric tridiagonal matrix T. Any such unreduced matrix has
     !> a well defined set of pairwise different real eigenvalues, the corresponding
     !> real eigenvectors are pairwise orthogonal.
     !> The spectrum may be computed either completely or partially by specifying
     !> either an interval (VL,VU] or a range of indices IL:IU for the desired
     !> eigenvalues.
     !> Depending on the number of desired eigenvalues, these are computed either
     !> by bisection or the dqds algorithm. Numerically orthogonal eigenvectors are
     !> computed by the use of various suitable L D L^T factorizations near clusters
     !> of close eigenvalues (referred to as RRRs, Relatively Robust
     !> Representations). An informal sketch of the algorithm follows.
     !> For each unreduced block (submatrix) of T,
     !> (a) Compute T - sigma I  = L D L^T, so that L and D
     !> define all the wanted eigenvalues to high relative accuracy.
     !> This means that small relative changes in the entries of D and L
     !> cause only small relative changes in the eigenvalues and
     !> eigenvectors. The standard (unfactored) representation of the
     !> tridiagonal matrix T does not have this property in general.
     !> (b) Compute the eigenvalues to suitable accuracy.
     !> If the eigenvectors are desired, the algorithm attains full
     !> accuracy of the computed eigenvalues only right before
     !> the corresponding vectors have to be computed, see steps c) and d).
     !> (c) For each cluster of close eigenvalues, select a new
     !> shift close to the cluster, find a new factorization, and refine
     !> the shifted eigenvalues to suitable accuracy.
     !> (d) For each eigenvalue with a large enough relative separation compute
     !> the corresponding eigenvector by forming a rank revealing twisted
     !> factorization. Go back to (c) for any clusters that remain.
     !> For more details, see:
     !> - Inderjit S. Dhillon and Beresford N. Parlett: "Multiple representations
     !> to compute orthogonal eigenvectors of symmetric tridiagonal matrices,"
     !> Linear Algebra and its Applications, 387(1), pp. 1-28, August 2004.
     !> - Inderjit Dhillon and Beresford Parlett: "Orthogonal Eigenvectors and
     !> Relative Gaps," SIAM Journal on Matrix Analysis and Applications, Vol. 25,
     !> 2004.  Also LAPACK Working Note 154.
     !> - Inderjit Dhillon: "A new O(n^2) algorithm for the symmetric
     !> tridiagonal eigenvalue/eigenvector problem",
     !> Computer Science Division Technical Report No. UCB/CSD-97-971,
     !> UC Berkeley, May 1997.
     !> Further Details
     !> 1.DSTEMR works only on machines which follow IEEE-754
     !> floating-point standard in their handling of infinities and NaNs.
     !> This permits the use of efficient inner loops avoiding a check for
     !> zero divisors.

     pure subroutine la_qstemr(jobz,range,n,d,e,vl,vu,il,iu,m,w,z,ldz,nzc, &
               isuppz,tryrac,work,lwork,iwork,liwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range
           logical(lk),intent(inout) :: tryrac
           integer(ilp),intent(in) :: il,iu,ldz,nzc,liwork,lwork,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: isuppz(*),iwork(*)
           real(qp),intent(inout) :: d(*),e(*)
           real(qp),intent(out) :: w(*),work(*)
           real(qp),intent(out) :: z(ldz,*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: minrgp = 1.0e-3_qp

           ! Local Scalars
           logical(lk) :: alleig,indeig,lquery,valeig,wantz,zquery
           integer(ilp) :: i,ibegin,iend,ifirst,iil,iindbl,iindw,iindwk,iinfo,iinspl, &
           iiu,ilast,in,indd,inde2,inderr,indgp,indgrs,indwrk,itmp,itmp2,j,jblk,jj, &
                     liwmin,lwmin,nsplit,nzcmin,offset,wbegin,wend
           real(qp) :: bignum,cs,eps,pivmin,r1,r2,rmax,rmin,rtol1,rtol2,safmin,scale, &
                     smlnum,sn,thresh,tmp,tnrm,wl,wu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lquery = ((lwork == -1) .or. (liwork == -1))
           zquery = (nzc == -1)
           ! la_qstemr needs work of size 6*n, iwork of size 3*n.
           ! in addition, la_qlarre needs work of size 6*n, iwork of size 5*n.
           ! furthermore, la_qlarrv needs work of size 12*n, iwork of size 7*n.
           if (wantz) then
              lwmin = 18*n
              liwmin = 10*n
           else
              ! need less workspace if only the eigenvalues are wanted
              lwmin = 12*n
              liwmin = 8*n
           end if
           wl = zero
           wu = zero
           iil = 0
           iiu = 0
           nsplit = 0
           if (valeig) then
              ! we do not reference vl, vu in the cases range = 'i','a'
              ! the interval (wl, wu] contains all the wanted eigenvalues.
              ! it is either given by the user or computed in la_qlarre.
              wl = vl
              wu = vu
           elseif (indeig) then
              ! we do not reference il, iu in the cases range = 'v','a'
              iil = il
              iiu = iu
           end if
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (valeig .and. n > 0 .and. wu <= wl) then
              info = -7
           else if (indeig .and. (iil < 1 .or. iil > n)) then
              info = -8
           else if (indeig .and. (iiu < iil .or. iiu > n)) then
              info = -9
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -13
           else if (lwork < lwmin .and. .not. lquery) then
              info = -17
           else if (liwork < liwmin .and. .not. lquery) then
              info = -19
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           if (info == 0) then
              work(1) = lwmin
              iwork(1) = liwmin
              if (wantz .and. alleig) then
                 nzcmin = n
              else if (wantz .and. valeig) then
                 call la_qlarrc('T',n,vl,vu,d,e,safmin,nzcmin,itmp,itmp2,info)

              else if (wantz .and. indeig) then
                 nzcmin = iiu - iil + 1
              else
                 ! wantz == false.
                 nzcmin = 0
              end if
              if (zquery .and. info == 0) then
                 z(1,1) = nzcmin
              else if (nzc < nzcmin .and. .not. zquery) then
                 info = -14
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSTEMR',-info)
              return
           else if (lquery .or. zquery) then
              return
           end if
           ! handle n = 0, 1, and 2 cases immediately
           m = 0
           if (n == 0) return
           if (n == 1) then
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = d(1)
              else
                 if (wl < d(1) .and. wu >= d(1)) then
                    m = 1
                    w(1) = d(1)
                 end if
              end if
              if (wantz .and. (.not. zquery)) then
                 z(1,1) = one
                 isuppz(1) = 1
                 isuppz(2) = 1
              end if
              return
           end if
           if (n == 2) then
              if (.not. wantz) then
                 call la_qlae2(d(1),e(1),d(2),r1,r2)
              else if (wantz .and. (.not. zquery)) then
                 call la_qlaev2(d(1),e(1),d(2),r1,r2,cs,sn)
              end if
              if (alleig .or. (valeig .and. (r2 > wl) .and. (r2 <= wu)) .or. (indeig .and. (iil == 1))) &
                        then
                 m = m + 1
                 w(m) = r2
                 if (wantz .and. (.not. zquery)) then
                    z(1,m) = -sn
                    z(2,m) = cs
                    ! note: at most one of sn and cs can be zero.
                    if (sn /= zero) then
                       if (cs /= zero) then
                          isuppz(2*m - 1) = 1
                          isuppz(2*m) = 2
                       else
                          isuppz(2*m - 1) = 1
                          isuppz(2*m) = 1
                       end if
                    else
                       isuppz(2*m - 1) = 2
                       isuppz(2*m) = 2
                    end if
                 end if
              end if
              if (alleig .or. (valeig .and. (r1 > wl) .and. (r1 <= wu)) .or. (indeig .and. (iiu == 2))) &
                        then
                 m = m + 1
                 w(m) = r1
                 if (wantz .and. (.not. zquery)) then
                    z(1,m) = cs
                    z(2,m) = sn
                    ! note: at most one of sn and cs can be zero.
                    if (sn /= zero) then
                       if (cs /= zero) then
                          isuppz(2*m - 1) = 1
                          isuppz(2*m) = 2
                       else
                          isuppz(2*m - 1) = 1
                          isuppz(2*m) = 1
                       end if
                    else
                       isuppz(2*m - 1) = 2
                       isuppz(2*m) = 2
                    end if
                 end if
              end if
           else
           ! continue with general n
              indgrs = 1
              inderr = 2*n + 1
              indgp = 3*n + 1
              indd = 4*n + 1
              inde2 = 5*n + 1
              indwrk = 6*n + 1
              iinspl = 1
              iindbl = n + 1
              iindw = 2*n + 1
              iindwk = 3*n + 1
              ! scale matrix to allowable range, if necessary.
              ! the allowable range is related to the pivmin parameter; see the
              ! comments in la_qlarrd.  the preference for scaling small values
              ! up is heuristic; we expect users' matrices not to be close to the
              ! rmax threshold.
              scale = one
              tnrm = la_qlanst('M',n,d,e)
              if (tnrm > zero .and. tnrm < rmin) then
                 scale = rmin/tnrm
              else if (tnrm > rmax) then
                 scale = rmax/tnrm
              end if
              if (scale /= one) then
                 call la_qscal(n,scale,d,1)
                 call la_qscal(n - 1,scale,e,1)
                 tnrm = tnrm*scale
                 if (valeig) then
                    ! if eigenvalues in interval have to be found,
                    ! scale (wl, wu] accordingly
                    wl = wl*scale
                    wu = wu*scale
                 end if
              end if
              ! compute the desired eigenvalues of the tridiagonal after splitting
              ! into smaller subblocks if the corresponding off-diagonal elements
              ! are small
              ! thresh is the splitting parameter for la_qlarre
              ! a negative thresh forces the old splitting criterion based on the
              ! size of the off-diagonal. a positive thresh switches to splitting
              ! which preserves relative accuracy.
              if (tryrac) then
                 ! test whether the matrix warrants the more expensive relative approach.
                 call la_qlarrr(n,d,e,iinfo)
              else
                 ! the user does not care about relative accurately eigenvalues
                 iinfo = -1
              end if
              ! set the splitting criterion
              if (iinfo == 0) then
                 thresh = eps
              else
                 thresh = -eps
                 ! relative accuracy is desired but t does not guarantee it
                 tryrac = .false.
              end if
              if (tryrac) then
                 ! copy original diagonal, needed to guarantee relative accuracy
                 call la_qcopy(n,d,1,work(indd),1)
              end if
              ! store the squares of the offdiagonal values of t
              do j = 1,n - 1
                 work(inde2 + j - 1) = e(j)**2
              end do
              ! set the tolerance parameters for bisection
              if (.not. wantz) then
                 ! la_qlarre computes the eigenvalues to full precision.
                 rtol1 = four*eps
                 rtol2 = four*eps
              else
                 ! la_qlarre computes the eigenvalues to less than full precision.
                 ! la_qlarrv will refine the eigenvalue approximations, and we can
                 ! need less accurate initial bisection in la_qlarre.
                 ! note: these settings do only affect the subset case and la_qlarre
                 rtol1 = sqrt(eps)
                 rtol2 = max(sqrt(eps)*5.0e-3_qp,four*eps)
              end if
              call la_qlarre(range,n,wl,wu,iil,iiu,d,e,work(inde2),rtol1,rtol2, &
              thresh,nsplit,iwork(iinspl),m,w,work(inderr),work(indgp),iwork(iindbl), &
              iwork(iindw),work(indgrs),pivmin,work(indwrk),iwork(iindwk),iinfo)

              if (iinfo /= 0) then
                 info = 10 + abs(iinfo)
                 return
              end if
              ! note that if range /= 'v', la_qlarre computes bounds on the desired
              ! part of the spectrum. all desired eigenvalues are contained in
              ! (wl,wu]
              if (wantz) then
                 ! compute the desired eigenvectors corresponding to the computed
                 ! eigenvalues
                 call la_qlarrv(n,wl,wu,d,e,pivmin,iwork(iinspl),m,1,m,minrgp, &
                 rtol1,rtol2,w,work(inderr),work(indgp),iwork(iindbl),iwork(iindw), &
                           work(indgrs),z,ldz,isuppz,work(indwrk),iwork(iindwk),iinfo)
                 if (iinfo /= 0) then
                    info = 20 + abs(iinfo)
                    return
                 end if
              else
                 ! la_qlarre computes eigenvalues of the (shifted) root representation
                 ! la_qlarrv returns the eigenvalues of the unshifted matrix.
                 ! however, if the eigenvectors are not desired by the user, we need
                 ! to apply the corresponding shifts from la_qlarre to obtain the
                 ! eigenvalues of the original matrix.
                 do j = 1,m
                    itmp = iwork(iindbl + j - 1)
                    w(j) = w(j) + e(iwork(iinspl + itmp - 1))
                 end do
              end if
              if (tryrac) then
                 ! refine computed eigenvalues so that they are relatively accurate
                 ! with respect to the original matrix t.
                 ibegin = 1
                 wbegin = 1
                 loop_39: do jblk = 1,iwork(iindbl + m - 1)
                    iend = iwork(iinspl + jblk - 1)
                    in = iend - ibegin + 1
                    wend = wbegin - 1
                    ! check if any eigenvalues have to be refined in this block
                    36 continue
                    if (wend < m) then
                       if (iwork(iindbl + wend) == jblk) then
                          wend = wend + 1
                          go to 36
                       end if
                    end if
                    if (wend < wbegin) then
                       ibegin = iend + 1
                       cycle loop_39
                    end if
                    offset = iwork(iindw + wbegin - 1) - 1
                    ifirst = iwork(iindw + wbegin - 1)
                    ilast = iwork(iindw + wend - 1)
                    rtol2 = four*eps
                    call la_qlarrj(in,work(indd + ibegin - 1),work(inde2 + ibegin - 1),ifirst, &
                    ilast,rtol2,offset,w(wbegin),work(inderr + wbegin - 1),work(indwrk),iwork( &
                               iindwk),pivmin,tnrm,iinfo)
                    ibegin = iend + 1
                    wbegin = wend + 1
                 end do loop_39
              end if
              ! if matrix was scaled, then rescale eigenvalues appropriately.
              if (scale /= one) then
                 call la_qscal(m,one/scale,w,1)
              end if
           end if
           ! if eigenvalues are not in increasing order, then sort them,
           ! possibly along with eigenvectors.
           if (nsplit > 1 .or. n == 2) then
              if (.not. wantz) then
                 call la_qlasrt('I',m,w,iinfo)
                 if (iinfo /= 0) then
                    info = 3
                    return
                 end if
              else
                 do j = 1,m - 1
                    i = 0
                    tmp = w(j)
                    do jj = j + 1,m
                       if (w(jj) < tmp) then
                          i = jj
                          tmp = w(jj)
                       end if
                    end do
                    if (i /= 0) then
                       w(i) = w(j)
                       w(j) = tmp
                       if (wantz) then
                          call la_qswap(n,z(1,i),1,z(1,j),1)
                          itmp = isuppz(2*i - 1)
                          isuppz(2*i - 1) = isuppz(2*j - 1)
                          isuppz(2*j - 1) = itmp
                          itmp = isuppz(2*i)
                          isuppz(2*i) = isuppz(2*j)
                          isuppz(2*j) = itmp
                       end if
                    end if
                 end do
              end if
           end if
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qstemr

     !> DSTEQR: computes all eigenvalues and, optionally, eigenvectors of a
     !> symmetric tridiagonal matrix using the implicit QL or QR method.
     !> The eigenvectors of a full or band symmetric matrix can also be found
     !> if DSYTRD or DSPTRD or DSBTRD has been used to reduce this matrix to
     !> tridiagonal form.

     pure subroutine la_qsteqr(compz,n,d,e,z,ldz,work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: compz
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldz,n
           ! Array Arguments
           real(qp),intent(inout) :: d(*),e(*),z(ldz,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: maxit = 30

           ! Local Scalars
           integer(ilp) :: i,icompz,ii,iscale,j,jtot,k,l,l1,lend,lendm1,lendp1,lendsv, &
                      lm1,lsv,m,mm,mm1,nm1,nmaxit
           real(qp) :: anorm,b,c,eps,eps2,f,g,p,r,rt1,rt2,s,safmax,safmin,ssfmax, &
                     ssfmin,tst
           ! Intrinsic Functions
           intrinsic :: abs,max,sign,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (la_lsame(compz,'N')) then
              icompz = 0
           else if (la_lsame(compz,'V')) then
              icompz = 1
           else if (la_lsame(compz,'I')) then
              icompz = 2
           else
              icompz = -1
           end if
           if (icompz < 0) then
              info = -1
           else if (n < 0) then
              info = -2
           else if ((ldz < 1) .or. (icompz > 0 .and. ldz < max(1,n))) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('DSTEQR',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              if (icompz == 2) z(1,1) = one
              return
           end if
           ! determine the unit roundoff and over/underflow thresholds.
           eps = la_qlamch('E')
           eps2 = eps**2
           safmin = la_qlamch('S')
           safmax = one/safmin
           ssfmax = sqrt(safmax)/three
           ssfmin = sqrt(safmin)/eps2
           ! compute the eigenvalues and eigenvectors of the tridiagonal
           ! matrix.
           if (icompz == 2) call la_qlaset('FULL',n,n,zero,one,z,ldz)
           nmaxit = n*maxit
           jtot = 0
           ! determine where the matrix splits and choose ql or qr iteration
           ! for each block, according to whether top or bottom diagonal
           ! element is smaller.
           l1 = 1
           nm1 = n - 1
           10 continue
           if (l1 > n) go to 160
           if (l1 > 1) e(l1 - 1) = zero
           if (l1 <= nm1) then
              do m = l1,nm1
                 tst = abs(e(m))
                 if (tst == zero) go to 30
                 if (tst <= (sqrt(abs(d(m)))*sqrt(abs(d(m + 1))))*eps) then
                    e(m) = zero
                    go to 30
                 end if
              end do
           end if
           m = n
           30 continue
           l = l1
           lsv = l
           lend = m
           lendsv = lend
           l1 = m + 1
           if (lend == l) go to 10
           ! scale submatrix in rows and columns l to lend
           anorm = la_qlanst('M',lend - l + 1,d(l),e(l))
           iscale = 0
           if (anorm == zero) go to 10
           if (anorm > ssfmax) then
              iscale = 1
              call la_qlascl('G',0,0,anorm,ssfmax,lend - l + 1,1,d(l),n,info)
              call la_qlascl('G',0,0,anorm,ssfmax,lend - l,1,e(l),n,info)
           else if (anorm < ssfmin) then
              iscale = 2
              call la_qlascl('G',0,0,anorm,ssfmin,lend - l + 1,1,d(l),n,info)
              call la_qlascl('G',0,0,anorm,ssfmin,lend - l,1,e(l),n,info)
           end if
           ! choose between ql and qr iteration
           if (abs(d(lend)) < abs(d(l))) then
              lend = lsv
              l = lendsv
           end if
           if (lend > l) then
              ! ql iteration
              ! look for small subdiagonal element.
              40 continue
              if (l /= lend) then
                 lendm1 = lend - 1
                 do m = l,lendm1
                    tst = abs(e(m))**2
                    if (tst <= (eps2*abs(d(m)))*abs(d(m + 1)) + safmin) go to 60
                 end do
              end if
              m = lend
              60 continue
              if (m < lend) e(m) = zero
              p = d(l)
              if (m == l) go to 80
              ! if remaining matrix is 2-by-2, use la_qlae2 or la_dlaev2
              ! to compute its eigensystem.
              if (m == l + 1) then
                 if (icompz > 0) then
                    call la_qlaev2(d(l),e(l),d(l + 1),rt1,rt2,c,s)
                    work(l) = c
                    work(n - 1 + l) = s
                    call la_qlasr('R','V','B',n,2,work(l),work(n - 1 + l),z(1,l), &
                              ldz)
                 else
                    call la_qlae2(d(l),e(l),d(l + 1),rt1,rt2)
                 end if
                 d(l) = rt1
                 d(l + 1) = rt2
                 e(l) = zero
                 l = l + 2
                 if (l <= lend) go to 40
                 go to 140
              end if
              if (jtot == nmaxit) go to 140
              jtot = jtot + 1
              ! form shift.
              g = (d(l + 1) - p)/(two*e(l))
              r = la_qlapy2(g,one)
              g = d(m) - p + (e(l)/(g + sign(r,g)))
              s = one
              c = one
              p = zero
              ! inner loop
              mm1 = m - 1
              do i = mm1,l,-1
                 f = s*e(i)
                 b = c*e(i)
                 call la_qlartg(g,f,c,s,r)
                 if (i /= m - 1) e(i + 1) = r
                 g = d(i + 1) - p
                 r = (d(i) - g)*s + two*c*b
                 p = s*r
                 d(i + 1) = g + p
                 g = c*r - b
                 ! if eigenvectors are desired, then save rotations.
                 if (icompz > 0) then
                    work(i) = c
                    work(n - 1 + i) = -s
                 end if
              end do
              ! if eigenvectors are desired, then apply saved rotations.
              if (icompz > 0) then
                 mm = m - l + 1
                 call la_qlasr('R','V','B',n,mm,work(l),work(n - 1 + l),z(1,l),ldz &
                           )
              end if
              d(l) = d(l) - p
              e(l) = g
              go to 40
              ! eigenvalue found.
              80 continue
              d(l) = p
              l = l + 1
              if (l <= lend) go to 40
              go to 140
           else
              ! qr iteration
              ! look for small superdiagonal element.
              90 continue
              if (l /= lend) then
                 lendp1 = lend + 1
                 do m = l,lendp1,-1
                    tst = abs(e(m - 1))**2
                    if (tst <= (eps2*abs(d(m)))*abs(d(m - 1)) + safmin) go to 110
                 end do
              end if
              m = lend
              110 continue
              if (m > lend) e(m - 1) = zero
              p = d(l)
              if (m == l) go to 130
              ! if remaining matrix is 2-by-2, use la_qlae2 or la_dlaev2
              ! to compute its eigensystem.
              if (m == l - 1) then
                 if (icompz > 0) then
                    call la_qlaev2(d(l - 1),e(l - 1),d(l),rt1,rt2,c,s)
                    work(m) = c
                    work(n - 1 + m) = s
                    call la_qlasr('R','V','F',n,2,work(m),work(n - 1 + m),z(1,l - 1), &
                              ldz)
                 else
                    call la_qlae2(d(l - 1),e(l - 1),d(l),rt1,rt2)
                 end if
                 d(l - 1) = rt1
                 d(l) = rt2
                 e(l - 1) = zero
                 l = l - 2
                 if (l >= lend) go to 90
                 go to 140
              end if
              if (jtot == nmaxit) go to 140
              jtot = jtot + 1
              ! form shift.
              g = (d(l - 1) - p)/(two*e(l - 1))
              r = la_qlapy2(g,one)
              g = d(m) - p + (e(l - 1)/(g + sign(r,g)))
              s = one
              c = one
              p = zero
              ! inner loop
              lm1 = l - 1
              do i = m,lm1
                 f = s*e(i)
                 b = c*e(i)
                 call la_qlartg(g,f,c,s,r)
                 if (i /= m) e(i - 1) = r
                 g = d(i) - p
                 r = (d(i + 1) - g)*s + two*c*b
                 p = s*r
                 d(i) = g + p
                 g = c*r - b
                 ! if eigenvectors are desired, then save rotations.
                 if (icompz > 0) then
                    work(i) = c
                    work(n - 1 + i) = s
                 end if
              end do
              ! if eigenvectors are desired, then apply saved rotations.
              if (icompz > 0) then
                 mm = l - m + 1
                 call la_qlasr('R','V','F',n,mm,work(m),work(n - 1 + m),z(1,m),ldz &
                           )
              end if
              d(l) = d(l) - p
              e(lm1) = g
              go to 90
              ! eigenvalue found.
              130 continue
              d(l) = p
              l = l - 1
              if (l >= lend) go to 90
              go to 140
           end if
           ! undo scaling if necessary
           140 continue
           if (iscale == 1) then
              call la_qlascl('G',0,0,ssfmax,anorm,lendsv - lsv + 1,1,d(lsv),n,info)

              call la_qlascl('G',0,0,ssfmax,anorm,lendsv - lsv,1,e(lsv),n,info)

           else if (iscale == 2) then
              call la_qlascl('G',0,0,ssfmin,anorm,lendsv - lsv + 1,1,d(lsv),n,info)

              call la_qlascl('G',0,0,ssfmin,anorm,lendsv - lsv,1,e(lsv),n,info)

           end if
           ! check for no convergence to an eigenvalue after a total
           ! of n*maxit iterations.
           if (jtot < nmaxit) go to 10
           do i = 1,n - 1
              if (e(i) /= zero) info = info + 1
           end do
           go to 190
           ! order eigenvalues and eigenvectors.
           160 continue
           if (icompz == 0) then
              ! use quick sort
              call la_qlasrt('I',n,d,info)
           else
              ! use selection sort to minimize swaps of eigenvectors
              do ii = 2,n
                 i = ii - 1
                 k = i
                 p = d(i)
                 do j = ii,n
                    if (d(j) < p) then
                       k = j
                       p = d(j)
                    end if
                 end do
                 if (k /= i) then
                    d(k) = d(i)
                    d(i) = p
                    call la_qswap(n,z(1,i),1,z(1,k),1)
                 end if
              end do
           end if
           190 continue
           return
     end subroutine la_qsteqr

     !> DSTERF: computes all eigenvalues of a symmetric tridiagonal matrix
     !> using the Pal-Walker-Kahan variant of the QL or QR algorithm.

     pure subroutine la_qsterf(n,d,e,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           real(qp),intent(inout) :: d(*),e(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: maxit = 30

           ! Local Scalars
           integer(ilp) :: i,iscale,jtot,l,l1,lend,lendsv,lsv,m,nmaxit
           real(qp) :: alpha,anorm,bb,c,eps,eps2,gamma,oldc,oldgam,p,r,rt1,rt2,rte, &
                     s,safmax,safmin,sigma,ssfmax,ssfmin,rmax
           ! Intrinsic Functions
           intrinsic :: abs,sign,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           ! quick return if possible
           if (n < 0) then
              info = -1
              call la_xerbla('DSTERF',-info)
              return
           end if
           if (n <= 1) return
           ! determine the unit roundoff for this environment.
           eps = la_qlamch('E')
           eps2 = eps**2
           safmin = la_qlamch('S')
           safmax = one/safmin
           ssfmax = sqrt(safmax)/three
           ssfmin = sqrt(safmin)/eps2
           rmax = la_qlamch('O')
           ! compute the eigenvalues of the tridiagonal matrix.
           nmaxit = n*maxit
           sigma = zero
           jtot = 0
           ! determine where the matrix splits and choose ql or qr iteration
           ! for each block, according to whether top or bottom diagonal
           ! element is smaller.
           l1 = 1
           10 continue
           if (l1 > n) go to 170
           if (l1 > 1) e(l1 - 1) = zero
           do m = l1,n - 1
              if (abs(e(m)) <= (sqrt(abs(d(m)))*sqrt(abs(d(m + 1))))*eps) &
                        then
                 e(m) = zero
                 go to 30
              end if
           end do
           m = n
           30 continue
           l = l1
           lsv = l
           lend = m
           lendsv = lend
           l1 = m + 1
           if (lend == l) go to 10
           ! scale submatrix in rows and columns l to lend
           anorm = la_qlanst('M',lend - l + 1,d(l),e(l))
           iscale = 0
           if (anorm == zero) go to 10
           if ((anorm > ssfmax)) then
              iscale = 1
              call la_qlascl('G',0,0,anorm,ssfmax,lend - l + 1,1,d(l),n,info)
              call la_qlascl('G',0,0,anorm,ssfmax,lend - l,1,e(l),n,info)
           else if (anorm < ssfmin) then
              iscale = 2
              call la_qlascl('G',0,0,anorm,ssfmin,lend - l + 1,1,d(l),n,info)
              call la_qlascl('G',0,0,anorm,ssfmin,lend - l,1,e(l),n,info)
           end if
           do i = l,lend - 1
              e(i) = e(i)**2
           end do
           ! choose between ql and qr iteration
           if (abs(d(lend)) < abs(d(l))) then
              lend = lsv
              l = lendsv
           end if
           if (lend >= l) then
              ! ql iteration
              ! look for small subdiagonal element.
              50 continue
              if (l /= lend) then
                 do m = l,lend - 1
                    if (abs(e(m)) <= eps2*abs(d(m)*d(m + 1))) go to 70
                 end do
              end if
              m = lend
              70 continue
              if (m < lend) e(m) = zero
              p = d(l)
              if (m == l) go to 90
              ! if remaining matrix is 2 by 2, use la_qlae2 to compute its
              ! eigenvalues.
              if (m == l + 1) then
                 rte = sqrt(e(l))
                 call la_qlae2(d(l),rte,d(l + 1),rt1,rt2)
                 d(l) = rt1
                 d(l + 1) = rt2
                 e(l) = zero
                 l = l + 2
                 if (l <= lend) go to 50
                 go to 150
              end if
              if (jtot == nmaxit) go to 150
              jtot = jtot + 1
              ! form shift.
              rte = sqrt(e(l))
              sigma = (d(l + 1) - p)/(two*rte)
              r = la_qlapy2(sigma,one)
              sigma = p - (rte/(sigma + sign(r,sigma)))
              c = one
              s = zero
              gamma = d(m) - sigma
              p = gamma*gamma
              ! inner loop
              do i = m - 1,l,-1
                 bb = e(i)
                 r = p + bb
                 if (i /= m - 1) e(i + 1) = s*r
                 oldc = c
                 c = p/r
                 s = bb/r
                 oldgam = gamma
                 alpha = d(i)
                 gamma = c*(alpha - sigma) - s*oldgam
                 d(i + 1) = oldgam + (alpha - gamma)
                 if (c /= zero) then
                    p = (gamma*gamma)/c
                 else
                    p = oldc*bb
                 end if
              end do
              e(l) = s*p
              d(l) = sigma + gamma
              go to 50
              ! eigenvalue found.
              90 continue
              d(l) = p
              l = l + 1
              if (l <= lend) go to 50
              go to 150
           else
              ! qr iteration
              ! look for small superdiagonal element.
              100 continue
              do m = l,lend + 1,-1
                 if (abs(e(m - 1)) <= eps2*abs(d(m)*d(m - 1))) go to 120
              end do
              m = lend
              120 continue
              if (m > lend) e(m - 1) = zero
              p = d(l)
              if (m == l) go to 140
              ! if remaining matrix is 2 by 2, use la_qlae2 to compute its
              ! eigenvalues.
              if (m == l - 1) then
                 rte = sqrt(e(l - 1))
                 call la_qlae2(d(l),rte,d(l - 1),rt1,rt2)
                 d(l) = rt1
                 d(l - 1) = rt2
                 e(l - 1) = zero
                 l = l - 2
                 if (l >= lend) go to 100
                 go to 150
              end if
              if (jtot == nmaxit) go to 150
              jtot = jtot + 1
              ! form shift.
              rte = sqrt(e(l - 1))
              sigma = (d(l - 1) - p)/(two*rte)
              r = la_qlapy2(sigma,one)
              sigma = p - (rte/(sigma + sign(r,sigma)))
              c = one
              s = zero
              gamma = d(m) - sigma
              p = gamma*gamma
              ! inner loop
              do i = m,l - 1
                 bb = e(i)
                 r = p + bb
                 if (i /= m) e(i - 1) = s*r
                 oldc = c
                 c = p/r
                 s = bb/r
                 oldgam = gamma
                 alpha = d(i + 1)
                 gamma = c*(alpha - sigma) - s*oldgam
                 d(i) = oldgam + (alpha - gamma)
                 if (c /= zero) then
                    p = (gamma*gamma)/c
                 else
                    p = oldc*bb
                 end if
              end do
              e(l - 1) = s*p
              d(l) = sigma + gamma
              go to 100
              ! eigenvalue found.
              140 continue
              d(l) = p
              l = l - 1
              if (l >= lend) go to 100
              go to 150
           end if
           ! undo scaling if necessary
           150 continue
           if (iscale == 1) call la_qlascl('G',0,0,ssfmax,anorm,lendsv - lsv + 1,1,d(lsv), &
                     n,info)
           if (iscale == 2) call la_qlascl('G',0,0,ssfmin,anorm,lendsv - lsv + 1,1,d(lsv), &
                     n,info)
           ! check for no convergence to an eigenvalue after a total
           ! of n*maxit iterations.
           if (jtot < nmaxit) go to 10
           do i = 1,n - 1
              if (e(i) /= zero) info = info + 1
           end do
           go to 180
           ! sort eigenvalues in increasing order.
           170 continue
           call la_qlasrt('I',n,d,info)
           180 continue
           return
     end subroutine la_qsterf

     !> DSTEV: computes all eigenvalues and, optionally, eigenvectors of a
     !> real symmetric tridiagonal matrix A.

     pure subroutine la_qstev(jobz,n,d,e,z,ldz,work,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldz,n
           ! Array Arguments
           real(qp),intent(inout) :: d(*),e(*)
           real(qp),intent(out) :: work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: wantz
           integer(ilp) :: imax,iscale
           real(qp) :: bignum,eps,rmax,rmin,safmin,sigma,smlnum,tnrm
           ! Intrinsic Functions
           intrinsic :: sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('DSTEV ',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              if (wantz) z(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = sqrt(bignum)
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           tnrm = la_qlanst('M',n,d,e)
           if (tnrm > zero .and. tnrm < rmin) then
              iscale = 1
              sigma = rmin/tnrm
           else if (tnrm > rmax) then
              iscale = 1
              sigma = rmax/tnrm
           end if
           if (iscale == 1) then
              call la_qscal(n,sigma,d,1)
              call la_qscal(n - 1,sigma,e(1),1)
           end if
           ! for eigenvalues only, call la_qsterf.  for eigenvalues and
           ! eigenvectors, call la_qsteqr.
           if (.not. wantz) then
              call la_qsterf(n,d,e,info)
           else
              call la_qsteqr('I',n,d,e,z,ldz,work,info)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           if (iscale == 1) then
              if (info == 0) then
                 imax = n
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,d,1)
           end if
           return
     end subroutine la_qstev

     !> DSTEVD: computes all eigenvalues and, optionally, eigenvectors of a
     !> real symmetric tridiagonal matrix. If eigenvectors are desired, it
     !> uses a divide and conquer algorithm.
     !> The divide and conquer algorithm makes very mild assumptions about
     !> floating point arithmetic. It will work on machines with a guard
     !> digit in add/subtract, or on those binary machines without guard
     !> digits which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or
     !> Cray-2. It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.

     pure subroutine la_qstevd(jobz,n,d,e,z,ldz,work,lwork,iwork,liwork,info)

        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldz,liwork,lwork,n
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: d(*),e(*)
           real(qp),intent(out) :: work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,wantz
           integer(ilp) :: iscale,liwmin,lwmin
           real(qp) :: bignum,eps,rmax,rmin,safmin,sigma,smlnum,tnrm
           ! Intrinsic Functions
           intrinsic :: sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           lquery = (lwork == -1 .or. liwork == -1)
           info = 0
           liwmin = 1
           lwmin = 1
           if (n > 1 .and. wantz) then
              lwmin = 1 + 4*n + n**2
              liwmin = 3 + 5*n
           end if
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -6
           end if
           if (info == 0) then
              work(1) = lwmin
              iwork(1) = liwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -8
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -10
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSTEVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              if (wantz) z(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = sqrt(bignum)
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           tnrm = la_qlanst('M',n,d,e)
           if (tnrm > zero .and. tnrm < rmin) then
              iscale = 1
              sigma = rmin/tnrm
           else if (tnrm > rmax) then
              iscale = 1
              sigma = rmax/tnrm
           end if
           if (iscale == 1) then
              call la_qscal(n,sigma,d,1)
              call la_qscal(n - 1,sigma,e(1),1)
           end if
           ! for eigenvalues only, call la_qsterf.  for eigenvalues and
           ! eigenvectors, call la_qstedc.
           if (.not. wantz) then
              call la_qsterf(n,d,e,info)
           else
              call la_qstedc('I',n,d,e,z,ldz,work,lwork,iwork,liwork,info)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           if (iscale == 1) call la_qscal(n,one/sigma,d,1)
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qstevd

     !> DSTEVR: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric tridiagonal matrix T.  Eigenvalues and
     !> eigenvectors can be selected by specifying either a range of values
     !> or a range of indices for the desired eigenvalues.
     !> Whenever possible, DSTEVR calls DSTEMR to compute the
     !> eigenspectrum using Relatively Robust Representations.  DSTEMR
     !> computes eigenvalues by the dqds algorithm, while orthogonal
     !> eigenvectors are computed from various "good" L D L^T representations
     !> (also known as Relatively Robust Representations). Gram-Schmidt
     !> orthogonalization is avoided as far as possible. More specifically,
     !> the various steps of the algorithm are as follows. For the i-th
     !> unreduced block of T,
     !> (a) Compute T - sigma_i = L_i D_i L_i^T, such that L_i D_i L_i^T
     !> is a relatively robust representation,
     !> (b) Compute the eigenvalues, lambda_j, of L_i D_i L_i^T to high
     !> relative accuracy by the dqds algorithm,
     !> (c) If there is a cluster of close eigenvalues, "choose" sigma_i
     !> close to the cluster, and go to step (a),
     !> (d) Given the approximate eigenvalue lambda_j of L_i D_i L_i^T,
     !> compute the corresponding eigenvector by forming a
     !> rank-revealing twisted factorization.
     !> The desired accuracy of the output can be specified by the input
     !> parameter ABSTOL.
     !> For more details, see "A new O(n^2) algorithm for the symmetric
     !> tridiagonal eigenvalue/eigenvector problem", by Inderjit Dhillon,
     !> Computer Science Division Technical Report No. UCB//CSD-97-971,
     !> UC Berkeley, May 1997.
     !> Note 1 : DSTEVR calls DSTEMR when the full spectrum is requested
     !> on machines which conform to the ieee-754 floating point standard.
     !> DSTEVR calls DSTEBZ and DSTEIN on non-ieee machines and
     !> when partial spectrum requests are made.
     !> Normal execution of DSTEMR may create NaNs and infinities and
     !> hence may abort due to a floating point exception in environments
     !> which do not handle NaNs and infinities in the ieee standard default
     !> manner.

     pure subroutine la_qstevr(jobz,range,n,d,e,vl,vu,il,iu,abstol,m,w,z,ldz, &
               isuppz,work,lwork,iwork,liwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range
           integer(ilp),intent(in) :: il,iu,ldz,liwork,lwork,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: isuppz(*),iwork(*)
           real(qp),intent(inout) :: d(*),e(*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,test,lquery,valeig,wantz,tryrac
           character :: order
           integer(ilp) :: i,ieeeok,imax,indibl,indifl,indisp,indiwo,iscale,itmp1,j,jj, &
                     liwmin,lwmin,nsplit
           real(qp) :: bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,tnrm,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           ieeeok = la_ilaenv(10,'DSTEVR','N',1,2,3,4)
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lquery = ((lwork == -1) .or. (liwork == -1))
           lwmin = max(1,20*n)
           liwmin = max(1,10*n)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (n < 0) then
              info = -3
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -7
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -8
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -9
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -14
              end if
           end if
           if (info == 0) then
              work(1) = lwmin
              iwork(1) = liwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -17
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -19
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSTEVR',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) return
           if (n == 1) then
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = d(1)
              else
                 if (vl < d(1) .and. vu >= d(1)) then
                    m = 1
                    w(1) = d(1)
                 end if
              end if
              if (wantz) z(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           if (valeig) then
              vll = vl
              vuu = vu
           end if
           tnrm = la_qlanst('M',n,d,e)
           if (tnrm > zero .and. tnrm < rmin) then
              iscale = 1
              sigma = rmin/tnrm
           else if (tnrm > rmax) then
              iscale = 1
              sigma = rmax/tnrm
           end if
           if (iscale == 1) then
              call la_qscal(n,sigma,d,1)
              call la_qscal(n - 1,sigma,e(1),1)
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! initialize indices into workspaces.  note: these indices are used only
           ! if la_qsterf or la_qstemr fail.
           ! iwork(indibl:indibl+m-1) corresponds to iblock in la_qstebz and
           ! stores the block indices of each of the m<=n eigenvalues.
           indibl = 1
           ! iwork(indisp:indisp+nsplit-1) corresponds to isplit in la_qstebz and
           ! stores the starting and finishing indices of each block.
           indisp = indibl + n
           ! iwork(indifl:indifl+n-1) stores the indices of eigenvectors
           ! that corresponding to eigenvectors that fail to converge in
           ! la_qstein.  this information is discarded; if any fail, the driver
           ! returns info > 0.
           indifl = indisp + n
           ! indiwo is the offset of the remaining integer workspace.
           indiwo = indisp + n
           ! if all eigenvalues are desired, then
           ! call la_qsterf or la_qstemr.  if this fails for some eigenvalue, then
           ! try la_qstebz.
           test = .false.
           if (indeig) then
              if (il == 1 .and. iu == n) then
                 test = .true.
              end if
           end if
           if ((alleig .or. test) .and. ieeeok == 1) then
              call la_qcopy(n - 1,e(1),1,work(1),1)
              if (.not. wantz) then
                 call la_qcopy(n,d,1,w,1)
                 call la_qsterf(n,w,work,info)
              else
                 call la_qcopy(n,d,1,work(n + 1),1)
                 if (abstol <= two*n*eps) then
                    tryrac = .true.
                 else
                    tryrac = .false.
                 end if
                 call la_qstemr(jobz,'A',n,work(n + 1),work,vl,vu,il,iu,m,w,z,ldz, &
                            n,isuppz,tryrac,work(2*n + 1),lwork - 2*n,iwork,liwork,info)
              end if
              if (info == 0) then
                 m = n
                 go to 10
              end if
              info = 0
           end if
           ! otherwise, call la_qstebz and, if eigenvectors are desired, la_qstein.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           call la_qstebz(range,order,n,vll,vuu,il,iu,abstol,d,e,m,nsplit,w, &
                     iwork(indibl),iwork(indisp),work,iwork(indiwo),info)
           if (wantz) then
              call la_qstein(n,d,e,m,w,iwork(indibl),iwork(indisp),z,ldz,work, &
                        iwork(indiwo),iwork(indifl),info)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           10 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    itmp1 = iwork(i)
                    w(i) = w(j)
                    iwork(i) = iwork(j)
                    w(j) = tmp1
                    iwork(j) = itmp1
                    call la_qswap(n,z(1,i),1,z(1,j),1)
                 end if
              end do
           end if
            ! causes problems with tests 19
            ! if (wantz .and. indeig ) z( 1,1) = z(1,1) / 1.002_qp + .002
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qstevr

     !> DSTEVX: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric tridiagonal matrix A.  Eigenvalues and
     !> eigenvectors can be selected by specifying either a range of values
     !> or a range of indices for the desired eigenvalues.

     pure subroutine la_qstevx(jobz,range,n,d,e,vl,vu,il,iu,abstol,m,w,z,ldz, &
               work,iwork,ifail,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range
           integer(ilp),intent(in) :: il,iu,ldz,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: ifail(*),iwork(*)
           real(qp),intent(inout) :: d(*),e(*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,test,valeig,wantz
           character :: order
           integer(ilp) :: i,imax,indibl,indisp,indiwo,indwrk,iscale,itmp1,j,jj, &
                     nsplit
           real(qp) :: bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,tnrm,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (n < 0) then
              info = -3
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -7
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -8
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -9
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) info = -14
           end if
           if (info /= 0) then
              call la_xerbla('DSTEVX',-info)
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) return
           if (n == 1) then
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = d(1)
              else
                 if (vl < d(1) .and. vu >= d(1)) then
                    m = 1
                    w(1) = d(1)
                 end if
              end if
              if (wantz) z(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           if (valeig) then
              vll = vl
              vuu = vu
           else
              vll = zero
              vuu = zero
           end if
           tnrm = la_qlanst('M',n,d,e)
           if (tnrm > zero .and. tnrm < rmin) then
              iscale = 1
              sigma = rmin/tnrm
           else if (tnrm > rmax) then
              iscale = 1
              sigma = rmax/tnrm
           end if
           if (iscale == 1) then
              call la_qscal(n,sigma,d,1)
              call la_qscal(n - 1,sigma,e(1),1)
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! if all eigenvalues are desired and abstol is less than zero, then
           ! call la_qsterf or la_dsteqr.  if this fails for some eigenvalue, then
           ! try la_qstebz.
           test = .false.
           if (indeig) then
              if (il == 1 .and. iu == n) then
                 test = .true.
              end if
           end if
           if ((alleig .or. test) .and. (abstol <= zero)) then
              call la_qcopy(n,d,1,w,1)
              call la_qcopy(n - 1,e(1),1,work(1),1)
              indwrk = n + 1
              if (.not. wantz) then
                 call la_qsterf(n,w,work,info)
              else
                 call la_qsteqr('I',n,w,work,z,ldz,work(indwrk),info)
                 if (info == 0) then
                    do i = 1,n
                       ifail(i) = 0
                    end do
                 end if
              end if
              if (info == 0) then
                 m = n
                 go to 20
              end if
              info = 0
           end if
           ! otherwise, call la_qstebz and, if eigenvectors are desired, la_dstein.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           indwrk = 1
           indibl = 1
           indisp = indibl + n
           indiwo = indisp + n
           call la_qstebz(range,order,n,vll,vuu,il,iu,abstol,d,e,m,nsplit,w, &
                     iwork(indibl),iwork(indisp),work(indwrk),iwork(indiwo),info)
           if (wantz) then
              call la_qstein(n,d,e,m,w,iwork(indibl),iwork(indisp),z,ldz,work( &
                        indwrk),iwork(indiwo),ifail,info)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           20 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    itmp1 = iwork(indibl + i - 1)
                    w(i) = w(j)
                    iwork(indibl + i - 1) = iwork(indibl + j - 1)
                    w(j) = tmp1
                    iwork(indibl + j - 1) = itmp1
                    call la_qswap(n,z(1,i),1,z(1,j),1)
                    if (info /= 0) then
                       itmp1 = ifail(i)
                       ifail(i) = ifail(j)
                       ifail(j) = itmp1
                    end if
                 end if
              end do
           end if
           return
     end subroutine la_qstevx

     !> DSYEV: computes all eigenvalues and, optionally, eigenvectors of a
     !> real symmetric matrix A.

     subroutine la_qsyev(jobz,uplo,n,a,lda,w,work,lwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,lwork,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: w(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,lquery,wantz
           integer(ilp) :: iinfo,imax,inde,indtau,indwrk,iscale,llwork,lwkopt,nb
           real(qp) :: anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum
           ! Intrinsic Functions
           intrinsic :: max,sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           lower = la_lsame(uplo,'L')
           lquery = (lwork == -1)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           end if
           if (info == 0) then
              nb = la_ilaenv(1,'DSYTRD',uplo,n,-1,-1,-1)
              lwkopt = max(1, (nb + 2)*n)
              work(1) = lwkopt
              if (lwork < max(1,3*n - 1) .and. .not. lquery) info = -8
           end if
           if (info /= 0) then
              call la_xerbla('DSYEV ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) then
              return
           end if
           if (n == 1) then
              w(1) = a(1,1)
              work(1) = 2
              if (wantz) a(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = sqrt(bignum)
           ! scale matrix to allowable range, if necessary.
           anrm = la_qlansy('M',uplo,n,a,lda,work)
           iscale = 0
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) call la_qlascl(uplo,0,0,one,sigma,n,n,a,lda,info)
           ! call la_qsytrd to reduce symmetric matrix to tridiagonal form.
           inde = 1
           indtau = inde + n
           indwrk = indtau + n
           llwork = lwork - indwrk + 1
           call la_qsytrd(uplo,n,a,lda,w,work(inde),work(indtau),work(indwrk), &
                     llwork,iinfo)
           ! for eigenvalues only, call la_qsterf.  for eigenvectors, first call
           ! la_qorgtr to generate the orthogonal matrix, then call la_qsteqr.
           if (.not. wantz) then
              call la_qsterf(n,w,work(inde),info)
           else
              call la_qorgtr(uplo,n,a,lda,work(indtau),work(indwrk),llwork,iinfo)

              call la_qsteqr(jobz,n,w,work(inde),a,lda,work(indtau),info)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           if (iscale == 1) then
              if (info == 0) then
                 imax = n
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           ! set work(1) to optimal workspace size.
           work(1) = lwkopt
           return
     end subroutine la_qsyev

     !> DSYEVD: computes all eigenvalues and, optionally, eigenvectors of a
     !> real symmetric matrix A. If eigenvectors are desired, it uses a
     !> divide and conquer algorithm.
     !> The divide and conquer algorithm makes very mild assumptions about
     !> floating point arithmetic. It will work on machines with a guard
     !> digit in add/subtract, or on those binary machines without guard
     !> digits which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or
     !> Cray-2. It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.
     !> Because of large use of BLAS of level 3, DSYEVD needs N**2 more
     !> workspace than DSYEVX.

     subroutine la_qsyevd(jobz,uplo,n,a,lda,w,work,lwork,iwork,liwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,liwork,lwork,n
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: w(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,lquery,wantz
           integer(ilp) :: iinfo,inde,indtau,indwk2,indwrk,iscale,liopt,liwmin,llwork, &
                     llwrk2,lopt,lwmin
           real(qp) :: anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum
           ! Intrinsic Functions
           intrinsic :: max,sqrt
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           lower = la_lsame(uplo,'L')
           lquery = (lwork == -1 .or. liwork == -1)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           end if
           if (info == 0) then
              if (n <= 1) then
                 liwmin = 1
                 lwmin = 1
                 lopt = lwmin
                 liopt = liwmin
              else
                 if (wantz) then
                    liwmin = 3 + 5*n
                    lwmin = 1 + 6*n + 2*n**2
                 else
                    liwmin = 1
                    lwmin = 2*n + 1
                 end if
                 lopt = max(lwmin,2*n + la_ilaenv(1,'DSYTRD',uplo,n,-1,-1,-1))

                 liopt = liwmin
              end if
              work(1) = lopt
              iwork(1) = liopt
              if (lwork < lwmin .and. .not. lquery) then
                 info = -8
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -10
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSYEVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              w(1) = a(1,1)
              if (wantz) a(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = sqrt(bignum)
           ! scale matrix to allowable range, if necessary.
           anrm = la_qlansy('M',uplo,n,a,lda,work)
           iscale = 0
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) call la_qlascl(uplo,0,0,one,sigma,n,n,a,lda,info)
           ! call la_qsytrd to reduce symmetric matrix to tridiagonal form.
           inde = 1
           indtau = inde + n
           indwrk = indtau + n
           llwork = lwork - indwrk + 1
           indwk2 = indwrk + n*n
           llwrk2 = lwork - indwk2 + 1
           call la_qsytrd(uplo,n,a,lda,w,work(inde),work(indtau),work(indwrk), &
                     llwork,iinfo)
           ! for eigenvalues only, call la_qsterf.  for eigenvectors, first call
           ! la_qstedc to generate the eigenvector matrix, work(indwrk), of the
           ! tridiagonal matrix, then call la_qormtr to multiply it by the
           ! householder transformations stored in a.
           if (.not. wantz) then
              call la_qsterf(n,w,work(inde),info)
           else
              call la_qstedc('I',n,w,work(inde),work(indwrk),n,work(indwk2), &
                        llwrk2,iwork,liwork,info)
              call la_qormtr('L',uplo,'N',n,n,a,lda,work(indtau),work(indwrk),n, &
                        work(indwk2),llwrk2,iinfo)
              call la_qlacpy('A',n,n,work(indwrk),n,a,lda)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           if (iscale == 1) call la_qscal(n,one/sigma,w,1)
           work(1) = lopt
           iwork(1) = liopt
           return
     end subroutine la_qsyevd

     !> DSYEVR: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric matrix A.  Eigenvalues and eigenvectors can be
     !> selected by specifying either a range of values or a range of
     !> indices for the desired eigenvalues.
     !> DSYEVR first reduces the matrix A to tridiagonal form T with a call
     !> to DSYTRD.  Then, whenever possible, DSYEVR calls DSTEMR to compute
     !> the eigenspectrum using Relatively Robust Representations.  DSTEMR
     !> computes eigenvalues by the dqds algorithm, while orthogonal
     !> eigenvectors are computed from various "good" L D L^T representations
     !> (also known as Relatively Robust Representations). Gram-Schmidt
     !> orthogonalization is avoided as far as possible. More specifically,
     !> the various steps of the algorithm are as follows.
     !> For each unreduced block (submatrix) of T,
     !> (a) Compute T - sigma I  = L D L^T, so that L and D
     !> define all the wanted eigenvalues to high relative accuracy.
     !> This means that small relative changes in the entries of D and L
     !> cause only small relative changes in the eigenvalues and
     !> eigenvectors. The standard (unfactored) representation of the
     !> tridiagonal matrix T does not have this property in general.
     !> (b) Compute the eigenvalues to suitable accuracy.
     !> If the eigenvectors are desired, the algorithm attains full
     !> accuracy of the computed eigenvalues only right before
     !> the corresponding vectors have to be computed, see steps c) and d).
     !> (c) For each cluster of close eigenvalues, select a new
     !> shift close to the cluster, find a new factorization, and refine
     !> the shifted eigenvalues to suitable accuracy.
     !> (d) For each eigenvalue with a large enough relative separation compute
     !> the corresponding eigenvector by forming a rank revealing twisted
     !> factorization. Go back to (c) for any clusters that remain.
     !> The desired accuracy of the output can be specified by the input
     !> parameter ABSTOL.
     !> For more details, see DSTEMR's documentation and:
     !> - Inderjit S. Dhillon and Beresford N. Parlett: "Multiple representations
     !> to compute orthogonal eigenvectors of symmetric tridiagonal matrices,"
     !> Linear Algebra and its Applications, 387(1), pp. 1-28, August 2004.
     !> - Inderjit Dhillon and Beresford Parlett: "Orthogonal Eigenvectors and
     !> Relative Gaps," SIAM Journal on Matrix Analysis and Applications, Vol. 25,
     !> 2004.  Also LAPACK Working Note 154.
     !> - Inderjit Dhillon: "A new O(n^2) algorithm for the symmetric
     !> tridiagonal eigenvalue/eigenvector problem",
     !> Computer Science Division Technical Report No. UCB/CSD-97-971,
     !> UC Berkeley, May 1997.
     !> Note 1 : DSYEVR calls DSTEMR when the full spectrum is requested
     !> on machines which conform to the ieee-754 floating point standard.
     !> DSYEVR calls DSTEBZ and DSTEIN on non-ieee machines and
     !> when partial spectrum requests are made.
     !> Normal execution of DSTEMR may create NaNs and infinities and
     !> hence may abort due to a floating point exception in environments
     !> which do not handle NaNs and infinities in the ieee standard default
     !> manner.

     subroutine la_qsyevr(jobz,range,uplo,n,a,lda,vl,vu,il,iu,abstol,m,w,z,ldz, &
               isuppz,work,lwork,iwork,liwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,iu,lda,ldz,liwork,lwork,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: isuppz(*),iwork(*)
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,lower,lquery,valeig,wantz,tryrac
           character :: order
           integer(ilp) :: i,ieeeok,iinfo,imax,indd,inddd,inde,indee,indibl,indifl, &
           indisp,indiwo,indtau,indwk,indwkn,iscale,j,jj,liwmin,llwork,llwrkn,lwkopt, &
                     lwmin,nb,nsplit
           real(qp) :: abstll,anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           ieeeok = la_ilaenv(10,'DSYEVR','N',1,2,3,4)
           lower = la_lsame(uplo,'L')
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lquery = ((lwork == -1) .or. (liwork == -1))
           lwmin = max(1,26*n)
           liwmin = max(1,10*n)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -8
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -9
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -10
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -15
              else if (lwork < lwmin .and. .not. lquery) then
                 info = -18
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -20
              end if
           end if
           if (info == 0) then
              nb = la_ilaenv(1,'DSYTRD',uplo,n,-1,-1,-1)
              nb = max(nb,la_ilaenv(1,'DORMTR',uplo,n,-1,-1,-1))
              lwkopt = max((nb + 1)*n,lwmin)
              work(1) = lwkopt
              iwork(1) = liwmin
           end if
           if (info /= 0) then
              call la_xerbla('DSYEVR',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) then
              work(1) = 1
              return
           end if
           if (n == 1) then
              work(1) = 7
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = a(1,1)
              else
                 if (vl < a(1,1) .and. vu >= a(1,1)) then
                    m = 1
                    w(1) = a(1,1)
                 end if
              end if
              if (wantz) then
                 z(1,1) = one
                 isuppz(1) = 1
                 isuppz(2) = 1
              end if
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           abstll = abstol
           if (valeig) then
              vll = vl
              vuu = vu
           end if
           anrm = la_qlansy('M',uplo,n,a,lda,work)
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              if (lower) then
                 do j = 1,n
                    call la_qscal(n - j + 1,sigma,a(j,j),1)
                 end do
              else
                 do j = 1,n
                    call la_qscal(j,sigma,a(1,j),1)
                 end do
              end if
              if (abstol > 0) abstll = abstol*sigma
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! initialize indices into workspaces.  note: the iwork indices are
           ! used only if la_qsterf or la_qstemr fail.
           ! work(indtau:indtau+n-1) stores the scalar factors of the
           ! elementary reflectors used in la_qsytrd.
           indtau = 1
           ! work(indd:indd+n-1) stores the tridiagonal's diagonal entries.
           indd = indtau + n
           ! work(inde:inde+n-1) stores the off-diagonal entries of the
           ! tridiagonal matrix from la_qsytrd.
           inde = indd + n
           ! work(inddd:inddd+n-1) is a copy of the diagonal entries over
           ! -written by la_qstemr (the la_qsterf path copies the diagonal to w).
           inddd = inde + n
           ! work(indee:indee+n-1) is a copy of the off-diagonal entries over
           ! -written while computing the eigenvalues in la_qsterf and la_qstemr.
           indee = inddd + n
           ! indwk is the starting offset of the left-over workspace, and
           ! llwork is the remaining workspace size.
           indwk = indee + n
           llwork = lwork - indwk + 1
           ! iwork(indibl:indibl+m-1) corresponds to iblock in la_qstebz and
           ! stores the block indices of each of the m<=n eigenvalues.
           indibl = 1
           ! iwork(indisp:indisp+nsplit-1) corresponds to isplit in la_qstebz and
           ! stores the starting and finishing indices of each block.
           indisp = indibl + n
           ! iwork(indifl:indifl+n-1) stores the indices of eigenvectors
           ! that corresponding to eigenvectors that fail to converge in
           ! la_qstein.  this information is discarded; if any fail, the driver
           ! returns info > 0.
           indifl = indisp + n
           ! indiwo is the offset of the remaining integer workspace.
           indiwo = indifl + n
           ! call la_qsytrd to reduce symmetric matrix to tridiagonal form.
           call la_qsytrd(uplo,n,a,lda,work(indd),work(inde),work(indtau),work( &
                     indwk),llwork,iinfo)
           ! if all eigenvalues are desired
           ! then call la_qsterf or la_qstemr and la_qormtr.
           if ((alleig .or. (indeig .and. il == 1 .and. iu == n)) .and. ieeeok == 1) then
              if (.not. wantz) then
                 call la_qcopy(n,work(indd),1,w,1)
                 call la_qcopy(n - 1,work(inde),1,work(indee),1)
                 call la_qsterf(n,w,work(indee),info)
              else
                 call la_qcopy(n - 1,work(inde),1,work(indee),1)
                 call la_qcopy(n,work(indd),1,work(inddd),1)
                 if (abstol <= two*n*eps) then
                    tryrac = .true.
                 else
                    tryrac = .false.
                 end if
                 call la_qstemr(jobz,'A',n,work(inddd),work(indee),vl,vu,il,iu,m, &
                            w,z,ldz,n,isuppz,tryrac,work(indwk),lwork,iwork,liwork,info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_qstemr.
                 if (wantz .and. info == 0) then
                    indwkn = inde
                    llwrkn = lwork - indwkn + 1
                    call la_qormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                               indwkn),llwrkn,iinfo)
                 end if
              end if
              if (info == 0) then
                 ! everything worked.  skip la_qstebz/la_qstein.  iwork(:) are
                 ! undefined.
                 m = n
                 go to 30
              end if
              info = 0
           end if
           ! otherwise, call la_qstebz and, if eigenvectors are desired, la_qstein.
           ! also call la_qstebz and la_qstein if la_qstemr fails.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           call la_qstebz(range,order,n,vll,vuu,il,iu,abstll,work(indd),work(inde &
           ),m,nsplit,w,iwork(indibl),iwork(indisp),work(indwk),iwork(indiwo),info)

           if (wantz) then
              call la_qstein(n,work(indd),work(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,work(indwk),iwork(indiwo),iwork(indifl),info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_qstein.
              indwkn = inde
              llwrkn = lwork - indwkn + 1
              call la_qormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                        indwkn),llwrkn,iinfo)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
        ! jump here if la_qstemr/la_qstein succeeded.
        30 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.  note: we do not sort the ifail portion of iwork.
           ! it may not be initialized (if la_qstemr/la_qstein succeeded), and we do
           ! not return this detailed information to the user.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    w(i) = w(j)
                    w(j) = tmp1
                    call la_qswap(n,z(1,i),1,z(1,j),1)
                 end if
              end do
           end if
           ! set work(1) to optimal workspace size.
           work(1) = lwkopt
           iwork(1) = liwmin
           return
     end subroutine la_qsyevr

     !> DSYEVX: computes selected eigenvalues and, optionally, eigenvectors
     !> of a real symmetric matrix A.  Eigenvalues and eigenvectors can be
     !> selected by specifying either a range of values or a range of indices
     !> for the desired eigenvalues.

     subroutine la_qsyevx(jobz,range,uplo,n,a,lda,vl,vu,il,iu,abstol,m,w,z,ldz, &
               work,lwork,iwork,ifail,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,iu,lda,ldz,lwork,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: ifail(*),iwork(*)
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,lower,lquery,test,valeig,wantz
           character :: order
           integer(ilp) :: i,iinfo,imax,indd,inde,indee,indibl,indisp,indiwo,indtau, &
           indwkn,indwrk,iscale,itmp1,j,jj,llwork,llwrkn,lwkmin,lwkopt,nb, &
                     nsplit
           real(qp) :: abstll,anrm,bignum,eps,rmax,rmin,safmin,sigma,smlnum,tmp1,vll, &
                     vuu
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           lower = la_lsame(uplo,'L')
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lquery = (lwork == -1)
           info = 0
           if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -1
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -2
           else if (.not. (lower .or. la_lsame(uplo,'U'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -8
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -9
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -10
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -15
              end if
           end if
           if (info == 0) then
              if (n <= 1) then
                 lwkmin = 1
                 work(1) = lwkmin
              else
                 lwkmin = 8*n
                 nb = la_ilaenv(1,'DSYTRD',uplo,n,-1,-1,-1)
                 nb = max(nb,la_ilaenv(1,'DORMTR',uplo,n,-1,-1,-1))
                 lwkopt = max(lwkmin, (nb + 3)*n)
                 work(1) = lwkopt
              end if
              if (lwork < lwkmin .and. .not. lquery) info = -17
           end if
           if (info /= 0) then
              call la_xerbla('DSYEVX',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) then
              return
           end if
           if (n == 1) then
              if (alleig .or. indeig) then
                 m = 1
                 w(1) = a(1,1)
              else
                 if (vl < a(1,1) .and. vu >= a(1,1)) then
                    m = 1
                    w(1) = a(1,1)
                 end if
              end if
              if (wantz) z(1,1) = one
              return
           end if
           ! get machine constants.
           safmin = la_qlamch('SAFE MINIMUM')
           eps = la_qlamch('PRECISION')
           smlnum = safmin/eps
           bignum = one/smlnum
           rmin = sqrt(smlnum)
           rmax = min(sqrt(bignum),one/sqrt(sqrt(safmin)))
           ! scale matrix to allowable range, if necessary.
           iscale = 0
           abstll = abstol
           if (valeig) then
              vll = vl
              vuu = vu
           end if
           anrm = la_qlansy('M',uplo,n,a,lda,work)
           if (anrm > zero .and. anrm < rmin) then
              iscale = 1
              sigma = rmin/anrm
           else if (anrm > rmax) then
              iscale = 1
              sigma = rmax/anrm
           end if
           if (iscale == 1) then
              if (lower) then
                 do j = 1,n
                    call la_qscal(n - j + 1,sigma,a(j,j),1)
                 end do
              else
                 do j = 1,n
                    call la_qscal(j,sigma,a(1,j),1)
                 end do
              end if
              if (abstol > 0) abstll = abstol*sigma
              if (valeig) then
                 vll = vl*sigma
                 vuu = vu*sigma
              end if
           end if
           ! call la_qsytrd to reduce symmetric matrix to tridiagonal form.
           indtau = 1
           inde = indtau + n
           indd = inde + n
           indwrk = indd + n
           llwork = lwork - indwrk + 1
           call la_qsytrd(uplo,n,a,lda,work(indd),work(inde),work(indtau),work( &
                     indwrk),llwork,iinfo)
           ! if all eigenvalues are desired and abstol is less than or equal to
           ! zero, then call la_qsterf or la_qorgtr and la_dsteqr.  if this fails for
           ! some eigenvalue, then try la_qstebz.
           test = .false.
           if (indeig) then
              if (il == 1 .and. iu == n) then
                 test = .true.
              end if
           end if
           if ((alleig .or. test) .and. (abstol <= zero)) then
              call la_qcopy(n,work(indd),1,w,1)
              indee = indwrk + 2*n
              if (.not. wantz) then
                 call la_qcopy(n - 1,work(inde),1,work(indee),1)
                 call la_qsterf(n,w,work(indee),info)
              else
                 call la_qlacpy('A',n,n,a,lda,z,ldz)
                 call la_qorgtr(uplo,n,z,ldz,work(indtau),work(indwrk),llwork, &
                           iinfo)
                 call la_qcopy(n - 1,work(inde),1,work(indee),1)
                 call la_qsteqr(jobz,n,w,work(indee),z,ldz,work(indwrk),info)

                 if (info == 0) then
                    do i = 1,n
                       ifail(i) = 0
                    end do
                 end if
              end if
              if (info == 0) then
                 m = n
                 go to 40
              end if
              info = 0
           end if
           ! otherwise, call la_qstebz and, if eigenvectors are desired, la_dstein.
           if (wantz) then
              order = 'B'
           else
              order = 'E'
           end if
           indibl = 1
           indisp = indibl + n
           indiwo = indisp + n
           call la_qstebz(range,order,n,vll,vuu,il,iu,abstll,work(indd),work(inde &
           ),m,nsplit,w,iwork(indibl),iwork(indisp),work(indwrk),iwork(indiwo),info &
                     )
           if (wantz) then
              call la_qstein(n,work(indd),work(inde),m,w,iwork(indibl),iwork( &
                        indisp),z,ldz,work(indwrk),iwork(indiwo),ifail,info)
              ! apply orthogonal matrix used in reduction to tridiagonal
              ! form to eigenvectors returned by la_qstein.
              indwkn = inde
              llwrkn = lwork - indwkn + 1
              call la_qormtr('L',uplo,'N',n,m,a,lda,work(indtau),z,ldz,work( &
                        indwkn),llwrkn,iinfo)
           end if
           ! if matrix was scaled, then rescale eigenvalues appropriately.
           40 continue
           if (iscale == 1) then
              if (info == 0) then
                 imax = m
              else
                 imax = info - 1
              end if
              call la_qscal(imax,one/sigma,w,1)
           end if
           ! if eigenvalues are not in order, then sort them, along with
           ! eigenvectors.
           if (wantz) then
              do j = 1,m - 1
                 i = 0
                 tmp1 = w(j)
                 do jj = j + 1,m
                    if (w(jj) < tmp1) then
                       i = jj
                       tmp1 = w(jj)
                    end if
                 end do
                 if (i /= 0) then
                    itmp1 = iwork(indibl + i - 1)
                    w(i) = w(j)
                    iwork(indibl + i - 1) = iwork(indibl + j - 1)
                    w(j) = tmp1
                    iwork(indibl + j - 1) = itmp1
                    call la_qswap(n,z(1,i),1,z(1,j),1)
                    if (info /= 0) then
                       itmp1 = ifail(i)
                       ifail(i) = ifail(j)
                       ifail(j) = itmp1
                    end if
                 end if
              end do
           end if
           ! set work(1) to optimal workspace size.
           work(1) = lwkopt
           return
     end subroutine la_qsyevx

     !> DSYGS2: reduces a real symmetric-definite generalized eigenproblem
     !> to standard form.
     !> If ITYPE = 1, the problem is A*x = lambda*B*x,
     !> and A is overwritten by inv(U**T)*A*inv(U) or inv(L)*A*inv(L**T)
     !> If ITYPE = 2 or 3, the problem is A*B*x = lambda*x or
     !> B*A*x = lambda*x, and A is overwritten by U*A*U**T or L**T *A*L.
     !> B must have been previously factorized as U**T *U or L*L**T by DPOTRF.

     pure subroutine la_qsygs2(itype,uplo,n,a,lda,b,ldb,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: itype,lda,ldb,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(in) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: k
           real(qp) :: akk,bkk,ct
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (itype < 1 .or. itype > 3) then
              info = -1
           else if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('DSYGS2',-info)
              return
           end if
           if (itype == 1) then
              if (upper) then
                 ! compute inv(u**t)*a*inv(u)
                 do k = 1,n
                    ! update the upper triangle of a(k:n,k:n)
                    akk = a(k,k)
                    bkk = b(k,k)
                    akk = akk/bkk**2
                    a(k,k) = akk
                    if (k < n) then
                       call la_qscal(n - k,one/bkk,a(k,k + 1),lda)
                       ct = -half*akk
                       call la_qaxpy(n - k,ct,b(k,k + 1),ldb,a(k,k + 1),lda)
                       call la_qsyr2(uplo,n - k,-one,a(k,k + 1),lda,b(k,k + 1),ldb,a( &
                                 k + 1,k + 1),lda)
                       call la_qaxpy(n - k,ct,b(k,k + 1),ldb,a(k,k + 1),lda)
                       call la_qtrsv(uplo,'TRANSPOSE','NON-UNIT',n - k,b(k + 1,k + 1),ldb, &
                                 a(k,k + 1),lda)
                    end if
                 end do
              else
                 ! compute inv(l)*a*inv(l**t)
                 do k = 1,n
                    ! update the lower triangle of a(k:n,k:n)
                    akk = a(k,k)
                    bkk = b(k,k)
                    akk = akk/bkk**2
                    a(k,k) = akk
                    if (k < n) then
                       call la_qscal(n - k,one/bkk,a(k + 1,k),1)
                       ct = -half*akk
                       call la_qaxpy(n - k,ct,b(k + 1,k),1,a(k + 1,k),1)
                       call la_qsyr2(uplo,n - k,-one,a(k + 1,k),1,b(k + 1,k),1,a(k + 1, &
                                 k + 1),lda)
                       call la_qaxpy(n - k,ct,b(k + 1,k),1,a(k + 1,k),1)
                       call la_qtrsv(uplo,'NO TRANSPOSE','NON-UNIT',n - k,b(k + 1,k + 1), &
                                 ldb,a(k + 1,k),1)
                    end if
                 end do
              end if
           else
              if (upper) then
                 ! compute u*a*u**t
                 do k = 1,n
                    ! update the upper triangle of a(1:k,1:k)
                    akk = a(k,k)
                    bkk = b(k,k)
                    call la_qtrmv(uplo,'NO TRANSPOSE','NON-UNIT',k - 1,b,ldb,a(1,k),1 &
                              )
                    ct = half*akk
                    call la_qaxpy(k - 1,ct,b(1,k),1,a(1,k),1)
                    call la_qsyr2(uplo,k - 1,one,a(1,k),1,b(1,k),1,a,lda)
                    call la_qaxpy(k - 1,ct,b(1,k),1,a(1,k),1)
                    call la_qscal(k - 1,bkk,a(1,k),1)
                    a(k,k) = akk*bkk**2
                 end do
              else
                 ! compute l**t *a*l
                 do k = 1,n
                    ! update the lower triangle of a(1:k,1:k)
                    akk = a(k,k)
                    bkk = b(k,k)
                    call la_qtrmv(uplo,'TRANSPOSE','NON-UNIT',k - 1,b,ldb,a(k,1),lda)

                    ct = half*akk
                    call la_qaxpy(k - 1,ct,b(k,1),ldb,a(k,1),lda)
                    call la_qsyr2(uplo,k - 1,one,a(k,1),lda,b(k,1),ldb,a,lda)

                    call la_qaxpy(k - 1,ct,b(k,1),ldb,a(k,1),lda)
                    call la_qscal(k - 1,bkk,a(k,1),lda)
                    a(k,k) = akk*bkk**2
                 end do
              end if
           end if
           return
     end subroutine la_qsygs2

     !> DSYGST: reduces a real symmetric-definite generalized eigenproblem
     !> to standard form.
     !> If ITYPE = 1, the problem is A*x = lambda*B*x,
     !> and A is overwritten by inv(U**T)*A*inv(U) or inv(L)*A*inv(L**T)
     !> If ITYPE = 2 or 3, the problem is A*B*x = lambda*x or
     !> B*A*x = lambda*x, and A is overwritten by U*A*U**T or L**T*A*L.
     !> B must have been previously factorized as U**T*U or L*L**T by DPOTRF.

     pure subroutine la_qsygst(itype,uplo,n,a,lda,b,ldb,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: itype,lda,ldb,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(in) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: k,kb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (itype < 1 .or. itype > 3) then
              info = -1
           else if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -2
           else if (n < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('DSYGST',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! determine the block size for this environment.
           nb = la_ilaenv(1,'DSYGST',uplo,n,-1,-1,-1)
           if (nb <= 1 .or. nb >= n) then
              ! use unblocked code
              call la_qsygs2(itype,uplo,n,a,lda,b,ldb,info)
           else
              ! use blocked code
              if (itype == 1) then
                 if (upper) then
                    ! compute inv(u**t)*a*inv(u)
                    do k = 1,n,nb
                       kb = min(n - k + 1,nb)
                       ! update the upper triangle of a(k:n,k:n)
                       call la_qsygs2(itype,uplo,kb,a(k,k),lda,b(k,k),ldb,info)

                       if (k + kb <= n) then
                          call la_qtrsm('LEFT',uplo,'TRANSPOSE','NON-UNIT',kb,n - k - kb + 1, &
                                    one,b(k,k),ldb,a(k,k + kb),lda)
                          call la_qsymm('LEFT',uplo,kb,n - k - kb + 1,-half,a(k,k),lda,b( &
                                    k,k + kb),ldb,one,a(k,k + kb),lda)
                          call la_qsyr2k(uplo,'TRANSPOSE',n - k - kb + 1,kb,-one,a(k,k + kb), &
                                    lda,b(k,k + kb),ldb,one,a(k + kb,k + kb),lda)
                          call la_qsymm('LEFT',uplo,kb,n - k - kb + 1,-half,a(k,k),lda,b( &
                                    k,k + kb),ldb,one,a(k,k + kb),lda)
                          call la_qtrsm('RIGHT',uplo,'NO TRANSPOSE','NON-UNIT',kb,n - k - kb + &
                                    1,one,b(k + kb,k + kb),ldb,a(k,k + kb),lda)
                       end if
                    end do
                 else
                    ! compute inv(l)*a*inv(l**t)
                    do k = 1,n,nb
                       kb = min(n - k + 1,nb)
                       ! update the lower triangle of a(k:n,k:n)
                       call la_qsygs2(itype,uplo,kb,a(k,k),lda,b(k,k),ldb,info)

                       if (k + kb <= n) then
                          call la_qtrsm('RIGHT',uplo,'TRANSPOSE','NON-UNIT',n - k - kb + 1,kb, &
                                    one,b(k,k),ldb,a(k + kb,k),lda)
                          call la_qsymm('RIGHT',uplo,n - k - kb + 1,kb,-half,a(k,k),lda,b( &
                                     k + kb,k),ldb,one,a(k + kb,k),lda)
                          call la_qsyr2k(uplo,'NO TRANSPOSE',n - k - kb + 1,kb,-one,a(k + kb,k &
                                    ),lda,b(k + kb,k),ldb,one,a(k + kb,k + kb),lda)
                          call la_qsymm('RIGHT',uplo,n - k - kb + 1,kb,-half,a(k,k),lda,b( &
                                     k + kb,k),ldb,one,a(k + kb,k),lda)
                          call la_qtrsm('LEFT',uplo,'NO TRANSPOSE','NON-UNIT',n - k - kb + 1, &
                                    kb,one,b(k + kb,k + kb),ldb,a(k + kb,k),lda)
                       end if
                    end do
                 end if
              else
                 if (upper) then
                    ! compute u*a*u**t
                    do k = 1,n,nb
                       kb = min(n - k + 1,nb)
                       ! update the upper triangle of a(1:k+kb-1,1:k+kb-1)
                       call la_qtrmm('LEFT',uplo,'NO TRANSPOSE','NON-UNIT',k - 1,kb,one, &
                                 b,ldb,a(1,k),lda)
                       call la_qsymm('RIGHT',uplo,k - 1,kb,half,a(k,k),lda,b(1,k), &
                                 ldb,one,a(1,k),lda)
                       call la_qsyr2k(uplo,'NO TRANSPOSE',k - 1,kb,one,a(1,k),lda,b( &
                                 1,k),ldb,one,a,lda)
                       call la_qsymm('RIGHT',uplo,k - 1,kb,half,a(k,k),lda,b(1,k), &
                                 ldb,one,a(1,k),lda)
                       call la_qtrmm('RIGHT',uplo,'TRANSPOSE','NON-UNIT',k - 1,kb,one,b( &
                                 k,k),ldb,a(1,k),lda)
                       call la_qsygs2(itype,uplo,kb,a(k,k),lda,b(k,k),ldb,info)

                    end do
                 else
                    ! compute l**t*a*l
                    do k = 1,n,nb
                       kb = min(n - k + 1,nb)
                       ! update the lower triangle of a(1:k+kb-1,1:k+kb-1)
                       call la_qtrmm('RIGHT',uplo,'NO TRANSPOSE','NON-UNIT',kb,k - 1,one, &
                                 b,ldb,a(k,1),lda)
                       call la_qsymm('LEFT',uplo,kb,k - 1,half,a(k,k),lda,b(k,1), &
                                 ldb,one,a(k,1),lda)
                       call la_qsyr2k(uplo,'TRANSPOSE',k - 1,kb,one,a(k,1),lda,b(k, &
                                 1),ldb,one,a,lda)
                       call la_qsymm('LEFT',uplo,kb,k - 1,half,a(k,k),lda,b(k,1), &
                                 ldb,one,a(k,1),lda)
                       call la_qtrmm('LEFT',uplo,'TRANSPOSE','NON-UNIT',kb,k - 1,one,b( &
                                 k,k),ldb,a(k,1),lda)
                       call la_qsygs2(itype,uplo,kb,a(k,k),lda,b(k,k),ldb,info)

                    end do
                 end if
              end if
           end if
           return
     end subroutine la_qsygst

     !> DSYGV: computes all the eigenvalues, and optionally, the eigenvectors
     !> of a real generalized symmetric-definite eigenproblem, of the form
     !> A*x=(lambda)*B*x,  A*Bx=(lambda)*x,  or B*A*x=(lambda)*x.
     !> Here A and B are assumed to be symmetric and B is also
     !> positive definite.

     subroutine la_qsygv(itype,jobz,uplo,n,a,lda,b,ldb,w,work,lwork,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: itype,lda,ldb,lwork,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: w(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,upper,wantz
           character :: trans
           integer(ilp) :: lwkmin,lwkopt,nb,neig
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1)
           info = 0
           if (itype < 1 .or. itype > 3) then
              info = -1
           else if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -2
           else if (.not. (upper .or. la_lsame(uplo,'L'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else if (ldb < max(1,n)) then
              info = -8
           end if
           if (info == 0) then
              lwkmin = max(1,3*n - 1)
              nb = la_ilaenv(1,'DSYTRD',uplo,n,-1,-1,-1)
              lwkopt = max(lwkmin, (nb + 2)*n)
              work(1) = lwkopt
              if (lwork < lwkmin .and. .not. lquery) then
                 info = -11
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSYGV ',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! form a cholesky factorization of b.
           call la_qpotrf(uplo,n,b,ldb,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem and solve.
           call la_qsygst(itype,uplo,n,a,lda,b,ldb,info)
           call la_qsyev(jobz,uplo,n,a,lda,w,work,lwork,info)
           if (wantz) then
              ! backtransform eigenvectors to the original problem.
              neig = n
              if (info > 0) neig = info - 1
              if (itype == 1 .or. itype == 2) then
                 ! for a*x=(lambda)*b*x and a*b*x=(lambda)*x;
                 ! backtransform eigenvectors: x = inv(l)**t*y or inv(u)*y
                 if (upper) then
                    trans = 'N'
                 else
                    trans = 'T'
                 end if
                 call la_qtrsm('LEFT',uplo,trans,'NON-UNIT',n,neig,one,b,ldb,a,lda)

              else if (itype == 3) then
                 ! for b*a*x=(lambda)*x;
                 ! backtransform eigenvectors: x = l*y or u**t*y
                 if (upper) then
                    trans = 'T'
                 else
                    trans = 'N'
                 end if
                 call la_qtrmm('LEFT',uplo,trans,'NON-UNIT',n,neig,one,b,ldb,a,lda)

              end if
           end if
           work(1) = lwkopt
           return
     end subroutine la_qsygv

     !> DSYGVD: computes all the eigenvalues, and optionally, the eigenvectors
     !> of a real generalized symmetric-definite eigenproblem, of the form
     !> A*x=(lambda)*B*x,  A*Bx=(lambda)*x,  or B*A*x=(lambda)*x.  Here A and
     !> B are assumed to be symmetric and B is also positive definite.
     !> If eigenvectors are desired, it uses a divide and conquer algorithm.
     !> The divide and conquer algorithm makes very mild assumptions about
     !> floating point arithmetic. It will work on machines with a guard
     !> digit in add/subtract, or on those binary machines without guard
     !> digits which subtract like the Cray X-MP, Cray Y-MP, Cray C-90, or
     !> Cray-2. It could conceivably fail on hexadecimal or decimal machines
     !> without guard digits, but we know of none.

     subroutine la_qsygvd(itype,jobz,uplo,n,a,lda,b,ldb,w,work,lwork,iwork,liwork, &
                info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: itype,lda,ldb,liwork,lwork,n
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: w(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,upper,wantz
           character :: trans
           integer(ilp) :: liopt,liwmin,lopt,lwmin
           ! Intrinsic Functions
           intrinsic :: real,max
           ! Executable Statements
           ! test the input parameters.
           wantz = la_lsame(jobz,'V')
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1 .or. liwork == -1)
           info = 0
           if (n <= 1) then
              liwmin = 1
              lwmin = 1
           else if (wantz) then
              liwmin = 3 + 5*n
              lwmin = 1 + 6*n + 2*n**2
           else
              liwmin = 1
              lwmin = 2*n + 1
           end if
           lopt = lwmin
           liopt = liwmin
           if (itype < 1 .or. itype > 3) then
              info = -1
           else if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -2
           else if (.not. (upper .or. la_lsame(uplo,'L'))) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else if (ldb < max(1,n)) then
              info = -8
           end if
           if (info == 0) then
              work(1) = lopt
              iwork(1) = liopt
              if (lwork < lwmin .and. .not. lquery) then
                 info = -11
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -13
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSYGVD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! form a cholesky factorization of b.
           call la_qpotrf(uplo,n,b,ldb,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem and solve.
           call la_qsygst(itype,uplo,n,a,lda,b,ldb,info)
           call la_qsyevd(jobz,uplo,n,a,lda,w,work,lwork,iwork,liwork,info)
           lopt = max(real(lopt,KIND=qp),real(work(1),KIND=qp))
           liopt = max(real(liopt,KIND=qp),real(iwork(1),KIND=qp))
           if (wantz .and. info == 0) then
              ! backtransform eigenvectors to the original problem.
              if (itype == 1 .or. itype == 2) then
                 ! for a*x=(lambda)*b*x and a*b*x=(lambda)*x;
                 ! backtransform eigenvectors: x = inv(l)**t*y or inv(u)*y
                 if (upper) then
                    trans = 'N'
                 else
                    trans = 'T'
                 end if
                 call la_qtrsm('LEFT',uplo,trans,'NON-UNIT',n,n,one,b,ldb,a,lda)

              else if (itype == 3) then
                 ! for b*a*x=(lambda)*x;
                 ! backtransform eigenvectors: x = l*y or u**t*y
                 if (upper) then
                    trans = 'T'
                 else
                    trans = 'N'
                 end if
                 call la_qtrmm('LEFT',uplo,trans,'NON-UNIT',n,n,one,b,ldb,a,lda)

              end if
           end if
           work(1) = lopt
           iwork(1) = liopt
           return
     end subroutine la_qsygvd

     !> DSYGVX: computes selected eigenvalues, and optionally, eigenvectors
     !> of a real generalized symmetric-definite eigenproblem, of the form
     !> A*x=(lambda)*B*x,  A*Bx=(lambda)*x,  or B*A*x=(lambda)*x.  Here A
     !> and B are assumed to be symmetric and B is also positive definite.
     !> Eigenvalues and eigenvectors can be selected by specifying either a
     !> range of values or a range of indices for the desired eigenvalues.

     subroutine la_qsygvx(itype,jobz,range,uplo,n,a,lda,b,ldb,vl,vu,il,iu,abstol, &
                m,w,z,ldz,work,lwork,iwork,ifail,info)
        ! -- lapack driver routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobz,range,uplo
           integer(ilp),intent(in) :: il,itype,iu,lda,ldb,ldz,lwork,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(in) :: abstol,vl,vu
           ! Array Arguments
           integer(ilp),intent(out) :: ifail(*),iwork(*)
           real(qp),intent(inout) :: a(lda,*),b(ldb,*)
           real(qp),intent(out) :: w(*),work(*),z(ldz,*)
       ! =====================================================================

           ! Local Scalars
           logical(lk) :: alleig,indeig,lquery,upper,valeig,wantz
           character :: trans
           integer(ilp) :: lwkmin,lwkopt,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           upper = la_lsame(uplo,'U')
           wantz = la_lsame(jobz,'V')
           alleig = la_lsame(range,'A')
           valeig = la_lsame(range,'V')
           indeig = la_lsame(range,'I')
           lquery = (lwork == -1)
           info = 0
           if (itype < 1 .or. itype > 3) then
              info = -1
           else if (.not. (wantz .or. la_lsame(jobz,'N'))) then
              info = -2
           else if (.not. (alleig .or. valeig .or. indeig)) then
              info = -3
           else if (.not. (upper .or. la_lsame(uplo,'L'))) then
              info = -4
           else if (n < 0) then
              info = -5
           else if (lda < max(1,n)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -9
           else
              if (valeig) then
                 if (n > 0 .and. vu <= vl) info = -11
              else if (indeig) then
                 if (il < 1 .or. il > max(1,n)) then
                    info = -12
                 else if (iu < min(n,il) .or. iu > n) then
                    info = -13
                 end if
              end if
           end if
           if (info == 0) then
              if (ldz < 1 .or. (wantz .and. ldz < n)) then
                 info = -18
              end if
           end if
           if (info == 0) then
              lwkmin = max(1,8*n)
              nb = la_ilaenv(1,'DSYTRD',uplo,n,-1,-1,-1)
              lwkopt = max(lwkmin, (nb + 3)*n)
              work(1) = lwkopt
              if (lwork < lwkmin .and. .not. lquery) then
                 info = -20
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DSYGVX',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           m = 0
           if (n == 0) then
              return
           end if
           ! form a cholesky factorization of b.
           call la_qpotrf(uplo,n,b,ldb,info)
           if (info /= 0) then
              info = n + info
              return
           end if
           ! transform problem to standard eigenvalue problem and solve.
           call la_qsygst(itype,uplo,n,a,lda,b,ldb,info)
           call la_qsyevx(jobz,range,uplo,n,a,lda,vl,vu,il,iu,abstol,m,w,z,ldz, &
                     work,lwork,iwork,ifail,info)
           if (wantz) then
              ! backtransform eigenvectors to the original problem.
              if (info > 0) m = info - 1
              if (itype == 1 .or. itype == 2) then
                 ! for a*x=(lambda)*b*x and a*b*x=(lambda)*x;
                 ! backtransform eigenvectors: x = inv(l)**t*y or inv(u)*y
                 if (upper) then
                    trans = 'N'
                 else
                    trans = 'T'
                 end if
                 call la_qtrsm('LEFT',uplo,trans,'NON-UNIT',n,m,one,b,ldb,z,ldz)

              else if (itype == 3) then
                 ! for b*a*x=(lambda)*x;
                 ! backtransform eigenvectors: x = l*y or u**t*y
                 if (upper) then
                    trans = 'T'
                 else
                    trans = 'N'
                 end if
                 call la_qtrmm('LEFT',uplo,trans,'NON-UNIT',n,m,one,b,ldb,z,ldz)

              end if
           end if
           ! set work(1) to optimal workspace size.
           work(1) = lwkopt
           return
     end subroutine la_qsygvx

     !> DSYTD2: reduces a real symmetric matrix A to symmetric tridiagonal
     !> form T by an orthogonal similarity transformation: Q**T * A * Q = T.

     pure subroutine la_qsytd2(uplo,n,a,lda,d,e,tau,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: d(*),e(*),tau(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i
           real(qp) :: alpha,taui
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('DSYTD2',-info)
              return
           end if
           ! quick return if possible
           if (n <= 0) return
           if (upper) then
              ! reduce the upper triangle of a
              do i = n - 1,1,-1
                 ! generate elementary reflector h(i) = i - tau * v * v**t
                 ! to annihilate a(1:i-1,i+1)
                 call la_qlarfg(i,a(i,i + 1),a(1,i + 1),1,taui)
                 e(i) = a(i,i + 1)
                 if (taui /= zero) then
                    ! apply h(i) from both sides to a(1:i,1:i)
                    a(i,i + 1) = one
                    ! compute  x := tau * a * v  storing x in tau(1:i)
                    call la_qsymv(uplo,i,taui,a,lda,a(1,i + 1),1,zero,tau,1)

                    ! compute  w := x - 1/2 * tau * (x**t * v) * v
                    alpha = -half*taui*la_qdot(i,tau,1,a(1,i + 1),1)
                    call la_qaxpy(i,alpha,a(1,i + 1),1,tau,1)
                    ! apply the transformation as a rank-2 update:
                       ! a := a - v * w**t - w * v**t
                    call la_qsyr2(uplo,i,-one,a(1,i + 1),1,tau,1,a,lda)
                    a(i,i + 1) = e(i)
                 end if
                 d(i + 1) = a(i + 1,i + 1)
                 tau(i) = taui
              end do
              d(1) = a(1,1)
           else
              ! reduce the lower triangle of a
              do i = 1,n - 1
                 ! generate elementary reflector h(i) = i - tau * v * v**t
                 ! to annihilate a(i+2:n,i)
                 call la_qlarfg(n - i,a(i + 1,i),a(min(i + 2,n),i),1,taui)
                 e(i) = a(i + 1,i)
                 if (taui /= zero) then
                    ! apply h(i) from both sides to a(i+1:n,i+1:n)
                    a(i + 1,i) = one
                    ! compute  x := tau * a * v  storing y in tau(i:n-1)
                    call la_qsymv(uplo,n - i,taui,a(i + 1,i + 1),lda,a(i + 1,i),1,zero, &
                              tau(i),1)
                    ! compute  w := x - 1/2 * tau * (x**t * v) * v
                    alpha = -half*taui*la_qdot(n - i,tau(i),1,a(i + 1,i),1)
                    call la_qaxpy(n - i,alpha,a(i + 1,i),1,tau(i),1)
                    ! apply the transformation as a rank-2 update:
                       ! a := a - v * w**t - w * v**t
                    call la_qsyr2(uplo,n - i,-one,a(i + 1,i),1,tau(i),1,a(i + 1,i + 1), &
                               lda)
                    a(i + 1,i) = e(i)
                 end if
                 d(i) = a(i,i)
                 tau(i) = taui
              end do
              d(n) = a(n,n)
           end if
           return
     end subroutine la_qsytd2

     !> DSYTRD: reduces a real symmetric matrix A to real symmetric
     !> tridiagonal form T by an orthogonal similarity transformation:
     !> Q**T * A * Q = T.

     pure subroutine la_qsytrd(uplo,n,a,lda,d,e,tau,work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,lwork,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: d(*),e(*),tau(*),work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,upper
           integer(ilp) :: i,iinfo,iws,j,kk,ldwork,lwkopt,nb,nbmin,nx
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters
           info = 0
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1)
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (lwork < 1 .and. .not. lquery) then
              info = -9
           end if
           if (info == 0) then
              ! determine the block size.
              nb = la_ilaenv(1,'DSYTRD',uplo,n,-1,-1,-1)
              lwkopt = n*nb
              work(1) = lwkopt
           end if
           if (info /= 0) then
              call la_xerbla('DSYTRD',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) then
              work(1) = 1
              return
           end if
           nx = n
           iws = 1
           if (nb > 1 .and. nb < n) then
              ! determine when to cross over from blocked to unblocked code
              ! (last block is always handled by unblocked code).
              nx = max(nb,la_ilaenv(3,'DSYTRD',uplo,n,-1,-1,-1))
              if (nx < n) then
                 ! determine if workspace is large enough for blocked code.
                 ldwork = n
                 iws = ldwork*nb
                 if (lwork < iws) then
                    ! not enough workspace to use optimal nb:  determine the
                    ! minimum value of nb, and reduce nb or force use of
                    ! unblocked code by setting nx = n.
                    nb = max(lwork/ldwork,1)
                    nbmin = la_ilaenv(2,'DSYTRD',uplo,n,-1,-1,-1)
                    if (nb < nbmin) nx = n
                 end if
              else
                 nx = n
              end if
           else
              nb = 1
           end if
           if (upper) then
              ! reduce the upper triangle of a.
              ! columns 1:kk are handled by the unblocked method.
              kk = n - ((n - nx + nb - 1)/nb)*nb
              do i = n - nb + 1,kk + 1,-nb
                 ! reduce columns i:i+nb-1 to tridiagonal form and form the
                 ! matrix w which is needed to update the unreduced part of
                 ! the matrix
                 call la_qlatrd(uplo,i + nb - 1,nb,a,lda,e,tau,work,ldwork)
                 ! update the unreduced submatrix a(1:i-1,1:i-1), using an
                 ! update of the form:  a := a - v*w**t - w*v**t
                 call la_qsyr2k(uplo,'NO TRANSPOSE',i - 1,nb,-one,a(1,i),lda,work, &
                           ldwork,one,a,lda)
                 ! copy superdiagonal elements back into a, and diagonal
                 ! elements into d
                 do j = i,i + nb - 1
                    a(j - 1,j) = e(j - 1)
                    d(j) = a(j,j)
                 end do
              end do
              ! use unblocked code to reduce the last or only block
              call la_qsytd2(uplo,kk,a,lda,d,e,tau,iinfo)
           else
              ! reduce the lower triangle of a
              do i = 1,n - nx,nb
                 ! reduce columns i:i+nb-1 to tridiagonal form and form the
                 ! matrix w which is needed to update the unreduced part of
                 ! the matrix
                 call la_qlatrd(uplo,n - i + 1,nb,a(i,i),lda,e(i),tau(i),work, &
                           ldwork)
                 ! update the unreduced submatrix a(i+ib:n,i+ib:n), using
                 ! an update of the form:  a := a - v*w**t - w*v**t
                 call la_qsyr2k(uplo,'NO TRANSPOSE',n - i - nb + 1,nb,-one,a(i + nb,i),lda, &
                           work(nb + 1),ldwork,one,a(i + nb,i + nb),lda)
                 ! copy subdiagonal elements back into a, and diagonal
                 ! elements into d
                 do j = i,i + nb - 1
                    a(j + 1,j) = e(j)
                    d(j) = a(j,j)
                 end do
              end do
              ! use unblocked code to reduce the last or only block
              call la_qsytd2(uplo,n - i + 1,a(i,i),lda,d(i),e(i),tau(i),iinfo)

           end if
           work(1) = lwkopt
           return
     end subroutine la_qsytrd

     !> DSYTRD_SB2ST: reduces a real symmetric band matrix A to real symmetric
     !> tridiagonal form T by a orthogonal similarity transformation:
     !> Q**T * A * Q = T.

     pure subroutine la_qsytrd_sb2st(stage1,vect,uplo,n,kd,ab,ldab,d,e,hous,lhous, &
               work,lwork,info)
#if defined(_OPENMP)
#endif
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: stage1,uplo,vect
           integer(ilp),intent(in) :: n,kd,ldab,lhous,lwork
           integer(ilp),intent(out) :: info
           ! Array Arguments
           real(qp),intent(out) :: d(*),e(*)
           real(qp),intent(inout) :: ab(ldab,*)
           real(qp),intent(out) :: hous(*),work(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: rzero = 0.0e+0_qp

           ! Local Scalars
           logical(lk) :: lquery,wantq,upper,afters1
           integer(ilp) :: i,m,k,ib,sweepid,myid,shift,stt,st,ed,stind,edind, &
           blklastind,colpt,thed,stepercol,grsiz,thgrsiz,thgrnb,thgrid,nbtiles,ttype, &
           tid,nthreads,debug,abdpos,abofdpos,dpos,ofdpos,awpos,inda,indw,apos,sizea, &
                     lda,indv,indtau,sidev,sizetau,ldv,lhmin,lwmin
           ! Intrinsic Functions
           intrinsic :: min,max,ceiling,real
           ! Executable Statements
           ! determine the minimal workspace size required.
           ! test the input parameters
           debug = 0
           info = 0
           afters1 = la_lsame(stage1,'Y')
           wantq = la_lsame(vect,'V')
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1) .or. (lhous == -1)
           ! determine the block size, the workspace size and the hous size.
           ib = la_ilaenv2stage(2,'DSYTRD_SB2ST',vect,n,kd,-1,-1)
           lhmin = la_ilaenv2stage(3,'DSYTRD_SB2ST',vect,n,kd,ib,-1)
           lwmin = la_ilaenv2stage(4,'DSYTRD_SB2ST',vect,n,kd,ib,-1)
           if (.not. afters1 .and. .not. la_lsame(stage1,'N')) then
              info = -1
           else if (.not. la_lsame(vect,'N')) then
              info = -2
           else if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -3
           else if (n < 0) then
              info = -4
           else if (kd < 0) then
              info = -5
           else if (ldab < (kd + 1)) then
              info = -7
           else if (lhous < lhmin .and. .not. lquery) then
              info = -11
           else if (lwork < lwmin .and. .not. lquery) then
              info = -13
           end if
           if (info == 0) then
              hous(1) = lhmin
              work(1) = lwmin
           end if
           if (info /= 0) then
              call la_xerbla('DSYTRD_SB2ST',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) then
               hous(1) = 1
               work(1) = 1
               return
           end if
           ! determine pointer position
           ldv = kd + ib
           sizetau = 2*n
           sidev = 2*n
           indtau = 1
           indv = indtau + sizetau
           lda = 2*kd + 1
           sizea = lda*n
           inda = 1
           indw = inda + sizea
           nthreads = 1
           tid = 0
           if (upper) then
               apos = inda + kd
               awpos = inda
               dpos = apos + kd
               ofdpos = dpos - 1
               abdpos = kd + 1
               abofdpos = kd
           else
               apos = inda
               awpos = inda + kd + 1
               dpos = apos
               ofdpos = dpos + 1
               abdpos = 1
               abofdpos = 2
           end if
           ! case kd=0:
           ! the matrix is diagonal. we just copy it (convert to "real" for
           ! real because d is double and the imaginary part should be 0)
           ! and store it in d. a sequential code here is better or
           ! in a parallel environment it might need two cores for d and e
           if (kd == 0) then
               do i = 1,n
                   d(i) = (ab(abdpos,i))
               end do
               do i = 1,n - 1
                   e(i) = rzero
               end do
               hous(1) = 1
               work(1) = 1
               return
           end if
           ! case kd=1:
           ! the matrix is already tridiagonal. we have to make diagonal
           ! and offdiagonal elements real, and store them in d and e.
           ! for that, for real precision just copy the diag and offdiag
           ! to d and e while for the complex case the bulge chasing is
           ! performed to convert the hermetian tridiagonal to symmetric
           ! tridiagonal. a simpler conversion formula might be used, but then
           ! updating the q matrix will be required and based if q is generated
           ! or not this might complicate the story.
           if (kd == 1) then
               do i = 1,n
                   d(i) = (ab(abdpos,i))
               end do
               if (upper) then
                   do i = 1,n - 1
                      e(i) = (ab(abofdpos,i + 1))
                   end do
               else
                   do i = 1,n - 1
                      e(i) = (ab(abofdpos,i))
                   end do
               end if
               hous(1) = 1
               work(1) = 1
               return
           end if
           ! main code start here.
           ! reduce the symmetric band of a to a tridiagonal matrix.
           thgrsiz = n
           grsiz = 1
           shift = 3
           nbtiles = ceiling(real(n,KIND=qp)/real(kd,KIND=qp))
           stepercol = ceiling(real(shift,KIND=qp)/real(grsiz,KIND=qp))
           thgrnb = ceiling(real(n - 1,KIND=qp)/real(thgrsiz,KIND=qp))
           call la_qlacpy("A",kd + 1,n,ab,ldab,work(apos),lda)
           call la_qlaset("A",kd,n,zero,zero,work(awpos),lda)
           ! openmp parallelisation start here
#if defined(_OPENMP)
!$OMP PARALLEL PRIVATE( TID, THGRID, BLKLASTIND )
!$OMP$         PRIVATE( THED, I, M, K, ST, ED, STT, SWEEPID )
!$OMP$         PRIVATE( MYID, TTYPE, COLPT, STIND, EDIND )
!$OMP$         SHARED ( UPLO, WANTQ, INDV, INDTAU, HOUS, WORK)
!$OMP$         SHARED ( N, KD, IB, NBTILES, LDA, LDV, INDA )
!$OMP$         SHARED ( STEPERCOL, THGRNB, THGRSIZ, GRSIZ, SHIFT )
!$OMP MASTER
#endif
           ! main bulge chasing loop
           loop_100: do thgrid = 1,thgrnb
               stt = (thgrid - 1)*thgrsiz + 1
               thed = min((stt + thgrsiz - 1), (n - 1))
               loop_110: do i = stt,n - 1
                   ed = min(i,thed)
                   if (stt > ed) exit
                   loop_120: do m = 1,stepercol
                       st = stt
                       loop_130: do sweepid = st,ed
                           loop_140: do k = 1,grsiz
                               myid = (i - sweepid)*(stepercol*grsiz) + (m - 1)*grsiz + k
                               if (myid == 1) then
                                   ttype = 1
                               else
                                   ttype = mod(myid,2) + 2
                               end if
                               if (ttype == 2) then
                                   colpt = (myid/2)*kd + sweepid
                                   stind = colpt - kd + 1
                                   edind = min(colpt,n)
                                   blklastind = colpt
                               else
                                   colpt = ((myid + 1)/2)*kd + sweepid
                                   stind = colpt - kd + 1
                                   edind = min(colpt,n)
                                   if ((stind >= edind - 1) .and. (edind == n)) then
                                       blklastind = n
                                   else
                                       blklastind = 0
                                   end if
                               end if
                               ! call the kernel
#if defined(_OPENMP) &&  _OPENMP >= 201307
                               if (ttype /= 1) then
!$OMP TASK DEPEND(in:WORK(MYID+SHIFT-1))
!$OMP$     DEPEND(in:WORK(MYID-1))
!$OMP$     DEPEND(out:WORK(MYID))
                                   tid = omp_get_thread_num()
                                   call la_qsb2st_kernels(uplo,wantq,ttype,stind,edind, &
                                   sweepid,n,kd,ib,work(inda),lda,hous(indv),hous( &
                                             indtau),ldv,work(indw + tid*kd))
!$OMP END TASK
                               else
!$OMP TASK DEPEND(in:WORK(MYID+SHIFT-1))
!$OMP$     DEPEND(out:WORK(MYID))
                                   tid = omp_get_thread_num()
                                   call la_qsb2st_kernels(uplo,wantq,ttype,stind,edind, &
                                   sweepid,n,kd,ib,work(inda),lda,hous(indv),hous( &
                                             indtau),ldv,work(indw + tid*kd))
!$OMP END TASK
                               end if
#else
                               call la_qsb2st_kernels(uplo,wantq,ttype,stind,edind, &
                               sweepid,n,kd,ib,work(inda),lda,hous(indv),hous(indtau), &
                                          ldv,work(indw + tid*kd))
#endif
                               if (blklastind >= (n - 1)) then
                                   stt = stt + 1
                                   exit
                               end if
                           end do loop_140
                       end do loop_130
                   end do loop_120
               end do loop_110
           end do loop_100
#if defined(_OPENMP)
!$OMP END MASTER
!$OMP END PARALLEL
#endif
           ! copy the diagonal from a to d. note that d is real thus only
           ! the real part is needed, the imaginary part should be zero.
           do i = 1,n
               d(i) = (work(dpos + (i - 1)*lda))
           end do
           ! copy the off diagonal from a to e. note that e is real thus only
           ! the real part is needed, the imaginary part should be zero.
           if (upper) then
               do i = 1,n - 1
                  e(i) = (work(ofdpos + i*lda))
               end do
           else
               do i = 1,n - 1
                  e(i) = (work(ofdpos + (i - 1)*lda))
               end do
           end if
           hous(1) = lhmin
           work(1) = lwmin
           return
     end subroutine la_qsytrd_sb2st

     !> DSYTRD_SY2SB: reduces a real symmetric matrix A to real symmetric
     !> band-diagonal form AB by a orthogonal similarity transformation:
     !> Q**T * A * Q = AB.

     pure subroutine la_qsytrd_sy2sb(uplo,n,kd,a,lda,ab,ldab,tau,work,lwork,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldab,lwork,n,kd
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: ab(ldab,*),tau(*),work(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: rone = 1.0e+0_qp

           ! Local Scalars
           logical(lk) :: lquery,upper
           integer(ilp) :: i,j,iinfo,lwmin,pn,pk,lk,ldt,ldw,lds2,lds1,ls2,ls1,lw,lt, &
                      tpos,wpos,s2pos,s1pos
           ! Intrinsic Functions
           intrinsic :: min,max
           ! Executable Statements
           ! determine the minimal workspace size required
           ! and test the input parameters
           info = 0
           upper = la_lsame(uplo,'U')
           lquery = (lwork == -1)
           lwmin = la_ilaenv2stage(4,'DSYTRD_SY2SB','',n,kd,-1,-1)
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kd < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldab < max(1,kd + 1)) then
              info = -7
           else if (lwork < lwmin .and. .not. lquery) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('DSYTRD_SY2SB',-info)
              return
           else if (lquery) then
              work(1) = lwmin
              return
           end if
           ! quick return if possible
           ! copy the upper/lower portion of a into ab
           if (n <= kd + 1) then
               if (upper) then
                   do i = 1,n
                       lk = min(kd + 1,i)
                       call la_qcopy(lk,a(i - lk + 1,i),1,ab(kd + 1 - lk + 1,i),1)
                   end do
               else
                   do i = 1,n
                       lk = min(kd + 1,n - i + 1)
                       call la_qcopy(lk,a(i,i),1,ab(1,i),1)
                   end do
               end if
               work(1) = 1
               return
           end if
           ! determine the pointer position for the workspace
           ldt = kd
           lds1 = kd
           lt = ldt*kd
           lw = n*kd
           ls1 = lds1*kd
           ls2 = lwmin - lt - lw - ls1
            ! ls2 = n*max(kd,factoptnb)
           tpos = 1
           wpos = tpos + lt
           s1pos = wpos + lw
           s2pos = s1pos + ls1
           if (upper) then
               ldw = kd
               lds2 = kd
           else
               ldw = n
               lds2 = n
           end if
           ! set the workspace of the triangular matrix t to zero once such a
           ! way every time t is generated the upper/lower portion will be always zero
           call la_qlaset("A",ldt,kd,zero,zero,work(tpos),ldt)
           if (upper) then
               do i = 1,n - kd,kd
                  pn = n - i - kd + 1
                  pk = min(n - i - kd + 1,kd)
                  ! compute the lq factorization of the current block
                  call la_qgelqf(kd,pn,a(i,i + kd),lda,tau(i),work(s2pos),ls2, &
                            iinfo)
                  ! copy the upper portion of a into ab
                  do j = i,i + pk - 1
                     lk = min(kd,n - j) + 1
                     call la_qcopy(lk,a(j,j),lda,ab(kd + 1,j),ldab - 1)
                  end do
                  call la_qlaset('LOWER',pk,pk,zero,one,a(i,i + kd),lda)
                  ! form the matrix t
                  call la_qlarft('FORWARD','ROWWISE',pn,pk,a(i,i + kd),lda,tau(i), &
                            work(tpos),ldt)
                  ! compute w:
                  call la_qgemm('CONJUGATE','NO TRANSPOSE',pk,pn,pk,one,work(tpos), &
                            ldt,a(i,i + kd),lda,zero,work(s2pos),lds2)
                  call la_qsymm('RIGHT',uplo,pk,pn,one,a(i + kd,i + kd),lda,work(s2pos &
                            ),lds2,zero,work(wpos),ldw)
                  call la_qgemm('NO TRANSPOSE','CONJUGATE',pk,pk,pn,one,work(wpos), &
                            ldw,work(s2pos),lds2,zero,work(s1pos),lds1)
                  call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',pk,pn,pk,-half,work( &
                            s1pos),lds1,a(i,i + kd),lda,one,work(wpos),ldw)
                  ! update the unreduced submatrix a(i+kd:n,i+kd:n), using
                  ! an update of the form:  a := a - v'*w - w'*v
                  call la_qsyr2k(uplo,'CONJUGATE',pn,pk,-one,a(i,i + kd),lda,work( &
                            wpos),ldw,rone,a(i + kd,i + kd),lda)
               end do
              ! copy the upper band to ab which is the band storage matrix
              do j = n - kd + 1,n
                 lk = min(kd,n - j) + 1
                 call la_qcopy(lk,a(j,j),lda,ab(kd + 1,j),ldab - 1)
              end do
           else
               ! reduce the lower triangle of a to lower band matrix
               loop_40: do i = 1,n - kd,kd
                  pn = n - i - kd + 1
                  pk = min(n - i - kd + 1,kd)
                  ! compute the qr factorization of the current block
                  call la_qgeqrf(pn,kd,a(i + kd,i),lda,tau(i),work(s2pos),ls2, &
                            iinfo)
                  ! copy the upper portion of a into ab
                  do j = i,i + pk - 1
                     lk = min(kd,n - j) + 1
                     call la_qcopy(lk,a(j,j),1,ab(1,j),1)
                  end do
                  call la_qlaset('UPPER',pk,pk,zero,one,a(i + kd,i),lda)
                  ! form the matrix t
                  call la_qlarft('FORWARD','COLUMNWISE',pn,pk,a(i + kd,i),lda,tau(i), &
                            work(tpos),ldt)
                  ! compute w:
                  call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',pn,pk,pk,one,a(i + kd,i), &
                             lda,work(tpos),ldt,zero,work(s2pos),lds2)
                  call la_qsymm('LEFT',uplo,pn,pk,one,a(i + kd,i + kd),lda,work(s2pos), &
                             lds2,zero,work(wpos),ldw)
                  call la_qgemm('CONJUGATE','NO TRANSPOSE',pk,pk,pn,one,work(s2pos), &
                            lds2,work(wpos),ldw,zero,work(s1pos),lds1)
                  call la_qgemm('NO TRANSPOSE','NO TRANSPOSE',pn,pk,pk,-half,a(i + kd,i &
                            ),lda,work(s1pos),lds1,one,work(wpos),ldw)
                  ! update the unreduced submatrix a(i+kd:n,i+kd:n), using
                  ! an update of the form:  a := a - v*w' - w*v'
                  call la_qsyr2k(uplo,'NO TRANSPOSE',pn,pk,-one,a(i + kd,i),lda,work( &
                            wpos),ldw,rone,a(i + kd,i + kd),lda)
                  ! ==================================================================
                  ! restore a for comparison and checking to be removed
                   ! do 45 j = i, i+pk-1
                      ! lk = min( kd, n-j ) + 1
                      ! call la_qcopy( lk, ab( 1, j ), 1, a( j, j ), 1 )
                      45 continue
                  ! ==================================================================
               end do loop_40
              ! copy the lower band to ab which is the band storage matrix
              do j = n - kd + 1,n
                 lk = min(kd,n - j) + 1
                 call la_qcopy(lk,a(j,j),1,ab(1,j),1)
              end do
           end if
           work(1) = lwmin
           return
     end subroutine la_qsytrd_sy2sb

     !> DTGEVC: computes some or all of the right and/or left eigenvectors of
     !> a pair of real matrices (S,P), where S is a quasi-triangular matrix
     !> and P is upper triangular.  Matrix pairs of this type are produced by
     !> the generalized Schur factorization of a matrix pair (A,B):
     !> A = Q*S*Z**T,  B = Q*P*Z**T
     !> as computed by DGGHRD + DHGEQZ.
     !> The right eigenvector x and the left eigenvector y of (S,P)
     !> corresponding to an eigenvalue w are defined by:
     !> S*x = w*P*x,  (y**H)*S = w*(y**H)*P,
     !> where y**H denotes the conjugate tranpose of y.
     !> The eigenvalues are not input to this routine, but are computed
     !> directly from the diagonal blocks of S and P.
     !> This routine returns the matrices X and/or Y of right and left
     !> eigenvectors of (S,P), or the products Z*X and/or Q*Y,
     !> where Z and Q are input matrices.
     !> If Q and Z are the orthogonal factors from the generalized Schur
     !> factorization of a matrix pair (A,B), then Z*X and Q*Y
     !> are the matrices of right and left eigenvectors of (A,B).

     pure subroutine la_qtgevc(side,howmny,select,n,s,lds,p,ldp,vl,ldvl,vr,ldvr, &
               mm,m,work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: howmny,side
           integer(ilp),intent(out) :: info,m
           integer(ilp),intent(in) :: ldp,lds,ldvl,ldvr,mm,n
           ! Array Arguments
           logical(lk),intent(in) :: select(*)
           real(qp),intent(in) :: p(ldp,*),s(lds,*)
           real(qp),intent(inout) :: vl(ldvl,*),vr(ldvr,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================
           ! Parameters
           real(qp),parameter :: safety = 1.0e+2_qp

           ! Local Scalars
           logical(lk) :: compl,compr,il2by2,ilabad,ilall,ilback,ilbbad,ilcomp,ilcplx, &
                     lsa,lsb
           integer(ilp) :: i,ibeg,ieig,iend,ihwmny,iinfo,im,iside,j,ja,jc,je,jr,jw, &
                     na,nw
           real(qp) :: acoef,acoefa,anorm,ascale,bcoefa,bcoefi,bcoefr,big,bignum,bnorm, &
           bscale,cim2a,cim2b,cimaga,cimagb,cre2a,cre2b,creala,crealb,dmin,safmin, &
                     salfar,sbeta,scale,small,temp,temp2,temp2i,temp2r,ulp,xmax,xscale
           ! Local Arrays
           real(qp) :: bdiag(2),sum(2,2),sums(2,2),sump(2,2)
           ! Intrinsic Functions
           intrinsic :: abs,max,min
           ! Executable Statements
           ! decode and test the input parameters
           if (la_lsame(howmny,'A')) then
              ihwmny = 1
              ilall = .true.
              ilback = .false.
           else if (la_lsame(howmny,'S')) then
              ihwmny = 2
              ilall = .false.
              ilback = .false.
           else if (la_lsame(howmny,'B')) then
              ihwmny = 3
              ilall = .true.
              ilback = .true.
           else
              ihwmny = -1
              ilall = .true.
           end if
           if (la_lsame(side,'R')) then
              iside = 1
              compl = .false.
              compr = .true.
           else if (la_lsame(side,'L')) then
              iside = 2
              compl = .true.
              compr = .false.
           else if (la_lsame(side,'B')) then
              iside = 3
              compl = .true.
              compr = .true.
           else
              iside = -1
           end if
           info = 0
           if (iside < 0) then
              info = -1
           else if (ihwmny < 0) then
              info = -2
           else if (n < 0) then
              info = -4
           else if (lds < max(1,n)) then
              info = -6
           else if (ldp < max(1,n)) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('DTGEVC',-info)
              return
           end if
           ! count the number of eigenvectors to be computed
           if (.not. ilall) then
              im = 0
              ilcplx = .false.
              loop_10: do j = 1,n
                 if (ilcplx) then
                    ilcplx = .false.
                    cycle loop_10
                 end if
                 if (j < n) then
                    if (s(j + 1,j) /= zero) ilcplx = .true.
                 end if
                 if (ilcplx) then
                    if (select(j) .or. select(j + 1)) im = im + 2
                 else
                    if (select(j)) im = im + 1
                 end if
              end do loop_10
           else
              im = n
           end if
           ! check 2-by-2 diagonal blocks of a, b
           ilabad = .false.
           ilbbad = .false.
           do j = 1,n - 1
              if (s(j + 1,j) /= zero) then
                 if (p(j,j) == zero .or. p(j + 1,j + 1) == zero .or. p(j,j + 1) /= zero) ilbbad = &
                           .true.
                 if (j < n - 1) then
                    if (s(j + 2,j + 1) /= zero) ilabad = .true.
                 end if
              end if
           end do
           if (ilabad) then
              info = -5
           else if (ilbbad) then
              info = -7
           else if (compl .and. ldvl < n .or. ldvl < 1) then
              info = -10
           else if (compr .and. ldvr < n .or. ldvr < 1) then
              info = -12
           else if (mm < im) then
              info = -13
           end if
           if (info /= 0) then
              call la_xerbla('DTGEVC',-info)
              return
           end if
           ! quick return if possible
           m = im
           if (n == 0) return
           ! machine constants
           safmin = la_qlamch('SAFE MINIMUM')
           big = one/safmin
           call la_qlabad(safmin,big)
           ulp = la_qlamch('EPSILON')*la_qlamch('BASE')
           small = safmin*n/ulp
           big = one/small
           bignum = one/(safmin*n)
           ! compute the 1-norm of each column of the strictly upper triangular
           ! part (i.e., excluding all elements belonging to the diagonal
           ! blocks) of a and b to check for possible overflow in the
           ! triangular solver.
           anorm = abs(s(1,1))
           if (n > 1) anorm = anorm + abs(s(2,1))
           bnorm = abs(p(1,1))
           work(1) = zero
           work(n + 1) = zero
           do j = 2,n
              temp = zero
              temp2 = zero
              if (s(j,j - 1) == zero) then
                 iend = j - 1
              else
                 iend = j - 2
              end if
              do i = 1,iend
                 temp = temp + abs(s(i,j))
                 temp2 = temp2 + abs(p(i,j))
              end do
              work(j) = temp
              work(n + j) = temp2
              do i = iend + 1,min(j + 1,n)
                 temp = temp + abs(s(i,j))
                 temp2 = temp2 + abs(p(i,j))
              end do
              anorm = max(anorm,temp)
              bnorm = max(bnorm,temp2)
           end do
           ascale = one/max(anorm,safmin)
           bscale = one/max(bnorm,safmin)
           ! left eigenvectors
           if (compl) then
              ieig = 0
              ! main loop over eigenvalues
              ilcplx = .false.
              loop_220: do je = 1,n
                 ! skip this iteration if (a) howmny='s' and select=.false., or
                 ! (b) this would be the second of a complex pair.
                 ! check for complex eigenvalue, so as to be sure of which
                 ! entry(-ies) of select to look at.
                 if (ilcplx) then
                    ilcplx = .false.
                    cycle loop_220
                 end if
                 nw = 1
                 if (je < n) then
                    if (s(je + 1,je) /= zero) then
                       ilcplx = .true.
                       nw = 2
                    end if
                 end if
                 if (ilall) then
                    ilcomp = .true.
                 else if (ilcplx) then
                    ilcomp = select(je) .or. select(je + 1)
                 else
                    ilcomp = select(je)
                 end if
                 if (.not. ilcomp) cycle loop_220
                 ! decide if (a) singular pencil, (b) real eigenvalue, or
                 ! (c) complex eigenvalue.
                 if (.not. ilcplx) then
                    if (abs(s(je,je)) <= safmin .and. abs(p(je,je)) <= safmin) then
                       ! singular matrix pencil -- return unit eigenvector
                       ieig = ieig + 1
                       do jr = 1,n
                          vl(jr,ieig) = zero
                       end do
                       vl(ieig,ieig) = one
                       cycle loop_220
                    end if
                 end if
                 ! clear vector
                 do jr = 1,nw*n
                    work(2*n + jr) = zero
                 end do
                                                       ! t
                 ! compute coefficients in  ( a a - b b )  y = 0
                    ! a  is  acoef
                    ! b  is  bcoefr + i*bcoefi
                 if (.not. ilcplx) then
                    ! real eigenvalue
                    temp = one/max(abs(s(je,je))*ascale,abs(p(je,je))*bscale,safmin &
                              )
                    salfar = (temp*s(je,je))*ascale
                    sbeta = (temp*p(je,je))*bscale
                    acoef = sbeta*ascale
                    bcoefr = salfar*bscale
                    bcoefi = zero
                    ! scale to avoid underflow
                    scale = one
                    lsa = abs(sbeta) >= safmin .and. abs(acoef) < small
                    lsb = abs(salfar) >= safmin .and. abs(bcoefr) < small
                    if (lsa) scale = (small/abs(sbeta))*min(anorm,big)
                    if (lsb) scale = max(scale, (small/abs(salfar))*min(bnorm,big))

                    if (lsa .or. lsb) then
                       scale = min(scale,one/(safmin*max(one,abs(acoef),abs(bcoefr))) &
                                 )
                       if (lsa) then
                          acoef = ascale*(scale*sbeta)
                       else
                          acoef = scale*acoef
                       end if
                       if (lsb) then
                          bcoefr = bscale*(scale*salfar)
                       else
                          bcoefr = scale*bcoefr
                       end if
                    end if
                    acoefa = abs(acoef)
                    bcoefa = abs(bcoefr)
                    ! first component is 1
                    work(2*n + je) = one
                    xmax = one
                 else
                    ! complex eigenvalue
                    call la_qlag2(s(je,je),lds,p(je,je),ldp,safmin*safety,acoef, &
                              temp,bcoefr,temp2,bcoefi)
                    bcoefi = -bcoefi
                    if (bcoefi == zero) then
                       info = je
                       return
                    end if
                    ! scale to avoid over/underflow
                    acoefa = abs(acoef)
                    bcoefa = abs(bcoefr) + abs(bcoefi)
                    scale = one
                    if (acoefa*ulp < safmin .and. acoefa >= safmin) scale = (safmin/ulp)/ &
                              acoefa
                    if (bcoefa*ulp < safmin .and. bcoefa >= safmin) scale = max(scale, (safmin/ &
                              ulp)/bcoefa)
                    if (safmin*acoefa > ascale) scale = ascale/(safmin*acoefa)
                    if (safmin*bcoefa > bscale) scale = min(scale,bscale/(safmin*bcoefa))

                    if (scale /= one) then
                       acoef = scale*acoef
                       acoefa = abs(acoef)
                       bcoefr = scale*bcoefr
                       bcoefi = scale*bcoefi
                       bcoefa = abs(bcoefr) + abs(bcoefi)
                    end if
                    ! compute first two components of eigenvector
                    temp = acoef*s(je + 1,je)
                    temp2r = acoef*s(je,je) - bcoefr*p(je,je)
                    temp2i = -bcoefi*p(je,je)
                    if (abs(temp) > abs(temp2r) + abs(temp2i)) then
                       work(2*n + je) = one
                       work(3*n + je) = zero
                       work(2*n + je + 1) = -temp2r/temp
                       work(3*n + je + 1) = -temp2i/temp
                    else
                       work(2*n + je + 1) = one
                       work(3*n + je + 1) = zero
                       temp = acoef*s(je,je + 1)
                       work(2*n + je) = (bcoefr*p(je + 1,je + 1) - acoef*s(je + 1,je + 1))/ &
                                 temp
                       work(3*n + je) = bcoefi*p(je + 1,je + 1)/temp
                    end if
                    xmax = max(abs(work(2*n + je)) + abs(work(3*n + je)),abs(work(2*n + je + 1) &
                              ) + abs(work(3*n + je + 1)))
                 end if
                 dmin = max(ulp*acoefa*anorm,ulp*bcoefa*bnorm,safmin)
                                                 ! t
                 ! triangular solve of  (a a - b b)  y = 0
                                         ! t
                 ! (rowwise in  (a a - b b) , or columnwise in (a a - b b) )
                 il2by2 = .false.
                 loop_160: do j = je + nw,n
                    if (il2by2) then
                       il2by2 = .false.
                       cycle loop_160
                    end if
                    na = 1
                    bdiag(1) = p(j,j)
                    if (j < n) then
                       if (s(j + 1,j) /= zero) then
                          il2by2 = .true.
                          bdiag(2) = p(j + 1,j + 1)
                          na = 2
                       end if
                    end if
                    ! check whether scaling is necessary for dot products
                    xscale = one/max(one,xmax)
                    temp = max(work(j),work(n + j),acoefa*work(j) + bcoefa*work(n + j))

                    if (il2by2) temp = max(temp,work(j + 1),work(n + j + 1),acoefa*work(j + 1) + &
                              bcoefa*work(n + j + 1))
                    if (temp > bignum*xscale) then
                       do jw = 0,nw - 1
                          do jr = je,j - 1
                             work((jw + 2)*n + jr) = xscale*work((jw + 2)*n + jr)
                          end do
                       end do
                       xmax = xmax*xscale
                    end if
                    ! compute dot products
                          ! j-1
                    ! sum = sum  conjg( a*s(k,j) - b*p(k,j) )*x(k)
                          ! k=je
                    ! to reduce the op count, this is done as
                    ! _        j-1                  _        j-1
                    ! a*conjg( sum  s(k,j)*x(k) ) - b*conjg( sum  p(k,j)*x(k) )
                             ! k=je                          k=je
                    ! which may cause underflow problems if a or b are close
                    ! to underflow.  (e.g., less than small.)
                    do jw = 1,nw
                       do ja = 1,na
                          sums(ja,jw) = zero
                          sump(ja,jw) = zero
                          do jr = je,j - 1
                             sums(ja,jw) = sums(ja,jw) + s(jr,j + ja - 1)*work((jw + 1)*n + jr &
                                       )
                             sump(ja,jw) = sump(ja,jw) + p(jr,j + ja - 1)*work((jw + 1)*n + jr &
                                       )
                          end do
                       end do
                    end do
                    do ja = 1,na
                       if (ilcplx) then
                          sum(ja,1) = -acoef*sums(ja,1) + bcoefr*sump(ja,1) - bcoefi*sump( &
                                    ja,2)
                          sum(ja,2) = -acoef*sums(ja,2) + bcoefr*sump(ja,2) + bcoefi*sump( &
                                    ja,1)
                       else
                          sum(ja,1) = -acoef*sums(ja,1) + bcoefr*sump(ja,1)
                       end if
                    end do
                                        ! t
                    ! solve  ( a a - b b )  y = sum(,)
                    ! with scaling and perturbation of the denominator
                    call la_qlaln2(.true.,na,nw,dmin,acoef,s(j,j),lds,bdiag(1), &
                    bdiag(2),sum,2,bcoefr,bcoefi,work(2*n + j),n,scale,temp,iinfo)

                    if (scale < one) then
                       do jw = 0,nw - 1
                          do jr = je,j - 1
                             work((jw + 2)*n + jr) = scale*work((jw + 2)*n + jr)
                          end do
                       end do
                       xmax = scale*xmax
                    end if
                    xmax = max(xmax,temp)
                 end do loop_160
                 ! copy eigenvector to vl, back transforming if
                 ! howmny='b'.
                 ieig = ieig + 1
                 if (ilback) then
                    do jw = 0,nw - 1
                       call la_qgemv('N',n,n + 1 - je,one,vl(1,je),ldvl,work((jw + 2)*n + &
                                 je),1,zero,work((jw + 4)*n + 1),1)
                    end do
                    call la_qlacpy(' ',n,nw,work(4*n + 1),n,vl(1,je),ldvl)
                    ibeg = 1
                 else
                    call la_qlacpy(' ',n,nw,work(2*n + 1),n,vl(1,ieig),ldvl)
                    ibeg = je
                 end if
                 ! scale eigenvector
                 xmax = zero
                 if (ilcplx) then
                    do j = ibeg,n
                       xmax = max(xmax,abs(vl(j,ieig)) + abs(vl(j,ieig + 1)))
                    end do
                 else
                    do j = ibeg,n
                       xmax = max(xmax,abs(vl(j,ieig)))
                    end do
                 end if
                 if (xmax > safmin) then
                    xscale = one/xmax
                    do jw = 0,nw - 1
                       do jr = ibeg,n
                          vl(jr,ieig + jw) = xscale*vl(jr,ieig + jw)
                       end do
                    end do
                 end if
                 ieig = ieig + nw - 1
              end do loop_220
           end if
           ! right eigenvectors
           if (compr) then
              ieig = im + 1
              ! main loop over eigenvalues
              ilcplx = .false.
              loop_500: do je = n,1,-1
                 ! skip this iteration if (a) howmny='s' and select=.false., or
                 ! (b) this would be the second of a complex pair.
                 ! check for complex eigenvalue, so as to be sure of which
                 ! entry(-ies) of select to look at -- if complex, select(je)
                 ! or select(je-1).
                 ! if this is a complex pair, the 2-by-2 diagonal block
                 ! corresponding to the eigenvalue is in rows/columns je-1:je
                 if (ilcplx) then
                    ilcplx = .false.
                    cycle loop_500
                 end if
                 nw = 1
                 if (je > 1) then
                    if (s(je,je - 1) /= zero) then
                       ilcplx = .true.
                       nw = 2
                    end if
                 end if
                 if (ilall) then
                    ilcomp = .true.
                 else if (ilcplx) then
                    ilcomp = select(je) .or. select(je - 1)
                 else
                    ilcomp = select(je)
                 end if
                 if (.not. ilcomp) cycle loop_500
                 ! decide if (a) singular pencil, (b) real eigenvalue, or
                 ! (c) complex eigenvalue.
                 if (.not. ilcplx) then
                    if (abs(s(je,je)) <= safmin .and. abs(p(je,je)) <= safmin) then
                       ! singular matrix pencil -- unit eigenvector
                       ieig = ieig - 1
                       do jr = 1,n
                          vr(jr,ieig) = zero
                       end do
                       vr(ieig,ieig) = one
                       cycle loop_500
                    end if
                 end if
                 ! clear vector
                 do jw = 0,nw - 1
                    do jr = 1,n
                       work((jw + 2)*n + jr) = zero
                    end do
                 end do
                 ! compute coefficients in  ( a a - b b ) x = 0
                    ! a  is  acoef
                    ! b  is  bcoefr + i*bcoefi
                 if (.not. ilcplx) then
                    ! real eigenvalue
                    temp = one/max(abs(s(je,je))*ascale,abs(p(je,je))*bscale,safmin &
                              )
                    salfar = (temp*s(je,je))*ascale
                    sbeta = (temp*p(je,je))*bscale
                    acoef = sbeta*ascale
                    bcoefr = salfar*bscale
                    bcoefi = zero
                    ! scale to avoid underflow
                    scale = one
                    lsa = abs(sbeta) >= safmin .and. abs(acoef) < small
                    lsb = abs(salfar) >= safmin .and. abs(bcoefr) < small
                    if (lsa) scale = (small/abs(sbeta))*min(anorm,big)
                    if (lsb) scale = max(scale, (small/abs(salfar))*min(bnorm,big))

                    if (lsa .or. lsb) then
                       scale = min(scale,one/(safmin*max(one,abs(acoef),abs(bcoefr))) &
                                 )
                       if (lsa) then
                          acoef = ascale*(scale*sbeta)
                       else
                          acoef = scale*acoef
                       end if
                       if (lsb) then
                          bcoefr = bscale*(scale*salfar)
                       else
                          bcoefr = scale*bcoefr
                       end if
                    end if
                    acoefa = abs(acoef)
                    bcoefa = abs(bcoefr)
                    ! first component is 1
                    work(2*n + je) = one
                    xmax = one
                    ! compute contribution from column je of a and b to sum
                    ! (see "further details", above.)
                    do jr = 1,je - 1
                       work(2*n + jr) = bcoefr*p(jr,je) - acoef*s(jr,je)
                    end do
                 else
                    ! complex eigenvalue
                    call la_qlag2(s(je - 1,je - 1),lds,p(je - 1,je - 1),ldp,safmin*safety, &
                              acoef,temp,bcoefr,temp2,bcoefi)
                    if (bcoefi == zero) then
                       info = je - 1
                       return
                    end if
                    ! scale to avoid over/underflow
                    acoefa = abs(acoef)
                    bcoefa = abs(bcoefr) + abs(bcoefi)
                    scale = one
                    if (acoefa*ulp < safmin .and. acoefa >= safmin) scale = (safmin/ulp)/ &
                              acoefa
                    if (bcoefa*ulp < safmin .and. bcoefa >= safmin) scale = max(scale, (safmin/ &
                              ulp)/bcoefa)
                    if (safmin*acoefa > ascale) scale = ascale/(safmin*acoefa)
                    if (safmin*bcoefa > bscale) scale = min(scale,bscale/(safmin*bcoefa))

                    if (scale /= one) then
                       acoef = scale*acoef
                       acoefa = abs(acoef)
                       bcoefr = scale*bcoefr
                       bcoefi = scale*bcoefi
                       bcoefa = abs(bcoefr) + abs(bcoefi)
                    end if
                    ! compute first two components of eigenvector
                    ! and contribution to sums
                    temp = acoef*s(je,je - 1)
                    temp2r = acoef*s(je,je) - bcoefr*p(je,je)
                    temp2i = -bcoefi*p(je,je)
                    if (abs(temp) >= abs(temp2r) + abs(temp2i)) then
                       work(2*n + je) = one
                       work(3*n + je) = zero
                       work(2*n + je - 1) = -temp2r/temp
                       work(3*n + je - 1) = -temp2i/temp
                    else
                       work(2*n + je - 1) = one
                       work(3*n + je - 1) = zero
                       temp = acoef*s(je - 1,je)
                       work(2*n + je) = (bcoefr*p(je - 1,je - 1) - acoef*s(je - 1,je - 1))/ &
                                 temp
                       work(3*n + je) = bcoefi*p(je - 1,je - 1)/temp
                    end if
                    xmax = max(abs(work(2*n + je)) + abs(work(3*n + je)),abs(work(2*n + je - 1) &
                              ) + abs(work(3*n + je - 1)))
                    ! compute contribution from columns je and je-1
                    ! of a and b to the sums.
                    creala = acoef*work(2*n + je - 1)
                    cimaga = acoef*work(3*n + je - 1)
                    crealb = bcoefr*work(2*n + je - 1) - bcoefi*work(3*n + je - 1)
                    cimagb = bcoefi*work(2*n + je - 1) + bcoefr*work(3*n + je - 1)
                    cre2a = acoef*work(2*n + je)
                    cim2a = acoef*work(3*n + je)
                    cre2b = bcoefr*work(2*n + je) - bcoefi*work(3*n + je)
                    cim2b = bcoefi*work(2*n + je) + bcoefr*work(3*n + je)
                    do jr = 1,je - 2
                       work(2*n + jr) = -creala*s(jr,je - 1) + crealb*p(jr,je - 1) - cre2a*s(jr, &
                                 je) + cre2b*p(jr,je)
                       work(3*n + jr) = -cimaga*s(jr,je - 1) + cimagb*p(jr,je - 1) - cim2a*s(jr, &
                                 je) + cim2b*p(jr,je)
                    end do
                 end if
                 dmin = max(ulp*acoefa*anorm,ulp*bcoefa*bnorm,safmin)
                 ! columnwise triangular solve of  (a a - b b)  x = 0
                 il2by2 = .false.
                 loop_370: do j = je - nw,1,-1
                    ! if a 2-by-2 block, is in position j-1:j, wait until
                    ! next iteration to process it (when it will be j:j+1)
                    if (.not. il2by2 .and. j > 1) then
                       if (s(j,j - 1) /= zero) then
                          il2by2 = .true.
                          cycle loop_370
                       end if
                    end if
                    bdiag(1) = p(j,j)
                    if (il2by2) then
                       na = 2
                       bdiag(2) = p(j + 1,j + 1)
                    else
                       na = 1
                    end if
                    ! compute x(j) (and x(j+1), if 2-by-2 block)
                    call la_qlaln2(.false.,na,nw,dmin,acoef,s(j,j),lds,bdiag(1), &
                    bdiag(2),work(2*n + j),n,bcoefr,bcoefi,sum,2,scale,temp,iinfo)

                    if (scale < one) then
                       do jw = 0,nw - 1
                          do jr = 1,je
                             work((jw + 2)*n + jr) = scale*work((jw + 2)*n + jr)
                          end do
                       end do
                    end if
                    xmax = max(scale*xmax,temp)
                    do jw = 1,nw
                       do ja = 1,na
                          work((jw + 1)*n + j + ja - 1) = sum(ja,jw)
                       end do
                    end do
                    ! w = w + x(j)*(a s(*,j) - b p(*,j) ) with scaling
                    if (j > 1) then
                       ! check whether scaling is necessary for sum.
                       xscale = one/max(one,xmax)
                       temp = acoefa*work(j) + bcoefa*work(n + j)
                       if (il2by2) temp = max(temp,acoefa*work(j + 1) + bcoefa*work(n + j + 1))

                       temp = max(temp,acoefa,bcoefa)
                       if (temp > bignum*xscale) then
                          do jw = 0,nw - 1
                             do jr = 1,je
                                work((jw + 2)*n + jr) = xscale*work((jw + 2)*n + jr)
                             end do
                          end do
                          xmax = xmax*xscale
                       end if
                       ! compute the contributions of the off-diagonals of
                       ! column j (and j+1, if 2-by-2 block) of a and b to the
                       ! sums.
                       do ja = 1,na
                          if (ilcplx) then
                             creala = acoef*work(2*n + j + ja - 1)
                             cimaga = acoef*work(3*n + j + ja - 1)
                             crealb = bcoefr*work(2*n + j + ja - 1) - bcoefi*work(3*n + j + ja - 1)
                             cimagb = bcoefi*work(2*n + j + ja - 1) + bcoefr*work(3*n + j + ja - 1)
                             do jr = 1,j - 1
                                work(2*n + jr) = work(2*n + jr) - creala*s(jr,j + ja - 1) + crealb*p( &
                                           jr,j + ja - 1)
                                work(3*n + jr) = work(3*n + jr) - cimaga*s(jr,j + ja - 1) + cimagb*p( &
                                           jr,j + ja - 1)
                             end do
                          else
                             creala = acoef*work(2*n + j + ja - 1)
                             crealb = bcoefr*work(2*n + j + ja - 1)
                             do jr = 1,j - 1
                                work(2*n + jr) = work(2*n + jr) - creala*s(jr,j + ja - 1) + crealb*p( &
                                           jr,j + ja - 1)
                             end do
                          end if
                       end do
                    end if
                    il2by2 = .false.
                 end do loop_370
                 ! copy eigenvector to vr, back transforming if
                 ! howmny='b'.
                 ieig = ieig - nw
                 if (ilback) then
                    do jw = 0,nw - 1
                       do jr = 1,n
                          work((jw + 4)*n + jr) = work((jw + 2)*n + 1)*vr(jr,1)
                       end do
                       ! a series of compiler directives to defeat
                       ! vectorization for the next loop
                       do jc = 2,je
                          do jr = 1,n
                             work((jw + 4)*n + jr) = work((jw + 4)*n + jr) + work((jw + 2)*n + jc) &
                                       *vr(jr,jc)
                          end do
                       end do
                    end do
                    do jw = 0,nw - 1
                       do jr = 1,n
                          vr(jr,ieig + jw) = work((jw + 4)*n + jr)
                       end do
                    end do
                    iend = n
                 else
                    do jw = 0,nw - 1
                       do jr = 1,n
                          vr(jr,ieig + jw) = work((jw + 2)*n + jr)
                       end do
                    end do
                    iend = je
                 end if
                 ! scale eigenvector
                 xmax = zero
                 if (ilcplx) then
                    do j = 1,iend
                       xmax = max(xmax,abs(vr(j,ieig)) + abs(vr(j,ieig + 1)))
                    end do
                 else
                    do j = 1,iend
                       xmax = max(xmax,abs(vr(j,ieig)))
                    end do
                 end if
                 if (xmax > safmin) then
                    xscale = one/xmax
                    do jw = 0,nw - 1
                       do jr = 1,iend
                          vr(jr,ieig + jw) = xscale*vr(jr,ieig + jw)
                       end do
                    end do
                 end if
              end do loop_500
           end if
           return
     end subroutine la_qtgevc

     !> DTGEX2: swaps adjacent diagonal blocks (A11, B11) and (A22, B22)
     !> of size 1-by-1 or 2-by-2 in an upper (quasi) triangular matrix pair
     !> (A, B) by an orthogonal equivalence transformation.
     !> (A, B) must be in generalized real Schur canonical form (as returned
     !> by DGGES), i.e. A is block upper triangular with 1-by-1 and 2-by-2
     !> diagonal blocks. B is upper triangular.
     !> Optionally, the matrices Q and Z of generalized Schur vectors are
     !> updated.
     !> Q(in) * A(in) * Z(in)**T = Q(out) * A(out) * Z(out)**T
     !> Q(in) * B(in) * Z(in)**T = Q(out) * B(out) * Z(out)**T

     pure subroutine la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,j1,n1,n2, &
               work,lwork,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: wantq,wantz
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: j1,lda,ldb,ldq,ldz,lwork,n,n1,n2
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================
        ! replaced various illegal calls to la_qcopy by calls to la_qlaset, or by do
        ! loops. sven hammarling, 1/5/02.
           ! Parameters
           real(qp),parameter :: twenty = 2.0e+01_qp
           integer(ilp),parameter :: ldst = 4
           logical(lk),parameter :: wands = .true.

           ! Local Scalars
           logical(lk) :: strong,weak
           integer(ilp) :: i,idum,linfo,m
           real(qp) :: bqra21,brqa21,ddum,dnorma,dnormb,dscale,dsum,eps,f,g,sa,sb, &
                     scale,smlnum,thresha,threshb
           ! Local Arrays
           integer(ilp) :: iwork(ldst)
           real(qp) :: ai(2),ar(2),be(2),ir(ldst,ldst),ircop(ldst,ldst),li(ldst,ldst),licop( &
           ldst,ldst),s(ldst,ldst),scpy(ldst,ldst),t(ldst,ldst),taul(ldst),taur(ldst),tcpy( &
                     ldst,ldst)
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Executable Statements
           info = 0
           ! quick return if possible
           if (n <= 1 .or. n1 <= 0 .or. n2 <= 0) return
           if (n1 > n .or. (j1 + n1) > n) return
           m = n1 + n2
           if (lwork < max(1,n*m,m*m*2)) then
              info = -16
              work(1) = max(1,n*m,m*m*2)
              return
           end if
           weak = .false.
           strong = .false.
           ! make a local copy of selected block
           call la_qlaset('FULL',ldst,ldst,zero,zero,li,ldst)
           call la_qlaset('FULL',ldst,ldst,zero,zero,ir,ldst)
           call la_qlacpy('FULL',m,m,a(j1,j1),lda,s,ldst)
           call la_qlacpy('FULL',m,m,b(j1,j1),ldb,t,ldst)
           ! compute threshold for testing acceptance of swapping.
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')/eps
           dscale = zero
           dsum = one
           call la_qlacpy('FULL',m,m,s,ldst,work,m)
           call la_qlassq(m*m,work,1,dscale,dsum)
           dnorma = dscale*sqrt(dsum)
           dscale = zero
           dsum = one
           call la_qlacpy('FULL',m,m,t,ldst,work,m)
           call la_qlassq(m*m,work,1,dscale,dsum)
           dnormb = dscale*sqrt(dsum)
           ! thres has been changed from
              ! thresh = max( ten*eps*sa, smlnum )
           ! to
              ! thresh = max( twenty*eps*sa, smlnum )
           ! on 04/01/10.
           ! "bug" reported by ondra kamenik, confirmed by julie langou, fixed by
           ! jim demmel and guillaume revy. see forum post 1783.
           thresha = max(twenty*eps*dnorma,smlnum)
           threshb = max(twenty*eps*dnormb,smlnum)
           if (m == 2) then
              ! case 1: swap 1-by-1 and 1-by-1 blocks.
              ! compute orthogonal ql and rq that swap 1-by-1 and 1-by-1 blocks
              ! using givens rotations and perform the swap tentatively.
              f = s(2,2)*t(1,1) - t(2,2)*s(1,1)
              g = s(2,2)*t(1,2) - t(2,2)*s(1,2)
              sa = abs(s(2,2))*abs(t(1,1))
              sb = abs(s(1,1))*abs(t(2,2))
              call la_qlartg(f,g,ir(1,2),ir(1,1),ddum)
              ir(2,1) = -ir(1,2)
              ir(2,2) = ir(1,1)
              call la_qrot(2,s(1,1),1,s(1,2),1,ir(1,1),ir(2,1))
              call la_qrot(2,t(1,1),1,t(1,2),1,ir(1,1),ir(2,1))
              if (sa >= sb) then
                 call la_qlartg(s(1,1),s(2,1),li(1,1),li(2,1),ddum)
              else
                 call la_qlartg(t(1,1),t(2,1),li(1,1),li(2,1),ddum)
              end if
              call la_qrot(2,s(1,1),ldst,s(2,1),ldst,li(1,1),li(2,1))

              call la_qrot(2,t(1,1),ldst,t(2,1),ldst,li(1,1),li(2,1))

              li(2,2) = li(1,1)
              li(1,2) = -li(2,1)
              ! weak stability test: |s21| <= o(eps f-norm((a)))
                                 ! and  |t21| <= o(eps f-norm((b)))
              weak = abs(s(2,1)) <= thresha .and. abs(t(2,1)) <= threshb
              if (.not. weak) go to 70
              if (wands) then
                 ! strong stability test:
                     ! f-norm((a-ql**h*s*qr)) <= o(eps*f-norm((a)))
                     ! and
                     ! f-norm((b-ql**h*t*qr)) <= o(eps*f-norm((b)))
                 call la_qlacpy('FULL',m,m,a(j1,j1),lda,work(m*m + 1),m)
                 call la_qgemm('N','N',m,m,m,one,li,ldst,s,ldst,zero,work,m)

                 call la_qgemm('N','T',m,m,m,-one,work,m,ir,ldst,one,work(m*m + 1), &
                            m)
                 dscale = zero
                 dsum = one
                 call la_qlassq(m*m,work(m*m + 1),1,dscale,dsum)
                 sa = dscale*sqrt(dsum)
                 call la_qlacpy('FULL',m,m,b(j1,j1),ldb,work(m*m + 1),m)
                 call la_qgemm('N','N',m,m,m,one,li,ldst,t,ldst,zero,work,m)

                 call la_qgemm('N','T',m,m,m,-one,work,m,ir,ldst,one,work(m*m + 1), &
                            m)
                 dscale = zero
                 dsum = one
                 call la_qlassq(m*m,work(m*m + 1),1,dscale,dsum)
                 sb = dscale*sqrt(dsum)
                 strong = sa <= thresha .and. sb <= threshb
                 if (.not. strong) go to 70
              end if
              ! update (a(j1:j1+m-1, m+j1:n), b(j1:j1+m-1, m+j1:n)) and
                     ! (a(1:j1-1, j1:j1+m), b(1:j1-1, j1:j1+m)).
              call la_qrot(j1 + 1,a(1,j1),1,a(1,j1 + 1),1,ir(1,1),ir(2,1))

              call la_qrot(j1 + 1,b(1,j1),1,b(1,j1 + 1),1,ir(1,1),ir(2,1))

              call la_qrot(n - j1 + 1,a(j1,j1),lda,a(j1 + 1,j1),lda,li(1,1),li(2,1 &
                        ))
              call la_qrot(n - j1 + 1,b(j1,j1),ldb,b(j1 + 1,j1),ldb,li(1,1),li(2,1 &
                        ))
              ! set  n1-by-n2 (2,1) - blocks to zero.
              a(j1 + 1,j1) = zero
              b(j1 + 1,j1) = zero
              ! accumulate transformations into q and z if requested.
              if (wantz) call la_qrot(n,z(1,j1),1,z(1,j1 + 1),1,ir(1,1),ir(2,1 &
                        ))
              if (wantq) call la_qrot(n,q(1,j1),1,q(1,j1 + 1),1,li(1,1),li(2,1 &
                        ))
              ! exit with info = 0 if swap was successfully performed.
              return
           else
              ! case 2: swap 1-by-1 and 2-by-2 blocks, or 2-by-2
                      ! and 2-by-2 blocks.
              ! solve the generalized sylvester equation
                       ! s11 * r - l * s22 = scale * s12
                       ! t11 * r - l * t22 = scale * t12
              ! for r and l. solutions in li and ir.
              call la_qlacpy('FULL',n1,n2,t(1,n1 + 1),ldst,li,ldst)
              call la_qlacpy('FULL',n1,n2,s(1,n1 + 1),ldst,ir(n2 + 1,n1 + 1),ldst)

              call la_qtgsy2('N',0,n1,n2,s,ldst,s(n1 + 1,n1 + 1),ldst,ir(n2 + 1,n1 + 1), &
               ldst,t,ldst,t(n1 + 1,n1 + 1),ldst,li,ldst,scale,dsum,dscale,iwork,idum, &
                         linfo)
              if (linfo /= 0) go to 70
              ! compute orthogonal matrix ql:
                          ! ql**t * li = [ tl ]
                                       ! [ 0  ]
              ! where
                          ! li =  [      -l              ]
                                ! [ scale * identity(n2) ]
              do i = 1,n2
                 call la_qscal(n1,-one,li(1,i),1)
                 li(n1 + i,i) = scale
              end do
              call la_qgeqr2(m,n2,li,ldst,taul,work,linfo)
              if (linfo /= 0) go to 70
              call la_qorg2r(m,m,n2,li,ldst,taul,work,linfo)
              if (linfo /= 0) go to 70
              ! compute orthogonal matrix rq:
                          ! ir * rq**t =   [ 0  tr],
               ! where ir = [ scale * identity(n1), r ]
              do i = 1,n1
                 ir(n2 + i,i) = scale
              end do
              call la_qgerq2(n1,m,ir(n2 + 1,1),ldst,taur,work,linfo)
              if (linfo /= 0) go to 70
              call la_qorgr2(m,m,n1,ir,ldst,taur,work,linfo)
              if (linfo /= 0) go to 70
              ! perform the swapping tentatively:
              call la_qgemm('T','N',m,m,m,one,li,ldst,s,ldst,zero,work,m)
              call la_qgemm('N','T',m,m,m,one,work,m,ir,ldst,zero,s,ldst)
              call la_qgemm('T','N',m,m,m,one,li,ldst,t,ldst,zero,work,m)
              call la_qgemm('N','T',m,m,m,one,work,m,ir,ldst,zero,t,ldst)
              call la_qlacpy('F',m,m,s,ldst,scpy,ldst)
              call la_qlacpy('F',m,m,t,ldst,tcpy,ldst)
              call la_qlacpy('F',m,m,ir,ldst,ircop,ldst)
              call la_qlacpy('F',m,m,li,ldst,licop,ldst)
              ! triangularize the b-part by an rq factorization.
              ! apply transformation (from left) to a-part, giving s.
              call la_qgerq2(m,m,t,ldst,taur,work,linfo)
              if (linfo /= 0) go to 70
              call la_qormr2('R','T',m,m,m,t,ldst,taur,s,ldst,work,linfo)
              if (linfo /= 0) go to 70
              call la_qormr2('L','N',m,m,m,t,ldst,taur,ir,ldst,work,linfo)
              if (linfo /= 0) go to 70
              ! compute f-norm(s21) in brqa21. (t21 is 0.)
              dscale = zero
              dsum = one
              do i = 1,n2
                 call la_qlassq(n1,s(n2 + 1,i),1,dscale,dsum)
              end do
              brqa21 = dscale*sqrt(dsum)
              ! triangularize the b-part by a qr factorization.
              ! apply transformation (from right) to a-part, giving s.
              call la_qgeqr2(m,m,tcpy,ldst,taul,work,linfo)
              if (linfo /= 0) go to 70
              call la_qorm2r('L','T',m,m,m,tcpy,ldst,taul,scpy,ldst,work,info)

              call la_qorm2r('R','N',m,m,m,tcpy,ldst,taul,licop,ldst,work,info)

              if (linfo /= 0) go to 70
              ! compute f-norm(s21) in bqra21. (t21 is 0.)
              dscale = zero
              dsum = one
              do i = 1,n2
                 call la_qlassq(n1,scpy(n2 + 1,i),1,dscale,dsum)
              end do
              bqra21 = dscale*sqrt(dsum)
              ! decide which method to use.
                ! weak stability test:
                   ! f-norm(s21) <= o(eps * f-norm((s)))
              if (bqra21 <= brqa21 .and. bqra21 <= thresha) then
                 call la_qlacpy('F',m,m,scpy,ldst,s,ldst)
                 call la_qlacpy('F',m,m,tcpy,ldst,t,ldst)
                 call la_qlacpy('F',m,m,ircop,ldst,ir,ldst)
                 call la_qlacpy('F',m,m,licop,ldst,li,ldst)
              else if (brqa21 >= thresha) then
                 go to 70
              end if
              ! set lower triangle of b-part to zero
              call la_qlaset('LOWER',m - 1,m - 1,zero,zero,t(2,1),ldst)
              if (wands) then
                 ! strong stability test:
                     ! f-norm((a-ql**h*s*qr)) <= o(eps*f-norm((a)))
                     ! and
                     ! f-norm((b-ql**h*t*qr)) <= o(eps*f-norm((b)))
                 call la_qlacpy('FULL',m,m,a(j1,j1),lda,work(m*m + 1),m)
                 call la_qgemm('N','N',m,m,m,one,li,ldst,s,ldst,zero,work,m)

                 call la_qgemm('N','N',m,m,m,-one,work,m,ir,ldst,one,work(m*m + 1), &
                            m)
                 dscale = zero
                 dsum = one
                 call la_qlassq(m*m,work(m*m + 1),1,dscale,dsum)
                 sa = dscale*sqrt(dsum)
                 call la_qlacpy('FULL',m,m,b(j1,j1),ldb,work(m*m + 1),m)
                 call la_qgemm('N','N',m,m,m,one,li,ldst,t,ldst,zero,work,m)

                 call la_qgemm('N','N',m,m,m,-one,work,m,ir,ldst,one,work(m*m + 1), &
                            m)
                 dscale = zero
                 dsum = one
                 call la_qlassq(m*m,work(m*m + 1),1,dscale,dsum)
                 sb = dscale*sqrt(dsum)
                 strong = sa <= thresha .and. sb <= threshb
                 if (.not. strong) go to 70
              end if
              ! if the swap is accepted ("weakly" and "strongly"), apply the
              ! transformations and set n1-by-n2 (2,1)-block to zero.
              call la_qlaset('FULL',n1,n2,zero,zero,s(n2 + 1,1),ldst)
              ! copy back m-by-m diagonal block starting at index j1 of (a, b)
              call la_qlacpy('F',m,m,s,ldst,a(j1,j1),lda)
              call la_qlacpy('F',m,m,t,ldst,b(j1,j1),ldb)
              call la_qlaset('FULL',ldst,ldst,zero,zero,t,ldst)
              ! standardize existing 2-by-2 blocks.
              call la_qlaset('FULL',m,m,zero,zero,work,m)
              work(1) = one
              t(1,1) = one
              idum = lwork - m*m - 2
              if (n2 > 1) then
                 call la_qlagv2(a(j1,j1),lda,b(j1,j1),ldb,ar,ai,be,work(1), &
                           work(2),t(1,1),t(2,1))
                 work(m + 1) = -work(2)
                 work(m + 2) = work(1)
                 t(n2,n2) = t(1,1)
                 t(1,2) = -t(2,1)
              end if
              work(m*m) = one
              t(m,m) = one
              if (n1 > 1) then
                 call la_qlagv2(a(j1 + n2,j1 + n2),lda,b(j1 + n2,j1 + n2),ldb,taur,taul, &
                 work(m*m + 1),work(n2*m + n2 + 1),work(n2*m + n2 + 2),t(n2 + 1,n2 + 1),t(m,m - 1))

                 work(m*m) = work(n2*m + n2 + 1)
                 work(m*m - 1) = -work(n2*m + n2 + 2)
                 t(m,m) = t(n2 + 1,n2 + 1)
                 t(m - 1,m) = -t(m,m - 1)
              end if
              call la_qgemm('T','N',n2,n1,n2,one,work,m,a(j1,j1 + n2),lda,zero, &
                        work(m*m + 1),n2)
              call la_qlacpy('FULL',n2,n1,work(m*m + 1),n2,a(j1,j1 + n2),lda)
              call la_qgemm('T','N',n2,n1,n2,one,work,m,b(j1,j1 + n2),ldb,zero, &
                        work(m*m + 1),n2)
              call la_qlacpy('FULL',n2,n1,work(m*m + 1),n2,b(j1,j1 + n2),ldb)
              call la_qgemm('N','N',m,m,m,one,li,ldst,work,m,zero,work(m*m + 1),m &
                        )
              call la_qlacpy('FULL',m,m,work(m*m + 1),m,li,ldst)
              call la_qgemm('N','N',n2,n1,n1,one,a(j1,j1 + n2),lda,t(n2 + 1,n2 + 1), &
                        ldst,zero,work,n2)
              call la_qlacpy('FULL',n2,n1,work,n2,a(j1,j1 + n2),lda)
              call la_qgemm('N','N',n2,n1,n1,one,b(j1,j1 + n2),ldb,t(n2 + 1,n2 + 1), &
                        ldst,zero,work,n2)
              call la_qlacpy('FULL',n2,n1,work,n2,b(j1,j1 + n2),ldb)
              call la_qgemm('T','N',m,m,m,one,ir,ldst,t,ldst,zero,work,m)
              call la_qlacpy('FULL',m,m,work,m,ir,ldst)
              ! accumulate transformations into q and z if requested.
              if (wantq) then
                 call la_qgemm('N','N',n,m,m,one,q(1,j1),ldq,li,ldst,zero,work, &
                           n)
                 call la_qlacpy('FULL',n,m,work,n,q(1,j1),ldq)
              end if
              if (wantz) then
                 call la_qgemm('N','N',n,m,m,one,z(1,j1),ldz,ir,ldst,zero,work, &
                           n)
                 call la_qlacpy('FULL',n,m,work,n,z(1,j1),ldz)
              end if
              ! update (a(j1:j1+m-1, m+j1:n), b(j1:j1+m-1, m+j1:n)) and
                      ! (a(1:j1-1, j1:j1+m), b(1:j1-1, j1:j1+m)).
              i = j1 + m
              if (i <= n) then
                 call la_qgemm('T','N',m,n - i + 1,m,one,li,ldst,a(j1,i),lda,zero, &
                           work,m)
                 call la_qlacpy('FULL',m,n - i + 1,work,m,a(j1,i),lda)
                 call la_qgemm('T','N',m,n - i + 1,m,one,li,ldst,b(j1,i),ldb,zero, &
                           work,m)
                 call la_qlacpy('FULL',m,n - i + 1,work,m,b(j1,i),ldb)
              end if
              i = j1 - 1
              if (i > 0) then
                 call la_qgemm('N','N',i,m,m,one,a(1,j1),lda,ir,ldst,zero,work, &
                           i)
                 call la_qlacpy('FULL',i,m,work,i,a(1,j1),lda)
                 call la_qgemm('N','N',i,m,m,one,b(1,j1),ldb,ir,ldst,zero,work, &
                           i)
                 call la_qlacpy('FULL',i,m,work,i,b(1,j1),ldb)
              end if
              ! exit with info = 0 if swap was successfully performed.
              return
           end if
           ! exit with info = 1 if swap was rejected.
           70 continue
           info = 1
           return
     end subroutine la_qtgex2

     !> DTGEXC: reorders the generalized real Schur decomposition of a real
     !> matrix pair (A,B) using an orthogonal equivalence transformation
     !> (A, B) = Q * (A, B) * Z**T,
     !> so that the diagonal block of (A, B) with row index IFST is moved
     !> to row ILST.
     !> (A, B) must be in generalized real Schur canonical form (as returned
     !> by DGGES), i.e. A is block upper triangular with 1-by-1 and 2-by-2
     !> diagonal blocks. B is upper triangular.
     !> Optionally, the matrices Q and Z of generalized Schur vectors are
     !> updated.
     !> Q(in) * A(in) * Z(in)**T = Q(out) * A(out) * Z(out)**T
     !> Q(in) * B(in) * Z(in)**T = Q(out) * B(out) * Z(out)**T

     pure subroutine la_qtgexc(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,ifst,ilst, &
               work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: wantq,wantz
           integer(ilp),intent(inout) :: ifst,ilst
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,ldq,ldz,lwork,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery
           integer(ilp) :: here,lwmin,nbf,nbl,nbnext
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! decode and test input arguments.
           info = 0
           lquery = (lwork == -1)
           if (n < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -7
           else if (ldq < 1 .or. wantq .and. (ldq < max(1,n))) then
              info = -9
           else if (ldz < 1 .or. wantz .and. (ldz < max(1,n))) then
              info = -11
           else if (ifst < 1 .or. ifst > n) then
              info = -12
           else if (ilst < 1 .or. ilst > n) then
              info = -13
           end if
           if (info == 0) then
              if (n <= 1) then
                 lwmin = 1
              else
                 lwmin = 4*n + 16
              end if
              work(1) = lwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -15
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DTGEXC',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n <= 1) return
           ! determine the first row of the specified block and find out
           ! if it is 1-by-1 or 2-by-2.
           if (ifst > 1) then
              if (a(ifst,ifst - 1) /= zero) ifst = ifst - 1
           end if
           nbf = 1
           if (ifst < n) then
              if (a(ifst + 1,ifst) /= zero) nbf = 2
           end if
           ! determine the first row of the final block
           ! and find out if it is 1-by-1 or 2-by-2.
           if (ilst > 1) then
              if (a(ilst,ilst - 1) /= zero) ilst = ilst - 1
           end if
           nbl = 1
           if (ilst < n) then
              if (a(ilst + 1,ilst) /= zero) nbl = 2
           end if
           if (ifst == ilst) return
           if (ifst < ilst) then
              ! update ilst.
              if (nbf == 2 .and. nbl == 1) ilst = ilst - 1
              if (nbf == 1 .and. nbl == 2) ilst = ilst + 1
              here = ifst
              10 continue
              ! swap with next one below.
              if (nbf == 1 .or. nbf == 2) then
                 ! current block either 1-by-1 or 2-by-2.
                 nbnext = 1
                 if (here + nbf + 1 <= n) then
                    if (a(here + nbf + 1,here + nbf) /= zero) nbnext = 2
                 end if
                 call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here,nbf, &
                           nbnext,work,lwork,info)
                 if (info /= 0) then
                    ilst = here
                    return
                 end if
                 here = here + nbnext
                 ! test if 2-by-2 block breaks into two 1-by-1 blocks.
                 if (nbf == 2) then
                    if (a(here + 1,here) == zero) nbf = 3
                 end if
              else
                 ! current block consists of two 1-by-1 blocks, each of which
                 ! must be swapped individually.
                 nbnext = 1
                 if (here + 3 <= n) then
                    if (a(here + 3,here + 2) /= zero) nbnext = 2
                 end if
                 call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here + 1,1, &
                           nbnext,work,lwork,info)
                 if (info /= 0) then
                    ilst = here
                    return
                 end if
                 if (nbnext == 1) then
                    ! swap two 1-by-1 blocks.
                    call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here,1, &
                              1,work,lwork,info)
                    if (info /= 0) then
                       ilst = here
                       return
                    end if
                    here = here + 1
                 else
                    ! recompute nbnext in case of 2-by-2 split.
                    if (a(here + 2,here + 1) == zero) nbnext = 1
                    if (nbnext == 2) then
                       ! 2-by-2 block did not split.
                       call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here, &
                                 1,nbnext,work,lwork,info)
                       if (info /= 0) then
                          ilst = here
                          return
                       end if
                       here = here + 2
                    else
                       ! 2-by-2 block did split.
                       call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here, &
                                 1,1,work,lwork,info)
                       if (info /= 0) then
                          ilst = here
                          return
                       end if
                       here = here + 1
                       call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here, &
                                 1,1,work,lwork,info)
                       if (info /= 0) then
                          ilst = here
                          return
                       end if
                       here = here + 1
                    end if
                 end if
              end if
              if (here < ilst) go to 10
           else
              here = ifst
              20 continue
              ! swap with next one below.
              if (nbf == 1 .or. nbf == 2) then
                 ! current block either 1-by-1 or 2-by-2.
                 nbnext = 1
                 if (here >= 3) then
                    if (a(here - 1,here - 2) /= zero) nbnext = 2
                 end if
                 call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here - nbnext, &
                           nbnext,nbf,work,lwork,info)
                 if (info /= 0) then
                    ilst = here
                    return
                 end if
                 here = here - nbnext
                 ! test if 2-by-2 block breaks into two 1-by-1 blocks.
                 if (nbf == 2) then
                    if (a(here + 1,here) == zero) nbf = 3
                 end if
              else
                 ! current block consists of two 1-by-1 blocks, each of which
                 ! must be swapped individually.
                 nbnext = 1
                 if (here >= 3) then
                    if (a(here - 1,here - 2) /= zero) nbnext = 2
                 end if
                 call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here - nbnext, &
                           nbnext,1,work,lwork,info)
                 if (info /= 0) then
                    ilst = here
                    return
                 end if
                 if (nbnext == 1) then
                    ! swap two 1-by-1 blocks.
                    call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here, &
                              nbnext,1,work,lwork,info)
                    if (info /= 0) then
                       ilst = here
                       return
                    end if
                    here = here - 1
                 else
                   ! recompute nbnext in case of 2-by-2 split.
                    if (a(here,here - 1) == zero) nbnext = 1
                    if (nbnext == 2) then
                       ! 2-by-2 block did not split.
                       call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here - 1, &
                                  2,1,work,lwork,info)
                       if (info /= 0) then
                          ilst = here
                          return
                       end if
                       here = here - 2
                    else
                       ! 2-by-2 block did split.
                       call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here, &
                                 1,1,work,lwork,info)
                       if (info /= 0) then
                          ilst = here
                          return
                       end if
                       here = here - 1
                       call la_qtgex2(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz,here, &
                                 1,1,work,lwork,info)
                       if (info /= 0) then
                          ilst = here
                          return
                       end if
                       here = here - 1
                    end if
                 end if
              end if
              if (here > ilst) go to 20
           end if
           ilst = here
           work(1) = lwmin
           return
     end subroutine la_qtgexc

     !> DTGSEN: reorders the generalized real Schur decomposition of a real
     !> matrix pair (A, B) (in terms of an orthonormal equivalence trans-
     !> formation Q**T * (A, B) * Z), so that a selected cluster of eigenvalues
     !> appears in the leading diagonal blocks of the upper quasi-triangular
     !> matrix A and the upper triangular B. The leading columns of Q and
     !> Z form orthonormal bases of the corresponding left and right eigen-
     !> spaces (deflating subspaces). (A, B) must be in generalized real
     !> Schur canonical form (as returned by DGGES), i.e. A is block upper
     !> triangular with 1-by-1 and 2-by-2 diagonal blocks. B is upper
     !> triangular.
     !> DTGSEN also computes the generalized eigenvalues
     !> w(j) = (ALPHAR(j) + i*ALPHAI(j))/BETA(j)
     !> of the reordered matrix pair (A, B).
     !> Optionally, DTGSEN computes the estimates of reciprocal condition
     !> numbers for eigenvalues and eigenspaces. These are Difu[(A11,B11),
     !> (A22,B22)] and Difl[(A11,B11), (A22,B22)], i.e. the separation(s)
     !> between the matrix pairs (A11, B11) and (A22,B22) that correspond to
     !> the selected cluster and the eigenvalues outside the cluster, resp.,
     !> and norms of "projections" onto left and right eigenspaces w.r.t.
     !> the selected cluster in the (1,1)-block.

     pure subroutine la_qtgsen(ijob,wantq,wantz,select,n,a,lda,b,ldb,alphar,alphai, &
               beta,q,ldq,z,ldz,m,pl,pr,dif,work,lwork,iwork,liwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           logical(lk),intent(in) :: wantq,wantz
           integer(ilp),intent(in) :: ijob,lda,ldb,ldq,ldz,liwork,lwork,n
           integer(ilp),intent(out) :: info,m
           real(qp),intent(out) :: pl,pr
           ! Array Arguments
           logical(lk),intent(in) :: select(*)
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),z(ldz,*)
           real(qp),intent(out) :: alphai(*),alphar(*),beta(*),dif(*),work(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: idifjb = 3

           ! Local Scalars
           logical(lk) :: lquery,pair,swap,wantd,wantd1,wantd2,wantp
           integer(ilp) :: i,ierr,ijb,k,kase,kk,ks,liwmin,lwmin,mn2,n1,n2
           real(qp) :: dscale,dsum,eps,rdscal,smlnum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: max,sign,sqrt
           ! Executable Statements
           ! decode and test the input parameters
           info = 0
           lquery = (lwork == -1 .or. liwork == -1)
           if (ijob < 0 .or. ijob > 5) then
              info = -1
           else if (n < 0) then
              info = -5
           else if (lda < max(1,n)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -9
           else if (ldq < 1 .or. (wantq .and. ldq < n)) then
              info = -14
           else if (ldz < 1 .or. (wantz .and. ldz < n)) then
              info = -16
           end if
           if (info /= 0) then
              call la_xerbla('DTGSEN',-info)
              return
           end if
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')/eps
           ierr = 0
           wantp = ijob == 1 .or. ijob >= 4
           wantd1 = ijob == 2 .or. ijob == 4
           wantd2 = ijob == 3 .or. ijob == 5
           wantd = wantd1 .or. wantd2
           ! set m to the dimension of the specified pair of deflating
           ! subspaces.
           m = 0
           pair = .false.
           if (.not. lquery .or. ijob /= 0) then
           do k = 1,n
              if (pair) then
                 pair = .false.
              else
                 if (k < n) then
                    if (a(k + 1,k) == zero) then
                       if (select(k)) m = m + 1
                    else
                       pair = .true.
                       if (select(k) .or. select(k + 1)) m = m + 2
                    end if
                 else
                    if (select(n)) m = m + 1
                 end if
              end if
           end do
           end if
           if (ijob == 1 .or. ijob == 2 .or. ijob == 4) then
              lwmin = max(1,4*n + 16,2*m*(n - m))
              liwmin = max(1,n + 6)
           else if (ijob == 3 .or. ijob == 5) then
              lwmin = max(1,4*n + 16,4*m*(n - m))
              liwmin = max(1,2*m*(n - m),n + 6)
           else
              lwmin = max(1,4*n + 16)
              liwmin = 1
           end if
           work(1) = lwmin
           iwork(1) = liwmin
           if (lwork < lwmin .and. .not. lquery) then
              info = -22
           else if (liwork < liwmin .and. .not. lquery) then
              info = -24
           end if
           if (info /= 0) then
              call la_xerbla('DTGSEN',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible.
           if (m == n .or. m == 0) then
              if (wantp) then
                 pl = one
                 pr = one
              end if
              if (wantd) then
                 dscale = zero
                 dsum = one
                 do i = 1,n
                    call la_qlassq(n,a(1,i),1,dscale,dsum)
                    call la_qlassq(n,b(1,i),1,dscale,dsum)
                 end do
                 dif(1) = dscale*sqrt(dsum)
                 dif(2) = dif(1)
              end if
              go to 60
           end if
           ! collect the selected blocks at the top-left corner of (a, b).
           ks = 0
           pair = .false.
           loop_30: do k = 1,n
              if (pair) then
                 pair = .false.
              else
                 swap = select(k)
                 if (k < n) then
                    if (a(k + 1,k) /= zero) then
                       pair = .true.
                       swap = swap .or. select(k + 1)
                    end if
                 end if
                 if (swap) then
                    ks = ks + 1
                    ! swap the k-th block to position ks.
                    ! perform the reordering of diagonal blocks in (a, b)
                    ! by orthogonal transformation matrices and update
                    ! q and z accordingly (if requested):
                    kk = k
                    if (k /= ks) call la_qtgexc(wantq,wantz,n,a,lda,b,ldb,q,ldq,z,ldz, &
                               kk,ks,work,lwork,ierr)
                    if (ierr > 0) then
                       ! swap is rejected: exit.
                       info = 1
                       if (wantp) then
                          pl = zero
                          pr = zero
                       end if
                       if (wantd) then
                          dif(1) = zero
                          dif(2) = zero
                       end if
                       go to 60
                    end if
                    if (pair) ks = ks + 1
                 end if
              end if
           end do loop_30
           if (wantp) then
              ! solve generalized sylvester equation for r and l
              ! and compute pl and pr.
              n1 = m
              n2 = n - m
              i = n1 + 1
              ijb = 0
              call la_qlacpy('FULL',n1,n2,a(1,i),lda,work,n1)
              call la_qlacpy('FULL',n1,n2,b(1,i),ldb,work(n1*n2 + 1),n1)
              call la_qtgsyl('N',ijb,n1,n2,a,lda,a(i,i),lda,work,n1,b,ldb,b(i, &
               i),ldb,work(n1*n2 + 1),n1,dscale,dif(1),work(n1*n2*2 + 1),lwork - 2*n1*n2, &
                         iwork,ierr)
              ! estimate the reciprocal of norms of "projections" onto left
              ! and right eigenspaces.
              rdscal = zero
              dsum = one
              call la_qlassq(n1*n2,work,1,rdscal,dsum)
              pl = rdscal*sqrt(dsum)
              if (pl == zero) then
                 pl = one
              else
                 pl = dscale/(sqrt(dscale*dscale/pl + pl)*sqrt(pl))
              end if
              rdscal = zero
              dsum = one
              call la_qlassq(n1*n2,work(n1*n2 + 1),1,rdscal,dsum)
              pr = rdscal*sqrt(dsum)
              if (pr == zero) then
                 pr = one
              else
                 pr = dscale/(sqrt(dscale*dscale/pr + pr)*sqrt(pr))
              end if
           end if
           if (wantd) then
              ! compute estimates of difu and difl.
              if (wantd1) then
                 n1 = m
                 n2 = n - m
                 i = n1 + 1
                 ijb = idifjb
                 ! frobenius norm-based difu-estimate.
                 call la_qtgsyl('N',ijb,n1,n2,a,lda,a(i,i),lda,work,n1,b,ldb,b( &
                  i,i),ldb,work(n1*n2 + 1),n1,dscale,dif(1),work(2*n1*n2 + 1),lwork - &
                            2*n1*n2,iwork,ierr)
                 ! frobenius norm-based difl-estimate.
                 call la_qtgsyl('N',ijb,n2,n1,a(i,i),lda,a,lda,work,n2,b(i,i), &
                  ldb,b,ldb,work(n1*n2 + 1),n2,dscale,dif(2),work(2*n1*n2 + 1),lwork - &
                            2*n1*n2,iwork,ierr)
              else
                 ! compute 1-norm-based estimates of difu and difl using
                 ! reversed communication with la_qlacn2. in each step a
                 ! generalized sylvester equation or a transposed variant
                 ! is solved.
                 kase = 0
                 n1 = m
                 n2 = n - m
                 i = n1 + 1
                 ijb = 0
                 mn2 = 2*n1*n2
                 ! 1-norm-based estimate of difu.
                 40 continue
                 call la_qlacn2(mn2,work(mn2 + 1),work,iwork,dif(1),kase,isave)

                 if (kase /= 0) then
                    if (kase == 1) then
                       ! solve generalized sylvester equation.
                       call la_qtgsyl('N',ijb,n1,n2,a,lda,a(i,i),lda,work,n1,b, &
                       ldb,b(i,i),ldb,work(n1*n2 + 1),n1,dscale,dif(1),work(2*n1*n2 + 1) &
                                 ,lwork - 2*n1*n2,iwork,ierr)
                    else
                       ! solve the transposed variant.
                       call la_qtgsyl('T',ijb,n1,n2,a,lda,a(i,i),lda,work,n1,b, &
                       ldb,b(i,i),ldb,work(n1*n2 + 1),n1,dscale,dif(1),work(2*n1*n2 + 1) &
                                 ,lwork - 2*n1*n2,iwork,ierr)
                    end if
                    go to 40
                 end if
                 dif(1) = dscale/dif(1)
                 ! 1-norm-based estimate of difl.
                 50 continue
                 call la_qlacn2(mn2,work(mn2 + 1),work,iwork,dif(2),kase,isave)

                 if (kase /= 0) then
                    if (kase == 1) then
                       ! solve generalized sylvester equation.
                       call la_qtgsyl('N',ijb,n2,n1,a(i,i),lda,a,lda,work,n2,b( &
                       i,i),ldb,b,ldb,work(n1*n2 + 1),n2,dscale,dif(2),work(2*n1*n2 + 1) &
                                 ,lwork - 2*n1*n2,iwork,ierr)
                    else
                       ! solve the transposed variant.
                       call la_qtgsyl('T',ijb,n2,n1,a(i,i),lda,a,lda,work,n2,b( &
                       i,i),ldb,b,ldb,work(n1*n2 + 1),n2,dscale,dif(2),work(2*n1*n2 + 1) &
                                 ,lwork - 2*n1*n2,iwork,ierr)
                    end if
                    go to 50
                 end if
                 dif(2) = dscale/dif(2)
              end if
           end if
           60 continue
           ! compute generalized eigenvalues of reordered pair (a, b) and
           ! normalize the generalized schur form.
           pair = .false.
           loop_80: do k = 1,n
              if (pair) then
                 pair = .false.
              else
                 if (k < n) then
                    if (a(k + 1,k) /= zero) then
                       pair = .true.
                    end if
                 end if
                 if (pair) then
                   ! compute the eigenvalue(s) at position k.
                    work(1) = a(k,k)
                    work(2) = a(k + 1,k)
                    work(3) = a(k,k + 1)
                    work(4) = a(k + 1,k + 1)
                    work(5) = b(k,k)
                    work(6) = b(k + 1,k)
                    work(7) = b(k,k + 1)
                    work(8) = b(k + 1,k + 1)
                    call la_qlag2(work,2,work(5),2,smlnum*eps,beta(k),beta(k + 1), &
                              alphar(k),alphar(k + 1),alphai(k))
                    alphai(k + 1) = -alphai(k)
                 else
                    if (sign(one,b(k,k)) < zero) then
                       ! if b(k,k) is negative, make it positive
                       do i = 1,n
                          a(k,i) = -a(k,i)
                          b(k,i) = -b(k,i)
                          if (wantq) q(i,k) = -q(i,k)
                       end do
                    end if
                    alphar(k) = a(k,k)
                    alphai(k) = zero
                    beta(k) = b(k,k)
                 end if
              end if
           end do loop_80
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qtgsen

     !> DTGSJA: computes the generalized singular value decomposition (GSVD)
     !> of two real upper triangular (or trapezoidal) matrices A and B.
     !> On entry, it is assumed that matrices A and B have the following
     !> forms, which may be obtained by the preprocessing subroutine DGGSVP
     !> from a general M-by-N matrix A and P-by-N matrix B:
     !> N-K-L  K    L
     !> A =    K ( 0    A12  A13 ) if M-K-L >= 0;
     !> L ( 0     0   A23 )
     !> M-K-L ( 0     0    0  )
     !> N-K-L  K    L
     !> A =  K ( 0    A12  A13 ) if M-K-L < 0;
     !> M-K ( 0     0   A23 )
     !> N-K-L  K    L
     !> B =  L ( 0     0   B13 )
     !> P-L ( 0     0    0  )
     !> where the K-by-K matrix A12 and L-by-L matrix B13 are nonsingular
     !> upper triangular; A23 is L-by-L upper triangular if M-K-L >= 0,
     !> otherwise A23 is (M-K)-by-L upper trapezoidal.
     !> On exit,
     !> U**T *A*Q = D1*( 0 R ),    V**T *B*Q = D2*( 0 R ),
     !> where U, V and Q are orthogonal matrices.
     !> R is a nonsingular upper triangular matrix, and D1 and D2 are
     !> ``diagonal'' matrices, which are of the following structures:
     !> If M-K-L >= 0,
     !> K  L
     !> D1 =     K ( I  0 )
     !> L ( 0  C )
     !> M-K-L ( 0  0 )
     !> K  L
     !> D2 = L   ( 0  S )
     !> P-L ( 0  0 )
     !> N-K-L  K    L
     !> ( 0 R ) = K (  0   R11  R12 ) K
     !> L (  0    0   R22 ) L
     !> where
     !> C = diag( ALPHA(K+1), ... , ALPHA(K+L) ),
     !> S = diag( BETA(K+1),  ... , BETA(K+L) ),
     !> C**2 + S**2 = I.
     !> R is stored in A(1:K+L,N-K-L+1:N) on exit.
     !> If M-K-L < 0,
     !> K M-K K+L-M
     !> D1 =   K ( I  0    0   )
     !> M-K ( 0  C    0   )
     !> K M-K K+L-M
     !> D2 =   M-K ( 0  S    0   )
     !> K+L-M ( 0  0    I   )
     !> P-L ( 0  0    0   )
     !> N-K-L  K   M-K  K+L-M
     !> ( 0 R ) =    K ( 0    R11  R12  R13  )
     !> M-K ( 0     0   R22  R23  )
     !> K+L-M ( 0     0    0   R33  )
     !> where
     !> C = diag( ALPHA(K+1), ... , ALPHA(M) ),
     !> S = diag( BETA(K+1),  ... , BETA(M) ),
     !> C**2 + S**2 = I.
     !> R = ( R11 R12 R13 ) is stored in A(1:M, N-K-L+1:N) and R33 is stored
     !> (  0  R22 R23 )
     !> in B(M-K+1:L,N+M-K-L+1:N) on exit.
     !> The computation of the orthogonal transformation matrices U, V or Q
     !> is optional.  These matrices may either be formed explicitly, or they
     !> may be postmultiplied into input matrices U1, V1, or Q1.

     pure subroutine la_qtgsja(jobu,jobv,jobq,m,p,n,k,l,a,lda,b,ldb,tola,tolb, &
               alpha,beta,u,ldu,v,ldv,q,ldq,work,ncycle,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: jobq,jobu,jobv
           integer(ilp),intent(out) :: info,ncycle
           integer(ilp),intent(in) :: k,l,lda,ldb,ldq,ldu,ldv,m,n,p
           real(qp),intent(in) :: tola,tolb
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*),b(ldb,*),q(ldq,*),u(ldu,*),v(ldv,*)
           real(qp),intent(out) :: alpha(*),beta(*),work(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: maxit = 40
           real(qp),parameter :: hugenum = huge(zero)

           ! Local Scalars
           logical(lk) :: initq,initu,initv,upper,wantq,wantu,wantv
           integer(ilp) :: i,j,kcycle
           real(qp) :: a1,a2,a3,b1,b2,b3,csq,csu,csv,error,gamma,rwk,snq,snu,snv, &
                     ssmin
           ! Intrinsic Functions
           intrinsic :: abs,max,min,huge
           ! Executable Statements
           ! decode and test the input parameters
           initu = la_lsame(jobu,'I')
           wantu = initu .or. la_lsame(jobu,'U')
           initv = la_lsame(jobv,'I')
           wantv = initv .or. la_lsame(jobv,'V')
           initq = la_lsame(jobq,'I')
           wantq = initq .or. la_lsame(jobq,'Q')
           info = 0
           if (.not. (initu .or. wantu .or. la_lsame(jobu,'N'))) then
              info = -1
           else if (.not. (initv .or. wantv .or. la_lsame(jobv,'N'))) then
              info = -2
           else if (.not. (initq .or. wantq .or. la_lsame(jobq,'N'))) then
              info = -3
           else if (m < 0) then
              info = -4
           else if (p < 0) then
              info = -5
           else if (n < 0) then
              info = -6
           else if (lda < max(1,m)) then
              info = -10
           else if (ldb < max(1,p)) then
              info = -12
           else if (ldu < 1 .or. (wantu .and. ldu < m)) then
              info = -18
           else if (ldv < 1 .or. (wantv .and. ldv < p)) then
              info = -20
           else if (ldq < 1 .or. (wantq .and. ldq < n)) then
              info = -22
           end if
           if (info /= 0) then
              call la_xerbla('DTGSJA',-info)
              return
           end if
           ! initialize u, v and q, if necessary
           if (initu) call la_qlaset('FULL',m,m,zero,one,u,ldu)
           if (initv) call la_qlaset('FULL',p,p,zero,one,v,ldv)
           if (initq) call la_qlaset('FULL',n,n,zero,one,q,ldq)
           ! loop until convergence
           upper = .false.
           loop_40: do kcycle = 1,maxit
              upper = .not. upper
              loop_20: do i = 1,l - 1
                 loop_10: do j = i + 1,l
                    a1 = zero
                    a2 = zero
                    a3 = zero
                    if (k + i <= m) a1 = a(k + i,n - l + i)
                    if (k + j <= m) a3 = a(k + j,n - l + j)
                    b1 = b(i,n - l + i)
                    b3 = b(j,n - l + j)
                    if (upper) then
                       if (k + i <= m) a2 = a(k + i,n - l + j)
                       b2 = b(i,n - l + j)
                    else
                       if (k + j <= m) a2 = a(k + j,n - l + i)
                       b2 = b(j,n - l + i)
                    end if
                    call la_qlags2(upper,a1,a2,a3,b1,b2,b3,csu,snu,csv,snv,csq, &
                              snq)
                    ! update (k+i)-th and (k+j)-th rows of matrix a: u**t *a
                    if (k + j <= m) call la_qrot(l,a(k + j,n - l + 1),lda,a(k + i,n - l + 1),lda, &
                              csu,snu)
                    ! update i-th and j-th rows of matrix b: v**t *b
                    call la_qrot(l,b(j,n - l + 1),ldb,b(i,n - l + 1),ldb,csv,snv)
                    ! update (n-l+i)-th and (n-l+j)-th columns of matrices
                    ! a and b: a*q and b*q
                    call la_qrot(min(k + l,m),a(1,n - l + j),1,a(1,n - l + i),1,csq,snq)

                    call la_qrot(l,b(1,n - l + j),1,b(1,n - l + i),1,csq,snq)
                    if (upper) then
                       if (k + i <= m) a(k + i,n - l + j) = zero
                       b(i,n - l + j) = zero
                    else
                       if (k + j <= m) a(k + j,n - l + i) = zero
                       b(j,n - l + i) = zero
                    end if
                    ! update orthogonal matrices u, v, q, if desired.
                    if (wantu .and. k + j <= m) call la_qrot(m,u(1,k + j),1,u(1,k + i),1, &
                              csu,snu)
                    if (wantv) call la_qrot(p,v(1,j),1,v(1,i),1,csv,snv)
                    if (wantq) call la_qrot(n,q(1,n - l + j),1,q(1,n - l + i),1,csq,snq)

                 end do loop_10
              end do loop_20
              if (.not. upper) then
                 ! the matrices a13 and b13 were lower triangular at the start
                 ! of the cycle, and are now upper triangular.
                 ! convergence test: test the parallelism of the corresponding
                 ! rows of a and b.
                 error = zero
                 do i = 1,min(l,m - k)
                    call la_qcopy(l - i + 1,a(k + i,n - l + i),lda,work,1)
                    call la_qcopy(l - i + 1,b(i,n - l + i),ldb,work(l + 1),1)
                    call la_qlapll(l - i + 1,work,1,work(l + 1),1,ssmin)
                    error = max(error,ssmin)
                 end do
                 if (abs(error) <= min(tola,tolb)) go to 50
              end if
              ! end of cycle loop
           end do loop_40
           ! the algorithm has not converged after maxit cycles.
           info = 1
           go to 100
           50 continue
           ! if error <= min(tola,tolb), then the algorithm has converged.
           ! compute the generalized singular value pairs (alpha, beta), and
           ! set the triangular matrix r to array a.
           do i = 1,k
              alpha(i) = one
              beta(i) = zero
           end do
           do i = 1,min(l,m - k)
              a1 = a(k + i,n - l + i)
              b1 = b(i,n - l + i)
              gamma = b1/a1
              if ((gamma <= hugenum) .and. (gamma >= -hugenum)) then
                 ! change sign if necessary
                 if (gamma < zero) then
                    call la_qscal(l - i + 1,-one,b(i,n - l + i),ldb)
                    if (wantv) call la_qscal(p,-one,v(1,i),1)
                 end if
                 call la_qlartg(abs(gamma),one,beta(k + i),alpha(k + i),rwk)
                 if (alpha(k + i) >= beta(k + i)) then
                    call la_qscal(l - i + 1,one/alpha(k + i),a(k + i,n - l + i),lda)
                 else
                    call la_qscal(l - i + 1,one/beta(k + i),b(i,n - l + i),ldb)
                    call la_qcopy(l - i + 1,b(i,n - l + i),ldb,a(k + i,n - l + i),lda)
                 end if
              else
                 alpha(k + i) = zero
                 beta(k + i) = one
                 call la_qcopy(l - i + 1,b(i,n - l + i),ldb,a(k + i,n - l + i),lda)
              end if
           end do
           ! post-assignment
           do i = m + 1,k + l
              alpha(i) = zero
              beta(i) = one
           end do
           if (k + l < n) then
              do i = k + l + 1,n
                 alpha(i) = zero
                 beta(i) = zero
              end do
           end if
           100 continue
           ncycle = kcycle
           return
     end subroutine la_qtgsja

     !> DTGSNA: estimates reciprocal condition numbers for specified
     !> eigenvalues and/or eigenvectors of a matrix pair (A, B) in
     !> generalized real Schur canonical form (or of any matrix pair
     !> (Q*A*Z**T, Q*B*Z**T) with orthogonal matrices Q and Z, where
     !> Z**T denotes the transpose of Z.
     !> (A, B) must be in generalized real Schur form (as returned by DGGES),
     !> i.e. A is block upper triangular with 1-by-1 and 2-by-2 diagonal
     !> blocks. B is upper triangular.

     pure subroutine la_qtgsna(job,howmny,select,n,a,lda,b,ldb,vl,ldvl,vr,ldvr,s, &
               dif,mm,m,work,lwork,iwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: howmny,job
           integer(ilp),intent(out) :: info,m
           integer(ilp),intent(in) :: lda,ldb,ldvl,ldvr,lwork,mm,n
           ! Array Arguments
           logical(lk),intent(in) :: select(*)
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(in) :: a(lda,*),b(ldb,*),vl(ldvl,*),vr(ldvr,*)
           real(qp),intent(out) :: dif(*),s(*),work(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: difdri = 3

           ! Local Scalars
           logical(lk) :: lquery,pair,somcon,wantbh,wantdf,wants
           integer(ilp) :: i,ierr,ifst,ilst,iz,k,ks,lwmin,n1,n2
           real(qp) :: alphai,alphar,alprqt,beta,c1,c2,cond,eps,lnrm,rnrm,root1,root2, &
                     scale,smlnum,tmpii,tmpir,tmpri,tmprr,uhav,uhavi,uhbv,uhbvi
           ! Local Arrays
           real(qp) :: dummy(1),dummy1(1)
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt
           ! Executable Statements
           ! decode and test the input parameters
           wantbh = la_lsame(job,'B')
           wants = la_lsame(job,'E') .or. wantbh
           wantdf = la_lsame(job,'V') .or. wantbh
           somcon = la_lsame(howmny,'S')
           info = 0
           lquery = (lwork == -1)
           if (.not. wants .and. .not. wantdf) then
              info = -1
           else if (.not. la_lsame(howmny,'A') .and. .not. somcon) then
              info = -2
           else if (n < 0) then
              info = -4
           else if (lda < max(1,n)) then
              info = -6
           else if (ldb < max(1,n)) then
              info = -8
           else if (wants .and. ldvl < n) then
              info = -10
           else if (wants .and. ldvr < n) then
              info = -12
           else
              ! set m to the number of eigenpairs for which condition numbers
              ! are required, and test mm.
              if (somcon) then
                 m = 0
                 pair = .false.
                 do k = 1,n
                    if (pair) then
                       pair = .false.
                    else
                       if (k < n) then
                          if (a(k + 1,k) == zero) then
                             if (select(k)) m = m + 1
                          else
                             pair = .true.
                             if (select(k) .or. select(k + 1)) m = m + 2
                          end if
                       else
                          if (select(n)) m = m + 1
                       end if
                    end if
                 end do
              else
                 m = n
              end if
              if (n == 0) then
                 lwmin = 1
              else if (la_lsame(job,'V') .or. la_lsame(job,'B')) then
                 lwmin = 2*n*(n + 2) + 16
              else
                 lwmin = n
              end if
              work(1) = lwmin
              if (mm < m) then
                 info = -15
              else if (lwork < lwmin .and. .not. lquery) then
                 info = -18
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DTGSNA',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')/eps
           ks = 0
           pair = .false.
           loop_20: do k = 1,n
              ! determine whether a(k,k) begins a 1-by-1 or 2-by-2 block.
              if (pair) then
                 pair = .false.
                 cycle loop_20
              else
                 if (k < n) pair = a(k + 1,k) /= zero
              end if
              ! determine whether condition numbers are required for the k-th
              ! eigenpair.
              if (somcon) then
                 if (pair) then
                    if (.not. select(k) .and. .not. select(k + 1)) cycle loop_20
                 else
                    if (.not. select(k)) cycle loop_20
                 end if
              end if
              ks = ks + 1
              if (wants) then
                 ! compute the reciprocal condition number of the k-th
                 ! eigenvalue.
                 if (pair) then
                    ! complex eigenvalue pair.
                    rnrm = la_qlapy2(la_qnrm2(n,vr(1,ks),1),la_qnrm2(n,vr( &
                              1,ks + 1),1))
                    lnrm = la_qlapy2(la_qnrm2(n,vl(1,ks),1),la_qnrm2(n,vl( &
                              1,ks + 1),1))
                    call la_qgemv('N',n,n,one,a,lda,vr(1,ks),1,zero,work,1)

                    tmprr = la_qdot(n,work,1,vl(1,ks),1)
                    tmpri = la_qdot(n,work,1,vl(1,ks + 1),1)
                    call la_qgemv('N',n,n,one,a,lda,vr(1,ks + 1),1,zero,work,1)

                    tmpii = la_qdot(n,work,1,vl(1,ks + 1),1)
                    tmpir = la_qdot(n,work,1,vl(1,ks),1)
                    uhav = tmprr + tmpii
                    uhavi = tmpir - tmpri
                    call la_qgemv('N',n,n,one,b,ldb,vr(1,ks),1,zero,work,1)

                    tmprr = la_qdot(n,work,1,vl(1,ks),1)
                    tmpri = la_qdot(n,work,1,vl(1,ks + 1),1)
                    call la_qgemv('N',n,n,one,b,ldb,vr(1,ks + 1),1,zero,work,1)

                    tmpii = la_qdot(n,work,1,vl(1,ks + 1),1)
                    tmpir = la_qdot(n,work,1,vl(1,ks),1)
                    uhbv = tmprr + tmpii
                    uhbvi = tmpir - tmpri
                    uhav = la_qlapy2(uhav,uhavi)
                    uhbv = la_qlapy2(uhbv,uhbvi)
                    cond = la_qlapy2(uhav,uhbv)
                    s(ks) = cond/(rnrm*lnrm)
                    s(ks + 1) = s(ks)
                 else
                    ! real eigenvalue.
                    rnrm = la_qnrm2(n,vr(1,ks),1)
                    lnrm = la_qnrm2(n,vl(1,ks),1)
                    call la_qgemv('N',n,n,one,a,lda,vr(1,ks),1,zero,work,1)

                    uhav = la_qdot(n,work,1,vl(1,ks),1)
                    call la_qgemv('N',n,n,one,b,ldb,vr(1,ks),1,zero,work,1)

                    uhbv = la_qdot(n,work,1,vl(1,ks),1)
                    cond = la_qlapy2(uhav,uhbv)
                    if (cond == zero) then
                       s(ks) = -one
                    else
                       s(ks) = cond/(rnrm*lnrm)
                    end if
                 end if
              end if
              if (wantdf) then
                 if (n == 1) then
                    dif(ks) = la_qlapy2(a(1,1),b(1,1))
                    cycle loop_20
                 end if
                 ! estimate the reciprocal condition number of the k-th
                 ! eigenvectors.
                 if (pair) then
                    ! copy the  2-by 2 pencil beginning at (a(k,k), b(k, k)).
                    ! compute the eigenvalue(s) at position k.
                    work(1) = a(k,k)
                    work(2) = a(k + 1,k)
                    work(3) = a(k,k + 1)
                    work(4) = a(k + 1,k + 1)
                    work(5) = b(k,k)
                    work(6) = b(k + 1,k)
                    work(7) = b(k,k + 1)
                    work(8) = b(k + 1,k + 1)
                    call la_qlag2(work,2,work(5),2,smlnum*eps,beta,dummy1(1), &
                              alphar,dummy(1),alphai)
                    alprqt = one
                    c1 = two*(alphar*alphar + alphai*alphai + beta*beta)
                    c2 = four*beta*beta*alphai*alphai
                    root1 = c1 + sqrt(c1*c1 - 4.0_qp*c2)
                    root2 = c2/root1
                    root1 = root1/two
                    cond = min(sqrt(root1),sqrt(root2))
                 end if
                 ! copy the matrix (a, b) to the array work and swap the
                 ! diagonal block beginning at a(k,k) to the (1,1) position.
                 call la_qlacpy('FULL',n,n,a,lda,work,n)
                 call la_qlacpy('FULL',n,n,b,ldb,work(n*n + 1),n)
                 ifst = k
                 ilst = 1
                 call la_qtgexc(.false.,.false.,n,work,n,work(n*n + 1),n,dummy,1, &
                           dummy1,1,ifst,ilst,work(n*n*2 + 1),lwork - 2*n*n,ierr)
                 if (ierr > 0) then
                    ! ill-conditioned problem - swap rejected.
                    dif(ks) = zero
                 else
                    ! reordering successful, solve generalized sylvester
                    ! equation for r and l,
                               ! a22 * r - l * a11 = a12
                               ! b22 * r - l * b11 = b12,
                    ! and compute estimate of difl((a11,b11), (a22, b22)).
                    n1 = 1
                    if (work(2) /= zero) n1 = 2
                    n2 = n - n1
                    if (n2 == 0) then
                       dif(ks) = cond
                    else
                       i = n*n + 1
                       iz = 2*n*n + 1
                       call la_qtgsyl('N',difdri,n2,n1,work(n*n1 + n1 + 1),n,work,n, &
                       work(n1 + 1),n,work(n*n1 + n1 + i),n,work(i),n,work(n1 + i),n,scale, &
                                 dif(ks),work(iz + 1),lwork - 2*n*n,iwork,ierr)
                       if (pair) dif(ks) = min(max(one,alprqt)*dif(ks),cond)
                    end if
                 end if
                 if (pair) dif(ks + 1) = dif(ks)
              end if
              if (pair) ks = ks + 1
           end do loop_20
           work(1) = lwmin
           return
     end subroutine la_qtgsna

     !> DTGSY2: solves the generalized Sylvester equation:
     !> A * R - L * B = scale * C                (1)
     !> D * R - L * E = scale * F,
     !> using Level 1 and 2 BLAS. where R and L are unknown M-by-N matrices,
     !> (A, D), (B, E) and (C, F) are given matrix pairs of size M-by-M,
     !> N-by-N and M-by-N, respectively, with real entries. (A, D) and (B, E)
     !> must be in generalized Schur canonical form, i.e. A, B are upper
     !> quasi triangular and D, E are upper triangular. The solution (R, L)
     !> overwrites (C, F). 0 <= SCALE <= 1 is an output scaling factor
     !> chosen to avoid overflow.
     !> In matrix notation solving equation (1) corresponds to solve
     !> Z*x = scale*b, where Z is defined as
     !> Z = [ kron(In, A)  -kron(B**T, Im) ]             (2)
     !> [ kron(In, D)  -kron(E**T, Im) ],
     !> Ik is the identity matrix of size k and X**T is the transpose of X.
     !> kron(X, Y) is the Kronecker product between the matrices X and Y.
     !> In the process of solving (1), we solve a number of such systems
     !> where Dim(In), Dim(In) = 1 or 2.
     !> If TRANS = 'T', solve the transposed system Z**T*y = scale*b for y,
     !> which is equivalent to solve for R and L in
     !> A**T * R  + D**T * L   = scale * C           (3)
     !> R  * B**T + L  * E**T  = scale * -F
     !> This case is used to compute an estimate of Dif[(A, D), (B, E)] =
     !> sigma_min(Z) using reverse communication with DLACON.
     !> DTGSY2 also (IJOB >= 1) contributes to the computation in DTGSYL
     !> of an upper bound on the separation between to matrix pairs. Then
     !> the input (A, D), (B, E) are sub-pencils of the matrix pair in
     !> DTGSYL. See DTGSYL for details.

     pure subroutine la_qtgsy2(trans,ijob,m,n,a,lda,b,ldb,c,ldc,d,ldd,e,lde,f, &
               ldf,scale,rdsum,rdscal,iwork,pq,info)
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(in) :: ijob,lda,ldb,ldc,ldd,lde,ldf,m,n
           integer(ilp),intent(out) :: info,pq
           real(qp),intent(inout) :: rdscal,rdsum
           real(qp),intent(out) :: scale
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(in) :: a(lda,*),b(ldb,*),d(ldd,*),e(lde,*)
           real(qp),intent(inout) :: c(ldc,*),f(ldf,*)
        ! =====================================================================
        ! replaced various illegal calls to la_qcopy by calls to la_qlaset.
        ! sven hammarling, 27/5/02.
           ! Parameters
           integer(ilp),parameter :: ldz = 8

           ! Local Scalars
           logical(lk) :: notran
           integer(ilp) :: i,ie,ierr,ii,is,isp1,j,je,jj,js,jsp1,k,mb,nb,p,q, &
                     zdim
           real(qp) :: alpha,scaloc
           ! Local Arrays
           integer(ilp) :: ipiv(ldz),jpiv(ldz)
           real(qp) :: rhs(ldz),z(ldz,ldz)
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! decode and test input parameters
           info = 0
           ierr = 0
           notran = la_lsame(trans,'N')
           if (.not. notran .and. .not. la_lsame(trans,'T')) then
              info = -1
           else if (notran) then
              if ((ijob < 0) .or. (ijob > 2)) then
                 info = -2
              end if
           end if
           if (info == 0) then
              if (m <= 0) then
                 info = -3
              else if (n <= 0) then
                 info = -4
              else if (lda < max(1,m)) then
                 info = -6
              else if (ldb < max(1,n)) then
                 info = -8
              else if (ldc < max(1,m)) then
                 info = -10
              else if (ldd < max(1,m)) then
                 info = -12
              else if (lde < max(1,n)) then
                 info = -14
              else if (ldf < max(1,m)) then
                 info = -16
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DTGSY2',-info)
              return
           end if
           ! determine block structure of a
           pq = 0
           p = 0
           i = 1
           10 continue
           if (i > m) go to 20
           p = p + 1
           iwork(p) = i
           if (i == m) go to 20
           if (a(i + 1,i) /= zero) then
              i = i + 2
           else
              i = i + 1
           end if
           go to 10
           20 continue
           iwork(p + 1) = m + 1
           ! determine block structure of b
           q = p + 1
           j = 1
           30 continue
           if (j > n) go to 40
           q = q + 1
           iwork(q) = j
           if (j == n) go to 40
           if (b(j + 1,j) /= zero) then
              j = j + 2
           else
              j = j + 1
           end if
           go to 30
           40 continue
           iwork(q + 1) = n + 1
           pq = p*(q - p - 1)
           if (notran) then
              ! solve (i, j) - subsystem
                 ! a(i, i) * r(i, j) - l(i, j) * b(j, j) = c(i, j)
                 ! d(i, i) * r(i, j) - l(i, j) * e(j, j) = f(i, j)
              ! for i = p, p - 1, ..., 1; j = 1, 2, ..., q
              scale = one
              scaloc = one
              loop_120: do j = p + 2,q
                 js = iwork(j)
                 jsp1 = js + 1
                 je = iwork(j + 1) - 1
                 nb = je - js + 1
                 loop_110: do i = p,1,-1
                    is = iwork(i)
                    isp1 = is + 1
                    ie = iwork(i + 1) - 1
                    mb = ie - is + 1
                    zdim = mb*nb*2
                    if ((mb == 1) .and. (nb == 1)) then
                       ! build a 2-by-2 system z * x = rhs
                       z(1,1) = a(is,is)
                       z(2,1) = d(is,is)
                       z(1,2) = -b(js,js)
                       z(2,2) = -e(js,js)
                       ! set up right hand side(s)
                       rhs(1) = c(is,js)
                       rhs(2) = f(is,js)
                       ! solve z * x = rhs
                       call la_qgetc2(zdim,z,ldz,ipiv,jpiv,ierr)
                       if (ierr > 0) info = ierr
                       if (ijob == 0) then
                          call la_qgesc2(zdim,z,ldz,rhs,ipiv,jpiv,scaloc)
                          if (scaloc /= one) then
                             do k = 1,n
                                call la_qscal(m,scaloc,c(1,k),1)
                                call la_qscal(m,scaloc,f(1,k),1)
                             end do
                             scale = scale*scaloc
                          end if
                       else
                          call la_qlatdf(ijob,zdim,z,ldz,rhs,rdsum,rdscal,ipiv,jpiv)

                       end if
                       ! unpack solution vector(s)
                       c(is,js) = rhs(1)
                       f(is,js) = rhs(2)
                       ! substitute r(i, j) and l(i, j) into remaining
                       ! equation.
                       if (i > 1) then
                          alpha = -rhs(1)
                          call la_qaxpy(is - 1,alpha,a(1,is),1,c(1,js),1)
                          call la_qaxpy(is - 1,alpha,d(1,is),1,f(1,js),1)
                       end if
                       if (j < q) then
                          call la_qaxpy(n - je,rhs(2),b(js,je + 1),ldb,c(is,je + 1), &
                                    ldc)
                          call la_qaxpy(n - je,rhs(2),e(js,je + 1),lde,f(is,je + 1), &
                                    ldf)
                       end if
                    else if ((mb == 1) .and. (nb == 2)) then
                       ! build a 4-by-4 system z * x = rhs
                       z(1,1) = a(is,is)
                       z(2,1) = zero
                       z(3,1) = d(is,is)
                       z(4,1) = zero
                       z(1,2) = zero
                       z(2,2) = a(is,is)
                       z(3,2) = zero
                       z(4,2) = d(is,is)
                       z(1,3) = -b(js,js)
                       z(2,3) = -b(js,jsp1)
                       z(3,3) = -e(js,js)
                       z(4,3) = -e(js,jsp1)
                       z(1,4) = -b(jsp1,js)
                       z(2,4) = -b(jsp1,jsp1)
                       z(3,4) = zero
                       z(4,4) = -e(jsp1,jsp1)
                       ! set up right hand side(s)
                       rhs(1) = c(is,js)
                       rhs(2) = c(is,jsp1)
                       rhs(3) = f(is,js)
                       rhs(4) = f(is,jsp1)
                       ! solve z * x = rhs
                       call la_qgetc2(zdim,z,ldz,ipiv,jpiv,ierr)
                       if (ierr > 0) info = ierr
                       if (ijob == 0) then
                          call la_qgesc2(zdim,z,ldz,rhs,ipiv,jpiv,scaloc)
                          if (scaloc /= one) then
                             do k = 1,n
                                call la_qscal(m,scaloc,c(1,k),1)
                                call la_qscal(m,scaloc,f(1,k),1)
                             end do
                             scale = scale*scaloc
                          end if
                       else
                          call la_qlatdf(ijob,zdim,z,ldz,rhs,rdsum,rdscal,ipiv,jpiv)

                       end if
                       ! unpack solution vector(s)
                       c(is,js) = rhs(1)
                       c(is,jsp1) = rhs(2)
                       f(is,js) = rhs(3)
                       f(is,jsp1) = rhs(4)
                       ! substitute r(i, j) and l(i, j) into remaining
                       ! equation.
                       if (i > 1) then
                          call la_qger(is - 1,nb,-one,a(1,is),1,rhs(1),1,c(1,js), &
                                     ldc)
                          call la_qger(is - 1,nb,-one,d(1,is),1,rhs(1),1,f(1,js), &
                                     ldf)
                       end if
                       if (j < q) then
                          call la_qaxpy(n - je,rhs(3),b(js,je + 1),ldb,c(is,je + 1), &
                                    ldc)
                          call la_qaxpy(n - je,rhs(3),e(js,je + 1),lde,f(is,je + 1), &
                                    ldf)
                          call la_qaxpy(n - je,rhs(4),b(jsp1,je + 1),ldb,c(is,je + 1), &
                                    ldc)
                          call la_qaxpy(n - je,rhs(4),e(jsp1,je + 1),lde,f(is,je + 1), &
                                    ldf)
                       end if
                    else if ((mb == 2) .and. (nb == 1)) then
                       ! build a 4-by-4 system z * x = rhs
                       z(1,1) = a(is,is)
                       z(2,1) = a(isp1,is)
                       z(3,1) = d(is,is)
                       z(4,1) = zero
                       z(1,2) = a(is,isp1)
                       z(2,2) = a(isp1,isp1)
                       z(3,2) = d(is,isp1)
                       z(4,2) = d(isp1,isp1)
                       z(1,3) = -b(js,js)
                       z(2,3) = zero
                       z(3,3) = -e(js,js)
                       z(4,3) = zero
                       z(1,4) = zero
                       z(2,4) = -b(js,js)
                       z(3,4) = zero
                       z(4,4) = -e(js,js)
                       ! set up right hand side(s)
                       rhs(1) = c(is,js)
                       rhs(2) = c(isp1,js)
                       rhs(3) = f(is,js)
                       rhs(4) = f(isp1,js)
                       ! solve z * x = rhs
                       call la_qgetc2(zdim,z,ldz,ipiv,jpiv,ierr)
                       if (ierr > 0) info = ierr
                       if (ijob == 0) then
                          call la_qgesc2(zdim,z,ldz,rhs,ipiv,jpiv,scaloc)
                          if (scaloc /= one) then
                             do k = 1,n
                                call la_qscal(m,scaloc,c(1,k),1)
                                call la_qscal(m,scaloc,f(1,k),1)
                             end do
                             scale = scale*scaloc
                          end if
                       else
                          call la_qlatdf(ijob,zdim,z,ldz,rhs,rdsum,rdscal,ipiv,jpiv)

                       end if
                       ! unpack solution vector(s)
                       c(is,js) = rhs(1)
                       c(isp1,js) = rhs(2)
                       f(is,js) = rhs(3)
                       f(isp1,js) = rhs(4)
                       ! substitute r(i, j) and l(i, j) into remaining
                       ! equation.
                       if (i > 1) then
                          call la_qgemv('N',is - 1,mb,-one,a(1,is),lda,rhs(1),1, &
                                    one,c(1,js),1)
                          call la_qgemv('N',is - 1,mb,-one,d(1,is),ldd,rhs(1),1, &
                                    one,f(1,js),1)
                       end if
                       if (j < q) then
                          call la_qger(mb,n - je,one,rhs(3),1,b(js,je + 1),ldb,c(is, &
                                    je + 1),ldc)
                          call la_qger(mb,n - je,one,rhs(3),1,e(js,je + 1),lde,f(is, &
                                    je + 1),ldf)
                       end if
                    else if ((mb == 2) .and. (nb == 2)) then
                       ! build an 8-by-8 system z * x = rhs
                       call la_qlaset('F',ldz,ldz,zero,zero,z,ldz)
                       z(1,1) = a(is,is)
                       z(2,1) = a(isp1,is)
                       z(5,1) = d(is,is)
                       z(1,2) = a(is,isp1)
                       z(2,2) = a(isp1,isp1)
                       z(5,2) = d(is,isp1)
                       z(6,2) = d(isp1,isp1)
                       z(3,3) = a(is,is)
                       z(4,3) = a(isp1,is)
                       z(7,3) = d(is,is)
                       z(3,4) = a(is,isp1)
                       z(4,4) = a(isp1,isp1)
                       z(7,4) = d(is,isp1)
                       z(8,4) = d(isp1,isp1)
                       z(1,5) = -b(js,js)
                       z(3,5) = -b(js,jsp1)
                       z(5,5) = -e(js,js)
                       z(7,5) = -e(js,jsp1)
                       z(2,6) = -b(js,js)
                       z(4,6) = -b(js,jsp1)
                       z(6,6) = -e(js,js)
                       z(8,6) = -e(js,jsp1)
                       z(1,7) = -b(jsp1,js)
                       z(3,7) = -b(jsp1,jsp1)
                       z(7,7) = -e(jsp1,jsp1)
                       z(2,8) = -b(jsp1,js)
                       z(4,8) = -b(jsp1,jsp1)
                       z(8,8) = -e(jsp1,jsp1)
                       ! set up right hand side(s)
                       k = 1
                       ii = mb*nb + 1
                       do jj = 0,nb - 1
                          call la_qcopy(mb,c(is,js + jj),1,rhs(k),1)
                          call la_qcopy(mb,f(is,js + jj),1,rhs(ii),1)
                          k = k + mb
                          ii = ii + mb
                       end do
                       ! solve z * x = rhs
                       call la_qgetc2(zdim,z,ldz,ipiv,jpiv,ierr)
                       if (ierr > 0) info = ierr
                       if (ijob == 0) then
                          call la_qgesc2(zdim,z,ldz,rhs,ipiv,jpiv,scaloc)
                          if (scaloc /= one) then
                             do k = 1,n
                                call la_qscal(m,scaloc,c(1,k),1)
                                call la_qscal(m,scaloc,f(1,k),1)
                             end do
                             scale = scale*scaloc
                          end if
                       else
                          call la_qlatdf(ijob,zdim,z,ldz,rhs,rdsum,rdscal,ipiv,jpiv)

                       end if
                       ! unpack solution vector(s)
                       k = 1
                       ii = mb*nb + 1
                       do jj = 0,nb - 1
                          call la_qcopy(mb,rhs(k),1,c(is,js + jj),1)
                          call la_qcopy(mb,rhs(ii),1,f(is,js + jj),1)
                          k = k + mb
                          ii = ii + mb
                       end do
                       ! substitute r(i, j) and l(i, j) into remaining
                       ! equation.
                       if (i > 1) then
                          call la_qgemm('N','N',is - 1,nb,mb,-one,a(1,is),lda,rhs(1 &
                                    ),mb,one,c(1,js),ldc)
                          call la_qgemm('N','N',is - 1,nb,mb,-one,d(1,is),ldd,rhs(1 &
                                    ),mb,one,f(1,js),ldf)
                       end if
                       if (j < q) then
                          k = mb*nb + 1
                          call la_qgemm('N','N',mb,n - je,nb,one,rhs(k),mb,b(js,je + &
                                    1),ldb,one,c(is,je + 1),ldc)
                          call la_qgemm('N','N',mb,n - je,nb,one,rhs(k),mb,e(js,je + &
                                    1),lde,one,f(is,je + 1),ldf)
                       end if
                    end if
                 end do loop_110
              end do loop_120
           else
              ! solve (i, j) - subsystem
                   ! a(i, i)**t * r(i, j) + d(i, i)**t * l(j, j)  =  c(i, j)
                   ! r(i, i)  * b(j, j) + l(i, j)  * e(j, j)  = -f(i, j)
              ! for i = 1, 2, ..., p, j = q, q - 1, ..., 1
              scale = one
              scaloc = one
              loop_200: do i = 1,p
                 is = iwork(i)
                 isp1 = is + 1
                 ie = iwork(i + 1) - 1
                 mb = ie - is + 1
                 loop_190: do j = q,p + 2,-1
                    js = iwork(j)
                    jsp1 = js + 1
                    je = iwork(j + 1) - 1
                    nb = je - js + 1
                    zdim = mb*nb*2
                    if ((mb == 1) .and. (nb == 1)) then
                       ! build a 2-by-2 system z**t * x = rhs
                       z(1,1) = a(is,is)
                       z(2,1) = -b(js,js)
                       z(1,2) = d(is,is)
                       z(2,2) = -e(js,js)
                       ! set up right hand side(s)
                       rhs(1) = c(is,js)
                       rhs(2) = f(is,js)
                       ! solve z**t * x = rhs
                       call la_qgetc2(zdim,z,ldz,ipiv,jpiv,ierr)
                       if (ierr > 0) info = ierr
                       call la_qgesc2(zdim,z,ldz,rhs,ipiv,jpiv,scaloc)
                       if (scaloc /= one) then
                          do k = 1,n
                             call la_qscal(m,scaloc,c(1,k),1)
                             call la_qscal(m,scaloc,f(1,k),1)
                          end do
                          scale = scale*scaloc
                       end if
                       ! unpack solution vector(s)
                       c(is,js) = rhs(1)
                       f(is,js) = rhs(2)
                       ! substitute r(i, j) and l(i, j) into remaining
                       ! equation.
                       if (j > p + 2) then
                          alpha = rhs(1)
                          call la_qaxpy(js - 1,alpha,b(1,js),1,f(is,1),ldf)
                          alpha = rhs(2)
                          call la_qaxpy(js - 1,alpha,e(1,js),1,f(is,1),ldf)
                       end if
                       if (i < p) then
                          alpha = -rhs(1)
                          call la_qaxpy(m - ie,alpha,a(is,ie + 1),lda,c(ie + 1,js),1)

                          alpha = -rhs(2)
                          call la_qaxpy(m - ie,alpha,d(is,ie + 1),ldd,c(ie + 1,js),1)

                       end if
                    else if ((mb == 1) .and. (nb == 2)) then
                       ! build a 4-by-4 system z**t * x = rhs
                       z(1,1) = a(is,is)
                       z(2,1) = zero
                       z(3,1) = -b(js,js)
                       z(4,1) = -b(jsp1,js)
                       z(1,2) = zero
                       z(2,2) = a(is,is)
                       z(3,2) = -b(js,jsp1)
                       z(4,2) = -b(jsp1,jsp1)
                       z(1,3) = d(is,is)
                       z(2,3) = zero
                       z(3,3) = -e(js,js)
                       z(4,3) = zero
                       z(1,4) = zero
                       z(2,4) = d(is,is)
                       z(3,4) = -e(js,jsp1)
                       z(4,4) = -e(jsp1,jsp1)
                       ! set up right hand side(s)
                       rhs(1) = c(is,js)
                       rhs(2) = c(is,jsp1)
                       rhs(3) = f(is,js)
                       rhs(4) = f(is,jsp1)
                       ! solve z**t * x = rhs
                       call la_qgetc2(zdim,z,ldz,ipiv,jpiv,ierr)
                       if (ierr > 0) info = ierr
                       call la_qgesc2(zdim,z,ldz,rhs,ipiv,jpiv,scaloc)
                       if (scaloc /= one) then
                          do k = 1,n
                             call la_qscal(m,scaloc,c(1,k),1)
                             call la_qscal(m,scaloc,f(1,k),1)
                          end do
                          scale = scale*scaloc
                       end if
                       ! unpack solution vector(s)
                       c(is,js) = rhs(1)
                       c(is,jsp1) = rhs(2)
                       f(is,js) = rhs(3)
                       f(is,jsp1) = rhs(4)
                       ! substitute r(i, j) and l(i, j) into remaining
                       ! equation.
                       if (j > p + 2) then
                          call la_qaxpy(js - 1,rhs(1),b(1,js),1,f(is,1),ldf)

                          call la_qaxpy(js - 1,rhs(2),b(1,jsp1),1,f(is,1),ldf)

                          call la_qaxpy(js - 1,rhs(3),e(1,js),1,f(is,1),ldf)

                          call la_qaxpy(js - 1,rhs(4),e(1,jsp1),1,f(is,1),ldf)

                       end if
                       if (i < p) then
                          call la_qger(m - ie,nb,-one,a(is,ie + 1),lda,rhs(1),1,c(ie + &
                                    1,js),ldc)
                          call la_qger(m - ie,nb,-one,d(is,ie + 1),ldd,rhs(3),1,c(ie + &
                                    1,js),ldc)
                       end if
                    else if ((mb == 2) .and. (nb == 1)) then
                       ! build a 4-by-4 system z**t * x = rhs
                       z(1,1) = a(is,is)
                       z(2,1) = a(is,isp1)
                       z(3,1) = -b(js,js)
                       z(4,1) = zero
                       z(1,2) = a(isp1,is)
                       z(2,2) = a(isp1,isp1)
                       z(3,2) = zero
                       z(4,2) = -b(js,js)
                       z(1,3) = d(is,is)
                       z(2,3) = d(is,isp1)
                       z(3,3) = -e(js,js)
                       z(4,3) = zero
                       z(1,4) = zero
                       z(2,4) = d(isp1,isp1)
                       z(3,4) = zero
                       z(4,4) = -e(js,js)
                       ! set up right hand side(s)
                       rhs(1) = c(is,js)
                       rhs(2) = c(isp1,js)
                       rhs(3) = f(is,js)
                       rhs(4) = f(isp1,js)
                       ! solve z**t * x = rhs
                       call la_qgetc2(zdim,z,ldz,ipiv,jpiv,ierr)
                       if (ierr > 0) info = ierr
                       call la_qgesc2(zdim,z,ldz,rhs,ipiv,jpiv,scaloc)
                       if (scaloc /= one) then
                          do k = 1,n
                             call la_qscal(m,scaloc,c(1,k),1)
                             call la_qscal(m,scaloc,f(1,k),1)
                          end do
                          scale = scale*scaloc
                       end if
                       ! unpack solution vector(s)
                       c(is,js) = rhs(1)
                       c(isp1,js) = rhs(2)
                       f(is,js) = rhs(3)
                       f(isp1,js) = rhs(4)
                       ! substitute r(i, j) and l(i, j) into remaining
                       ! equation.
                       if (j > p + 2) then
                          call la_qger(mb,js - 1,one,rhs(1),1,b(1,js),1,f(is,1), &
                                    ldf)
                          call la_qger(mb,js - 1,one,rhs(3),1,e(1,js),1,f(is,1), &
                                    ldf)
                       end if
                       if (i < p) then
                          call la_qgemv('T',mb,m - ie,-one,a(is,ie + 1),lda,rhs(1),1, &
                                    one,c(ie + 1,js),1)
                          call la_qgemv('T',mb,m - ie,-one,d(is,ie + 1),ldd,rhs(3),1, &
                                    one,c(ie + 1,js),1)
                       end if
                    else if ((mb == 2) .and. (nb == 2)) then
                       ! build an 8-by-8 system z**t * x = rhs
                       call la_qlaset('F',ldz,ldz,zero,zero,z,ldz)
                       z(1,1) = a(is,is)
                       z(2,1) = a(is,isp1)
                       z(5,1) = -b(js,js)
                       z(7,1) = -b(jsp1,js)
                       z(1,2) = a(isp1,is)
                       z(2,2) = a(isp1,isp1)
                       z(6,2) = -b(js,js)
                       z(8,2) = -b(jsp1,js)
                       z(3,3) = a(is,is)
                       z(4,3) = a(is,isp1)
                       z(5,3) = -b(js,jsp1)
                       z(7,3) = -b(jsp1,jsp1)
                       z(3,4) = a(isp1,is)
                       z(4,4) = a(isp1,isp1)
                       z(6,4) = -b(js,jsp1)
                       z(8,4) = -b(jsp1,jsp1)
                       z(1,5) = d(is,is)
                       z(2,5) = d(is,isp1)
                       z(5,5) = -e(js,js)
                       z(2,6) = d(isp1,isp1)
                       z(6,6) = -e(js,js)
                       z(3,7) = d(is,is)
                       z(4,7) = d(is,isp1)
                       z(5,7) = -e(js,jsp1)
                       z(7,7) = -e(jsp1,jsp1)
                       z(4,8) = d(isp1,isp1)
                       z(6,8) = -e(js,jsp1)
                       z(8,8) = -e(jsp1,jsp1)
                       ! set up right hand side(s)
                       k = 1
                       ii = mb*nb + 1
                       do jj = 0,nb - 1
                          call la_qcopy(mb,c(is,js + jj),1,rhs(k),1)
                          call la_qcopy(mb,f(is,js + jj),1,rhs(ii),1)
                          k = k + mb
                          ii = ii + mb
                       end do
                       ! solve z**t * x = rhs
                       call la_qgetc2(zdim,z,ldz,ipiv,jpiv,ierr)
                       if (ierr > 0) info = ierr
                       call la_qgesc2(zdim,z,ldz,rhs,ipiv,jpiv,scaloc)
                       if (scaloc /= one) then
                          do k = 1,n
                             call la_qscal(m,scaloc,c(1,k),1)
                             call la_qscal(m,scaloc,f(1,k),1)
                          end do
                          scale = scale*scaloc
                       end if
                       ! unpack solution vector(s)
                       k = 1
                       ii = mb*nb + 1
                       do jj = 0,nb - 1
                          call la_qcopy(mb,rhs(k),1,c(is,js + jj),1)
                          call la_qcopy(mb,rhs(ii),1,f(is,js + jj),1)
                          k = k + mb
                          ii = ii + mb
                       end do
                       ! substitute r(i, j) and l(i, j) into remaining
                       ! equation.
                       if (j > p + 2) then
                          call la_qgemm('N','T',mb,js - 1,nb,one,c(is,js),ldc,b(1, &
                                    js),ldb,one,f(is,1),ldf)
                          call la_qgemm('N','T',mb,js - 1,nb,one,f(is,js),ldf,e(1, &
                                    js),lde,one,f(is,1),ldf)
                       end if
                       if (i < p) then
                          call la_qgemm('T','N',m - ie,nb,mb,-one,a(is,ie + 1),lda,c( &
                                    is,js),ldc,one,c(ie + 1,js),ldc)
                          call la_qgemm('T','N',m - ie,nb,mb,-one,d(is,ie + 1),ldd,f( &
                                    is,js),ldf,one,c(ie + 1,js),ldc)
                       end if
                    end if
                 end do loop_190
              end do loop_200
           end if
           return
     end subroutine la_qtgsy2

     !> DTGSYL: solves the generalized Sylvester equation:
     !> A * R - L * B = scale * C                 (1)
     !> D * R - L * E = scale * F
     !> where R and L are unknown m-by-n matrices, (A, D), (B, E) and
     !> (C, F) are given matrix pairs of size m-by-m, n-by-n and m-by-n,
     !> respectively, with real entries. (A, D) and (B, E) must be in
     !> generalized (real) Schur canonical form, i.e. A, B are upper quasi
     !> triangular and D, E are upper triangular.
     !> The solution (R, L) overwrites (C, F). 0 <= SCALE <= 1 is an output
     !> scaling factor chosen to avoid overflow.
     !> In matrix notation (1) is equivalent to solve  Zx = scale b, where
     !> Z is defined as
     !> Z = [ kron(In, A)  -kron(B**T, Im) ]         (2)
     !> [ kron(In, D)  -kron(E**T, Im) ].
     !> Here Ik is the identity matrix of size k and X**T is the transpose of
     !> X. kron(X, Y) is the Kronecker product between the matrices X and Y.
     !> If TRANS = 'T', DTGSYL solves the transposed system Z**T*y = scale*b,
     !> which is equivalent to solve for R and L in
     !> A**T * R + D**T * L = scale * C           (3)
     !> R * B**T + L * E**T = scale * -F
     !> This case (TRANS = 'T') is used to compute an one-norm-based estimate
     !> of Dif[(A,D), (B,E)], the separation between the matrix pairs (A,D)
     !> and (B,E), using DLACON.
     !> If IJOB >= 1, DTGSYL computes a Frobenius norm-based estimate
     !> of Dif[(A,D),(B,E)]. That is, the reciprocal of a lower bound on the
     !> reciprocal of the smallest singular value of Z. See [1-2] for more
     !> information.
     !> This is a level 3 BLAS algorithm.

     pure subroutine la_qtgsyl(trans,ijob,m,n,a,lda,b,ldb,c,ldc,d,ldd,e,lde,f, &
               ldf,scale,dif,work,lwork,iwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trans
           integer(ilp),intent(in) :: ijob,lda,ldb,ldc,ldd,lde,ldf,lwork,m,n
           integer(ilp),intent(out) :: info
           real(qp),intent(out) :: dif,scale
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(in) :: a(lda,*),b(ldb,*),d(ldd,*),e(lde,*)
           real(qp),intent(inout) :: c(ldc,*),f(ldf,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================
        ! replaced various illegal calls to la_qcopy by calls to la_qlaset.
        ! sven hammarling, 1/5/02.

           ! Local Scalars
           logical(lk) :: lquery,notran
           integer(ilp) :: i,ie,ifunc,iround,is,isolve,j,je,js,k,linfo,lwmin,mb,nb, &
                     p,ppqq,pq,q
           real(qp) :: dscale,dsum,scale2,scaloc
           ! Intrinsic Functions
           intrinsic :: real,max,sqrt
           ! Executable Statements
           ! decode and test input parameters
           info = 0
           notran = la_lsame(trans,'N')
           lquery = (lwork == -1)
           if (.not. notran .and. .not. la_lsame(trans,'T')) then
              info = -1
           else if (notran) then
              if ((ijob < 0) .or. (ijob > 4)) then
                 info = -2
              end if
           end if
           if (info == 0) then
              if (m <= 0) then
                 info = -3
              else if (n <= 0) then
                 info = -4
              else if (lda < max(1,m)) then
                 info = -6
              else if (ldb < max(1,n)) then
                 info = -8
              else if (ldc < max(1,m)) then
                 info = -10
              else if (ldd < max(1,m)) then
                 info = -12
              else if (lde < max(1,n)) then
                 info = -14
              else if (ldf < max(1,m)) then
                 info = -16
              end if
           end if
           if (info == 0) then
              if (notran) then
                 if (ijob == 1 .or. ijob == 2) then
                    lwmin = max(1,2*m*n)
                 else
                    lwmin = 1
                 end if
              else
                 lwmin = 1
              end if
              work(1) = lwmin
              if (lwork < lwmin .and. .not. lquery) then
                 info = -20
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DTGSYL',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible
           if (m == 0 .or. n == 0) then
              scale = 1
              if (notran) then
                 if (ijob /= 0) then
                    dif = 0
                 end if
              end if
              return
           end if
           ! determine optimal block sizes mb and nb
           mb = la_ilaenv(2,'DTGSYL',trans,m,n,-1,-1)
           nb = la_ilaenv(5,'DTGSYL',trans,m,n,-1,-1)
           isolve = 1
           ifunc = 0
           if (notran) then
              if (ijob >= 3) then
                 ifunc = ijob - 2
                 call la_qlaset('F',m,n,zero,zero,c,ldc)
                 call la_qlaset('F',m,n,zero,zero,f,ldf)
              else if (ijob >= 1) then
                 isolve = 2
              end if
           end if
           if ((mb <= 1 .and. nb <= 1) .or. (mb >= m .and. nb >= n)) then
              loop_30: do iround = 1,isolve
                 ! use unblocked level 2 solver
                 dscale = zero
                 dsum = one
                 pq = 0
                 call la_qtgsy2(trans,ifunc,m,n,a,lda,b,ldb,c,ldc,d,ldd,e,lde,f, &
                            ldf,scale,dsum,dscale,iwork,pq,info)
                 if (dscale /= zero) then
                    if (ijob == 1 .or. ijob == 3) then
                       dif = sqrt(real(2*m*n,KIND=qp))/(dscale*sqrt(dsum))
                    else
                       dif = sqrt(real(pq,KIND=qp))/(dscale*sqrt(dsum))
                    end if
                 end if
                 if (isolve == 2 .and. iround == 1) then
                    if (notran) then
                       ifunc = ijob
                    end if
                    scale2 = scale
                    call la_qlacpy('F',m,n,c,ldc,work,m)
                    call la_qlacpy('F',m,n,f,ldf,work(m*n + 1),m)
                    call la_qlaset('F',m,n,zero,zero,c,ldc)
                    call la_qlaset('F',m,n,zero,zero,f,ldf)
                 else if (isolve == 2 .and. iround == 2) then
                    call la_qlacpy('F',m,n,work,m,c,ldc)
                    call la_qlacpy('F',m,n,work(m*n + 1),m,f,ldf)
                    scale = scale2
                 end if
              end do loop_30
              return
           end if
           ! determine block structure of a
           p = 0
           i = 1
           40 continue
           if (i > m) go to 50
           p = p + 1
           iwork(p) = i
           i = i + mb
           if (i >= m) go to 50
           if (a(i,i - 1) /= zero) i = i + 1
           go to 40
           50 continue
           iwork(p + 1) = m + 1
           if (iwork(p) == iwork(p + 1)) p = p - 1
           ! determine block structure of b
           q = p + 1
           j = 1
           60 continue
           if (j > n) go to 70
           q = q + 1
           iwork(q) = j
           j = j + nb
           if (j >= n) go to 70
           if (b(j,j - 1) /= zero) j = j + 1
           go to 60
           70 continue
           iwork(q + 1) = n + 1
           if (iwork(q) == iwork(q + 1)) q = q - 1
           if (notran) then
              loop_150: do iround = 1,isolve
                 ! solve (i, j)-subsystem
                     ! a(i, i) * r(i, j) - l(i, j) * b(j, j) = c(i, j)
                     ! d(i, i) * r(i, j) - l(i, j) * e(j, j) = f(i, j)
                 ! for i = p, p - 1,..., 1; j = 1, 2,..., q
                 dscale = zero
                 dsum = one
                 pq = 0
                 scale = one
                 loop_130: do j = p + 2,q
                    js = iwork(j)
                    je = iwork(j + 1) - 1
                    nb = je - js + 1
                    loop_120: do i = p,1,-1
                       is = iwork(i)
                       ie = iwork(i + 1) - 1
                       mb = ie - is + 1
                       ppqq = 0
                       call la_qtgsy2(trans,ifunc,mb,nb,a(is,is),lda,b(js,js), &
                       ldb,c(is,js),ldc,d(is,is),ldd,e(js,js),lde,f(is,js),ldf, &
                                 scaloc,dsum,dscale,iwork(q + 2),ppqq,linfo)
                       if (linfo > 0) info = linfo
                       pq = pq + ppqq
                       if (scaloc /= one) then
                          do k = 1,js - 1
                             call la_qscal(m,scaloc,c(1,k),1)
                             call la_qscal(m,scaloc,f(1,k),1)
                          end do
                          do k = js,je
                             call la_qscal(is - 1,scaloc,c(1,k),1)
                             call la_qscal(is - 1,scaloc,f(1,k),1)
                          end do
                          do k = js,je
                             call la_qscal(m - ie,scaloc,c(ie + 1,k),1)
                             call la_qscal(m - ie,scaloc,f(ie + 1,k),1)
                          end do
                          do k = je + 1,n
                             call la_qscal(m,scaloc,c(1,k),1)
                             call la_qscal(m,scaloc,f(1,k),1)
                          end do
                          scale = scale*scaloc
                       end if
                       ! substitute r(i, j) and l(i, j) into remaining
                       ! equation.
                       if (i > 1) then
                          call la_qgemm('N','N',is - 1,nb,mb,-one,a(1,is),lda,c(is, &
                                    js),ldc,one,c(1,js),ldc)
                          call la_qgemm('N','N',is - 1,nb,mb,-one,d(1,is),ldd,c(is, &
                                    js),ldc,one,f(1,js),ldf)
                       end if
                       if (j < q) then
                          call la_qgemm('N','N',mb,n - je,nb,one,f(is,js),ldf,b(js, &
                                    je + 1),ldb,one,c(is,je + 1),ldc)
                          call la_qgemm('N','N',mb,n - je,nb,one,f(is,js),ldf,e(js, &
                                    je + 1),lde,one,f(is,je + 1),ldf)
                       end if
                    end do loop_120
                 end do loop_130
                 if (dscale /= zero) then
                    if (ijob == 1 .or. ijob == 3) then
                       dif = sqrt(real(2*m*n,KIND=qp))/(dscale*sqrt(dsum))
                    else
                       dif = sqrt(real(pq,KIND=qp))/(dscale*sqrt(dsum))
                    end if
                 end if
                 if (isolve == 2 .and. iround == 1) then
                    if (notran) then
                       ifunc = ijob
                    end if
                    scale2 = scale
                    call la_qlacpy('F',m,n,c,ldc,work,m)
                    call la_qlacpy('F',m,n,f,ldf,work(m*n + 1),m)
                    call la_qlaset('F',m,n,zero,zero,c,ldc)
                    call la_qlaset('F',m,n,zero,zero,f,ldf)
                 else if (isolve == 2 .and. iround == 2) then
                    call la_qlacpy('F',m,n,work,m,c,ldc)
                    call la_qlacpy('F',m,n,work(m*n + 1),m,f,ldf)
                    scale = scale2
                 end if
              end do loop_150
           else
              ! solve transposed (i, j)-subsystem
                   ! a(i, i)**t * r(i, j)  + d(i, i)**t * l(i, j)  =  c(i, j)
                   ! r(i, j)  * b(j, j)**t + l(i, j)  * e(j, j)**t = -f(i, j)
              ! for i = 1,2,..., p; j = q, q-1,..., 1
              scale = one
              loop_210: do i = 1,p
                 is = iwork(i)
                 ie = iwork(i + 1) - 1
                 mb = ie - is + 1
                 loop_200: do j = q,p + 2,-1
                    js = iwork(j)
                    je = iwork(j + 1) - 1
                    nb = je - js + 1
                    call la_qtgsy2(trans,ifunc,mb,nb,a(is,is),lda,b(js,js),ldb, &
                    c(is,js),ldc,d(is,is),ldd,e(js,js),lde,f(is,js),ldf,scaloc, &
                              dsum,dscale,iwork(q + 2),ppqq,linfo)
                    if (linfo > 0) info = linfo
                    if (scaloc /= one) then
                       do k = 1,js - 1
                          call la_qscal(m,scaloc,c(1,k),1)
                          call la_qscal(m,scaloc,f(1,k),1)
                       end do
                       do k = js,je
                          call la_qscal(is - 1,scaloc,c(1,k),1)
                          call la_qscal(is - 1,scaloc,f(1,k),1)
                       end do
                       do k = js,je
                          call la_qscal(m - ie,scaloc,c(ie + 1,k),1)
                          call la_qscal(m - ie,scaloc,f(ie + 1,k),1)
                       end do
                       do k = je + 1,n
                          call la_qscal(m,scaloc,c(1,k),1)
                          call la_qscal(m,scaloc,f(1,k),1)
                       end do
                       scale = scale*scaloc
                    end if
                    ! substitute r(i, j) and l(i, j) into remaining equation.
                    if (j > p + 2) then
                       call la_qgemm('N','T',mb,js - 1,nb,one,c(is,js),ldc,b(1,js) &
                                 ,ldb,one,f(is,1),ldf)
                       call la_qgemm('N','T',mb,js - 1,nb,one,f(is,js),ldf,e(1,js) &
                                 ,lde,one,f(is,1),ldf)
                    end if
                    if (i < p) then
                       call la_qgemm('T','N',m - ie,nb,mb,-one,a(is,ie + 1),lda,c(is, &
                                 js),ldc,one,c(ie + 1,js),ldc)
                       call la_qgemm('T','N',m - ie,nb,mb,-one,d(is,ie + 1),ldd,f(is, &
                                 js),ldf,one,c(ie + 1,js),ldc)
                    end if
                 end do loop_200
              end do loop_210
           end if
           work(1) = lwmin
           return
     end subroutine la_qtgsyl

     !> DTREVC: computes some or all of the right and/or left eigenvectors of
     !> a real upper quasi-triangular matrix T.
     !> Matrices of this type are produced by the Schur factorization of
     !> a real general matrix:  A = Q*T*Q**T, as computed by DHSEQR.
     !> The right eigenvector x and the left eigenvector y of T corresponding
     !> to an eigenvalue w are defined by:
     !> T*x = w*x,     (y**H)*T = w*(y**H)
     !> where y**H denotes the conjugate transpose of y.
     !> The eigenvalues are not input to this routine, but are read directly
     !> from the diagonal blocks of T.
     !> This routine returns the matrices X and/or Y of right and left
     !> eigenvectors of T, or the products Q*X and/or Q*Y, where Q is an
     !> input matrix.  If Q is the orthogonal factor that reduces a matrix
     !> A to Schur form T, then Q*X and Q*Y are the matrices of right and
     !> left eigenvectors of A.

     pure subroutine la_qtrevc(side,howmny,select,n,t,ldt,vl,ldvl,vr,ldvr,mm,m, &
               work,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: howmny,side
           integer(ilp),intent(out) :: info,m
           integer(ilp),intent(in) :: ldt,ldvl,ldvr,mm,n
           ! Array Arguments
           logical(lk),intent(inout) :: select(*)
           real(qp),intent(in) :: t(ldt,*)
           real(qp),intent(inout) :: vl(ldvl,*),vr(ldvr,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: allv,bothv,leftv,over,pair,rightv,somev
           integer(ilp) :: i,ierr,ii,ip,is,j,j1,j2,jnxt,k,ki,n2
           real(qp) :: beta,bignum,emax,ovfl,rec,remax,scale,smin,smlnum,ulp,unfl, &
                     vcrit,vmax,wi,wr,xnorm
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Local Arrays
           real(qp) :: x(2,2)
           ! Executable Statements
           ! decode and test the input parameters
           bothv = la_lsame(side,'B')
           rightv = la_lsame(side,'R') .or. bothv
           leftv = la_lsame(side,'L') .or. bothv
           allv = la_lsame(howmny,'A')
           over = la_lsame(howmny,'B')
           somev = la_lsame(howmny,'S')
           info = 0
           if (.not. rightv .and. .not. leftv) then
              info = -1
           else if (.not. allv .and. .not. over .and. .not. somev) then
              info = -2
           else if (n < 0) then
              info = -4
           else if (ldt < max(1,n)) then
              info = -6
           else if (ldvl < 1 .or. (leftv .and. ldvl < n)) then
              info = -8
           else if (ldvr < 1 .or. (rightv .and. ldvr < n)) then
              info = -10
           else
              ! set m to the number of columns required to store the selected
              ! eigenvectors, standardize the array select if necessary, and
              ! test mm.
              if (somev) then
                 m = 0
                 pair = .false.
                 do j = 1,n
                    if (pair) then
                       pair = .false.
                       select(j) = .false.
                    else
                       if (j < n) then
                          if (t(j + 1,j) == zero) then
                             if (select(j)) m = m + 1
                          else
                             pair = .true.
                             if (select(j) .or. select(j + 1)) then
                                select(j) = .true.
                                m = m + 2
                             end if
                          end if
                       else
                          if (select(n)) m = m + 1
                       end if
                    end if
                 end do
              else
                 m = n
              end if
              if (mm < m) then
                 info = -11
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DTREVC',-info)
              return
           end if
           ! quick return if possible.
           if (n == 0) return
           ! set the constants to control overflow.
           unfl = la_qlamch('SAFE MINIMUM')
           ovfl = one/unfl
           call la_qlabad(unfl,ovfl)
           ulp = la_qlamch('PRECISION')
           smlnum = unfl*(n/ulp)
           bignum = (one - ulp)/smlnum
           ! compute 1-norm of each column of strictly upper triangular
           ! part of t to control overflow in triangular solver.
           work(1) = zero
           do j = 2,n
              work(j) = zero
              do i = 1,j - 1
                 work(j) = work(j) + abs(t(i,j))
              end do
           end do
           ! index ip is used to specify the real or complex eigenvalue:
             ! ip = 0, real eigenvalue,
                  ! 1, first of conjugate complex pair: (wr,wi)
                 ! -1, second of conjugate complex pair: (wr,wi)
           n2 = 2*n
           if (rightv) then
              ! compute right eigenvectors.
              ip = 0
              is = m
              loop_140: do ki = n,1,-1
                 if (ip == 1) go to 130
                 if (ki == 1) go to 40
                 if (t(ki,ki - 1) == zero) go to 40
                 ip = -1
                 40 continue
                 if (somev) then
                    if (ip == 0) then
                       if (.not. select(ki)) go to 130
                    else
                       if (.not. select(ki - 1)) go to 130
                    end if
                 end if
                 ! compute the ki-th eigenvalue (wr,wi).
                 wr = t(ki,ki)
                 wi = zero
                 if (ip /= 0) wi = sqrt(abs(t(ki,ki - 1)))*sqrt(abs(t(ki - 1,ki)))
                 smin = max(ulp*(abs(wr) + abs(wi)),smlnum)
                 if (ip == 0) then
                    ! real right eigenvector
                    work(ki + n) = one
                    ! form right-hand side
                    do k = 1,ki - 1
                       work(k + n) = -t(k,ki)
                    end do
                    ! solve the upper quasi-triangular system:
                       ! (t(1:ki-1,1:ki-1) - wr)*x = scale*work.
                    jnxt = ki - 1
                    loop_60: do j = ki - 1,1,-1
                       if (j > jnxt) cycle loop_60
                       j1 = j
                       j2 = j
                       jnxt = j - 1
                       if (j > 1) then
                          if (t(j,j - 1) /= zero) then
                             j1 = j - 1
                             jnxt = j - 2
                          end if
                       end if
                       if (j1 == j2) then
                          ! 1-by-1 diagonal block
                          call la_qlaln2(.false.,1,1,smin,one,t(j,j),ldt,one,one, &
                                    work(j + n),n,wr,zero,x,2,scale,xnorm,ierr)
                          ! scale x(1,1) to avoid overflow when updating
                          ! the right-hand side.
                          if (xnorm > one) then
                             if (work(j) > bignum/xnorm) then
                                x(1,1) = x(1,1)/xnorm
                                scale = scale/xnorm
                             end if
                          end if
                          ! scale if necessary
                          if (scale /= one) call la_qscal(ki,scale,work(1 + n),1)
                          work(j + n) = x(1,1)
                          ! update right-hand side
                          call la_qaxpy(j - 1,-x(1,1),t(1,j),1,work(1 + n),1)

                       else
                          ! 2-by-2 diagonal block
                          call la_qlaln2(.false.,2,1,smin,one,t(j - 1,j - 1),ldt,one, &
                                    one,work(j - 1 + n),n,wr,zero,x,2,scale,xnorm,ierr)
                          ! scale x(1,1) and x(2,1) to avoid overflow when
                          ! updating the right-hand side.
                          if (xnorm > one) then
                             beta = max(work(j - 1),work(j))
                             if (beta > bignum/xnorm) then
                                x(1,1) = x(1,1)/xnorm
                                x(2,1) = x(2,1)/xnorm
                                scale = scale/xnorm
                             end if
                          end if
                          ! scale if necessary
                          if (scale /= one) call la_qscal(ki,scale,work(1 + n),1)
                          work(j - 1 + n) = x(1,1)
                          work(j + n) = x(2,1)
                          ! update right-hand side
                          call la_qaxpy(j - 2,-x(1,1),t(1,j - 1),1,work(1 + n),1)

                          call la_qaxpy(j - 2,-x(2,1),t(1,j),1,work(1 + n),1)

                       end if
                    end do loop_60
                    ! copy the vector x or q*x to vr and normalize.
                    if (.not. over) then
                       call la_qcopy(ki,work(1 + n),1,vr(1,is),1)
                       ii = la_iqamax(ki,vr(1,is),1)
                       remax = one/abs(vr(ii,is))
                       call la_qscal(ki,remax,vr(1,is),1)
                       do k = ki + 1,n
                          vr(k,is) = zero
                       end do
                    else
                       if (ki > 1) call la_qgemv('N',n,ki - 1,one,vr,ldvr,work(1 + n),1, &
                                 work(ki + n),vr(1,ki),1)
                       ii = la_iqamax(n,vr(1,ki),1)
                       remax = one/abs(vr(ii,ki))
                       call la_qscal(n,remax,vr(1,ki),1)
                    end if
                 else
                    ! complex right eigenvector.
                    ! initial solve
                      ! [ (t(ki-1,ki-1) t(ki-1,ki) ) - (wr + i* wi)]*x = 0.
                      ! [ (t(ki,ki-1)   t(ki,ki)   )               ]
                    if (abs(t(ki - 1,ki)) >= abs(t(ki,ki - 1))) then
                       work(ki - 1 + n) = one
                       work(ki + n2) = wi/t(ki - 1,ki)
                    else
                       work(ki - 1 + n) = -wi/t(ki,ki - 1)
                       work(ki + n2) = one
                    end if
                    work(ki + n) = zero
                    work(ki - 1 + n2) = zero
                    ! form right-hand side
                    do k = 1,ki - 2
                       work(k + n) = -work(ki - 1 + n)*t(k,ki - 1)
                       work(k + n2) = -work(ki + n2)*t(k,ki)
                    end do
                    ! solve upper quasi-triangular system:
                    ! (t(1:ki-2,1:ki-2) - (wr+i*wi))*x = scale*(work+i*work2)
                    jnxt = ki - 2
                    loop_90: do j = ki - 2,1,-1
                       if (j > jnxt) cycle loop_90
                       j1 = j
                       j2 = j
                       jnxt = j - 1
                       if (j > 1) then
                          if (t(j,j - 1) /= zero) then
                             j1 = j - 1
                             jnxt = j - 2
                          end if
                       end if
                       if (j1 == j2) then
                          ! 1-by-1 diagonal block
                          call la_qlaln2(.false.,1,2,smin,one,t(j,j),ldt,one,one, &
                                    work(j + n),n,wr,wi,x,2,scale,xnorm,ierr)
                          ! scale x(1,1) and x(1,2) to avoid overflow when
                          ! updating the right-hand side.
                          if (xnorm > one) then
                             if (work(j) > bignum/xnorm) then
                                x(1,1) = x(1,1)/xnorm
                                x(1,2) = x(1,2)/xnorm
                                scale = scale/xnorm
                             end if
                          end if
                          ! scale if necessary
                          if (scale /= one) then
                             call la_qscal(ki,scale,work(1 + n),1)
                             call la_qscal(ki,scale,work(1 + n2),1)
                          end if
                          work(j + n) = x(1,1)
                          work(j + n2) = x(1,2)
                          ! update the right-hand side
                          call la_qaxpy(j - 1,-x(1,1),t(1,j),1,work(1 + n),1)

                          call la_qaxpy(j - 1,-x(1,2),t(1,j),1,work(1 + n2),1)

                       else
                          ! 2-by-2 diagonal block
                          call la_qlaln2(.false.,2,2,smin,one,t(j - 1,j - 1),ldt,one, &
                                    one,work(j - 1 + n),n,wr,wi,x,2,scale,xnorm,ierr)
                          ! scale x to avoid overflow when updating
                          ! the right-hand side.
                          if (xnorm > one) then
                             beta = max(work(j - 1),work(j))
                             if (beta > bignum/xnorm) then
                                rec = one/xnorm
                                x(1,1) = x(1,1)*rec
                                x(1,2) = x(1,2)*rec
                                x(2,1) = x(2,1)*rec
                                x(2,2) = x(2,2)*rec
                                scale = scale*rec
                             end if
                          end if
                          ! scale if necessary
                          if (scale /= one) then
                             call la_qscal(ki,scale,work(1 + n),1)
                             call la_qscal(ki,scale,work(1 + n2),1)
                          end if
                          work(j - 1 + n) = x(1,1)
                          work(j + n) = x(2,1)
                          work(j - 1 + n2) = x(1,2)
                          work(j + n2) = x(2,2)
                          ! update the right-hand side
                          call la_qaxpy(j - 2,-x(1,1),t(1,j - 1),1,work(1 + n),1)

                          call la_qaxpy(j - 2,-x(2,1),t(1,j),1,work(1 + n),1)

                          call la_qaxpy(j - 2,-x(1,2),t(1,j - 1),1,work(1 + n2),1)

                          call la_qaxpy(j - 2,-x(2,2),t(1,j),1,work(1 + n2),1)

                       end if
                    end do loop_90
                    ! copy the vector x or q*x to vr and normalize.
                    if (.not. over) then
                       call la_qcopy(ki,work(1 + n),1,vr(1,is - 1),1)
                       call la_qcopy(ki,work(1 + n2),1,vr(1,is),1)
                       emax = zero
                       do k = 1,ki
                          emax = max(emax,abs(vr(k,is - 1)) + abs(vr(k,is)))
                       end do
                       remax = one/emax
                       call la_qscal(ki,remax,vr(1,is - 1),1)
                       call la_qscal(ki,remax,vr(1,is),1)
                       do k = ki + 1,n
                          vr(k,is - 1) = zero
                          vr(k,is) = zero
                       end do
                    else
                       if (ki > 2) then
                          call la_qgemv('N',n,ki - 2,one,vr,ldvr,work(1 + n),1,work(ki - &
                                    1 + n),vr(1,ki - 1),1)
                          call la_qgemv('N',n,ki - 2,one,vr,ldvr,work(1 + n2),1,work( &
                                    ki + n2),vr(1,ki),1)
                       else
                          call la_qscal(n,work(ki - 1 + n),vr(1,ki - 1),1)
                          call la_qscal(n,work(ki + n2),vr(1,ki),1)
                       end if
                       emax = zero
                       do k = 1,n
                          emax = max(emax,abs(vr(k,ki - 1)) + abs(vr(k,ki)))
                       end do
                       remax = one/emax
                       call la_qscal(n,remax,vr(1,ki - 1),1)
                       call la_qscal(n,remax,vr(1,ki),1)
                    end if
                 end if
                 is = is - 1
                 if (ip /= 0) is = is - 1
                 130 continue
                 if (ip == 1) ip = 0
                 if (ip == -1) ip = 1
              end do loop_140
           end if
           if (leftv) then
              ! compute left eigenvectors.
              ip = 0
              is = 1
              loop_260: do ki = 1,n
                 if (ip == -1) go to 250
                 if (ki == n) go to 150
                 if (t(ki + 1,ki) == zero) go to 150
                 ip = 1
                 150 continue
                 if (somev) then
                    if (.not. select(ki)) go to 250
                 end if
                 ! compute the ki-th eigenvalue (wr,wi).
                 wr = t(ki,ki)
                 wi = zero
                 if (ip /= 0) wi = sqrt(abs(t(ki,ki + 1)))*sqrt(abs(t(ki + 1,ki)))
                 smin = max(ulp*(abs(wr) + abs(wi)),smlnum)
                 if (ip == 0) then
                    ! real left eigenvector.
                    work(ki + n) = one
                    ! form right-hand side
                    do k = ki + 1,n
                       work(k + n) = -t(ki,k)
                    end do
                    ! solve the quasi-triangular system:
                       ! (t(ki+1:n,ki+1:n) - wr)**t*x = scale*work
                    vmax = one
                    vcrit = bignum
                    jnxt = ki + 1
                    loop_170: do j = ki + 1,n
                       if (j < jnxt) cycle loop_170
                       j1 = j
                       j2 = j
                       jnxt = j + 1
                       if (j < n) then
                          if (t(j + 1,j) /= zero) then
                             j2 = j + 1
                             jnxt = j + 2
                          end if
                       end if
                       if (j1 == j2) then
                          ! 1-by-1 diagonal block
                          ! scale if necessary to avoid overflow when forming
                          ! the right-hand side.
                          if (work(j) > vcrit) then
                             rec = one/vmax
                             call la_qscal(n - ki + 1,rec,work(ki + n),1)
                             vmax = one
                             vcrit = bignum
                          end if
                          work(j + n) = work(j + n) - la_qdot(j - ki - 1,t(ki + 1,j),1,work( &
                                    ki + 1 + n),1)
                          ! solve (t(j,j)-wr)**t*x = work
                          call la_qlaln2(.false.,1,1,smin,one,t(j,j),ldt,one,one, &
                                    work(j + n),n,wr,zero,x,2,scale,xnorm,ierr)
                          ! scale if necessary
                          if (scale /= one) call la_qscal(n - ki + 1,scale,work(ki + n),1)

                          work(j + n) = x(1,1)
                          vmax = max(abs(work(j + n)),vmax)
                          vcrit = bignum/vmax
                       else
                          ! 2-by-2 diagonal block
                          ! scale if necessary to avoid overflow when forming
                          ! the right-hand side.
                          beta = max(work(j),work(j + 1))
                          if (beta > vcrit) then
                             rec = one/vmax
                             call la_qscal(n - ki + 1,rec,work(ki + n),1)
                             vmax = one
                             vcrit = bignum
                          end if
                          work(j + n) = work(j + n) - la_qdot(j - ki - 1,t(ki + 1,j),1,work( &
                                    ki + 1 + n),1)
                          work(j + 1 + n) = work(j + 1 + n) - la_qdot(j - ki - 1,t(ki + 1,j + 1),1, &
                                    work(ki + 1 + n),1)
                          ! solve
                            ! [t(j,j)-wr   t(j,j+1)     ]**t * x = scale*( work1 )
                            ! [t(j+1,j)    t(j+1,j+1)-wr]                ( work2 )
                          call la_qlaln2(.true.,2,1,smin,one,t(j,j),ldt,one,one, &
                                    work(j + n),n,wr,zero,x,2,scale,xnorm,ierr)
                          ! scale if necessary
                          if (scale /= one) call la_qscal(n - ki + 1,scale,work(ki + n),1)

                          work(j + n) = x(1,1)
                          work(j + 1 + n) = x(2,1)
                          vmax = max(abs(work(j + n)),abs(work(j + 1 + n)),vmax)
                          vcrit = bignum/vmax
                       end if
                    end do loop_170
                    ! copy the vector x or q*x to vl and normalize.
                    if (.not. over) then
                       call la_qcopy(n - ki + 1,work(ki + n),1,vl(ki,is),1)
                       ii = la_iqamax(n - ki + 1,vl(ki,is),1) + ki - 1
                       remax = one/abs(vl(ii,is))
                       call la_qscal(n - ki + 1,remax,vl(ki,is),1)
                       do k = 1,ki - 1
                          vl(k,is) = zero
                       end do
                    else
                       if (ki < n) call la_qgemv('N',n,n - ki,one,vl(1,ki + 1),ldvl,work( &
                                 ki + 1 + n),1,work(ki + n),vl(1,ki),1)
                       ii = la_iqamax(n,vl(1,ki),1)
                       remax = one/abs(vl(ii,ki))
                       call la_qscal(n,remax,vl(1,ki),1)
                    end if
                 else
                    ! complex left eigenvector.
                     ! initial solve:
                       ! ((t(ki,ki)    t(ki,ki+1) )**t - (wr - i* wi))*x = 0.
                       ! ((t(ki+1,ki) t(ki+1,ki+1))                )
                    if (abs(t(ki,ki + 1)) >= abs(t(ki + 1,ki))) then
                       work(ki + n) = wi/t(ki,ki + 1)
                       work(ki + 1 + n2) = one
                    else
                       work(ki + n) = one
                       work(ki + 1 + n2) = -wi/t(ki + 1,ki)
                    end if
                    work(ki + 1 + n) = zero
                    work(ki + n2) = zero
                    ! form right-hand side
                    do k = ki + 2,n
                       work(k + n) = -work(ki + n)*t(ki,k)
                       work(k + n2) = -work(ki + 1 + n2)*t(ki + 1,k)
                    end do
                    ! solve complex quasi-triangular system:
                    ! ( t(ki+2,n:ki+2,n) - (wr-i*wi) )*x = work1+i*work2
                    vmax = one
                    vcrit = bignum
                    jnxt = ki + 2
                    loop_200: do j = ki + 2,n
                       if (j < jnxt) cycle loop_200
                       j1 = j
                       j2 = j
                       jnxt = j + 1
                       if (j < n) then
                          if (t(j + 1,j) /= zero) then
                             j2 = j + 1
                             jnxt = j + 2
                          end if
                       end if
                       if (j1 == j2) then
                          ! 1-by-1 diagonal block
                          ! scale if necessary to avoid overflow when
                          ! forming the right-hand side elements.
                          if (work(j) > vcrit) then
                             rec = one/vmax
                             call la_qscal(n - ki + 1,rec,work(ki + n),1)
                             call la_qscal(n - ki + 1,rec,work(ki + n2),1)
                             vmax = one
                             vcrit = bignum
                          end if
                          work(j + n) = work(j + n) - la_qdot(j - ki - 2,t(ki + 2,j),1,work( &
                                    ki + 2 + n),1)
                          work(j + n2) = work(j + n2) - la_qdot(j - ki - 2,t(ki + 2,j),1,work( &
                                    ki + 2 + n2),1)
                          ! solve (t(j,j)-(wr-i*wi))*(x11+i*x12)= wk+i*wk2
                          call la_qlaln2(.false.,1,2,smin,one,t(j,j),ldt,one,one, &
                                    work(j + n),n,wr,-wi,x,2,scale,xnorm,ierr)
                          ! scale if necessary
                          if (scale /= one) then
                             call la_qscal(n - ki + 1,scale,work(ki + n),1)
                             call la_qscal(n - ki + 1,scale,work(ki + n2),1)
                          end if
                          work(j + n) = x(1,1)
                          work(j + n2) = x(1,2)
                          vmax = max(abs(work(j + n)),abs(work(j + n2)),vmax)
                          vcrit = bignum/vmax
                       else
                          ! 2-by-2 diagonal block
                          ! scale if necessary to avoid overflow when forming
                          ! the right-hand side elements.
                          beta = max(work(j),work(j + 1))
                          if (beta > vcrit) then
                             rec = one/vmax
                             call la_qscal(n - ki + 1,rec,work(ki + n),1)
                             call la_qscal(n - ki + 1,rec,work(ki + n2),1)
                             vmax = one
                             vcrit = bignum
                          end if
                          work(j + n) = work(j + n) - la_qdot(j - ki - 2,t(ki + 2,j),1,work( &
                                    ki + 2 + n),1)
                          work(j + n2) = work(j + n2) - la_qdot(j - ki - 2,t(ki + 2,j),1,work( &
                                    ki + 2 + n2),1)
                          work(j + 1 + n) = work(j + 1 + n) - la_qdot(j - ki - 2,t(ki + 2,j + 1),1, &
                                    work(ki + 2 + n),1)
                          work(j + 1 + n2) = work(j + 1 + n2) - la_qdot(j - ki - 2,t(ki + 2,j + 1),1, &
                                    work(ki + 2 + n2),1)
                          ! solve 2-by-2 complex linear equation
                            ! ([t(j,j)   t(j,j+1)  ]**t-(wr-i*wi)*i)*x = scale*b
                            ! ([t(j+1,j) t(j+1,j+1)]               )
                          call la_qlaln2(.true.,2,2,smin,one,t(j,j),ldt,one,one, &
                                    work(j + n),n,wr,-wi,x,2,scale,xnorm,ierr)
                          ! scale if necessary
                          if (scale /= one) then
                             call la_qscal(n - ki + 1,scale,work(ki + n),1)
                             call la_qscal(n - ki + 1,scale,work(ki + n2),1)
                          end if
                          work(j + n) = x(1,1)
                          work(j + n2) = x(1,2)
                          work(j + 1 + n) = x(2,1)
                          work(j + 1 + n2) = x(2,2)
                          vmax = max(abs(x(1,1)),abs(x(1,2)),abs(x(2,1)),abs(x( &
                                     2,2)),vmax)
                          vcrit = bignum/vmax
                       end if
                    end do loop_200
                    ! copy the vector x or q*x to vl and normalize.
                    if (.not. over) then
                       call la_qcopy(n - ki + 1,work(ki + n),1,vl(ki,is),1)
                       call la_qcopy(n - ki + 1,work(ki + n2),1,vl(ki,is + 1),1)
                       emax = zero
                       do k = ki,n
                          emax = max(emax,abs(vl(k,is)) + abs(vl(k,is + 1)))
                       end do
                       remax = one/emax
                       call la_qscal(n - ki + 1,remax,vl(ki,is),1)
                       call la_qscal(n - ki + 1,remax,vl(ki,is + 1),1)
                       do k = 1,ki - 1
                          vl(k,is) = zero
                          vl(k,is + 1) = zero
                       end do
                    else
                       if (ki < n - 1) then
                          call la_qgemv('N',n,n - ki - 1,one,vl(1,ki + 2),ldvl,work(ki + 2 + &
                                    n),1,work(ki + n),vl(1,ki),1)
                          call la_qgemv('N',n,n - ki - 1,one,vl(1,ki + 2),ldvl,work(ki + 2 + &
                                    n2),1,work(ki + 1 + n2),vl(1,ki + 1),1)
                       else
                          call la_qscal(n,work(ki + n),vl(1,ki),1)
                          call la_qscal(n,work(ki + 1 + n2),vl(1,ki + 1),1)
                       end if
                       emax = zero
                       do k = 1,n
                          emax = max(emax,abs(vl(k,ki)) + abs(vl(k,ki + 1)))
                       end do
                       remax = one/emax
                       call la_qscal(n,remax,vl(1,ki),1)
                       call la_qscal(n,remax,vl(1,ki + 1),1)
                    end if
                 end if
                 is = is + 1
                 if (ip /= 0) is = is + 1
                 250 continue
                 if (ip == -1) ip = 0
                 if (ip == 1) ip = -1
              end do loop_260
           end if
           return
     end subroutine la_qtrevc

     !> DTREVC3: computes some or all of the right and/or left eigenvectors of
     !> a real upper quasi-triangular matrix T.
     !> Matrices of this type are produced by the Schur factorization of
     !> a real general matrix:  A = Q*T*Q**T, as computed by DHSEQR.
     !> The right eigenvector x and the left eigenvector y of T corresponding
     !> to an eigenvalue w are defined by:
     !> T*x = w*x,     (y**T)*T = w*(y**T)
     !> where y**T denotes the transpose of the vector y.
     !> The eigenvalues are not input to this routine, but are read directly
     !> from the diagonal blocks of T.
     !> This routine returns the matrices X and/or Y of right and left
     !> eigenvectors of T, or the products Q*X and/or Q*Y, where Q is an
     !> input matrix. If Q is the orthogonal factor that reduces a matrix
     !> A to Schur form T, then Q*X and Q*Y are the matrices of right and
     !> left eigenvectors of A.
     !> This uses a Level 3 BLAS version of the back transformation.

     pure subroutine la_qtrevc3(side,howmny,select,n,t,ldt,vl,ldvl,vr,ldvr,mm,m, &
               work,lwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: howmny,side
           integer(ilp),intent(out) :: info,m
           integer(ilp),intent(in) :: ldt,ldvl,ldvr,lwork,mm,n
           ! Array Arguments
           logical(lk),intent(inout) :: select(*)
           real(qp),intent(in) :: t(ldt,*)
           real(qp),intent(inout) :: vl(ldvl,*),vr(ldvr,*)
           real(qp),intent(out) :: work(*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: nbmin = 8
           integer(ilp),parameter :: nbmax = 128

           ! Local Scalars
           logical(lk) :: allv,bothv,leftv,lquery,over,pair,rightv,somev
           integer(ilp) :: i,ierr,ii,ip,is,j,j1,j2,jnxt,k,ki,iv,maxwrk,nb, &
                     ki2
           real(qp) :: beta,bignum,emax,ovfl,rec,remax,scale,smin,smlnum,ulp,unfl, &
                     vcrit,vmax,wi,wr,xnorm
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Local Arrays
           real(qp) :: x(2,2)
           integer(ilp) :: iscomplex(nbmax)
           ! Executable Statements
           ! decode and test the input parameters
           bothv = la_lsame(side,'B')
           rightv = la_lsame(side,'R') .or. bothv
           leftv = la_lsame(side,'L') .or. bothv
           allv = la_lsame(howmny,'A')
           over = la_lsame(howmny,'B')
           somev = la_lsame(howmny,'S')
           info = 0
           nb = la_ilaenv(1,'DTREVC',side//howmny,n,-1,-1,-1)
           maxwrk = n + 2*n*nb
           work(1) = maxwrk
           lquery = (lwork == -1)
           if (.not. rightv .and. .not. leftv) then
              info = -1
           else if (.not. allv .and. .not. over .and. .not. somev) then
              info = -2
           else if (n < 0) then
              info = -4
           else if (ldt < max(1,n)) then
              info = -6
           else if (ldvl < 1 .or. (leftv .and. ldvl < n)) then
              info = -8
           else if (ldvr < 1 .or. (rightv .and. ldvr < n)) then
              info = -10
           else if (lwork < max(1,3*n) .and. .not. lquery) then
              info = -14
           else
              ! set m to the number of columns required to store the selected
              ! eigenvectors, standardize the array select if necessary, and
              ! test mm.
              if (somev) then
                 m = 0
                 pair = .false.
                 do j = 1,n
                    if (pair) then
                       pair = .false.
                       select(j) = .false.
                    else
                       if (j < n) then
                          if (t(j + 1,j) == zero) then
                             if (select(j)) m = m + 1
                          else
                             pair = .true.
                             if (select(j) .or. select(j + 1)) then
                                select(j) = .true.
                                m = m + 2
                             end if
                          end if
                       else
                          if (select(n)) m = m + 1
                       end if
                    end if
                 end do
              else
                 m = n
              end if
              if (mm < m) then
                 info = -11
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DTREVC3',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible.
           if (n == 0) return
           ! use blocked version of back-transformation if sufficient workspace.
           ! zero-out the workspace to avoid potential nan propagation.
           if (over .and. lwork >= n + 2*n*nbmin) then
              nb = (lwork - n)/(2*n)
              nb = min(nb,nbmax)
              call la_qlaset('F',n,1 + 2*nb,zero,zero,work,n)
           else
              nb = 1
           end if
           ! set the constants to control overflow.
           unfl = la_qlamch('SAFE MINIMUM')
           ovfl = one/unfl
           call la_qlabad(unfl,ovfl)
           ulp = la_qlamch('PRECISION')
           smlnum = unfl*(n/ulp)
           bignum = (one - ulp)/smlnum
           ! compute 1-norm of each column of strictly upper triangular
           ! part of t to control overflow in triangular solver.
           work(1) = zero
           do j = 2,n
              work(j) = zero
              do i = 1,j - 1
                 work(j) = work(j) + abs(t(i,j))
              end do
           end do
           ! index ip is used to specify the real or complex eigenvalue:
             ! ip = 0, real eigenvalue,
                  ! 1, first  of conjugate complex pair: (wr,wi)
                 ! -1, second of conjugate complex pair: (wr,wi)
             ! iscomplex array stores ip for each column in current block.
           if (rightv) then
              ! ============================================================
              ! compute right eigenvectors.
              ! iv is index of column in current block.
              ! for complex right vector, uses iv-1 for real part and iv for complex part.
              ! non-blocked version always uses iv=2;
              ! blocked     version starts with iv=nb, goes down to 1 or 2.
              ! (note the "0-th" column is used for 1-norms computed above.)
              iv = 2
              if (nb > 2) then
                 iv = nb
              end if
              ip = 0
              is = m
              loop_140: do ki = n,1,-1
                 if (ip == -1) then
                    ! previous iteration (ki+1) was second of conjugate pair,
                    ! so this ki is first of conjugate pair; skip to end of loop
                    ip = 1
                    cycle loop_140
                 else if (ki == 1) then
                    ! last column, so this ki must be real eigenvalue
                    ip = 0
                 else if (t(ki,ki - 1) == zero) then
                    ! zero on sub-diagonal, so this ki is real eigenvalue
                    ip = 0
                 else
                    ! non-zero on sub-diagonal, so this ki is second of conjugate pair
                    ip = -1
                 end if
                 if (somev) then
                    if (ip == 0) then
                       if (.not. select(ki)) cycle loop_140
                    else
                       if (.not. select(ki - 1)) cycle loop_140
                    end if
                 end if
                 ! compute the ki-th eigenvalue (wr,wi).
                 wr = t(ki,ki)
                 wi = zero
                 if (ip /= 0) wi = sqrt(abs(t(ki,ki - 1)))*sqrt(abs(t(ki - 1,ki)))
                 smin = max(ulp*(abs(wr) + abs(wi)),smlnum)
                 if (ip == 0) then
                    ! --------------------------------------------------------
                    ! real right eigenvector
                    work(ki + iv*n) = one
                    ! form right-hand side.
                    do k = 1,ki - 1
                       work(k + iv*n) = -t(k,ki)
                    end do
                    ! solve upper quasi-triangular system:
                    ! [ t(1:ki-1,1:ki-1) - wr ]*x = scale*work.
                    jnxt = ki - 1
                    loop_60: do j = ki - 1,1,-1
                       if (j > jnxt) cycle loop_60
                       j1 = j
                       j2 = j
                       jnxt = j - 1
                       if (j > 1) then
                          if (t(j,j - 1) /= zero) then
                             j1 = j - 1
                             jnxt = j - 2
                          end if
                       end if
                       if (j1 == j2) then
                          ! 1-by-1 diagonal block
                          call la_qlaln2(.false.,1,1,smin,one,t(j,j),ldt,one,one, &
                                    work(j + iv*n),n,wr,zero,x,2,scale,xnorm,ierr)
                          ! scale x(1,1) to avoid overflow when updating
                          ! the right-hand side.
                          if (xnorm > one) then
                             if (work(j) > bignum/xnorm) then
                                x(1,1) = x(1,1)/xnorm
                                scale = scale/xnorm
                             end if
                          end if
                          ! scale if necessary
                          if (scale /= one) call la_qscal(ki,scale,work(1 + iv*n),1)

                          work(j + iv*n) = x(1,1)
                          ! update right-hand side
                          call la_qaxpy(j - 1,-x(1,1),t(1,j),1,work(1 + iv*n),1)

                       else
                          ! 2-by-2 diagonal block
                          call la_qlaln2(.false.,2,1,smin,one,t(j - 1,j - 1),ldt,one, &
                                    one,work(j - 1 + iv*n),n,wr,zero,x,2,scale,xnorm,ierr)
                          ! scale x(1,1) and x(2,1) to avoid overflow when
                          ! updating the right-hand side.
                          if (xnorm > one) then
                             beta = max(work(j - 1),work(j))
                             if (beta > bignum/xnorm) then
                                x(1,1) = x(1,1)/xnorm
                                x(2,1) = x(2,1)/xnorm
                                scale = scale/xnorm
                             end if
                          end if
                          ! scale if necessary
                          if (scale /= one) call la_qscal(ki,scale,work(1 + iv*n),1)

                          work(j - 1 + iv*n) = x(1,1)
                          work(j + iv*n) = x(2,1)
                          ! update right-hand side
                          call la_qaxpy(j - 2,-x(1,1),t(1,j - 1),1,work(1 + iv*n),1)

                          call la_qaxpy(j - 2,-x(2,1),t(1,j),1,work(1 + iv*n),1)

                       end if
                    end do loop_60
                    ! copy the vector x or q*x to vr and normalize.
                    if (.not. over) then
                       ! ------------------------------
                       ! no back-transform: copy x to vr and normalize.
                       call la_qcopy(ki,work(1 + iv*n),1,vr(1,is),1)
                       ii = la_iqamax(ki,vr(1,is),1)
                       remax = one/abs(vr(ii,is))
                       call la_qscal(ki,remax,vr(1,is),1)
                       do k = ki + 1,n
                          vr(k,is) = zero
                       end do
                    else if (nb == 1) then
                       ! ------------------------------
                       ! version 1: back-transform each vector with gemv, q*x.
                       if (ki > 1) call la_qgemv('N',n,ki - 1,one,vr,ldvr,work(1 + iv*n), &
                                 1,work(ki + iv*n),vr(1,ki),1)
                       ii = la_iqamax(n,vr(1,ki),1)
                       remax = one/abs(vr(ii,ki))
                       call la_qscal(n,remax,vr(1,ki),1)
                    else
                       ! ------------------------------
                       ! version 2: back-transform block of vectors with gemm
                       ! zero out below vector
                       do k = ki + 1,n
                          work(k + iv*n) = zero
                       end do
                       iscomplex(iv) = ip
                       ! back-transform and normalization is done below
                    end if
                 else
                    ! --------------------------------------------------------
                    ! complex right eigenvector.
                    ! initial solve
                    ! [ ( t(ki-1,ki-1) t(ki-1,ki) ) - (wr + i*wi) ]*x = 0.
                    ! [ ( t(ki,  ki-1) t(ki,  ki) )               ]
                    if (abs(t(ki - 1,ki)) >= abs(t(ki,ki - 1))) then
                       work(ki - 1 + (iv - 1)*n) = one
                       work(ki + (iv)*n) = wi/t(ki - 1,ki)
                    else
                       work(ki - 1 + (iv - 1)*n) = -wi/t(ki,ki - 1)
                       work(ki + (iv)*n) = one
                    end if
                    work(ki + (iv - 1)*n) = zero
                    work(ki - 1 + (iv)*n) = zero
                    ! form right-hand side.
                    do k = 1,ki - 2
                       work(k + (iv - 1)*n) = -work(ki - 1 + (iv - 1)*n)*t(k,ki - 1)
                       work(k + (iv)*n) = -work(ki + (iv)*n)*t(k,ki)
                    end do
                    ! solve upper quasi-triangular system:
                    ! [ t(1:ki-2,1:ki-2) - (wr+i*wi) ]*x = scale*(work+i*work2)
                    jnxt = ki - 2
                    loop_90: do j = ki - 2,1,-1
                       if (j > jnxt) cycle loop_90
                       j1 = j
                       j2 = j
                       jnxt = j - 1
                       if (j > 1) then
                          if (t(j,j - 1) /= zero) then
                             j1 = j - 1
                             jnxt = j - 2
                          end if
                       end if
                       if (j1 == j2) then
                          ! 1-by-1 diagonal block
                          call la_qlaln2(.false.,1,2,smin,one,t(j,j),ldt,one,one, &
                                    work(j + (iv - 1)*n),n,wr,wi,x,2,scale,xnorm,ierr)
                          ! scale x(1,1) and x(1,2) to avoid overflow when
                          ! updating the right-hand side.
                          if (xnorm > one) then
                             if (work(j) > bignum/xnorm) then
                                x(1,1) = x(1,1)/xnorm
                                x(1,2) = x(1,2)/xnorm
                                scale = scale/xnorm
                             end if
                          end if
                          ! scale if necessary
                          if (scale /= one) then
                             call la_qscal(ki,scale,work(1 + (iv - 1)*n),1)
                             call la_qscal(ki,scale,work(1 + (iv)*n),1)
                          end if
                          work(j + (iv - 1)*n) = x(1,1)
                          work(j + (iv)*n) = x(1,2)
                          ! update the right-hand side
                          call la_qaxpy(j - 1,-x(1,1),t(1,j),1,work(1 + (iv - 1)*n),1)

                          call la_qaxpy(j - 1,-x(1,2),t(1,j),1,work(1 + (iv)*n),1)

                       else
                          ! 2-by-2 diagonal block
                          call la_qlaln2(.false.,2,2,smin,one,t(j - 1,j - 1),ldt,one, &
                                    one,work(j - 1 + (iv - 1)*n),n,wr,wi,x,2,scale,xnorm,ierr)
                          ! scale x to avoid overflow when updating
                          ! the right-hand side.
                          if (xnorm > one) then
                             beta = max(work(j - 1),work(j))
                             if (beta > bignum/xnorm) then
                                rec = one/xnorm
                                x(1,1) = x(1,1)*rec
                                x(1,2) = x(1,2)*rec
                                x(2,1) = x(2,1)*rec
                                x(2,2) = x(2,2)*rec
                                scale = scale*rec
                             end if
                          end if
                          ! scale if necessary
                          if (scale /= one) then
                             call la_qscal(ki,scale,work(1 + (iv - 1)*n),1)
                             call la_qscal(ki,scale,work(1 + (iv)*n),1)
                          end if
                          work(j - 1 + (iv - 1)*n) = x(1,1)
                          work(j + (iv - 1)*n) = x(2,1)
                          work(j - 1 + (iv)*n) = x(1,2)
                          work(j + (iv)*n) = x(2,2)
                          ! update the right-hand side
                          call la_qaxpy(j - 2,-x(1,1),t(1,j - 1),1,work(1 + (iv - 1)*n), &
                                     1)
                          call la_qaxpy(j - 2,-x(2,1),t(1,j),1,work(1 + (iv - 1)*n), &
                                    1)
                          call la_qaxpy(j - 2,-x(1,2),t(1,j - 1),1,work(1 + (iv)*n), &
                                    1)
                          call la_qaxpy(j - 2,-x(2,2),t(1,j),1,work(1 + (iv)*n),1)

                       end if
                    end do loop_90
                    ! copy the vector x or q*x to vr and normalize.
                    if (.not. over) then
                       ! ------------------------------
                       ! no back-transform: copy x to vr and normalize.
                       call la_qcopy(ki,work(1 + (iv - 1)*n),1,vr(1,is - 1),1)
                       call la_qcopy(ki,work(1 + (iv)*n),1,vr(1,is),1)
                       emax = zero
                       do k = 1,ki
                          emax = max(emax,abs(vr(k,is - 1)) + abs(vr(k,is)))
                       end do
                       remax = one/emax
                       call la_qscal(ki,remax,vr(1,is - 1),1)
                       call la_qscal(ki,remax,vr(1,is),1)
                       do k = ki + 1,n
                          vr(k,is - 1) = zero
                          vr(k,is) = zero
                       end do
                    else if (nb == 1) then
                       ! ------------------------------
                       ! version 1: back-transform each vector with gemv, q*x.
                       if (ki > 2) then
                          call la_qgemv('N',n,ki - 2,one,vr,ldvr,work(1 + (iv - 1)*n), &
                                    1,work(ki - 1 + (iv - 1)*n),vr(1,ki - 1),1)
                          call la_qgemv('N',n,ki - 2,one,vr,ldvr,work(1 + (iv)*n),1, &
                                    work(ki + (iv)*n),vr(1,ki),1)
                       else
                          call la_qscal(n,work(ki - 1 + (iv - 1)*n),vr(1,ki - 1),1)
                          call la_qscal(n,work(ki + (iv)*n),vr(1,ki),1)
                       end if
                       emax = zero
                       do k = 1,n
                          emax = max(emax,abs(vr(k,ki - 1)) + abs(vr(k,ki)))
                       end do
                       remax = one/emax
                       call la_qscal(n,remax,vr(1,ki - 1),1)
                       call la_qscal(n,remax,vr(1,ki),1)
                    else
                       ! ------------------------------
                       ! version 2: back-transform block of vectors with gemm
                       ! zero out below vector
                       do k = ki + 1,n
                          work(k + (iv - 1)*n) = zero
                          work(k + (iv)*n) = zero
                       end do
                       iscomplex(iv - 1) = -ip
                       iscomplex(iv) = ip
                       iv = iv - 1
                       ! back-transform and normalization is done below
                    end if
                 end if
                 if (nb > 1) then
                    ! --------------------------------------------------------
                    ! blocked version of back-transform
                    ! for complex case, ki2 includes both vectors (ki-1 and ki)
                    if (ip == 0) then
                       ki2 = ki
                    else
                       ki2 = ki - 1
                    end if
                    ! columns iv:nb of work are valid vectors.
                    ! when the number of vectors stored reaches nb-1 or nb,
                    ! or if this was last vector, do the gemm
                    if ((iv <= 2) .or. (ki2 == 1)) then
                       call la_qgemm('N','N',n,nb - iv + 1,ki2 + nb - iv,one,vr,ldvr,work(1 + &
                                 (iv)*n),n,zero,work(1 + (nb + iv)*n),n)
                       ! normalize vectors
                       do k = iv,nb
                          if (iscomplex(k) == 0) then
                             ! real eigenvector
                             ii = la_iqamax(n,work(1 + (nb + k)*n),1)
                             remax = one/abs(work(ii + (nb + k)*n))
                          else if (iscomplex(k) == 1) then
                             ! first eigenvector of conjugate pair
                             emax = zero
                             do ii = 1,n
                                emax = max(emax,abs(work(ii + (nb + k)*n)) + abs(work(ii + ( &
                                          nb + k + 1)*n)))
                             end do
                             remax = one/emax
                          ! else if iscomplex(k)==-1
                             ! second eigenvector of conjugate pair
                             ! reuse same remax as previous k
                          end if
                          call la_qscal(n,remax,work(1 + (nb + k)*n),1)
                       end do
                       call la_qlacpy('F',n,nb - iv + 1,work(1 + (nb + iv)*n),n,vr(1,ki2), &
                                 ldvr)
                       iv = nb
                    else
                       iv = iv - 1
                    end if
                 end if ! blocked back-transform
                 is = is - 1
                 if (ip /= 0) is = is - 1
              end do loop_140
           end if
           if (leftv) then
              ! ============================================================
              ! compute left eigenvectors.
              ! iv is index of column in current block.
              ! for complex left vector, uses iv for real part and iv+1 for complex part.
              ! non-blocked version always uses iv=1;
              ! blocked     version starts with iv=1, goes up to nb-1 or nb.
              ! (note the "0-th" column is used for 1-norms computed above.)
              iv = 1
              ip = 0
              is = 1
              loop_260: do ki = 1,n
                 if (ip == 1) then
                    ! previous iteration (ki-1) was first of conjugate pair,
                    ! so this ki is second of conjugate pair; skip to end of loop
                    ip = -1
                    cycle loop_260
                 else if (ki == n) then
                    ! last column, so this ki must be real eigenvalue
                    ip = 0
                 else if (t(ki + 1,ki) == zero) then
                    ! zero on sub-diagonal, so this ki is real eigenvalue
                    ip = 0
                 else
                    ! non-zero on sub-diagonal, so this ki is first of conjugate pair
                    ip = 1
                 end if
                 if (somev) then
                    if (.not. select(ki)) cycle loop_260
                 end if
                 ! compute the ki-th eigenvalue (wr,wi).
                 wr = t(ki,ki)
                 wi = zero
                 if (ip /= 0) wi = sqrt(abs(t(ki,ki + 1)))*sqrt(abs(t(ki + 1,ki)))
                 smin = max(ulp*(abs(wr) + abs(wi)),smlnum)
                 if (ip == 0) then
                    ! --------------------------------------------------------
                    ! real left eigenvector
                    work(ki + iv*n) = one
                    ! form right-hand side.
                    do k = ki + 1,n
                       work(k + iv*n) = -t(ki,k)
                    end do
                    ! solve transposed quasi-triangular system:
                    ! [ t(ki+1:n,ki+1:n) - wr ]**t * x = scale*work
                    vmax = one
                    vcrit = bignum
                    jnxt = ki + 1
                    loop_170: do j = ki + 1,n
                       if (j < jnxt) cycle loop_170
                       j1 = j
                       j2 = j
                       jnxt = j + 1
                       if (j < n) then
                          if (t(j + 1,j) /= zero) then
                             j2 = j + 1
                             jnxt = j + 2
                          end if
                       end if
                       if (j1 == j2) then
                          ! 1-by-1 diagonal block
                          ! scale if necessary to avoid overflow when forming
                          ! the right-hand side.
                          if (work(j) > vcrit) then
                             rec = one/vmax
                             call la_qscal(n - ki + 1,rec,work(ki + iv*n),1)
                             vmax = one
                             vcrit = bignum
                          end if
                          work(j + iv*n) = work(j + iv*n) - la_qdot(j - ki - 1,t(ki + 1,j),1, &
                                    work(ki + 1 + iv*n),1)
                          ! solve [ t(j,j) - wr ]**t * x = work
                          call la_qlaln2(.false.,1,1,smin,one,t(j,j),ldt,one,one, &
                                    work(j + iv*n),n,wr,zero,x,2,scale,xnorm,ierr)
                          ! scale if necessary
                          if (scale /= one) call la_qscal(n - ki + 1,scale,work(ki + iv*n),1)

                          work(j + iv*n) = x(1,1)
                          vmax = max(abs(work(j + iv*n)),vmax)
                          vcrit = bignum/vmax
                       else
                          ! 2-by-2 diagonal block
                          ! scale if necessary to avoid overflow when forming
                          ! the right-hand side.
                          beta = max(work(j),work(j + 1))
                          if (beta > vcrit) then
                             rec = one/vmax
                             call la_qscal(n - ki + 1,rec,work(ki + iv*n),1)
                             vmax = one
                             vcrit = bignum
                          end if
                          work(j + iv*n) = work(j + iv*n) - la_qdot(j - ki - 1,t(ki + 1,j),1, &
                                    work(ki + 1 + iv*n),1)
                          work(j + 1 + iv*n) = work(j + 1 + iv*n) - la_qdot(j - ki - 1,t(ki + 1,j + 1) &
                                    ,1,work(ki + 1 + iv*n),1)
                          ! solve
                          ! [ t(j,j)-wr   t(j,j+1)      ]**t * x = scale*( work1 )
                          ! [ t(j+1,j)    t(j+1,j+1)-wr ]                ( work2 )
                          call la_qlaln2(.true.,2,1,smin,one,t(j,j),ldt,one,one, &
                                    work(j + iv*n),n,wr,zero,x,2,scale,xnorm,ierr)
                          ! scale if necessary
                          if (scale /= one) call la_qscal(n - ki + 1,scale,work(ki + iv*n),1)

                          work(j + iv*n) = x(1,1)
                          work(j + 1 + iv*n) = x(2,1)
                          vmax = max(abs(work(j + iv*n)),abs(work(j + 1 + iv*n)),vmax)

                          vcrit = bignum/vmax
                       end if
                    end do loop_170
                    ! copy the vector x or q*x to vl and normalize.
                    if (.not. over) then
                       ! ------------------------------
                       ! no back-transform: copy x to vl and normalize.
                       call la_qcopy(n - ki + 1,work(ki + iv*n),1,vl(ki,is),1)
                       ii = la_iqamax(n - ki + 1,vl(ki,is),1) + ki - 1
                       remax = one/abs(vl(ii,is))
                       call la_qscal(n - ki + 1,remax,vl(ki,is),1)
                       do k = 1,ki - 1
                          vl(k,is) = zero
                       end do
                    else if (nb == 1) then
                       ! ------------------------------
                       ! version 1: back-transform each vector with gemv, q*x.
                       if (ki < n) call la_qgemv('N',n,n - ki,one,vl(1,ki + 1),ldvl,work( &
                                 ki + 1 + iv*n),1,work(ki + iv*n),vl(1,ki),1)
                       ii = la_iqamax(n,vl(1,ki),1)
                       remax = one/abs(vl(ii,ki))
                       call la_qscal(n,remax,vl(1,ki),1)
                    else
                       ! ------------------------------
                       ! version 2: back-transform block of vectors with gemm
                       ! zero out above vector
                       ! could go from ki-nv+1 to ki-1
                       do k = 1,ki - 1
                          work(k + iv*n) = zero
                       end do
                       iscomplex(iv) = ip
                       ! back-transform and normalization is done below
                    end if
                 else
                    ! --------------------------------------------------------
                    ! complex left eigenvector.
                    ! initial solve:
                    ! [ ( t(ki,ki)    t(ki,ki+1)  )**t - (wr - i* wi) ]*x = 0.
                    ! [ ( t(ki+1,ki) t(ki+1,ki+1) )                   ]
                    if (abs(t(ki,ki + 1)) >= abs(t(ki + 1,ki))) then
                       work(ki + (iv)*n) = wi/t(ki,ki + 1)
                       work(ki + 1 + (iv + 1)*n) = one
                    else
                       work(ki + (iv)*n) = one
                       work(ki + 1 + (iv + 1)*n) = -wi/t(ki + 1,ki)
                    end if
                    work(ki + 1 + (iv)*n) = zero
                    work(ki + (iv + 1)*n) = zero
                    ! form right-hand side.
                    do k = ki + 2,n
                       work(k + (iv)*n) = -work(ki + (iv)*n)*t(ki,k)
                       work(k + (iv + 1)*n) = -work(ki + 1 + (iv + 1)*n)*t(ki + 1,k)
                    end do
                    ! solve transposed quasi-triangular system:
                    ! [ t(ki+2:n,ki+2:n)**t - (wr-i*wi) ]*x = work1+i*work2
                    vmax = one
                    vcrit = bignum
                    jnxt = ki + 2
                    loop_200: do j = ki + 2,n
                       if (j < jnxt) cycle loop_200
                       j1 = j
                       j2 = j
                       jnxt = j + 1
                       if (j < n) then
                          if (t(j + 1,j) /= zero) then
                             j2 = j + 1
                             jnxt = j + 2
                          end if
                       end if
                       if (j1 == j2) then
                          ! 1-by-1 diagonal block
                          ! scale if necessary to avoid overflow when
                          ! forming the right-hand side elements.
                          if (work(j) > vcrit) then
                             rec = one/vmax
                             call la_qscal(n - ki + 1,rec,work(ki + (iv)*n),1)
                             call la_qscal(n - ki + 1,rec,work(ki + (iv + 1)*n),1)
                             vmax = one
                             vcrit = bignum
                          end if
                          work(j + (iv)*n) = work(j + (iv)*n) - la_qdot(j - ki - 2,t(ki + 2,j) &
                                    ,1,work(ki + 2 + (iv)*n),1)
                          work(j + (iv + 1)*n) = work(j + (iv + 1)*n) - la_qdot(j - ki - 2,t(ki + 2, &
                                    j),1,work(ki + 2 + (iv + 1)*n),1)
                          ! solve [ t(j,j)-(wr-i*wi) ]*(x11+i*x12)= wk+i*wk2
                          call la_qlaln2(.false.,1,2,smin,one,t(j,j),ldt,one,one, &
                                    work(j + iv*n),n,wr,-wi,x,2,scale,xnorm,ierr)
                          ! scale if necessary
                          if (scale /= one) then
                             call la_qscal(n - ki + 1,scale,work(ki + (iv)*n),1)
                             call la_qscal(n - ki + 1,scale,work(ki + (iv + 1)*n),1)
                          end if
                          work(j + (iv)*n) = x(1,1)
                          work(j + (iv + 1)*n) = x(1,2)
                          vmax = max(abs(work(j + (iv)*n)),abs(work(j + (iv + 1)*n)),vmax)

                          vcrit = bignum/vmax
                       else
                          ! 2-by-2 diagonal block
                          ! scale if necessary to avoid overflow when forming
                          ! the right-hand side elements.
                          beta = max(work(j),work(j + 1))
                          if (beta > vcrit) then
                             rec = one/vmax
                             call la_qscal(n - ki + 1,rec,work(ki + (iv)*n),1)
                             call la_qscal(n - ki + 1,rec,work(ki + (iv + 1)*n),1)
                             vmax = one
                             vcrit = bignum
                          end if
                          work(j + (iv)*n) = work(j + (iv)*n) - la_qdot(j - ki - 2,t(ki + 2, &
                                    j),1,work(ki + 2 + (iv)*n),1)
                          work(j + (iv + 1)*n) = work(j + (iv + 1)*n) - la_qdot(j - ki - 2,t(ki + 2, &
                                     j),1,work(ki + 2 + (iv + 1)*n),1)
                          work(j + 1 + (iv)*n) = work(j + 1 + (iv)*n) - la_qdot(j - ki - 2,t(ki + 2, &
                                     j + 1),1,work(ki + 2 + (iv)*n),1)
                          work(j + 1 + (iv + 1)*n) = work(j + 1 + (iv + 1)*n) - la_qdot(j - ki - 2,t(ki + &
                                    2,j + 1),1,work(ki + 2 + (iv + 1)*n),1)
                          ! solve 2-by-2 complex linear equation
                          ! [ (t(j,j)   t(j,j+1)  )**t - (wr-i*wi)*i ]*x = scale*b
                          ! [ (t(j+1,j) t(j+1,j+1))                  ]
                          call la_qlaln2(.true.,2,2,smin,one,t(j,j),ldt,one,one, &
                                    work(j + iv*n),n,wr,-wi,x,2,scale,xnorm,ierr)
                          ! scale if necessary
                          if (scale /= one) then
                             call la_qscal(n - ki + 1,scale,work(ki + (iv)*n),1)
                             call la_qscal(n - ki + 1,scale,work(ki + (iv + 1)*n),1)
                          end if
                          work(j + (iv)*n) = x(1,1)
                          work(j + (iv + 1)*n) = x(1,2)
                          work(j + 1 + (iv)*n) = x(2,1)
                          work(j + 1 + (iv + 1)*n) = x(2,2)
                          vmax = max(abs(x(1,1)),abs(x(1,2)),abs(x(2,1)),abs(x( &
                                     2,2)),vmax)
                          vcrit = bignum/vmax
                       end if
                    end do loop_200
                    ! copy the vector x or q*x to vl and normalize.
                    if (.not. over) then
                       ! ------------------------------
                       ! no back-transform: copy x to vl and normalize.
                       call la_qcopy(n - ki + 1,work(ki + (iv)*n),1,vl(ki,is),1)

                       call la_qcopy(n - ki + 1,work(ki + (iv + 1)*n),1,vl(ki,is + 1),1)

                       emax = zero
                       do k = ki,n
                          emax = max(emax,abs(vl(k,is)) + abs(vl(k,is + 1)))
                       end do
                       remax = one/emax
                       call la_qscal(n - ki + 1,remax,vl(ki,is),1)
                       call la_qscal(n - ki + 1,remax,vl(ki,is + 1),1)
                       do k = 1,ki - 1
                          vl(k,is) = zero
                          vl(k,is + 1) = zero
                       end do
                    else if (nb == 1) then
                       ! ------------------------------
                       ! version 1: back-transform each vector with gemv, q*x.
                       if (ki < n - 1) then
                          call la_qgemv('N',n,n - ki - 1,one,vl(1,ki + 2),ldvl,work(ki + 2 + &
                                    (iv)*n),1,work(ki + (iv)*n),vl(1,ki),1)
                          call la_qgemv('N',n,n - ki - 1,one,vl(1,ki + 2),ldvl,work(ki + 2 + &
                                    (iv + 1)*n),1,work(ki + 1 + (iv + 1)*n),vl(1,ki + 1),1)
                       else
                          call la_qscal(n,work(ki + (iv)*n),vl(1,ki),1)
                          call la_qscal(n,work(ki + 1 + (iv + 1)*n),vl(1,ki + 1),1)
                       end if
                       emax = zero
                       do k = 1,n
                          emax = max(emax,abs(vl(k,ki)) + abs(vl(k,ki + 1)))
                       end do
                       remax = one/emax
                       call la_qscal(n,remax,vl(1,ki),1)
                       call la_qscal(n,remax,vl(1,ki + 1),1)
                    else
                       ! ------------------------------
                       ! version 2: back-transform block of vectors with gemm
                       ! zero out above vector
                       ! could go from ki-nv+1 to ki-1
                       do k = 1,ki - 1
                          work(k + (iv)*n) = zero
                          work(k + (iv + 1)*n) = zero
                       end do
                       iscomplex(iv) = ip
                       iscomplex(iv + 1) = -ip
                       iv = iv + 1
                       ! back-transform and normalization is done below
                    end if
                 end if
                 if (nb > 1) then
                    ! --------------------------------------------------------
                    ! blocked version of back-transform
                    ! for complex case, ki2 includes both vectors (ki and ki+1)
                    if (ip == 0) then
                       ki2 = ki
                    else
                       ki2 = ki + 1
                    end if
                    ! columns 1:iv of work are valid vectors.
                    ! when the number of vectors stored reaches nb-1 or nb,
                    ! or if this was last vector, do the gemm
                    if ((iv >= nb - 1) .or. (ki2 == n)) then
                       call la_qgemm('N','N',n,iv,n - ki2 + iv,one,vl(1,ki2 - iv + 1),ldvl, &
                                 work(ki2 - iv + 1 + (1)*n),n,zero,work(1 + (nb + 1)*n),n)
                       ! normalize vectors
                       do k = 1,iv
                          if (iscomplex(k) == 0) then
                             ! real eigenvector
                             ii = la_iqamax(n,work(1 + (nb + k)*n),1)
                             remax = one/abs(work(ii + (nb + k)*n))
                          else if (iscomplex(k) == 1) then
                             ! first eigenvector of conjugate pair
                             emax = zero
                             do ii = 1,n
                                emax = max(emax,abs(work(ii + (nb + k)*n)) + abs(work(ii + ( &
                                          nb + k + 1)*n)))
                             end do
                             remax = one/emax
                          ! else if iscomplex(k)==-1
                             ! second eigenvector of conjugate pair
                             ! reuse same remax as previous k
                          end if
                          call la_qscal(n,remax,work(1 + (nb + k)*n),1)
                       end do
                       call la_qlacpy('F',n,iv,work(1 + (nb + 1)*n),n,vl(1,ki2 - iv + 1), &
                                 ldvl)
                       iv = 1
                    else
                       iv = iv + 1
                    end if
                 end if ! blocked back-transform
                 is = is + 1
                 if (ip /= 0) is = is + 1
              end do loop_260
           end if
           return
     end subroutine la_qtrevc3

     !> DTRSEN: reorders the real Schur factorization of a real matrix
     !> A = Q*T*Q**T, so that a selected cluster of eigenvalues appears in
     !> the leading diagonal blocks of the upper quasi-triangular matrix T,
     !> and the leading columns of Q form an orthonormal basis of the
     !> corresponding right invariant subspace.
     !> Optionally the routine computes the reciprocal condition numbers of
     !> the cluster of eigenvalues and/or the invariant subspace.
     !> T must be in Schur canonical form (as returned by DHSEQR), that is,
     !> block upper triangular with 1-by-1 and 2-by-2 diagonal blocks; each
     !> 2-by-2 diagonal block has its diagonal elements equal and its
     !> off-diagonal elements of opposite sign.

     subroutine la_qtrsen(job,compq,select,n,t,ldt,q,ldq,wr,wi,m,s,sep,work, &
               lwork,iwork,liwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: compq,job
           integer(ilp),intent(out) :: info,m
           integer(ilp),intent(in) :: ldq,ldt,liwork,lwork,n
           real(qp),intent(out) :: s,sep
           ! Array Arguments
           logical(lk),intent(in) :: select(*)
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(inout) :: q(ldq,*),t(ldt,*)
           real(qp),intent(out) :: wi(*),work(*),wr(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lquery,pair,swap,wantbh,wantq,wants,wantsp
           integer(ilp) :: ierr,k,kase,kk,ks,liwmin,lwmin,n1,n2,nn
           real(qp) :: est,rnorm,scale
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Executable Statements
           ! decode and test the input parameters
           wantbh = la_lsame(job,'B')
           wants = la_lsame(job,'E') .or. wantbh
           wantsp = la_lsame(job,'V') .or. wantbh
           wantq = la_lsame(compq,'V')
           info = 0
           lquery = (lwork == -1)
           if (.not. la_lsame(job,'N') .and. .not. wants .and. .not. wantsp) then
              info = -1
           else if (.not. la_lsame(compq,'N') .and. .not. wantq) then
              info = -2
           else if (n < 0) then
              info = -4
           else if (ldt < max(1,n)) then
              info = -6
           else if (ldq < 1 .or. (wantq .and. ldq < n)) then
              info = -8
           else
              ! set m to the dimension of the specified invariant subspace,
              ! and test lwork and liwork.
              m = 0
              pair = .false.
              do k = 1,n
                 if (pair) then
                    pair = .false.
                 else
                    if (k < n) then
                       if (t(k + 1,k) == zero) then
                          if (select(k)) m = m + 1
                       else
                          pair = .true.
                          if (select(k) .or. select(k + 1)) m = m + 2
                       end if
                    else
                       if (select(n)) m = m + 1
                    end if
                 end if
              end do
              n1 = m
              n2 = n - m
              nn = n1*n2
              if (wantsp) then
                 lwmin = max(1,2*nn)
                 liwmin = max(1,nn)
              else if (la_lsame(job,'N')) then
                 lwmin = max(1,n)
                 liwmin = 1
              else if (la_lsame(job,'E')) then
                 lwmin = max(1,nn)
                 liwmin = 1
              end if
              if (lwork < lwmin .and. .not. lquery) then
                 info = -15
              else if (liwork < liwmin .and. .not. lquery) then
                 info = -17
              end if
           end if
           if (info == 0) then
              work(1) = lwmin
              iwork(1) = liwmin
           end if
           if (info /= 0) then
              call la_xerbla('DTRSEN',-info)
              return
           else if (lquery) then
              return
           end if
           ! quick return if possible.
           if (m == n .or. m == 0) then
              if (wants) s = one
              if (wantsp) sep = la_qlange('1',n,n,t,ldt,work)
              go to 40
           end if
           ! collect the selected blocks at the top-left corner of t.
           ks = 0
           pair = .false.
           loop_20: do k = 1,n
              if (pair) then
                 pair = .false.
              else
                 swap = select(k)
                 if (k < n) then
                    if (t(k + 1,k) /= zero) then
                       pair = .true.
                       swap = swap .or. select(k + 1)
                    end if
                 end if
                 if (swap) then
                    ks = ks + 1
                    ! swap the k-th block to position ks.
                    ierr = 0
                    kk = k
                    if (k /= ks) call la_qtrexc(compq,n,t,ldt,q,ldq,kk,ks,work,ierr)

                    if (ierr == 1 .or. ierr == 2) then
                       ! blocks too close to swap: exit.
                       info = 1
                       if (wants) s = zero
                       if (wantsp) sep = zero
                       go to 40
                    end if
                    if (pair) ks = ks + 1
                 end if
              end if
           end do loop_20
           if (wants) then
              ! solve sylvester equation for r:
                 ! t11*r - r*t22 = scale*t12
              call la_qlacpy('F',n1,n2,t(1,n1 + 1),ldt,work,n1)
              call la_qtrsyl('N','N',-1,n1,n2,t,ldt,t(n1 + 1,n1 + 1),ldt,work,n1, &
                        scale,ierr)
              ! estimate the reciprocal of the condition number of the cluster
              ! of eigenvalues.
              rnorm = la_qlange('F',n1,n2,work,n1,work)
              if (rnorm == zero) then
                 s = one
              else
                 s = scale/(sqrt(scale*scale/rnorm + rnorm)*sqrt(rnorm))
              end if
           end if
           if (wantsp) then
              ! estimate sep(t11,t22).
              est = zero
              kase = 0
              30 continue
              call la_qlacn2(nn,work(nn + 1),work,iwork,est,kase,isave)
              if (kase /= 0) then
                 if (kase == 1) then
                    ! solve  t11*r - r*t22 = scale*x.
                    call la_qtrsyl('N','N',-1,n1,n2,t,ldt,t(n1 + 1,n1 + 1),ldt,work, &
                              n1,scale,ierr)
                 else
                    ! solve t11**t*r - r*t22**t = scale*x.
                    call la_qtrsyl('T','T',-1,n1,n2,t,ldt,t(n1 + 1,n1 + 1),ldt,work, &
                              n1,scale,ierr)
                 end if
                 go to 30
              end if
              sep = scale/est
           end if
           40 continue
           ! store the output eigenvalues in wr and wi.
           do k = 1,n
              wr(k) = t(k,k)
              wi(k) = zero
           end do
           do k = 1,n - 1
              if (t(k + 1,k) /= zero) then
                 wi(k) = sqrt(abs(t(k,k + 1)))*sqrt(abs(t(k + 1,k)))
                 wi(k + 1) = -wi(k)
              end if
           end do
           work(1) = lwmin
           iwork(1) = liwmin
           return
     end subroutine la_qtrsen

     !> DTRSNA: estimates reciprocal condition numbers for specified
     !> eigenvalues and/or right eigenvectors of a real upper
     !> quasi-triangular matrix T (or of any matrix Q*T*Q**T with Q
     !> orthogonal).
     !> T must be in Schur canonical form (as returned by DHSEQR), that is,
     !> block upper triangular with 1-by-1 and 2-by-2 diagonal blocks; each
     !> 2-by-2 diagonal block has its diagonal elements equal and its
     !> off-diagonal elements of opposite sign.

     subroutine la_qtrsna(job,howmny,select,n,t,ldt,vl,ldvl,vr,ldvr,s,sep,mm,m, &
               work,ldwork,iwork,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: howmny,job
           integer(ilp),intent(out) :: info,m
           integer(ilp),intent(in) :: ldt,ldvl,ldvr,ldwork,mm,n
           ! Array Arguments
           logical(lk),intent(in) :: select(*)
           integer(ilp),intent(out) :: iwork(*)
           real(qp),intent(out) :: s(*),sep(*),work(ldwork,*)
           real(qp),intent(in) :: t(ldt,*),vl(ldvl,*),vr(ldvr,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: pair,somcon,wantbh,wants,wantsp
           integer(ilp) :: i,ierr,ifst,ilst,j,k,kase,ks,n2,nn
           real(qp) :: bignum,cond,cs,delta,dumm,eps,est,lnrm,mu,prod,prod1,prod2, &
                     rnrm,scale,smlnum,sn
           ! Local Arrays
           integer(ilp) :: isave(3)
           real(qp) :: dummy(1)
           ! Intrinsic Functions
           intrinsic :: abs,max,sqrt
           ! Executable Statements
           ! decode and test the input parameters
           wantbh = la_lsame(job,'B')
           wants = la_lsame(job,'E') .or. wantbh
           wantsp = la_lsame(job,'V') .or. wantbh
           somcon = la_lsame(howmny,'S')
           info = 0
           if (.not. wants .and. .not. wantsp) then
              info = -1
           else if (.not. la_lsame(howmny,'A') .and. .not. somcon) then
              info = -2
           else if (n < 0) then
              info = -4
           else if (ldt < max(1,n)) then
              info = -6
           else if (ldvl < 1 .or. (wants .and. ldvl < n)) then
              info = -8
           else if (ldvr < 1 .or. (wants .and. ldvr < n)) then
              info = -10
           else
              ! set m to the number of eigenpairs for which condition numbers
              ! are required, and test mm.
              if (somcon) then
                 m = 0
                 pair = .false.
                 do k = 1,n
                    if (pair) then
                       pair = .false.
                    else
                       if (k < n) then
                          if (t(k + 1,k) == zero) then
                             if (select(k)) m = m + 1
                          else
                             pair = .true.
                             if (select(k) .or. select(k + 1)) m = m + 2
                          end if
                       else
                          if (select(n)) m = m + 1
                       end if
                    end if
                 end do
              else
                 m = n
              end if
              if (mm < m) then
                 info = -13
              else if (ldwork < 1 .or. (wantsp .and. ldwork < n)) then
                 info = -16
              end if
           end if
           if (info /= 0) then
              call la_xerbla('DTRSNA',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (n == 1) then
              if (somcon) then
                 if (.not. select(1)) return
              end if
              if (wants) s(1) = one
              if (wantsp) sep(1) = abs(t(1,1))
              return
           end if
           ! get machine constants
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')/eps
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           ks = 0
           pair = .false.
           loop_60: do k = 1,n
              ! determine whether t(k,k) begins a 1-by-1 or 2-by-2 block.
              if (pair) then
                 pair = .false.
                 cycle loop_60
              else
                 if (k < n) pair = t(k + 1,k) /= zero
              end if
              ! determine whether condition numbers are required for the k-th
              ! eigenpair.
              if (somcon) then
                 if (pair) then
                    if (.not. select(k) .and. .not. select(k + 1)) cycle loop_60
                 else
                    if (.not. select(k)) cycle loop_60
                 end if
              end if
              ks = ks + 1
              if (wants) then
                 ! compute the reciprocal condition number of the k-th
                 ! eigenvalue.
                 if (.not. pair) then
                    ! real eigenvalue.
                    prod = la_qdot(n,vr(1,ks),1,vl(1,ks),1)
                    rnrm = la_qnrm2(n,vr(1,ks),1)
                    lnrm = la_qnrm2(n,vl(1,ks),1)
                    s(ks) = abs(prod)/(rnrm*lnrm)
                 else
                    ! complex eigenvalue.
                    prod1 = la_qdot(n,vr(1,ks),1,vl(1,ks),1)
                    prod1 = prod1 + la_qdot(n,vr(1,ks + 1),1,vl(1,ks + 1),1)
                    prod2 = la_qdot(n,vl(1,ks),1,vr(1,ks + 1),1)
                    prod2 = prod2 - la_qdot(n,vl(1,ks + 1),1,vr(1,ks),1)
                    rnrm = la_qlapy2(la_qnrm2(n,vr(1,ks),1),la_qnrm2(n,vr( &
                              1,ks + 1),1))
                    lnrm = la_qlapy2(la_qnrm2(n,vl(1,ks),1),la_qnrm2(n,vl( &
                              1,ks + 1),1))
                    cond = la_qlapy2(prod1,prod2)/(rnrm*lnrm)
                    s(ks) = cond
                    s(ks + 1) = cond
                 end if
              end if
              if (wantsp) then
                 ! estimate the reciprocal condition number of the k-th
                 ! eigenvector.
                 ! copy the matrix t to the array work and swap the diagonal
                 ! block beginning at t(k,k) to the (1,1) position.
                 call la_qlacpy('FULL',n,n,t,ldt,work,ldwork)
                 ifst = k
                 ilst = 1
                 call la_qtrexc('NO Q',n,work,ldwork,dummy,1,ifst,ilst,work(1,n + 1), &
                            ierr)
                 if (ierr == 1 .or. ierr == 2) then
                    ! could not swap because blocks not well separated
                    scale = one
                    est = bignum
                 else
                    ! reordering successful
                    if (work(2,1) == zero) then
                       ! form c = t22 - lambda*i in work(2:n,2:n).
                       do i = 2,n
                          work(i,i) = work(i,i) - work(1,1)
                       end do
                       n2 = 1
                       nn = n - 1
                    else
                       ! triangularize the 2 by 2 block by unitary
                       ! transformation u = [  cs   i*ss ]
                                          ! [ i*ss   cs  ].
                       ! such that the (1,1) position of work is complex
                       ! eigenvalue lambda with positive imaginary part. (2,2)
                       ! position of work is the complex eigenvalue lambda
                       ! with negative imaginary  part.
                       mu = sqrt(abs(work(1,2)))*sqrt(abs(work(2,1)))
                       delta = la_qlapy2(mu,work(2,1))
                       cs = mu/delta
                       sn = -work(2,1)/delta
                       ! form
                       ! c**t = work(2:n,2:n) + i*[rwork(1) ..... rwork(n-1) ]
                                                ! [   mu                     ]
                                                ! [         ..               ]
                                                ! [             ..           ]
                                                ! [                  mu      ]
                       ! where c**t is transpose of matrix c,
                       ! and rwork is stored starting in the n+1-st column of
                       ! work.
                       do j = 3,n
                          work(2,j) = cs*work(2,j)
                          work(j,j) = work(j,j) - work(1,1)
                       end do
                       work(2,2) = zero
                       work(1,n + 1) = two*mu
                       do i = 2,n - 1
                          work(i,n + 1) = sn*work(1,i + 1)
                       end do
                       n2 = 2
                       nn = 2*(n - 1)
                    end if
                    ! estimate norm(inv(c**t))
                    est = zero
                    kase = 0
                    50 continue
                    call la_qlacn2(nn,work(1,n + 2),work(1,n + 4),iwork,est,kase, &
                              isave)
                    if (kase /= 0) then
                       if (kase == 1) then
                          if (n2 == 1) then
                             ! real eigenvalue: solve c**t*x = scale*c.
                             call la_qlaqtr(.true.,.true.,n - 1,work(2,2),ldwork,dummy, &
                                       dumm,scale,work(1,n + 4),work(1,n + 6),ierr)
                          else
                             ! complex eigenvalue: solve
                             ! c**t*(p+iq) = scale*(c+id) in real arithmetic.
                             call la_qlaqtr(.true.,.false.,n - 1,work(2,2),ldwork,work( &
                                       1,n + 1),mu,scale,work(1,n + 4),work(1,n + 6),ierr)
                          end if
                       else
                          if (n2 == 1) then
                             ! real eigenvalue: solve c*x = scale*c.
                             call la_qlaqtr(.false.,.true.,n - 1,work(2,2),ldwork,dummy, &
                                        dumm,scale,work(1,n + 4),work(1,n + 6),ierr)
                          else
                             ! complex eigenvalue: solve
                             ! c*(p+iq) = scale*(c+id) in real arithmetic.
                             call la_qlaqtr(.false.,.false.,n - 1,work(2,2),ldwork,work( &
                                       1,n + 1),mu,scale,work(1,n + 4),work(1,n + 6),ierr)
                          end if
                       end if
                       go to 50
                    end if
                 end if
                 sep(ks) = scale/max(est,smlnum)
                 if (pair) sep(ks + 1) = sep(ks)
              end if
              if (pair) ks = ks + 1
           end do loop_60
           return
     end subroutine la_qtrsna

     !> DTRSYL: solves the real Sylvester matrix equation:
     !> op(A)*X + X*op(B) = scale*C or
     !> op(A)*X - X*op(B) = scale*C,
     !> where op(A) = A or A**T, and  A and B are both upper quasi-
     !> triangular. A is M-by-M and B is N-by-N; the right hand side C and
     !> the solution X are M-by-N; and scale is an output scale factor, set
     !> <= 1 to avoid overflow in X.
     !> A and B must be in Schur canonical form (as returned by DHSEQR), that
     !> is, block upper triangular with 1-by-1 and 2-by-2 diagonal blocks;
     !> each 2-by-2 diagonal block has its diagonal elements equal and its
     !> off-diagonal elements of opposite sign.

     subroutine la_qtrsyl(trana,tranb,isgn,m,n,a,lda,b,ldb,c,ldc,scale,info)

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: trana,tranb
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: isgn,lda,ldb,ldc,m,n
           real(qp),intent(out) :: scale
           ! Array Arguments
           real(qp),intent(in) :: a(lda,*),b(ldb,*)
           real(qp),intent(inout) :: c(ldc,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: notrna,notrnb
           integer(ilp) :: ierr,j,k,k1,k2,knext,l,l1,l2,lnext
           real(qp) :: a11,bignum,da11,db,eps,scaloc,sgn,smin,smlnum,suml,sumr, &
                     xnorm
           ! Local Arrays
           real(qp) :: dum(1),vec(2,2),x(2,2)
           ! Intrinsic Functions
           intrinsic :: abs,real,max,min
           ! Executable Statements
           ! decode and test input parameters
           notrna = la_lsame(trana,'N')
           notrnb = la_lsame(tranb,'N')
           info = 0
           if (.not. notrna .and. .not. la_lsame(trana,'T') .and. .not. la_lsame(trana, &
                     'C')) then
              info = -1
           else if (.not. notrnb .and. .not. la_lsame(tranb,'T') .and. .not. la_lsame( &
                     tranb,'C')) then
              info = -2
           else if (isgn /= 1 .and. isgn /= -1) then
              info = -3
           else if (m < 0) then
              info = -4
           else if (n < 0) then
              info = -5
           else if (lda < max(1,m)) then
              info = -7
           else if (ldb < max(1,n)) then
              info = -9
           else if (ldc < max(1,m)) then
              info = -11
           end if
           if (info /= 0) then
              call la_xerbla('DTRSYL',-info)
              return
           end if
           ! quick return if possible
           scale = one
           if (m == 0 .or. n == 0) return
           ! set constants to control overflow
           eps = la_qlamch('P')
           smlnum = la_qlamch('S')
           bignum = one/smlnum
           call la_qlabad(smlnum,bignum)
           smlnum = smlnum*real(m*n,KIND=qp)/eps
           bignum = one/smlnum
           smin = max(smlnum,eps*la_qlange('M',m,m,a,lda,dum),eps*la_qlange('M', &
                      n,n,b,ldb,dum))
           sgn = isgn
           if (notrna .and. notrnb) then
              ! solve    a*x + isgn*x*b = scale*c.
              ! the (k,l)th block of x is determined starting from
              ! bottom-left corner column by column by
               ! a(k,k)*x(k,l) + isgn*x(k,l)*b(l,l) = c(k,l) - r(k,l)
              ! where
                        ! m                         l-1
              ! r(k,l) = sum [a(k,i)*x(i,l)] + isgn*sum [x(k,j)*b(j,l)].
                      ! i=k+1                       j=1
              ! start column loop (index = l)
              ! l1 (l2) : column index of the first (first) row of x(k,l).
              lnext = 1
              loop_60: do l = 1,n
                 if (l < lnext) cycle loop_60
                 if (l == n) then
                    l1 = l
                    l2 = l
                 else
                    if (b(l + 1,l) /= zero) then
                       l1 = l
                       l2 = l + 1
                       lnext = l + 2
                    else
                       l1 = l
                       l2 = l
                       lnext = l + 1
                    end if
                 end if
                 ! start row loop (index = k)
                 ! k1 (k2): row index of the first (last) row of x(k,l).
                 knext = m
                 loop_50: do k = m,1,-1
                    if (k > knext) cycle loop_50
                    if (k == 1) then
                       k1 = k
                       k2 = k
                    else
                       if (a(k,k - 1) /= zero) then
                          k1 = k - 1
                          k2 = k
                          knext = k - 2
                       else
                          k1 = k
                          k2 = k
                          knext = k - 1
                       end if
                    end if
                    if (l1 == l2 .and. k1 == k2) then
                       suml = la_qdot(m - k1,a(k1,min(k1 + 1,m)),lda,c(min(k1 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l1),1)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       scaloc = one
                       a11 = a(k1,k1) + sgn*b(l1,l1)
                       da11 = abs(a11)
                       if (da11 <= smin) then
                          a11 = smin
                          da11 = smin
                          info = 1
                       end if
                       db = abs(vec(1,1))
                       if (da11 < one .and. db > one) then
                          if (db > bignum*da11) scaloc = one/db
                       end if
                       x(1,1) = (vec(1,1)*scaloc)/a11
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                    else if (l1 == l2 .and. k1 /= k2) then
                       suml = la_qdot(m - k2,a(k1,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l1),1)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       suml = la_qdot(m - k2,a(k2,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(l1 - 1,c(k2,1),ldc,b(1,l1),1)
                       vec(2,1) = c(k2,l1) - (suml + sgn*sumr)
                       call la_qlaln2(.false.,2,1,smin,one,a(k1,k1),lda,one,one, &
                                 vec,2,-sgn*b(l1,l1),zero,x,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k2,l1) = x(2,1)
                    else if (l1 /= l2 .and. k1 == k2) then
                       suml = la_qdot(m - k1,a(k1,min(k1 + 1,m)),lda,c(min(k1 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l1),1)
                       vec(1,1) = sgn*(c(k1,l1) - (suml + sgn*sumr))
                       suml = la_qdot(m - k1,a(k1,min(k1 + 1,m)),lda,c(min(k1 + 1,m), &
                                 l2),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l2),1)
                       vec(2,1) = sgn*(c(k1,l2) - (suml + sgn*sumr))
                       call la_qlaln2(.true.,2,1,smin,one,b(l1,l1),ldb,one,one, &
                                 vec,2,-sgn*a(k1,k1),zero,x,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k1,l2) = x(2,1)
                    else if (l1 /= l2 .and. k1 /= k2) then
                       suml = la_qdot(m - k2,a(k1,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l1),1)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       suml = la_qdot(m - k2,a(k1,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l2),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l2),1)
                       vec(1,2) = c(k1,l2) - (suml + sgn*sumr)
                       suml = la_qdot(m - k2,a(k2,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(l1 - 1,c(k2,1),ldc,b(1,l1),1)
                       vec(2,1) = c(k2,l1) - (suml + sgn*sumr)
                       suml = la_qdot(m - k2,a(k2,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l2),1)
                       sumr = la_qdot(l1 - 1,c(k2,1),ldc,b(1,l2),1)
                       vec(2,2) = c(k2,l2) - (suml + sgn*sumr)
                       call la_qlasy2(.false.,.false.,isgn,2,2,a(k1,k1),lda,b(l1, &
                                 l1),ldb,vec,2,scaloc,x,2,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k1,l2) = x(1,2)
                       c(k2,l1) = x(2,1)
                       c(k2,l2) = x(2,2)
                    end if
                 end do loop_50
              end do loop_60
           else if (.not. notrna .and. notrnb) then
              ! solve    a**t *x + isgn*x*b = scale*c.
              ! the (k,l)th block of x is determined starting from
              ! upper-left corner column by column by
                ! a(k,k)**t*x(k,l) + isgn*x(k,l)*b(l,l) = c(k,l) - r(k,l)
              ! where
                         ! k-1        t                    l-1
                ! r(k,l) = sum [a(i,k)**t*x(i,l)] +isgn*sum [x(k,j)*b(j,l)]
                         ! i=1                          j=1
              ! start column loop (index = l)
              ! l1 (l2): column index of the first (last) row of x(k,l)
              lnext = 1
              loop_120: do l = 1,n
                 if (l < lnext) cycle loop_120
                 if (l == n) then
                    l1 = l
                    l2 = l
                 else
                    if (b(l + 1,l) /= zero) then
                       l1 = l
                       l2 = l + 1
                       lnext = l + 2
                    else
                       l1 = l
                       l2 = l
                       lnext = l + 1
                    end if
                 end if
                 ! start row loop (index = k)
                 ! k1 (k2): row index of the first (last) row of x(k,l)
                 knext = 1
                 loop_110: do k = 1,m
                    if (k < knext) cycle loop_110
                    if (k == m) then
                       k1 = k
                       k2 = k
                    else
                       if (a(k + 1,k) /= zero) then
                          k1 = k
                          k2 = k + 1
                          knext = k + 2
                       else
                          k1 = k
                          k2 = k
                          knext = k + 1
                       end if
                    end if
                    if (l1 == l2 .and. k1 == k2) then
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l1),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l1),1)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       scaloc = one
                       a11 = a(k1,k1) + sgn*b(l1,l1)
                       da11 = abs(a11)
                       if (da11 <= smin) then
                          a11 = smin
                          da11 = smin
                          info = 1
                       end if
                       db = abs(vec(1,1))
                       if (da11 < one .and. db > one) then
                          if (db > bignum*da11) scaloc = one/db
                       end if
                       x(1,1) = (vec(1,1)*scaloc)/a11
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                    else if (l1 == l2 .and. k1 /= k2) then
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l1),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l1),1)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       suml = la_qdot(k1 - 1,a(1,k2),1,c(1,l1),1)
                       sumr = la_qdot(l1 - 1,c(k2,1),ldc,b(1,l1),1)
                       vec(2,1) = c(k2,l1) - (suml + sgn*sumr)
                       call la_qlaln2(.true.,2,1,smin,one,a(k1,k1),lda,one,one, &
                                 vec,2,-sgn*b(l1,l1),zero,x,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k2,l1) = x(2,1)
                    else if (l1 /= l2 .and. k1 == k2) then
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l1),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l1),1)
                       vec(1,1) = sgn*(c(k1,l1) - (suml + sgn*sumr))
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l2),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l2),1)
                       vec(2,1) = sgn*(c(k1,l2) - (suml + sgn*sumr))
                       call la_qlaln2(.true.,2,1,smin,one,b(l1,l1),ldb,one,one, &
                                 vec,2,-sgn*a(k1,k1),zero,x,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k1,l2) = x(2,1)
                    else if (l1 /= l2 .and. k1 /= k2) then
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l1),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l1),1)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l2),1)
                       sumr = la_qdot(l1 - 1,c(k1,1),ldc,b(1,l2),1)
                       vec(1,2) = c(k1,l2) - (suml + sgn*sumr)
                       suml = la_qdot(k1 - 1,a(1,k2),1,c(1,l1),1)
                       sumr = la_qdot(l1 - 1,c(k2,1),ldc,b(1,l1),1)
                       vec(2,1) = c(k2,l1) - (suml + sgn*sumr)
                       suml = la_qdot(k1 - 1,a(1,k2),1,c(1,l2),1)
                       sumr = la_qdot(l1 - 1,c(k2,1),ldc,b(1,l2),1)
                       vec(2,2) = c(k2,l2) - (suml + sgn*sumr)
                       call la_qlasy2(.true.,.false.,isgn,2,2,a(k1,k1),lda,b(l1, &
                                 l1),ldb,vec,2,scaloc,x,2,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k1,l2) = x(1,2)
                       c(k2,l1) = x(2,1)
                       c(k2,l2) = x(2,2)
                    end if
                 end do loop_110
              end do loop_120
           else if (.not. notrna .and. .not. notrnb) then
              ! solve    a**t*x + isgn*x*b**t = scale*c.
              ! the (k,l)th block of x is determined starting from
              ! top-right corner column by column by
                 ! a(k,k)**t*x(k,l) + isgn*x(k,l)*b(l,l)**t = c(k,l) - r(k,l)
              ! where
                           ! k-1                            n
                  ! r(k,l) = sum [a(i,k)**t*x(i,l)] + isgn*sum [x(k,j)*b(l,j)**t].
                           ! i=1                          j=l+1
              ! start column loop (index = l)
              ! l1 (l2): column index of the first (last) row of x(k,l)
              lnext = n
              loop_180: do l = n,1,-1
                 if (l > lnext) cycle loop_180
                 if (l == 1) then
                    l1 = l
                    l2 = l
                 else
                    if (b(l,l - 1) /= zero) then
                       l1 = l - 1
                       l2 = l
                       lnext = l - 2
                    else
                       l1 = l
                       l2 = l
                       lnext = l - 1
                    end if
                 end if
                 ! start row loop (index = k)
                 ! k1 (k2): row index of the first (last) row of x(k,l)
                 knext = 1
                 loop_170: do k = 1,m
                    if (k < knext) cycle loop_170
                    if (k == m) then
                       k1 = k
                       k2 = k
                    else
                       if (a(k + 1,k) /= zero) then
                          k1 = k
                          k2 = k + 1
                          knext = k + 2
                       else
                          k1 = k
                          k2 = k
                          knext = k + 1
                       end if
                    end if
                    if (l1 == l2 .and. k1 == k2) then
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l1),1)
                       sumr = la_qdot(n - l1,c(k1,min(l1 + 1,n)),ldc,b(l1,min(l1 + 1,n &
                                 )),ldb)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       scaloc = one
                       a11 = a(k1,k1) + sgn*b(l1,l1)
                       da11 = abs(a11)
                       if (da11 <= smin) then
                          a11 = smin
                          da11 = smin
                          info = 1
                       end if
                       db = abs(vec(1,1))
                       if (da11 < one .and. db > one) then
                          if (db > bignum*da11) scaloc = one/db
                       end if
                       x(1,1) = (vec(1,1)*scaloc)/a11
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                    else if (l1 == l2 .and. k1 /= k2) then
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l1),1)
                       sumr = la_qdot(n - l2,c(k1,min(l2 + 1,n)),ldc,b(l1,min(l2 + 1,n &
                                 )),ldb)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       suml = la_qdot(k1 - 1,a(1,k2),1,c(1,l1),1)
                       sumr = la_qdot(n - l2,c(k2,min(l2 + 1,n)),ldc,b(l1,min(l2 + 1,n &
                                 )),ldb)
                       vec(2,1) = c(k2,l1) - (suml + sgn*sumr)
                       call la_qlaln2(.true.,2,1,smin,one,a(k1,k1),lda,one,one, &
                                 vec,2,-sgn*b(l1,l1),zero,x,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k2,l1) = x(2,1)
                    else if (l1 /= l2 .and. k1 == k2) then
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l1),1)
                       sumr = la_qdot(n - l2,c(k1,min(l2 + 1,n)),ldc,b(l1,min(l2 + 1,n &
                                 )),ldb)
                       vec(1,1) = sgn*(c(k1,l1) - (suml + sgn*sumr))
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l2),1)
                       sumr = la_qdot(n - l2,c(k1,min(l2 + 1,n)),ldc,b(l2,min(l2 + 1,n &
                                 )),ldb)
                       vec(2,1) = sgn*(c(k1,l2) - (suml + sgn*sumr))
                       call la_qlaln2(.false.,2,1,smin,one,b(l1,l1),ldb,one,one, &
                                 vec,2,-sgn*a(k1,k1),zero,x,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k1,l2) = x(2,1)
                    else if (l1 /= l2 .and. k1 /= k2) then
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l1),1)
                       sumr = la_qdot(n - l2,c(k1,min(l2 + 1,n)),ldc,b(l1,min(l2 + 1,n &
                                 )),ldb)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       suml = la_qdot(k1 - 1,a(1,k1),1,c(1,l2),1)
                       sumr = la_qdot(n - l2,c(k1,min(l2 + 1,n)),ldc,b(l2,min(l2 + 1,n &
                                 )),ldb)
                       vec(1,2) = c(k1,l2) - (suml + sgn*sumr)
                       suml = la_qdot(k1 - 1,a(1,k2),1,c(1,l1),1)
                       sumr = la_qdot(n - l2,c(k2,min(l2 + 1,n)),ldc,b(l1,min(l2 + 1,n &
                                 )),ldb)
                       vec(2,1) = c(k2,l1) - (suml + sgn*sumr)
                       suml = la_qdot(k1 - 1,a(1,k2),1,c(1,l2),1)
                       sumr = la_qdot(n - l2,c(k2,min(l2 + 1,n)),ldc,b(l2,min(l2 + 1,n &
                                 )),ldb)
                       vec(2,2) = c(k2,l2) - (suml + sgn*sumr)
                       call la_qlasy2(.true.,.true.,isgn,2,2,a(k1,k1),lda,b(l1,l1 &
                                 ),ldb,vec,2,scaloc,x,2,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k1,l2) = x(1,2)
                       c(k2,l1) = x(2,1)
                       c(k2,l2) = x(2,2)
                    end if
                 end do loop_170
              end do loop_180
           else if (notrna .and. .not. notrnb) then
              ! solve    a*x + isgn*x*b**t = scale*c.
              ! the (k,l)th block of x is determined starting from
              ! bottom-right corner column by column by
                  ! a(k,k)*x(k,l) + isgn*x(k,l)*b(l,l)**t = c(k,l) - r(k,l)
              ! where
                            ! m                          n
                  ! r(k,l) = sum [a(k,i)*x(i,l)] + isgn*sum [x(k,j)*b(l,j)**t].
                          ! i=k+1                      j=l+1
              ! start column loop (index = l)
              ! l1 (l2): column index of the first (last) row of x(k,l)
              lnext = n
              loop_240: do l = n,1,-1
                 if (l > lnext) cycle loop_240
                 if (l == 1) then
                    l1 = l
                    l2 = l
                 else
                    if (b(l,l - 1) /= zero) then
                       l1 = l - 1
                       l2 = l
                       lnext = l - 2
                    else
                       l1 = l
                       l2 = l
                       lnext = l - 1
                    end if
                 end if
                 ! start row loop (index = k)
                 ! k1 (k2): row index of the first (last) row of x(k,l)
                 knext = m
                 loop_230: do k = m,1,-1
                    if (k > knext) cycle loop_230
                    if (k == 1) then
                       k1 = k
                       k2 = k
                    else
                       if (a(k,k - 1) /= zero) then
                          k1 = k - 1
                          k2 = k
                          knext = k - 2
                       else
                          k1 = k
                          k2 = k
                          knext = k - 1
                       end if
                    end if
                    if (l1 == l2 .and. k1 == k2) then
                       suml = la_qdot(m - k1,a(k1,min(k1 + 1,m)),lda,c(min(k1 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(n - l1,c(k1,min(l1 + 1,n)),ldc,b(l1,min(l1 + 1,n &
                                 )),ldb)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       scaloc = one
                       a11 = a(k1,k1) + sgn*b(l1,l1)
                       da11 = abs(a11)
                       if (da11 <= smin) then
                          a11 = smin
                          da11 = smin
                          info = 1
                       end if
                       db = abs(vec(1,1))
                       if (da11 < one .and. db > one) then
                          if (db > bignum*da11) scaloc = one/db
                       end if
                       x(1,1) = (vec(1,1)*scaloc)/a11
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                    else if (l1 == l2 .and. k1 /= k2) then
                       suml = la_qdot(m - k2,a(k1,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(n - l2,c(k1,min(l2 + 1,n)),ldc,b(l1,min(l2 + 1,n &
                                 )),ldb)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       suml = la_qdot(m - k2,a(k2,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(n - l2,c(k2,min(l2 + 1,n)),ldc,b(l1,min(l2 + 1,n &
                                 )),ldb)
                       vec(2,1) = c(k2,l1) - (suml + sgn*sumr)
                       call la_qlaln2(.false.,2,1,smin,one,a(k1,k1),lda,one,one, &
                                 vec,2,-sgn*b(l1,l1),zero,x,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k2,l1) = x(2,1)
                    else if (l1 /= l2 .and. k1 == k2) then
                       suml = la_qdot(m - k1,a(k1,min(k1 + 1,m)),lda,c(min(k1 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(n - l2,c(k1,min(l2 + 1,n)),ldc,b(l1,min(l2 + 1,n &
                                 )),ldb)
                       vec(1,1) = sgn*(c(k1,l1) - (suml + sgn*sumr))
                       suml = la_qdot(m - k1,a(k1,min(k1 + 1,m)),lda,c(min(k1 + 1,m), &
                                 l2),1)
                       sumr = la_qdot(n - l2,c(k1,min(l2 + 1,n)),ldc,b(l2,min(l2 + 1,n &
                                 )),ldb)
                       vec(2,1) = sgn*(c(k1,l2) - (suml + sgn*sumr))
                       call la_qlaln2(.false.,2,1,smin,one,b(l1,l1),ldb,one,one, &
                                 vec,2,-sgn*a(k1,k1),zero,x,2,scaloc,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k1,l2) = x(2,1)
                    else if (l1 /= l2 .and. k1 /= k2) then
                       suml = la_qdot(m - k2,a(k1,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(n - l2,c(k1,min(l2 + 1,n)),ldc,b(l1,min(l2 + 1,n &
                                 )),ldb)
                       vec(1,1) = c(k1,l1) - (suml + sgn*sumr)
                       suml = la_qdot(m - k2,a(k1,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l2),1)
                       sumr = la_qdot(n - l2,c(k1,min(l2 + 1,n)),ldc,b(l2,min(l2 + 1,n &
                                 )),ldb)
                       vec(1,2) = c(k1,l2) - (suml + sgn*sumr)
                       suml = la_qdot(m - k2,a(k2,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l1),1)
                       sumr = la_qdot(n - l2,c(k2,min(l2 + 1,n)),ldc,b(l1,min(l2 + 1,n &
                                 )),ldb)
                       vec(2,1) = c(k2,l1) - (suml + sgn*sumr)
                       suml = la_qdot(m - k2,a(k2,min(k2 + 1,m)),lda,c(min(k2 + 1,m), &
                                 l2),1)
                       sumr = la_qdot(n - l2,c(k2,min(l2 + 1,n)),ldc,b(l2,min(l2 + 1,n &
                                 )),ldb)
                       vec(2,2) = c(k2,l2) - (suml + sgn*sumr)
                       call la_qlasy2(.false.,.true.,isgn,2,2,a(k1,k1),lda,b(l1, &
                                 l1),ldb,vec,2,scaloc,x,2,xnorm,ierr)
                       if (ierr /= 0) info = 1
                       if (scaloc /= one) then
                          do j = 1,n
                             call la_qscal(m,scaloc,c(1,j),1)
                          end do
                          scale = scale*scaloc
                       end if
                       c(k1,l1) = x(1,1)
                       c(k1,l2) = x(1,2)
                       c(k2,l1) = x(2,1)
                       c(k2,l2) = x(2,2)
                    end if
                 end do loop_230
              end do loop_240
           end if
           return
     end subroutine la_qtrsyl

end module la_lapack_q
